/* DSE Writing Part B: imported from supplied PDFs. */
window.EDMUND_DSE_WRITING_PART_B_2021_SEED = {"dse/writing/part-b/2021/Q2":[{"front":"going green","meaning":"實踐環保","examples":[{"en":"Electric cars will sell only when going green is made easy.","zh":"只有當實踐環保變得容易時，電動車才會暢銷。"},{"en":"Going green means choosing actions that reduce harm to the environment.","zh":"實踐環保是指選擇能減少對環境傷害的行動。"},{"en":"A family can start going green by using less plastic and saving electricity at home.","zh":"一個家庭可以從少用塑膠和在家節省用電開始實踐環保。"},{"en":"Going green can lower pollution when many people use public transport instead of private cars.","zh":"當很多人使用公共交通而不是私家車時，實踐環保可以減少污染。"},{"en":"Going green is easier when the cleaner choice is also affordable and convenient.","zh":"當較環保的選擇同時負擔得起又方便時，實踐環保會更容易。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"be made easy","meaning":"變得容易","examples":[{"en":"Going green must be made easy for ordinary drivers.","zh":"對普通駕駛人士來說，實踐環保必須變得容易。"},{"en":"If something is made easy, people can do it without much stress or difficulty.","zh":"如果某事變得容易，人們就可以少一點壓力和困難地完成它。"},{"en":"Online booking is made easy when a website uses clear steps and simple language.","zh":"當網站使用清晰步驟和簡單語言時，網上預訂就會變得容易。"},{"en":"Recycling can be made easy by placing clear bins near homes and schools.","zh":"透過在家居和學校附近放置清楚標示的回收箱，回收可以變得容易。"},{"en":"A good policy works best when the right choice is made easy for everyone.","zh":"當正確選擇對所有人都變得容易時，好的政策最能發揮作用。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"Dear Editor","meaning":"尊敬的編輯","examples":[{"en":"The letter begins with Dear Editor.","zh":"這封信以「尊敬的編輯」開始。"},{"en":"Dear Editor is a formal greeting used at the start of a letter to a newspaper or magazine.","zh":"「尊敬的編輯」是寫給報章或雜誌時在信件開首使用的正式稱呼。"},{"en":"A student may write Dear Editor before sharing an opinion about school lunches.","zh":"學生在分享對學校午餐的意見前，可能會寫「尊敬的編輯」。"},{"en":"Using Dear Editor shows that the writer is addressing the person who handles readers’ letters.","zh":"使用「尊敬的編輯」表示作者正在向處理讀者來信的人發言。"},{"en":"In a formal public letter, Dear Editor sounds more suitable than Hi there.","zh":"在正式公開信中，「尊敬的編輯」比「你好」更合適。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"research indicates that","meaning":"研究顯示","examples":[{"en":"Research indicates that electric vehicles are greener than petrol cars.","zh":"研究顯示，電動車比汽油車更環保。"},{"en":"Research indicates that means studies or evidence show that something is likely to be true.","zh":"「研究顯示」意思是研究或證據表明某事很可能是真實的。"},{"en":"Research indicates that students remember words better when they use them in real sentences.","zh":"研究顯示，學生把詞語用在真實句子中時，會記得更好。"},{"en":"Research indicates that poor sleep can affect concentration and memory.","zh":"研究顯示，睡眠不足會影響專注力和記憶。"},{"en":"Writers use research indicates that when they want to support an opinion with evidence.","zh":"當作者想用證據支持意見時，會使用「研究顯示」。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"electric vehicles","meaning":"電動車","examples":[{"en":"Electric vehicles are greener than petrol cars.","zh":"電動車比汽油車更環保。"},{"en":"Electric vehicles are cars, buses, or other vehicles powered mainly by electricity instead of petrol.","zh":"電動車是主要由電力而不是汽油驅動的汽車、巴士或其他車輛。"},{"en":"A city may buy electric vehicles for public buses to reduce roadside pollution.","zh":"城市可能購買電動巴士，以減少路邊空氣污染。"},{"en":"Electric vehicles need charging points, so infrastructure affects how useful they are.","zh":"電動車需要充電點，所以基礎設施會影響它們是否實用。"},{"en":"Electric vehicles can help the environment, but drivers still consider price, charging, and repairs.","zh":"電動車可以幫助環境，但駕駛人士仍會考慮價格、充電和維修。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"greener than","meaning":"比……更環保","examples":[{"en":"Electric vehicles are greener than petrol cars.","zh":"電動車比汽油車更環保。"},{"en":"Greener than means causing less environmental damage than something else.","zh":"「比……更環保」意思是對環境造成的傷害比另一樣東西少。"},{"en":"Taking the train is usually greener than flying for a short journey.","zh":"短途旅程中，乘火車通常比乘飛機更環保。"},{"en":"Reusable bottles are greener than disposable plastic bottles because they create less waste.","zh":"可重用水樽比即棄塑膠水樽更環保，因為它們製造較少廢物。"},{"en":"A product is not truly greener than another one unless its whole life cycle is considered.","zh":"除非考慮整個生命周期，否則一件產品未必真正比另一件更環保。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"petrol cars","meaning":"汽油車","examples":[{"en":"Petrol cars are still more familiar to many drivers.","zh":"對許多駕駛人士來說，汽油車仍然更熟悉。"},{"en":"Petrol cars are cars that run on petrol instead of electricity.","zh":"汽油車是使用汽油而不是電力行駛的汽車。"},{"en":"Many families choose petrol cars because petrol stations are easy to find.","zh":"許多家庭選擇汽油車，因為油站容易找到。"},{"en":"Petrol cars create exhaust fumes, which can worsen roadside air quality.","zh":"汽油車會排放廢氣，可能令路邊空氣質素惡化。"},{"en":"Petrol cars may feel convenient, but their environmental cost is harder to ignore.","zh":"汽油車可能感覺方便，但其環境成本越來越難以忽視。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"vehicles sold worldwide","meaning":"全球售出的車輛","examples":[{"en":"Less than 3% of vehicles sold worldwide in 2020 were electric.","zh":"2020年全球售出的車輛中，少於3%是電動車。"},{"en":"Vehicles sold worldwide means all vehicles bought by customers across the world.","zh":"「全球售出的車輛」指世界各地顧客購買的所有車輛。"},{"en":"Reports often count vehicles sold worldwide to compare global market trends.","zh":"報告常計算全球售出的車輛，以比較全球市場趨勢。"},{"en":"If electric vehicles form a small share of vehicles sold worldwide, adoption is still limited.","zh":"如果電動車只佔全球售出車輛的一小部分，採用程度仍然有限。"},{"en":"The number of vehicles sold worldwide can show whether a technology has become mainstream.","zh":"全球售出的車輛數字可以顯示一項技術是否已成為主流。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"this contrast","meaning":"這種反差","examples":[{"en":"This contrast should make policymakers reflect on the issue.","zh":"這種反差應該令政策制定者反思這個問題。"},{"en":"This contrast means the clear difference between two facts or situations just mentioned.","zh":"「這種反差」指剛才提到的兩個事實或情況之間的明顯差異。"},{"en":"This contrast between high concern and low action shows that people face practical barriers.","zh":"高度關注與低度行動之間的這種反差顯示，人們面對實際障礙。"},{"en":"This contrast can help students see why evidence matters in an argument.","zh":"這種反差可以幫助學生看見證據在論證中的重要性。"},{"en":"When this contrast is large, readers may ask why the result does not match expectations.","zh":"當這種反差很大時，讀者可能會問為何結果與預期不符。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"policymakers","meaning":"政策制定者","examples":[{"en":"Hong Kong policymakers should reflect on why electric cars are not more popular.","zh":"香港政策制定者應反思為何電動車沒有更受歡迎。"},{"en":"Policymakers are people in government or organisations who create rules and plans.","zh":"政策制定者是在政府或機構中制定規則和計劃的人。"},{"en":"Policymakers may decide where schools, hospitals, and transport services should be built.","zh":"政策制定者可能決定學校、醫院和交通服務應建在哪裡。"},{"en":"Good policymakers listen to citizens before changing laws that affect daily life.","zh":"好的政策制定者在改變影響日常生活的法律前，會聆聽市民意見。"},{"en":"If policymakers ignore practical problems, even a good idea may fail.","zh":"如果政策制定者忽視實際問題，即使好的想法也可能失敗。"}],"source":"2021 Q2.pdf","sourcePage":1},{"front":"car dealers","meaning":"車行；汽車經銷商","examples":[{"en":"Car dealers need to understand why drivers hesitate to buy electric cars.","zh":"車行需要了解為何駕駛人士猶豫購買電動車。"},{"en":"Car dealers are businesses or people who sell cars to customers.","zh":"車行或汽車經銷商是向顧客售賣汽車的商戶或人士。"},{"en":"Car dealers may explain prices, warranties, repairs, and financing to buyers.","zh":"車行可能向買家解釋價格、保養、維修和貸款安排。"},{"en":"Honest car dealers build trust by explaining both benefits and risks clearly.","zh":"誠實的車行會清楚解釋好處和風險，從而建立信任。"},{"en":"If car dealers cannot answer charging questions, buyers may feel less confident.","zh":"如果車行不能回答充電問題，買家可能會更沒有信心。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"reflect on","meaning":"反思","examples":[{"en":"Policymakers, car dealers and drivers should reflect on one question.","zh":"政策制定者、車行和駕駛人士都應反思一個問題。"},{"en":"To reflect on something means to think carefully about it and learn from it.","zh":"「反思」某事是指仔細思考它，並從中學習。"},{"en":"After a poor test result, a student should reflect on how they studied.","zh":"考試成績不理想後，學生應反思自己如何溫習。"},{"en":"A company may reflect on customer complaints before improving its service.","zh":"公司可能在改善服務前反思顧客投訴。"},{"en":"People reflect on mistakes so they can make better choices next time.","zh":"人們反思錯誤，是為了下次作出更好的選擇。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"apparently better technology","meaning":"看似更好的技術","examples":[{"en":"An apparently better technology has not become a popular choice.","zh":"一項看似更好的技術尚未成為受歡迎的選擇。"},{"en":"Apparently better technology seems better at first, but people may still have doubts about using it.","zh":"看似更好的技術表面上較好，但人們可能仍然懷疑是否使用它。"},{"en":"A new app may be an apparently better technology, but users will avoid it if it is confusing.","zh":"一個新應用程式可能是看似更好的技術，但如果令人困惑，用戶便會避開它。"},{"en":"Apparently better technology can fail when it is too expensive or difficult to access.","zh":"當看似更好的技術太昂貴或難以接觸時，它可能會失敗。"},{"en":"People do not choose an apparently better technology unless it also fits real life.","zh":"除非看似更好的技術也配合現實生活，否則人們不會選擇它。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"a popular choice","meaning":"受歡迎的選擇","examples":[{"en":"Electric cars have not yet become a popular choice.","zh":"電動車尚未成為受歡迎的選擇。"},{"en":"A popular choice is something many people choose because it feels useful, safe, or attractive.","zh":"受歡迎的選擇是許多人因覺得有用、安全或吸引而選擇的東西。"},{"en":"Online payment became a popular choice when shops and customers found it convenient.","zh":"當商店和顧客都覺得方便時，網上付款成為受歡迎的選擇。"},{"en":"A product becomes a popular choice when its price and quality meet people’s needs.","zh":"當產品的價格和質素符合人們需要時，它會成為受歡迎的選擇。"},{"en":"Being new does not automatically make something a popular choice.","zh":"新穎並不會自動令某物成為受歡迎的選擇。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"not so much…as…","meaning":"與其說是……不如說是……","examples":[{"en":"The problem is not so much a lack of environmental concern as a lack of everyday confidence.","zh":"問題與其說是缺乏環保意識，不如說是缺乏日常使用上的信心。"},{"en":"Not so much A as B means B is the real or more important reason, not A.","zh":"「與其說是A，不如說是B」意思是B才是真正或更重要的原因，而不是A。"},{"en":"The issue is not so much laziness as confusion about what to do next.","zh":"這個問題與其說是懶惰，不如說是不清楚下一步該做甚麼。"},{"en":"His failure was not so much a lack of effort as a lack of clear guidance.","zh":"他的失敗與其說是缺乏努力，不如說是缺乏清晰指導。"},{"en":"This structure helps writers correct a simple explanation and point to a deeper one.","zh":"這個句式幫助作者修正簡單解釋，並指出更深層原因。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"environmental concern","meaning":"環保意識","examples":[{"en":"The problem is not simply a lack of environmental concern.","zh":"問題不只是缺乏環保意識。"},{"en":"Environmental concern means care about protecting nature, air, water, and the climate.","zh":"環保意識是指關心保護自然、空氣、水和氣候。"},{"en":"Students show environmental concern when they reduce waste during school activities.","zh":"學生在學校活動中減少浪費時，就是表現出環保意識。"},{"en":"Environmental concern can lead people to recycle, save energy, and choose cleaner transport.","zh":"環保意識可以令人回收、節省能源和選擇較潔淨的交通。"},{"en":"Environmental concern is important, but practical support is needed to turn concern into action.","zh":"環保意識很重要，但仍需要實際支援，才能把關注變成行動。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"everyday confidence","meaning":"日常使用上的信心","examples":[{"en":"Drivers need everyday confidence before they buy electric cars.","zh":"駕駛人士在購買電動車前，需要日常使用上的信心。"},{"en":"Everyday confidence means feeling sure that something will work smoothly in normal daily life.","zh":"日常使用上的信心是指相信某物在平常生活中能順利運作。"},{"en":"Parents need everyday confidence that a school bus will arrive safely and on time.","zh":"家長需要對校車安全準時到達有日常使用上的信心。"},{"en":"Everyday confidence grows when people understand costs, risks, and support clearly.","zh":"當人們清楚了解成本、風險和支援時，日常使用上的信心會增加。"},{"en":"Without everyday confidence, even interested buyers may delay their decision.","zh":"沒有日常使用上的信心，即使有興趣的買家也可能推遲決定。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"turn something from…into…","meaning":"把某物由……變成……","examples":[{"en":"Society must turn electric cars from a principled purchase into a practical one.","zh":"社會必須把電動車由基於理念的購買，變成實際可行的選擇。"},{"en":"To turn something from A into B means to change its nature or role.","zh":"「把某物由A變成B」意思是改變它的性質或作用。"},{"en":"A teacher can turn a boring grammar rule from a memory task into a useful speaking tool.","zh":"老師可以把沉悶的文法規則由記憶任務變成有用的說話工具。"},{"en":"Clear information can turn fear from a barrier into a reason to prepare better.","zh":"清晰資訊可以把恐懼由障礙變成促使人更好準備的原因。"},{"en":"Good design turns a complicated service from a problem into something people can use easily.","zh":"良好設計會把複雜服務由問題變成人們容易使用的東西。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"a principled purchase","meaning":"基於理念的購買","examples":[{"en":"An electric car should not remain only a principled purchase.","zh":"電動車不應只停留在基於理念的購買。"},{"en":"A principled purchase is something bought mainly because it matches a person’s beliefs or values.","zh":"基於理念的購買是指主要因符合個人信念或價值觀而作出的購買。"},{"en":"Buying fair-trade coffee can be a principled purchase for someone who cares about workers’ rights.","zh":"對關心工人權益的人來說，購買公平貿易咖啡可以是基於理念的購買。"},{"en":"A principled purchase may be hard to choose if it costs far more than the ordinary option.","zh":"如果基於理念的購買比普通選擇貴很多，人們可能難以選擇。"},{"en":"People are more likely to make a principled purchase when it is also practical.","zh":"當基於理念的購買同時實際可行時，人們更可能作出這種選擇。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"a practical one","meaning":"實際可行的選擇","examples":[{"en":"Electric cars must become a practical choice for ordinary families.","zh":"電動車必須成為普通家庭實際可行的選擇。"},{"en":"A practical one means an option that works well in real daily situations.","zh":"實際可行的選擇是指在真實日常情況中運作良好的選項。"},{"en":"For a busy parent, a practical one is a phone plan that is affordable and reliable.","zh":"對忙碌家長來說，實際可行的選擇是負擔得起又可靠的電話計劃。"},{"en":"A choice becomes a practical one when people can afford it, understand it, and use it easily.","zh":"當人們負擔得起、理解得到並容易使用時，一個選擇就會變得實際可行。"},{"en":"An idea may sound good, but it must become a practical one before people adopt it.","zh":"一個想法可能聽起來很好，但在被採用前必須成為實際可行的選擇。"}],"source":"2021 Q2.pdf","sourcePage":2},{"front":"reduce their cost","meaning":"降低其成本","examples":[{"en":"Society must reduce the cost of electric cars.","zh":"社會必須降低電動車的成本。"},{"en":"To reduce their cost means to make them cheaper for people to buy or use.","zh":"降低其成本是指令它們購買或使用起來更便宜。"},{"en":"Schools can reduce their cost by sharing books and equipment instead of buying everything twice.","zh":"學校可以透過共用書本和設備，而不是重複購買所有東西，來降低其成本。"},{"en":"Government support may reduce the cost of cleaner transport for low-income families.","zh":"政府支援可能為低收入家庭降低較潔淨交通的成本。"},{"en":"If companies reduce their cost, more customers may be willing to try the product.","zh":"如果公司降低其成本，更多顧客可能願意嘗試該產品。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"remove the inconvenience of","meaning":"消除……的不便","examples":[{"en":"Society must remove the inconvenience of charging.","zh":"社會必須消除充電的不便。"},{"en":"To remove the inconvenience of something means to take away the trouble that makes it difficult to use.","zh":"消除某事的不便是指移除使它難以使用的麻煩。"},{"en":"A shop can remove the inconvenience of waiting by offering online appointments.","zh":"商店可以透過提供網上預約來消除等待的不便。"},{"en":"Clear signs can remove the inconvenience of finding the right bus stop.","zh":"清晰指示牌可以消除尋找正確巴士站的不便。"},{"en":"People accept new services faster when designers remove the inconvenience of using them.","zh":"當設計者消除使用上的不便時，人們會更快接受新服務。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"rebuild public trust in","meaning":"重建公眾對……的信任","examples":[{"en":"Society must rebuild public trust in electric vehicles.","zh":"社會必須重建公眾對電動車的信任。"},{"en":"To rebuild public trust in something means to help people believe in it again after doubts or bad experiences.","zh":"重建公眾對某物的信任，是指在人們有疑慮或不好經驗後，幫助他們重新相信它。"},{"en":"A school must rebuild public trust in its safety rules after a serious accident.","zh":"發生嚴重意外後，學校必須重建公眾對其安全規則的信任。"},{"en":"Clear explanations and honest repairs can rebuild public trust in a damaged service.","zh":"清楚解釋和誠實修復可以重建公眾對受損服務的信任。"},{"en":"Public trust is rebuilt slowly when people see consistent proof, not just promises.","zh":"當人們看到持續證據而不只是承諾時，公眾信任會慢慢重建。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"the technology","meaning":"這項技術","examples":[{"en":"Public trust in the technology must be rebuilt.","zh":"公眾對這項技術的信任必須被重建。"},{"en":"The technology means the particular tools, machines, or systems being discussed.","zh":"「這項技術」指正在討論的特定工具、機器或系統。"},{"en":"Before using online banking, some elderly people want to understand the technology better.","zh":"在使用網上銀行前，一些長者想更了解這項技術。"},{"en":"The technology may be advanced, but people still need simple instructions to use it.","zh":"這項技術可能很先進，但人們仍需要簡單指引才能使用它。"},{"en":"Trust in the technology grows when users see that it is safe and reliable.","zh":"當用戶看見這項技術安全可靠時，對它的信任會增加。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"motorists","meaning":"駕駛人士","examples":[{"en":"Many motorists are put off by the cost.","zh":"許多駕駛人士因成本而卻步。"},{"en":"Motorists are people who drive cars or other motor vehicles.","zh":"駕駛人士是駕駛汽車或其他機動車輛的人。"},{"en":"Motorists need clear road signs to drive safely in unfamiliar areas.","zh":"駕駛人士在不熟悉的地區需要清晰路牌才能安全駕駛。"},{"en":"Higher parking fees may encourage some motorists to use public transport.","zh":"較高的泊車費可能鼓勵一些駕駛人士使用公共交通。"},{"en":"When motorists face high costs, they may delay changing to cleaner vehicles.","zh":"當駕駛人士面對高成本時，他們可能推遲轉用較潔淨的車輛。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"be put off by","meaning":"因……而卻步","examples":[{"en":"Many motorists are put off by the high cost of electric cars.","zh":"許多駕駛人士因電動車的高成本而卻步。"},{"en":"To be put off by something means to lose interest because of a problem, worry, or unpleasant feature.","zh":"因某事而卻步，是指因問題、憂慮或令人不快的特點而失去興趣。"},{"en":"Students may be put off by a course if the instructions are too confusing.","zh":"如果指示太混亂，學生可能會因一門課程而卻步。"},{"en":"Customers are often put off by hidden fees at the final payment stage.","zh":"顧客常因最後付款階段出現隱藏收費而卻步。"},{"en":"People may support an idea but still be put off by its practical difficulties.","zh":"人們可能支持一個想法，但仍因其實際困難而卻步。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"for society","meaning":"對社會而言","examples":[{"en":"An electric car may be greener for society.","zh":"電動車對社會而言可能更環保。"},{"en":"For society means considering the effects on the wider public, not only one person.","zh":"對社會而言，是指考慮對更廣大公眾的影響，而不只是對一個人的影響。"},{"en":"Vaccination can be important for society because it protects vulnerable people.","zh":"疫苗接種對社會而言可能很重要，因為它保護弱勢人士。"},{"en":"A policy may be good for society even if some individuals find it inconvenient.","zh":"一項政策對社會而言可能是好的，即使一些個人覺得不方便。"},{"en":"Writers use for society when they discuss the common good or public impact.","zh":"當作者討論共同利益或公共影響時，會使用「對社會而言」。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"an individual family","meaning":"個別家庭","examples":[{"en":"An electric car can still look expensive for an individual family.","zh":"對個別家庭而言，電動車仍可能看起來昂貴。"},{"en":"An individual family means one particular household, not the whole society.","zh":"個別家庭是指某一個特定家庭，而不是整個社會。"},{"en":"A policy may save money nationally but still feel costly for an individual family.","zh":"一項政策可能在全國層面節省金錢，但對個別家庭仍感覺昂貴。"},{"en":"An individual family must consider rent, food, school fees, and transport before buying a car.","zh":"個別家庭在買車前必須考慮租金、食物、學費和交通。"},{"en":"What is good for society may still be difficult for an individual family to afford.","zh":"對社會有益的事情，對個別家庭而言仍可能難以負擔。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"look like a financial gamble","meaning":"看起來像一場財務賭博","examples":[{"en":"Buying an electric car can still look like a financial gamble.","zh":"購買電動車仍可能看起來像一場財務賭博。"},{"en":"To look like a financial gamble means to seem risky because the future costs are uncertain.","zh":"看起來像一場財務賭博，是指因未來成本不明朗而顯得有風險。"},{"en":"Opening a shop without knowing the rent or customer demand can look like a financial gamble.","zh":"在不知道租金或顧客需求的情況下開店，可能看起來像一場財務賭博。"},{"en":"A purchase looks like a financial gamble when repairs, resale value, and running costs are unclear.","zh":"當維修、轉售價值和日常使用成本不清楚時，一項購買就看起來像一場財務賭博。"},{"en":"Families avoid choices that look like a financial gamble when their budget is tight.","zh":"當家庭預算緊張時，他們會避開看起來像一場財務賭博的選擇。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"initial price","meaning":"初始價格","examples":[{"en":"The initial price is often higher than that of a petrol car.","zh":"初始價格通常高於汽油車的初始價格。"},{"en":"The initial price is the amount paid at the beginning before later costs are added.","zh":"初始價格是指在之後成本加入前，最開始需要支付的金額。"},{"en":"A phone may have a low initial price but expensive monthly fees.","zh":"一部手機可能初始價格低，但每月費用昂貴。"},{"en":"A high initial price can stop customers from trying a product even if it saves money later.","zh":"高初始價格可以阻止顧客嘗試一件產品，即使它之後能省錢。"},{"en":"Buyers should compare the initial price with repair costs, fuel costs, and resale value.","zh":"買家應把初始價格與維修成本、燃料成本和轉售價值作比較。"}],"source":"2021 Q2.pdf","sourcePage":3},{"front":"higher than that of","meaning":"高於……的","examples":[{"en":"The initial price is often higher than that of a petrol car.","zh":"初始價格通常高於汽油車的初始價格。"},{"en":"Higher than that of means one thing’s level or amount is greater than the level or amount of another thing.","zh":"「高於……的」意思是一件事物的水平或數量比另一件事物的水平或數量高。"},{"en":"The rent in the city centre is higher than that of many suburban areas.","zh":"市中心的租金高於許多郊區的租金。"},{"en":"A private school’s fee may be higher than that of a public school.","zh":"私立學校的學費可能高於公立學校的學費。"},{"en":"This phrase avoids repeating the same noun when comparing two things.","zh":"這個短語在比較兩件事物時，可以避免重複同一個名詞。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"future expenses","meaning":"未來開支","examples":[{"en":"Future expenses remain uncertain for many buyers.","zh":"對許多買家來說，未來開支仍然不明朗。"},{"en":"Future expenses are costs that people may need to pay later, not immediately.","zh":"未來開支是指人們之後可能需要支付，而不是立即支付的成本。"},{"en":"Parents consider future expenses such as school trips, uniforms, and exam fees.","zh":"家長會考慮學校旅行、校服和考試費等未來開支。"},{"en":"Future expenses can make a cheap purchase expensive over time.","zh":"未來開支可以令一項便宜的購買隨時間變得昂貴。"},{"en":"Buyers feel safer when future expenses are clear before they make a decision.","zh":"當未來開支在決定前清晰時，買家會感到較安心。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"remain uncertain","meaning":"仍然不明朗","examples":[{"en":"Future expenses remain uncertain.","zh":"未來開支仍然不明朗。"},{"en":"Remain uncertain means something is still not clear or not yet known.","zh":"仍然不明朗是指某事仍不清楚或尚未知道。"},{"en":"The date of the school trip remains uncertain because the weather may change.","zh":"由於天氣可能改變，學校旅行日期仍然不明朗。"},{"en":"If repair costs remain uncertain, customers may avoid buying the product.","zh":"如果維修成本仍然不明朗，顧客可能避免購買該產品。"},{"en":"People often delay important decisions when the risks remain uncertain.","zh":"當風險仍然不明朗時，人們常推遲重要決定。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"in areas such as","meaning":"在……等方面","examples":[{"en":"Future expenses remain uncertain in areas such as battery replacement and specialist repairs.","zh":"未來開支在更換電池和專門維修等方面仍然不明朗。"},{"en":"In areas such as means including examples from particular parts of a larger topic.","zh":"「在……等方面」意思是從一個較大主題的特定部分中舉例。"},{"en":"Schools need support in areas such as mental health, reading, and technology.","zh":"學校在心理健康、閱讀和科技等方面需要支援。"},{"en":"A company may cut costs in areas such as travel, printing, and office supplies.","zh":"公司可能在差旅、印刷和辦公用品等方面削減成本。"},{"en":"This phrase helps writers give examples without claiming the list is complete.","zh":"這個短語幫助作者舉例，而不表示清單完整。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"battery replacement","meaning":"更換電池","examples":[{"en":"Battery replacement can worry potential buyers.","zh":"更換電池可能令潛在買家擔心。"},{"en":"Battery replacement means changing an old or weak battery for a new one.","zh":"更換電池是指把舊的或性能弱的電池換成新的。"},{"en":"A phone may need battery replacement when it loses power too quickly.","zh":"當手機太快沒電時，可能需要更換電池。"},{"en":"Battery replacement can become expensive if the battery is large or specialised.","zh":"如果電池很大或屬專門款式，更換電池可能變得昂貴。"},{"en":"Clear battery replacement costs help buyers judge the long-term value of a vehicle.","zh":"清晰的更換電池成本幫助買家判斷車輛的長遠價值。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"resale value","meaning":"轉售價值","examples":[{"en":"Resale value is one of the costs that potential buyers worry about.","zh":"轉售價值是潛在買家擔心的成本之一。"},{"en":"Resale value is the amount of money something may be sold for after it has been used.","zh":"轉售價值是指某物使用後可能售出的金額。"},{"en":"A car with a strong brand may keep a higher resale value.","zh":"品牌強的汽車可能保持較高轉售價值。"},{"en":"Low resale value can make buyers feel that a product is a poor investment.","zh":"低轉售價值可能令買家覺得產品是不好的投資。"},{"en":"People consider resale value when they know they may sell the item later.","zh":"當人們知道日後可能出售物品時，會考慮轉售價值。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"specialist repairs","meaning":"專門維修","examples":[{"en":"Specialist repairs may increase the cost of owning an electric car.","zh":"專門維修可能增加擁有電動車的成本。"},{"en":"Specialist repairs are repairs that need specially trained workers or equipment.","zh":"專門維修是指需要受過專門訓練的工人或設備進行的維修。"},{"en":"A hospital machine may need specialist repairs because ordinary technicians cannot fix it.","zh":"醫院機器可能需要專門維修，因為普通技術員無法修理。"},{"en":"Specialist repairs can be slower and more expensive than simple repairs.","zh":"專門維修可能比簡單維修更慢和更昂貴。"},{"en":"Buyers feel more confident when specialist repairs are easy to find and clearly priced.","zh":"當專門維修容易找到且價格清晰時，買家會更有信心。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"potential buyers","meaning":"潛在買家","examples":[{"en":"Battery replacement and resale value worry potential buyers.","zh":"更換電池和轉售價值令潛在買家擔心。"},{"en":"Potential buyers are people who may buy something but have not decided yet.","zh":"潛在買家是可能購買某物但尚未決定的人。"},{"en":"A shop offers free samples to help potential buyers try a new product.","zh":"商店提供免費試用裝，幫助潛在買家嘗試新產品。"},{"en":"Potential buyers may walk away if important information is missing.","zh":"如果缺少重要資訊，潛在買家可能會離開。"},{"en":"To win potential buyers, sellers must answer their real questions clearly.","zh":"要吸引潛在買家，賣方必須清楚回答他們真正的問題。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"running costs","meaning":"日常使用成本","examples":[{"en":"The running costs of petrol cars are familiar to many drivers.","zh":"汽油車的日常使用成本為許多駕駛人士所熟悉。"},{"en":"Running costs are the regular costs of using something after buying it.","zh":"日常使用成本是購買後使用某物所需的定期成本。"},{"en":"The running costs of a flat include electricity, water, internet, and maintenance.","zh":"單位的日常使用成本包括電費、水費、上網費和維修費。"},{"en":"Low running costs can make an expensive product cheaper over time.","zh":"低日常使用成本可以令昂貴產品隨時間變得較便宜。"},{"en":"Buyers should compare the purchase price with running costs before deciding.","zh":"買家在決定前應比較購買價格和日常使用成本。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"second-hand prices","meaning":"二手價格","examples":[{"en":"Second-hand prices for petrol cars are familiar to drivers.","zh":"汽油車的二手價格為駕駛人士所熟悉。"},{"en":"Second-hand prices are the prices of used goods sold after their first owner.","zh":"二手價格是指物品經第一位擁有人使用後出售的價格。"},{"en":"Students may check second-hand prices before buying a used laptop.","zh":"學生購買二手手提電腦前，可能會查看二手價格。"},{"en":"Stable second-hand prices can make buyers feel safer about resale value.","zh":"穩定的二手價格可以令買家對轉售價值更安心。"},{"en":"If second-hand prices fall sharply, owners may lose more money when they sell.","zh":"如果二手價格急跌，車主出售時可能損失更多金錢。"}],"source":"2021 Q2.pdf","sourcePage":4},{"front":"be familiar","meaning":"為人熟悉","examples":[{"en":"Petrol cars have running costs that are familiar to many drivers.","zh":"汽油車有許多駕駛人士熟悉的日常使用成本。"},{"en":"To be familiar means to be well known or easy to recognise because of past experience.","zh":"為人熟悉是指因過往經驗而被充分知道或容易認出。"},{"en":"The route to school is familiar after a student travels it every day.","zh":"學生每天走上學路線後，那條路線就會變得熟悉。"},{"en":"Customers feel safer when payment steps are familiar and simple.","zh":"當付款步驟熟悉又簡單時，顧客會感到較安心。"},{"en":"People often choose what is familiar because it feels less risky.","zh":"人們常選擇熟悉的事物，因為它感覺風險較低。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"hidden risks","meaning":"隱藏風險","examples":[{"en":"Electric vehicles are still seen by many as machines with hidden risks.","zh":"電動車仍被許多人視為帶有隱藏風險的機器。"},{"en":"Hidden risks are dangers or problems that are not obvious at first.","zh":"隱藏風險是指一開始不明顯的危險或問題。"},{"en":"A cheap flat may have hidden risks such as leaks, noise, or repair costs.","zh":"便宜單位可能有漏水、噪音或維修費等隱藏風險。"},{"en":"Hidden risks make buyers cautious because they fear unexpected problems later.","zh":"隱藏風險令買家謹慎，因為他們害怕日後出現意外問題。"},{"en":"Clear information helps turn hidden risks into manageable risks.","zh":"清晰資訊有助把隱藏風險變成可管理的風險。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a young couple, for example.","zh":"以一對年輕夫婦為例。"},{"en":"Take something for example means using one case to make a point easier to understand.","zh":"「以……為例」意思是用一個例子令觀點更容易理解。"},{"en":"Take public libraries, for example: they help students who cannot buy many books.","zh":"以公共圖書館為例：它們幫助無法購買很多書的學生。"},{"en":"A writer may say take a small restaurant for example before explaining a business problem.","zh":"作者在解釋商業問題前，可能會說以一間小餐廳為例。"},{"en":"This phrase helps move from a general idea to a clear real-life case.","zh":"這個短語幫助文章從一般想法轉向清晰的生活例子。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"roadside pollution","meaning":"路邊空氣污染","examples":[{"en":"A young couple may care about roadside pollution.","zh":"一對年輕夫婦可能關心路邊空氣污染。"},{"en":"Roadside pollution is dirty air found near roads, often caused by vehicle exhaust.","zh":"路邊空氣污染是道路附近的骯髒空氣，通常由車輛廢氣造成。"},{"en":"Children walking to school may breathe roadside pollution from busy traffic.","zh":"走路上學的孩子可能吸入繁忙交通造成的路邊空氣污染。"},{"en":"Roadside pollution can worsen health problems such as asthma and coughing.","zh":"路邊空氣污染可能令哮喘和咳嗽等健康問題惡化。"},{"en":"Cleaner buses and fewer private cars can help reduce roadside pollution.","zh":"較潔淨的巴士和較少私家車可以幫助減少路邊空氣污染。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"yet choose","meaning":"但仍然選擇","examples":[{"en":"They may care about pollution yet choose a cheaper petrol car.","zh":"他們可能關心污染，但仍然選擇較便宜的汽油車。"},{"en":"Yet choose means someone does one thing despite having a reason to do something different.","zh":"「但仍然選擇」意思是某人有理由做另一件事，卻仍作出某個選擇。"},{"en":"A student may know fast food is unhealthy yet choose it because it is cheap and quick.","zh":"學生可能知道快餐不健康，但仍然因便宜快捷而選擇它。"},{"en":"Families may support recycling yet choose disposable items when they are under pressure.","zh":"家庭可能支持回收，但在壓力下仍然選擇即棄物品。"},{"en":"This phrase shows a gap between belief and practical decision.","zh":"這個短語顯示信念與實際決定之間的差距。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"a cheaper petrol car","meaning":"較便宜的汽油車","examples":[{"en":"A young couple may choose a cheaper petrol car.","zh":"一對年輕夫婦可能選擇較便宜的汽油車。"},{"en":"A cheaper petrol car is a lower-priced car that uses petrol instead of electricity.","zh":"較便宜的汽油車是指價格較低、使用汽油而非電力的汽車。"},{"en":"A family with a tight budget may choose a cheaper petrol car to keep monthly payments low.","zh":"預算緊張的家庭可能選擇較便宜的汽油車，以降低每月供款。"},{"en":"A cheaper petrol car can seem safer financially when electric-car costs are unclear.","zh":"當電動車成本不清楚時，較便宜的汽油車在財務上可能看似較安全。"},{"en":"Choosing a cheaper petrol car may be practical, even if the family cares about the environment.","zh":"選擇較便宜的汽油車可能是實際考慮，即使該家庭關心環境。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"electric model","meaning":"電動車款","examples":[{"en":"An electric model may stretch a family’s mortgage budget.","zh":"電動車款可能令家庭的供樓預算吃緊。"},{"en":"An electric model is a version of a car that runs on electricity.","zh":"電動車款是指使用電力行駛的汽車版本。"},{"en":"A car brand may sell both a petrol model and an electric model.","zh":"一個汽車品牌可能同時售賣汽油車款和電動車款。"},{"en":"An electric model may attract buyers who want lower emissions and quieter driving.","zh":"電動車款可能吸引想要較低排放和較安靜駕駛體驗的買家。"},{"en":"Buyers compare the electric model with the petrol model before choosing.","zh":"買家會把電動車款與汽油車款比較後再作選擇。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"stretch their mortgage budget","meaning":"令供樓預算吃緊","examples":[{"en":"An electric model may stretch their mortgage budget.","zh":"電動車款可能令他們的供樓預算吃緊。"},{"en":"To stretch their mortgage budget means to put pressure on the money a family has after paying for its home loan.","zh":"令供樓預算吃緊，是指對家庭支付房貸後剩下的金錢造成壓力。"},{"en":"Expensive childcare can stretch a young couple’s mortgage budget.","zh":"昂貴的托兒費用可能令年輕夫婦的供樓預算吃緊。"},{"en":"A large car payment may stretch their mortgage budget and leave less money for savings.","zh":"大額汽車供款可能令他們的供樓預算吃緊，並使儲蓄減少。"},{"en":"Families avoid extra costs when those costs stretch their mortgage budget too far.","zh":"當額外成本令供樓預算過度吃緊時，家庭會避免這些成本。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"charging equipment","meaning":"充電設備","examples":[{"en":"Some families cannot install charging equipment at home.","zh":"一些家庭無法在家安裝充電設備。"},{"en":"Charging equipment is the device or system used to put electricity into an electric vehicle.","zh":"充電設備是用來把電力輸入電動車的裝置或系統。"},{"en":"A car park may need charging equipment before residents can use electric cars easily.","zh":"停車場可能需要充電設備，居民才能容易使用電動車。"},{"en":"Without safe charging equipment, drivers may worry about where to charge their vehicles.","zh":"沒有安全的充電設備，駕駛人士可能擔心在哪裡為車輛充電。"},{"en":"Charging equipment must be convenient, reliable, and suitable for daily use.","zh":"充電設備必須方便、可靠，並適合日常使用。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"cannot install","meaning":"無法安裝","examples":[{"en":"They may need charging equipment they cannot install.","zh":"他們可能需要自己無法安裝的充電設備。"},{"en":"Cannot install means being unable to put equipment in place so it can be used.","zh":"無法安裝是指不能把設備放置並設置好以供使用。"},{"en":"Tenants may want air conditioning but cannot install it without the landlord’s approval.","zh":"租客可能想裝冷氣，但沒有業主批准便無法安裝。"},{"en":"A school cannot install new computers if the classrooms lack enough power sockets.","zh":"如果課室沒有足夠電源插座，學校便無法安裝新電腦。"},{"en":"People may reject a useful device if they cannot install it where they live.","zh":"如果人們無法在居住地方安裝有用裝置，他們可能會拒絕使用它。"}],"source":"2021 Q2.pdf","sourcePage":5},{"front":"hypocrisy","meaning":"虛偽","examples":[{"en":"That decision is not hypocrisy.","zh":"那個決定並不是虛偽。"},{"en":"Hypocrisy means saying you believe one thing while acting against it.","zh":"虛偽是指口頭上相信一件事，行動卻與之相反。"},{"en":"It is hypocrisy to demand honesty from others while lying yourself.","zh":"自己說謊卻要求別人誠實，就是虛偽。"},{"en":"Choosing a cheaper option is not hypocrisy if a person simply cannot afford the greener one.","zh":"如果一個人只是負擔不起較環保的選擇，選擇較便宜的選項並不是虛偽。"},{"en":"Before accusing someone of hypocrisy, we should consider their real limits.","zh":"在指責別人虛偽前，我們應考慮他們真正的限制。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"rather","meaning":"反而；更準確地說","examples":[{"en":"That decision is not hypocrisy; rather, it is household arithmetic.","zh":"那個決定不是虛偽；更準確地說，是家庭財務計算。"},{"en":"Rather is used to correct or sharpen a previous idea by giving a more accurate explanation.","zh":"Rather 用來修正或加強前面的想法，給出更準確的解釋。"},{"en":"The child is not lazy; rather, he is confused about the instructions.","zh":"那個孩子不是懶惰；更準確地說，他是不明白指示。"},{"en":"The shop did not fail because the food was bad; rather, the rent was too high.","zh":"那間店失敗並不是因為食物差；反而是因為租金太高。"},{"en":"Writers use rather when they want to replace a weak explanation with a clearer one.","zh":"當作者想用更清楚的解釋取代較弱的解釋時，會使用 rather。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"household arithmetic","meaning":"家庭財務計算","examples":[{"en":"Choosing a petrol car may simply be household arithmetic.","zh":"選擇汽油車可能只是家庭財務計算。"},{"en":"Household arithmetic means the practical calculation a family makes about income, bills, and daily costs.","zh":"家庭財務計算是指家庭對收入、帳單和日常成本作出的實際計算。"},{"en":"A family may cancel a holiday because household arithmetic shows the rent must come first.","zh":"一個家庭可能取消旅行，因為家庭財務計算顯示必須先交租。"},{"en":"Household arithmetic can decide whether a parent buys a new car or repairs the old one.","zh":"家庭財務計算可以決定家長買新車還是修理舊車。"},{"en":"This phrase reminds readers that moral choices often meet real budgets.","zh":"這個短語提醒讀者，道德選擇常會遇上真實預算。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"unless","meaning":"除非","examples":[{"en":"Unless electric vehicles are financially comparable, many drivers will hesitate.","zh":"除非電動車在價格上可相比，否則許多駕駛人士會猶豫。"},{"en":"Unless means if something does not happen or if a condition is not met.","zh":"除非是指如果某事沒有發生，或某個條件沒有達成。"},{"en":"Unless you save your work, the file may disappear when the computer shuts down.","zh":"除非你儲存工作，否則電腦關機時檔案可能會消失。"},{"en":"A shop will not attract customers unless its prices are clear and fair.","zh":"除非價格清晰公平，否則商店難以吸引顧客。"},{"en":"Unless marks the condition that must be satisfied before the result can change.","zh":"「除非」標示出結果改變前必須滿足的條件。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"financially comparable","meaning":"在價格上可相比","examples":[{"en":"Electric vehicles need to be financially comparable with petrol cars.","zh":"電動車需要與汽油車在價格上可相比。"},{"en":"Financially comparable means similar enough in cost for people to compare fairly.","zh":"在價格上可相比，是指成本相近到人們可以公平比較。"},{"en":"Two phone plans are financially comparable if their prices and services are close.","zh":"如果兩個電話計劃的價格和服務接近，它們就在價格上可相比。"},{"en":"Electric cars become financially comparable when subsidies, fuel savings, and repairs are counted together.","zh":"當資助、燃料節省和維修一起計算時，電動車會變得在價格上可相比。"},{"en":"Buyers hesitate when two choices are not financially comparable.","zh":"當兩個選擇在價格上不可相比時，買家會猶豫。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"environmental argument","meaning":"環保論點","examples":[{"en":"The environmental argument may lose to the monthly payment.","zh":"環保論點可能輸給每月供款。"},{"en":"An environmental argument is a reason based on protecting nature, health, or the climate.","zh":"環保論點是基於保護自然、健康或氣候的理由。"},{"en":"The environmental argument for recycling is that it reduces waste and saves resources.","zh":"支持回收的環保論點是它能減少廢物並節省資源。"},{"en":"An environmental argument may not persuade people if the practical cost is too high.","zh":"如果實際成本太高，環保論點未必能說服人。"},{"en":"A strong environmental argument should be supported by clear daily-life solutions.","zh":"有力的環保論點應由清晰的日常生活解決方案支持。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"lose to","meaning":"輸給","examples":[{"en":"The environmental argument will lose to the monthly payment.","zh":"環保論點會輸給每月供款。"},{"en":"Lose to means be less powerful or less successful than another factor.","zh":"輸給是指力量或成功程度不及另一個因素。"},{"en":"A healthy meal may lose to fast food when a worker has only ten minutes for lunch.","zh":"當工人只有十分鐘吃午餐時，健康餐可能輸給快餐。"},{"en":"A good idea can lose to poor timing if people are not ready for it.","zh":"如果人們未準備好，一個好想法可能輸給不合適的時機。"},{"en":"This phrase shows that one reason is defeated by a stronger practical pressure.","zh":"這個短語顯示一個理由被更強的實際壓力擊敗。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"monthly payment","meaning":"每月供款","examples":[{"en":"The monthly payment matters greatly to ordinary families.","zh":"每月供款對普通家庭十分重要。"},{"en":"A monthly payment is the amount someone pays every month for a loan, service, or purchase.","zh":"每月供款是指某人每月為貸款、服務或購買支付的金額。"},{"en":"Families compare monthly payments before choosing a mortgage or car loan.","zh":"家庭在選擇按揭或汽車貸款前，會比較每月供款。"},{"en":"A low monthly payment can make an expensive item feel more affordable.","zh":"較低的每月供款可以令昂貴物品感覺較負擔得起。"},{"en":"If the monthly payment is too high, families may reject the purchase immediately.","zh":"如果每月供款太高，家庭可能立即拒絕購買。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"battery charging","meaning":"電池充電","examples":[{"en":"Battery charging remains the greatest practical barrier.","zh":"電池充電仍然是最大的實際障礙。"},{"en":"Battery charging means putting electricity into a battery so it can power a device or vehicle.","zh":"電池充電是指把電力輸入電池，使其能為裝置或車輛供電。"},{"en":"Phone battery charging is easy because most homes have sockets nearby.","zh":"手機電池充電很容易，因為大多數家中附近都有插座。"},{"en":"Electric-car battery charging becomes difficult when chargers are too few or too slow.","zh":"當充電器太少或太慢時，電動車電池充電就會變得困難。"},{"en":"Reliable battery charging is essential before drivers can depend on electric vehicles.","zh":"在駕駛人士能依賴電動車前，可靠的電池充電十分必要。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"practical barrier","meaning":"實際障礙","examples":[{"en":"Charging remains the greatest practical barrier.","zh":"充電仍然是最大的實際障礙。"},{"en":"A practical barrier is a real-life problem that stops people from doing something.","zh":"實際障礙是阻止人們做某事的現實生活問題。"},{"en":"Lack of time is a practical barrier for adults who want to study after work.","zh":"對想下班後學習的成年人來說，缺乏時間是一個實際障礙。"},{"en":"High rent can be a practical barrier for small businesses.","zh":"高租金可以成為小企業的實際障礙。"},{"en":"A practical barrier must be solved before an idea can work in daily life.","zh":"在想法能於日常生活中運作前，實際障礙必須被解決。"}],"source":"2021 Q2.pdf","sourcePage":6},{"front":"high-rise buildings","meaning":"高樓大廈","examples":[{"en":"Hong Kong is a city of high-rise buildings and shared car parks.","zh":"香港是一個充滿高樓大廈和共用停車場的城市。"},{"en":"High-rise buildings are tall buildings with many floors.","zh":"高樓大廈是有很多樓層的高建築物。"},{"en":"Many people in dense cities live in high-rise buildings instead of houses.","zh":"在人口密集的城市，許多人住在高樓大廈而不是房屋。"},{"en":"High-rise buildings may make home charging harder because residents share parking spaces.","zh":"高樓大廈可能令家居充電更困難，因為居民共用停車位。"},{"en":"Planning services for high-rise buildings requires thinking about lifts, power supply, and common areas.","zh":"為高樓大廈規劃服務時，需要考慮升降機、電力供應和公共空間。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"shared car parks","meaning":"共用停車場","examples":[{"en":"Many Hong Kong drivers use shared car parks.","zh":"許多香港駕駛人士使用共用停車場。"},{"en":"Shared car parks are parking areas used by many residents, workers, or visitors.","zh":"共用停車場是由許多居民、員工或訪客使用的泊車地方。"},{"en":"A shopping centre has shared car parks because different customers use the spaces throughout the day.","zh":"商場有共用停車場，因為不同顧客整天都會使用車位。"},{"en":"Shared car parks can make private charging difficult because no one owns a fixed space.","zh":"共用停車場可能令私人充電困難，因為沒有人擁有固定車位。"},{"en":"Rules are needed in shared car parks so all drivers can use facilities fairly.","zh":"共用停車場需要規則，讓所有駕駛人士公平使用設施。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"detached houses","meaning":"獨立屋","examples":[{"en":"Hong Kong is not a city of detached houses with private garages.","zh":"香港不是一個有私家車房的獨立屋城市。"},{"en":"Detached houses are separate houses that do not share walls with another home.","zh":"獨立屋是不與其他住宅共用牆壁的獨立房屋。"},{"en":"In some suburbs, families live in detached houses with gardens and driveways.","zh":"在一些郊區，家庭住在有花園和車道的獨立屋。"},{"en":"Detached houses often make home charging easier because owners control their own parking space.","zh":"獨立屋通常令家居充電更容易，因為業主控制自己的泊車位。"},{"en":"A city with few detached houses needs public charging solutions, not only home chargers.","zh":"獨立屋很少的城市需要公共充電方案，而不只是家用充電器。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"private garages","meaning":"私家車房","examples":[{"en":"Detached houses usually have private garages.","zh":"獨立屋通常有私家車房。"},{"en":"Private garages are personal indoor parking spaces attached to or near a home.","zh":"私家車房是附屬於住宅或靠近住宅的私人室內泊車空間。"},{"en":"A family may store tools, bicycles, and a car in a private garage.","zh":"一個家庭可能在私家車房存放工具、單車和汽車。"},{"en":"Private garages make charging easier because the driver can install equipment nearby.","zh":"私家車房令充電更容易，因為駕駛人士可以在附近安裝設備。"},{"en":"People without private garages depend more on public or shared charging spaces.","zh":"沒有私家車房的人更依賴公共或共用充電空間。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"be willing to switch","meaning":"願意轉用","examples":[{"en":"Even when drivers are willing to switch, they may have nowhere to charge.","zh":"即使駕駛人士願意轉用，他們也可能沒有地方充電。"},{"en":"To be willing to switch means to be ready to change from one option to another.","zh":"願意轉用是指準備由一個選項轉到另一個選項。"},{"en":"A customer may be willing to switch banks if the new service is simpler and cheaper.","zh":"如果新服務更簡單便宜，顧客可能願意轉用另一間銀行。"},{"en":"Workers are more willing to switch systems when training is clear.","zh":"當培訓清晰時，員工更願意轉用新系統。"},{"en":"People may be willing to switch in principle but unable to do so without support.","zh":"人們原則上可能願意轉用，但沒有支援便無法做到。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"nowhere reliable to","meaning":"沒有可靠地方去……","examples":[{"en":"Drivers may have nowhere reliable to charge their cars overnight.","zh":"駕駛人士可能沒有可靠地方通宵為汽車充電。"},{"en":"Nowhere reliable to do something means there is no dependable place for that action.","zh":"沒有可靠地方去做某事，是指沒有可依靠的地方進行那個行動。"},{"en":"A street vendor may have nowhere reliable to store goods safely after work.","zh":"街頭小販下班後可能沒有可靠地方安全存放貨物。"},{"en":"Students may have nowhere reliable to study if their homes are noisy and libraries are full.","zh":"如果家中嘈雜而圖書館又滿座，學生可能沒有可靠地方學習。"},{"en":"Without somewhere dependable, a simple task becomes a daily worry.","zh":"沒有可依靠的地方，簡單任務也會變成日常憂慮。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"charge their cars overnight","meaning":"通宵為汽車充電","examples":[{"en":"Drivers may have nowhere reliable to charge their cars overnight.","zh":"駕駛人士可能沒有可靠地方通宵為汽車充電。"},{"en":"To charge their cars overnight means to plug in electric cars for several hours while people sleep.","zh":"通宵為汽車充電是指在人們睡覺時，把電動車接上電源數小時。"},{"en":"Residents with fixed parking spaces can often charge their cars overnight at home.","zh":"有固定車位的居民通常可以在家通宵為汽車充電。"},{"en":"Drivers cannot easily charge their cars overnight if chargers are far away or always occupied.","zh":"如果充電器很遠或總是被佔用，駕駛人士便難以通宵為汽車充電。"},{"en":"Overnight charging is useful because the car can be ready the next morning.","zh":"通宵充電很有用，因為汽車第二天早上可以準備好使用。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"be refuelled in minutes","meaning":"幾分鐘內加滿燃油","examples":[{"en":"A petrol car can be refuelled in minutes almost anywhere.","zh":"汽油車幾乎可以在任何地方於幾分鐘內加滿燃油。"},{"en":"To be refuelled in minutes means fuel can be added very quickly.","zh":"幾分鐘內加滿燃油是指可以非常快速地加入燃料。"},{"en":"A taxi is easier to operate when it can be refuelled in minutes during a short break.","zh":"如果的士能在短暫休息時幾分鐘內加滿燃油，營運會更容易。"},{"en":"Petrol cars feel convenient because they can be refuelled in minutes at many stations.","zh":"汽油車感覺方便，因為它們可以在許多油站幾分鐘內加滿燃油。"},{"en":"Electric vehicles must compete with the speed of cars that can be refuelled in minutes.","zh":"電動車必須與能在幾分鐘內加滿燃油的汽車速度競爭。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, an electric car may require hours of waiting.","zh":"相比之下，電動車可能需要等待數小時。"},{"en":"By contrast introduces a clear difference between the previous point and the next one.","zh":"相比之下用來引出前一點與下一點之間的明顯差異。"},{"en":"The city centre is noisy; by contrast, the village is quiet at night.","zh":"市中心很嘈雜；相比之下，村莊晚上很安靜。"},{"en":"Petrol stations are common; by contrast, fast chargers may be harder to find.","zh":"油站很常見；相比之下，快速充電器可能較難找到。"},{"en":"Writers use by contrast to make differences easier for readers to see.","zh":"作者使用「相比之下」，令讀者更容易看見差異。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"a working charger","meaning":"可正常運作的充電器","examples":[{"en":"An electric car may require a working charger.","zh":"電動車可能需要可正常運作的充電器。"},{"en":"A working charger is a charger that is not broken and can provide power properly.","zh":"可正常運作的充電器是指沒有故障並能正常供電的充電器。"},{"en":"A phone is useless on a trip if there is no working charger nearby.","zh":"旅行時，如果附近沒有可正常運作的充電器，手機便沒有用。"},{"en":"Drivers lose confidence when a public station has no working charger available.","zh":"當公共充電站沒有可正常運作的充電器時，駕駛人士會失去信心。"},{"en":"One working charger can solve a problem, but many reliable chargers build trust.","zh":"一個可正常運作的充電器可以解決問題，但大量可靠充電器才能建立信任。"}],"source":"2021 Q2.pdf","sourcePage":7},{"front":"an available parking space","meaning":"可用的車位","examples":[{"en":"A driver needs an available parking space to charge an electric car.","zh":"駕駛人士需要可用的車位來為電動車充電。"},{"en":"An available parking space is an empty space that a driver can use at that time.","zh":"可用的車位是指當時空置並可供駕駛人士使用的泊車位。"},{"en":"A parent may arrive late to a clinic because there is no available parking space nearby.","zh":"如果診所附近沒有可用的車位，家長可能會遲到。"},{"en":"Charging is difficult if the charger exists but there is no available parking space beside it.","zh":"如果有充電器但旁邊沒有可用的車位，充電仍然困難。"},{"en":"Drivers need both a charger and an available parking space, not just one of them.","zh":"駕駛人士需要充電器和可用的車位，而不只是其中一樣。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"several hours of waiting","meaning":"幾小時的等待","examples":[{"en":"Charging may require several hours of waiting.","zh":"充電可能需要幾小時的等待。"},{"en":"Several hours of waiting means spending a long period doing nothing while something finishes.","zh":"幾小時的等待是指花一段長時間等某事完成。"},{"en":"Patients may face several hours of waiting if a clinic is understaffed.","zh":"如果診所人手不足，病人可能面對幾小時的等待。"},{"en":"Several hours of waiting can turn a simple task into a serious inconvenience.","zh":"幾小時的等待可以把簡單任務變成嚴重不便。"},{"en":"Busy workers avoid services that often require several hours of waiting.","zh":"忙碌的工人會避開經常需要幾小時等待的服務。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"taxi driver","meaning":"的士司機","examples":[{"en":"A taxi driver cannot afford long charging delays.","zh":"的士司機承受不起長時間充電延誤。"},{"en":"A taxi driver is someone whose job is to drive passengers for payment.","zh":"的士司機是以駕車接載乘客收費為工作的人。"},{"en":"A taxi driver needs a reliable vehicle because every hour on the road may bring income.","zh":"的士司機需要可靠車輛，因為路上的每一小時都可能帶來收入。"},{"en":"Long queues at chargers can reduce a taxi driver’s working time.","zh":"充電器前的長隊可以減少的士司機的工作時間。"},{"en":"Policies for electric cars must consider taxi drivers because their vehicles are used heavily every day.","zh":"電動車政策必須考慮的士司機，因為他們的車輛每天使用量很高。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"delivery van operator","meaning":"送貨客貨車營運者","examples":[{"en":"A delivery van operator needs reliable transport every day.","zh":"送貨客貨車營運者每天都需要可靠交通。"},{"en":"A delivery van operator is a person or business that uses vans to move goods to customers.","zh":"送貨客貨車營運者是使用客貨車把貨物送到顧客手上的個人或企業。"},{"en":"A delivery van operator may lose clients if parcels arrive late too often.","zh":"如果包裹經常遲到，送貨客貨車營運者可能失去客戶。"},{"en":"Charging delays can hurt a delivery van operator because delivery schedules are tight.","zh":"充電延誤會傷害送貨客貨車營運者，因為送貨時間表很緊密。"},{"en":"Electric vans must save time and money before many delivery van operators will switch.","zh":"在許多送貨客貨車營運者轉用前，電動客貨車必須節省時間和金錢。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"rush between work and school","meaning":"在工作和學校之間奔波","examples":[{"en":"A parent may be rushing between work and school.","zh":"家長可能正在工作和學校之間奔波。"},{"en":"To rush between work and school means to hurry from a job to a child’s school or school activity.","zh":"在工作和學校之間奔波，是指急忙從工作地點趕到孩子的學校或學校活動。"},{"en":"Many parents rush between work and school when they need to pick up children on time.","zh":"許多家長需要準時接孩子時，會在工作和學校之間奔波。"},{"en":"If charging takes too long, parents who rush between work and school may feel extra stress.","zh":"如果充電需時太長，在工作和學校之間奔波的家長可能感到額外壓力。"},{"en":"Transport systems should support people who rush between work and school every day.","zh":"交通系統應支援每天在工作和學校之間奔波的人。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"translate directly into","meaning":"直接變成","examples":[{"en":"Charging uncertainty translates directly into lost time and stress.","zh":"充電的不確定性會直接變成浪費的時間和壓力。"},{"en":"Translate directly into means one thing quickly becomes another result in real life.","zh":"直接變成是指一件事在現實中很快造成另一個結果。"},{"en":"Poor instructions translate directly into mistakes when students do homework alone.","zh":"當學生獨自做功課時，差劣指示會直接變成錯誤。"},{"en":"Higher rent can translate directly into higher food prices in small restaurants.","zh":"較高租金可能在小餐廳中直接變成較高食物價格。"},{"en":"This phrase shows a clear link between a problem and its consequence.","zh":"這個短語顯示問題與後果之間的清晰連繫。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"lost time and stress","meaning":"浪費的時間和壓力","examples":[{"en":"Charging problems can create lost time and stress.","zh":"充電問題可以造成浪費的時間和壓力。"},{"en":"Lost time and stress means wasted hours together with worry or pressure.","zh":"浪費的時間和壓力是指被浪費的時間，加上憂慮或壓力。"},{"en":"A delayed train can cause lost time and stress for workers who have morning meetings.","zh":"火車延誤可能為早上有會議的工人造成浪費的時間和壓力。"},{"en":"Confusing hospital procedures create lost time and stress for patients and families.","zh":"混亂的醫院程序為病人和家庭造成浪費的時間和壓力。"},{"en":"Good services reduce lost time and stress by making steps clear and predictable.","zh":"好服務透過令步驟清晰可預測，減少浪費的時間和壓力。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"more precisely","meaning":"更準確地說","examples":[{"en":"More precisely, the issue is whether charging fits into crowded lives.","zh":"更準確地說，問題是充電能否安排進忙碌的生活之中。"},{"en":"More precisely is used to make an explanation clearer and more exact.","zh":"更準確地說，是用來令解釋更清楚和更準確。"},{"en":"The problem is not money alone; more precisely, it is unstable income.","zh":"問題不只是金錢；更準確地說，是收入不穩定。"},{"en":"She is not afraid of studying abroad; more precisely, she worries about living alone.","zh":"她不是害怕留學；更準確地說，她擔心獨自生活。"},{"en":"Writers use more precisely when they want to correct a broad statement.","zh":"當作者想修正一個籠統說法時，會使用「更準確地說」。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"not only whether…but whether…","meaning":"不只是是否……而是是否……","examples":[{"en":"The question is not only whether electric cars can travel far enough, but whether charging is convenient.","zh":"問題不只是電動車行駛距離是否足夠，而是充電是否方便。"},{"en":"Not only whether A but whether B shows that B is also an important question.","zh":"「不只是是否A，而是是否B」顯示B也是重要問題。"},{"en":"The issue is not only whether students can pass, but whether they truly understand.","zh":"問題不只是學生是否能及格，而是他們是否真正理解。"},{"en":"A city should ask not only whether housing is built, but whether people can afford it.","zh":"城市不應只問房屋是否建成，而應問人們是否負擔得起。"},{"en":"This structure helps writers add a deeper concern after an obvious one.","zh":"這個句式幫助作者在明顯問題後加入更深層關注。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"travel far enough","meaning":"行駛距離是否足夠","examples":[{"en":"Drivers worry about whether electric cars can travel far enough.","zh":"駕駛人士擔心電動車行駛距離是否足夠。"},{"en":"Travel far enough means go the needed distance without stopping or failing.","zh":"行駛距離是否足夠，是指能否在不停止或失效的情況下走完所需距離。"},{"en":"A bus must travel far enough to finish its route before returning to the depot.","zh":"巴士必須有足夠行駛距離完成路線後返回車廠。"},{"en":"Families worry whether a car can travel far enough for weekend trips.","zh":"家庭會擔心汽車行駛距離是否足夠應付週末旅行。"},{"en":"Range matters because drivers need confidence that they can travel far enough for daily life.","zh":"續航距離很重要，因為駕駛人士需要有信心能應付日常生活所需路程。"}],"source":"2021 Q2.pdf","sourcePage":8},{"front":"fit charging into","meaning":"把充電安排進……之中","examples":[{"en":"Drivers need to fit charging into crowded lives.","zh":"駕駛人士需要把充電安排進忙碌的生活之中。"},{"en":"To fit charging into a schedule means to find time for it among other duties.","zh":"把充電安排進日程，是指在其他責任之中找時間充電。"},{"en":"A nurse working shifts may struggle to fit charging into her daily routine.","zh":"輪班護士可能難以把充電安排進每日生活之中。"},{"en":"Parents need to fit charging into school runs, work, shopping, and rest.","zh":"家長需要把充電安排進接送上學、工作、購物和休息之中。"},{"en":"If people cannot fit charging into their lives, they may choose a petrol car instead.","zh":"如果人們不能把充電安排進生活之中，他們可能改選汽油車。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"crowded lives","meaning":"忙碌的生活","examples":[{"en":"Many drivers have crowded lives.","zh":"許多駕駛人士有忙碌的生活。"},{"en":"Crowded lives are busy lives filled with many duties, appointments, and worries.","zh":"忙碌的生活是充滿責任、約會和憂慮的生活。"},{"en":"Parents with crowded lives may have little time to compare car technologies.","zh":"生活忙碌的家長可能沒有太多時間比較汽車技術。"},{"en":"Crowded lives make convenience important because people cannot absorb extra delays.","zh":"忙碌的生活令便利變得重要，因為人們無法承受額外延誤。"},{"en":"A good service respects crowded lives by saving time and reducing stress.","zh":"好服務會透過節省時間和減少壓力來尊重忙碌的生活。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"no wonder","meaning":"難怪","examples":[{"en":"No wonder many people hesitate.","zh":"難怪許多人會猶豫。"},{"en":"No wonder means it is not surprising because there is a clear reason.","zh":"難怪意思是某事不令人驚訝，因為背後有清楚原因。"},{"en":"The bus was late every day, so no wonder students complained.","zh":"巴士每天都遲到，難怪學生投訴。"},{"en":"No wonder customers left the shop when prices rose and service fell.","zh":"當價格上升而服務下降，難怪顧客離開那間店。"},{"en":"Writers use no wonder to show that a reaction is understandable.","zh":"作者使用「難怪」來表示某種反應是可以理解的。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"hesitate","meaning":"猶豫","examples":[{"en":"Many people hesitate before buying electric cars.","zh":"許多人在購買電動車前會猶豫。"},{"en":"To hesitate means to pause before acting because of doubt, fear, or uncertainty.","zh":"猶豫是指因懷疑、害怕或不確定而在行動前停下來。"},{"en":"A student may hesitate before answering if they are not sure of the grammar.","zh":"如果學生不確定文法，回答前可能會猶豫。"},{"en":"Buyers hesitate when the price is high and the benefits are unclear.","zh":"當價格高而好處不清楚時，買家會猶豫。"},{"en":"People hesitate less when they receive clear information and practical support.","zh":"當人們獲得清晰資訊和實際支援時，會少一點猶豫。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"convenience","meaning":"便利","examples":[{"en":"Convenience is not a luxury in modern transport.","zh":"在現代交通中，便利不是奢侈品。"},{"en":"Convenience means something is easy, quick, and suitable for daily use.","zh":"便利是指某事容易、快捷，並適合日常使用。"},{"en":"Online payment offers convenience because people can pay without queuing.","zh":"網上付款提供便利，因為人們不用排隊也能付款。"},{"en":"Convenience affects transport choices because busy people value time highly.","zh":"便利會影響交通選擇，因為忙碌的人非常重視時間。"},{"en":"A green option needs convenience as well as good intentions.","zh":"環保選項除了良好意願，也需要便利。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"not a luxury","meaning":"不是奢侈品","examples":[{"en":"Convenience is not a luxury in modern transport.","zh":"在現代交通中，便利不是奢侈品。"},{"en":"Not a luxury means something is necessary, not just an extra comfort for rich people.","zh":"不是奢侈品是指某物是必要的，而不只是富人的額外享受。"},{"en":"Internet access is not a luxury for students who need to submit homework online.","zh":"對需要網上交功課的學生來說，上網不是奢侈品。"},{"en":"Safe public toilets are not a luxury in a busy city.","zh":"在繁忙城市中，安全的公共洗手間不是奢侈品。"},{"en":"Calling something not a luxury shows that it is a basic need.","zh":"稱某物不是奢侈品，表示它是基本需要。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"modern transport","meaning":"現代交通","examples":[{"en":"Convenience matters greatly in modern transport.","zh":"便利在現代交通中十分重要。"},{"en":"Modern transport includes today’s systems for moving people and goods, such as trains, buses, cars, and delivery networks.","zh":"現代交通包括今天運送人和貨物的系統，例如火車、巴士、汽車和送貨網絡。"},{"en":"Modern transport must be reliable because people plan work and school around it.","zh":"現代交通必須可靠，因為人們圍繞它安排工作和上學。"},{"en":"Modern transport becomes better when it is clean, affordable, and easy to use.","zh":"當現代交通潔淨、負擔得起又易用時，它會變得更好。"},{"en":"Electric vehicles can be part of modern transport only if charging fits daily life.","zh":"只有當充電配合日常生活時，電動車才能成為現代交通的一部分。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"the condition on which","meaning":"……所依賴的條件","examples":[{"en":"Convenience is the condition on which adoption depends.","zh":"便利是採用與否所依賴的條件。"},{"en":"The condition on which means the necessary factor that decides whether something can happen.","zh":"「……所依賴的條件」指決定某事能否發生的必要因素。"},{"en":"Trust is the condition on which a good friendship depends.","zh":"信任是良好友誼所依賴的條件。"},{"en":"Clear safety rules are the condition on which parents allow children to join a trip.","zh":"清晰安全規則是家長允許孩子參加旅行所依賴的條件。"},{"en":"This phrase shows that one thing cannot succeed without another thing.","zh":"這個短語顯示一件事沒有另一件事便不能成功。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"adoption depends","meaning":"採用與否取決於","examples":[{"en":"The adoption of electric cars depends on convenience.","zh":"電動車的採用與否取決於便利。"},{"en":"Adoption depends means people will accept or use something only if a certain condition is met.","zh":"採用與否取決於某事，是指只有在某個條件達成時，人們才會接受或使用它。"},{"en":"The adoption of online learning depends on internet access and teacher support.","zh":"網上學習的採用與否取決於網絡接入和教師支援。"},{"en":"Recycling adoption depends on whether bins are easy to find and use.","zh":"回收的採用與否取決於回收箱是否容易找到和使用。"},{"en":"When adoption depends on convenience, good design becomes essential.","zh":"當採用與否取決於便利時，良好設計就變得必要。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"suffer from","meaning":"受……困擾","examples":[{"en":"Electric vehicles still suffer from a trust gap.","zh":"電動車仍然受信任缺口困擾。"},{"en":"To suffer from a problem means to be negatively affected by it.","zh":"受某問題困擾是指受到它的負面影響。"},{"en":"Students may suffer from stress when exams and homework pile up.","zh":"當考試和功課堆積時，學生可能受壓力困擾。"},{"en":"A small shop can suffer from high rent and falling customer numbers.","zh":"小店可能受高租金和顧客減少困擾。"},{"en":"When a product suffers from a bad reputation, clear evidence is needed to rebuild confidence.","zh":"當產品受壞名聲困擾時，需要清晰證據重建信心。"}],"source":"2021 Q2.pdf","sourcePage":9},{"front":"a trust gap","meaning":"信任缺口","examples":[{"en":"Electric vehicles still suffer from a trust gap.","zh":"電動車仍然受信任缺口困擾。"},{"en":"A trust gap is the distance between what people are told and what they feel able to believe.","zh":"信任缺口是指人們被告知的內容與他們能夠相信的程度之間的距離。"},{"en":"A hospital may face a trust gap if patients do not understand its safety procedures.","zh":"如果病人不理解醫院的安全程序，醫院可能面對信任缺口。"},{"en":"A trust gap grows when bad stories spread faster than clear facts.","zh":"當壞消息比清楚事實傳得更快時，信任缺口會擴大。"},{"en":"Companies close a trust gap by being honest, consistent, and transparent.","zh":"公司透過誠實、一致和透明來收窄信任缺口。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"fully understand","meaning":"充分了解","examples":[{"en":"Few buyers fully understand battery warranties.","zh":"很少買家充分了解電池保養。"},{"en":"To fully understand something means to know it clearly, including its details and limits.","zh":"充分了解某事是指清楚知道它，包括細節和限制。"},{"en":"Students fully understand a grammar rule when they can explain and use it correctly.","zh":"當學生能正確解釋和使用文法規則時，他們才算充分了解。"},{"en":"Buyers may not fully understand a contract if important terms are hidden in small print.","zh":"如果重要條款藏在細字中，買家可能無法充分了解合約。"},{"en":"People make better decisions when they fully understand both benefits and risks.","zh":"當人們充分了解好處和風險時，會作出更好的決定。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"battery warranties","meaning":"電池保養","examples":[{"en":"Many buyers do not fully understand battery warranties.","zh":"許多買家並不充分了解電池保養。"},{"en":"Battery warranties are promises about repair or replacement if a battery fails within certain conditions.","zh":"電池保養是在某些條件下電池失效時，關於維修或更換的承諾。"},{"en":"A phone battery warranty may cover defects but not damage caused by misuse.","zh":"手機電池保養可能涵蓋瑕疵，但不包括錯誤使用造成的損壞。"},{"en":"Battery warranties affect buyer confidence because batteries can be expensive to replace.","zh":"電池保養會影響買家信心，因為更換電池可能很昂貴。"},{"en":"Clear battery warranties help people know what protection they really have.","zh":"清晰的電池保養幫助人們知道自己真正得到甚麼保障。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"safety in heavy rain","meaning":"暴雨中的安全性","examples":[{"en":"Some buyers worry about electric-car safety in heavy rain.","zh":"一些買家擔心電動車在暴雨中的安全性。"},{"en":"Safety in heavy rain means whether something remains safe during strong rainfall and wet conditions.","zh":"暴雨中的安全性是指某物在強降雨和濕滑情況下是否仍然安全。"},{"en":"Parents may ask about school bus safety in heavy rain before a typhoon season.","zh":"家長可能在颱風季前詢問校巴在暴雨中的安全性。"},{"en":"Drivers worry about safety in heavy rain because roads become slippery and visibility falls.","zh":"駕駛人士擔心暴雨中的安全性，因為道路會變滑，能見度會下降。"},{"en":"Clear testing results can reduce fears about safety in heavy rain.","zh":"清晰測試結果可以減少人們對暴雨中安全性的恐懼。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"long-term savings","meaning":"長遠節省","examples":[{"en":"Many buyers are unsure about long-term savings.","zh":"許多買家對長遠節省沒有把握。"},{"en":"Long-term savings are money saved over a long period, not immediately.","zh":"長遠節省是指在長時間內節省的金錢，而不是立即節省。"},{"en":"Energy-efficient lights may cost more at first but create long-term savings through lower electricity bills.","zh":"節能燈一開始可能較貴，但可透過較低電費帶來長遠節省。"},{"en":"Long-term savings are difficult to trust if repair costs remain unclear.","zh":"如果維修成本仍然不清楚，長遠節省便難以令人相信。"},{"en":"Buyers need clear calculations before they believe in promised long-term savings.","zh":"買家需要清晰計算，才會相信承諾中的長遠節省。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Meanwhile, one negative story can spread quickly.","zh":"與此同時，一個負面故事可以迅速傳開。"},{"en":"Meanwhile means at the same time or while another situation is happening.","zh":"與此同時是指在同一時間，或另一情況正在發生時。"},{"en":"The school repaired the library; meanwhile, students used the computer room for study.","zh":"學校維修圖書館；與此同時，學生使用電腦室溫習。"},{"en":"Prices were falling; meanwhile, customers were still worried about quality.","zh":"價格正在下降；與此同時，顧客仍擔心質素。"},{"en":"Writers use meanwhile to connect two things happening in the same period.","zh":"作者使用「與此同時」來連接同一時期發生的兩件事。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"a broken charger","meaning":"壞掉的充電器","examples":[{"en":"A story about a broken charger can damage public trust.","zh":"關於壞掉的充電器的故事可以損害公眾信任。"},{"en":"A broken charger is a charging device that does not work properly.","zh":"壞掉的充電器是指不能正常運作的充電裝置。"},{"en":"A traveller may panic when their phone is dying and they only have a broken charger.","zh":"當旅客手機快沒電而只有壞掉的充電器時，可能會慌張。"},{"en":"One broken charger at a public station can create delays for several drivers.","zh":"公共充電站一個壞掉的充電器可以為幾位駕駛人士造成延誤。"},{"en":"Broken chargers should be repaired quickly because reliability shapes public confidence.","zh":"壞掉的充電器應迅速修理，因為可靠性會塑造公眾信心。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"a degraded battery","meaning":"性能衰退的電池","examples":[{"en":"A degraded battery can make the whole technology look unreliable.","zh":"性能衰退的電池可以令整項技術看起來不可靠。"},{"en":"A degraded battery is a battery that has lost some of its original power or performance.","zh":"性能衰退的電池是指失去部分原有電力或表現的電池。"},{"en":"An old phone with a degraded battery may shut down even when it shows 20%.","zh":"一部有性能衰退電池的舊手機，即使顯示20%電量也可能關機。"},{"en":"A degraded battery worries drivers because it may reduce travel distance.","zh":"性能衰退的電池令駕駛人士擔心，因為它可能減少行駛距離。"},{"en":"Battery checks can show whether a degraded battery still works safely.","zh":"電池檢查可以顯示性能衰退的電池是否仍能安全運作。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"spread quickly","meaning":"迅速傳開","examples":[{"en":"A negative story can spread quickly.","zh":"一個負面故事可以迅速傳開。"},{"en":"Spread quickly means become known by many people in a short time.","zh":"迅速傳開是指在短時間內被很多人知道。"},{"en":"A rumour can spread quickly through group chats at school.","zh":"謠言可以透過學校群組聊天迅速傳開。"},{"en":"Bad reviews spread quickly online and may hurt a small business.","zh":"壞評價在網上迅速傳開，可能傷害小企業。"},{"en":"When stories spread quickly, facts must be shared quickly too.","zh":"當故事迅速傳開時，事實也必須快速分享。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"make something look unreliable","meaning":"令某物看起來不可靠","examples":[{"en":"A single bad story can make the technology look unreliable.","zh":"單一壞故事可以令這項技術看起來不可靠。"},{"en":"To make something look unreliable means to create the impression that it cannot be trusted to work properly.","zh":"令某物看起來不可靠，是指造成它不能被信任會正常運作的印象。"},{"en":"One late school bus can make the whole transport service look unreliable.","zh":"一班遲到的校巴可以令整個交通服務看起來不可靠。"},{"en":"Broken payment machines make a shop look unreliable even if its products are good.","zh":"壞掉的付款機令商店看起來不可靠，即使其產品很好。"},{"en":"People avoid services that look unreliable because they fear wasted time and trouble.","zh":"人們避開看起來不可靠的服務，因為他們害怕浪費時間和遇到麻煩。"}],"source":"2021 Q2.pdf","sourcePage":10},{"front":"in the eyes of the public","meaning":"在公眾眼中","examples":[{"en":"In the eyes of the public, uncertainty can be very damaging.","zh":"在公眾眼中，不確定性可以很具破壞性。"},{"en":"In the eyes of the public means from the viewpoint of ordinary people in society.","zh":"在公眾眼中，是指從社會普通人的角度來看。"},{"en":"In the eyes of the public, a leader’s apology must sound honest to rebuild trust.","zh":"在公眾眼中，領袖的道歉必須聽起來真誠，才能重建信任。"},{"en":"A company may be successful financially but still look careless in the eyes of the public.","zh":"一間公司可能財務上成功，但在公眾眼中仍顯得粗心。"},{"en":"This phrase is useful when discussing reputation and public opinion.","zh":"討論聲譽和公眾意見時，這個短語很有用。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"actual weakness","meaning":"實際弱點","examples":[{"en":"Uncertainty can be as damaging as actual weakness.","zh":"不確定性可以與實際弱點一樣具破壞性。"},{"en":"Actual weakness means a real problem or fault, not just a fear or rumour.","zh":"實際弱點是指真實問題或缺陷，而不只是恐懼或傳言。"},{"en":"A bridge may have actual weakness if engineers find cracks in its structure.","zh":"如果工程師在橋樑結構中發現裂痕，橋樑可能有實際弱點。"},{"en":"A product can lose trust even before actual weakness is proven.","zh":"即使實際弱點尚未被證明，產品也可能失去信任。"},{"en":"Clear testing helps people separate actual weakness from imagined danger.","zh":"清晰測試幫助人們把實際弱點與想像中的危險分開。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"as damaging as","meaning":"與……一樣具破壞性","examples":[{"en":"Uncertainty can be as damaging as actual weakness.","zh":"不確定性可以與實際弱點一樣具破壞性。"},{"en":"As damaging as means causing the same level of harm as something else.","zh":"與……一樣具破壞性，是指造成與另一事物相同程度的傷害。"},{"en":"False information can be as damaging as no information in an emergency.","zh":"在緊急情況中，錯誤資訊可以與沒有資訊一樣具破壞性。"},{"en":"Poor communication may be as damaging as poor service because both destroy trust.","zh":"差劣溝通可能與差劣服務一樣具破壞性，因為兩者都摧毀信任。"},{"en":"This phrase compares two different causes that create similar harm.","zh":"這個短語比較兩個不同原因所造成的相似傷害。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"therefore","meaning":"因此","examples":[{"en":"Therefore, the government and the motor industry should act.","zh":"因此，政府和汽車業應採取行動。"},{"en":"Therefore means for that reason or as a result of what has just been explained.","zh":"因此是指基於剛剛解釋的原因或結果。"},{"en":"The road is flooded; therefore, drivers should avoid the area.","zh":"道路被水淹浸；因此，駕駛人士應避開該區。"},{"en":"Many students cannot afford textbooks; therefore, the school should provide shared copies.","zh":"許多學生負擔不起教科書；因此，學校應提供共用書本。"},{"en":"Writers use therefore to connect evidence with a conclusion or recommendation.","zh":"作者使用「因此」來把證據與結論或建議連接起來。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"the motor industry","meaning":"汽車業","examples":[{"en":"The government and the motor industry should make the experience transparent.","zh":"政府和汽車業應令電動車體驗透明化。"},{"en":"The motor industry includes businesses that design, make, sell, repair, and support vehicles.","zh":"汽車業包括設計、製造、銷售、維修和支援車輛的企業。"},{"en":"The motor industry trains mechanics when new vehicle technology becomes common.","zh":"當新車輛技術變得普遍時，汽車業會培訓技工。"},{"en":"The motor industry affects drivers because it controls prices, services, and repair information.","zh":"汽車業會影響駕駛人士，因為它控制價格、服務和維修資訊。"},{"en":"Cleaner transport needs cooperation between government, drivers, and the motor industry.","zh":"較潔淨交通需要政府、駕駛人士和汽車業合作。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"not merely","meaning":"不只是","examples":[{"en":"The industry should not merely praise electric cars.","zh":"汽車業不應只是稱讚電動車。"},{"en":"Not merely means not only or not just one simple action.","zh":"不只是意思是不只做一個簡單行動。"},{"en":"Schools should not merely punish bullying; they should also teach respect.","zh":"學校不應只是懲罰欺凌，還應教導尊重。"},{"en":"A company should not merely advertise safety but prove it through testing.","zh":"公司不應只是宣傳安全，而應透過測試證明安全。"},{"en":"This phrase shows that a stronger or more complete action is needed.","zh":"這個短語顯示需要更有力或更完整的行動。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"praise electric cars","meaning":"稱讚電動車","examples":[{"en":"The government should not merely praise electric cars.","zh":"政府不應只是稱讚電動車。"},{"en":"To praise electric cars means to speak positively about their benefits.","zh":"稱讚電動車是指正面談論它們的好處。"},{"en":"Officials may praise electric cars for producing less roadside pollution.","zh":"官員可能稱讚電動車能產生較少路邊空氣污染。"},{"en":"Praising electric cars is not enough if drivers still cannot afford or charge them.","zh":"如果駕駛人士仍負擔不起或無法充電，稱讚電動車並不足夠。"},{"en":"People trust praise more when it is supported by facts, prices, and services.","zh":"當稱讚有事實、價格和服務支持時，人們會更相信。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"make the experience transparent","meaning":"令體驗透明化","examples":[{"en":"The industry should make the electric-car experience transparent.","zh":"汽車業應令電動車體驗透明化。"},{"en":"To make the experience transparent means to show people clearly what using something is really like.","zh":"令體驗透明化是指清楚展示使用某物的真實情況。"},{"en":"A school can make the application experience transparent by explaining fees, deadlines, and interviews.","zh":"學校可以透過解釋費用、截止日期和面試，令申請體驗透明化。"},{"en":"Car dealers make the experience transparent when they show charging time, repair costs, and warranties openly.","zh":"當車行公開展示充電時間、維修成本和保養時，就是令體驗透明化。"},{"en":"Transparency helps customers decide with facts instead of fear.","zh":"透明化幫助顧客憑事實而不是恐懼作決定。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"public test-drive days","meaning":"公眾試駕日","examples":[{"en":"Public test-drive days would help consumers understand electric cars.","zh":"公眾試駕日會幫助消費者了解電動車。"},{"en":"Public test-drive days are events where ordinary people can try driving vehicles before buying them.","zh":"公眾試駕日是讓普通人在購買前試駕車輛的活動。"},{"en":"A community centre may host public test-drive days to let families experience electric cars safely.","zh":"社區中心可能舉辦公眾試駕日，讓家庭安全地體驗電動車。"},{"en":"Public test-drive days reduce fear because people can ask questions while trying the car.","zh":"公眾試駕日減少恐懼，因為人們可以一邊試車一邊提問。"},{"en":"Such events turn an unfamiliar technology into a real experience.","zh":"這類活動把陌生技術變成真實體驗。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"clear cost calculators","meaning":"清晰的成本計算器","examples":[{"en":"Clear cost calculators would help consumers compare different cars.","zh":"清晰的成本計算器會幫助消費者比較不同汽車。"},{"en":"Clear cost calculators are tools that show expected costs in a simple and understandable way.","zh":"清晰的成本計算器是以簡單易明方式展示預計成本的工具。"},{"en":"A bank uses clear cost calculators to help families estimate monthly loan payments.","zh":"銀行使用清晰的成本計算器，幫助家庭估算每月貸款供款。"},{"en":"Clear cost calculators can include purchase price, fuel savings, repairs, and resale value.","zh":"清晰的成本計算器可以包括購買價格、燃料節省、維修和轉售價值。"},{"en":"When cost calculators are clear, buyers can compare choices without guessing.","zh":"當成本計算器清晰時，買家可以不用猜測地比較選擇。"}],"source":"2021 Q2.pdf","sourcePage":11},{"front":"independent battery-health certificates","meaning":"獨立電池健康證明","examples":[{"en":"Independent battery-health certificates would build consumer confidence.","zh":"獨立電池健康證明會建立消費者信心。"},{"en":"Independent battery-health certificates are reports from neutral experts showing the condition of a battery.","zh":"獨立電池健康證明是由中立專家發出的報告，顯示電池狀況。"},{"en":"A used electric car with an independent battery-health certificate may feel less risky to buy.","zh":"一輛有獨立電池健康證明的二手電動車，可能讓人覺得購買風險較低。"},{"en":"These certificates protect buyers because they reduce uncertainty about battery quality.","zh":"這些證明保護買家，因為它們減少對電池質素的不確定性。"},{"en":"Independent proof is stronger than a seller’s simple promise.","zh":"獨立證明比賣方的簡單承諾更有力。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"honest comparisons between…and…","meaning":"……與……之間的誠實比較","examples":[{"en":"Honest comparisons between petrol and electric models would help consumers.","zh":"汽油車款與電動車款之間的誠實比較會幫助消費者。"},{"en":"Honest comparisons between two things show both strengths and weaknesses fairly.","zh":"兩者之間的誠實比較會公平展示雙方的優點和弱點。"},{"en":"Honest comparisons between public and private schools should include cost, support, and pressure.","zh":"公立學校與私立學校之間的誠實比較應包括成本、支援和壓力。"},{"en":"Buyers need honest comparisons between products instead of only advertising slogans.","zh":"買家需要產品之間的誠實比較，而不是只有廣告口號。"},{"en":"Honest comparisons help people choose what fits their real needs.","zh":"誠實比較幫助人們選擇符合真實需要的東西。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"make informed decisions","meaning":"作出知情決定","examples":[{"en":"Consumers need information to make informed decisions.","zh":"消費者需要資訊來作出知情決定。"},{"en":"To make informed decisions means to choose after understanding the facts, risks, and options.","zh":"作出知情決定是指在了解事實、風險和選項後作選擇。"},{"en":"Patients make informed decisions when doctors explain treatment benefits and side effects clearly.","zh":"當醫生清楚解釋治療好處和副作用時，病人能作出知情決定。"},{"en":"Students can make informed decisions about courses after seeing workload and career paths.","zh":"學生看過工作量和職業路向後，可以對課程作出知情決定。"},{"en":"Clear information helps people make informed decisions instead of acting on fear.","zh":"清晰資訊幫助人們作出知情決定，而不是因恐懼行動。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"instead of relying on","meaning":"而不是依賴","examples":[{"en":"Consumers should make informed decisions instead of relying on rumours.","zh":"消費者應作出知情決定，而不是依賴傳聞。"},{"en":"Instead of relying on means choosing not to depend on one weak source and using something better.","zh":"而不是依賴，是指不依靠一個較弱來源，而使用更好的來源。"},{"en":"Students should check the textbook instead of relying on guesses from classmates.","zh":"學生應查看課本，而不是依賴同學的猜測。"},{"en":"Patients should ask doctors instead of relying on random internet comments.","zh":"病人應詢問醫生，而不是依賴網上隨機留言。"},{"en":"This phrase shows that one method should replace another.","zh":"這個短語顯示一種方法應取代另一種方法。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"rely on rumours","meaning":"依賴傳聞","examples":[{"en":"Consumers should not rely on rumours when choosing a car.","zh":"消費者選擇汽車時不應依賴傳聞。"},{"en":"To rely on rumours means to base decisions on unverified stories or gossip.","zh":"依賴傳聞是指根據未經證實的故事或流言作決定。"},{"en":"Students should not rely on rumours about exam questions.","zh":"學生不應依賴關於考試題目的傳聞。"},{"en":"Buyers who rely on rumours may misunderstand the real costs and risks.","zh":"依賴傳聞的買家可能誤解真實成本和風險。"},{"en":"People should rely on evidence, not rumours, when making expensive decisions.","zh":"作出昂貴決定時，人們應依賴證據，而不是傳聞。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"attract more drivers","meaning":"吸引更多駕駛人士","examples":[{"en":"Hong Kong needs a coordinated plan to attract more drivers.","zh":"香港需要一個協調一致的計劃來吸引更多駕駛人士。"},{"en":"To attract more drivers means to encourage a larger number of drivers to choose something.","zh":"吸引更多駕駛人士是指鼓勵更多駕駛人士選擇某物。"},{"en":"Lower fares and safer routes can attract more drivers to park-and-ride services.","zh":"較低收費和較安全路線可以吸引更多駕駛人士使用泊車轉乘服務。"},{"en":"Electric cars will attract more drivers if charging is easy and costs are predictable.","zh":"如果充電容易且成本可預測，電動車會吸引更多駕駛人士。"},{"en":"To attract more drivers, policies must solve their everyday worries.","zh":"要吸引更多駕駛人士，政策必須解決他們的日常憂慮。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"a coordinated plan","meaning":"協調一致的計劃","examples":[{"en":"Hong Kong needs a coordinated plan rather than scattered incentives.","zh":"香港需要協調一致的計劃，而不是零散的誘因。"},{"en":"A coordinated plan is an organised plan whose parts work together.","zh":"協調一致的計劃是各部分互相配合的有組織計劃。"},{"en":"A school needs a coordinated plan when teachers, parents, and counsellors support the same student.","zh":"當老師、家長和輔導員一起支援同一學生時，學校需要協調一致的計劃。"},{"en":"A coordinated plan prevents waste because different groups know their roles.","zh":"協調一致的計劃可以避免浪費，因為不同群體知道自己的角色。"},{"en":"Big problems usually need a coordinated plan, not separate small actions.","zh":"大問題通常需要協調一致的計劃，而不是分散的小行動。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"rather than","meaning":"而不是","examples":[{"en":"Hong Kong needs a coordinated plan rather than scattered incentives.","zh":"香港需要協調一致的計劃，而不是零散的誘因。"},{"en":"Rather than shows that one choice is preferred over another.","zh":"Rather than 表示一個選擇比另一個更可取。"},{"en":"Students should revise regularly rather than wait until the night before the exam.","zh":"學生應定期溫習，而不是等到考試前一晚。"},{"en":"A city should improve public transport rather than simply build more roads.","zh":"城市應改善公共交通，而不是只興建更多道路。"},{"en":"This phrase makes contrast clear by showing what should replace what.","zh":"這個短語透過顯示甚麼應取代甚麼，令對比清楚。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"scattered incentives","meaning":"零散的誘因","examples":[{"en":"Scattered incentives are not enough to encourage electric-car adoption.","zh":"零散的誘因不足以鼓勵採用電動車。"},{"en":"Scattered incentives are separate rewards or supports that are not joined into a clear plan.","zh":"零散的誘因是沒有連成清晰計劃的個別獎勵或支援。"},{"en":"A few coupons in different shops may feel like scattered incentives rather than real help.","zh":"幾間不同商店的一些優惠券，可能像零散的誘因，而不是真正幫助。"},{"en":"Scattered incentives can confuse people because they do not know which support applies.","zh":"零散的誘因可能令人困惑，因為人們不知道哪項支援適用。"},{"en":"A coordinated policy is stronger than scattered incentives that fail to solve the main problem.","zh":"協調政策比無法解決主要問題的零散誘因更有力。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"targeted subsidies","meaning":"針對性資助","examples":[{"en":"The government should offer targeted subsidies for families and commercial drivers.","zh":"政府應為家庭和商用車司機提供針對性資助。"},{"en":"Targeted subsidies are financial support given to specific groups or needs.","zh":"針對性資助是給予特定群體或需要的財政支援。"},{"en":"Targeted subsidies can help low-income students pay for transport to school.","zh":"針對性資助可以幫助低收入學生支付上學交通費。"},{"en":"Targeted subsidies work better when they reach people who face the biggest barriers.","zh":"當針對性資助到達面對最大障礙的人手中時，效果會更好。"},{"en":"Instead of helping everyone equally, targeted subsidies focus money where it is most needed.","zh":"針對性資助不是平均幫助所有人，而是把金錢集中在最需要的地方。"}],"source":"2021 Q2.pdf","sourcePage":12},{"front":"low-interest green loans","meaning":"低息綠色貸款","examples":[{"en":"Low-interest green loans could help families buy electric cars.","zh":"低息綠色貸款可以幫助家庭購買電動車。"},{"en":"Low-interest green loans are loans with cheaper interest rates for environmentally friendly purchases.","zh":"低息綠色貸款是為環保購買提供較低利息的貸款。"},{"en":"A bank may offer low-interest green loans for solar panels or energy-saving home improvements.","zh":"銀行可能為太陽能板或節能家居改善提供低息綠色貸款。"},{"en":"Low-interest green loans reduce monthly payments and make clean choices easier.","zh":"低息綠色貸款降低每月供款，令潔淨選擇更容易。"},{"en":"These loans are useful only if families can clearly understand the repayment terms.","zh":"只有當家庭清楚了解還款條款時，這些貸款才有用。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"commercial drivers","meaning":"商用車司機","examples":[{"en":"Commercial drivers should receive support to switch to electric vehicles.","zh":"商用車司機應獲得支援轉用電動車。"},{"en":"Commercial drivers are people who drive for work, business, or income.","zh":"商用車司機是為工作、業務或收入而駕駛的人。"},{"en":"Taxi drivers, delivery drivers, and bus drivers are examples of commercial drivers.","zh":"的士司機、送貨司機和巴士司機都是商用車司機的例子。"},{"en":"Commercial drivers need reliable vehicles because delays can reduce their earnings.","zh":"商用車司機需要可靠車輛，因為延誤會減少收入。"},{"en":"Supporting commercial drivers can cut pollution quickly because they drive many hours each day.","zh":"支援商用車司機可以快速減少污染，因為他們每天駕駛很多小時。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"replacing older vehicles","meaning":"更換較舊車輛","examples":[{"en":"Subsidies should help drivers who are replacing older vehicles.","zh":"資助應幫助正在更換較舊車輛的駕駛人士。"},{"en":"Replacing older vehicles means changing old cars or vans for newer ones.","zh":"更換較舊車輛是指把舊汽車或客貨車換成較新的車輛。"},{"en":"A company may save fuel by replacing older vehicles with cleaner models.","zh":"公司可以透過以較潔淨車款更換較舊車輛來節省燃料。"},{"en":"Replacing older vehicles can reduce pollution if the old vehicles produce heavy emissions.","zh":"如果舊車排放嚴重，更換較舊車輛可以減少污染。"},{"en":"Financial help matters because replacing older vehicles can be expensive.","zh":"財政幫助很重要，因為更換較舊車輛可能很昂貴。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"more polluting vehicles","meaning":"污染較嚴重的車輛","examples":[{"en":"Older, more polluting vehicles should be replaced first.","zh":"較舊、污染較嚴重的車輛應先被更換。"},{"en":"More polluting vehicles are vehicles that release more harmful emissions than others.","zh":"污染較嚴重的車輛是指比其他車輛排放更多有害物質的車輛。"},{"en":"Old diesel buses may be more polluting vehicles if they produce heavy smoke.","zh":"如果舊柴油巴士產生濃煙，它們可能是污染較嚴重的車輛。"},{"en":"Replacing more polluting vehicles first can improve air quality faster.","zh":"先更換污染較嚴重的車輛，可以更快改善空氣質素。"},{"en":"A fair transport policy should identify which vehicles harm public health most.","zh":"公平的交通政策應找出哪些車輛最傷害公眾健康。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"at the same time","meaning":"與此同時","examples":[{"en":"At the same time, new buildings should include charging-ready parking spaces.","zh":"與此同時，新建築應包括已預留充電設施的車位。"},{"en":"At the same time means while another action or situation is also happening.","zh":"與此同時是指另一個行動或情況也正在發生。"},{"en":"Students can learn grammar and, at the same time, practise speaking.","zh":"學生可以學習文法，與此同時練習說話。"},{"en":"A city can build homes and, at the same time, improve public transport.","zh":"城市可以興建房屋，與此同時改善公共交通。"},{"en":"This phrase helps writers add a related action that should happen together.","zh":"這個短語幫助作者加入應一同發生的相關行動。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"residential and commercial buildings","meaning":"住宅及商業大廈","examples":[{"en":"New residential and commercial buildings should include charging-ready parking spaces.","zh":"新的住宅及商業大廈應包括已預留充電設施的車位。"},{"en":"Residential and commercial buildings are buildings used for homes and for business activities.","zh":"住宅及商業大廈是用作居住和商業活動的建築物。"},{"en":"Flats are residential buildings, while offices and shops are commercial buildings.","zh":"住宅樓宇是住宅大廈，而辦公室和商店是商業大廈。"},{"en":"Charging plans must cover residential and commercial buildings because drivers park in both places.","zh":"充電計劃必須涵蓋住宅及商業大廈，因為駕駛人士會在兩類地方泊車。"},{"en":"Good city planning connects residential and commercial buildings with transport, power, and services.","zh":"良好城市規劃會把住宅及商業大廈與交通、電力和服務連接起來。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"charging-ready parking spaces","meaning":"已預留充電設施的車位","examples":[{"en":"New buildings should include charging-ready parking spaces.","zh":"新建築應包括已預留充電設施的車位。"},{"en":"Charging-ready parking spaces are parking spaces already prepared for future electric-car charging.","zh":"已預留充電設施的車位是已為日後電動車充電作準備的泊車位。"},{"en":"A new estate may install cables early so spaces become charging-ready parking spaces.","zh":"新屋苑可能提早安裝電纜，使車位成為已預留充電設施的車位。"},{"en":"Charging-ready parking spaces reduce future costs because buildings do not need major changes later.","zh":"已預留充電設施的車位減少未來成本，因為建築日後不需要大改動。"},{"en":"They make electric-car adoption easier for residents who cannot install chargers alone.","zh":"它們令無法獨自安裝充電器的居民更容易採用電動車。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"older estates","meaning":"較舊屋苑","examples":[{"en":"Older estates should receive support to upgrade their electrical systems.","zh":"較舊屋苑應獲得支援以升級其電力系統。"},{"en":"Older estates are housing estates built many years ago, often with older facilities.","zh":"較舊屋苑是多年前興建、通常設施較舊的屋苑。"},{"en":"Older estates may have narrow car parks and limited power capacity.","zh":"較舊屋苑可能有狹窄停車場和有限電力容量。"},{"en":"Upgrading older estates can be difficult because residents, owners, and managers must agree.","zh":"升級較舊屋苑可能困難，因為居民、業主和管理者必須達成共識。"},{"en":"Support for older estates helps make green transport fairer for long-time residents.","zh":"支援較舊屋苑有助令綠色交通對長期居民更公平。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"receive support to","meaning":"獲得支援去……","examples":[{"en":"Older estates should receive support to upgrade their electrical systems.","zh":"較舊屋苑應獲得支援去升級其電力系統。"},{"en":"Receive support to do something means get help, money, advice, or resources for that action.","zh":"獲得支援去做某事，是指為該行動得到幫助、金錢、建議或資源。"},{"en":"Students may receive support to improve reading through extra lessons.","zh":"學生可能透過額外課堂獲得支援去改善閱讀。"},{"en":"Small shops can receive support to install digital payment systems.","zh":"小店可以獲得支援去安裝電子付款系統。"},{"en":"People are more likely to make changes when they receive support to do them properly.","zh":"當人們獲得支援去正確完成改變時，他們更可能行動。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"upgrade their electrical systems","meaning":"升級電力系統","examples":[{"en":"Older estates should upgrade their electrical systems.","zh":"較舊屋苑應升級其電力系統。"},{"en":"To upgrade their electrical systems means to improve the wires, power supply, and related equipment.","zh":"升級電力系統是指改善電線、電力供應和相關設備。"},{"en":"A school may upgrade its electrical systems before installing many new computers.","zh":"學校在安裝大量新電腦前，可能需要升級電力系統。"},{"en":"Buildings must upgrade their electrical systems if old wiring cannot handle extra demand.","zh":"如果舊電線無法承受額外需求，建築物必須升級電力系統。"},{"en":"Upgraded electrical systems make charging safer and more reliable.","zh":"升級後的電力系統令充電更安全可靠。"}],"source":"2021 Q2.pdf","sourcePage":13},{"front":"shopping centres","meaning":"商場","examples":[{"en":"Shopping centres should install more fast chargers.","zh":"商場應安裝更多快速充電器。"},{"en":"Shopping centres are large places with many shops, restaurants, and services.","zh":"商場是有許多商店、餐廳和服務的大型地方。"},{"en":"Families often park at shopping centres while buying groceries or eating out.","zh":"家庭買日用品或外出用餐時，常在商場泊車。"},{"en":"Fast chargers in shopping centres let drivers charge during normal errands.","zh":"商場內的快速充電器讓駕駛人士在日常辦事期間充電。"},{"en":"Shopping centres are useful charging locations because many drivers already visit them.","zh":"商場是有用的充電地點，因為許多駕駛人士本來就會到訪。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"government car parks","meaning":"政府停車場","examples":[{"en":"Government car parks should install more fast chargers.","zh":"政府停車場應安裝更多快速充電器。"},{"en":"Government car parks are parking facilities owned or managed by public authorities.","zh":"政府停車場是由公共機關擁有或管理的泊車設施。"},{"en":"Drivers may use government car parks near offices, markets, hospitals, and public buildings.","zh":"駕駛人士可能使用辦公室、街市、醫院和公共建築附近的政府停車場。"},{"en":"Installing chargers in government car parks can show public commitment to clean transport.","zh":"在政府停車場安裝充電器，可以顯示公共部門對潔淨交通的承諾。"},{"en":"Government car parks can serve drivers who do not have private charging spaces.","zh":"政府停車場可以服務沒有私人充電空間的駕駛人士。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"transport interchanges","meaning":"交通交匯處","examples":[{"en":"Transport interchanges should install more fast chargers.","zh":"交通交匯處應安裝更多快速充電器。"},{"en":"Transport interchanges are places where people change between buses, trains, taxis, or other transport.","zh":"交通交匯處是人們在巴士、火車、的士或其他交通工具之間轉乘的地方。"},{"en":"A busy transport interchange may connect a railway station with bus and minibus routes.","zh":"繁忙的交通交匯處可能把鐵路站與巴士和小巴路線連接起來。"},{"en":"Fast chargers at transport interchanges help commercial drivers charge between trips.","zh":"交通交匯處的快速充電器幫助商用車司機在行程之間充電。"},{"en":"Transport interchanges are practical charging sites because vehicles already stop there.","zh":"交通交匯處是實用的充電地點，因為車輛本來就會停在那裡。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"fast chargers","meaning":"快速充電器","examples":[{"en":"More fast chargers should be installed in public places.","zh":"公共地方應安裝更多快速充電器。"},{"en":"Fast chargers are chargers that fill an electric-vehicle battery more quickly than ordinary chargers.","zh":"快速充電器是比普通充電器更快為電動車電池充電的充電器。"},{"en":"A fast charger at a service station can help drivers continue a long trip sooner.","zh":"服務站的快速充電器可以幫助駕駛人士更快繼續長途旅程。"},{"en":"Fast chargers reduce waiting time, especially for taxis and delivery vehicles.","zh":"快速充電器減少等待時間，尤其對的士和送貨車輛有用。"},{"en":"Drivers trust electric transport more when fast chargers are common and reliable.","zh":"當快速充電器普遍又可靠時，駕駛人士會更信任電動交通。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"top up","meaning":"補充電量","examples":[{"en":"Drivers should be able to top up during ordinary activities.","zh":"駕駛人士應能在日常活動期間補充電量。"},{"en":"To top up means to add more of something before it runs out completely.","zh":"補充是指在某物完全用完前再加入更多。"},{"en":"A student may top up an Octopus card before taking the train.","zh":"學生乘火車前可能會為八達通增值。"},{"en":"Drivers can top up their battery while shopping, eating, or attending a meeting.","zh":"駕駛人士可以在購物、吃飯或開會時補充電池電量。"},{"en":"Easy top-ups make charging feel like part of daily life, not a separate burden.","zh":"容易補充電量會令充電感覺像日常生活的一部分，而不是額外負擔。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"ordinary activities","meaning":"日常活動","examples":[{"en":"Drivers could charge their cars during ordinary activities.","zh":"駕駛人士可以在日常活動期間為汽車充電。"},{"en":"Ordinary activities are normal things people do in daily life.","zh":"日常活動是人們日常生活中做的普通事情。"},{"en":"Buying food, going to work, exercising, and visiting family are ordinary activities.","zh":"買食物、上班、運動和探望家人都是日常活動。"},{"en":"Charging during ordinary activities saves time because drivers do not need a special trip.","zh":"在日常活動期間充電可以節省時間，因為駕駛人士不需要特意走一趟。"},{"en":"Green transport becomes easier when it fits ordinary activities.","zh":"當綠色交通配合日常活動時，它會變得更容易。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"better still","meaning":"更理想的是","examples":[{"en":"Better still, taxis and delivery fleets should be encouraged to switch first.","zh":"更理想的是，的士和送貨車隊應獲鼓勵率先轉用。"},{"en":"Better still introduces an even better idea than the one just mentioned.","zh":"更理想的是，用來引出比剛才提到的想法更好的建議。"},{"en":"Students should read more examples; better still, they should write their own sentences.","zh":"學生應閱讀更多例句；更理想的是，他們應自己寫句子。"},{"en":"A shop can reduce plastic bags; better still, it can reward customers who bring reusable bags.","zh":"商店可以減少膠袋；更理想的是，它可以獎勵自備可重用袋的顧客。"},{"en":"Writers use better still when they want to move from a good suggestion to a stronger one.","zh":"當作者想從好建議推進到更強建議時，會使用「更理想的是」。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"delivery fleets","meaning":"送貨車隊","examples":[{"en":"Delivery fleets should be encouraged to switch to electric vehicles.","zh":"送貨車隊應獲鼓勵轉用電動車。"},{"en":"Delivery fleets are groups of vehicles used by companies to deliver goods.","zh":"送貨車隊是公司用來運送貨物的一組車輛。"},{"en":"Supermarkets use delivery fleets to bring groceries to customers’ homes.","zh":"超級市場使用送貨車隊把雜貨送到顧客家中。"},{"en":"Electric delivery fleets can reduce pollution because they drive many routes every day.","zh":"電動送貨車隊可以減少污染，因為它們每天行走很多路線。"},{"en":"Companies will switch delivery fleets only when charging and repair support are reliable.","zh":"只有當充電和維修支援可靠時，公司才會轉用送貨車隊。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"be encouraged to switch first","meaning":"獲鼓勵率先轉用","examples":[{"en":"Taxis and delivery fleets should be encouraged to switch first.","zh":"的士和送貨車隊應獲鼓勵率先轉用。"},{"en":"To be encouraged to switch first means to receive support or pressure to change before others do.","zh":"獲鼓勵率先轉用，是指得到支援或推動，比其他人更早改變。"},{"en":"Large schools may be encouraged to switch first to digital notices because they use much paper.","zh":"大型學校可能獲鼓勵率先轉用電子通告，因為它們使用大量紙張。"},{"en":"Buses may be encouraged to switch first because they affect many passengers and roads.","zh":"巴士可能獲鼓勵率先轉用，因為它們影響許多乘客和道路。"},{"en":"Choosing who should switch first helps a policy create visible results quickly.","zh":"選擇誰應率先轉用，能幫助政策快速產生可見成果。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"visible commercial vehicles","meaning":"常見的商用車輛","examples":[{"en":"Visible commercial vehicles can prove that electric transport works.","zh":"常見的商用車輛可以證明電動交通行得通。"},{"en":"Visible commercial vehicles are work vehicles that the public often sees on roads.","zh":"常見的商用車輛是公眾經常在路上看見的工作車輛。"},{"en":"Taxis, buses, and delivery vans are visible commercial vehicles in daily city life.","zh":"的士、巴士和送貨客貨車都是日常城市生活中常見的商用車輛。"},{"en":"When visible commercial vehicles become electric, people see the technology working under pressure.","zh":"當常見的商用車輛變成電動車，人們會看見技術在壓力下運作。"},{"en":"Public examples matter because visible commercial vehicles shape everyday opinions.","zh":"公開例子很重要，因為常見的商用車輛會塑造日常意見。"}],"source":"2021 Q2.pdf","sourcePage":14},{"front":"prove that","meaning":"證明","examples":[{"en":"Commercial vehicles can prove that electric transport works under pressure.","zh":"商用車輛可以證明電動交通在壓力下仍能運作。"},{"en":"Prove that means show clearly that something is true.","zh":"證明是指清楚顯示某事是真實的。"},{"en":"A successful trial can prove that a new bus route is useful.","zh":"成功的試行可以證明新巴士路線有用。"},{"en":"Clean taxis on busy roads can prove that electric vehicles are practical.","zh":"在繁忙道路上的潔淨的士可以證明電動車是實際可行的。"},{"en":"Evidence proves more than promises when people doubt a new technology.","zh":"當人們懷疑新技術時，證據比承諾更能證明。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"electric transport","meaning":"電動交通","examples":[{"en":"Electric transport can work under pressure.","zh":"電動交通可以在壓力下運作。"},{"en":"Electric transport means transport systems or vehicles powered by electricity.","zh":"電動交通是指由電力驅動的交通系統或車輛。"},{"en":"Electric transport can include electric buses, taxis, vans, trains, and private cars.","zh":"電動交通可以包括電動巴士、的士、客貨車、火車和私家車。"},{"en":"Electric transport reduces roadside emissions when it replaces heavily used petrol or diesel vehicles.","zh":"當電動交通取代使用量高的汽油或柴油車輛時，可以減少路邊排放。"},{"en":"Electric transport needs reliable power, charging networks, and public trust.","zh":"電動交通需要可靠電力、充電網絡和公眾信任。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"work under pressure","meaning":"在壓力下仍能運作","examples":[{"en":"Commercial electric vehicles can prove that the technology works under pressure.","zh":"商用電動車可以證明這項技術在壓力下仍能運作。"},{"en":"Work under pressure means continue to perform well when demands are high.","zh":"在壓力下仍能運作，是指在高要求情況下繼續有良好表現。"},{"en":"A nurse must work under pressure during a busy emergency shift.","zh":"護士在繁忙急症輪班期間必須在壓力下工作。"},{"en":"A delivery system works under pressure if it remains reliable during holidays.","zh":"如果送貨系統在假期仍可靠，它就是在壓力下仍能運作。"},{"en":"Technology gains trust when it works under pressure, not only in easy tests.","zh":"技術在壓力下仍能運作，而不只是在簡單測試中成功時，才會獲得信任。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"in conclusion","meaning":"總括而言","examples":[{"en":"In conclusion, low electric-car sales do not prove that people reject green living.","zh":"總括而言，電動車銷量低並不證明人們拒絕環保生活。"},{"en":"In conclusion introduces the final summary or judgement of a piece of writing.","zh":"總括而言用來引出文章的最後總結或判斷。"},{"en":"In conclusion, schools should teach both knowledge and kindness.","zh":"總括而言，學校應同時教授知識和善良。"},{"en":"In conclusion, a city needs clean transport that ordinary people can actually use.","zh":"總括而言，城市需要普通人真正能使用的潔淨交通。"},{"en":"This phrase signals that the writer is bringing the argument to an end.","zh":"這個短語表示作者正在把論點帶到結尾。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"low sales","meaning":"銷量低","examples":[{"en":"The low sales of electric vehicles do not prove that people reject green living.","zh":"電動車銷量低並不證明人們拒絕環保生活。"},{"en":"Low sales means a small number of products are bought.","zh":"銷量低是指產品被購買的數量少。"},{"en":"A shop may have low sales if its prices are high and few customers visit.","zh":"如果價格高而顧客少，商店可能銷量低。"},{"en":"Low sales can show weak demand, but they can also show practical barriers.","zh":"銷量低可以顯示需求弱，但也可以顯示實際障礙。"},{"en":"Before blaming customers for low sales, businesses should ask what makes buying difficult.","zh":"在因銷量低而責怪顧客前，企業應先問甚麼令購買變得困難。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"prove that","meaning":"證明","examples":[{"en":"Low sales do not prove that people reject green living.","zh":"銷量低並不證明人們拒絕環保生活。"},{"en":"Prove that means provide enough evidence to show that something is true.","zh":"證明是指提供足夠證據來顯示某事是真實的。"},{"en":"One bad test result does not prove that a student is lazy.","zh":"一次測驗成績差並不證明學生懶惰。"},{"en":"A small number of complaints does not always prove that a service is failing.","zh":"少量投訴不一定證明服務正在失敗。"},{"en":"Writers use prove that carefully because evidence may have more than one explanation.","zh":"作者應小心使用「證明」，因為證據可能有多於一種解釋。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"reject green living","meaning":"拒絕環保生活","examples":[{"en":"People do not necessarily reject green living.","zh":"人們不一定拒絕環保生活。"},{"en":"To reject green living means to refuse environmentally friendly habits or choices.","zh":"拒絕環保生活是指拒絕環保的習慣或選擇。"},{"en":"A person may care about nature but reject green living if the options are too expensive.","zh":"一個人可能關心自然，但如果選項太昂貴，仍可能拒絕環保生活。"},{"en":"Low use of recycling bins does not always mean people reject green living; the bins may be hard to find.","zh":"回收箱使用率低不一定代表人們拒絕環保生活；回收箱可能很難找到。"},{"en":"People are less likely to reject green living when it is simple and affordable.","zh":"當環保生活簡單又負擔得起時，人們較不會拒絕它。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"quite the contrary","meaning":"正好相反","examples":[{"en":"Quite the contrary, low sales show that good intentions are not enough.","zh":"正好相反，低銷量顯示良好意願並不足夠。"},{"en":"Quite the contrary means the opposite is true.","zh":"正好相反意思是事實剛好相反。"},{"en":"Some people think exercise wastes time; quite the contrary, it can improve energy and focus.","zh":"有些人認為運動浪費時間；正好相反，它可以改善精力和專注。"},{"en":"Low attendance does not mean students dislike learning; quite the contrary, the schedule may be unsuitable.","zh":"出席率低不代表學生不喜歡學習；正好相反，時間表可能不合適。"},{"en":"This phrase strongly corrects a mistaken idea.","zh":"這個短語有力地修正錯誤想法。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"good intentions","meaning":"良好意願","examples":[{"en":"Good intentions are not enough by themselves.","zh":"單靠良好意願本身是不夠的。"},{"en":"Good intentions are kind or positive aims behind an action.","zh":"良好意願是行動背後善意或正面的目的。"},{"en":"A student may have good intentions when helping a friend, even if the advice is wrong.","zh":"學生幫朋友時可能有良好意願，即使建議是錯的。"},{"en":"Good intentions can fail if they are not supported by planning and resources.","zh":"如果沒有計劃和資源支持，良好意願可能失敗。"},{"en":"Policies need practical design because good intentions alone do not solve problems.","zh":"政策需要實際設計，因為單靠良好意願不能解決問題。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"by themselves","meaning":"單靠本身","examples":[{"en":"Good intentions are not enough by themselves.","zh":"良好意願單靠本身是不足夠的。"},{"en":"By themselves means alone, without extra help or support.","zh":"單靠本身是指獨自地、沒有額外幫助或支援。"},{"en":"Rules by themselves cannot stop bullying if teachers never enforce them.","zh":"如果老師從不執行規則，規則單靠本身不能阻止欺凌。"},{"en":"Posters by themselves may not change habits unless people also get convenient choices.","zh":"如果人們沒有方便選擇，海報單靠本身可能無法改變習慣。"},{"en":"This phrase shows that something needs support from other actions.","zh":"這個短語顯示某事需要其他行動支持。"}],"source":"2021 Q2.pdf","sourcePage":15},{"front":"become common","meaning":"變得普遍","examples":[{"en":"Electric cars must become affordable and convenient if they are to become common.","zh":"如果電動車要變得普遍，就必須買得起又充電方便。"},{"en":"Become common means be used, seen, or accepted by many people.","zh":"變得普遍是指被許多人使用、看見或接受。"},{"en":"Online meetings became common when many workers started working from home.","zh":"當許多工人開始在家工作時，網上會議變得普遍。"},{"en":"A new habit becomes common when it is easy to repeat every day.","zh":"當一個新習慣容易每天重複時，它會變得普遍。"},{"en":"Electric cars will become common only when ordinary drivers can use them without worry.","zh":"只有當普通駕駛人士能無憂使用時，電動車才會變得普遍。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"affordable to buy","meaning":"買得起","examples":[{"en":"Electric cars must be affordable to buy.","zh":"電動車必須買得起。"},{"en":"Affordable to buy means cheap enough for people to purchase without serious financial pressure.","zh":"買得起是指價格低到人們可以購買，而不會造成嚴重財務壓力。"},{"en":"School uniforms should be affordable to buy so families are not overburdened.","zh":"校服應該買得起，讓家庭不會負擔過重。"},{"en":"A product may be attractive but fail if it is not affordable to buy.","zh":"一件產品可能吸引，但如果買不起就會失敗。"},{"en":"Subsidies can make clean technology more affordable to buy for ordinary households.","zh":"資助可以令潔淨科技對普通家庭更買得起。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"convenient to charge","meaning":"充電方便","examples":[{"en":"Electric cars must be convenient to charge.","zh":"電動車必須充電方便。"},{"en":"Convenient to charge means easy to power up without wasting much time or effort.","zh":"充電方便是指容易補充電力，而不浪費太多時間或力氣。"},{"en":"A phone is convenient to charge when sockets and cables are easy to find.","zh":"當插座和電線容易找到時，手機就充電方便。"},{"en":"Electric cars are convenient to charge when drivers can charge at home, work, or public places.","zh":"當駕駛人士能在家、工作地點或公共地方充電時，電動車就充電方便。"},{"en":"If a vehicle is not convenient to charge, drivers may not trust it for daily use.","zh":"如果車輛充電不方便，駕駛人士可能不信任它作日常使用。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"trustworthy to own","meaning":"擁有起來令人放心","examples":[{"en":"Electric cars must be trustworthy to own.","zh":"電動車必須擁有起來令人放心。"},{"en":"Trustworthy to own means safe and reliable enough for people to depend on after buying.","zh":"擁有起來令人放心，是指購買後足夠安全可靠，可以依賴。"},{"en":"A washing machine is trustworthy to own if it rarely breaks and repairs are easy.","zh":"如果洗衣機很少故障且容易維修，它就擁有起來令人放心。"},{"en":"Cars become trustworthy to own when warranties, parts, and service are clear.","zh":"當保養、零件和服務清晰時，汽車會變得擁有起來令人放心。"},{"en":"People buy expensive products only when they feel they are trustworthy to own.","zh":"人們只有在覺得昂貴產品擁有起來令人放心時，才會購買。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"act together","meaning":"共同採取行動","examples":[{"en":"The government, developers, car dealers and power companies should act together.","zh":"政府、發展商、車行和電力公司應共同採取行動。"},{"en":"To act together means different people or groups cooperate instead of working separately.","zh":"共同採取行動是指不同人士或群體合作，而不是各自工作。"},{"en":"Teachers and parents should act together when a child needs extra support.","zh":"當孩子需要額外支援時，老師和家長應共同採取行動。"},{"en":"A city can reduce waste faster when shops, schools, and households act together.","zh":"當商店、學校和家庭共同採取行動時，城市可以更快減少浪費。"},{"en":"Large problems need groups to act together because one group cannot solve everything alone.","zh":"大問題需要各方共同採取行動，因為單一群體不能獨自解決所有事情。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"power companies","meaning":"電力公司","examples":[{"en":"Power companies should help make electric cars easier to use.","zh":"電力公司應幫助令電動車更容易使用。"},{"en":"Power companies are businesses that produce, supply, or manage electricity.","zh":"電力公司是生產、供應或管理電力的企業。"},{"en":"Power companies maintain the systems that bring electricity to homes and buildings.","zh":"電力公司維護把電力送到住宅和建築物的系統。"},{"en":"Electric-car charging depends on power companies because chargers need stable electricity.","zh":"電動車充電依賴電力公司，因為充電器需要穩定電力。"},{"en":"Power companies can support cleaner transport by improving supply and charging connections.","zh":"電力公司可以透過改善供電和充電連接來支持較潔淨交通。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"the future of clean transport","meaning":"清潔交通的未來","examples":[{"en":"The future of clean transport depends on making green choices easier.","zh":"清潔交通的未來取決於令綠色選擇更容易。"},{"en":"The future of clean transport means how low-pollution travel and delivery will develop in the years ahead.","zh":"清潔交通的未來是指低污染出行和運輸在未來幾年會如何發展。"},{"en":"Electric buses, safe cycling routes, and reliable trains all shape the future of clean transport.","zh":"電動巴士、安全單車徑和可靠火車都塑造清潔交通的未來。"},{"en":"The future of clean transport will fail if cleaner choices remain expensive and inconvenient.","zh":"如果較潔淨選擇仍然昂貴又不方便，清潔交通的未來會失敗。"},{"en":"A city protects the future of clean transport by planning for ordinary daily users.","zh":"城市透過為普通日常用戶規劃，保護清潔交通的未來。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"choosing the greener car","meaning":"選擇較環保的車","examples":[{"en":"Choosing the greener car should also become the easier choice.","zh":"選擇較環保的車也應成為較容易的選擇。"},{"en":"Choosing the greener car means selecting the vehicle that causes less environmental harm.","zh":"選擇較環保的車是指選擇對環境造成較少傷害的車輛。"},{"en":"A family may want to choose the greener car if it saves fuel and reduces emissions.","zh":"如果較環保的車能節省燃料並減少排放，家庭可能想選擇它。"},{"en":"Choosing the greener car becomes difficult when charging spaces are limited.","zh":"當充電空間有限時，選擇較環保的車會變得困難。"},{"en":"People are more likely to choose the greener car when it is also affordable and convenient.","zh":"當較環保的車同時負擔得起又方便時，人們更可能選擇它。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"the easier choice","meaning":"較容易的選擇","examples":[{"en":"The greener car must also become the easier choice.","zh":"較環保的車也必須成為較容易的選擇。"},{"en":"The easier choice is the option that takes less effort, time, worry, or money.","zh":"較容易的選擇是需要較少力氣、時間、憂慮或金錢的選項。"},{"en":"Recycling becomes the easier choice when bins are clearly marked and nearby.","zh":"當回收箱標示清楚又在附近時，回收會成為較容易的選擇。"},{"en":"Public transport becomes the easier choice when it is cheaper than parking and faster than driving.","zh":"當公共交通比泊車便宜又比駕車快時，它會成為較容易的選擇。"},{"en":"People often follow the easier choice, so good policy should make the better option easier.","zh":"人們常跟隨較容易的選擇，所以好政策應令較好的選項更容易。"}],"source":"2021 Q2.pdf","sourcePage":16},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"The letter ends with Yours faithfully.","zh":"這封信以「謹啟」結尾。"},{"en":"Yours faithfully is a formal closing used at the end of a letter when the writer does not know the recipient personally.","zh":"「謹啟」是正式信件結尾使用的禮貌結語，通常用於作者不熟悉收信人的情況。"},{"en":"A student may write Yours faithfully at the end of a letter to a newspaper editor.","zh":"學生在寫給報章編輯的信末，可能會寫「謹啟」。"},{"en":"In formal letters, Yours faithfully shows respect and completes the polite structure.","zh":"在正式信件中，「謹啟」表示尊重，並完成禮貌的信件結構。"},{"en":"It is more suitable for public or official letters than casual messages to friends.","zh":"它比寫給朋友的隨意訊息更適合用於公開或正式信件。"}],"source":"2021 Q2.pdf","sourcePage":16}],"dse/writing/part-b/2021/Q3":[{"front":"Sales Manager","meaning":"銷售經理","examples":[{"en":"Ms Lin is the Sales Manager at Fast Fashion.","zh":"林女士是 Fast Fashion 的銷售經理。"},{"en":"A Sales Manager is a person who leads the sales team and helps the company sell more products.","zh":"銷售經理是領導銷售團隊並幫助公司銷售更多產品的人。"},{"en":"A Sales Manager may train staff to speak politely to customers.","zh":"銷售經理可能會培訓員工有禮貌地與顧客交談。"},{"en":"If sales fall, the Sales Manager must find out what customers are unhappy about.","zh":"如果銷售下跌，銷售經理必須找出顧客不滿的原因。"},{"en":"A good Sales Manager balances company profit with customer trust.","zh":"好的銷售經理會在公司利潤和顧客信任之間取得平衡。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"Sales Department","meaning":"銷售部","examples":[{"en":"Chris Wong works in the Sales Department.","zh":"Chris Wong 在銷售部工作。"},{"en":"The Sales Department is the part of a company that deals with selling products and serving buyers.","zh":"銷售部是公司中負責銷售產品和服務買家的部門。"},{"en":"Staff in the Sales Department often hear customer complaints first.","zh":"銷售部員工通常最先聽到顧客投訴。"},{"en":"If a returns policy is unfair, the Sales Department may lose repeat customers.","zh":"如果退貨政策不公平，銷售部可能會失去回頭客。"},{"en":"The Sales Department can give useful advice because it speaks to customers every day.","zh":"銷售部每天與顧客交談，因此可以提供有用建議。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"returns policy","meaning":"退貨政策","examples":[{"en":"Fast Fashion needs a fairer returns policy.","zh":"Fast Fashion 需要一個更公平的退貨政策。"},{"en":"A returns policy tells customers when they can return, exchange, or get money back for an item.","zh":"退貨政策告訴顧客在甚麼情況下可以退貨、換貨或退款。"},{"en":"An online shop should explain its returns policy before customers pay.","zh":"網店應在顧客付款前解釋其退貨政策。"},{"en":"A strict returns policy can reduce costs but may also increase complaints.","zh":"嚴格的退貨政策可以減少成本，但也可能增加投訴。"},{"en":"A fair returns policy helps customers feel safer when buying online.","zh":"公平的退貨政策令顧客網購時感到更安心。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"protect customers and the business","meaning":"保障顧客及業務","examples":[{"en":"A fairer returns policy can protect customers and the business.","zh":"更公平的退貨政策可以保障顧客及業務。"},{"en":"To protect customers and the business means to help buyers fairly while also avoiding losses for the company.","zh":"保障顧客及業務意思是公平地幫助買家，同時避免公司蒙受損失。"},{"en":"Clear rules protect customers and the business by reducing arguments.","zh":"清晰規則透過減少爭拗來保障顧客及業務。"},{"en":"If staff check returned items carefully, they can protect customers and the business.","zh":"如果員工仔細檢查退回貨品，他們可以保障顧客及業務。"},{"en":"A good policy should not favour only customers or only the company.","zh":"好政策不應只偏向顧客或只偏向公司。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"following the recent rise in","meaning":"鑑於最近……增加","examples":[{"en":"Following the recent rise in customer complaints, Chris recommends a policy revision.","zh":"鑑於最近顧客投訴增加，Chris 建議修訂政策。"},{"en":"“Following the recent rise in” means after something has increased recently.","zh":"“following the recent rise in” 指某事最近增加之後。"},{"en":"Following the recent rise in delivery problems, the shop hired more customer service staff.","zh":"鑑於最近送貨問題增加，商店聘請了更多客戶服務員工。"},{"en":"Following the recent rise in returns, managers checked whether the size guide was accurate.","zh":"鑑於最近退貨增加，管理層檢查尺碼指南是否準確。"},{"en":"This phrase is useful when explaining why action is needed now.","zh":"這個片語適合用來解釋為何現在需要採取行動。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"customer complaints","meaning":"顧客投訴","examples":[{"en":"Customer complaints about the policy have recently increased.","zh":"關於該政策的顧客投訴最近有所增加。"},{"en":"Customer complaints are messages from buyers who are unhappy with a product or service.","zh":"顧客投訴是買家對產品或服務不滿時發出的訊息。"},{"en":"A customer complaint may be about late delivery, wrong colour, or poor quality.","zh":"顧客投訴可能關於送貨遲、顏色錯誤或品質差。"},{"en":"If customer complaints keep rising, the company may lose trust.","zh":"如果顧客投訴持續上升，公司可能會失去信任。"},{"en":"Serious customer complaints should be recorded and reviewed by managers.","zh":"嚴重的顧客投訴應被記錄並由管理層檢視。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"no-exchange, no-refund policy","meaning":"不設換貨、不設退款政策","examples":[{"en":"The company currently has a no-exchange, no-refund policy.","zh":"公司目前實行不設換貨、不設退款政策。"},{"en":"A no-exchange, no-refund policy means customers cannot change an item or get their money back.","zh":"不設換貨、不設退款政策意思是顧客不能換貨或取回款項。"},{"en":"A shop may use a no-exchange, no-refund policy for final-sale items.","zh":"商店可能對清貨貨品使用不設換貨、不設退款政策。"},{"en":"If the policy is too strict, genuine customers may feel treated unfairly.","zh":"如果政策過於嚴格，真正有需要的顧客可能覺得受到不公平對待。"},{"en":"This policy saves handling work but can damage customer confidence.","zh":"這項政策可節省處理工作，但可能損害顧客信心。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"as a member of","meaning":"作為……的一員","examples":[{"en":"Chris is writing as a member of the sales department.","zh":"Chris 作為銷售部的一員寫這封信。"},{"en":"“As a member of” means speaking from the position of belonging to a group.","zh":"“as a member of” 指以某個群體成員的身份發言。"},{"en":"As a member of the school council, she suggested longer library hours.","zh":"作為學生會的一員，她建議延長圖書館開放時間。"},{"en":"As a member of the sales team, Chris understands customers’ daily problems.","zh":"作為銷售團隊的一員，Chris 了解顧客的日常問題。"},{"en":"This phrase helps show why the writer has a reason to give advice.","zh":"這個片語有助說明作者為何有理由提出建議。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"recommend a revision","meaning":"建議作出修訂","examples":[{"en":"Chris writes to recommend a carefully controlled revision.","zh":"Chris 寫信建議作出經過嚴格控制的修訂。"},{"en":"To recommend a revision means to suggest changing something after reviewing its problems.","zh":"建議作出修訂意思是在檢視問題後提出修改某事。"},{"en":"A teacher may recommend a revision to school rules if many students are confused.","zh":"如果許多學生感到混亂，老師可能建議修訂校規。"},{"en":"Customer complaints can lead staff to recommend a revision of company policy.","zh":"顧客投訴可能令員工建議修訂公司政策。"},{"en":"A revision should improve the rule without creating new problems.","zh":"修訂應改善規則，而不是製造新問題。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"carefully controlled revision","meaning":"經過嚴格控制的修訂","examples":[{"en":"A carefully controlled revision could reduce complaints without inviting abuse.","zh":"經過嚴格控制的修訂可以減少投訴，而不會引來濫用。"},{"en":"A carefully controlled revision is a change with clear limits and safeguards.","zh":"經過嚴格控制的修訂是有清晰限制和防範措施的改變。"},{"en":"A shop may allow exchanges only within fourteen days as a carefully controlled revision.","zh":"商店只准十四日內換貨，這可以是經過嚴格控制的修訂。"},{"en":"This kind of revision can help customers while preventing misuse.","zh":"這種修訂可以幫助顧客，同時防止濫用。"},{"en":"It is different from a completely open refund policy.","zh":"它不同於完全開放的退款政策。"}],"source":"2021 Q3.pdf","sourcePage":1},{"front":"the aim is not to…, but to…","meaning":"目的不是……，而是……","examples":[{"en":"The aim is not to sacrifice profit, but to reduce frustration.","zh":"目的不是犧牲利潤，而是減少不滿。"},{"en":"This structure shows contrast between what the goal is not and what the real goal is.","zh":"這個句式顯示不是某個目標，而真正目標是另一件事。"},{"en":"The aim is not to blame staff, but to improve the system.","zh":"目的不是責怪員工，而是改善制度。"},{"en":"The aim is not to give free returns to everyone, but to help fair cases.","zh":"目的不是讓所有人免費退貨，而是幫助合理個案。"},{"en":"This phrase makes a proposal sound balanced and reasonable.","zh":"這個片語令建議聽起來平衡而合理。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"sacrifice profit","meaning":"犧牲利潤","examples":[{"en":"The aim is not to sacrifice profit unnecessarily.","zh":"目的不是不必要地犧牲利潤。"},{"en":"To sacrifice profit means to accept earning less money in order to achieve another purpose.","zh":"犧牲利潤意思是為了達到另一目的而接受賺少一些錢。"},{"en":"A company may sacrifice profit for a short time to keep loyal customers.","zh":"公司可能短期犧牲利潤，以留住忠誠顧客。"},{"en":"If refunds are uncontrolled, the business may sacrifice profit without gaining trust.","zh":"如果退款不受控制，企業可能犧牲利潤卻得不到信任。"},{"en":"Managers should help customers fairly without sacrificing profit too much.","zh":"管理層應公平幫助顧客，而不要過度犧牲利潤。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"reduce frustration","meaning":"減少不滿","examples":[{"en":"The revised policy could reduce frustration among customers.","zh":"經修訂的政策可以減少顧客的不滿。"},{"en":"To reduce frustration means to make people feel less annoyed or helpless.","zh":"減少不滿意思是令人少一點惱怒或無助。"},{"en":"Clear return steps can reduce frustration because customers know what to do.","zh":"清晰的退貨步驟可以減少不滿，因為顧客知道該怎樣做。"},{"en":"If staff cannot help fair cases, frustration may increase.","zh":"如果員工不能幫助合理個案，不滿可能增加。"},{"en":"A simple explanation often reduces frustration more than a long argument.","zh":"簡單解釋往往比長時間爭論更能減少不滿。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"rebuild confidence","meaning":"重建信心","examples":[{"en":"A fairer policy may help rebuild customer confidence.","zh":"更公平的政策可能有助重建顧客信心。"},{"en":"To rebuild confidence means to help people trust something again after disappointment.","zh":"重建信心意思是在失望後幫助人重新信任某事。"},{"en":"A school can rebuild confidence after a mistake by apologising and changing its rules.","zh":"學校犯錯後，可以透過道歉和修改規則來重建信心。"},{"en":"Fast refunds for defective goods can rebuild confidence in an online shop.","zh":"對有瑕疵貨品快速退款可以重建顧客對網店的信心。"},{"en":"Confidence is rebuilt slowly through fair action, not promises alone.","zh":"信心是透過公平行動慢慢重建的，不只是靠承諾。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"protect repeat business","meaning":"保住回頭客生意","examples":[{"en":"The company should protect repeat business by treating customers fairly.","zh":"公司應透過公平對待顧客來保住回頭客生意。"},{"en":"To protect repeat business means to keep customers willing to buy again.","zh":"保住回頭客生意意思是令顧客願意再次購買。"},{"en":"Good service can protect repeat business even when a mistake happens.","zh":"即使出現錯誤，良好服務也可以保住回頭客生意。"},{"en":"An unfair policy may damage repeat business because customers choose another shop.","zh":"不公平政策可能損害回頭客生意，因為顧客會選擇其他商店。"},{"en":"Online stores protect repeat business by solving problems quickly.","zh":"網店透過快速解決問題來保住回頭客生意。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"in my view","meaning":"在我看來","examples":[{"en":"In my view, the current policy should be changed.","zh":"在我看來，現行政策應該改變。"},{"en":"“In my view” means “in my opinion” and is used before giving a personal judgement.","zh":"“in my view” 意思是「在我看來」，用於提出個人判斷前。"},{"en":"In my view, schools should teach students how to manage money.","zh":"在我看來，學校應教學生如何理財。"},{"en":"In my view, a policy is stronger when it is both fair and clear.","zh":"在我看來，政策若既公平又清晰，會更有力。"},{"en":"This phrase is polite because it shows the writer is giving an opinion, not a command.","zh":"這個片語較有禮貌，因為它顯示作者是在表達意見，而不是下命令。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"a limited system","meaning":"有限制的制度","examples":[{"en":"A limited system would be safer than an unlimited refund policy.","zh":"有限制的制度會比無限制退款政策更安全。"},{"en":"A limited system has clear rules about who qualifies and what is allowed.","zh":"有限制的制度對誰符合資格和甚麼被允許有清晰規則。"},{"en":"A shop may use a limited system by allowing one exchange only.","zh":"商店可透過只准一次換貨來使用有限制的制度。"},{"en":"Limits can prevent customers from using returns carelessly.","zh":"限制可以防止顧客隨便使用退貨安排。"},{"en":"A limited system can still be fair if genuine problems are covered.","zh":"如果真正問題受到保障，有限制的制度仍可以公平。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"evidence-based","meaning":"以證據為本的","examples":[{"en":"An evidence-based returns system would rely on clear proof.","zh":"以證據為本的退貨制度會依靠清晰證明。"},{"en":"Evidence-based decisions are based on facts, records, or proof, not feelings alone.","zh":"以證據為本的決定是根據事實、紀錄或證明，而不只是感覺。"},{"en":"A doctor makes an evidence-based decision after checking test results.","zh":"醫生在檢查化驗結果後作出以證據為本的決定。"},{"en":"An evidence-based refund policy may ask for photos of a defective item.","zh":"以證據為本的退款政策可能要求顧客提供瑕疵貨品的相片。"},{"en":"Evidence-based rules help staff explain decisions more fairly.","zh":"以證據為本的規則幫助員工更公平地解釋決定。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"exchange and refund system","meaning":"換貨及退款制度","examples":[{"en":"A limited exchange and refund system would be fairer to customers.","zh":"有限制的換貨及退款制度會對顧客更公平。"},{"en":"An exchange and refund system explains when customers can change items or get money back.","zh":"換貨及退款制度說明顧客在甚麼情況下可以換貨或取回款項。"},{"en":"A clothing shop needs an exchange and refund system because sizes may not fit.","zh":"服裝店需要換貨及退款制度，因為尺碼可能不合身。"},{"en":"Without a clear system, staff may handle similar cases differently.","zh":"沒有清晰制度，員工可能以不同方式處理相似個案。"},{"en":"A fair system protects honest customers and discourages abuse.","zh":"公平制度保障誠實顧客，並阻止濫用。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"safe from abuse","meaning":"可避免被濫用","examples":[{"en":"The system can be safe from abuse if clear safeguards are built in.","zh":"如果加入清晰防範措施，制度可以避免被濫用。"},{"en":"Safe from abuse means protected from people using the rule unfairly.","zh":"可避免被濫用意思是受到保護，不讓人不公平地利用規則。"},{"en":"A return system is safer from abuse when staff inspect items before issuing refunds.","zh":"員工在退款前檢查貨品，退貨制度便較可避免被濫用。"},{"en":"Order numbers and photos can keep the policy safe from abuse.","zh":"訂單編號和相片可以令政策避免被濫用。"},{"en":"A policy can be flexible and still safe from abuse if limits are clear.","zh":"如果限制清楚，政策可以靈活，同時仍可避免被濫用。"}],"source":"2021 Q3.pdf","sourcePage":2},{"front":"safeguards","meaning":"保障措施；防範措施","examples":[{"en":"Clear safeguards should be built into the policy.","zh":"政策應加入清晰的防範措施。"},{"en":"Safeguards are rules or steps that prevent problems or misuse.","zh":"防範措施是防止問題或濫用的規則或步驟。"},{"en":"Asking for receipts is a safeguard against false refund requests.","zh":"要求收據是防止虛假退款申請的防範措施。"},{"en":"Safety locks are safeguards that stop children from opening dangerous cupboards.","zh":"安全鎖是防止兒童打開危險櫃子的保障措施。"},{"en":"Good safeguards allow fair help without opening the door to abuse.","zh":"好的防範措施容許公平幫助，同時不讓濫用有機可乘。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"built in","meaning":"內置；加入","examples":[{"en":"Clear safeguards should be built in from the beginning.","zh":"清晰的防範措施應從一開始就加入。"},{"en":"Built in means included as part of a system from the start.","zh":"built in 意思是從開始便作為制度的一部分加入。"},{"en":"A phone may have privacy settings built in to protect users.","zh":"電話可能內置私隱設定以保護用戶。"},{"en":"If inspection rules are built in, staff know what to check.","zh":"如果加入檢查規則，員工便知道要檢查甚麼。"},{"en":"Problems are easier to prevent when safeguards are built in early.","zh":"防範措施及早加入時，問題較容易預防。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"at issue is not whether…, but whether…","meaning":"問題不在於是否……，而在於是否……","examples":[{"en":"At issue is not whether customers should have unlimited rights, but whether the present rule is fair.","zh":"問題不在於顧客是否應有無限制權利，而在於現行規則是否公平。"},{"en":"This structure shows that the real question is different from the easy or extreme question.","zh":"這個句式顯示真正問題不同於簡單或極端的問題。"},{"en":"At issue is not whether students should work hard, but whether the workload is healthy.","zh":"問題不在於學生是否應努力，而在於功課量是否健康。"},{"en":"At issue is not whether shops need rules, but whether the rules are reasonable.","zh":"問題不在於商店是否需要規則，而在於規則是否合理。"},{"en":"This phrase is useful for narrowing a debate to the real problem.","zh":"這個片語適合用來把討論收窄到真正問題。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"change their minds","meaning":"改變主意","examples":[{"en":"Customers should not be allowed to change their minds without limit.","zh":"不應容許顧客無限制地改變主意。"},{"en":"To change their minds means to decide differently after making an earlier choice.","zh":"改變主意意思是在作出早前選擇後改變決定。"},{"en":"A customer may change her mind after seeing a dress at home.","zh":"顧客在家中看到裙子後可能改變主意。"},{"en":"A policy should treat change-of-mind cases differently from defective goods.","zh":"政策應把改變主意的個案與有瑕疵貨品分開處理。"},{"en":"People can change their minds, but businesses still need clear limits.","zh":"人可以改變主意，但企業仍需要清晰限制。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"without limit","meaning":"無限制地","examples":[{"en":"Customers should not be allowed to return items without limit.","zh":"不應容許顧客無限制地退貨。"},{"en":"Without limit means with no clear end, number, or control.","zh":"無限制地意思是沒有清晰終點、數量或控制。"},{"en":"Students cannot borrow library books without limit because others need them too.","zh":"學生不能無限制地借圖書館書籍，因為其他人也需要。"},{"en":"If returns are allowed without limit, some customers may misuse the system.","zh":"如果容許無限制地退貨，有些顧客可能濫用制度。"},{"en":"Fairness often needs limits so that one person’s freedom does not hurt others.","zh":"公平往往需要限制，以免一個人的自由傷害他人。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"present rule","meaning":"現行規則","examples":[{"en":"The present rule may be too strict for online fashion.","zh":"現行規則對網上時裝而言可能太嚴格。"},{"en":"The present rule means the rule that is being used now.","zh":"現行規則指現在正在使用的規則。"},{"en":"The present rule allows no refund even when the size guide is wrong.","zh":"現行規則即使尺碼指南錯誤也不容許退款。"},{"en":"If the present rule causes many complaints, managers should review it.","zh":"如果現行規則引起許多投訴，管理層應檢討它。"},{"en":"Changing the present rule does not mean removing all control.","zh":"改變現行規則不等於取消所有控制。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"proportionate for","meaning":"對……而言合乎比例","examples":[{"en":"The present rule may not be proportionate for online fashion.","zh":"現行規則對網上時裝而言可能不合乎比例。"},{"en":"Proportionate for means suitable and not too extreme for a particular situation.","zh":"proportionate for 指對某情況而言合適，而且不過分。"},{"en":"A heavy punishment is not proportionate for a small mistake.","zh":"對小錯誤施以嚴厲懲罰並不合乎比例。"},{"en":"A total refund ban may not be proportionate for defective goods.","zh":"對有瑕疵貨品實施全面退款禁令可能不合乎比例。"},{"en":"Good rules are firm but proportionate for the risk involved.","zh":"好規則應堅定，但也要與涉及的風險合乎比例。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"online fashion","meaning":"網上時裝","examples":[{"en":"Online fashion customers cannot try on clothes before buying them.","zh":"網上時裝顧客在購買前不能試穿衣服。"},{"en":"Online fashion means buying and selling clothes through websites or apps.","zh":"網上時裝指透過網站或應用程式買賣服裝。"},{"en":"Online fashion depends heavily on photos, size charts, and delivery accuracy.","zh":"網上時裝非常依賴相片、尺碼表和送貨準確度。"},{"en":"Returns are common in online fashion because customers cannot feel the fabric first.","zh":"網上時裝常有退貨，因為顧客不能先觸摸布料。"},{"en":"A fair returns policy is especially important in online fashion.","zh":"公平的退貨政策對網上時裝尤其重要。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"unlike shoppers in","meaning":"不像……的顧客","examples":[{"en":"Unlike shoppers in a physical boutique, online customers cannot try on clothes first.","zh":"不像實體精品店的顧客，網上顧客不能先試穿衣服。"},{"en":"“Unlike shoppers in” is used to show how one group is different from another group of shoppers.","zh":"“unlike shoppers in” 用來顯示一組顧客與另一組顧客有何不同。"},{"en":"Unlike shoppers in supermarkets, online buyers cannot check fruit before paying.","zh":"不像超級市場的顧客，網上買家不能在付款前檢查水果。"},{"en":"Unlike shoppers in a shoe shop, online customers cannot test the fit.","zh":"不像鞋店的顧客，網上顧客不能測試是否合腳。"},{"en":"This phrase helps explain why online customers need different protection.","zh":"這個片語有助解釋為何網上顧客需要不同保障。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"physical boutique","meaning":"實體精品店","examples":[{"en":"Customers in a physical boutique can check the fit before paying.","zh":"實體精品店的顧客可以在付款前檢查是否合身。"},{"en":"A physical boutique is a real shop where customers can see and touch clothes.","zh":"實體精品店是顧客可以看見和觸摸衣服的真實店舖。"},{"en":"In a physical boutique, staff can suggest another size immediately.","zh":"在實體精品店，員工可以即時建議另一個尺碼。"},{"en":"Online shops lack the fitting rooms that a physical boutique provides.","zh":"網店沒有實體精品店提供的試身室。"},{"en":"A physical boutique gives customers more information before they decide.","zh":"實體精品店讓顧客在決定前得到更多資訊。"}],"source":"2021 Q3.pdf","sourcePage":3},{"front":"try on","meaning":"試穿","examples":[{"en":"Customers cannot try on a dress before ordering online.","zh":"顧客網上訂購前不能試穿裙子。"},{"en":"To try on clothes means to put them on briefly to check size, style, or comfort.","zh":"試穿衣服意思是短暫穿上它們，以檢查尺碼、款式或舒適度。"},{"en":"A customer may try on two jackets before choosing one.","zh":"顧客可能試穿兩件外套才選擇其中一件。"},{"en":"If people cannot try on clothes, they may order the wrong size.","zh":"如果人們不能試穿衣服，他們可能訂錯尺碼。"},{"en":"Fitting rooms let shoppers try on items before they buy them.","zh":"試身室讓顧客購買前試穿貨品。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"feel the fabric","meaning":"觸摸布料","examples":[{"en":"Online shoppers cannot feel the fabric before buying the item.","zh":"網上顧客購買前不能觸摸貨品的布料。"},{"en":"To feel the fabric means to touch the material to judge its softness, thickness, or quality.","zh":"觸摸布料意思是碰觸材料，以判斷其柔軟度、厚薄或品質。"},{"en":"A customer may feel the fabric of a coat to check whether it is warm enough.","zh":"顧客可能觸摸外套布料，以檢查它是否足夠保暖。"},{"en":"If shoppers cannot feel the fabric, photos may give them the wrong expectation.","zh":"如果顧客不能觸摸布料，相片可能令他們有錯誤期望。"},{"en":"Feeling the fabric helps customers decide whether clothing is comfortable.","zh":"觸摸布料幫助顧客決定衣服是否舒適。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"compare two sizes","meaning":"比較兩個尺碼","examples":[{"en":"Customers cannot compare two sizes in front of a mirror.","zh":"顧客不能在鏡子前比較兩個尺碼。"},{"en":"To compare two sizes means to look at or try two measurements to see which fits better.","zh":"比較兩個尺碼意思是查看或試穿兩個尺寸，以知道哪個更合身。"},{"en":"A shopper may compare two sizes of jeans before buying one pair.","zh":"顧客可能先比較兩個牛仔褲尺碼才購買一條。"},{"en":"Without comparing two sizes, online customers may choose wrongly.","zh":"如果不能比較兩個尺碼，網上顧客可能會選錯。"},{"en":"A flexible exchange policy helps when customers cannot compare two sizes first.","zh":"當顧客不能先比較兩個尺碼時，靈活換貨政策會有幫助。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"in front of a mirror","meaning":"在鏡子前","examples":[{"en":"Customers cannot compare two sizes in front of a mirror.","zh":"顧客不能在鏡子前比較兩個尺碼。"},{"en":"In front of a mirror means standing where you can see your reflection.","zh":"在鏡子前意思是站在可以看見自己倒影的位置。"},{"en":"A shopper checks a jacket in front of a mirror to see how it looks.","zh":"顧客在鏡子前檢查外套，看它是否好看。"},{"en":"Without being in front of a mirror, online buyers must judge clothes from photos.","zh":"不能在鏡子前查看時，網上買家只能根據相片判斷衣服。"},{"en":"Fitting rooms help customers decide because they can look in front of a mirror.","zh":"試身室有助顧客決定，因為他們可以在鏡子前查看。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"rely on","meaning":"依賴","examples":[{"en":"Online customers rely on photos, size charts and delivery accuracy.","zh":"網上顧客依賴相片、尺碼表和送貨準確度。"},{"en":"To rely on something means to depend on it because you need it to make a decision or complete a task.","zh":"依賴某物意思是因為需要它來作決定或完成任務而倚靠它。"},{"en":"Students rely on clear notes when preparing for exams.","zh":"學生準備考試時依賴清晰筆記。"},{"en":"If customers rely on a wrong size chart, they may buy clothes that do not fit.","zh":"如果顧客依賴錯誤尺碼表，他們可能買到不合身的衣服。"},{"en":"People trust a company more when the information they rely on is accurate.","zh":"當人們依賴的資訊準確時，他們會更信任公司。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"size charts","meaning":"尺碼表","examples":[{"en":"Customers use size charts to choose the right fit.","zh":"顧客使用尺碼表來選擇合適尺寸。"},{"en":"Size charts show measurements such as waist, chest, length, and shoulder width.","zh":"尺碼表顯示腰圍、胸圍、長度和肩寬等尺寸。"},{"en":"A good size chart helps online shoppers choose clothes more accurately.","zh":"好的尺碼表幫助網上顧客更準確地選擇衣服。"},{"en":"If size charts are wrong, customers may return more items.","zh":"如果尺碼表錯誤，顧客可能退回更多貨品。"},{"en":"Clear size charts reduce confusion before customers pay.","zh":"清晰尺碼表在顧客付款前減少混亂。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"delivery accuracy","meaning":"送貨準確度","examples":[{"en":"Delivery accuracy is important for customer trust.","zh":"送貨準確度對顧客信任很重要。"},{"en":"Delivery accuracy means sending the correct item to the correct person at the correct time.","zh":"送貨準確度意思是把正確貨品在正確時間送給正確的人。"},{"en":"A shop improves delivery accuracy by checking order numbers carefully.","zh":"商店透過仔細核對訂單編號來提高送貨準確度。"},{"en":"Poor delivery accuracy can lead to wrong colours, wrong sizes, and complaints.","zh":"送貨準確度低可能導致顏色錯誤、尺碼錯誤和投訴。"},{"en":"Customers trust online stores more when delivery accuracy is high.","zh":"當送貨準確度高，顧客會更信任網店。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"far longer than expected","meaning":"比預期長得多","examples":[{"en":"The blouse arrived with sleeves far longer than expected.","zh":"那件女裝襯衫送到時，袖子比預期長得多。"},{"en":"Far longer than expected means much longer than the customer thought it would be.","zh":"比預期長得多意思是比顧客原本以為的長很多。"},{"en":"The delivery took far longer than expected, so the customer missed the event.","zh":"送貨時間比預期長得多，所以顧客錯過了活動。"},{"en":"If trousers are far longer than expected, the buyer may need an exchange.","zh":"如果褲子比預期長得多，買家可能需要換貨。"},{"en":"This phrase shows a large gap between expectation and reality.","zh":"這個片語顯示期望與現實之間有很大差距。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"fit differently from","meaning":"與……的合身程度不同","examples":[{"en":"The jeans fit differently from the size chart.","zh":"這條牛仔褲的合身程度與尺碼表不同。"},{"en":"Fit differently from means the actual size or shape does not match what something suggests.","zh":"fit differently from 指實際尺碼或形狀與某物所顯示的不一致。"},{"en":"This dress fits differently from the photo because it is tighter at the waist.","zh":"這條裙與相片顯示的合身程度不同，因為腰部較緊。"},{"en":"If clothes fit differently from the size chart, customers may feel misled.","zh":"如果衣服與尺碼表的合身程度不同，顧客可能覺得被誤導。"},{"en":"Online shops should explain when a style fits differently from normal sizes.","zh":"當款式與正常尺碼的合身程度不同，網店應加以說明。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"feel punished for","meaning":"因……而覺得受罰","examples":[{"en":"The customer may feel punished for trusting the company.","zh":"顧客可能因信任公司而覺得受罰。"},{"en":"To feel punished for something means to feel unfairly treated because of doing that thing.","zh":"因某事而覺得受罰意思是因做了那件事而感到被不公平對待。"},{"en":"A student may feel punished for asking questions if the teacher reacts angrily.","zh":"如果老師生氣回應，學生可能因發問而覺得受罰。"},{"en":"Customers feel punished for trusting the size chart when they cannot exchange wrong sizes.","zh":"顧客信任尺碼表卻不能換錯尺碼時，會覺得受罰。"},{"en":"A fair policy should not make honest customers feel punished.","zh":"公平政策不應令誠實顧客覺得受罰。"}],"source":"2021 Q3.pdf","sourcePage":4},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, a strict policy seems to save money.","zh":"乍看之下，嚴格政策似乎可以省錢。"},{"en":"At first glance means when something is first seen or considered, before looking carefully.","zh":"乍看之下意思是在最初看見或考慮某事時，尚未仔細分析。"},{"en":"At first glance, the dress looked perfect, but the zip was broken.","zh":"乍看之下，那條裙看似完美，但拉鏈壞了。"},{"en":"A rule may seem fair at first glance but cause problems in real cases.","zh":"規則乍看之下可能公平，但在真實個案中造成問題。"},{"en":"This phrase prepares the reader for a deeper second look.","zh":"這個片語讓讀者準備進一步細看。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"handling costs","meaning":"處理成本","examples":[{"en":"A strict policy may save handling costs at first.","zh":"嚴格政策起初可能節省處理成本。"},{"en":"Handling costs are the money and time spent dealing with orders, returns, or complaints.","zh":"處理成本是處理訂單、退貨或投訴所花的金錢和時間。"},{"en":"A shop pays handling costs when staff check returned clothes.","zh":"員工檢查退回衣服時，商店便要支付處理成本。"},{"en":"Too many returns can increase handling costs for the company.","zh":"太多退貨可能增加公司的處理成本。"},{"en":"Lower handling costs are helpful, but they should not destroy customer trust.","zh":"較低處理成本有幫助，但不應破壞顧客信任。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"on closer inspection","meaning":"仔細看來","examples":[{"en":"On closer inspection, the strict policy may damage repeat business.","zh":"仔細看來，嚴格政策可能損害回頭客生意。"},{"en":"On closer inspection means after looking at something more carefully.","zh":"仔細看來意思是在更仔細查看某事之後。"},{"en":"On closer inspection, the coat had a small tear near the pocket.","zh":"仔細看來，外套口袋附近有一個小裂口。"},{"en":"A rule may seem simple, but on closer inspection it may treat fair cases badly.","zh":"規則可能看似簡單，但仔細看來可能不善待合理個案。"},{"en":"This phrase often introduces a more careful judgement.","zh":"這個片語常用來引出更仔細的判斷。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"turn problems into arguments","meaning":"將問題變成爭拗","examples":[{"en":"The policy turns ordinary sizing problems into arguments.","zh":"該政策將普通尺碼問題變成爭拗。"},{"en":"To turn problems into arguments means to make small difficulties become disputes.","zh":"將問題變成爭拗意思是令小困難變成爭議。"},{"en":"A rude reply can turn a simple complaint into an argument.","zh":"粗魯回覆可以把簡單投訴變成爭拗。"},{"en":"If staff have no power to help, ordinary problems may turn into arguments.","zh":"如果員工無權幫忙，普通問題可能變成爭拗。"},{"en":"Clear rules can stop customer problems from becoming arguments.","zh":"清晰規則可以防止顧客問題變成爭拗。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"ordinary sizing problems","meaning":"普通尺碼問題","examples":[{"en":"Ordinary sizing problems should not become serious disputes.","zh":"普通尺碼問題不應變成嚴重爭議。"},{"en":"Ordinary sizing problems are common issues where clothes are too small, too large, too long, or too short.","zh":"普通尺碼問題是衣服太小、太大、太長或太短等常見問題。"},{"en":"A customer ordering shoes online may face ordinary sizing problems.","zh":"顧客網上訂鞋時可能遇到普通尺碼問題。"},{"en":"If ordinary sizing problems cannot be solved, customers may complain angrily.","zh":"如果普通尺碼問題不能解決，顧客可能憤怒投訴。"},{"en":"A one-exchange rule can deal with ordinary sizing problems fairly.","zh":"一次換貨規則可以公平處理普通尺碼問題。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"negative reviews","meaning":"負面評價","examples":[{"en":"Unfair cases can lead to negative reviews.","zh":"不公平個案可能導致負面評價。"},{"en":"Negative reviews are public comments that describe a bad experience with a product or company.","zh":"負面評價是描述產品或公司差劣經驗的公開評論。"},{"en":"A customer may leave negative reviews after receiving the wrong colour twice.","zh":"顧客收到兩次錯誤顏色後，可能留下負面評價。"},{"en":"Negative reviews can warn other buyers and reduce future sales.","zh":"負面評價可以提醒其他買家，並減少未來銷售。"},{"en":"Good service can prevent one mistake from becoming many negative reviews.","zh":"良好服務可以防止一次錯誤變成許多負面評價。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"lost repeat purchases","meaning":"流失的回購","examples":[{"en":"Customer frustration can lead to lost repeat purchases.","zh":"顧客不滿可能導致流失的回購。"},{"en":"Lost repeat purchases are sales a company loses because customers decide not to buy again.","zh":"流失的回購是公司因顧客決定不再購買而失去的銷售。"},{"en":"A slow refund process may cause lost repeat purchases.","zh":"緩慢的退款程序可能造成流失的回購。"},{"en":"If first-time buyers feel ignored, lost repeat purchases may follow.","zh":"如果首次買家覺得被忽視，之後可能出現流失的回購。"},{"en":"Companies should count lost repeat purchases, not only refund costs.","zh":"公司不應只計算退款成本，也應計算流失的回購。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"disappointed first-time customer","meaning":"失望的首次顧客","examples":[{"en":"A disappointed first-time customer may not buy from us again.","zh":"失望的首次顧客可能不會再向我們購買。"},{"en":"A disappointed first-time customer is someone whose first buying experience with a company is unhappy.","zh":"失望的首次顧客是首次向公司購買卻有不愉快經驗的人。"},{"en":"A wrong delivery can turn a new buyer into a disappointed first-time customer.","zh":"送錯貨可以令新買家變成失望的首次顧客。"},{"en":"If this customer leaves, the company loses a chance to build loyalty.","zh":"如果這位顧客離開，公司便失去建立忠誠度的機會。"},{"en":"Helping a disappointed first-time customer quickly can save future business.","zh":"快速幫助失望的首次顧客可以挽回未來生意。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"abandon her cart","meaning":"放棄購物車","examples":[{"en":"A disappointed customer may abandon her cart next time.","zh":"失望的顧客下次可能放棄購物車。"},{"en":"To abandon her cart means to leave items in an online shopping basket without buying them.","zh":"放棄購物車意思是在網上購物籃留下貨品但沒有購買。"},{"en":"A customer may abandon her cart if delivery fees appear too late.","zh":"如果運費太遲才出現，顧客可能放棄購物車。"},{"en":"Bad past service can make a buyer abandon her cart before payment.","zh":"過去差劣服務會令買家付款前放棄購物車。"},{"en":"Clear prices and fair returns reduce the chance that customers abandon their carts.","zh":"清晰價格和公平退貨可減少顧客放棄購物車的機會。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"warn friends","meaning":"提醒朋友；警告朋友","examples":[{"en":"A customer may warn friends about a bad shopping experience.","zh":"顧客可能提醒朋友注意一次差劣購物經驗。"},{"en":"To warn friends means to tell friends about a risk or problem so they can avoid it.","zh":"提醒朋友意思是告訴朋友某種風險或問題，好讓他們避免。"},{"en":"After a poor refund experience, a buyer may warn friends not to use the shop.","zh":"經歷差劣退款服務後，買家可能提醒朋友不要使用那間商店。"},{"en":"People often warn friends in group chats when a company treats them unfairly.","zh":"當公司不公平對待顧客時，人們常在群組聊天中提醒朋友。"},{"en":"Good service gives customers no reason to warn friends away.","zh":"良好服務令顧客沒有理由警告朋友遠離公司。"}],"source":"2021 Q3.pdf","sourcePage":5},{"front":"group chats","meaning":"群組聊天","examples":[{"en":"Customers may share bad experiences in group chats.","zh":"顧客可能在群組聊天中分享差劣經驗。"},{"en":"Group chats are online conversations where several people send messages to one another.","zh":"群組聊天是多人互相發送訊息的網上對話。"},{"en":"A bad return experience can spread quickly in group chats.","zh":"差劣退貨經驗可以在群組聊天中快速傳開。"},{"en":"If many customers complain in group chats, the company’s reputation may suffer.","zh":"如果許多顧客在群組聊天中投訴，公司聲譽可能受損。"},{"en":"Group chats make private frustration become public influence.","zh":"群組聊天令私人不滿變成公開影響。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"alternatives are one click away","meaning":"替代選擇只需一按","examples":[{"en":"In online fashion, alternatives are one click away.","zh":"在網上時裝中，替代選擇只需一按。"},{"en":"This phrase means customers can easily choose another shop online.","zh":"這個片語意思是顧客可以很容易在網上選擇另一間商店。"},{"en":"If checkout is confusing, alternatives are one click away.","zh":"如果付款過程令人混亂，替代選擇只需一按。"},{"en":"Bad service is risky because online customers can leave instantly.","zh":"差劣服務很危險，因為網上顧客可以立即離開。"},{"en":"Companies must stay fair because competitors are very easy to reach.","zh":"公司必須保持公平，因為競爭對手很容易接觸到。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"keeping the rule unchanged","meaning":"保持規則不變","examples":[{"en":"Keeping the rule unchanged may cost the company more than it saves.","zh":"保持規則不變可能令公司得不償失。"},{"en":"Keeping the rule unchanged means continuing to use the same rule without revision.","zh":"保持規則不變意思是繼續使用同一規則而不作修訂。"},{"en":"A school may regret keeping the rule unchanged if students keep misunderstanding it.","zh":"如果學生一直誤解規則，學校可能後悔保持規則不變。"},{"en":"If complaints rise, keeping the rule unchanged may look careless.","zh":"如果投訴增加，保持規則不變可能顯得不負責任。"},{"en":"Sometimes changing a rule is safer than keeping it unchanged.","zh":"有時改變規則比保持規則不變更安全。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"cost more than it saves","meaning":"得不償失","examples":[{"en":"The strict policy may cost more than it saves.","zh":"嚴格政策可能得不償失。"},{"en":"Cost more than it saves means the damage or loss is greater than the money saved.","zh":"得不償失意思是造成的損害或損失大於節省的金錢。"},{"en":"A cheap repair may cost more than it saves if the machine breaks again.","zh":"如果機器再次壞掉，便宜維修可能得不償失。"},{"en":"A no-refund rule may save handling costs but lose loyal customers.","zh":"不退款規則可能節省處理成本，卻失去忠誠顧客。"},{"en":"Managers should check hidden costs before thinking a rule saves money.","zh":"管理層認為規則省錢前，應檢查隱藏成本。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"in addition","meaning":"此外","examples":[{"en":"In addition, the policy gives staff little room to help customers.","zh":"此外，該政策令員工幾乎沒有空間幫助顧客。"},{"en":"In addition means “also” and is used to add another point.","zh":"in addition 意思是「此外」，用來加入另一點。"},{"en":"The shop should improve its size chart; in addition, it should train staff better.","zh":"商店應改善尺碼表；此外，也應更好地培訓員工。"},{"en":"In addition, clear return forms can reduce misunderstandings.","zh":"此外，清晰退貨表格可以減少誤解。"},{"en":"This phrase helps organise several reasons in a formal letter.","zh":"這個片語有助在正式信件中組織多個理由。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"leave someone with little room to","meaning":"令某人幾乎沒有空間去……","examples":[{"en":"The policy leaves our team with little room to resolve fair cases.","zh":"該政策令我們團隊幾乎沒有空間處理合理個案。"},{"en":"This phrase means someone has very few choices or very little flexibility to act.","zh":"這個片語意思是某人幾乎沒有選擇或彈性去行動。"},{"en":"A strict school rule may leave teachers with little room to help special cases.","zh":"嚴格校規可能令老師幾乎沒有空間幫助特殊個案。"},{"en":"The no-refund policy leaves staff with little room to solve honest mistakes.","zh":"不退款政策令員工幾乎沒有空間解決誠實錯誤。"},{"en":"Good rules should not leave responsible staff with no room to use judgement.","zh":"好規則不應令負責任的員工完全沒有判斷空間。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"resolve fair cases","meaning":"處理合理個案","examples":[{"en":"Staff need more flexibility to resolve fair cases.","zh":"員工需要更多彈性來處理合理個案。"},{"en":"To resolve fair cases means to solve situations where the customer has a reasonable problem.","zh":"處理合理個案意思是解決顧客有合理問題的情況。"},{"en":"A defective zip is a fair case that staff should resolve quickly.","zh":"有問題的拉鏈是員工應迅速處理的合理個案。"},{"en":"If staff cannot resolve fair cases, customers may feel ignored.","zh":"如果員工不能處理合理個案，顧客可能覺得被忽視。"},{"en":"Clear evidence helps staff resolve fair cases without opening the door to abuse.","zh":"清晰證據幫助員工處理合理個案，而不讓濫用有機可乘。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"defective zip","meaning":"有問題的拉鏈","examples":[{"en":"A customer reported a defective zip on a new dress.","zh":"有顧客報告一條新裙的拉鏈有問題。"},{"en":"A defective zip is a zip that is broken, stuck, or not working properly.","zh":"有問題的拉鏈是損壞、卡住或不能正常使用的拉鏈。"},{"en":"A jacket with a defective zip may not close even when it is new.","zh":"有問題的拉鏈可能令新外套也無法拉上。"},{"en":"If a defective zip is the company’s fault, a refund may be fair.","zh":"如果有問題的拉鏈是公司責任，退款可能是公平的。"},{"en":"Staff should inspect the defective zip before approving the return.","zh":"員工應在批准退貨前檢查有問題的拉鏈。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"wrong colour","meaning":"錯誤顏色","examples":[{"en":"The customer received the wrong colour.","zh":"顧客收到錯誤顏色。"},{"en":"Wrong colour means the item delivered is not the colour the customer ordered.","zh":"錯誤顏色意思是送到的貨品不是顧客訂購的顏色。"},{"en":"A customer may order a black dress but receive the wrong colour in blue.","zh":"顧客可能訂購黑色裙子，卻收到藍色這個錯誤顏色。"},{"en":"Wrong colour cases often happen when warehouse labels are checked carelessly.","zh":"錯誤顏色個案常在倉庫標籤核對不仔細時發生。"},{"en":"If the wrong colour is delivered, the customer should not pay extra postage.","zh":"如果送錯顏色，顧客不應支付額外郵費。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"size guide","meaning":"尺碼指南","examples":[{"en":"The size guide clearly misled the customer.","zh":"尺碼指南明顯誤導了顧客。"},{"en":"A size guide gives advice about which size a customer should choose.","zh":"尺碼指南提供建議，告訴顧客應選擇哪個尺碼。"},{"en":"A good size guide explains body measurements and clothing measurements clearly.","zh":"好的尺碼指南會清楚解釋身體尺寸和衣服尺寸。"},{"en":"If the size guide is inaccurate, customers may buy clothes that do not fit.","zh":"如果尺碼指南不準確，顧客可能買到不合身的衣服。"},{"en":"Online fashion needs a reliable size guide because customers cannot try items on.","zh":"網上時裝需要可靠尺碼指南，因為顧客不能試穿貨品。"}],"source":"2021 Q3.pdf","sourcePage":6},{"front":"mislead someone","meaning":"誤導某人","examples":[{"en":"An inaccurate size guide can mislead customers.","zh":"不準確的尺碼指南可能誤導顧客。"},{"en":"To mislead someone means to give information that makes them believe something wrong.","zh":"誤導某人意思是提供令人相信錯誤事情的資訊。"},{"en":"A photo with heavy editing may mislead customers about the real colour.","zh":"過度修圖的相片可能誤導顧客對真實顏色的理解。"},{"en":"If a delivery date is unclear, it may mislead buyers.","zh":"如果送貨日期不清晰，可能誤導買家。"},{"en":"Companies should correct information quickly before it misleads more people.","zh":"公司應迅速更正資訊，以免誤導更多人。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"look as though","meaning":"看起來好像","examples":[{"en":"The company may look as though it is hiding behind fine print.","zh":"公司可能看起來好像躲在細則背後。"},{"en":"Look as though means seem like something is true, even if it may not be intended.","zh":"look as though 意思是看起來某事似乎是真的，即使未必是原意。"},{"en":"If staff refuse every request, the shop may look as though it does not care.","zh":"如果員工拒絕每個申請，商店可能看起來好像不關心顧客。"},{"en":"A confusing policy can look as though the company wants customers to give up.","zh":"混亂政策可能看起來好像公司想令顧客放棄。"},{"en":"Companies should avoid behaviour that looks as though it is unfair.","zh":"公司應避免看起來好像不公平的行為。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"hide behind fine print","meaning":"躲在細則背後","examples":[{"en":"The company should not hide behind fine print.","zh":"公司不應躲在細則背後。"},{"en":"To hide behind fine print means to use small legal details to avoid fair responsibility.","zh":"躲在細則背後意思是利用小字法律細節逃避公平責任。"},{"en":"A business hides behind fine print when it refuses help although the customer was misled.","zh":"即使顧客被誤導，公司仍拒絕幫忙，就是躲在細則背後。"},{"en":"Customers dislike companies that hide behind fine print instead of solving problems.","zh":"顧客不喜歡躲在細則背後而不解決問題的公司。"},{"en":"Clear and fair policies stop the company from looking like it hides behind fine print.","zh":"清晰公平的政策可避免公司看起來像躲在細則背後。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"fine print","meaning":"細則；小字條款","examples":[{"en":"Customers may feel that the company is relying on fine print.","zh":"顧客可能覺得公司依靠小字條款。"},{"en":"Fine print means small written terms that many customers may not notice easily.","zh":"小字條款指許多顧客不容易注意到的小型書面條款。"},{"en":"Important return conditions should not be hidden in fine print.","zh":"重要退貨條件不應隱藏在小字條款中。"},{"en":"If customers miss the fine print, they may feel tricked later.","zh":"如果顧客錯過小字條款，他們之後可能覺得被欺騙。"},{"en":"Good businesses explain key rules clearly, not only in fine print.","zh":"好企業會清楚解釋重要規則，而不只是放在小字條款中。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"serve customers","meaning":"服務顧客","examples":[{"en":"The company should focus on serving customers fairly.","zh":"公司應專注公平地服務顧客。"},{"en":"To serve customers means to help buyers before, during, or after a purchase.","zh":"服務顧客意思是在購買前、購買時或購買後幫助買家。"},{"en":"Staff serve customers well when they listen patiently to complaints.","zh":"員工耐心聆聽投訴時，就是良好地服務顧客。"},{"en":"A policy that gives no solution makes it harder to serve customers.","zh":"沒有解決方案的政策令服務顧客更加困難。"},{"en":"Serving customers fairly can protect both trust and sales.","zh":"公平地服務顧客可以保障信任和銷售。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"replace the blanket ban with","meaning":"以……取代一刀切禁令","examples":[{"en":"Chris suggests replacing the blanket ban with a conditional policy.","zh":"Chris 建議以有條件政策取代一刀切禁令。"},{"en":"To replace the blanket ban with something means to remove a total rule and use a more specific rule instead.","zh":"以某物取代一刀切禁令意思是取消全面規則，改用更具體的規則。"},{"en":"A school may replace a blanket phone ban with rules for responsible use.","zh":"學校可能以負責任使用規則取代一刀切手機禁令。"},{"en":"Fast Fashion could replace the blanket ban with a fourteen-day exchange policy.","zh":"Fast Fashion 可以以十四日換貨政策取代一刀切禁令。"},{"en":"This phrase shows a move from strict refusal to controlled flexibility.","zh":"這個片語顯示由嚴格拒絕轉向受控彈性。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"blanket ban","meaning":"一刀切禁令","examples":[{"en":"A blanket ban may be too harsh for genuine customers.","zh":"一刀切禁令對真正有需要的顧客可能太嚴厲。"},{"en":"A blanket ban is a rule that forbids something in all cases, without exceptions.","zh":"一刀切禁令是在所有情況下禁止某事、沒有例外的規則。"},{"en":"A blanket ban on returns treats defective items and change-of-mind cases the same.","zh":"一刀切退貨禁令把有瑕疵貨品和改變主意個案同樣處理。"},{"en":"Blanket bans are simple to apply but can be unfair in special cases.","zh":"一刀切禁令容易執行，但在特殊個案中可能不公平。"},{"en":"A company may replace a blanket ban with clearer conditions.","zh":"公司可能以更清晰條件取代一刀切禁令。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"conditional fourteen-day policy","meaning":"有條件的十四日政策","examples":[{"en":"A conditional fourteen-day policy would allow limited returns.","zh":"有條件的十四日政策會容許有限度退貨。"},{"en":"A conditional fourteen-day policy allows returns within fourteen days only if certain rules are met.","zh":"有條件的十四日政策只在符合某些規則時容許十四日內退貨。"},{"en":"The policy may require items to be unworn, unwashed, and properly tagged.","zh":"該政策可能要求貨品未穿過、未洗過並有吊牌。"},{"en":"If customers apply after fourteen days, they may not qualify.","zh":"如果顧客在十四日後申請，可能不符合資格。"},{"en":"This policy gives fair help while keeping clear time limits.","zh":"這項政策提供公平幫助，同時保留清晰時限。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"one exchange","meaning":"一次換貨","examples":[{"en":"Customers should be allowed one exchange for size or colour.","zh":"顧客應獲准因尺碼或顏色問題進行一次換貨。"},{"en":"One exchange means the customer can change the item once, but not repeatedly.","zh":"一次換貨意思是顧客可以更換貨品一次，但不能反覆更換。"},{"en":"A buyer may use one exchange to replace a medium shirt with a large one.","zh":"買家可使用一次換貨，把中碼襯衫換成大碼。"},{"en":"Allowing one exchange helps honest customers without encouraging endless returns.","zh":"容許一次換貨能幫助誠實顧客，而不鼓勵無止境退貨。"},{"en":"Staff should record the one exchange so the limit is clear.","zh":"員工應記錄這次換貨，讓限制清楚。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"size or colour","meaning":"尺碼或顏色","examples":[{"en":"Customers may request one exchange for size or colour.","zh":"顧客可因尺碼或顏色問題要求一次換貨。"},{"en":"Size or colour refers to the measurement or shade of a product.","zh":"尺碼或顏色指產品的尺寸或色調。"},{"en":"A customer may need an exchange if the size is too small or the colour is wrong.","zh":"如果尺碼太小或顏色錯誤，顧客可能需要換貨。"},{"en":"Size or colour problems are common in online clothing purchases.","zh":"尺碼或顏色問題在網上購買服裝時很常見。"},{"en":"A policy can allow exchanges for size or colour without allowing every return.","zh":"政策可以容許因尺碼或顏色換貨，而不容許所有退貨。"}],"source":"2021 Q3.pdf","sourcePage":7},{"front":"unworn and unwashed","meaning":"未穿過及未洗過","examples":[{"en":"The item must be unworn and unwashed.","zh":"貨品必須未穿過及未洗過。"},{"en":"Unworn and unwashed means the item has not been used or cleaned after purchase.","zh":"未穿過及未洗過意思是貨品購買後沒有被使用或清洗。"},{"en":"A dress with perfume or make-up marks is not unworn and unwashed.","zh":"有香水味或化妝痕跡的裙子並非未穿過及未洗過。"},{"en":"Requiring items to be unworn and unwashed protects the company from abuse.","zh":"要求貨品未穿過及未洗過可保護公司免受濫用。"},{"en":"Customers should keep tags on items until they decide whether to keep them.","zh":"顧客在決定是否保留貨品前應保留吊牌。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"refunds should be available only when","meaning":"退款只應在……情況下提供","examples":[{"en":"Refunds should be available only when the company is at fault.","zh":"退款只應在公司有錯的情況下提供。"},{"en":"This phrase means customers should get money back only under specific conditions.","zh":"這個片語意思是顧客只應在特定條件下取回款項。"},{"en":"Refunds should be available only when an item is defective or wrongly delivered.","zh":"退款只應在貨品有瑕疵或送錯時提供。"},{"en":"If customers simply change their minds, store credit may be more suitable.","zh":"如果顧客只是改變主意，店舖購物金可能更合適。"},{"en":"This wording keeps refund rights clear and limited.","zh":"這種表達令退款權利清晰而有限。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"defective","meaning":"有瑕疵的","examples":[{"en":"Refunds should be available when the item is defective.","zh":"當貨品有瑕疵時，應提供退款。"},{"en":"Defective means something is faulty, broken, or not working as it should.","zh":"有瑕疵的意思是某物有問題、損壞或不能正常運作。"},{"en":"A bag with a broken strap is defective.","zh":"手帶斷裂的袋是有瑕疵的貨品。"},{"en":"If a defective item reaches a customer, the company should offer a fair remedy.","zh":"如果有瑕疵貨品送到顧客手上，公司應提供公平補救方法。"},{"en":"Defective goods are different from items a customer simply dislikes.","zh":"有瑕疵貨品不同於顧客只是單純不喜歡的貨品。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"wrongly delivered","meaning":"送錯的","examples":[{"en":"Refunds should be available when an item is wrongly delivered.","zh":"當貨品送錯時，應提供退款。"},{"en":"Wrongly delivered means sent to the wrong person, address, or order.","zh":"送錯的意思是送給錯誤的人、地址或訂單。"},{"en":"A red dress is wrongly delivered if the customer ordered a black one.","zh":"如果顧客訂購黑色裙卻收到紅色裙，貨品就是送錯的。"},{"en":"Wrongly delivered items show that the company, not the customer, made the mistake.","zh":"送錯貨品顯示錯誤在公司，而不是顧客。"},{"en":"When goods are wrongly delivered, the customer should not bear the cost.","zh":"當貨品送錯時，顧客不應承擔成本。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"materially different from","meaning":"與……有重大差異","examples":[{"en":"A refund should be allowed if the item is materially different from its description.","zh":"如果貨品與描述有重大差異，應容許退款。"},{"en":"Materially different from means seriously or importantly different from what was promised.","zh":"與……有重大差異意思是與承諾內容有嚴重或重要不同。"},{"en":"A cotton shirt is materially different from the description if it is actually polyester.","zh":"如果描述說是棉質襯衫，但實際是聚酯纖維，便與描述有重大差異。"},{"en":"If the colour, fabric, or size is materially different, the customer may deserve a refund.","zh":"如果顏色、布料或尺碼有重大差異，顧客可能應獲退款。"},{"en":"Small lighting differences in photos may not always be materially different.","zh":"相片中的輕微光線差異未必總是重大差異。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"product description","meaning":"產品描述","examples":[{"en":"The item should match the product description.","zh":"貨品應符合產品描述。"},{"en":"A product description explains an item’s size, colour, material, features, and use.","zh":"產品描述解釋貨品的尺碼、顏色、物料、特點和用途。"},{"en":"Customers rely on the product description before buying online.","zh":"顧客網購前依賴產品描述。"},{"en":"If the product description says “wool” but the coat is polyester, customers may feel misled.","zh":"如果產品描述寫「羊毛」，但外套是聚酯纖維，顧客可能覺得被誤導。"},{"en":"Accurate product descriptions reduce returns and complaints.","zh":"準確的產品描述可以減少退貨和投訴。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"change-of-mind cases","meaning":"改變主意的個案","examples":[{"en":"Store credit is more suitable for simple change-of-mind cases.","zh":"店舖購物金較適合簡單的改變主意個案。"},{"en":"Change-of-mind cases happen when customers no longer want an item even though it is not defective.","zh":"改變主意的個案指顧客不再想要貨品，但貨品本身沒有瑕疵。"},{"en":"A customer may create a change-of-mind case after deciding the colour does not suit her.","zh":"顧客決定顏色不適合自己後，可能形成改變主意的個案。"},{"en":"These cases should be treated differently from company mistakes.","zh":"這些個案應與公司錯誤分開處理。"},{"en":"Store credit can help change-of-mind cases without giving unlimited cash refunds.","zh":"店舖購物金可以幫助改變主意的個案，而不提供無限制現金退款。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"store credit","meaning":"店舖購物金","examples":[{"en":"Store credit may be more suitable than a cash refund.","zh":"店舖購物金可能比現金退款更合適。"},{"en":"Store credit is value a customer can use to buy from the same shop later.","zh":"店舖購物金是顧客日後可在同一商店使用的金額。"},{"en":"A shop may give store credit when a customer changes her mind.","zh":"當顧客改變主意時，商店可能提供店舖購物金。"},{"en":"Store credit keeps the money in the business while giving customers another choice.","zh":"店舖購物金讓金錢留在企業內，同時給顧客另一選擇。"},{"en":"Store credit is not the same as cash because it must be spent in that shop.","zh":"店舖購物金不同於現金，因為它必須在該商店使用。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"cash refunds","meaning":"現金退款","examples":[{"en":"Cash refunds should be limited to serious cases.","zh":"現金退款應限於嚴重個案。"},{"en":"Cash refunds return money to customers instead of giving exchange or store credit.","zh":"現金退款是把款項退還給顧客，而不是提供換貨或店舖購物金。"},{"en":"A customer may receive a cash refund when the company sends a defective item.","zh":"當公司送出有瑕疵貨品時，顧客可能收到現金退款。"},{"en":"Too many cash refunds can harm profit if they are not controlled.","zh":"如果不受控制，太多現金退款可能損害利潤。"},{"en":"Clear rules help staff decide when cash refunds are fair.","zh":"清晰規則幫助員工判斷何時現金退款是公平的。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"final-sale items","meaning":"清貨不設退換貨品","examples":[{"en":"Final-sale items should remain non-returnable.","zh":"清貨不設退換貨品應維持不可退貨。"},{"en":"Final-sale items are products sold at a final price with no return or exchange allowed.","zh":"清貨不設退換貨品是以最終價格出售且不准退換的產品。"},{"en":"A shop may mark heavily discounted clothes as final-sale items.","zh":"商店可能把大幅折扣衣服標示為清貨不設退換貨品。"},{"en":"Customers should know before payment that final-sale items cannot be returned.","zh":"顧客付款前應知道清貨不設退換貨品不可退回。"},{"en":"Clear labels prevent disputes over final-sale items.","zh":"清晰標籤可防止關於清貨不設退換貨品的爭議。"}],"source":"2021 Q3.pdf","sourcePage":8},{"front":"hygiene-sensitive goods","meaning":"涉及衞生問題的貨品","examples":[{"en":"Underwear and earrings are hygiene-sensitive goods.","zh":"內衣和耳環是涉及衞生問題的貨品。"},{"en":"Hygiene-sensitive goods are items that cannot safely be resold after touching the body.","zh":"涉及衞生問題的貨品是接觸身體後不能安全轉售的貨品。"},{"en":"Swimwear may be treated as hygiene-sensitive goods for health reasons.","zh":"泳衣可能因健康原因被視為涉及衞生問題的貨品。"},{"en":"Returns of hygiene-sensitive goods can create risks for other customers.","zh":"退回涉及衞生問題的貨品可能為其他顧客帶來風險。"},{"en":"These goods should remain non-returnable if the rule is clearly stated.","zh":"如果規則清楚列明，這些貨品應維持不可退貨。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"remain non-returnable","meaning":"維持不可退貨","examples":[{"en":"Hygiene-sensitive goods should remain non-returnable.","zh":"涉及衞生問題的貨品應維持不可退貨。"},{"en":"Remain non-returnable means continue to be items that customers cannot return.","zh":"維持不可退貨意思是繼續屬於顧客不能退回的貨品。"},{"en":"Earrings may remain non-returnable after purchase for hygiene reasons.","zh":"耳環購買後可能因衞生原因維持不可退貨。"},{"en":"Final-sale items can remain non-returnable if the rule is stated before payment.","zh":"如果付款前列明規則，清貨貨品可以維持不可退貨。"},{"en":"A fair policy can allow some returns while some items remain non-returnable.","zh":"公平政策可以容許某些退貨，同時讓某些貨品維持不可退貨。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"provided that","meaning":"只要；前提是","examples":[{"en":"Final-sale items can remain non-returnable, provided that this is clearly stated before payment.","zh":"清貨貨品可以維持不可退貨，前提是付款前清楚列明。"},{"en":"Provided that means only if a certain condition is met.","zh":"provided that 意思是只有在某條件符合時才可以。"},{"en":"Students may join the trip, provided that they return the form on time.","zh":"學生可以參加旅行，前提是準時交回表格。"},{"en":"A shop can refuse final-sale returns, provided that customers were warned clearly.","zh":"商店可以拒絕清貨退貨，前提是已清楚提醒顧客。"},{"en":"This phrase is useful for adding a condition to a rule.","zh":"這個片語適合用來為規則加入條件。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"clearly stated before payment","meaning":"付款前清楚列明","examples":[{"en":"The return conditions should be clearly stated before payment.","zh":"退貨條件應在付款前清楚列明。"},{"en":"Clearly stated before payment means explained plainly before the customer pays.","zh":"付款前清楚列明意思是在顧客付款前清楚解釋。"},{"en":"Delivery fees should be clearly stated before payment so customers are not surprised.","zh":"送貨費應在付款前清楚列明，令顧客不會感到意外。"},{"en":"If final-sale rules are not clearly stated before payment, complaints may follow.","zh":"如果清貨規則沒有在付款前清楚列明，之後可能出現投訴。"},{"en":"Clear information before payment helps customers make informed choices.","zh":"付款前的清晰資訊幫助顧客作出知情選擇。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"return postage","meaning":"退貨郵費","examples":[{"en":"Customers could pay return postage for ordinary exchanges.","zh":"顧客可為一般換貨支付退貨郵費。"},{"en":"Return postage is the delivery cost of sending an item back to the seller.","zh":"退貨郵費是把貨品寄回賣方的運送費用。"},{"en":"A customer may pay return postage when she changes size by choice.","zh":"當顧客自行更改尺碼時，可能要支付退貨郵費。"},{"en":"If the fault is the company’s, the company should pay the return postage.","zh":"如果錯在公司，公司應支付退貨郵費。"},{"en":"Clear return postage rules prevent arguments about costs.","zh":"清晰退貨郵費規則可防止關於費用的爭拗。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"ordinary exchanges","meaning":"一般換貨","examples":[{"en":"Customers could pay return postage for ordinary exchanges.","zh":"顧客可為一般換貨支付退貨郵費。"},{"en":"Ordinary exchanges are normal changes for size, colour, or preference, not serious faults.","zh":"一般換貨是因尺碼、顏色或喜好而作出的普通更換，不是嚴重錯誤。"},{"en":"Changing a medium shirt to a large one is an ordinary exchange.","zh":"把中碼襯衫換成大碼就是一般換貨。"},{"en":"Customers may pay postage for ordinary exchanges because the company did not make a mistake.","zh":"顧客可能要為一般換貨支付郵費，因為公司沒有犯錯。"},{"en":"Ordinary exchanges should be simple but still controlled.","zh":"一般換貨應簡單，但仍需受控。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"when the fault is ours","meaning":"當錯在我們一方","examples":[{"en":"Fast Fashion should pay the postage when the fault is ours.","zh":"當錯在我們一方時，Fast Fashion 應支付郵費。"},{"en":"When the fault is ours means when the company caused the problem.","zh":"當錯在我們一方意思是公司造成了問題。"},{"en":"If the warehouse sends the wrong colour, the fault is ours.","zh":"如果倉庫送錯顏色，錯就在我們一方。"},{"en":"When the fault is ours, customers should not pay to fix the mistake.","zh":"當錯在我們一方時，顧客不應付錢去修正錯誤。"},{"en":"Admitting when the fault is ours helps rebuild trust.","zh":"承認錯在我們一方有助重建信任。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"genuine customers","meaning":"真正有需要的顧客","examples":[{"en":"The system would give genuine customers a fair remedy.","zh":"該制度會給真正有需要的顧客公平補救方法。"},{"en":"Genuine customers are honest buyers with real problems, not people trying to misuse the policy.","zh":"真正有需要的顧客是有真實問題的誠實買家，而不是想濫用政策的人。"},{"en":"A genuine customer may ask for help because a zip broke on arrival.","zh":"真正有需要的顧客可能因拉鏈到貨時已損壞而求助。"},{"en":"Safeguards should stop abuse without hurting genuine customers.","zh":"防範措施應阻止濫用，而不傷害真正有需要的顧客。"},{"en":"A fair policy protects genuine customers and the business at the same time.","zh":"公平政策同時保障真正有需要的顧客和企業。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"fair remedy","meaning":"公平補救方法","examples":[{"en":"Genuine customers deserve a fair remedy.","zh":"真正有需要的顧客應得到公平補救方法。"},{"en":"A fair remedy is a reasonable solution, such as exchange, refund, repair, or store credit.","zh":"公平補救方法是合理解決方案，例如換貨、退款、維修或店舖購物金。"},{"en":"A customer who receives the wrong item should receive a fair remedy.","zh":"收到錯誤貨品的顧客應得到公平補救方法。"},{"en":"Without a fair remedy, a small mistake can become a serious complaint.","zh":"沒有公平補救方法，小錯誤可能變成嚴重投訴。"},{"en":"The remedy should match the seriousness of the problem.","zh":"補救方法應與問題的嚴重程度相稱。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"turn returns into","meaning":"將退貨變成……","examples":[{"en":"The company should not turn returns into free wardrobe rental.","zh":"公司不應將退貨變成免費租衫。"},{"en":"To turn returns into something means to make returns become that thing in practice.","zh":"將退貨變成某事意思是在實際上令退貨成為那種事情。"},{"en":"An unlimited policy may turn returns into a way to borrow clothes for events.","zh":"無限制政策可能將退貨變成為活動借衣服的方法。"},{"en":"Strong inspection rules stop customers from turning returns into misuse.","zh":"嚴格檢查規則阻止顧客將退貨變成濫用。"},{"en":"The goal is to help fair cases, not turn returns into a free service for abuse.","zh":"目標是幫助合理個案，而不是將退貨變成可濫用的免費服務。"}],"source":"2021 Q3.pdf","sourcePage":9},{"front":"free wardrobe rental","meaning":"免費租衫","examples":[{"en":"The policy must not become free wardrobe rental.","zh":"政策絕不能變成免費租衫。"},{"en":"Free wardrobe rental means customers use clothes once and return them without real cost.","zh":"免費租衫意思是顧客只穿衣服一次，再免費退回。"},{"en":"A dress bought for one party and returned the next day may become free wardrobe rental.","zh":"為一次派對購買裙子並翌日退回，可能變成免費租衫。"},{"en":"Tamper-evident tags can reduce free wardrobe rental.","zh":"防拆封吊牌可以減少免費租衫。"},{"en":"A returns policy should not let dishonest customers treat the shop like a rental service.","zh":"退貨政策不應讓不誠實顧客把商店當成租衫服務。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, a more flexible policy may encourage abuse.","zh":"誠然，較靈活的政策可能鼓勵濫用。"},{"en":"Granted means the writer accepts a point before explaining why it does not defeat the argument.","zh":"granted 意思是作者先承認一點，再解釋為何它不推翻論點。"},{"en":"Granted, refunds cost money, but unfair rules can cost trust.","zh":"誠然，退款會花錢，但不公平規則可能失去信任。"},{"en":"Granted, some customers may misuse the policy, so safeguards are needed.","zh":"誠然，有些顧客可能濫用政策，所以需要防範措施。"},{"en":"This word helps show that the writer is balanced and realistic.","zh":"這個字有助顯示作者平衡而現實。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"flexible policy","meaning":"較靈活的政策","examples":[{"en":"A more flexible policy may encourage abuse if it is not controlled.","zh":"如果不受控制，較靈活的政策可能鼓勵濫用。"},{"en":"A flexible policy allows staff to handle different cases in different fair ways.","zh":"較靈活的政策容許員工以不同公平方式處理不同個案。"},{"en":"A school may use a flexible policy for students with medical needs.","zh":"學校可能為有醫療需要的學生使用較靈活的政策。"},{"en":"A flexible returns policy helps when customers face genuine problems.","zh":"較靈活的退貨政策在顧客遇到真正問題時有幫助。"},{"en":"Flexibility must come with safeguards so it does not become unfair.","zh":"彈性必須配合防範措施，才不會變得不公平。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"encourage abuse","meaning":"鼓勵濫用","examples":[{"en":"A careless refund policy may encourage abuse.","zh":"草率的退款政策可能鼓勵濫用。"},{"en":"To encourage abuse means to make it easier or more tempting for people to misuse a system.","zh":"鼓勵濫用意思是令人更容易或更想不當使用制度。"},{"en":"Unlimited returns may encourage abuse by people who wear items once and send them back.","zh":"無限制退貨可能鼓勵只穿一次就退回的人濫用制度。"},{"en":"Weak checks encourage abuse because dishonest customers feel there is no risk.","zh":"薄弱檢查會鼓勵濫用，因為不誠實顧客覺得沒有風險。"},{"en":"Clear limits help customers fairly without encouraging abuse.","zh":"清晰限制能公平幫助顧客，而不鼓勵濫用。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"wear something once","meaning":"只穿一次","examples":[{"en":"Some customers may wear a dress once and send it back.","zh":"有些顧客可能只穿裙子一次便退回。"},{"en":"To wear something once means to use clothing one time only.","zh":"只穿一次意思是衣服只被使用一次。"},{"en":"A person may wear something once for a wedding and then try to return it.","zh":"有人可能為婚禮只穿某件衣服一次，然後試圖退貨。"},{"en":"If a policy allows this, returns may become free wardrobe rental.","zh":"如果政策容許這樣，退貨可能變成免費租衫。"},{"en":"Tamper-evident tags help show whether customers have worn something once.","zh":"防拆封吊牌有助顯示顧客是否只穿過一次。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"send it back","meaning":"寄回；退回","examples":[{"en":"Some customers may wear an item once and send it back.","zh":"有些顧客可能只穿貨品一次便寄回。"},{"en":"To send it back means to return an item to the seller by post or delivery.","zh":"寄回意思是透過郵寄或送貨把貨品退還賣方。"},{"en":"A customer may send it back if the wrong size arrives.","zh":"如果送到錯誤尺碼，顧客可能把它寄回。"},{"en":"Customers should not send it back after wearing it to an event.","zh":"顧客不應在穿去活動後把它寄回。"},{"en":"Clear instructions tell customers how and when to send it back.","zh":"清晰指引告訴顧客如何及何時寄回貨品。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"order several sizes","meaning":"訂購多個尺碼","examples":[{"en":"Some customers may order several sizes without intending to keep them all.","zh":"有些顧客可能訂購多個尺碼，卻無意全部保留。"},{"en":"To order several sizes means to buy the same item in different measurements.","zh":"訂購多個尺碼意思是以不同尺寸購買同一貨品。"},{"en":"A customer may order several sizes because she is unsure which one will fit.","zh":"顧客可能因不確定哪個合身而訂購多個尺碼。"},{"en":"Ordering several sizes can increase return rates and handling costs.","zh":"訂購多個尺碼可能增加退貨率和處理成本。"},{"en":"A one-exchange limit discourages customers from ordering too many sizes carelessly.","zh":"一次換貨限制可減少顧客隨便訂購太多尺碼。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"with no intention of","meaning":"無意……","examples":[{"en":"Some customers may order several sizes with no intention of keeping more than one.","zh":"有些顧客可能訂購多個尺碼，卻無意保留超過一件。"},{"en":"With no intention of means without planning or wanting to do something.","zh":"with no intention of 意思是沒有計劃或不想做某事。"},{"en":"A student should not join a project with no intention of helping.","zh":"學生不應無意幫忙卻加入項目。"},{"en":"A customer acts unfairly if she orders five dresses with no intention of keeping them.","zh":"如果顧客訂購五條裙卻無意保留，就是不公平行為。"},{"en":"Policies should discourage behaviour done with no intention of real purchase.","zh":"政策應阻止無意真正購買的行為。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"acknowledge the risk","meaning":"承認風險","examples":[{"en":"To acknowledge the risk is not to reject the policy.","zh":"承認風險並不等於拒絕該政策。"},{"en":"To acknowledge the risk means to admit that a possible problem exists.","zh":"承認風險意思是承認可能存在問題。"},{"en":"A manager can acknowledge the risk of abuse while still supporting fair returns.","zh":"管理人員可以承認濫用風險，同時仍支持公平退貨。"},{"en":"If we acknowledge the risk early, we can design safeguards.","zh":"如果我們及早承認風險，就能設計防範措施。"},{"en":"Honest proposals acknowledge the risk instead of pretending everything is safe.","zh":"誠實建議會承認風險，而不是假裝一切安全。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"concede that","meaning":"承認","examples":[{"en":"To acknowledge the risk is not to concede that the policy should remain unchanged.","zh":"承認風險並不等於承認政策應維持不變。"},{"en":"To concede that means to admit a point, often after argument or discussion.","zh":"concede that 意思是承認某一點，通常在爭論或討論後使用。"},{"en":"I concede that refunds can be costly, but they may still protect trust.","zh":"我承認退款可能成本高，但它們仍可能保障信任。"},{"en":"The company need not concede that strict rules are the only answer.","zh":"公司不必承認嚴格規則是唯一答案。"},{"en":"This phrase is useful when accepting part of the other side’s argument.","zh":"這個片語適合用於接受對方論點的一部分。"}],"source":"2021 Q3.pdf","sourcePage":10},{"front":"remain unchanged","meaning":"維持不變","examples":[{"en":"The policy should not remain unchanged simply because abuse is possible.","zh":"政策不應只因可能被濫用就維持不變。"},{"en":"Remain unchanged means stay the same without any revision.","zh":"維持不變意思是保持原樣，不作任何修訂。"},{"en":"A school rule should not remain unchanged if it keeps causing confusion.","zh":"如果校規一直造成混亂，就不應維持不變。"},{"en":"If customer complaints rise, the returns policy should not remain unchanged.","zh":"如果顧客投訴增加，退貨政策就不應維持不變。"},{"en":"Some parts can remain unchanged while unfair parts are improved.","zh":"某些部分可以維持不變，同時改善不公平的部分。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"prevent misuse","meaning":"防止濫用","examples":[{"en":"The company can prevent misuse by designing the policy carefully.","zh":"公司可以透過仔細設計政策來防止濫用。"},{"en":"To prevent misuse means to stop people from using a rule or system in the wrong way.","zh":"防止濫用意思是阻止人以錯誤方式使用規則或制度。"},{"en":"Asking for order numbers can prevent misuse of refund requests.","zh":"要求訂單編號可以防止退款申請被濫用。"},{"en":"Inspection after returns helps prevent misuse by dishonest customers.","zh":"退貨後檢查有助防止不誠實顧客濫用制度。"},{"en":"Preventing misuse is important, but it should not block fair cases.","zh":"防止濫用很重要，但不應阻礙合理個案。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"return request","meaning":"退貨申請","examples":[{"en":"Every return request should require an order number and a reason.","zh":"每宗退貨申請都應要求訂單編號和原因。"},{"en":"A return request is a customer’s application to send an item back.","zh":"退貨申請是顧客要求把貨品退回的申請。"},{"en":"A customer may submit a return request when the item arrives damaged.","zh":"當貨品送到時已損壞，顧客可能提交退貨申請。"},{"en":"Return requests should include enough information for staff to decide fairly.","zh":"退貨申請應包括足夠資料，讓員工公平決定。"},{"en":"Clear return requests reduce delays and misunderstandings.","zh":"清晰退貨申請可減少延誤和誤解。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"order number","meaning":"訂單編號","examples":[{"en":"Customers should provide an order number with every return request.","zh":"顧客每次退貨申請都應提供訂單編號。"},{"en":"An order number is a code that identifies a specific purchase.","zh":"訂單編號是識別特定購買紀錄的代碼。"},{"en":"Staff use the order number to check what the customer bought and when.","zh":"員工使用訂單編號檢查顧客購買了甚麼和何時購買。"},{"en":"Without an order number, false or mistaken return requests are harder to detect.","zh":"沒有訂單編號，虛假或錯誤退貨申請更難被發現。"},{"en":"Asking for an order number makes the return process more evidence-based.","zh":"要求訂單編號令退貨程序更以證據為本。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"where relevant","meaning":"在相關情況下","examples":[{"en":"Customers should provide clear photos where relevant.","zh":"顧客應在相關情況下提供清晰相片。"},{"en":"Where relevant means when it is suitable or connected to the case.","zh":"where relevant 意思是在適合或與個案有關時。"},{"en":"Customers should attach photos where relevant, such as when an item is defective.","zh":"顧客應在相關情況下附上相片，例如貨品有瑕疵時。"},{"en":"Staff may ask for measurements where relevant to a sizing problem.","zh":"對尺碼問題，員工可在相關情況下要求尺寸資料。"},{"en":"This phrase avoids asking for unnecessary evidence in every case.","zh":"這個片語避免在每個個案中要求不必要證據。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"clear photos","meaning":"清晰相片","examples":[{"en":"Clear photos can help prove that an item is defective.","zh":"清晰相片可以幫助證明貨品有瑕疵。"},{"en":"Clear photos are pictures that show the problem plainly and sharply.","zh":"清晰相片是清楚而銳利地顯示問題的圖片。"},{"en":"A customer may send clear photos of a broken zip before returning the dress.","zh":"顧客可能在退回裙子前發送壞拉鏈的清晰相片。"},{"en":"Blurry photos may not help staff inspect the problem.","zh":"模糊相片未必能幫助員工檢查問題。"},{"en":"Clear photos can speed up fair refund decisions.","zh":"清晰相片可以加快公平退款決定。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"refunds or credits","meaning":"退款或購物金","examples":[{"en":"Refunds or credits should be issued only after inspection.","zh":"退款或購物金只應在檢查後發出。"},{"en":"Refunds or credits mean money returned to the customer or value given for future shopping.","zh":"退款或購物金指退回給顧客的款項或供日後購物使用的金額。"},{"en":"A shop may offer refunds or credits depending on the seriousness of the case.","zh":"商店可根據個案嚴重程度提供退款或購物金。"},{"en":"Issuing refunds or credits before inspection may encourage abuse.","zh":"檢查前發出退款或購物金可能鼓勵濫用。"},{"en":"Clear rules help staff decide between refunds and credits.","zh":"清晰規則幫助員工決定退款還是購物金。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"issued only after","meaning":"只在……之後發出","examples":[{"en":"Refunds or credits should be issued only after staff inspect the item.","zh":"退款或購物金只應在員工檢查貨品後發出。"},{"en":"Issued only after means given or provided only when a later step has been completed.","zh":"issued only after 意思是只在之後某步驟完成後才給予或提供。"},{"en":"A library card may be issued only after the student proves their identity.","zh":"學生證明身份後，圖書證才可發出。"},{"en":"A refund should be issued only after the returned item is checked.","zh":"退款只應在退回貨品被檢查後發出。"},{"en":"This phrase makes the order of steps clear.","zh":"這個片語令步驟次序清晰。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"warehouse staff","meaning":"倉務職員","examples":[{"en":"Warehouse staff should inspect returned items carefully.","zh":"倉務職員應仔細檢查退回貨品。"},{"en":"Warehouse staff are workers who store, pack, check, and send goods.","zh":"倉務職員是負責儲存、包裝、檢查和寄送貨品的工人。"},{"en":"Warehouse staff may check whether tags are missing or the item is stained.","zh":"倉務職員可能檢查吊牌是否遺失或貨品是否有污漬。"},{"en":"If warehouse staff make mistakes, wrong items may be delivered.","zh":"如果倉務職員犯錯，貨品可能會送錯。"},{"en":"Clear inspection criteria help warehouse staff make fair decisions.","zh":"清晰檢查準則幫助倉務職員作出公平決定。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"inspect the item","meaning":"檢查貨品","examples":[{"en":"Staff should inspect the item for damage or stains.","zh":"員工應檢查貨品是否有損壞或污漬。"},{"en":"To inspect the item means to check it carefully before making a decision.","zh":"檢查貨品意思是在作出決定前仔細查看貨品。"},{"en":"Staff inspect the item to see whether the zip is defective.","zh":"員工檢查貨品，以查看拉鏈是否有瑕疵。"},{"en":"If staff do not inspect the item, they may approve unfair returns.","zh":"如果員工不檢查貨品，可能會批准不公平退貨。"},{"en":"Inspection protects both genuine customers and the company.","zh":"檢查保障真正有需要的顧客和公司。"}],"source":"2021 Q3.pdf","sourcePage":11},{"front":"missing tags","meaning":"吊牌遺失","examples":[{"en":"Items with missing tags should not normally qualify for return.","zh":"吊牌遺失的貨品通常不應符合退貨資格。"},{"en":"Missing tags are product labels or price tags that have been removed or lost.","zh":"吊牌遺失指產品標籤或價錢牌已被移除或不見了。"},{"en":"A dress with missing tags may have been worn already.","zh":"吊牌遺失的裙子可能已被穿過。"},{"en":"Missing tags make it harder for staff to resell the item.","zh":"吊牌遺失令員工更難重新出售貨品。"},{"en":"Customers should keep tags attached until they decide to keep the item.","zh":"顧客應在決定保留貨品前保留吊牌。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"make-up marks","meaning":"化妝痕跡","examples":[{"en":"Warehouse staff should check for stains, perfume and make-up marks.","zh":"倉務職員應檢查污漬、香水味和化妝痕跡。"},{"en":"Make-up marks are cosmetic stains left on clothing, such as foundation or lipstick.","zh":"化妝痕跡是留在衣物上的化妝品污漬，例如粉底或口紅。"},{"en":"A white blouse with make-up marks may not be suitable for resale.","zh":"有化妝痕跡的白襯衫可能不適合重新出售。"},{"en":"Make-up marks can show that an item was tried on carelessly or worn.","zh":"化妝痕跡可以顯示貨品曾被粗心試穿或穿過。"},{"en":"Inspection rules should mention make-up marks clearly.","zh":"檢查規則應清楚提及化妝痕跡。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"discretionary exchange","meaning":"酌情換貨","examples":[{"en":"Each discretionary exchange could be limited to two items.","zh":"每次酌情換貨可限於兩件貨品。"},{"en":"A discretionary exchange is an exchange allowed by staff judgement, not an automatic right.","zh":"酌情換貨是由員工按判斷批准的換貨，而不是自動權利。"},{"en":"A manager may approve a discretionary exchange for a loyal customer with a fair reason.","zh":"管理人員可因忠誠顧客有合理原因而批准酌情換貨。"},{"en":"Discretionary exchanges need limits so decisions do not become unfair.","zh":"酌情換貨需要限制，避免決定變得不公平。"},{"en":"Staff should record why each discretionary exchange was approved.","zh":"員工應記錄每次酌情換貨獲批准的原因。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"be limited to","meaning":"限於","examples":[{"en":"Each discretionary exchange could be limited to two items per customer.","zh":"每次酌情換貨可限於每名顧客兩件貨品。"},{"en":"Be limited to means be restricted to a certain number, amount, or group.","zh":"be limited to 意思是受限於某個數量、金額或群體。"},{"en":"The school trip is limited to thirty students because the bus is small.","zh":"因為巴士較小，學校旅行限於三十名學生。"},{"en":"Refunds may be limited to defective or wrongly delivered items.","zh":"退款可限於有瑕疵或送錯的貨品。"},{"en":"Limits make the policy easier to control.","zh":"限制令政策更容易控制。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"per customer","meaning":"每名顧客","examples":[{"en":"The limit could be two items per customer within thirty days.","zh":"限制可以是在三十日內每名顧客兩件貨品。"},{"en":"Per customer means for each individual customer.","zh":"per customer 意思是按每一位個別顧客計算。"},{"en":"The shop allows one discount code per customer.","zh":"商店容許每名顧客使用一個折扣碼。"},{"en":"A two-item limit per customer prevents one person from using too many returns.","zh":"每名顧客兩件貨品的限制可防止一個人使用太多退貨。"},{"en":"Per-customer limits make rules fairer across all buyers.","zh":"按每名顧客設定限制令規則對所有買家更公平。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"within thirty days","meaning":"三十日內","examples":[{"en":"The exchange limit could apply within thirty days.","zh":"換貨限制可在三十日內適用。"},{"en":"Within thirty days means before thirty days have passed.","zh":"三十日內意思是在三十天過去之前。"},{"en":"Customers must submit the return request within thirty days of delivery.","zh":"顧客必須在送貨後三十日內提交退貨申請。"},{"en":"If a request arrives after thirty days, it may not qualify.","zh":"如果申請在三十日後到達，可能不符合資格。"},{"en":"Clear time limits help both customers and staff know what is allowed.","zh":"清晰時限幫助顧客和員工知道甚麼被允許。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"unusual return patterns","meaning":"異常退貨模式","examples":[{"en":"Unusual return patterns should be flagged for review.","zh":"異常退貨模式應被標記作審查。"},{"en":"Unusual return patterns are repeated return behaviours that look different from normal customer behaviour.","zh":"異常退貨模式是看起來不同於正常顧客行為的重複退貨行為。"},{"en":"A customer returning ten dresses every month may show an unusual return pattern.","zh":"每月退回十條裙的顧客可能顯示異常退貨模式。"},{"en":"These patterns can suggest misuse, mistakes, or unclear product information.","zh":"這些模式可能顯示濫用、錯誤或產品資訊不清。"},{"en":"Reviewing unusual return patterns helps the company improve controls.","zh":"檢視異常退貨模式有助公司改善控制措施。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"flagged for review","meaning":"標記作審查","examples":[{"en":"Unusual return patterns should be flagged for review.","zh":"異常退貨模式應被標記作審查。"},{"en":"Flagged for review means marked so someone will check it more carefully later.","zh":"標記作審查意思是被標示出來，讓某人之後更仔細檢查。"},{"en":"A large refund request may be flagged for review by a manager.","zh":"大額退款申請可能被標記作審查，由經理處理。"},{"en":"If a customer makes many returns in one month, the account may be flagged for review.","zh":"如果顧客一個月內多次退貨，其帳戶可能被標記作審查。"},{"en":"Flagging cases for review helps prevent unfair or careless decisions.","zh":"標記個案作審查有助防止不公平或草率決定。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"better still","meaning":"更好的是","examples":[{"en":"Better still, the company could use tamper-evident tags.","zh":"更好的是，公司可以使用防拆封吊牌。"},{"en":"Better still means an even better idea is being added.","zh":"better still 意思是再加入一個更好的想法。"},{"en":"The shop could improve the size chart; better still, it could add real customer measurements.","zh":"商店可以改善尺碼表；更好的是，它可以加入真實顧客尺寸資料。"},{"en":"Staff could check returns manually; better still, the system could flag unusual patterns automatically.","zh":"員工可以手動檢查退貨；更好的是，系統可以自動標記異常模式。"},{"en":"This phrase helps introduce a stronger suggestion.","zh":"這個片語有助引入更強的建議。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"tamper-evident tags","meaning":"防拆封吊牌","examples":[{"en":"Tamper-evident tags could be used on higher-risk items.","zh":"防拆封吊牌可用於較高風險貨品。"},{"en":"Tamper-evident tags are labels that show clearly if someone has removed or changed them.","zh":"防拆封吊牌是能清楚顯示是否被移除或改動的標籤。"},{"en":"A dress with a broken tamper-evident tag may have been worn.","zh":"防拆封吊牌被破壞的裙子可能已被穿過。"},{"en":"These tags can reduce free wardrobe rental.","zh":"這些吊牌可以減少免費租衫。"},{"en":"Customers should be told that returns fail once tamper-evident tags are removed.","zh":"應告知顧客，防拆封吊牌一經移除便不能退貨。"}],"source":"2021 Q3.pdf","sourcePage":12},{"front":"higher-risk items","meaning":"較高風險貨品","examples":[{"en":"Higher-risk items may need tamper-evident tags.","zh":"較高風險貨品可能需要防拆封吊牌。"},{"en":"Higher-risk items are products more likely to be misused, damaged, or returned unfairly.","zh":"較高風險貨品是較可能被濫用、損壞或不公平退回的產品。"},{"en":"Expensive dresses for parties may be higher-risk items.","zh":"昂貴的派對裙可能是較高風險貨品。"},{"en":"The company can apply stricter checks to higher-risk items.","zh":"公司可對較高風險貨品實施更嚴格檢查。"},{"en":"Identifying higher-risk items helps protect profit without punishing all customers.","zh":"識別較高風險貨品有助保障利潤，而不懲罰所有顧客。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"once removed","meaning":"一經移除","examples":[{"en":"Once removed, the tag would no longer qualify the item for return.","zh":"吊牌一經移除，貨品便不再符合退貨資格。"},{"en":"Once removed means after something has been taken off.","zh":"once removed 意思是某物被取下之後。"},{"en":"Once removed, a hygiene seal may show that the item cannot be resold.","zh":"衞生封條一經移除，可能表示貨品不能重新出售。"},{"en":"Once removed, the tag proves the customer accepted the risk of keeping the item.","zh":"吊牌一經移除，便證明顧客接受保留貨品的風險。"},{"en":"This phrase makes the condition simple and clear.","zh":"這個片語令條件簡單清晰。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"no longer qualify for","meaning":"不再符合……資格","examples":[{"en":"Once the tag is removed, the item would no longer qualify for return.","zh":"吊牌一經移除，貨品便不再符合退貨資格。"},{"en":"No longer qualify for means no longer meet the conditions for something.","zh":"no longer qualify for 意思是不再符合某事的條件。"},{"en":"A late application may no longer qualify for a refund.","zh":"逾期申請可能不再符合退款資格。"},{"en":"Clothes with stains may no longer qualify for exchange.","zh":"有污漬的衣服可能不再符合換貨資格。"},{"en":"Clear rules tell customers when items no longer qualify for return.","zh":"清晰規則告訴顧客貨品何時不再符合退貨資格。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"tick an acknowledgement","meaning":"勾選確認聲明","examples":[{"en":"Customers should tick an acknowledgement of the return conditions.","zh":"顧客應勾選退貨條件確認聲明。"},{"en":"To tick an acknowledgement means to check a box showing that you have read and accepted something.","zh":"勾選確認聲明意思是剔選方格，表示已閱讀並接受某事。"},{"en":"Online shoppers may tick an acknowledgement before completing payment.","zh":"網上顧客可能在完成付款前勾選確認聲明。"},{"en":"This step makes it harder for customers to claim surprise later.","zh":"這一步令顧客較難事後聲稱不知情。"},{"en":"A ticked acknowledgement provides evidence that the rule was shown clearly.","zh":"已勾選的確認聲明提供證據，顯示規則已清楚展示。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"conditions at checkout","meaning":"結帳時的條款","examples":[{"en":"Customers should confirm the conditions at checkout.","zh":"顧客應確認結帳時的條款。"},{"en":"Conditions at checkout are the rules shown when customers are about to pay online.","zh":"結帳時的條款是在顧客即將網上付款時顯示的規則。"},{"en":"Return limits should appear in the conditions at checkout.","zh":"退貨限制應出現在結帳時的條款中。"},{"en":"If customers accept the conditions at checkout, they cannot easily claim surprise later.","zh":"如果顧客接受結帳時的條款，便不容易事後聲稱不知情。"},{"en":"Clear checkout conditions protect both the shop and the buyer.","zh":"清晰的結帳條款保障商店和買家。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"claim surprise later","meaning":"事後聲稱不知情","examples":[{"en":"Customers cannot claim surprise later if they have accepted the conditions.","zh":"如果顧客已接受條款，便不能事後聲稱不知情。"},{"en":"To claim surprise later means to say afterwards that you did not know about a rule.","zh":"事後聲稱不知情意思是之後說自己不知道某條規則。"},{"en":"A customer may claim surprise later if return limits were hidden.","zh":"如果退貨限制被隱藏，顧客可能事後聲稱不知情。"},{"en":"Clear checkout warnings stop customers from claiming surprise later.","zh":"清晰的結帳提示可防止顧客事後聲稱不知情。"},{"en":"The company should make rules visible so this argument does not arise.","zh":"公司應令規則清楚可見，避免這種爭論出現。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"all things considered","meaning":"綜合而言","examples":[{"en":"All things considered, Chris recommends a three-month pilot.","zh":"綜合而言，Chris 建議進行三個月試行計劃。"},{"en":"All things considered means after thinking about all the important points.","zh":"all things considered 意思是在考慮所有重要因素後。"},{"en":"All things considered, a controlled policy is safer than a blanket ban.","zh":"綜合而言，受控政策比一刀切禁令更安全。"},{"en":"All things considered, the company should test the change before making it permanent.","zh":"綜合而言，公司應先測試改變，再作永久決定。"},{"en":"This phrase is useful for giving a final balanced judgement.","zh":"這個片語適合用來提出最後的平衡判斷。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"strongly recommend","meaning":"強烈建議","examples":[{"en":"Chris strongly recommends a three-month pilot.","zh":"Chris 強烈建議進行三個月試行計劃。"},{"en":"To strongly recommend means to advise something clearly and firmly.","zh":"強烈建議意思是清楚而堅定地提出建議。"},{"en":"A doctor may strongly recommend rest if a patient is seriously tired.","zh":"如果病人非常疲倦，醫生可能強烈建議休息。"},{"en":"Chris strongly recommends testing the new returns policy before full adoption.","zh":"Chris 強烈建議在全面採用前測試新的退貨政策。"},{"en":"This phrase shows confidence but still sounds professional.","zh":"這個片語顯示信心，同時仍然專業。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"three-month pilot","meaning":"三個月試行計劃","examples":[{"en":"The company should run a three-month pilot of the revised policy.","zh":"公司應進行為期三個月的經修訂政策試行計劃。"},{"en":"A three-month pilot is a short test of a new idea for three months.","zh":"三個月試行計劃是對新想法進行三個月的短期測試。"},{"en":"A school may run a three-month pilot before changing its timetable permanently.","zh":"學校可能在永久改變時間表前進行三個月試行計劃。"},{"en":"During the pilot, the company can collect data on complaints and returns.","zh":"試行期間，公司可收集投訴和退貨數據。"},{"en":"A pilot reduces risk because managers can adjust the policy before final approval.","zh":"試行計劃可降低風險，因為管理層可在最終批准前調整政策。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"revised policy","meaning":"經修訂的政策","examples":[{"en":"The revised policy could reduce distrust.","zh":"經修訂的政策可以減少不信任。"},{"en":"A revised policy is a policy that has been changed after review.","zh":"經修訂的政策是經檢討後已被改變的政策。"},{"en":"The revised policy may allow one exchange within fourteen days.","zh":"經修訂的政策可能容許十四日內一次換貨。"},{"en":"If the revised policy is clear, staff can explain it more easily.","zh":"如果經修訂的政策清晰，員工可以更容易解釋。"},{"en":"A revised policy should solve old problems without creating serious new ones.","zh":"經修訂的政策應解決舊問題，而不製造嚴重新問題。"}],"source":"2021 Q3.pdf","sourcePage":13},{"front":"protect our margins","meaning":"保障我們的利潤率","examples":[{"en":"The original rule was introduced to protect our margins.","zh":"原有規則是為了保障我們的利潤率而引入的。"},{"en":"To protect our margins means to keep enough profit after costs are paid.","zh":"保障我們的利潤率意思是在支付成本後仍保留足夠利潤。"},{"en":"A shop protects its margins by controlling return costs.","zh":"商店透過控制退貨成本來保障利潤率。"},{"en":"Too many cash refunds may make it harder to protect our margins.","zh":"太多現金退款可能令保障利潤率更困難。"},{"en":"Protecting margins matters, but not at the cost of losing customer trust.","zh":"保障利潤率很重要，但不應以失去顧客信任為代價。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"the way things are going","meaning":"按目前情況來看","examples":[{"en":"The way things are going, the current rule is creating distrust.","zh":"按目前情況來看，現行規則正在造成不信任。"},{"en":"The way things are going means judging from the present trend or situation.","zh":"the way things are going 意思是根據目前趨勢或情況判斷。"},{"en":"The way things are going, more customers may leave negative reviews.","zh":"按目前情況來看，更多顧客可能留下負面評價。"},{"en":"The way things are going, the company should act before the problem grows.","zh":"按目前情況來看，公司應在問題擴大前行動。"},{"en":"This phrase suggests that current signs point to a likely result.","zh":"這個片語表示目前跡象指向某個可能結果。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"a source of avoidable distrust","meaning":"可避免的不信任來源","examples":[{"en":"The strict rule is becoming a source of avoidable distrust.","zh":"嚴格規則正成為可避免的不信任來源。"},{"en":"A source of avoidable distrust is something that unnecessarily makes people lose trust.","zh":"可避免的不信任來源是指不必要地令人失去信任的事情。"},{"en":"Hidden fees can become a source of avoidable distrust in online shopping.","zh":"隱藏收費可能成為網購中的可避免不信任來源。"},{"en":"A confusing refund rule creates avoidable distrust because customers feel tricked.","zh":"混亂退款規則造成可避免的不信任，因為顧客覺得被欺騙。"},{"en":"The company should remove problems that create distrust when they can be fixed.","zh":"公司應移除可以修正卻造成不信任的問題。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"adopt a controlled system","meaning":"採用受控的制度","examples":[{"en":"The company should adopt a controlled exchange and refund system.","zh":"公司應採用受控的換貨及退款制度。"},{"en":"To adopt a controlled system means to start using a system with clear rules and limits.","zh":"採用受控的制度意思是開始使用有清晰規則和限制的制度。"},{"en":"A school may adopt a controlled system for borrowing laptops.","zh":"學校可能採用受控的制度來借出手提電腦。"},{"en":"Fast Fashion can adopt a controlled system to help fair cases while preventing abuse.","zh":"Fast Fashion 可以採用受控的制度，以幫助合理個案並防止濫用。"},{"en":"Adoption should come with staff training and clear procedures.","zh":"採用制度時應配合員工培訓和清晰程序。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"customer service","meaning":"客戶服務","examples":[{"en":"The sales, customer service and warehouse teams should agree on procedures.","zh":"銷售、客戶服務和倉務團隊應就程序達成共識。"},{"en":"Customer service is the support given to customers before, during, and after buying.","zh":"客戶服務是在購買前、購買時和購買後提供給顧客的支援。"},{"en":"Customer service staff answer questions, handle complaints, and explain policies.","zh":"客戶服務員工回答問題、處理投訴和解釋政策。"},{"en":"Poor customer service can turn a small return problem into a serious argument.","zh":"差劣客戶服務可以把小退貨問題變成嚴重爭拗。"},{"en":"Good customer service helps customers feel heard and respected.","zh":"良好客戶服務令顧客感到被聆聽和尊重。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"standard scripts","meaning":"標準應對稿","examples":[{"en":"The teams should agree on standard scripts for handling return requests.","zh":"各團隊應就處理退貨申請的標準應對稿達成共識。"},{"en":"Standard scripts are prepared words that staff can use when explaining common situations.","zh":"標準應對稿是員工解釋常見情況時可使用的預備說法。"},{"en":"Customer service staff may use standard scripts to explain refund limits politely.","zh":"客戶服務員工可使用標準應對稿有禮貌地解釋退款限制。"},{"en":"Standard scripts help different staff give consistent answers.","zh":"標準應對稿幫助不同員工給出一致答案。"},{"en":"Scripts should sound helpful, not cold or robotic.","zh":"應對稿應聽起來有幫助，而不是冷漠或機械化。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"inspection criteria","meaning":"檢查準則","examples":[{"en":"Warehouse staff need clear inspection criteria.","zh":"倉務職員需要清晰檢查準則。"},{"en":"Inspection criteria are the rules staff use to decide whether an item passes checking.","zh":"檢查準則是員工用來判斷貨品是否通過檢查的規則。"},{"en":"Criteria may include tags, stains, damage, odour, and signs of wear.","zh":"準則可包括吊牌、污漬、損壞、氣味和穿著痕跡。"},{"en":"Without inspection criteria, staff may make inconsistent decisions.","zh":"沒有檢查準則，員工可能作出不一致決定。"},{"en":"Clear criteria make return decisions fairer and easier to explain.","zh":"清晰準則令退貨決定更公平，也更容易解釋。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"reporting procedures","meaning":"匯報程序","examples":[{"en":"The teams should agree on reporting procedures.","zh":"各團隊應就匯報程序達成共識。"},{"en":"Reporting procedures are steps for recording and sharing important information.","zh":"匯報程序是記錄和分享重要資訊的步驟。"},{"en":"Staff may follow reporting procedures when complaints increase suddenly.","zh":"當投訴突然增加時，員工可按照匯報程序處理。"},{"en":"Clear reporting procedures help managers review return rates and complaint volume.","zh":"清晰匯報程序幫助管理層檢視退貨率和投訴量。"},{"en":"Without reporting procedures, useful evidence may be lost.","zh":"沒有匯報程序，有用證據可能流失。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"review complaint volume","meaning":"檢視投訴量","examples":[{"en":"After the pilot, the company can review complaint volume.","zh":"試行後，公司可以檢視投訴量。"},{"en":"To review complaint volume means to examine how many complaints were received.","zh":"檢視投訴量意思是查看收到多少投訴。"},{"en":"Managers may review complaint volume each month to see whether the policy works.","zh":"管理層可每月檢視投訴量，以了解政策是否有效。"},{"en":"If complaint volume falls, the revised policy may be successful.","zh":"如果投訴量下降，經修訂政策可能是成功的。"},{"en":"Reviewing complaint volume helps the company make decisions based on data.","zh":"檢視投訴量幫助公司根據數據作決定。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"repeat purchases","meaning":"回購","examples":[{"en":"The company should review repeat purchases after the pilot.","zh":"公司應在試行後檢視回購情況。"},{"en":"Repeat purchases are later purchases made by customers who have bought before.","zh":"回購是曾經購買的顧客之後再次購買。"},{"en":"A fair returns policy can encourage repeat purchases.","zh":"公平退貨政策可以鼓勵回購。"},{"en":"If repeat purchases fall, customers may be losing trust.","zh":"如果回購下降，顧客可能正在失去信任。"},{"en":"Repeat purchases show whether customers are willing to come back.","zh":"回購顯示顧客是否願意再次光顧。"}],"source":"2021 Q3.pdf","sourcePage":14},{"front":"return rates","meaning":"退貨率","examples":[{"en":"The company should monitor return rates during the pilot.","zh":"公司應在試行期間監察退貨率。"},{"en":"Return rates show the percentage or number of sold items that customers return.","zh":"退貨率顯示售出貨品中被顧客退回的比例或數量。"},{"en":"High return rates may suggest sizing problems or unclear descriptions.","zh":"高退貨率可能表示尺碼問題或描述不清。"},{"en":"If return rates rise too much, the company may need stronger safeguards.","zh":"如果退貨率上升太多，公司可能需要更強防範措施。"},{"en":"Return rates should be studied together with complaints and repeat purchases.","zh":"退貨率應與投訴和回購一起研究。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"make a permanent decision","meaning":"作出永久決定","examples":[{"en":"The company can make a permanent decision after reviewing the data.","zh":"公司可以在檢視數據後作出永久決定。"},{"en":"To make a permanent decision means to choose a long-term action after careful thought.","zh":"作出永久決定意思是在仔細考慮後選擇長期做法。"},{"en":"A school may make a permanent decision after testing a new timetable.","zh":"學校可能在測試新時間表後作出永久決定。"},{"en":"Fast Fashion should not make a permanent decision before checking pilot results.","zh":"Fast Fashion 不應在檢查試行結果前作出永久決定。"},{"en":"Data helps managers decide whether the revised policy should continue.","zh":"數據幫助管理層決定經修訂政策是否應繼續。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"what matters is balance","meaning":"重要的是取得平衡","examples":[{"en":"What matters is balance between fairness and control.","zh":"重要的是在公平與控制之間取得平衡。"},{"en":"What matters is balance means the most important thing is to avoid going too far in either direction.","zh":"重要的是取得平衡意思是最重要的是避免走向任何一個極端。"},{"en":"In school discipline, what matters is balance between rules and understanding.","zh":"在學校紀律中，重要的是在規則和理解之間取得平衡。"},{"en":"In returns policy, what matters is balance between helping customers and preventing abuse.","zh":"在退貨政策中，重要的是在幫助顧客和防止濫用之間取得平衡。"},{"en":"This phrase gives a clear final principle.","zh":"這個片語提出清晰的最後原則。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"firm against abuse","meaning":"對濫用行為堅決","examples":[{"en":"The company should be firm against abuse.","zh":"公司應對濫用行為堅決。"},{"en":"Firm against abuse means clear and strict when people try to misuse the system.","zh":"對濫用行為堅決意思是當人試圖濫用制度時清楚而嚴格。"},{"en":"Staff should be firm against abuse when items are worn and returned dishonestly.","zh":"當貨品被穿過後不誠實退回，員工應對濫用行為堅決。"},{"en":"Being firm against abuse protects honest customers too.","zh":"對濫用行為堅決也能保護誠實顧客。"},{"en":"A company can be firm against abuse while still polite to customers.","zh":"公司可以對濫用行為堅決，同時仍對顧客有禮。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"fair to honest customers","meaning":"對誠實顧客公平","examples":[{"en":"The company should be fair to honest customers.","zh":"公司應對誠實顧客公平。"},{"en":"Fair to honest customers means treating genuine buyers reasonably when they have real problems.","zh":"對誠實顧客公平意思是在真正買家遇到真實問題時合理對待他們。"},{"en":"A refund for a wrongly delivered item is fair to honest customers.","zh":"對送錯貨品提供退款是對誠實顧客公平。"},{"en":"If rules are too strict, the company may punish honest customers by mistake.","zh":"如果規則太嚴格，公司可能錯誤懲罰誠實顧客。"},{"en":"The best policy is firm against abuse but fair to honest customers.","zh":"最好的政策是對濫用行為堅決，但對誠實顧客公平。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"raise this proposal","meaning":"提出這項建議","examples":[{"en":"Chris asks Ms Lin to raise this proposal at the next meeting.","zh":"Chris 請林女士在下次會議提出這項建議。"},{"en":"To raise this proposal means to bring up the suggestion for discussion.","zh":"提出這項建議意思是把建議帶出來討論。"},{"en":"A staff member may raise this proposal with managers after receiving many complaints.","zh":"員工在收到許多投訴後，可能向管理層提出這項建議。"},{"en":"If the proposal is raised at the meeting, different teams can give feedback.","zh":"如果這項建議在會議上提出，不同團隊可以給予意見。"},{"en":"Raising a proposal is the first step before approval.","zh":"提出建議是獲批准前的第一步。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"management meeting","meaning":"管理層會議","examples":[{"en":"Chris hopes the proposal will be discussed at the next management meeting.","zh":"Chris 希望這項建議會在下次管理層會議上討論。"},{"en":"A management meeting is a meeting where managers discuss decisions, problems, and plans.","zh":"管理層會議是管理人員討論決定、問題和計劃的會議。"},{"en":"A returns policy change should be discussed at a management meeting before it is approved.","zh":"退貨政策改變在批准前應在管理層會議上討論。"},{"en":"Sales, customer service, and warehouse problems can all be raised in a management meeting.","zh":"銷售、客戶服務和倉務問題都可以在管理層會議上提出。"},{"en":"Management meetings help different leaders agree on the next step.","zh":"管理層會議幫助不同領導者就下一步達成共識。"}],"source":"2021 Q3.pdf","sourcePage":15},{"front":"Yours sincerely","meaning":"謹啟","examples":[{"en":"Chris closes the letter with Yours sincerely.","zh":"Chris 以「謹啟」結束信件。"},{"en":"Yours sincerely is a polite ending used in formal letters, especially when the writer knows the recipient’s name.","zh":"Yours sincerely 是正式信件中有禮貌的結尾，尤其用於知道收信人姓名時。"},{"en":"A staff member may write “Yours sincerely” before signing a proposal letter.","zh":"員工可能在簽署建議信前寫上 “Yours sincerely”。"},{"en":"This ending shows respect and keeps the tone professional.","zh":"這個結尾顯示尊重，並保持語氣專業。"},{"en":"In a business letter, “Yours sincerely” is more formal than “Best”.","zh":"在商業信件中，“Yours sincerely” 比 “Best” 更正式。"}],"source":"2021 Q3.pdf","sourcePage":15}],"dse/writing/part-b/2021/Q4":[{"front":"apply for the position of","meaning":"申請……職位","examples":[{"en":"I am writing to apply for the position of Assistant Coach.","zh":"我寫信申請助理教練一職。"},{"en":"To apply for the position of something means to formally ask to be considered for that job.","zh":"apply for the position of 某職位，意思是正式要求被考慮擔任該工作。"},{"en":"A student may apply for the position of library helper by filling in a school form.","zh":"學生可以透過填寫學校表格申請圖書館助手一職。"},{"en":"People usually apply for the position of a job when they believe their skills match the duties.","zh":"人們通常在相信自己的技能符合職責時，申請某個職位。"},{"en":"Before you apply for the position of team leader, you should understand what responsibilities it includes.","zh":"在申請組長一職之前，你應該了解該職位包括甚麼責任。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"Assistant Coach","meaning":"助理教練","examples":[{"en":"Chris Wong is applying for the position of Assistant Coach.","zh":"Chris Wong 正在申請助理教練一職。"},{"en":"An Assistant Coach helps the main coach train players, plan practice, and support the team.","zh":"助理教練協助主教練訓練隊員、計劃練習和支援隊伍。"},{"en":"In a school football team, an Assistant Coach may warm up students before the head coach arrives.","zh":"在學校足球隊中，助理教練可能在主教練到達前帶學生熱身。"},{"en":"A good Assistant Coach can help athletes improve because they receive more individual attention.","zh":"好的助理教練能幫助運動員進步，因為他們可以得到更多個別關注。"},{"en":"An Assistant Coach is not just a helper; they often guide young athletes directly.","zh":"助理教練不只是助手；他們常常直接指導年輕運動員。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"having spent","meaning":"在……之後；花了……之後","examples":[{"en":"Having spent twelve years as a professional runner, he is seeking a career change.","zh":"在當了十二年職業跑手之後，他正在尋求轉行。"},{"en":"Having spent means after spending time doing something or experiencing something.","zh":"having spent 的意思是在花時間做某事或經歷某事之後。"},{"en":"Having spent the whole afternoon studying, the student felt ready for the test.","zh":"花了一整個下午溫習之後，這名學生覺得自己已準備好考試。"},{"en":"Having spent many years in one field, people may want to use their experience in a new way.","zh":"在某個領域多年之後，人們可能想以新方式運用自己的經驗。"},{"en":"Having spent a long time on a task, you usually understand its difficulties better.","zh":"花了很長時間做一項任務後，你通常會更了解其中的困難。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"professional middle-distance runner","meaning":"職業中距離跑手","examples":[{"en":"He spent twelve years as a professional middle-distance runner.","zh":"他做了十二年職業中距離跑手。"},{"en":"A professional middle-distance runner is paid to compete in races such as 800 metres or 1,500 metres.","zh":"職業中距離跑手是受薪參加例如八百米或一千五百米比賽的運動員。"},{"en":"A professional middle-distance runner must train both speed and endurance.","zh":"職業中距離跑手必須同時訓練速度和耐力。"},{"en":"Because middle-distance races are fast but not short, runners need careful pacing.","zh":"因為中距離賽跑速度快但不是短跑，跑手需要仔細控制步速。"},{"en":"A professional middle-distance runner lives with regular training, competitions, recovery, and pressure.","zh":"職業中距離跑手的生活包括定期訓練、比賽、恢復和壓力。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"seek a career change","meaning":"尋求轉行；轉換事業方向","examples":[{"en":"He is now seeking a career change in elite sport.","zh":"他現在正尋求在精英體育中轉換事業方向。"},{"en":"To seek a career change means to look for a new type of work or professional direction.","zh":"seek a career change 的意思是尋找新的工作類型或職業方向。"},{"en":"A nurse may seek a career change into health education after years in hospitals.","zh":"一名護士在醫院工作多年後，可能尋求轉到健康教育工作。"},{"en":"People often seek a career change when their interests, health, or life goals change.","zh":"當興趣、健康或人生目標改變時，人們常會尋求轉行。"},{"en":"Seeking a career change does not mean wasting past experience; it can mean using it differently.","zh":"尋求轉行不代表浪費過去經驗；它可以代表以不同方式運用經驗。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"remain in the world of","meaning":"留在……的領域","examples":[{"en":"He wants to remain in the world of elite sport.","zh":"他想留在精英體育的領域。"},{"en":"To remain in the world of something means to continue working or being involved in that area.","zh":"remain in the world of 某領域，意思是繼續在該範疇工作或參與其中。"},{"en":"A retired teacher may remain in the world of education by training new teachers.","zh":"退休老師可以透過培訓新老師，留在教育界。"},{"en":"People remain in the world of an industry when they still care about its work and community.","zh":"當人們仍關心某行業的工作和社群時，他們會留在該領域。"},{"en":"Remaining in the world of sport allows former athletes to support others after retirement.","zh":"留在體育界讓退役運動員能在退役後支援其他人。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"elite sport","meaning":"精英體育","examples":[{"en":"He hopes to continue working in the world of elite sport.","zh":"他希望繼續在精英體育界工作。"},{"en":"Elite sport refers to sport at a very high level, often involving top athletes and serious competition.","zh":"elite sport 指非常高水平的體育，通常涉及頂尖運動員和嚴肅比賽。"},{"en":"Olympic training centres are part of elite sport because athletes prepare for international events there.","zh":"奧運訓練中心屬於精英體育的一部分，因為運動員在那裡備戰國際賽事。"},{"en":"Elite sport requires strong coaching, medical support, discipline, and long-term planning.","zh":"精英體育需要強大的教練、醫療支援、紀律和長遠規劃。"},{"en":"Elite sport can be exciting, but it also brings pressure, injuries, and sacrifice.","zh":"精英體育可以令人興奮，但也帶來壓力、傷患和犧牲。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"contribute more directly to","meaning":"更直接地貢獻於……","examples":[{"en":"He wants to contribute more directly to the development of other athletes.","zh":"他想更直接地貢獻於其他運動員的發展。"},{"en":"To contribute more directly to something means to help it in a clear and active way.","zh":"contribute more directly to 某事，意思是以清楚而積極的方式幫助它。"},{"en":"A parent can contribute more directly to a school by joining the parent committee.","zh":"家長可以透過加入家長委員會，更直接地貢獻於學校。"},{"en":"Coaches contribute more directly to athletes when they give personal advice, not only general encouragement.","zh":"教練提供個人建議，而不只是一般鼓勵時，會更直接地幫助運動員。"},{"en":"If you want to contribute more directly to a cause, you may volunteer instead of only donating money.","zh":"如果你想更直接地貢獻於某個理念，你可以做義工，而不只是捐錢。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"the development of other athletes","meaning":"其他運動員的發展","examples":[{"en":"Coaching allows him to support the development of other athletes.","zh":"教練工作讓他能支援其他運動員的發展。"},{"en":"The development of other athletes means helping athletes improve their skills, confidence, habits, and performance.","zh":"the development of other athletes 指幫助運動員提升技能、信心、習慣和表現。"},{"en":"Senior players can support the development of other athletes by sharing training advice.","zh":"資深隊員可以透過分享訓練建議，支援其他運動員的發展。"},{"en":"Without good guidance, the development of other athletes may be slow or uneven.","zh":"沒有良好指導，其他運動員的發展可能會緩慢或不平均。"},{"en":"Supporting the development of other athletes is about long-term growth, not only winning one race.","zh":"支援其他運動員的發展，是關於長遠成長，而不只是贏一場比賽。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"high-performance sport","meaning":"高水平競技體育","examples":[{"en":"High-performance sport requires talent, discipline and support.","zh":"高水平競技體育需要天分、紀律和支援。"},{"en":"High-performance sport means competitive sport where athletes train seriously to reach top results.","zh":"high-performance sport 指運動員認真訓練以達到頂尖成績的競技體育。"},{"en":"A high-performance sport programme may include coaching, nutrition, psychology, and medical care.","zh":"高水平競技體育計劃可能包括教練、營養、心理和醫療照顧。"},{"en":"Athletes in high-performance sport can improve faster when their training and recovery are planned carefully.","zh":"在高水平競技體育中，如果訓練和恢復安排得宜，運動員可以更快進步。"},{"en":"High-performance sport is different from casual exercise because the aim is peak performance.","zh":"高水平競技體育不同於休閒運動，因為目標是最佳表現。"}],"source":"2021 Q4.pdf","sourcePage":1},{"front":"talent alone","meaning":"單靠天分","examples":[{"en":"Talent alone is not enough in high-performance sport.","zh":"在高水平競技體育中，單靠天分是不足夠的。"},{"en":"Talent alone means natural ability without enough effort, support, or training.","zh":"talent alone 指只有天生能力，卻沒有足夠努力、支援或訓練。"},{"en":"A clever student may fail if they rely on talent alone and never revise.","zh":"聰明學生如果單靠天分而從不溫習，也可能失敗。"},{"en":"Talent alone can disappear in competition if an athlete lacks discipline and preparation.","zh":"如果運動員缺乏紀律和準備，單靠天分在比賽中可能不夠。"},{"en":"Success usually needs talent, practice, feedback, and patience, not talent alone.","zh":"成功通常需要天分、練習、回饋和耐性，而不是單靠天分。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"the environment in which","meaning":"……所在的環境","examples":[{"en":"The environment in which athletes train is very important.","zh":"運動員訓練所在的環境非常重要。"},{"en":"The environment in which something happens means the place, people, rules, and conditions around it.","zh":"the environment in which 某事發生，意思是圍繞它的地方、人、規則和條件。"},{"en":"The environment in which children study affects their concentration and confidence.","zh":"孩子學習所在的環境會影響他們的專注力和信心。"},{"en":"If the environment in which workers work is unsafe, mistakes and injuries may increase.","zh":"如果員工工作的環境不安全，錯誤和受傷可能會增加。"},{"en":"The environment in which athletes grow can shape both their performance and character.","zh":"運動員成長所在的環境，能塑造他們的表現和品格。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"trained, tested and protected","meaning":"受訓練、受考驗和受保護","examples":[{"en":"Young athletes need to be trained, tested and protected.","zh":"年輕運動員需要受訓練、受考驗和受保護。"},{"en":"Trained, tested and protected means athletes are taught skills, challenged safely, and kept from unnecessary harm.","zh":"trained, tested and protected 指運動員被教授技能、被安全地挑戰，並避免不必要傷害。"},{"en":"New lifeguards must be trained, tested and protected before they work at a busy pool.","zh":"新救生員在繁忙泳池工作前，必須受訓練、受考驗和受保護。"},{"en":"If young people are tested without being protected, pressure may damage their confidence.","zh":"如果年輕人只受考驗而沒有受保護，壓力可能會損害他們的信心。"},{"en":"Good programmes do not only train athletes; they make sure they are trained, tested and protected.","zh":"好的計劃不只訓練運動員；它確保他們受訓練、受考驗和受保護。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"athletic background","meaning":"運動員背景","examples":[{"en":"His athletic background helps him understand the needs of athletes.","zh":"他的運動員背景幫助他理解運動員的需要。"},{"en":"An athletic background means past experience in sport, training, and competition.","zh":"athletic background 指過去在體育、訓練和比賽方面的經驗。"},{"en":"A teacher with an athletic background may understand why students need rest after hard training.","zh":"有運動員背景的老師可能明白學生在艱苦訓練後為何需要休息。"},{"en":"An athletic background can help a coach explain advice from real experience.","zh":"運動員背景可以幫助教練用真實經驗解釋建議。"},{"en":"Having an athletic background is useful, but good communication is also necessary.","zh":"有運動員背景很有用，但良好溝通也同樣必要。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"practical knowledge of competition","meaning":"實戰比賽知識","examples":[{"en":"He has practical knowledge of competition from his running career.","zh":"他從跑步生涯中獲得實戰比賽知識。"},{"en":"Practical knowledge of competition means real understanding gained by taking part in contests, not only reading about them.","zh":"practical knowledge of competition 指透過真正參與比賽得到的理解，而不只是從書本得來。"},{"en":"A former swimmer has practical knowledge of competition because they know how nerves feel before a race.","zh":"前游泳選手有實戰比賽知識，因為他們知道賽前緊張的感覺。"},{"en":"Practical knowledge of competition helps coaches prepare athletes for pressure and mistakes.","zh":"實戰比賽知識幫助教練讓運動員準備面對壓力和失誤。"},{"en":"Books can teach rules, but practical knowledge of competition teaches timing, fear, and decision-making.","zh":"書本可以教授規則，但實戰比賽知識教會人時機、恐懼和決策。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"commitment to youth development","meaning":"對青年發展的承諾","examples":[{"en":"He has a strong commitment to youth development.","zh":"他對青年發展有強烈承諾。"},{"en":"Commitment to youth development means a serious desire to help young people grow and succeed.","zh":"commitment to youth development 指認真希望幫助年輕人成長和成功。"},{"en":"A school shows commitment to youth development by offering clubs, counselling, and career advice.","zh":"學校提供社團、輔導和職業建議，就是展現對青年發展的承諾。"},{"en":"Without commitment to youth development, talented teenagers may lose direction.","zh":"沒有對青年發展的承諾，有才華的青少年可能會失去方向。"},{"en":"Commitment to youth development requires patience because young people grow at different speeds.","zh":"對青年發展的承諾需要耐性，因為年輕人成長速度不同。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"be well suited to","meaning":"非常適合","examples":[{"en":"He believes he is well suited to support the Foundation’s mission.","zh":"他相信自己非常適合支持基金會的使命。"},{"en":"To be well suited to something means to be a good match for a role, task, or situation.","zh":"be well suited to 某事，意思是非常適合某個角色、任務或情況。"},{"en":"A patient person may be well suited to teaching young children.","zh":"有耐性的人可能非常適合教導年幼孩子。"},{"en":"People are well suited to a job when their skills and personality fit its demands.","zh":"當一個人的技能和性格符合工作要求時，他就非常適合該工作。"},{"en":"Being well suited to a role does not mean it is easy; it means you have the right qualities.","zh":"非常適合某個角色不代表它容易；而是代表你具備合適特質。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"support the Foundation’s mission","meaning":"支持基金會的使命","examples":[{"en":"He hopes to support the Foundation’s mission through coaching.","zh":"他希望透過教練工作支持基金會的使命。"},{"en":"To support the Foundation’s mission means to help the organisation achieve its main purpose.","zh":"support the Foundation’s mission 指幫助該組織實現其主要目的。"},{"en":"Volunteers support a charity’s mission when they help with events and services.","zh":"義工協助活動和服務時，就是支持慈善機構的使命。"},{"en":"Staff can support the Foundation’s mission by turning its values into daily action.","zh":"員工可以透過把價值轉化為日常行動，支持基金會的使命。"},{"en":"Supporting the Foundation’s mission is stronger when people understand why the mission matters.","zh":"當人們明白使命為何重要時，支持基金會的使命會更有力量。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"by way of background","meaning":"作為背景資料","examples":[{"en":"By way of background, he began formal athletics training at thirteen.","zh":"作為背景資料，他十三歲開始接受正規田徑訓練。"},{"en":"By way of background is used to introduce useful information about someone’s past experience.","zh":"by way of background 用來介紹某人過去經驗中的有用資料。"},{"en":"By way of background, the new teacher worked in a community centre before joining the school.","zh":"作為背景資料，這位新老師加入學校前曾在社區中心工作。"},{"en":"People use by way of background when they want the reader to understand later details more clearly.","zh":"人們使用 by way of background，是為了讓讀者更清楚理解後面的細節。"},{"en":"In an application letter, by way of background helps connect past experience to the job.","zh":"在求職信中，by way of background 有助把過去經驗連繫到工作。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"formal athletics training","meaning":"正規田徑訓練","examples":[{"en":"He began formal athletics training at the age of thirteen.","zh":"他十三歲開始接受正規田徑訓練。"},{"en":"Formal athletics training means organised sports training with clear coaching, schedules, and goals.","zh":"formal athletics training 指有清楚教練、時間表和目標的有組織田徑訓練。"},{"en":"A child may start formal athletics training after joining a school running club.","zh":"孩子加入學校跑步隊後，可能開始接受正規田徑訓練。"},{"en":"Formal athletics training helps young athletes learn correct technique before bad habits form.","zh":"正規田徑訓練幫助年輕運動員在形成壞習慣前學習正確技術。"},{"en":"Informal running builds interest, but formal athletics training builds structure.","zh":"非正式跑步能建立興趣，但正規田徑訓練能建立結構。"}],"source":"2021 Q4.pdf","sourcePage":2},{"front":"at the age of","meaning":"在……歲時","examples":[{"en":"He began training at the age of thirteen.","zh":"他在十三歲時開始訓練。"},{"en":"At the age of means when someone was a particular age.","zh":"at the age of 的意思是在某人某個年齡的時候。"},{"en":"She learned to swim at the age of six.","zh":"她在六歲時學會游泳。"},{"en":"People often mention at the age of something when describing important life stages.","zh":"人們描述重要人生階段時，常會用 at the age of。"},{"en":"At the age of eighteen, many students begin making more independent decisions.","zh":"在十八歲時，許多學生開始作出更獨立的決定。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"represent Hong Kong","meaning":"代表香港","examples":[{"en":"He later represented Hong Kong in international competitions.","zh":"他後來在國際比賽中代表香港。"},{"en":"To represent Hong Kong means to compete, speak, or act on behalf of Hong Kong.","zh":"represent Hong Kong 指代表香港參賽、發言或行動。"},{"en":"A student may represent Hong Kong in a science competition overseas.","zh":"學生可能在海外科學比賽中代表香港。"},{"en":"Athletes who represent Hong Kong carry personal hopes and public expectations.","zh":"代表香港的運動員承載個人希望和公眾期望。"},{"en":"Representing Hong Kong is an honour, but it also requires discipline and responsibility.","zh":"代表香港是一種榮譽，但也需要紀律和責任感。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"regional and international competitions","meaning":"區域及國際比賽","examples":[{"en":"He competed in regional and international competitions.","zh":"他參加過區域及國際比賽。"},{"en":"Regional and international competitions are contests held between areas, countries, or teams from different places.","zh":"regional and international competitions 指不同地區、國家或隊伍之間舉行的比賽。"},{"en":"A debate team may first join regional competitions before entering international ones.","zh":"辯論隊可能先參加區域比賽，再參加國際比賽。"},{"en":"Regional and international competitions expose participants to higher standards and different styles.","zh":"區域及國際比賽讓參加者接觸更高標準和不同風格。"},{"en":"These competitions can build confidence because students learn to perform outside their usual environment.","zh":"這些比賽能建立信心，因為學生學會在熟悉環境以外表現。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"invitation meets","meaning":"邀請賽","examples":[{"en":"He took part in several invitation meets in Asia.","zh":"他參加過亞洲幾個邀請賽。"},{"en":"Invitation meets are sports competitions where selected athletes or teams are invited to compete.","zh":"invitation meets 指被選中的運動員或隊伍受邀參加的體育比賽。"},{"en":"A school runner may join an invitation meet after winning local races.","zh":"學校跑手在本地比賽勝出後，可能參加邀請賽。"},{"en":"Invitation meets can give athletes experience against strong competitors from other places.","zh":"邀請賽能讓運動員獲得與其他地方強手比賽的經驗。"},{"en":"Unlike open events, invitation meets usually involve athletes chosen for their ability or record.","zh":"與公開賽不同，邀請賽通常包括因能力或紀錄而被選中的運動員。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"as captain of","meaning":"作為……隊長","examples":[{"en":"As captain of his club team, he supported younger teammates.","zh":"作為會隊隊長，他支援年輕隊友。"},{"en":"As captain of means serving as the leader of a team or group.","zh":"as captain of 的意思是擔任某隊伍或小組的領袖。"},{"en":"As captain of the school basketball team, she helped organise practice.","zh":"作為學校籃球隊隊長，她幫忙組織練習。"},{"en":"A person acting as captain of a team must encourage others and solve small problems.","zh":"作為隊長的人必須鼓勵別人並解決小問題。"},{"en":"Being captain of a group is not only about status; it is about responsibility.","zh":"作為隊長不只是關於地位；更是關於責任。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"perform under pressure","meaning":"在壓力下表現","examples":[{"en":"He learned to perform under pressure during major competitions.","zh":"他在大型比賽中學會在壓力下表現。"},{"en":"To perform under pressure means to do a task well when the situation is stressful.","zh":"perform under pressure 指在有壓力的情況下仍把任務做好。"},{"en":"A student must perform under pressure when giving a speech in front of the class.","zh":"學生在全班面前演講時，必須在壓力下表現。"},{"en":"Practice helps people perform under pressure because familiar actions feel less frightening.","zh":"練習幫助人在壓力下表現，因為熟悉的動作較不令人害怕。"},{"en":"Someone who can perform under pressure stays focused even when mistakes or noise appear.","zh":"能在壓力下表現的人，即使出現錯誤或噪音，仍能保持專注。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"communicate with","meaning":"與……溝通","examples":[{"en":"Athletes must communicate with coaches and physiotherapists.","zh":"運動員必須與教練和物理治療師溝通。"},{"en":"To communicate with someone means to share information, feelings, or needs clearly with them.","zh":"communicate with 某人，意思是清楚地與對方分享資訊、感受或需要。"},{"en":"Students should communicate with teachers when they do not understand homework.","zh":"學生不明白功課時，應該與老師溝通。"},{"en":"Good communication with team members prevents confusion and repeated mistakes.","zh":"與隊員良好溝通可以避免混亂和重複犯錯。"},{"en":"If patients do not communicate with doctors honestly, treatment may be less effective.","zh":"如果病人不坦誠地與醫生溝通，治療效果可能較差。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"physiotherapists","meaning":"物理治療師","examples":[{"en":"He worked closely with coaches and physiotherapists.","zh":"他與教練和物理治療師密切合作。"},{"en":"Physiotherapists are health professionals who help people recover movement and reduce pain after injury or illness.","zh":"物理治療師是幫助人們在受傷或患病後恢復活動能力和減輕痛楚的醫療專業人員。"},{"en":"A runner may visit physiotherapists to treat knee pain.","zh":"跑手可能會看物理治療師來處理膝痛。"},{"en":"Physiotherapists can prevent small injuries from becoming serious by checking movement carefully.","zh":"物理治療師透過仔細檢查動作，可以防止小傷患變嚴重。"},{"en":"Athletes need physiotherapists because training hard often puts stress on muscles and joints.","zh":"運動員需要物理治療師，因為艱苦訓練常對肌肉和關節造成壓力。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"support younger teammates","meaning":"支持年輕隊友","examples":[{"en":"He supported younger teammates who were new to elite sport.","zh":"他支持剛接觸精英體育的年輕隊友。"},{"en":"To support younger teammates means to help less experienced team members learn, improve, and feel confident.","zh":"support younger teammates 指幫助經驗較少的隊員學習、進步和建立信心。"},{"en":"Older students can support younger teammates by explaining team rules patiently.","zh":"高年級學生可以透過耐心解釋隊規，支持年輕隊友。"},{"en":"Younger teammates adjust faster when seniors support them instead of criticising every mistake.","zh":"當前輩支持年輕隊友，而不是批評每個錯誤時，他們會更快適應。"},{"en":"Supporting younger teammates builds a stronger team because knowledge is shared.","zh":"支持年輕隊友能建立更強團隊，因為知識得以分享。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"adjust to the demands of","meaning":"適應……的要求","examples":[{"en":"Young athletes need time to adjust to the demands of elite sport.","zh":"年輕運動員需要時間適應精英體育的要求。"},{"en":"To adjust to the demands of something means to get used to its difficulties, rules, and expectations.","zh":"adjust to the demands of 某事，意思是習慣其困難、規則和期望。"},{"en":"New university students need time to adjust to the demands of independent study.","zh":"大學新生需要時間適應自主學習的要求。"},{"en":"People may feel tired while adjusting to the demands of a new job.","zh":"人們在適應新工作的要求時可能會感到疲累。"},{"en":"Good support helps beginners adjust to the demands of a challenge without giving up.","zh":"良好支援能幫助初學者適應挑戰的要求，而不輕易放棄。"}],"source":"2021 Q4.pdf","sourcePage":3},{"front":"trained twice a day","meaning":"每日訓練兩次","examples":[{"en":"At one point, he trained twice a day while studying at university.","zh":"有一段時間，他讀大學時每日訓練兩次。"},{"en":"Trained twice a day means having two separate training sessions in one day.","zh":"trained twice a day 指一天內有兩節分開的訓練。"},{"en":"A swimmer may train twice a day before an important competition.","zh":"游泳選手在重要比賽前可能每日訓練兩次。"},{"en":"Training twice a day can improve fitness, but it also increases the need for rest and food.","zh":"每日訓練兩次可以改善體能，但也增加對休息和食物的需要。"},{"en":"People should not train twice a day without a plan, because overtraining can cause injury.","zh":"沒有計劃時不應每日訓練兩次，因為過度訓練可能造成受傷。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"completing university studies","meaning":"完成大學學業","examples":[{"en":"He trained twice a day while completing his university studies.","zh":"他完成大學學業期間每日訓練兩次。"},{"en":"Completing university studies means finishing the courses and requirements needed for a degree.","zh":"completing university studies 指完成取得學位所需的課程和要求。"},{"en":"Many students work part-time while completing university studies.","zh":"許多學生在完成大學學業期間兼職。"},{"en":"Completing university studies can be harder when a person also has family or sports responsibilities.","zh":"當一個人同時有家庭或運動責任時，完成大學學業可能更困難。"},{"en":"Good time management helps students stay healthy while completing university studies.","zh":"良好時間管理能幫助學生在完成大學學業期間保持健康。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"balance between ambition, discipline and recovery","meaning":"雄心、紀律與恢復之間的平衡","examples":[{"en":"He understands the balance between ambition, discipline and recovery.","zh":"他明白雄心、紀律與恢復之間的平衡。"},{"en":"This balance means knowing when to work hard, follow rules, and rest properly.","zh":"這種平衡指知道何時努力、遵守規律和適當休息。"},{"en":"A student preparing for exams needs a balance between ambition, discipline and recovery.","zh":"備考學生需要在雄心、紀律與恢復之間取得平衡。"},{"en":"Too much ambition without recovery can lead to stress, illness, or injury.","zh":"只有雄心而沒有恢復，可能導致壓力、疾病或受傷。"},{"en":"Real progress often comes from balancing strong goals with steady habits and enough rest.","zh":"真正進步常來自把強烈目標、穩定習慣和足夠休息平衡起來。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"resilience, patience and responsibility","meaning":"抗逆力、耐性和責任感","examples":[{"en":"These experiences developed his resilience, patience and responsibility.","zh":"這些經歷培養了他的抗逆力、耐性和責任感。"},{"en":"Resilience, patience and responsibility help people recover from problems, wait for progress, and do what they should do.","zh":"抗逆力、耐性和責任感幫助人從問題中恢復、等待進步，並做應做的事。"},{"en":"Group projects can develop resilience, patience and responsibility because students must solve problems together.","zh":"小組專題可以培養抗逆力、耐性和責任感，因為學生必須一起解決問題。"},{"en":"Without resilience, patience and responsibility, people may quit when results take time.","zh":"沒有抗逆力、耐性和責任感，人們可能在成果需要時間時放棄。"},{"en":"These qualities matter in sport, work, family life, and study.","zh":"這些特質在體育、工作、家庭生活和學習中都很重要。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"be particularly interested in","meaning":"對……特別感興趣","examples":[{"en":"He is particularly interested in designing training programmes.","zh":"他對設計訓練計劃特別感興趣。"},{"en":"To be particularly interested in something means to care about or enjoy that thing more than others.","zh":"be particularly interested in 某事，意思是比其他事情更關心或更喜歡它。"},{"en":"A student may be particularly interested in history because family stories make the past feel real.","zh":"學生可能因為家庭故事令過去變得真實，而對歷史特別感興趣。"},{"en":"People work harder when they are particularly interested in the subject.","zh":"當人們對某科目特別感興趣時，通常會更努力。"},{"en":"Being particularly interested in a duty can make someone more motivated to do it well.","zh":"對某項職責特別感興趣，可以令人更有動力把它做好。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"the duty of designing","meaning":"設計……的職責","examples":[{"en":"He is interested in the duty of designing training programmes.","zh":"他對設計訓練計劃的職責感興趣。"},{"en":"The duty of designing something means the responsibility to plan and create it carefully.","zh":"the duty of designing 某物，指仔細計劃和創造它的責任。"},{"en":"A teacher may have the duty of designing lessons for different ability groups.","zh":"老師可能有為不同能力組別設計課堂的職責。"},{"en":"If the duty of designing a plan is done poorly, people may waste time or get confused.","zh":"如果設計計劃的職責做得不好，人們可能浪費時間或感到混亂。"},{"en":"The duty of designing a programme requires understanding the people who will use it.","zh":"設計計劃的職責需要理解將會使用它的人。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"training programmes","meaning":"訓練計劃","examples":[{"en":"He wants to design training programmes for elite athletes.","zh":"他想為精英運動員設計訓練計劃。"},{"en":"Training programmes are planned sets of exercises, lessons, or activities that help people improve.","zh":"training programmes 指一系列有計劃的練習、課堂或活動，幫助人進步。"},{"en":"A gym may offer training programmes for beginners who want to build strength safely.","zh":"健身室可能為想安全增強力量的初學者提供訓練計劃。"},{"en":"Good training programmes reduce confusion because each session has a clear purpose.","zh":"好的訓練計劃能減少混亂，因為每節都有明確目的。"},{"en":"Training programmes should change when a learner’s level, goal, or health changes.","zh":"當學習者的程度、目標或健康狀況改變時，訓練計劃也應改變。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"elite athletes","meaning":"精英運動員","examples":[{"en":"The Foundation supports training programmes for elite athletes.","zh":"基金會支持精英運動員的訓練計劃。"},{"en":"Elite athletes are sportspeople who compete at a very high level.","zh":"elite athletes 指在非常高水平比賽的運動員。"},{"en":"Elite athletes often need coaches, doctors, nutrition advice, and mental support.","zh":"精英運動員常需要教練、醫生、營養建議和心理支援。"},{"en":"Because elite athletes train hard, poor recovery can quickly affect their performance.","zh":"因為精英運動員訓練艱苦，恢復不足會很快影響表現。"},{"en":"Elite athletes may look confident, but they still need guidance and protection.","zh":"精英運動員可能看起來自信，但他們仍需要指導和保護。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"periodised training plans","meaning":"分期訓練計劃","examples":[{"en":"He worked with periodised training plans throughout his career.","zh":"他整個職業生涯都使用分期訓練計劃。"},{"en":"Periodised training plans divide training into stages so athletes build fitness, peak, and recover at the right times.","zh":"periodised training plans 把訓練分成不同階段，讓運動員在合適時間建立體能、達到高峰和恢復。"},{"en":"A runner may use periodised training plans to prepare slowly for a marathon.","zh":"跑手可能使用分期訓練計劃，慢慢備戰馬拉松。"},{"en":"Without periodised training plans, athletes may train too hard too early and become tired before competition.","zh":"沒有分期訓練計劃，運動員可能太早訓練過重，賽前已經疲累。"},{"en":"Periodised training plans help coaches decide when to increase, reduce, or change training.","zh":"分期訓練計劃幫助教練決定何時增加、減少或改變訓練。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"endurance","meaning":"耐力","examples":[{"en":"The training plan covered endurance, speed work and strength conditioning.","zh":"訓練計劃包括耐力、速度訓練和體能及力量訓練。"},{"en":"Endurance is the ability to keep going for a long time without becoming too tired.","zh":"endurance 指長時間持續做事而不太快疲累的能力。"},{"en":"Long-distance running builds endurance because the body learns to work for longer periods.","zh":"長跑能建立耐力，因為身體學會長時間運作。"},{"en":"Poor endurance can make a player slow down near the end of a match.","zh":"耐力不足可能令球員在比賽尾段慢下來。"},{"en":"Endurance matters not only in sport; students also need it for long exams and projects.","zh":"耐力不只在運動中重要；學生面對長考試和專題時也需要它。"}],"source":"2021 Q4.pdf","sourcePage":4},{"front":"speed work","meaning":"速度訓練","examples":[{"en":"Speed work is an important part of middle-distance training.","zh":"速度訓練是中距離訓練的重要部分。"},{"en":"Speed work means training designed to help athletes move faster.","zh":"speed work 指為幫助運動員移動得更快而設計的訓練。"},{"en":"A football player may do speed work by practising short sprints.","zh":"足球員可以透過練習短途衝刺進行速度訓練。"},{"en":"Speed work can improve performance, but doing too much may increase injury risk.","zh":"速度訓練可以提升表現，但做得太多可能增加受傷風險。"},{"en":"Speed work is most useful when it is balanced with endurance and recovery.","zh":"速度訓練在與耐力和恢復平衡時最有用。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"strength conditioning","meaning":"體能及力量訓練","examples":[{"en":"Strength conditioning can help athletes improve performance and prevent injury.","zh":"體能及力量訓練可以幫助運動員提升表現和預防受傷。"},{"en":"Strength conditioning means exercises that build muscle power, control, and body stability.","zh":"strength conditioning 指建立肌肉力量、控制力和身體穩定性的練習。"},{"en":"A dancer may use strength conditioning to protect the knees and back.","zh":"舞蹈員可能使用體能及力量訓練來保護膝蓋和背部。"},{"en":"Good strength conditioning helps athletes move better because their bodies are stronger and more stable.","zh":"良好的體能及力量訓練能幫助運動員動作更好，因為身體更強壯和穩定。"},{"en":"Strength conditioning is not only lifting heavy weights; it also includes safe movement habits.","zh":"體能及力量訓練不只是舉重，也包括安全的動作習慣。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"injury prevention","meaning":"預防受傷","examples":[{"en":"The programme included injury prevention and recovery strategies.","zh":"該計劃包括預防受傷和恢復策略。"},{"en":"Injury prevention means taking steps to reduce the chance of getting hurt.","zh":"injury prevention 指採取措施減低受傷機會。"},{"en":"Warming up before exercise is a simple form of injury prevention.","zh":"運動前熱身是簡單的預防受傷方法。"},{"en":"Poor shoes, tired muscles, and rushed training can make injury prevention more difficult.","zh":"不合適的鞋、疲累的肌肉和倉促訓練會令預防受傷更困難。"},{"en":"Injury prevention saves time because avoiding an injury is better than recovering from one.","zh":"預防受傷能節省時間，因為避免受傷比受傷後恢復更好。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"tapering before major events","meaning":"大賽前減量調整","examples":[{"en":"Athletes often use tapering before major events.","zh":"運動員常在大賽前使用減量調整。"},{"en":"Tapering before major events means reducing training before an important competition so the body can feel fresh.","zh":"tapering before major events 指在重要比賽前減少訓練，讓身體保持新鮮狀態。"},{"en":"A runner may run fewer kilometres in the week before a championship.","zh":"跑手可能在錦標賽前一星期減少跑量。"},{"en":"Without tapering before major events, athletes may arrive tired instead of ready.","zh":"沒有大賽前減量調整，運動員可能疲累上場，而不是準備好上場。"},{"en":"Tapering is not laziness; it is planned rest before performance.","zh":"減量調整不是懶惰；它是表現前有計劃的休息。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"came to understand why","meaning":"逐漸明白為何","examples":[{"en":"He came to understand why each athlete needs a different plan.","zh":"他逐漸明白為何每位運動員都需要不同計劃。"},{"en":"Came to understand why means gradually learned the reason for something.","zh":"came to understand why 的意思是逐漸學會某事背後的原因。"},{"en":"After helping his sister revise, he came to understand why teaching requires patience.","zh":"幫妹妹溫習後，他逐漸明白為何教學需要耐性。"},{"en":"People often come to understand why rules exist after seeing what happens without them.","zh":"人們在看見沒有規則會發生甚麼後，常會逐漸明白規則存在的原因。"},{"en":"Experience can make someone come to understand why simple advice is not always enough.","zh":"經驗可以令人逐漸明白為何簡單建議不總是足夠。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"the same plan cannot serve every athlete","meaning":"同一個計劃不能適用於每位運動員","examples":[{"en":"The same plan cannot serve every athlete effectively.","zh":"同一個計劃不能有效適用於每位運動員。"},{"en":"This means one training plan will not suit all athletes because people have different bodies, goals, and problems.","zh":"這句話意思是一個訓練計劃不會適合所有運動員，因為每個人的身體、目標和問題不同。"},{"en":"The same study timetable cannot serve every student because some learn faster in the morning and others at night.","zh":"同一個溫習時間表不能適用於每位學生，因為有人早上學得快，有人晚上學得快。"},{"en":"If coaches use one plan for everyone, some athletes may improve while others get injured.","zh":"如果教練對所有人使用同一個計劃，有些運動員可能進步，有些則可能受傷。"},{"en":"Fair support often means different plans, not exactly the same plan for all.","zh":"公平支援往往代表不同計劃，而不是所有人用完全一樣的計劃。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"returning from a hamstring injury","meaning":"腿後肌受傷後復出","examples":[{"en":"A sprinter returning from a hamstring injury needs careful support.","zh":"腿後肌受傷後復出的短跑手需要小心支援。"},{"en":"Returning from a hamstring injury means coming back to training or competition after hurting the muscles at the back of the thigh.","zh":"returning from a hamstring injury 指大腿後方肌肉受傷後重返訓練或比賽。"},{"en":"A footballer returning from a hamstring injury may first practise gentle running.","zh":"腿後肌受傷後復出的足球員，可能先練習輕鬆跑。"},{"en":"If an athlete rushes while returning from a hamstring injury, the injury may happen again.","zh":"如果運動員在腿後肌受傷後復出時太急，傷患可能再次出現。"},{"en":"Returning from injury should be slow enough to rebuild strength safely.","zh":"傷後復出應該夠慢，才能安全重建力量。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"a progressive programme","meaning":"漸進式計劃","examples":[{"en":"The athlete may need a progressive programme after injury.","zh":"運動員受傷後可能需要漸進式計劃。"},{"en":"A progressive programme is a plan that becomes harder step by step.","zh":"progressive programme 指一步一步變得更困難的計劃。"},{"en":"A patient recovering from surgery may follow a progressive programme of walking and stretching.","zh":"手術後康復的病人可能跟隨一個由步行和伸展組成的漸進式計劃。"},{"en":"A progressive programme reduces risk because the body has time to adapt.","zh":"漸進式計劃能降低風險，因為身體有時間適應。"},{"en":"A plan that jumps from easy to very hard is not a safe progressive programme.","zh":"一個由容易突然跳到非常困難的計劃，不是安全的漸進式計劃。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"built around","meaning":"以……為核心設計","examples":[{"en":"The programme is built around mobility and acceleration mechanics.","zh":"該計劃以活動能力和加速動作機制為核心設計。"},{"en":"Built around means designed with something as the main focus or centre.","zh":"built around 的意思是以某事作為主要焦點或中心來設計。"},{"en":"A lesson built around real examples is easier for students to understand.","zh":"以真實例子為核心設計的課堂，較容易讓學生理解。"},{"en":"If a training plan is built around recovery, athletes may avoid overtraining.","zh":"如果訓練計劃以恢復為核心設計，運動員可能避免過度訓練。"},{"en":"A good support plan should be built around the needs of the people using it.","zh":"好的支援計劃應以使用者的需要為核心設計。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"mobility","meaning":"活動能力；關節靈活度","examples":[{"en":"Mobility is important for athletes returning from injury.","zh":"活動能力對傷後復出的運動員很重要。"},{"en":"Mobility means the ability to move joints and muscles freely and safely.","zh":"mobility 指關節和肌肉能自由而安全活動的能力。"},{"en":"Older people may do gentle exercises to improve mobility.","zh":"年長人士可能做溫和運動來改善活動能力。"},{"en":"Poor mobility can make simple movements painful or increase the risk of injury.","zh":"活動能力不足可能令簡單動作疼痛，或增加受傷風險。"},{"en":"Mobility is not the same as speed; it is about moving well and comfortably.","zh":"活動能力不等於速度；它關乎能否良好而舒適地活動。"}],"source":"2021 Q4.pdf","sourcePage":5},{"front":"acceleration mechanics","meaning":"加速動作機制","examples":[{"en":"The coach focuses on mobility and acceleration mechanics.","zh":"教練專注於活動能力和加速動作機制。"},{"en":"Acceleration mechanics are the body movements and techniques used to speed up efficiently.","zh":"acceleration mechanics 指有效加速時使用的身體動作和技術。"},{"en":"A sprinter practises acceleration mechanics when learning how to drive the knees and push off the ground.","zh":"短跑手學習提膝和蹬地時，就是在練習加速動作機制。"},{"en":"Poor acceleration mechanics can waste energy and slow an athlete at the start of a race.","zh":"差的加速動作機制會浪費能量，令運動員起跑時變慢。"},{"en":"Good acceleration mechanics help athletes move faster without forcing the body badly.","zh":"良好的加速動作機制幫助運動員更快移動，而不會錯誤地強迫身體。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"preparing for a championship","meaning":"備戰錦標賽","examples":[{"en":"A distance runner preparing for a championship needs managed training.","zh":"備戰錦標賽的長跑手需要受管理的訓練。"},{"en":"Preparing for a championship means getting ready for an important competition.","zh":"preparing for a championship 指為重要比賽作準備。"},{"en":"A school team preparing for a championship may practise tactics every afternoon.","zh":"備戰錦標賽的學校隊伍可能每天下午練習戰術。"},{"en":"Athletes preparing for a championship must balance hard work with sleep and recovery.","zh":"備戰錦標賽的運動員必須平衡艱苦訓練、睡眠和恢復。"},{"en":"Preparing for a championship is not only physical; it also includes confidence and planning.","zh":"備戰錦標賽不只是身體上的，也包括信心和計劃。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"carefully managed mileage","meaning":"妥善控制的跑量","examples":[{"en":"A distance runner requires carefully managed mileage and recovery.","zh":"長跑手需要妥善控制的跑量和恢復。"},{"en":"Carefully managed mileage means the amount of running is planned and controlled to avoid too much or too little training.","zh":"carefully managed mileage 指有計劃地控制跑步距離，避免訓練過多或過少。"},{"en":"A beginner training for a race needs carefully managed mileage to prevent sore knees.","zh":"初學者備戰比賽時需要妥善控制的跑量，以防膝蓋疼痛。"},{"en":"If mileage increases too quickly, carefully managed mileage becomes especially important.","zh":"如果跑量增加得太快，妥善控制跑量就尤其重要。"},{"en":"Carefully managed mileage helps runners improve without breaking down.","zh":"妥善控制的跑量幫助跑手進步，而不令身體崩潰。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"evidence-informed","meaning":"以證據為本的","examples":[{"en":"He would help design evidence-informed training programmes.","zh":"他會協助設計以證據為本的訓練計劃。"},{"en":"Evidence-informed means guided by facts, records, research, or careful observation.","zh":"evidence-informed 指由事實、紀錄、研究或仔細觀察作指引。"},{"en":"A teacher makes evidence-informed decisions by checking students’ test results and classwork.","zh":"老師透過查看學生測驗成績和課堂作業，作出以證據為本的決定。"},{"en":"Evidence-informed plans are safer because they do not depend only on guesswork.","zh":"以證據為本的計劃較安全，因為它們不只依靠猜測。"},{"en":"Being evidence-informed does not remove experience; it uses evidence to improve judgement.","zh":"以證據為本不代表排除經驗；它是用證據改善判斷。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"athlete-centred programmes","meaning":"以運動員為中心的計劃","examples":[{"en":"He would design athlete-centred programmes for different runners.","zh":"他會為不同跑手設計以運動員為中心的計劃。"},{"en":"Athlete-centred programmes are plans built around the needs, goals, health, and progress of each athlete.","zh":"athlete-centred programmes 指圍繞每位運動員的需要、目標、健康和進度而設計的計劃。"},{"en":"A young swimmer may need an athlete-centred programme that protects school time and sleep.","zh":"年輕游泳選手可能需要一個保護上學時間和睡眠的以運動員為中心的計劃。"},{"en":"Athlete-centred programmes work better because athletes are treated as people, not machines.","zh":"以運動員為中心的計劃效果較好，因為運動員被視為人，而不是機器。"},{"en":"A programme is not truly athlete-centred if it ignores injury, stress, or personal goals.","zh":"如果計劃忽視傷患、壓力或個人目標，它就不是真正以運動員為中心。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"performance records","meaning":"表現紀錄","examples":[{"en":"Performance records can show whether training is effective.","zh":"表現紀錄可以顯示訓練是否有效。"},{"en":"Performance records are written or digital records of results, times, scores, or progress.","zh":"performance records 指結果、時間、分數或進步的書面或電子紀錄。"},{"en":"A teacher may keep performance records to see whether students are improving.","zh":"老師可能保存表現紀錄，以查看學生是否進步。"},{"en":"Without performance records, coaches may not notice small problems until they become serious.","zh":"沒有表現紀錄，教練可能要到小問題變嚴重時才注意到。"},{"en":"Performance records help people make decisions based on facts, not memory alone.","zh":"表現紀錄幫助人根據事實，而不只是記憶作決定。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"training diaries","meaning":"訓練日誌","examples":[{"en":"Training diaries help coaches understand an athlete’s progress.","zh":"訓練日誌幫助教練了解運動員的進度。"},{"en":"Training diaries are records where athletes write what they trained, how they felt, and what changed.","zh":"training diaries 指運動員記錄訓練內容、感受和變化的紀錄。"},{"en":"A runner may use a training diary to record distance, sleep, and pain.","zh":"跑手可以用訓練日誌記錄距離、睡眠和疼痛。"},{"en":"Training diaries can reveal patterns, such as tiredness after too many hard sessions.","zh":"訓練日誌可以揭示模式，例如太多艱苦訓練後出現疲累。"},{"en":"A training diary is useful because small daily details may explain big changes later.","zh":"訓練日誌有用，因為日常小細節日後可能解釋重大變化。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"regular feedback","meaning":"定期回饋","examples":[{"en":"Regular feedback helps ensure that every session has a clear purpose.","zh":"定期回饋有助確保每節訓練都有明確目的。"},{"en":"Regular feedback means comments or advice given often, not only once.","zh":"regular feedback 指經常給予的評語或建議，而不是只給一次。"},{"en":"Students improve faster when teachers give regular feedback on their writing.","zh":"當老師定期回饋學生的寫作時，學生會進步得更快。"},{"en":"Regular feedback prevents small mistakes from becoming long-term habits.","zh":"定期回饋能防止小錯誤變成長期習慣。"},{"en":"Feedback is most useful when it is regular, specific, and respectful.","zh":"回饋在定期、具體和尊重時最有用。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"every session has a clear purpose","meaning":"每節訓練都有明確目的","examples":[{"en":"Every session should have a clear purpose.","zh":"每節訓練都應該有明確目的。"},{"en":"This means each lesson, meeting, or training period should have a specific goal.","zh":"這句話意思是每節課、會議或訓練時段都應有具體目標。"},{"en":"A revision session has a clear purpose when students know which skill they are practising.","zh":"當學生知道自己正在練習哪項技能時，溫習時段就有明確目的。"},{"en":"If every session has a clear purpose, people waste less time and understand why they are there.","zh":"如果每節都有明確目的，人們會少浪費時間，也明白自己為何在場。"},{"en":"Without a clear purpose, a session may feel busy but produce little progress.","zh":"沒有明確目的的時段可能看似忙碌，但進展很少。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"be confident that","meaning":"有信心","examples":[{"en":"He is confident that he could assist in organising competitions.","zh":"他有信心自己能協助籌辦比賽。"},{"en":"To be confident that something is true means to believe it strongly because there is good reason.","zh":"be confident that 某事屬實，意思是因有充分理由而強烈相信它。"},{"en":"A student is confident that she passed because she prepared carefully and understood the questions.","zh":"學生因準備充足並理解題目，所以有信心自己及格。"},{"en":"People are more confident that they can do a task after practising it many times.","zh":"人們在多次練習後，會更有信心自己能完成任務。"},{"en":"Being confident that you can help should be based on skill, not empty pride.","zh":"有信心自己能幫忙應建基於技能，而不是空洞自滿。"}],"source":"2021 Q4.pdf","sourcePage":6},{"front":"assist in organising","meaning":"協助籌辦","examples":[{"en":"He could assist in organising international sporting competitions.","zh":"他可以協助籌辦國際體育賽事。"},{"en":"To assist in organising means to help plan, prepare, and manage an event or activity.","zh":"assist in organising 指幫助計劃、準備和管理活動。"},{"en":"Students may assist in organising a school fair by setting up booths.","zh":"學生可以透過設置攤位，協助籌辦學校市集。"},{"en":"People who assist in organising events help reduce pressure on the main team.","zh":"協助籌辦活動的人可以減輕主辦團隊的壓力。"},{"en":"To assist in organising well, you must notice details before they become problems.","zh":"要好好協助籌辦，你必須在細節變成問題前留意它們。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"international sporting competitions","meaning":"國際體育賽事","examples":[{"en":"The Foundation may organise international sporting competitions.","zh":"基金會可能籌辦國際體育賽事。"},{"en":"International sporting competitions are sports events involving athletes or teams from different countries.","zh":"international sporting competitions 指有不同國家運動員或隊伍參與的體育賽事。"},{"en":"The Asian Games and Olympic events are examples of international sporting competitions.","zh":"亞運會和奧運項目都是國際體育賽事的例子。"},{"en":"International sporting competitions need careful planning because visitors may need travel, language, and safety support.","zh":"國際體育賽事需要仔細規劃，因為訪客可能需要交通、語言和安全支援。"},{"en":"These competitions can bring people together, but they also require strong organisation.","zh":"這些賽事可以把人聚集起來，但也需要強大的組織能力。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"invisible work lies behind","meaning":"背後有很多看不見的工作","examples":[{"en":"He has seen how much invisible work lies behind a successful event.","zh":"他見過一場成功賽事背後有多少看不見的工作。"},{"en":"Invisible work lies behind something means many hidden tasks make the visible result possible.","zh":"invisible work lies behind 某事，意思是許多隱藏任務令可見成果成為可能。"},{"en":"Invisible work lies behind a clean classroom, such as planning, cleaning, and checking supplies.","zh":"乾淨課室背後有看不見的工作，例如計劃、清潔和檢查物資。"},{"en":"When invisible work is ignored, people may not appreciate how difficult success really is.","zh":"當看不見的工作被忽視，人們可能不懂欣賞成功其實有多困難。"},{"en":"A smooth event often looks simple because the invisible work was done well.","zh":"順利活動常看似簡單，因為背後看不見的工作做得好。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"a successful event","meaning":"成功的活動；成功的賽事","examples":[{"en":"Careful planning is essential for a successful event.","zh":"仔細計劃對成功活動很重要。"},{"en":"A successful event is an activity that achieves its aims and runs smoothly for the people involved.","zh":"successful event 指達到目標，並讓參與者順利進行的活動。"},{"en":"A school concert is a successful event when performers, parents, and teachers know what to do.","zh":"當表演者、家長和老師都知道該做甚麼時，學校音樂會就是成功活動。"},{"en":"A successful event usually results from clear roles, good timing, and quick problem-solving.","zh":"成功活動通常來自清晰角色、良好時間安排和快速解決問題。"},{"en":"An event is not successful only because many people attend; it must also be safe and meaningful.","zh":"活動不只是因為很多人出席就成功；它也必須安全和有意義。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"transport and accommodation","meaning":"交通及住宿安排","examples":[{"en":"Transport and accommodation must be arranged for visiting teams.","zh":"必須為到訪隊伍安排交通及住宿。"},{"en":"Transport and accommodation means travel arrangements and places to stay.","zh":"transport and accommodation 指交通安排和住宿地方。"},{"en":"A school trip needs transport and accommodation if students travel to another city overnight.","zh":"如果學生到另一個城市過夜，學校旅行就需要交通及住宿安排。"},{"en":"Poor transport and accommodation can make visitors tired before an event begins.","zh":"差劣的交通及住宿安排可能令訪客在活動開始前已感疲累。"},{"en":"Good transport and accommodation show respect for guests and help the schedule run smoothly.","zh":"良好的交通及住宿安排顯示對客人的尊重，並幫助日程順利進行。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"warm-up facilities","meaning":"熱身設施","examples":[{"en":"Athletes need suitable warm-up facilities before competition.","zh":"運動員在比賽前需要合適的熱身設施。"},{"en":"Warm-up facilities are spaces or equipment athletes use to prepare their bodies before performing.","zh":"warm-up facilities 指運動員在表現前準備身體所用的空間或設備。"},{"en":"A basketball tournament may provide warm-up facilities such as courts and stretching areas.","zh":"籃球比賽可能提供球場和伸展區等熱身設施。"},{"en":"Without warm-up facilities, athletes may feel stiff or risk injury.","zh":"沒有熱身設施，運動員可能感到僵硬或有受傷風險。"},{"en":"Warm-up facilities help competitors enter the event physically and mentally ready.","zh":"熱身設施幫助參賽者在身體和心理上準備好參賽。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"equipment checks","meaning":"器材檢查","examples":[{"en":"Equipment checks are necessary before a competition begins.","zh":"比賽開始前，器材檢查是必要的。"},{"en":"Equipment checks are careful inspections to make sure tools, machines, or sports items are safe and ready.","zh":"equipment checks 指仔細檢查工具、機器或體育用品是否安全和準備妥當。"},{"en":"A PE teacher does equipment checks before students use trampolines.","zh":"體育老師在學生使用彈床前會進行器材檢查。"},{"en":"Equipment checks prevent delays and accidents caused by broken or missing items.","zh":"器材檢查能防止破損或遺失物品造成延誤和意外。"},{"en":"Skipping equipment checks may save minutes but create serious problems later.","zh":"跳過器材檢查可能節省幾分鐘，但日後會造成嚴重問題。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"volunteer coordination","meaning":"義工協調","examples":[{"en":"Volunteer coordination helps an event run smoothly.","zh":"義工協調幫助活動順利進行。"},{"en":"Volunteer coordination means organising volunteers so each person knows their role, time, and task.","zh":"volunteer coordination 指組織義工，讓每個人知道自己的角色、時間和任務。"},{"en":"A charity walk needs volunteer coordination for registration, water stations, and directions.","zh":"慈善步行活動需要義工協調，以處理登記、水站和指路。"},{"en":"Without volunteer coordination, helpers may repeat the same job while other jobs are missed.","zh":"沒有義工協調，幫手可能重複做同一份工作，而其他工作被遺漏。"},{"en":"Good volunteer coordination makes volunteers feel useful rather than confused.","zh":"良好的義工協調令義工感到有用，而不是混亂。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"safety arrangements","meaning":"安全安排","examples":[{"en":"Safety arrangements protect athletes, staff and spectators.","zh":"安全安排保護運動員、工作人員和觀眾。"},{"en":"Safety arrangements are plans and actions that reduce danger during an activity.","zh":"safety arrangements 指在活動中減少危險的計劃和行動。"},{"en":"A school trip needs safety arrangements such as emergency contacts and first-aid supplies.","zh":"學校旅行需要安全安排，例如緊急聯絡資料和急救用品。"},{"en":"Poor safety arrangements can turn a small accident into a serious problem.","zh":"差劣的安全安排可能把小意外變成嚴重問題。"},{"en":"Safety arrangements should be prepared before an event, not after something goes wrong.","zh":"安全安排應在活動前準備，而不是出事後才處理。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"communication with visiting teams","meaning":"與到訪隊伍溝通","examples":[{"en":"Clear communication with visiting teams is essential.","zh":"與到訪隊伍清晰溝通是必要的。"},{"en":"Communication with visiting teams means sharing information clearly with teams coming from other places.","zh":"communication with visiting teams 指與來自其他地方的隊伍清楚分享資訊。"},{"en":"Organisers may use email groups for communication with visiting teams before a tournament.","zh":"主辦方可能在比賽前用電郵群組與到訪隊伍溝通。"},{"en":"Poor communication with visiting teams can cause missed buses, late arrivals, or confusion.","zh":"與到訪隊伍溝通不良，可能造成錯過巴士、遲到或混亂。"},{"en":"Good communication with visiting teams helps guests feel welcomed and prepared.","zh":"良好地與到訪隊伍溝通，能讓客人感到受歡迎和準備妥當。"}],"source":"2021 Q4.pdf","sourcePage":7},{"front":"unsettle athletes","meaning":"令運動員不安","examples":[{"en":"Small mistakes can unsettle athletes before a competition.","zh":"小錯誤可能在比賽前令運動員不安。"},{"en":"To unsettle athletes means to make them nervous, distracted, or less confident.","zh":"unsettle athletes 指令運動員緊張、分心或較缺乏信心。"},{"en":"A sudden timetable change may unsettle athletes just before a race.","zh":"突然改變時間表可能在賽前令運動員不安。"},{"en":"Unclear instructions can unsettle athletes because they no longer know what to expect.","zh":"不清晰的指示會令運動員不安，因為他們不再知道會發生甚麼。"},{"en":"Good organisers try to avoid problems that unsettle athletes at important moments.","zh":"好的主辦方會盡量避免在重要時刻令運動員不安的問題。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"focus on performance","meaning":"專注於表現","examples":[{"en":"Careful planning allows athletes to focus on performance.","zh":"仔細計劃讓運動員能專注於表現。"},{"en":"To focus on performance means to give attention to doing well rather than worrying about other problems.","zh":"focus on performance 指把注意力放在做好表現，而不是擔心其他問題。"},{"en":"Students can focus on performance in exams when they know the rules and timing clearly.","zh":"當學生清楚考試規則和時間時，就能專注於考試表現。"},{"en":"If travel, food, and schedules are well arranged, athletes can focus on performance more easily.","zh":"如果交通、食物和時間表安排妥當，運動員較容易專注於表現。"},{"en":"Removing distractions helps people focus on performance when results matter.","zh":"消除干擾能幫助人在結果重要時專注於表現。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"club competitions","meaning":"會內比賽","examples":[{"en":"He helped solve problems during previous club competitions.","zh":"他曾在以往會內比賽中協助解決問題。"},{"en":"Club competitions are contests organised by or within a sports club.","zh":"club competitions 指由體育會舉辦或在體育會內進行的比賽。"},{"en":"A swimming club may hold club competitions so young swimmers can gain race experience.","zh":"游泳會可能舉辦會內比賽，讓年輕泳手獲得比賽經驗。"},{"en":"Club competitions help beginners practise competition routines in a familiar environment.","zh":"會內比賽幫助初學者在熟悉環境中練習比賽程序。"},{"en":"Although club competitions may be smaller than international events, they still need planning.","zh":"雖然會內比賽可能比國際賽事小，但仍需要計劃。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"liaise with overseas teams","meaning":"與海外隊伍聯絡","examples":[{"en":"He helped liaise with overseas teams during competitions.","zh":"他在比賽期間協助與海外隊伍聯絡。"},{"en":"To liaise with overseas teams means to communicate and coordinate with teams from other countries or regions.","zh":"liaise with overseas teams 指與來自其他國家或地區的隊伍溝通和協調。"},{"en":"Event staff may liaise with overseas teams about hotels, transport, and practice times.","zh":"活動工作人員可能與海外隊伍聯絡酒店、交通和練習時間。"},{"en":"If nobody liaises with overseas teams, guests may miss important instructions.","zh":"如果沒有人與海外隊伍聯絡，客人可能錯過重要指示。"},{"en":"Liaising with overseas teams requires clear language, patience, and cultural awareness.","zh":"與海外隊伍聯絡需要清晰語言、耐性和文化意識。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"brief junior volunteers","meaning":"向年輕義工簡介工作","examples":[{"en":"He helped brief junior volunteers before the event.","zh":"他在活動前協助向年輕義工簡介工作。"},{"en":"To brief junior volunteers means to give young or less experienced helpers clear instructions before they start work.","zh":"brief junior volunteers 指在年輕或經驗較少的助手開始工作前，給予清晰指示。"},{"en":"A teacher may brief junior volunteers before a school open day.","zh":"老師可能在學校開放日前向年輕義工簡介工作。"},{"en":"Briefing junior volunteers prevents confusion because they know where to go and whom to ask.","zh":"向年輕義工簡介工作能防止混亂，因為他們知道去哪裡和問誰。"},{"en":"A good briefing should be short, clear, and practical.","zh":"好的簡介應該簡短、清晰和實用。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"last-minute scheduling problems","meaning":"臨時賽程問題","examples":[{"en":"He solved last-minute scheduling problems calmly.","zh":"他冷靜地解決臨時賽程問題。"},{"en":"Last-minute scheduling problems are timetable issues that appear very close to the start of an activity.","zh":"last-minute scheduling problems 指活動快開始時才出現的時間表問題。"},{"en":"A delayed bus can create last-minute scheduling problems for a school trip.","zh":"巴士延誤可能為學校旅行造成臨時日程問題。"},{"en":"Last-minute scheduling problems cause stress because there is little time to fix them.","zh":"臨時賽程問題會造成壓力，因為修正時間很少。"},{"en":"Calm planning helps solve last-minute scheduling problems without blaming people.","zh":"冷靜規劃有助解決臨時賽程問題，而不是互相責怪。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"stay calm","meaning":"保持冷靜","examples":[{"en":"Those responsibilities taught him to stay calm.","zh":"那些責任教會他保持冷靜。"},{"en":"To stay calm means to remain steady and not panic when something difficult happens.","zh":"stay calm 指在困難發生時保持穩定，不驚慌。"},{"en":"A student should stay calm if they forget one answer during an exam.","zh":"學生在考試中忘記一題答案時，應該保持冷靜。"},{"en":"Staying calm helps people think clearly and choose the next step.","zh":"保持冷靜幫助人清楚思考並選擇下一步。"},{"en":"It is easier to stay calm when you have prepared for possible problems.","zh":"當你為可能出現的問題作好準備時，較容易保持冷靜。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"think step by step","meaning":"逐步思考","examples":[{"en":"He learned to think step by step under pressure.","zh":"他學會在壓力下逐步思考。"},{"en":"To think step by step means to solve a problem one stage at a time.","zh":"think step by step 指一個階段一個階段地解決問題。"},{"en":"When a maths question looks difficult, students can think step by step instead of guessing.","zh":"當數學題看起來困難時，學生可以逐步思考，而不是亂猜。"},{"en":"Thinking step by step reduces panic because each small action feels manageable.","zh":"逐步思考能減少恐慌，因為每個小行動都較易處理。"},{"en":"Big problems often become clearer when people slow down and think step by step.","zh":"當人們放慢並逐步思考時，大問題常會變得更清楚。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"leave nothing to chance","meaning":"不把事情交給運氣；事事預先準備","examples":[{"en":"He tries to plan carefully and leave nothing to chance.","zh":"他嘗試仔細計劃，不把事情交給運氣。"},{"en":"To leave nothing to chance means to prepare carefully so success does not depend on luck.","zh":"leave nothing to chance 指仔細準備，讓成功不依賴運氣。"},{"en":"A wedding organiser leaves nothing to chance by checking weather, transport, food, and timing.","zh":"婚禮統籌員透過檢查天氣、交通、食物和時間安排，做到事事預先準備。"},{"en":"People leave nothing to chance when mistakes would be costly or dangerous.","zh":"當錯誤代價高或危險時，人們會不把事情交給運氣。"},{"en":"Leaving nothing to chance does not mean controlling everything; it means preparing for what you reasonably can.","zh":"事事預先準備不代表控制一切；而是為合理可預見的事情作準備。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"bring the same professionalism to","meaning":"把同樣的專業態度帶到……","examples":[{"en":"He would bring the same professionalism to events organised by the Foundation.","zh":"他會把同樣的專業態度帶到基金會舉辦的活動中。"},{"en":"To bring the same professionalism to something means to use the same serious, careful, and responsible working attitude there.","zh":"bring the same professionalism to 某事，意思是在該處使用同樣認真、細心和負責的工作態度。"},{"en":"A nurse can bring the same professionalism to community health talks as to hospital work.","zh":"護士可以把醫院工作中的同樣專業態度帶到社區健康講座中。"},{"en":"Bringing professionalism to a task makes people trust you because you act carefully and respectfully.","zh":"把專業態度帶到任務中，能令人信任你，因為你做事細心而尊重他人。"},{"en":"Professionalism should appear in small tasks as well as important public events.","zh":"專業態度應出現在小任務中，也應出現在重要公開活動中。"}],"source":"2021 Q4.pdf","sourcePage":8},{"front":"equally important","meaning":"同樣重要的是","examples":[{"en":"Equally important is the responsibility to identify local talent.","zh":"同樣重要的是發掘本地人才的責任。"},{"en":"Equally important means just as important as the point already mentioned.","zh":"equally important 指與剛提到的一點同樣重要。"},{"en":"Good grades are important; equally important is learning how to ask questions.","zh":"好成績很重要；同樣重要的是學會如何提問。"},{"en":"People use equally important to show that a second idea should not be treated as less valuable.","zh":"人們使用 equally important 來表示第二個想法不應被視為較不重要。"},{"en":"In teamwork, finishing the task matters, but equally important is respecting one another.","zh":"在團隊合作中，完成任務重要，但同樣重要的是互相尊重。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"identify and support local talent","meaning":"發掘並支援本地人才","examples":[{"en":"The Foundation helps identify and support local talent.","zh":"基金會幫助發掘並支援本地人才。"},{"en":"To identify and support local talent means to find skilled people in the community and help them grow.","zh":"identify and support local talent 指在社區中找出有能力的人，並幫助他們成長。"},{"en":"Schools can identify and support local talent by noticing students who do well in music, sport, or science.","zh":"學校可以透過留意在音樂、體育或科學方面表現好的學生，發掘並支援本地人才。"},{"en":"If local talent is identified but not supported, potential may be wasted.","zh":"如果本地人才被發掘卻沒有獲得支援，潛能可能被浪費。"},{"en":"Identifying local talent is only the first step; support turns ability into progress.","zh":"發掘本地人才只是第一步；支援才能把能力變成進步。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"promising young athletes","meaning":"有潛質的年輕運動員","examples":[{"en":"Hong Kong has many promising young athletes.","zh":"香港有許多有潛質的年輕運動員。"},{"en":"Promising young athletes are young sportspeople who show strong potential for future success.","zh":"promising young athletes 指展現未來成功潛力的年輕運動員。"},{"en":"A promising young athlete may not win every race yet, but their improvement is clear.","zh":"有潛質的年輕運動員未必每場比賽都勝出，但進步很清楚。"},{"en":"Promising young athletes need guidance so early ability becomes long-term development.","zh":"有潛質的年輕運動員需要指導，讓早期能力變成長遠發展。"},{"en":"Calling someone promising means they have potential, not that success is already guaranteed.","zh":"說某人有潛質，意思是他有可能成功，而不是成功已經保證。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"remain unnoticed","meaning":"未被注意；被忽略","examples":[{"en":"Some young athletes’ potential may remain unnoticed.","zh":"一些年輕運動員的潛能可能未被注意。"},{"en":"To remain unnoticed means to not be seen, recognised, or given attention.","zh":"remain unnoticed 指沒有被看見、認可或關注。"},{"en":"A quiet student’s talent may remain unnoticed if teachers only praise loud students.","zh":"如果老師只稱讚活躍的學生，安靜學生的才華可能被忽略。"},{"en":"Potential can remain unnoticed when families lack information about opportunities.","zh":"當家庭缺乏機會資訊時，潛能可能未被注意。"},{"en":"Good teachers and coaches look carefully so hidden ability does not remain unnoticed.","zh":"好老師和教練會仔細觀察，讓隱藏能力不被忽略。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"lack guidance","meaning":"缺乏指導","examples":[{"en":"Some athletes lack guidance and confidence.","zh":"一些運動員缺乏指導和信心。"},{"en":"To lack guidance means to not have enough advice, direction, or support.","zh":"lack guidance 指沒有足夠建議、方向或支援。"},{"en":"A student may lack guidance when choosing subjects if nobody explains the options.","zh":"如果沒有人解釋選項，學生選科時可能缺乏指導。"},{"en":"Young people who lack guidance may make avoidable mistakes or lose motivation.","zh":"缺乏指導的年輕人可能犯可避免的錯誤，或失去動力。"},{"en":"Guidance does not control people; it helps them see the next sensible step.","zh":"指導不是控制別人；它幫助人看見下一個合理步驟。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"access to the right pathway","meaning":"接觸合適發展途徑的機會","examples":[{"en":"Young athletes need access to the right pathway.","zh":"年輕運動員需要接觸合適發展途徑的機會。"},{"en":"Access to the right pathway means having a real chance to follow a suitable route for development.","zh":"access to the right pathway 指有真正機會走上適合自己的發展路線。"},{"en":"A student needs access to the right pathway when choosing between university, training, or work.","zh":"學生在大學、培訓或工作之間選擇時，需要接觸合適發展途徑的機會。"},{"en":"Without access to the right pathway, talented people may not know where to go next.","zh":"沒有合適發展途徑，有才華的人可能不知道下一步應去哪裡。"},{"en":"The right pathway connects ability with opportunity, guidance, and long-term support.","zh":"合適發展途徑把能力與機會、指導和長遠支援連接起來。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"volunteered in school athletics clinics","meaning":"在學校田徑訓練班做義工","examples":[{"en":"He volunteered in school athletics clinics in Sha Tin and Tuen Mun.","zh":"他曾在沙田和屯門的學校田徑訓練班做義工。"},{"en":"Volunteered in school athletics clinics means helped without pay at school-based sports training sessions.","zh":"volunteered in school athletics clinics 指在學校田徑訓練班無償幫忙。"},{"en":"A former runner may volunteer in school athletics clinics to teach children safe running techniques.","zh":"前跑手可能在學校田徑訓練班做義工，教孩子安全跑步技術。"},{"en":"Volunteering in school athletics clinics gives young athletes extra attention and encouragement.","zh":"在學校田徑訓練班做義工，能給年輕運動員額外關注和鼓勵。"},{"en":"Such clinics can reveal talent that normal PE lessons may not show.","zh":"這類訓練班可以發現普通體育課未必展現的人才。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"raw speed","meaning":"天然速度；未經雕琢的速度","examples":[{"en":"Some students showed raw speed during the clinic.","zh":"一些學生在訓練班中展現天然速度。"},{"en":"Raw speed means natural quickness before much formal training or refinement.","zh":"raw speed 指在大量正規訓練或打磨前已有的天生速度。"},{"en":"A child who wins playground races easily may have raw speed.","zh":"一個輕易贏得操場跑步比賽的孩子，可能有天然速度。"},{"en":"Raw speed is valuable, but it needs technique and discipline to become real performance.","zh":"天然速度很有價值，但需要技術和紀律才能變成真正表現。"},{"en":"Coaches notice raw speed, then help athletes turn it into controlled speed.","zh":"教練會注意天然速度，然後幫助運動員把它變成受控制的速度。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"courage and curiosity","meaning":"勇氣和好奇心","examples":[{"en":"He saw students with raw speed, courage and curiosity.","zh":"他看見一些學生有天然速度、勇氣和好奇心。"},{"en":"Courage and curiosity mean bravery to try and interest in learning more.","zh":"courage and curiosity 指敢於嘗試的勇氣和想學更多的興趣。"},{"en":"A child shows courage and curiosity when they ask questions and try a new activity despite fear.","zh":"孩子雖然害怕仍提問並嘗試新活動時，就展現勇氣和好奇心。"},{"en":"Courage helps people begin; curiosity helps them keep learning.","zh":"勇氣幫助人開始；好奇心幫助人持續學習。"},{"en":"Talent grows better when courage and curiosity are supported, not laughed at.","zh":"當勇氣和好奇心得到支持，而不是被取笑，天分會更好地成長。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"early success","meaning":"早期成功","examples":[{"en":"Early success does not always lead to long-term development.","zh":"早期成功不一定會帶來長遠發展。"},{"en":"Early success means achieving good results near the beginning of a learning or career journey.","zh":"early success 指在學習或事業初期取得好成果。"},{"en":"A student may enjoy early success in music by winning a small competition.","zh":"學生可能透過贏得小型比賽，在音樂方面取得早期成功。"},{"en":"Early success can create confidence, but it may also create pressure.","zh":"早期成功可以建立信心，但也可能帶來壓力。"},{"en":"Early success is useful only if it is followed by learning, humility, and steady practice.","zh":"早期成功只有在之後配合學習、謙遜和穩定練習時才有用。"}],"source":"2021 Q4.pdf","sourcePage":9},{"front":"long-term development","meaning":"長遠發展","examples":[{"en":"Young athletes need support for long-term development.","zh":"年輕運動員需要支援以促進長遠發展。"},{"en":"Long-term development means growth that continues over months or years, not only quick improvement.","zh":"long-term development 指持續數月或數年的成長，而不只是快速進步。"},{"en":"Reading regularly supports a child’s long-term development better than last-minute exam drilling.","zh":"定期閱讀比臨急抱佛腳操練更能支持孩子的長遠發展。"},{"en":"Long-term development may slow down if people chase short-term results too aggressively.","zh":"如果人們過度追求短期成果，長遠發展可能會放慢。"},{"en":"Good coaches care about long-term development because athletes are still growing as people.","zh":"好教練重視長遠發展，因為運動員仍在作為人而成長。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"technical coaching","meaning":"技術指導","examples":[{"en":"Young athletes need technical coaching and mental support.","zh":"年輕運動員需要技術指導和心理支援。"},{"en":"Technical coaching means teaching the specific skills and correct methods needed for an activity.","zh":"technical coaching 指教授某項活動所需的具體技能和正確方法。"},{"en":"A tennis player receives technical coaching when learning how to serve properly.","zh":"網球員學習如何正確發球時，就是接受技術指導。"},{"en":"Technical coaching prevents bad habits from becoming difficult to change later.","zh":"技術指導能防止壞習慣日後變得難以改正。"},{"en":"Encouragement is helpful, but athletes also need technical coaching to improve safely.","zh":"鼓勵有幫助，但運動員也需要技術指導才能安全進步。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"mental support","meaning":"心理支援","examples":[{"en":"Mental support is important for young athletes.","zh":"心理支援對年輕運動員很重要。"},{"en":"Mental support means help with confidence, stress, motivation, and emotional difficulties.","zh":"mental support 指在信心、壓力、動力和情緒困難方面的幫助。"},{"en":"A teacher gives mental support when calming a nervous student before a presentation.","zh":"老師在學生匯報前安撫緊張的學生，就是提供心理支援。"},{"en":"Without mental support, talented people may lose confidence after failure.","zh":"沒有心理支援，有才華的人可能在失敗後失去信心。"},{"en":"Mental support does not remove pressure completely; it helps people handle pressure better.","zh":"心理支援不會完全消除壓力；它幫助人更好地處理壓力。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"realistic advice about","meaning":"關於……的實際建議","examples":[{"en":"Young athletes need realistic advice about education and injury management.","zh":"年輕運動員需要關於教育和傷患管理的實際建議。"},{"en":"Realistic advice about something means practical guidance that considers real limits, risks, and choices.","zh":"realistic advice about 某事，指考慮真實限制、風險和選擇的實用指導。"},{"en":"Students need realistic advice about careers, not just encouragement to follow dreams.","zh":"學生需要關於職業的實際建議，而不只是鼓勵他們追夢。"},{"en":"Realistic advice about money can prevent young people from making careless financial decisions.","zh":"關於金錢的實際建議可以防止年輕人作出粗心的財務決定。"},{"en":"Advice is realistic when it is honest, useful, and connected to the person’s actual situation.","zh":"當建議誠實、有用並連繫到當事人的實際情況時，它就是實際建議。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"family expectations","meaning":"家庭期望","examples":[{"en":"Young athletes often need to manage family expectations.","zh":"年輕運動員常需要處理家庭期望。"},{"en":"Family expectations are hopes or pressures from family members about what someone should do or achieve.","zh":"family expectations 指家人對某人應該做甚麼或達到甚麼成就的希望或壓力。"},{"en":"A student may feel family expectations when parents want them to choose medicine.","zh":"當父母希望孩子選讀醫科時，學生可能感受到家庭期望。"},{"en":"Family expectations can motivate young people, but they can also create stress.","zh":"家庭期望可以激勵年輕人，但也可能造成壓力。"},{"en":"Healthy family expectations should include support, listening, and realistic understanding.","zh":"健康的家庭期望應包括支援、聆聽和實際理解。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"injury management","meaning":"傷患管理","examples":[{"en":"Injury management is part of long-term athlete development.","zh":"傷患管理是長遠運動員發展的一部分。"},{"en":"Injury management means dealing with injuries through care, treatment, rest, and a safe return plan.","zh":"injury management 指透過護理、治療、休息和安全復出計劃來處理傷患。"},{"en":"A dancer needs injury management after ankle pain appears during practice.","zh":"舞蹈員在練習中出現腳踝痛後，需要傷患管理。"},{"en":"Poor injury management can turn a short break into a long-term problem.","zh":"差劣的傷患管理可能把短暫休息變成長期問題。"},{"en":"Good injury management helps people recover without rushing back too soon.","zh":"良好的傷患管理幫助人恢復，而不太早急著復出。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"lived through these challenges","meaning":"親身經歷過這些挑戰","examples":[{"en":"He has lived through these challenges as an athlete.","zh":"他作為運動員親身經歷過這些挑戰。"},{"en":"To have lived through these challenges means to have personally experienced and survived difficult situations.","zh":"lived through these challenges 指親身經歷並挺過困難情況。"},{"en":"A teacher who struggled at school has lived through some of the challenges weak students face.","zh":"曾在學校掙扎的老師，親身經歷過成績較弱學生面對的一些挑戰。"},{"en":"People who lived through challenges can often give more understanding advice.","zh":"親身經歷過挑戰的人，往往能給予更有同理心的建議。"},{"en":"Lived experience does not make someone perfect, but it can make their support more realistic.","zh":"親身經歷不會令人完美，但可以令支援更實際。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"build trust with","meaning":"與……建立信任","examples":[{"en":"He can build trust with young athletes and their parents.","zh":"他可以與年輕運動員及其父母建立信任。"},{"en":"To build trust with someone means to make them believe you are honest, fair, and reliable.","zh":"build trust with 某人，意思是令對方相信你誠實、公平和可靠。"},{"en":"A doctor builds trust with patients by listening carefully and explaining clearly.","zh":"醫生透過仔細聆聽和清楚解釋，與病人建立信任。"},{"en":"Trust builds slowly when people keep promises and act consistently.","zh":"當人們信守承諾並行動一致時，信任會慢慢建立。"},{"en":"You cannot build trust with words alone; actions must support what you say.","zh":"你不能只靠言語與人建立信任；行動必須支持你所說的話。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"be eager to assist with","meaning":"渴望協助","examples":[{"en":"He would be eager to assist with talent days and mentorship schemes.","zh":"他會渴望協助人才選拔日和導師計劃。"},{"en":"To be eager to assist with something means to be very willing and enthusiastic to help with it.","zh":"be eager to assist with 某事，意思是非常願意並熱心協助它。"},{"en":"A student may be eager to assist with the school fair because they enjoy organising activities.","zh":"學生可能因喜歡組織活動，而渴望協助學校市集。"},{"en":"People are eager to assist when they care about the purpose of the work.","zh":"當人們關心工作的目的時，會渴望協助。"},{"en":"Being eager to assist is valuable, but the help still needs to be reliable and organised.","zh":"渴望協助很有價值，但幫助仍需要可靠和有組織。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"talent days","meaning":"人才選拔日","examples":[{"en":"Talent days can help identify promising young athletes.","zh":"人才選拔日可以幫助發掘有潛質的年輕運動員。"},{"en":"Talent days are events where people are tested or observed to find those with potential.","zh":"talent days 指透過測試或觀察來尋找有潛質人士的活動。"},{"en":"A music school may hold talent days to discover children with strong rhythm or voice.","zh":"音樂學校可能舉辦人才選拔日，發現有強節奏感或嗓音的孩子。"},{"en":"Talent days can open doors for young people who have not joined formal programmes.","zh":"人才選拔日可以為未參加正規計劃的年輕人打開機會。"},{"en":"A good talent day should look for potential, not only polished performance.","zh":"好的人才選拔日應尋找潛力，而不只是成熟表現。"}],"source":"2021 Q4.pdf","sourcePage":10},{"front":"school outreach","meaning":"學校外展","examples":[{"en":"School outreach can help local students find the right pathway.","zh":"學校外展可以幫助本地學生找到合適發展途徑。"},{"en":"School outreach means visiting or working with schools to share support, information, or opportunities.","zh":"school outreach 指到學校或與學校合作，分享支援、資訊或機會。"},{"en":"A university may use school outreach to explain courses to senior students.","zh":"大學可能透過學校外展向高中學生解釋課程。"},{"en":"School outreach helps students who may not know opportunities exist.","zh":"學校外展幫助可能不知道有機會存在的學生。"},{"en":"Effective school outreach brings information to young people instead of waiting for them to ask.","zh":"有效的學校外展會把資訊帶給年輕人，而不是等待他們主動詢問。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"mentorship schemes","meaning":"導師計劃","examples":[{"en":"Mentorship schemes can support young athletes outside training.","zh":"導師計劃可以在訓練以外支援年輕運動員。"},{"en":"Mentorship schemes are organised programmes where experienced people guide less experienced people.","zh":"mentorship schemes 指由有經驗的人指導經驗較少者的有組織計劃。"},{"en":"A company may run mentorship schemes for new staff.","zh":"公司可能為新員工推行導師計劃。"},{"en":"Mentorship schemes help beginners avoid mistakes because mentors share experience.","zh":"導師計劃幫助初學者避免錯誤，因為導師會分享經驗。"},{"en":"Good mentorship schemes build confidence through regular conversation, not only one meeting.","zh":"好的導師計劃透過定期對話建立信心，而不只是一次會面。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"follow-up training plans","meaning":"跟進訓練計劃","examples":[{"en":"Follow-up training plans help ensure that potential is not wasted.","zh":"跟進訓練計劃有助確保潛能不被浪費。"},{"en":"Follow-up training plans are plans given after an event, test, or first programme to continue progress.","zh":"follow-up training plans 指在活動、測試或第一個計劃後，用來延續進步的計劃。"},{"en":"After a fitness test, a coach may give follow-up training plans for the next eight weeks.","zh":"體能測試後，教練可能給予未來八星期的跟進訓練計劃。"},{"en":"Without follow-up training plans, people may feel excited for one day and then lose direction.","zh":"沒有跟進訓練計劃，人們可能只興奮一天，然後失去方向。"},{"en":"Follow-up training plans turn first interest into steady development.","zh":"跟進訓練計劃把最初興趣變成穩定發展。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"potential is not wasted","meaning":"才能不被浪費","examples":[{"en":"Good support ensures that potential is not wasted.","zh":"良好支援確保才能不被浪費。"},{"en":"Potential is not wasted means ability or promise is used and developed instead of being lost.","zh":"potential is not wasted 指能力或潛質得到運用和發展，而不是流失。"},{"en":"A talented student’s potential is not wasted when the school gives them suitable challenges.","zh":"當學校給予合適挑戰時，有才華學生的潛能就不會被浪費。"},{"en":"Potential may be wasted if people lack money, guidance, or opportunities.","zh":"如果人們缺乏金錢、指導或機會，潛能可能被浪費。"},{"en":"To make sure potential is not wasted, support must continue after talent is discovered.","zh":"要確保才能不被浪費，支援必須在發現人才後持續。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"communicate fluently in","meaning":"能流利地以……溝通","examples":[{"en":"He can communicate fluently in English, Cantonese and Putonghua.","zh":"他能流利地以英語、廣東話和普通話溝通。"},{"en":"To communicate fluently in a language means to use it smoothly and clearly in conversation or work.","zh":"communicate fluently in 某語言，指在對話或工作中流暢清楚地使用該語言。"},{"en":"A receptionist who communicates fluently in several languages can help more visitors.","zh":"能流利地以多種語言溝通的接待員，可以幫助更多訪客。"},{"en":"Communicating fluently in a language reduces misunderstanding and builds trust.","zh":"能流利地以某語言溝通，能減少誤解並建立信任。"},{"en":"Fluency is not only knowing words; it is using them naturally with people.","zh":"流利不只是知道詞語；而是能自然地與人使用它們。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"Cantonese and Putonghua","meaning":"廣東話和普通話","examples":[{"en":"Cantonese and Putonghua are useful when working with local athletes.","zh":"與本地運動員合作時，廣東話和普通話很有用。"},{"en":"Cantonese and Putonghua are two Chinese spoken varieties commonly used in Hong Kong and mainland Chinese contexts.","zh":"廣東話和普通話是在香港和內地中文語境中常用的兩種中文口語。"},{"en":"A coach may use Cantonese and Putonghua to speak with athletes from different backgrounds.","zh":"教練可能用廣東話和普通話與不同背景的運動員溝通。"},{"en":"Knowing Cantonese and Putonghua can make communication with families and visitors smoother.","zh":"懂廣東話和普通話可以令與家庭和訪客的溝通更順暢。"},{"en":"Language ability matters because people feel more comfortable when they understand instructions clearly.","zh":"語言能力很重要，因為人們清楚理解指示時會較安心。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"international guests","meaning":"國際來賓","examples":[{"en":"Language skills are useful when working with international guests.","zh":"與國際來賓合作時，語言技能很有用。"},{"en":"International guests are visitors who come from other countries or regions.","zh":"international guests 指來自其他國家或地區的訪客。"},{"en":"A school may welcome international guests during an exchange programme.","zh":"學校可能在交流計劃中接待國際來賓。"},{"en":"International guests need clear information about transport, schedules, and local rules.","zh":"國際來賓需要關於交通、時間表和本地規則的清晰資訊。"},{"en":"Treating international guests well helps an event feel respectful and professional.","zh":"好好接待國際來賓，能令活動顯得尊重和專業。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"organised, punctual and used to","meaning":"有條理、守時並習慣於","examples":[{"en":"He is organised, punctual and used to working in a team.","zh":"他有條理、守時，並習慣團隊合作。"},{"en":"Organised, punctual and used to means planned, on time, and familiar with doing something regularly.","zh":"organised, punctual and used to 指有計劃、準時，並熟悉經常做某事。"},{"en":"A good class monitor is organised, punctual and used to helping classmates.","zh":"好的班長有條理、守時，並習慣幫助同學。"},{"en":"These qualities matter at work because people depend on your preparation and timing.","zh":"這些特質在工作中重要，因為別人依賴你的準備和時間觀念。"},{"en":"Being organised, punctual and used to teamwork makes cooperation easier for everyone.","zh":"有條理、守時並習慣團隊合作，會令每個人合作更容易。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"working in a team","meaning":"團隊合作","examples":[{"en":"He is used to working in a team with coaches and medical staff.","zh":"他習慣與教練和醫療團隊合作。"},{"en":"Working in a team means cooperating with others to reach a shared goal.","zh":"working in a team 指與他人合作以達到共同目標。"},{"en":"Students practise working in a team when they divide jobs for a group project.","zh":"學生在小組專題中分工時，就是練習團隊合作。"},{"en":"Working in a team can produce better results because people bring different skills.","zh":"團隊合作可以帶來更好成果，因為人們帶來不同技能。"},{"en":"Good teamwork needs listening, responsibility, and respect, not only doing your own part.","zh":"好的團隊合作需要聆聽、責任感和尊重，而不只是做好自己的部分。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"medical staff","meaning":"醫療團隊","examples":[{"en":"Coaches, medical staff and administrators must support one another.","zh":"教練、醫療團隊和行政人員必須互相支援。"},{"en":"Medical staff are health workers who care for injuries, illness, safety, or recovery.","zh":"medical staff 指照顧傷患、疾病、安全或康復的醫療工作者。"},{"en":"At a sports event, medical staff may treat cuts, heat illness, or muscle pain.","zh":"在體育賽事中，醫療團隊可能處理割傷、中暑或肌肉痛。"},{"en":"Medical staff are important because quick care can prevent a problem from becoming worse.","zh":"醫療團隊很重要，因為快速護理可以防止問題惡化。"},{"en":"Athletes should communicate honestly with medical staff about pain and tiredness.","zh":"運動員應誠實地向醫療團隊說明疼痛和疲累。"}],"source":"2021 Q4.pdf","sourcePage":11},{"front":"administrators","meaning":"行政人員","examples":[{"en":"Administrators play an important role in sports organisations.","zh":"行政人員在體育組織中扮演重要角色。"},{"en":"Administrators are people who manage records, schedules, communication, and office work.","zh":"administrators 指管理紀錄、時間表、溝通和辦公室工作的人员。"},{"en":"School administrators help arrange timetables, forms, rooms, and notices.","zh":"學校行政人員協助安排時間表、表格、房間和通告。"},{"en":"Without administrators, even talented teams may struggle with basic organisation.","zh":"沒有行政人員，即使有才華的團隊也可能在基本組織上遇到困難。"},{"en":"Administrators often do quiet work that keeps a whole organisation moving.","zh":"行政人員常做安靜但重要的工作，讓整個組織運作。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"support one another","meaning":"互相支援","examples":[{"en":"Coaches, medical staff and administrators must support one another.","zh":"教練、醫療團隊和行政人員必須互相支援。"},{"en":"To support one another means to help each other when tasks, problems, or pressure appear.","zh":"support one another 指在出現任務、問題或壓力時彼此幫助。"},{"en":"Family members support one another by sharing housework when someone is busy.","zh":"家人在有人忙碌時分擔家務，就是互相支援。"},{"en":"Teams work better when members support one another instead of blaming one another.","zh":"當成員互相支援，而不是互相責怪時，團隊會運作得更好。"},{"en":"Supporting one another builds trust because people know they are not facing problems alone.","zh":"互相支援能建立信任，因為人們知道自己不是獨自面對問題。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"giving instructions from the side of a track","meaning":"在跑道旁發號施令","examples":[{"en":"Coaching is not just giving instructions from the side of a track.","zh":"教練工作不只是站在跑道旁發號施令。"},{"en":"Giving instructions from the side of a track means telling athletes what to do while standing beside the running area.","zh":"giving instructions from the side of a track 指站在跑道旁告訴運動員該做甚麼。"},{"en":"A coach may give instructions from the side of a track about pace, posture, or breathing.","zh":"教練可能在跑道旁就步速、姿勢或呼吸發出指示。"},{"en":"Coaching is more than giving instructions because athletes also need planning, trust, and care.","zh":"教練工作不只是發號施令，因為運動員也需要計劃、信任和照顧。"},{"en":"Someone can shout instructions, but real coaching helps athletes understand why they act.","zh":"有人可以大聲給指示，但真正教練會幫助運動員明白為何要這樣做。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"creating the conditions in which","meaning":"創造讓……能夠……的條件","examples":[{"en":"Coaching means creating the conditions in which athletes can grow.","zh":"教練工作意味着創造讓運動員能夠成長的條件。"},{"en":"Creating the conditions in which something can happen means building an environment that makes it possible.","zh":"creating the conditions in which 某事能發生，指建立令它成為可能的環境。"},{"en":"Teachers create the conditions in which students can ask questions without fear.","zh":"老師創造讓學生能夠不怕提問的條件。"},{"en":"If a workplace creates the conditions in which staff feel respected, people may work better.","zh":"如果工作場所創造讓員工感到受尊重的條件，人們可能工作得更好。"},{"en":"Growth often depends not only on effort, but on the conditions around people.","zh":"成長往往不只取決於努力，也取決於人周圍的條件。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"train bravely","meaning":"勇敢地訓練","examples":[{"en":"A good coach helps athletes train bravely.","zh":"好教練幫助運動員勇敢地訓練。"},{"en":"To train bravely means to practise with courage, even when the task is difficult or frightening.","zh":"train bravely 指即使任務困難或令人害怕，仍有勇氣練習。"},{"en":"A beginner trains bravely when they try a new skill after failing before.","zh":"初學者在失敗後仍嘗試新技能時，就是勇敢地訓練。"},{"en":"Athletes train bravely when they are supported enough to take safe risks.","zh":"當運動員得到足夠支援去承擔安全風險時，就是勇敢地訓練。"},{"en":"Training bravely does not mean ignoring danger; it means facing challenge with guidance.","zh":"勇敢訓練不代表無視危險；而是在指導下面對挑戰。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"compete wisely","meaning":"明智地比賽","examples":[{"en":"A good coach helps athletes compete wisely.","zh":"好教練幫助運動員明智地比賽。"},{"en":"To compete wisely means to make smart choices during competition, not only to try hard.","zh":"compete wisely 指在比賽中作出聰明選擇，而不只是努力。"},{"en":"A runner competes wisely by saving energy for the final lap.","zh":"跑手保留體力給最後一圈，就是明智地比賽。"},{"en":"Athletes who compete wisely know when to attack, wait, or protect themselves.","zh":"明智比賽的運動員知道何時進攻、等待或保護自己。"},{"en":"Competing wisely can matter as much as strength because poor decisions waste ability.","zh":"明智地比賽可能和力量一樣重要，因為錯誤決定會浪費能力。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"stand tall","meaning":"昂然面對；保持自信","examples":[{"en":"Athletes should stand tall whatever the result may be.","zh":"無論結果如何，運動員都應昂然面對。"},{"en":"To stand tall means to stay proud, confident, and respectful even after difficulty or failure.","zh":"stand tall 指即使經歷困難或失敗，仍保持自信、自尊和尊重。"},{"en":"A student can stand tall after losing a debate if they prepared honestly and learned from it.","zh":"學生如果誠實準備並從中學習，即使輸掉辯論也可以昂然面對。"},{"en":"People stand tall when they accept results without shame or bitterness.","zh":"人們在不羞愧、不怨恨地接受結果時，就是昂然面對。"},{"en":"Standing tall does not mean pretending not to feel sad; it means keeping dignity.","zh":"昂然面對不代表假裝不難過；而是保持尊嚴。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"whatever the result may be","meaning":"無論結果如何","examples":[{"en":"Athletes should stand tall whatever the result may be.","zh":"無論結果如何，運動員都應昂然面對。"},{"en":"Whatever the result may be means no matter whether the outcome is good or bad.","zh":"whatever the result may be 指不論結果是好是壞。"},{"en":"Whatever the result may be, students should review what they learned after a competition.","zh":"無論結果如何，學生在比賽後都應回顧自己學到甚麼。"},{"en":"This phrase is useful when the attitude matters more than the final score.","zh":"當態度比最終分數更重要時，這個短語很有用。"},{"en":"Whatever the result may be, honest effort still has value.","zh":"無論結果如何，誠實努力仍然有價值。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"I enclose my curriculum vitae","meaning":"隨函附上我的履歷","examples":[{"en":"I enclose my curriculum vitae for your consideration.","zh":"我隨函附上我的履歷，供你考慮。"},{"en":"I enclose my curriculum vitae means I include my CV with this application or letter.","zh":"I enclose my curriculum vitae 指我在申請或信件中附上我的履歷。"},{"en":"In a job application email, a person may write, “I enclose my curriculum vitae” to show the CV is attached.","zh":"在求職電郵中，人們可能寫 “I enclose my curriculum vitae” 來表示履歷已附上。"},{"en":"This phrase helps the reader know where to find details about education and experience.","zh":"這個短語幫助讀者知道在哪裡找到教育和經驗詳情。"},{"en":"It is a formal phrase, so it suits application letters more than casual messages.","zh":"這是正式用語，所以比起閒談訊息，更適合求職信。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"for your consideration","meaning":"供你考慮","examples":[{"en":"I enclose my curriculum vitae for your consideration.","zh":"我隨函附上我的履歷，供你考慮。"},{"en":"For your consideration means so that you can read, think about, and judge it.","zh":"for your consideration 指讓你閱讀、思考和判斷。"},{"en":"A student may submit a proposal to the teacher for consideration.","zh":"學生可能向老師提交建議書，供老師考慮。"},{"en":"People use for your consideration in formal writing when asking someone to review something.","zh":"人們在正式寫作中使用 for your consideration，要求對方審閱某事。"},{"en":"This phrase is polite because it does not force the reader to accept the request.","zh":"這個短語很有禮貌，因為它不強迫讀者接受請求。"}],"source":"2021 Q4.pdf","sourcePage":12},{"front":"appreciate the opportunity to","meaning":"感激有機會……","examples":[{"en":"He would appreciate the opportunity to attend an interview.","zh":"他會感激有機會出席面試。"},{"en":"To appreciate the opportunity to do something means to be grateful for the chance to do it.","zh":"appreciate the opportunity to do something 指感激有機會做某事。"},{"en":"A student may appreciate the opportunity to join an exchange programme.","zh":"學生可能感激有機會參加交流計劃。"},{"en":"People use this phrase politely when they hope to be given a chance.","zh":"人們希望獲得機會時，會禮貌地使用這個短語。"},{"en":"Appreciating an opportunity means you value it and will treat it seriously.","zh":"感激一個機會，意思是你重視它並會認真對待。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"attend an interview","meaning":"出席面試","examples":[{"en":"He would appreciate the opportunity to attend an interview.","zh":"他會感激有機會出席面試。"},{"en":"To attend an interview means to go to a formal meeting where someone asks questions about your suitability.","zh":"attend an interview 指出席正式會面，讓對方提問以了解你是否合適。"},{"en":"A job applicant may attend an interview after sending a strong CV.","zh":"求職者寄出有力履歷後，可能獲邀出席面試。"},{"en":"People attend interviews so employers can learn more than what is written on paper.","zh":"人們出席面試，讓僱主了解履歷以外的更多資料。"},{"en":"Before attending an interview, applicants should prepare examples of their experience.","zh":"出席面試前，申請人應準備好自己經驗的例子。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"explain in greater detail","meaning":"更詳細地解釋","examples":[{"en":"He hopes to explain in greater detail how his experience could benefit the Foundation.","zh":"他希望更詳細地解釋他的經驗如何使基金會受益。"},{"en":"To explain in greater detail means to give more information so something becomes clearer.","zh":"explain in greater detail 指提供更多資料，令某事更清楚。"},{"en":"A teacher may explain in greater detail when students still look confused.","zh":"當學生仍看起來困惑時，老師可能會更詳細地解釋。"},{"en":"Explaining in greater detail helps readers understand reasons, examples, and consequences.","zh":"更詳細地解釋能幫助讀者理解原因、例子和後果。"},{"en":"In an interview, candidates can explain in greater detail what a short CV point really means.","zh":"在面試中，候選人可以更詳細地解釋履歷上一個簡短要點真正代表甚麼。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"benefit the Foundation","meaning":"使基金會受益","examples":[{"en":"His experience could benefit the Hong Kong Sports Foundation.","zh":"他的經驗可以使香港體育基金會受益。"},{"en":"To benefit the Foundation means to help the organisation become stronger or achieve its aims.","zh":"benefit the Foundation 指幫助該組織變得更強或達成目標。"},{"en":"A volunteer’s language skills may benefit the Foundation during international events.","zh":"義工的語言技能可能在國際活動中使基金會受益。"},{"en":"Experience can benefit an organisation when it solves real problems, not just looks impressive.","zh":"經驗在能解決真實問題時，才會使組織受益，而不只是看起來亮眼。"},{"en":"The best way to benefit the Foundation is to connect personal skills with its needs.","zh":"使基金會受益的最好方法，是把個人技能與其需要連接起來。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"Thank you for considering my application","meaning":"感謝你考慮我的申請","examples":[{"en":"Thank you for considering my application.","zh":"感謝你考慮我的申請。"},{"en":"Thank you for considering my application is a polite formal sentence used to thank someone for reviewing your request for a job or place.","zh":"Thank you for considering my application 是正式禮貌句，用來感謝對方審閱你的職位或名額申請。"},{"en":"An applicant may write this near the end of a cover letter.","zh":"申請人可能在求職信接近結尾時寫這句。"},{"en":"This sentence shows respect because the reader has spent time looking at the application.","zh":"這句顯示尊重，因為讀者花時間查看申請。"},{"en":"It is often followed by a closing sentence, such as hoping to hear from the reader.","zh":"它後面常接結尾句，例如希望收到對方回覆。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"I look forward to hearing from you","meaning":"期待你的回覆","examples":[{"en":"I look forward to hearing from you.","zh":"我期待你的回覆。"},{"en":"I look forward to hearing from you means I hope to receive your reply in the future.","zh":"I look forward to hearing from you 的意思是我希望日後收到你的回覆。"},{"en":"A student may use this sentence after asking a teacher for a meeting.","zh":"學生向老師要求會面後，可能使用這句。"},{"en":"This phrase is polite because it shows interest without demanding an immediate answer.","zh":"這個短語很有禮貌，因為它表達期待，但不要求對方立即回答。"},{"en":"It is common in formal emails, applications, and letters.","zh":"它常見於正式電郵、申請和信件中。"}],"source":"2021 Q4.pdf","sourcePage":13},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"Yours faithfully is used to close a formal application letter.","zh":"Yours faithfully 用於正式申請信的結尾。"},{"en":"Yours faithfully is a formal closing used when ending certain letters politely.","zh":"Yours faithfully 是某些信件結尾時使用的正式禮貌結語。"},{"en":"A job applicant may write Yours faithfully before signing their name.","zh":"求職者可能在簽名前寫 Yours faithfully。"},{"en":"This closing helps the letter sound respectful and complete.","zh":"這個結語令信件聽起來尊重而完整。"},{"en":"Yours faithfully is suitable for formal letters, but it would sound too stiff in a casual text message.","zh":"Yours faithfully 適合正式信件，但在 casual 短訊中會顯得太生硬。"}],"source":"2021 Q4.pdf","sourcePage":13}],"dse/writing/part-b/2021/Q5":[{"front":"familiarity","meaning":"熟悉感","examples":[{"en":"Familiarity is not the same as trust.","zh":"熟悉感並不等於信任。"},{"en":"Familiarity means knowing someone or something because you have seen it often.","zh":"熟悉感是指因為經常看見某人或某事物而對其產生認識。"},{"en":"A familiar shop may feel comfortable even if its products are not better.","zh":"一間熟悉的商店可能令人感到安心，即使它的產品並不更好。"},{"en":"Seeing the same influencer every day can create familiarity and make viewers less cautious.","zh":"每天看到同一位KOL可以產生熟悉感，令觀眾降低警覺。"},{"en":"Familiarity can make a message feel safe, but it does not prove honesty.","zh":"熟悉感可以令訊息感覺可靠，但不能證明它誠實。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"not the same as","meaning":"與……並不相同","examples":[{"en":"Familiarity is not the same as trust.","zh":"熟悉感與信任並不相同。"},{"en":"“Not the same as” shows that two things should not be treated as equal.","zh":"「not the same as」表示兩件事不應被視為相等。"},{"en":"Being popular is not the same as being knowledgeable.","zh":"受歡迎與有知識並不相同。"},{"en":"A high price is not the same as high quality.","zh":"價格高與品質高並不相同。"},{"en":"Looking confident is not the same as being correct.","zh":"看起來有自信與真正正確並不相同。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"in an age when","meaning":"在一個……的時代","examples":[{"en":"In an age when a phone screen has become both a shopping mall and a conversation, advertising no longer waits between television programmes.","zh":"在一個手機螢幕既成為購物商場又成為交流平台的時代，廣告不再只等在電視節目之間出現。"},{"en":"“In an age when” introduces an important feature of the period we live in.","zh":"「in an age when」用來帶出我們所處時代的一個重要特徵。"},{"en":"In an age when people shop online, advertisements can reach customers at home.","zh":"在一個人們網上購物的時代，廣告可以在家中接觸顧客。"},{"en":"In an age when news spreads instantly, false information can travel quickly too.","zh":"在一個新聞即時傳播的時代，虛假資訊也可以迅速擴散。"},{"en":"In an age when phones are always nearby, companies have many chances to attract attention.","zh":"在一個手機總在身邊的時代，公司有很多機會吸引注意。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"a phone screen","meaning":"手機螢幕","examples":[{"en":"A phone screen has become both a shopping mall and a conversation.","zh":"手機螢幕既成為購物商場，又成為交流平台。"},{"en":"A phone screen is the display on a mobile phone where users read, watch, shop, and communicate.","zh":"手機螢幕是流動電話上讓使用者閱讀、觀看、購物和溝通的顯示畫面。"},{"en":"Students may spend hours looking at a phone screen for messages and videos.","zh":"學生可能花數小時看手機螢幕上的訊息和影片。"},{"en":"A phone screen can show an advertisement while someone is chatting with friends.","zh":"一個人和朋友聊天時，手機螢幕也可能同時顯示廣告。"},{"en":"Because so much daily life happens on a phone screen, commercial messages can be difficult to avoid.","zh":"因為很多日常生活都在手機螢幕上進行，商業訊息很難完全避開。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"become both…and…","meaning":"既成為……又成為……","examples":[{"en":"A phone screen has become both a shopping mall and a conversation.","zh":"手機螢幕既成為購物商場，又成為交流平台。"},{"en":"“Become both A and B” means something develops two different roles at the same time.","zh":"「become both A and B」表示某事物同時發展出兩種不同角色。"},{"en":"A café can become both a workplace and a meeting place.","zh":"咖啡店可以既成為工作場所，又成為見面地點。"},{"en":"Social media has become both a source of entertainment and a place for advertising.","zh":"社交媒體既成為娛樂來源，又成為廣告平台。"},{"en":"When one platform becomes both personal and commercial, users may find the two roles difficult to separate.","zh":"當一個平台既屬私人又屬商業用途，使用者可能難以分清兩種角色。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"no longer waits between","meaning":"不再只等在……之間出現","examples":[{"en":"Advertising no longer waits between television programmes.","zh":"廣告不再只等在電視節目之間出現。"},{"en":"“No longer” means something that happened in the past does not happen in the same way now.","zh":"「no longer」表示過去會發生的事情現在已不再以相同方式發生。"},{"en":"News no longer waits for the morning newspaper; it appears instantly online.","zh":"新聞不再等到早報出版，而是即時在網上出現。"},{"en":"Advertising no longer waits between shows because it can enter social media posts directly.","zh":"廣告不再只等在節目之間出現，因為它可以直接進入社交媒體帖文。"},{"en":"When promotion no longer waits for a clear advertising break, people may not notice it immediately.","zh":"當推廣不再等待清楚的廣告時段，人們可能不會立即察覺。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"television programmes","meaning":"電視節目","examples":[{"en":"Advertising no longer waits between television programmes.","zh":"廣告不再只等在電視節目之間出現。"},{"en":"Television programmes are shows broadcast on television, such as dramas, news, and documentaries.","zh":"電視節目是在電視播放的內容，例如劇集、新聞和紀錄片。"},{"en":"Families may watch television programmes together after dinner.","zh":"家庭可能在晚飯後一起觀看電視節目。"},{"en":"Traditional advertisements often appear during breaks between television programmes.","zh":"傳統廣告常在電視節目之間的休息時段播放。"},{"en":"Streaming services have changed how many people watch television programmes.","zh":"串流平台改變了很多人觀看電視節目的方式。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"slips into","meaning":"悄悄滲入","examples":[{"en":"Advertising slips into daily routines, livestreams, and “honest reviews”.","zh":"廣告悄悄滲入日常生活習慣、直播和所謂的「真誠評測」。"},{"en":"“Slip into” means to enter quietly or gradually without attracting much attention.","zh":"「slip into」表示在不太引人注意的情況下悄悄或逐漸進入。"},{"en":"Advertising can slip into a cooking video when the host casually mentions a brand.","zh":"當主持人隨意提到某個品牌時，廣告可以悄悄滲入烹飪影片。"},{"en":"Commercial messages slip into daily life when people see them while checking messages.","zh":"當人們查看訊息時看到商業內容，廣告便悄悄滲入日常生活。"},{"en":"When advertising slips into ordinary content, viewers may not recognise it as promotion.","zh":"當廣告滲入普通內容，觀眾可能不會察覺它其實是推廣。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"daily routines","meaning":"日常生活習慣","examples":[{"en":"Advertising slips into daily routines, livestreams, and “honest reviews”.","zh":"廣告悄悄滲入日常生活習慣、直播和所謂的「真誠評測」。"},{"en":"Daily routines are activities people regularly do each day, such as eating breakfast or travelling to work.","zh":"日常生活習慣是人們每天經常做的活動，例如吃早餐或上班。"},{"en":"Checking social media has become part of many teenagers’ daily routines.","zh":"查看社交媒體已成為很多青少年的日常生活習慣。"},{"en":"Advertisers enter daily routines by placing products in morning or exercise videos.","zh":"廣告商透過在早晨生活或運動影片中放入產品，進入人們的日常生活習慣。"},{"en":"When promotion becomes part of daily routines, it can feel less like traditional advertising.","zh":"當推廣成為日常生活習慣的一部分，它可能不像傳統廣告那麼明顯。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"livestreams","meaning":"直播","examples":[{"en":"Advertising often appears in livestreams.","zh":"廣告經常出現在直播中。"},{"en":"Livestreams are videos broadcast over the internet while events are happening.","zh":"直播是在事情發生的同時透過互聯網播放的影片。"},{"en":"A gamer may talk to viewers and demonstrate a product during a livestream.","zh":"遊戲直播主可以在直播期間一邊與觀眾交談，一邊示範產品。"},{"en":"Viewers can comment immediately during livestreams, making the experience feel personal.","zh":"觀眾可以在直播期間即時留言，因此體驗會感覺較私人。"},{"en":"Because livestreams feel informal, sponsored products may seem like casual recommendations.","zh":"因為直播感覺較隨意，贊助產品可能看起來像普通推薦。"}],"source":"2021 Q5.pdf","sourcePage":1},{"front":"honest reviews","meaning":"真誠評測","examples":[{"en":"Advertising may appear inside so-called “honest reviews”.","zh":"廣告可能出現在所謂的「真誠評測」之中。"},{"en":"Honest reviews are supposed to give a genuine opinion about a product’s strengths and weaknesses.","zh":"真誠評測應該如實說明產品的優點和缺點。"},{"en":"A useful honest review explains both what worked and what disappointed the reviewer.","zh":"有用的真誠評測會同時解釋哪些地方好用，以及哪些地方令人失望。"},{"en":"If a reviewer hides payment from a company, viewers may question whether the review is truly honest.","zh":"如果評測者隱瞞公司付款，觀眾可能會懷疑評測是否真的誠實。"},{"en":"An honest review should help consumers judge a product rather than simply persuade them to buy it.","zh":"真誠評測應幫助消費者判斷產品，而不是只說服他們購買。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"surveys show that","meaning":"調查顯示","examples":[{"en":"Surveys show that many millennials trust influencers more than traditional advertisements.","zh":"調查顯示，很多千禧世代比起傳統廣告更信任KOL。"},{"en":"“Surveys show that” introduces a finding collected from people’s answers to questions.","zh":"「surveys show that」用來帶出從受訪者回答中得到的調查結果。"},{"en":"Surveys show that many students sleep less during examination periods.","zh":"調查顯示，很多學生在考試期間睡得較少。"},{"en":"Surveys may show that customers prefer clear prices to complicated discounts.","zh":"調查可能顯示，顧客較喜歡清楚價格，而不是複雜折扣。"},{"en":"When surveys show that an opinion is common, the result still needs to be interpreted carefully.","zh":"即使調查顯示某種意見很普遍，結果仍需要小心解讀。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"millennials","meaning":"千禧世代","examples":[{"en":"Many millennials trust influencers more than traditional advertisements.","zh":"很多千禧世代比起傳統廣告更信任KOL。"},{"en":"Millennials are generally people born from the early 1980s to the mid-1990s.","zh":"千禧世代一般指大約在1980年代初至1990年代中出生的人。"},{"en":"Many millennials grew up while the internet and mobile phones were becoming common.","zh":"很多千禧世代成長時，互聯網和流動電話正逐漸普及。"},{"en":"Companies study millennials’ shopping habits because they form a large consumer group.","zh":"公司研究千禧世代的購物習慣，因為他們是一個龐大的消費群體。"},{"en":"Millennials are not all alike, so age alone cannot predict what every person trusts.","zh":"千禧世代並非人人相同，所以不能單靠年齡預測每個人信任甚麼。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"trust influencers more than","meaning":"比起……更信任KOL","examples":[{"en":"Many millennials trust influencers more than traditional advertisements.","zh":"很多千禧世代比起傳統廣告更信任KOL。"},{"en":"“Trust A more than B” means believing that A is more reliable or honest than B.","zh":"「trust A more than B」表示認為A比B更可靠或誠實。"},{"en":"Some shoppers trust friends more than salespeople when choosing a phone.","zh":"有些消費者選購手機時，比起售貨員更信任朋友。"},{"en":"Viewers may trust influencers more than brands because influencers speak in a personal way.","zh":"觀眾可能比起品牌更信任KOL，因為KOL的說話方式較個人化。"},{"en":"Trusting influencers more than advertisements does not guarantee that their advice is more accurate.","zh":"比起廣告更信任KOL，並不保證他們的建議更準確。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"traditional advertisements","meaning":"傳統廣告","examples":[{"en":"Some viewers trust influencers more than traditional advertisements.","zh":"有些觀眾比起傳統廣告更信任KOL。"},{"en":"Traditional advertisements are paid promotional messages shown through media such as television, newspapers, radio, or billboards.","zh":"傳統廣告是透過電視、報紙、電台或廣告牌等媒體播放的付費推廣訊息。"},{"en":"A thirty-second television commercial is a common form of traditional advertisement.","zh":"三十秒的電視廣告是一種常見的傳統廣告。"},{"en":"Traditional advertisements usually make it obvious that a company is selling something.","zh":"傳統廣告通常會清楚顯示公司正在銷售某些東西。"},{"en":"Although traditional advertisements can exaggerate, viewers normally know they are watching marketing.","zh":"雖然傳統廣告可能誇大，但觀眾通常知道自己正在看市場推廣內容。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"be increasingly tempted to","meaning":"越來越想","examples":[{"en":"Companies are increasingly tempted to use personal relationships to sell products.","zh":"公司越來越想利用私人關係來銷售產品。"},{"en":"“Be increasingly tempted to” means feeling a stronger and stronger desire to do something.","zh":"「be increasingly tempted to」表示做某件事的慾望變得越來越強。"},{"en":"Students may be increasingly tempted to check their phones when lessons feel boring.","zh":"當課堂感覺沉悶時，學生可能越來越想查看手機。"},{"en":"Shops are increasingly tempted to use influencers when online audiences grow.","zh":"當網上觀眾增加，商店會越來越想使用KOL推廣。"},{"en":"Companies may be increasingly tempted to hide advertising inside personal content because it feels more persuasive.","zh":"公司可能越來越想把廣告藏在私人內容中，因為這種方式感覺更有說服力。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"personal relationships","meaning":"私人關係","examples":[{"en":"Companies use personal relationships to make marketing appear warmer.","zh":"公司利用私人關係令市場推廣顯得更親切。"},{"en":"Personal relationships are close connections between people based on familiarity, friendship, family, or regular contact.","zh":"私人關係是人與人之間因熟悉、友誼、家庭或經常接觸而形成的親近連繫。"},{"en":"A teacher and student need clear boundaries even when they have a friendly personal relationship.","zh":"即使老師和學生關係友好，也需要在私人關係中保持清楚界線。"},{"en":"Influencers build personal relationships with followers by sharing everyday experiences.","zh":"KOL透過分享日常經歷，與追蹤者建立私人關係。"},{"en":"When companies use personal relationships for selling, friendship and advertising can become difficult to separate.","zh":"當公司利用私人關係銷售產品，友誼與廣告可能變得難以分辨。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"sell products","meaning":"銷售產品","examples":[{"en":"Companies use personal relationships to sell products.","zh":"公司利用私人關係來銷售產品。"},{"en":"To sell products means to persuade customers to pay money for goods.","zh":"銷售產品是指說服顧客付款購買商品。"},{"en":"A supermarket uses discounts to sell products before their expiry dates.","zh":"超級市場會用折扣在到期日前銷售產品。"},{"en":"Influencers may sell products by showing how they use them in daily life.","zh":"KOL可能透過展示自己在日常生活中如何使用產品來銷售產品。"},{"en":"A recommendation can still be designed to sell products even if it sounds friendly.","zh":"即使一項推薦聽起來友善，它仍可能是為了銷售產品而設計。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"in order to","meaning":"為了","examples":[{"en":"Companies use personal relationships in order to make marketing appear more believable.","zh":"公司利用私人關係，為了令市場推廣顯得更可信。"},{"en":"“In order to” introduces the purpose or reason for doing something.","zh":"「in order to」用來帶出做某件事的目的或原因。"},{"en":"Students revise regularly in order to remember information for an examination.","zh":"學生定期溫習，為了在考試時記住所學內容。"},{"en":"Shops lower prices in order to attract more customers.","zh":"商店降低價格，為了吸引更多顧客。"},{"en":"Influencers may share personal stories in order to make promotions feel natural.","zh":"KOL可能分享個人故事，為了令推廣感覺更自然。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"make marketing appear warmer","meaning":"令市場推廣顯得更親切","examples":[{"en":"Companies try to make marketing appear warmer and more believable.","zh":"公司嘗試令市場推廣顯得更親切和更可信。"},{"en":"To make marketing appear warmer means to make selling feel friendlier and less commercial.","zh":"令市場推廣顯得更親切，就是令銷售感覺更友善、更不像商業活動。"},{"en":"A brand may use family stories to make marketing appear warmer.","zh":"品牌可能使用家庭故事令市場推廣顯得更親切。"},{"en":"Friendly language can make marketing appear warmer even when the main goal is still to sell.","zh":"友善的語言可以令市場推廣顯得更親切，即使主要目的仍是銷售。"},{"en":"Making marketing appear warmer can reduce viewers’ awareness that they are being persuaded.","zh":"令市場推廣顯得更親切，可能會降低觀眾對自己正在被說服的警覺。"}],"source":"2021 Q5.pdf","sourcePage":2},{"front":"more believable","meaning":"更可信","examples":[{"en":"Influencer marketing can make advertising seem more believable.","zh":"KOL市場推廣可以令廣告看起來更可信。"},{"en":"“More believable” means easier to accept as true or trustworthy.","zh":"「more believable」表示更容易令人相信是真實或可靠的。"},{"en":"A story becomes more believable when it includes clear dates and evidence.","zh":"故事包含清楚日期和證據時會變得更可信。"},{"en":"A product claim may sound more believable when a familiar person says it.","zh":"當熟悉的人提出產品聲稱時，它可能聽起來更可信。"},{"en":"Something sounding more believable does not necessarily mean it is actually true.","zh":"某件事聽起來更可信，並不代表它實際上一定是真的。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"as far as I am concerned","meaning":"就我而言","examples":[{"en":"As far as I am concerned, social media influencers are not more trustworthy than traditional advertisements.","zh":"就我而言，社交媒體KOL並不比傳統廣告更值得信任。"},{"en":"“As far as I am concerned” introduces the speaker’s personal opinion.","zh":"「as far as I am concerned」用來帶出說話者的個人意見。"},{"en":"As far as I am concerned, schools should teach students how to check online information.","zh":"就我而言，學校應教學生如何核實網上資訊。"},{"en":"As far as I am concerned, a clear advert is better than a hidden promotion.","zh":"就我而言，清楚表明的廣告比隱藏式推廣好。"},{"en":"This phrase is useful when stating a position before giving reasons.","zh":"這個片語適合在提出理由前先表明自己的立場。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"social media influencers","meaning":"社交媒體KOL","examples":[{"en":"Social media influencers are not necessarily more trustworthy than traditional advertisements.","zh":"社交媒體KOL不一定比傳統廣告更值得信任。"},{"en":"Social media influencers are people who build online audiences and can affect followers’ opinions or purchases.","zh":"社交媒體KOL是在網上建立觀眾群，並能影響追蹤者意見或購買決定的人。"},{"en":"A fashion influencer may show followers how to combine different clothes.","zh":"時裝KOL可能向追蹤者展示如何配搭不同衣服。"},{"en":"Companies pay social media influencers because their recommendations can reach specific audiences.","zh":"公司會付費給社交媒體KOL，因為他們的推薦可以接觸特定觀眾。"},{"en":"Having many followers does not automatically make social media influencers experts.","zh":"擁有很多追蹤者並不會自動令社交媒體KOL成為專家。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"not more trustworthy than","meaning":"不比……更值得信任","examples":[{"en":"Influencers are not more trustworthy than traditional advertisements.","zh":"KOL並不比傳統廣告更值得信任。"},{"en":"“Not more trustworthy than” means there is no good reason to consider one source more reliable than another.","zh":"「not more trustworthy than」表示沒有充分理由認為其中一個來源比另一個更可靠。"},{"en":"A popular review is not more trustworthy than an expert report simply because more people watched it.","zh":"一個受歡迎的評測不會只因更多人觀看，就比專家報告更值得信任。"},{"en":"A friend’s guess is not more trustworthy than medical advice from a qualified doctor.","zh":"朋友的猜測不會比合資格醫生的醫療建議更值得信任。"},{"en":"Familiar language is not more trustworthy than clearly supported evidence.","zh":"熟悉的語氣並不比有清楚證據支持的內容更值得信任。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"traditional media advertisements","meaning":"傳統媒體廣告","examples":[{"en":"Social media influencers are not more trustworthy than traditional media advertisements.","zh":"社交媒體KOL並不比傳統媒體廣告更值得信任。"},{"en":"Traditional media advertisements are promotions placed in established media such as television, radio, newspapers, and magazines.","zh":"傳統媒體廣告是刊登或播放在電視、電台、報紙和雜誌等傳統媒體上的推廣內容。"},{"en":"A full-page newspaper advert is a traditional media advertisement.","zh":"報紙上的全版廣告就是一種傳統媒體廣告。"},{"en":"Traditional media advertisements usually separate promotional content from ordinary programmes or articles.","zh":"傳統媒體廣告通常會把推廣內容與普通節目或文章分開。"},{"en":"Their commercial purpose is often easier to recognise than that of hidden online promotions.","zh":"與隱藏式網上推廣相比，它們的商業目的通常更容易辨認。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"relatable and persuasive","meaning":"容易令人產生共鳴而且有說服力","examples":[{"en":"Influencers may be more relatable and persuasive.","zh":"KOL可能更容易令人產生共鳴，而且更有說服力。"},{"en":"“Relatable and persuasive” means easy to identify with and effective at changing someone’s opinion.","zh":"「relatable and persuasive」表示容易令人感同身受，而且能有效影響別人的想法。"},{"en":"A student speaker may be relatable and persuasive if classmates recognise the problem being described.","zh":"如果同學認得演講中描述的問題，學生講者可能會更容易令人產生共鳴和被說服。"},{"en":"Influencers can seem relatable and persuasive when they discuss ordinary worries in a familiar tone.","zh":"當KOL用熟悉語氣談普通人的煩惱時，會顯得容易令人產生共鳴而且有說服力。"},{"en":"Being relatable and persuasive can make a message powerful without making it accurate.","zh":"容易令人產生共鳴和有說服力，可以令訊息很有力量，但不代表內容準確。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"relatable","meaning":"容易令人產生共鳴","examples":[{"en":"Influencers may seem relatable to their followers.","zh":"KOL在追蹤者眼中可能容易令人產生共鳴。"},{"en":"Relatable means easy to understand or identify with because something feels similar to your own experience.","zh":"「relatable」表示因為與自己的經歷相似，所以容易理解或產生認同。"},{"en":"A story about examination stress is relatable to many students.","zh":"關於考試壓力的故事對很多學生來說都容易產生共鳴。"},{"en":"Influencers seem relatable when they share ordinary problems such as tiredness or money worries.","zh":"當KOL分享疲倦或金錢壓力等普通問題時，會顯得更容易令人產生共鳴。"},{"en":"A relatable person may feel familiar, but familiarity should not replace careful judgement.","zh":"一個容易令人產生共鳴的人可能感覺很熟悉，但熟悉感不應取代仔細判斷。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"persuasive","meaning":"有說服力","examples":[{"en":"Influencers can be persuasive because they sound familiar.","zh":"KOL可能因為語氣熟悉而很有說服力。"},{"en":"Persuasive means able to make someone believe something or take a particular action.","zh":"「persuasive」表示能令別人相信某件事或採取某種行動。"},{"en":"A persuasive speech gives clear reasons and examples.","zh":"有說服力的演講會提供清楚理由和例子。"},{"en":"A salesperson may be persuasive enough to make a customer buy something unnecessary.","zh":"售貨員可能很有說服力，甚至令顧客購買不需要的東西。"},{"en":"Persuasive language can change behaviour, so listeners should still check the facts.","zh":"有說服力的語言可以改變行為，所以聽眾仍應核實事實。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"rest not on…, but on…","meaning":"不應建基於……而應建基於……","examples":[{"en":"Trust should rest not on familiarity, but on transparency, accountability, and evidence.","zh":"信任不應建基於熟悉感，而應建基於透明度、問責性和證據。"},{"en":"“Rest not on A, but on B” means something should be based on B rather than A.","zh":"「rest not on A, but on B」表示某事應以B而不是A作為基礎。"},{"en":"A hiring decision should rest not on friendship, but on ability and experience.","zh":"招聘決定不應建基於友誼，而應建基於能力和經驗。"},{"en":"A medical claim should rest not on popularity, but on reliable research.","zh":"醫療聲稱不應建基於受歡迎程度，而應建基於可靠研究。"},{"en":"Good judgement should rest not on first impressions, but on facts that can be checked.","zh":"良好判斷不應建基於第一印象，而應建基於可核實的事實。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"transparency","meaning":"透明度","examples":[{"en":"Trust should rest on transparency, accountability, and evidence.","zh":"信任應建基於透明度、問責性和證據。"},{"en":"Transparency means being open and clear about important information, decisions, or interests.","zh":"透明度是指對重要資訊、決定或利益關係保持公開和清楚。"},{"en":"A company shows transparency when it clearly states who paid for an advertisement.","zh":"公司清楚說明誰支付廣告費時，就是展現透明度。"},{"en":"Transparency helps consumers understand whether a recommendation is independent or sponsored.","zh":"透明度可以幫助消費者了解推薦是獨立意見還是受贊助內容。"},{"en":"Without transparency, people may trust a message without knowing who benefits from it.","zh":"缺乏透明度時，人們可能在不知道誰會受益的情況下信任訊息。"}],"source":"2021 Q5.pdf","sourcePage":3},{"front":"accountability","meaning":"問責性","examples":[{"en":"Trust should rest on transparency, accountability, and evidence.","zh":"信任應建基於透明度、問責性和證據。"},{"en":"Accountability means being responsible for actions and having to explain or correct mistakes.","zh":"問責性是指要為自己的行為負責，並需要解釋或改正錯誤。"},{"en":"A company shows accountability when it admits a faulty product and refunds customers.","zh":"公司承認產品有問題並向顧客退款時，就是展現問責性。"},{"en":"Public criticism creates accountability by making organisations answer for misleading claims.","zh":"公眾批評可以建立問責性，令機構必須回應誤導性聲稱。"},{"en":"Without accountability, a promoter can make promises and disappear when customers are harmed.","zh":"如果沒有問責性，推廣者可以作出承諾，顧客受損後卻一走了之。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"evidence","meaning":"證據","examples":[{"en":"Trust should be supported by evidence.","zh":"信任應得到證據支持。"},{"en":"Evidence is information, facts, or results that help show whether a claim is true.","zh":"證據是有助判斷某項聲稱是否真實的資訊、事實或結果。"},{"en":"A doctor uses test results as evidence before making a diagnosis.","zh":"醫生在作出診斷前會使用檢查結果作為證據。"},{"en":"Product claims are stronger when independent studies provide evidence for them.","zh":"如果有獨立研究提供證據，產品聲稱會更有根據。"},{"en":"Personal stories can be interesting, but they should not replace reliable evidence.","zh":"個人故事可以很吸引，但不應取代可靠證據。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"the first reason is that","meaning":"第一個原因是","examples":[{"en":"The first reason is that influencer marketing often blurs the line between personal recommendation and paid persuasion.","zh":"第一個原因是KOL市場推廣經常模糊個人推薦與付費說服之間的界線。"},{"en":"“The first reason is that” introduces the first main explanation supporting an argument.","zh":"「the first reason is that」用來帶出支持論點的第一個主要解釋。"},{"en":"The first reason is that students need enough sleep to concentrate in class.","zh":"第一個原因是學生需要充足睡眠才能在課堂集中精神。"},{"en":"The first reason is that hidden advertising makes it harder for consumers to judge motives.","zh":"第一個原因是隱藏式廣告令消費者更難判斷背後動機。"},{"en":"This phrase helps organise an essay by clearly signalling the beginning of the first argument.","zh":"這個片語可以清楚標示第一個論點的開始，令文章更有組織。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"influencer marketing","meaning":"KOL市場推廣","examples":[{"en":"Influencer marketing often blurs the line between personal recommendation and paid persuasion.","zh":"KOL市場推廣經常模糊個人推薦與付費說服之間的界線。"},{"en":"Influencer marketing is a form of promotion in which online creators recommend or display products to their followers.","zh":"KOL市場推廣是一種由網上創作者向追蹤者推薦或展示產品的推廣方式。"},{"en":"A sports brand may use influencer marketing by paying a runner to wear its shoes online.","zh":"運動品牌可以付費給跑步KOL在網上穿其跑鞋，進行KOL市場推廣。"},{"en":"Influencer marketing works partly because followers already pay attention to the creator.","zh":"KOL市場推廣部分有效，是因為追蹤者本來已經留意該創作者。"},{"en":"It becomes less trustworthy when payment or sponsorship is hidden.","zh":"當付款或贊助被隱藏時，這種推廣會變得較不可信。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"blur the line between","meaning":"模糊……之間的界線","examples":[{"en":"Influencer marketing often blurs the line between personal recommendation and paid persuasion.","zh":"KOL市場推廣經常模糊個人推薦與付費說服之間的界線。"},{"en":"To blur the line between two things means to make their difference less clear.","zh":"「blur the line between」表示令兩件事之間的分別變得不清楚。"},{"en":"Working from home can blur the line between work time and family time.","zh":"在家工作可能模糊工作時間與家庭時間之間的界線。"},{"en":"Sponsored videos can blur the line between entertainment and advertising.","zh":"贊助影片可以模糊娛樂與廣告之間的界線。"},{"en":"When the line is blurred, people may mistake a commercial message for an independent opinion.","zh":"當界線變得模糊，人們可能把商業訊息誤當成獨立意見。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"personal recommendation","meaning":"個人推薦","examples":[{"en":"Influencer marketing can look like a personal recommendation.","zh":"KOL市場推廣可能看起來像個人推薦。"},{"en":"A personal recommendation is advice given by an individual based on what appears to be their own opinion or experience.","zh":"個人推薦是某人根據看似屬於自己的意見或經驗而給出的建議。"},{"en":"A friend telling you which restaurant they enjoyed is a personal recommendation.","zh":"朋友告訴你哪間餐廳好吃，就是個人推薦。"},{"en":"Viewers may trust a personal recommendation because it feels less formal than an advertisement.","zh":"觀眾可能信任個人推薦，因為它感覺不像廣告那麼正式。"},{"en":"A paid message should not pretend to be a purely personal recommendation.","zh":"付費訊息不應假裝成純粹的個人推薦。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"paid persuasion","meaning":"付費說服","examples":[{"en":"Influencer marketing may actually be paid persuasion.","zh":"KOL市場推廣實際上可能是付費說服。"},{"en":"Paid persuasion means someone receives money or benefits to influence another person’s opinion or behaviour.","zh":"付費說服是指某人收取金錢或利益，以影響另一個人的意見或行為。"},{"en":"A sponsored video recommending a phone is a form of paid persuasion.","zh":"一段受贊助並推薦手機的影片就是付費說服。"},{"en":"Paid persuasion is not automatically dishonest if the commercial relationship is clearly stated.","zh":"如果商業關係清楚說明，付費說服不一定是不誠實的。"},{"en":"Problems arise when paid persuasion is presented as completely independent advice.","zh":"當付費說服被包裝成完全獨立的建議時，就會出現問題。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"whether…or…","meaning":"無論是……還是……","examples":[{"en":"A traditional advertisement, whether on television, in a newspaper, or on a billboard, normally announces itself officially as an advertisement.","zh":"傳統廣告，無論是在電視、報紙還是廣告牌上，通常都會正式表明自己是廣告。"},{"en":"“Whether A or B” means the statement remains true for either possibility.","zh":"「whether A or B」表示無論是哪一種情況，後面的說法都成立。"},{"en":"Whether you travel by bus or train, you should leave enough time.","zh":"無論你乘巴士還是火車，都應預留足夠時間。"},{"en":"Whether a promotion appears online or in print, consumers should know who paid for it.","zh":"無論推廣出現在網上還是印刷媒體，消費者都應知道誰支付了費用。"},{"en":"This structure is useful when several different situations lead to the same conclusion.","zh":"當幾種不同情況都導向同一結論時，這個句式很有用。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"on a billboard","meaning":"在廣告牌上","examples":[{"en":"A traditional advertisement may appear on a billboard.","zh":"傳統廣告可能出現在廣告牌上。"},{"en":"A billboard is a large outdoor board used to display advertisements or public messages.","zh":"廣告牌是戶外大型展示板，用來展示廣告或公共訊息。"},{"en":"Drivers often see advertisements on a billboard beside a busy road.","zh":"駕駛者經常在繁忙道路旁的廣告牌上看到廣告。"},{"en":"A company may place a new product on a billboard to reach thousands of people.","zh":"公司可能把新產品放在廣告牌上，接觸數以千計的人。"},{"en":"Unlike a hidden social media promotion, an advert on a billboard is usually easy to recognise.","zh":"與隱藏式社交媒體推廣不同，廣告牌上的廣告通常很容易辨認。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"announce itself officially as","meaning":"正式表明自己是……","examples":[{"en":"A traditional advertisement normally announces itself officially as an advertisement.","zh":"傳統廣告通常會正式表明自己是廣告。"},{"en":"To announce itself officially as something means to identify its nature clearly and openly.","zh":"「announce itself officially as」表示清楚而公開地表明自己的性質。"},{"en":"A sponsored article should announce itself officially as paid content.","zh":"受贊助文章應正式表明自己是付費內容。"},{"en":"A charity event announces itself officially as a fundraiser so visitors know its purpose.","zh":"慈善活動會正式表明自己是籌款活動，讓訪客知道其目的。"},{"en":"When commercial material announces itself officially as advertising, consumers can judge it more cautiously.","zh":"當商業內容正式表明自己是廣告，消費者便能更謹慎地判斷。"}],"source":"2021 Q5.pdf","sourcePage":4},{"front":"be well informed that","meaning":"清楚知道","examples":[{"en":"The audience is well informed that a company is trying to sell something.","zh":"觀眾清楚知道公司正在試圖銷售某些東西。"},{"en":"To be well informed that something is happening means to know the relevant fact clearly.","zh":"「be well informed that」表示清楚知道某項相關事實。"},{"en":"Patients should be well informed that a treatment may have side effects.","zh":"病人應清楚知道治療可能有副作用。"},{"en":"Customers should be well informed that an online post is sponsored.","zh":"顧客應清楚知道一篇網上帖文是受贊助的。"},{"en":"When audiences are well informed that money is involved, they can judge recommendations more carefully.","zh":"當觀眾清楚知道當中涉及金錢，他們可以更小心判斷推薦內容。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"try to sell something","meaning":"試圖銷售某物","examples":[{"en":"The audience knows that a company is trying to sell something.","zh":"觀眾知道公司正在試圖銷售某些東西。"},{"en":"To try to sell something means to encourage another person to buy a product or service.","zh":"試圖銷售某物是指鼓勵另一個人購買產品或服務。"},{"en":"A shop assistant may try to sell something by explaining its features.","zh":"售貨員可能透過解釋產品功能來試圖銷售某物。"},{"en":"An influencer can try to sell something without directly saying, “Buy this now.”","zh":"KOL即使沒有直接說「現在買」，仍可能正在試圖銷售某物。"},{"en":"Recognising that someone is trying to sell something helps consumers judge the message more carefully.","zh":"意識到有人正在試圖銷售某物，有助消費者更小心判斷訊息。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"watch with caution","meaning":"帶着警覺觀看","examples":[{"en":"The audience can watch with caution.","zh":"觀眾可以帶着警覺觀看。"},{"en":"To watch with caution means to pay attention while remaining careful and sceptical.","zh":"「watch with caution」表示一邊觀看，一邊保持小心和懷疑。"},{"en":"People should watch with caution when a video promises impossible health results.","zh":"當影片承諾不可能的健康效果時，人們應帶着警覺觀看。"},{"en":"Viewers may watch with caution when they know a company paid for the content.","zh":"當觀眾知道內容由公司付費，他們可能會帶着警覺觀看。"},{"en":"Watching with caution does not mean rejecting everything; it means checking before believing.","zh":"帶着警覺觀看不代表拒絕所有內容，而是相信之前先作核實。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, an influencer’s promotion is often placed inside ordinary-looking content.","zh":"相比之下，KOL的推廣內容經常被放在看似普通的內容中。"},{"en":"“By contrast” introduces a clear difference from the situation just mentioned.","zh":"「by contrast」用來帶出與前面情況明顯不同的另一種情況。"},{"en":"Traditional adverts clearly show a brand; by contrast, sponsored posts may look personal.","zh":"傳統廣告會清楚展示品牌；相比之下，贊助帖文可能看起來很私人。"},{"en":"City buses are frequent; by contrast, rural buses may come only a few times a day.","zh":"城市巴士班次頻密；相比之下，鄉郊巴士一天可能只有數班。"},{"en":"This phrase is useful when comparing two situations that work differently.","zh":"當比較兩種運作方式不同的情況時，這個片語很有用。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"an influencer’s promotion","meaning":"KOL的推廣內容","examples":[{"en":"An influencer’s promotion is often placed inside ordinary-looking content.","zh":"KOL的推廣內容經常被放在看似普通的內容中。"},{"en":"An influencer’s promotion is content in which an online creator encourages interest in a product, service, or brand.","zh":"KOL的推廣內容是網上創作者鼓勵觀眾留意某項產品、服務或品牌的內容。"},{"en":"An influencer’s promotion may appear during a makeup tutorial or travel video.","zh":"KOL的推廣內容可能出現在化妝教學或旅遊影片中。"},{"en":"Payment can affect how positively an influencer’s promotion describes a product.","zh":"收取費用可能影響KOL的推廣內容對產品的描述有多正面。"},{"en":"An influencer’s promotion should be clearly labelled when a commercial relationship exists.","zh":"如果存在商業關係，KOL的推廣內容應有清楚標示。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"ordinary-looking content","meaning":"看似普通的內容","examples":[{"en":"An influencer’s promotion is often placed inside ordinary-looking content.","zh":"KOL的推廣內容經常被放在看似普通的內容中。"},{"en":"Ordinary-looking content appears casual or non-commercial even when it may have a hidden purpose.","zh":"看似普通的內容表面上很隨意或沒有商業性，即使背後可能有隱藏目的。"},{"en":"A sponsored drink may appear in ordinary-looking content about someone’s morning routine.","zh":"一款受贊助飲品可能出現在某人的早晨日常這類看似普通的內容中。"},{"en":"Ordinary-looking content can make advertising harder to recognise.","zh":"看似普通的內容可以令廣告更難被辨認。"},{"en":"Viewers should check labels because ordinary-looking content may still be carefully planned promotion.","zh":"觀眾應查看標籤，因為看似普通的內容仍可能是經仔細策劃的推廣。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"a morning routine","meaning":"早晨日常影片","examples":[{"en":"A promotion may appear inside a morning routine video.","zh":"推廣內容可能出現在早晨日常影片中。"},{"en":"A morning routine is the usual set of activities someone does after waking up.","zh":"早晨日常是某人起床後通常會做的一連串活動。"},{"en":"A student’s morning routine may include breakfast, getting dressed, and travelling to school.","zh":"學生的早晨日常可能包括吃早餐、換衣服和上學。"},{"en":"Influencers may include skincare or food products naturally inside a morning routine.","zh":"KOL可能自然地把護膚品或食物放進早晨日常內容。"},{"en":"Because a morning routine feels personal, advertising inside it may seem like ordinary advice.","zh":"因為早晨日常感覺很私人，當中的廣告可能看起來像普通建議。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"what I eat in a day","meaning":"一日飲食影片","examples":[{"en":"A promotion may appear in a “what I eat in a day” video.","zh":"推廣內容可能出現在「一日飲食」影片中。"},{"en":"A “what I eat in a day” video shows the meals and snacks someone eats during one day.","zh":"「一日飲食」影片會展示某人在一天內吃的正餐和小食。"},{"en":"Viewers may watch a “what I eat in a day” video for meal ideas.","zh":"觀眾可能觀看「一日飲食」影片來尋找用餐靈感。"},{"en":"A food brand may sponsor part of a “what I eat in a day” video.","zh":"食品品牌可能贊助「一日飲食」影片中的部分內容。"},{"en":"Such videos can look personal even when some products are included for commercial reasons.","zh":"即使某些產品因商業原因被加入，這類影片仍可能看起來很私人。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"a travel vlog","meaning":"旅行影片網誌","examples":[{"en":"A promotion may appear in a travel vlog.","zh":"推廣內容可能出現在旅行影片網誌中。"},{"en":"A travel vlog is a video diary in which someone shares experiences from a journey or destination.","zh":"旅行影片網誌是某人以影片日記方式分享旅程或目的地經歷。"},{"en":"A travel vlog may show hotels, food, transport, and local attractions.","zh":"旅行影片網誌可能展示酒店、食物、交通和本地景點。"},{"en":"A hotel can pay a creator to feature its rooms in a travel vlog.","zh":"酒店可以付費給創作者，讓其房間出現在旅行影片網誌中。"},{"en":"Viewers should distinguish between genuine travel experience and paid promotion inside a travel vlog.","zh":"觀眾應分辨旅行影片網誌中的真實旅遊經驗與付費推廣。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"a livestream chat","meaning":"直播聊天","examples":[{"en":"A promotion may appear in a livestream chat.","zh":"推廣內容可能出現在直播聊天中。"},{"en":"A livestream chat is a real-time online conversation between a creator and viewers during a live broadcast.","zh":"直播聊天是創作者在直播期間與觀眾進行的即時網上對話。"},{"en":"Followers may ask questions directly during a livestream chat.","zh":"追蹤者可以在直播聊天中直接提出問題。"},{"en":"A creator can mention a sponsored product casually during a livestream chat.","zh":"創作者可以在直播聊天中隨意提到受贊助產品。"},{"en":"Because the conversation feels spontaneous, viewers may overlook the commercial purpose.","zh":"因為對話感覺即興，觀眾可能忽略背後的商業目的。"}],"source":"2021 Q5.pdf","sourcePage":5},{"front":"after following the same creator for months","meaning":"追蹤同一位創作者數月後","examples":[{"en":"After following the same creator for months, viewers may feel close to that person.","zh":"追蹤同一位創作者數月後，觀眾可能會覺得與那個人很親近。"},{"en":"This phrase describes what may happen after someone regularly watches the same online creator for a long period.","zh":"這個片語描述某人長期定期觀看同一位網上創作者後可能出現的情況。"},{"en":"After following the same creator for months, a teenager may recognise their habits and favourite phrases.","zh":"追蹤同一位創作者數月後，青少年可能會認得對方的習慣和常用說話。"},{"en":"Familiarity grows after following the same creator for months and seeing personal details repeatedly.","zh":"追蹤同一位創作者數月並反覆看到私人細節後，熟悉感會增加。"},{"en":"After following the same creator for months, viewers may trust recommendations more easily even without strong evidence.","zh":"追蹤同一位創作者數月後，觀眾即使沒有強力證據，也可能更容易相信推薦。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"feel as if","meaning":"感覺好像","examples":[{"en":"Viewers may feel as if they know the creator personally.","zh":"觀眾可能感覺好像親身認識那位創作者。"},{"en":"“Feel as if” means having the impression that something is true even when it may not actually be so.","zh":"「feel as if」表示有一種某件事是真實的感覺，即使實際上未必如此。"},{"en":"A good novel can make readers feel as if they are living inside the story.","zh":"一本好小說可以令讀者感覺好像自己活在故事之中。"},{"en":"Followers may feel as if an influencer is a friend because they hear personal stories every day.","zh":"追蹤者每天聽到KOL分享私人故事，可能感覺好像對方是朋友。"},{"en":"Feeling as if you know someone online is different from actually having a two-way relationship.","zh":"感覺好像認識網上某人，與真正擁有雙向關係是兩回事。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"know someone personally","meaning":"親身認識某人","examples":[{"en":"Viewers may feel as if they know the influencer personally.","zh":"觀眾可能感覺好像親身認識那位KOL。"},{"en":"To know someone personally means to have a real individual relationship with them rather than simply knowing about them.","zh":"親身認識某人是指真正與對方有個人關係，而不只是知道對方的資料。"},{"en":"You may recognise a famous actor without knowing them personally.","zh":"你可能認得一位著名演員，但並不代表你親身認識他。"},{"en":"Followers can know many details about an influencer without knowing that person personally.","zh":"追蹤者可以知道KOL很多事情，卻仍然沒有親身認識那個人。"},{"en":"Knowing someone personally usually involves real interaction, not only watching their content.","zh":"親身認識某人通常涉及真正互動，而不只是觀看對方的內容。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"emotional closeness","meaning":"情感上的親近感","examples":[{"en":"Emotional closeness makes the message sound like friendly advice.","zh":"情感上的親近感令訊息聽起來像朋友般的建議。"},{"en":"Emotional closeness is the feeling of being emotionally connected to and comfortable with another person.","zh":"情感上的親近感是指與另一個人在情感上感到連繫和自在。"},{"en":"Close friends often develop emotional closeness by sharing worries and supporting each other.","zh":"親密朋友常透過分享煩惱和互相支持建立情感上的親近感。"},{"en":"Influencers can create emotional closeness by regularly discussing personal experiences.","zh":"KOL可以透過經常分享個人經歷來建立情感上的親近感。"},{"en":"Emotional closeness may increase trust even when the audience does not know the creator in real life.","zh":"即使觀眾現實中不認識創作者，情感上的親近感仍可能增加信任。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"make the message sound like","meaning":"令訊息聽起來像","examples":[{"en":"Emotional closeness makes the message sound like friendly advice.","zh":"情感上的親近感令訊息聽起來像朋友般的建議。"},{"en":"“Make the message sound like” means to cause a statement to seem similar in tone or purpose to something else.","zh":"「make the message sound like」表示令一段說話在語氣或目的上顯得像另一種東西。"},{"en":"Casual language can make the message sound like a conversation rather than an advertisement.","zh":"隨意的語言可以令訊息聽起來像對話，而不是廣告。"},{"en":"Personal stories may make the message sound like genuine experience.","zh":"個人故事可能令訊息聽起來像真實經驗。"},{"en":"The way a message sounds can influence trust even when its commercial purpose is unchanged.","zh":"訊息聽起來的方式可以影響信任，即使其商業目的沒有改變。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"friendly advice","meaning":"朋友般的建議","examples":[{"en":"The message may sound like friendly advice instead of commercial persuasion.","zh":"訊息可能聽起來像朋友般的建議，而不是商業說服。"},{"en":"Friendly advice is helpful guidance given in a warm, informal way by someone who seems to care about you.","zh":"朋友般的建議是由看似關心你的人，以親切和非正式方式提供的有用意見。"},{"en":"A classmate suggesting an easier study method is giving friendly advice.","zh":"同學建議你使用較容易的溫習方法，就是朋友般的建議。"},{"en":"Advertising can imitate friendly advice by using personal language and everyday stories.","zh":"廣告可以透過私人語言和日常故事，模仿朋友般的建議。"},{"en":"Consumers should ask whether apparently friendly advice is connected to payment or sponsorship.","zh":"消費者應問清楚，看似朋友般的建議是否與付款或贊助有關。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"instead of","meaning":"而不是","examples":[{"en":"The message may sound like friendly advice instead of commercial persuasion.","zh":"訊息可能聽起來像朋友般的建議，而不是商業說服。"},{"en":"“Instead of” means one thing happens or is chosen in place of another.","zh":"「instead of」表示用一件事取代另一件事。"},{"en":"A student may walk instead of taking the bus.","zh":"學生可能步行，而不是乘巴士。"},{"en":"A company may use a personal story instead of a formal advertisement.","zh":"公司可能使用個人故事，而不是正式廣告。"},{"en":"When advertising looks like advice instead of promotion, its purpose can be harder to recognise.","zh":"當廣告看起來像建議而不是推廣時，其目的可能更難辨認。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"commercial persuasion","meaning":"商業說服","examples":[{"en":"The message may hide its nature as commercial persuasion.","zh":"訊息可能隱藏自己作為商業說服的本質。"},{"en":"Commercial persuasion is communication designed to influence people so that they buy or support something.","zh":"商業說服是為了影響人們購買或支持某項東西而設計的溝通方式。"},{"en":"A television advert uses commercial persuasion to encourage viewers to choose one brand.","zh":"電視廣告使用商業說服，鼓勵觀眾選擇某個品牌。"},{"en":"Commercial persuasion can use emotion, humour, discounts, or celebrity support.","zh":"商業說服可以使用情感、幽默、折扣或名人支持。"},{"en":"It becomes more concerning when commercial persuasion is disguised as independent advice.","zh":"當商業說服被偽裝成獨立建議時，問題會更加嚴重。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"take…for example","meaning":"以……為例","examples":[{"en":"Take a skincare influencer, for example.","zh":"以一位護膚KOL為例。"},{"en":"“Take…for example” introduces a specific case that helps explain a general point.","zh":"「take…for example」用來帶出一個具體例子，以說明較一般性的觀點。"},{"en":"Take public transport, for example: cheaper fares can encourage people to leave their cars at home.","zh":"以公共交通為例：較便宜的車費可以鼓勵人們把私家車留在家中。"},{"en":"Take online reviews, for example; one dishonest post can affect many buyers.","zh":"以網上評價為例；一篇不誠實的帖文可以影響很多買家。"},{"en":"This phrase is useful when an argument needs a clear real-life illustration.","zh":"當論點需要一個清楚的現實例子時，這個片語很有用。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"a skincare influencer","meaning":"護膚KOL","examples":[{"en":"A skincare influencer may recommend a serum to her followers.","zh":"護膚KOL可能向追蹤者推薦一款精華液。"},{"en":"A skincare influencer is an online creator who mainly discusses products and routines for caring for the skin.","zh":"護膚KOL是主要在網上討論護膚產品和護理程序的創作者。"},{"en":"A skincare influencer may compare cleansers, creams, or sunscreen in a video.","zh":"護膚KOL可能在影片中比較潔面產品、面霜或防曬用品。"},{"en":"Followers may trust a skincare influencer because they can see the person using products regularly.","zh":"追蹤者可能因為經常看到護膚KOL使用產品而信任對方。"},{"en":"A skincare influencer’s personal experience cannot prove that a product will work for every skin type.","zh":"護膚KOL的個人經驗不能證明某產品適合每一種膚質。"}],"source":"2021 Q5.pdf","sourcePage":6},{"front":"save my skin","meaning":"拯救了我的皮膚","examples":[{"en":"The influencer claims that the serum saved her skin.","zh":"那位KOL聲稱精華液拯救了她的皮膚。"},{"en":"“Save my skin” can mean that a product greatly improved someone’s skin condition.","zh":"「save my skin」在這個語境中可以表示某產品大大改善了某人的皮膚狀況。"},{"en":"Someone may say a moisturiser “saved my skin” after severe dryness improved.","zh":"如果嚴重乾燥得到改善，有人可能會說某款保濕霜「拯救了我的皮膚」。"},{"en":"Strong phrases such as “this saved my skin” can make a product sound unusually effective.","zh":"「這產品拯救了我的皮膚」這類強烈說法會令產品聽起來效果特別好。"},{"en":"A personal claim that something “saved my skin” is not the same as scientific evidence.","zh":"個人聲稱某產品「拯救了我的皮膚」，並不等同科學證據。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"focus on","meaning":"專注於","examples":[{"en":"Followers may focus on her confidence and familiar tone.","zh":"追蹤者可能專注於她的自信和熟悉語氣。"},{"en":"To focus on something means to give most of your attention to it.","zh":"「focus on」表示把大部分注意力放在某件事上。"},{"en":"Students should focus on the question before starting an essay.","zh":"學生開始寫文章前應先專注於題目。"},{"en":"Customers may focus on attractive packaging and forget to compare ingredients.","zh":"顧客可能專注於漂亮包裝，而忘記比較成分。"},{"en":"If viewers focus on an influencer’s personality, they may overlook whether the claim has evidence.","zh":"如果觀眾專注於KOL的個人魅力，可能會忽略聲稱是否有證據支持。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"familiar tone","meaning":"熟悉的語氣","examples":[{"en":"Followers may trust the influencer’s familiar tone.","zh":"追蹤者可能信任KOL熟悉的語氣。"},{"en":"A familiar tone is a style of speaking that feels known, comfortable, and personal to the listener.","zh":"熟悉的語氣是令聽者感到認識、自在和有私人感的說話方式。"},{"en":"A teacher may use a familiar tone to help nervous students relax.","zh":"老師可能使用熟悉的語氣，幫助緊張的學生放鬆。"},{"en":"Influencers develop a familiar tone by speaking to followers regularly in the same style.","zh":"KOL透過長期以相似方式與追蹤者說話，建立熟悉的語氣。"},{"en":"A familiar tone can make advice feel trustworthy even when the facts have not been checked.","zh":"熟悉的語氣可以令建議感覺可信，即使當中的事實未經核實。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"whether she has been paid","meaning":"她是否收了費","examples":[{"en":"Followers may not ask whether she has been paid.","zh":"追蹤者可能沒有問她是否收了費。"},{"en":"“Whether she has been paid” asks if money was given to the person for making or sharing the content.","zh":"「whether she has been paid」是問該人是否因製作或分享內容而收到金錢。"},{"en":"Consumers should ask whether a reviewer has been paid before treating praise as independent.","zh":"消費者把讚賞視為獨立意見前，應先問評測者是否收了費。"},{"en":"If viewers do not know whether she has been paid, they cannot fully judge her motive.","zh":"如果觀眾不知道她是否收了費，就無法完整判斷她的動機。"},{"en":"Clear sponsorship labels answer the question of whether she has been paid.","zh":"清楚的贊助標籤可以回答她是否收了費這個問題。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"suit different skin types","meaning":"適合不同膚質","examples":[{"en":"Followers may not know whether the product suits different skin types.","zh":"追蹤者可能不知道產品是否適合不同膚質。"},{"en":"To suit different skin types means to be appropriate and safe for people whose skin has different characteristics.","zh":"適合不同膚質是指產品對具有不同皮膚特徵的人都合適而且安全。"},{"en":"A heavy cream may suit dry skin but not suit very oily skin.","zh":"厚重的面霜可能適合乾性皮膚，但不適合非常油性的皮膚。"},{"en":"Products that suit different skin types usually need testing on a range of users.","zh":"聲稱適合不同膚質的產品通常需要在不同使用者身上進行測試。"},{"en":"One influencer’s good result cannot show whether a product suits different skin types.","zh":"一位KOL的良好效果不能證明產品是否適合不同膚質。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"be supported by evidence","meaning":"得到證據支持","examples":[{"en":"Followers may not know whether the claim is supported by evidence.","zh":"追蹤者可能不知道該聲稱是否得到證據支持。"},{"en":"To be supported by evidence means that reliable facts or research provide reasons to believe a claim.","zh":"得到證據支持表示有可靠事實或研究提供相信某項聲稱的理由。"},{"en":"A health statement should be supported by evidence from properly designed studies.","zh":"健康聲稱應得到設計妥善的研究證據支持。"},{"en":"A school’s decision is easier to defend when it is supported by evidence.","zh":"學校的決定如果得到證據支持，會更容易為其辯護。"},{"en":"A confident statement should not be accepted simply because it sounds convincing; it should be supported by evidence.","zh":"一項自信的說法不應只因聽起來有說服力而被接受；它應得到證據支持。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"the more…, the easier…","meaning":"越……就越容易……","examples":[{"en":"The more personal the delivery is, the easier it becomes for advertising to borrow the language of friendship.","zh":"表達方式越個人化，廣告就越容易借用友誼的語言。"},{"en":"“The more…, the easier…” shows that as one condition increases, another result becomes easier.","zh":"「the more…, the easier…」表示一個條件增加時，另一個結果會變得更容易。"},{"en":"The more clearly a teacher explains, the easier the lesson is to understand.","zh":"老師解釋得越清楚，課堂內容就越容易理解。"},{"en":"The more familiar an influencer feels, the easier it may be for viewers to trust them.","zh":"KOL感覺越熟悉，觀眾就可能越容易信任對方。"},{"en":"This pattern is useful for describing a relationship between two changing conditions.","zh":"這個句式適合描述兩個會改變的條件之間的關係。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"personal delivery","meaning":"個人化的表達方式","examples":[{"en":"Personal delivery can make advertising sound like advice from a friend.","zh":"個人化的表達方式可以令廣告聽起來像朋友的建議。"},{"en":"Personal delivery means presenting a message in an individual, intimate, or conversational way.","zh":"個人化的表達方式是指以個人、親密或對話式的方法傳達訊息。"},{"en":"A speaker using someone’s name creates a more personal delivery.","zh":"講者稱呼對方名字，可以令表達方式更個人化。"},{"en":"Influencers use personal delivery by sharing stories about their own lives.","zh":"KOL透過分享自己的生活故事來使用個人化的表達方式。"},{"en":"Personal delivery can make promotion emotionally powerful without making its claims more reliable.","zh":"個人化的表達方式可以令推廣更有情感力量，但不會令聲稱本身更可靠。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"borrow the language of friendship","meaning":"借用友誼的語言","examples":[{"en":"Advertising can borrow the language of friendship.","zh":"廣告可以借用友誼的語言。"},{"en":"To borrow the language of friendship means to use warm, personal expressions that normally belong to friendly relationships.","zh":"借用友誼的語言是指使用通常屬於朋友關係的溫暖和私人表達。"},{"en":"An advert may say “I genuinely want to help you” to borrow the language of friendship.","zh":"廣告可能說「我真心想幫你」，藉此借用友誼的語言。"},{"en":"Influencers borrow the language of friendship when they call followers “family” while promoting products.","zh":"KOL在推廣產品時稱追蹤者為「家人」，就是在借用友誼的語言。"},{"en":"Advertising that borrows the language of friendship may hide how commercial the relationship really is.","zh":"借用友誼語言的廣告可能掩蓋這段關係實際上有多商業化。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"not necessarily trustworthy","meaning":"不一定值得信任","examples":[{"en":"Influencers may be powerful, but not necessarily trustworthy.","zh":"KOL可能很有影響力，但不一定值得信任。"},{"en":"“Not necessarily trustworthy” means something may seem convincing without always being reliable or honest.","zh":"「not necessarily trustworthy」表示某事物可能很有說服力，但不一定可靠或誠實。"},{"en":"A popular website is not necessarily trustworthy just because many people visit it.","zh":"一個受歡迎的網站不會只因很多人瀏覽就一定值得信任。"},{"en":"A confident speaker is not necessarily trustworthy if no evidence supports the claim.","zh":"如果沒有證據支持聲稱，一個自信的講者也不一定值得信任。"},{"en":"Being familiar, entertaining, or successful does not make someone necessarily trustworthy.","zh":"熟悉、有娛樂性或成功，都不會令一個人必然值得信任。"}],"source":"2021 Q5.pdf","sourcePage":7},{"front":"be held to the same standard","meaning":"被要求達到同一標準","examples":[{"en":"Influencers are not always held to the same standard of expertise or accountability.","zh":"KOL並不總是被要求達到相同的專業知識或問責標準。"},{"en":"To be held to the same standard means to be judged according to equally strict expectations or rules.","zh":"被要求達到同一標準是指按照同樣嚴格的期望或規則接受評價。"},{"en":"All students should be held to the same standard when the same examination is marked.","zh":"批改同一份考試時，所有學生都應被要求達到同一標準。"},{"en":"Online promoters should be held to the same standard of honesty as other advertisers.","zh":"網上推廣者應在誠實方面被要求達到與其他廣告商相同的標準。"},{"en":"If two people make similar claims, it is fair to hold them to the same standard of evidence.","zh":"如果兩個人提出相似聲稱，要求他們達到相同證據標準是公平的。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"expertise","meaning":"專業知識","examples":[{"en":"Influencers are not always held to the same standard of expertise.","zh":"KOL並不總是被要求達到相同的專業知識標準。"},{"en":"Expertise means a high level of knowledge or skill developed through study, training, or experience.","zh":"專業知識是透過學習、訓練或經驗建立的高水平知識或技能。"},{"en":"A qualified engineer has expertise in areas that ordinary customers may not understand.","zh":"合資格工程師在一般顧客未必了解的領域具備專業知識。"},{"en":"Someone can be popular online without having expertise in health, finance, or science.","zh":"一個人可以在網上很受歡迎，卻沒有健康、財經或科學方面的專業知識。"},{"en":"When advice involves serious risks, expertise matters more than confidence or appearance.","zh":"當建議涉及嚴重風險時，專業知識比自信或外表更重要。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"not to say that","meaning":"這並不是說","examples":[{"en":"This is not to say that traditional advertisements are perfectly honest.","zh":"這並不是說傳統廣告是完全誠實的。"},{"en":"“This is not to say that” prevents readers from wrongly thinking the writer is making a stronger claim.","zh":"「this is not to say that」用來避免讀者誤以為作者提出了一個更強烈的主張。"},{"en":"Exercise is important; this is not to say that everyone needs to train like an athlete.","zh":"運動很重要；這並不是說每個人都需要像運動員一樣訓練。"},{"en":"Influencer marketing has weaknesses, but this is not to say that every influencer is dishonest.","zh":"KOL市場推廣有弱點，但這並不是說每一位KOL都不誠實。"},{"en":"This phrase helps make an argument more balanced by recognising an important limitation.","zh":"這個片語透過承認重要限制，令論點更平衡。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"perfectly honest","meaning":"完全誠實","examples":[{"en":"Traditional advertisements are not perfectly honest.","zh":"傳統廣告並不是完全誠實的。"},{"en":"“Perfectly honest” means completely truthful, without hiding, exaggerating, or misleading anything.","zh":"「perfectly honest」表示完全說真話，不隱瞞、不誇大，也不誤導。"},{"en":"A person may be generally truthful without being perfectly honest about every mistake.","zh":"一個人可以一般而言很誠實，但未必對每個錯誤都完全坦白。"},{"en":"Advertisements are rarely perfectly honest because they usually highlight strengths rather than weaknesses.","zh":"廣告很少完全誠實，因為它們通常突出優點，而不是缺點。"},{"en":"Expecting perfect honesty may be unrealistic, but deliberate deception is still unacceptable.","zh":"要求百分百完全誠實可能不現實，但故意欺騙仍然不能接受。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"far from it","meaning":"絕非如此","examples":[{"en":"Traditional advertisements are not perfectly honest; far from it.","zh":"傳統廣告並非完全誠實；絕非如此。"},{"en":"“Far from it” strongly means that the opposite of the previous idea is closer to the truth.","zh":"「far from it」強烈表示實際情況與剛才提到的想法相反。"},{"en":"The exam was not easy; far from it, many students could not finish.","zh":"那次考試並不容易；絕非如此，很多學生甚至未能完成。"},{"en":"The product is not harmless; far from it, incorrect use can cause serious problems.","zh":"這產品並非無害；絕非如此，錯誤使用可以造成嚴重問題。"},{"en":"This expression strengthens a correction when the reality is very different from what was suggested.","zh":"當實際情況與先前說法非常不同時，這個表達可用來加強更正。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"exaggerate reality","meaning":"誇大現實","examples":[{"en":"Traditional advertisements often exaggerate reality.","zh":"傳統廣告經常誇大現實。"},{"en":"To exaggerate reality means to make something seem better, worse, bigger, or more dramatic than it truly is.","zh":"誇大現實是指令某件事看起來比實際更好、更差、更大或更戲劇化。"},{"en":"A beauty advert may exaggerate reality by suggesting one cream will completely change someone’s appearance.","zh":"美容廣告如果暗示一款面霜能徹底改變外貌，就是在誇大現實。"},{"en":"Social media posts can exaggerate reality when creators show only perfect moments.","zh":"當創作者只展示完美時刻，社交媒體帖文也可能誇大現實。"},{"en":"Exaggerating reality can persuade people, but it can also create unrealistic expectations.","zh":"誇大現實可以說服人，但也可能製造不切實際的期望。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"simplify reality","meaning":"簡化現實","examples":[{"en":"Advertisements often simplify reality.","zh":"廣告經常簡化現實。"},{"en":"To simplify reality means to present a complicated situation as if it were much easier or more straightforward than it really is.","zh":"簡化現實是指把複雜情況描述得比實際容易或直接得多。"},{"en":"A weight-loss advert may simplify reality by suggesting one product solves a complex health problem.","zh":"減肥廣告如果暗示一款產品便能解決複雜健康問題，就是在簡化現實。"},{"en":"News headlines sometimes simplify reality because they cannot explain every detail.","zh":"新聞標題有時會簡化現實，因為不可能交代所有細節。"},{"en":"Simplifying reality can make a message easy to understand, but important information may be lost.","zh":"簡化現實可以令訊息容易理解，但也可能失去重要資訊。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"beautify reality","meaning":"美化現實","examples":[{"en":"Advertisements often beautify reality.","zh":"廣告經常美化現實。"},{"en":"To beautify reality means to present something in a more attractive and pleasant way than it normally appears.","zh":"美化現實是指把某件事呈現得比平常實際情況更吸引和更美好。"},{"en":"A travel brochure may beautify reality by showing empty beaches but not crowded roads.","zh":"旅遊小冊子只展示空曠沙灘而不展示擠塞道路，就是在美化現實。"},{"en":"Food photography can beautify reality through lighting and careful arrangement.","zh":"食物攝影可以透過燈光和仔細擺放來美化現實。"},{"en":"Beautifying reality may attract customers, but it can also hide practical disadvantages.","zh":"美化現實可以吸引顧客，但也可能隱藏實際缺點。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"traditional media campaigns","meaning":"傳統媒體宣傳活動","examples":[{"en":"Traditional media campaigns usually involve companies, agencies, and public scrutiny.","zh":"傳統媒體宣傳活動通常涉及公司、廣告代理和公眾監察。"},{"en":"Traditional media campaigns are organised advertising efforts using channels such as television, radio, newspapers, and magazines.","zh":"傳統媒體宣傳活動是利用電視、電台、報紙和雜誌等渠道進行的有組織廣告活動。"},{"en":"A national supermarket may run traditional media campaigns before a major festival.","zh":"全國性超級市場可能在大型節日前進行傳統媒體宣傳活動。"},{"en":"Traditional media campaigns often involve professional designers, legal checks, and large budgets.","zh":"傳統媒體宣傳活動通常涉及專業設計、法律審查和大型預算。"},{"en":"Because they are highly visible, traditional media campaigns may face strong public criticism when claims are misleading.","zh":"因為曝光度高，傳統媒體宣傳活動提出誤導性聲稱時可能受到強烈公眾批評。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"public scrutiny","meaning":"公眾監察","examples":[{"en":"Traditional media campaigns usually face public scrutiny.","zh":"傳統媒體宣傳活動通常要面對公眾監察。"},{"en":"Public scrutiny means close examination and criticism by ordinary people, journalists, experts, or organisations.","zh":"公眾監察是指普通市民、記者、專家或機構對某件事作仔細檢視和批評。"},{"en":"Government spending often faces public scrutiny because taxpayers want to know how money is used.","zh":"政府開支常面對公眾監察，因為納稅人想知道金錢如何使用。"},{"en":"A misleading advertisement may face public scrutiny after consumers complain.","zh":"消費者投訴後，誤導性廣告可能面對公眾監察。"},{"en":"Public scrutiny can create accountability by forcing organisations to explain their decisions.","zh":"公眾監察可以迫使機構解釋決定，從而建立問責性。"}],"source":"2021 Q5.pdf","sourcePage":8},{"front":"make a false claim","meaning":"作出虛假聲稱","examples":[{"en":"A television commercial may make a false claim.","zh":"電視廣告可能作出虛假聲稱。"},{"en":"To make a false claim means to state something as true when it is actually untrue or unsupported.","zh":"作出虛假聲稱是指把實際不真實或沒有證據支持的事情說成真的。"},{"en":"A company makes a false claim if it says a product cures an illness when it does not.","zh":"如果公司聲稱某產品能治療疾病，但實際不能，就是作出虛假聲稱。"},{"en":"A student should not make a false claim about research they have never read.","zh":"學生不應對自己從未閱讀的研究作出虛假聲稱。"},{"en":"Making a false claim can damage trust and may lead to complaints or penalties.","zh":"作出虛假聲稱會破壞信任，也可能引起投訴或處罰。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"be challenged","meaning":"受到質疑","examples":[{"en":"A brand can be challenged if it makes a false claim.","zh":"如果品牌作出虛假聲稱，可能會受到質疑。"},{"en":"To be challenged means to have a statement, decision, or action questioned and asked to be justified.","zh":"「be challenged」表示某項說法、決定或行為被人質疑，並被要求提出理據。"},{"en":"A scientific result may be challenged if other researchers cannot repeat it.","zh":"如果其他研究人員無法重複結果，一項科學研究可能受到質疑。"},{"en":"An advertiser can be challenged by consumers who believe a claim is misleading.","zh":"如果消費者認為聲稱具誤導性，廣告商可能受到質疑。"},{"en":"Being challenged creates pressure to provide evidence rather than relying on confidence alone.","zh":"受到質疑會產生壓力，令人需要提供證據，而不是只靠自信。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"be criticised","meaning":"受到批評","examples":[{"en":"A brand can be criticised for making a false claim.","zh":"品牌可能因作出虛假聲稱而受到批評。"},{"en":"To be criticised means to receive negative judgement because people think something is wrong, unfair, or poor.","zh":"「be criticised」表示因為別人認為某事錯誤、不公平或做得差而受到負面評價。"},{"en":"A school may be criticised if it ignores serious bullying complaints.","zh":"學校如果忽視嚴重欺凌投訴，可能受到批評。"},{"en":"Influencers can be criticised for promoting unsafe products without checking them.","zh":"KOL如果沒有查證便推廣不安全產品，可能受到批評。"},{"en":"Public figures are often criticised more strongly when their actions affect many people.","zh":"當公眾人物的行為影響很多人時，往往會受到更強烈批評。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"be remembered for it","meaning":"因此被記住","examples":[{"en":"A brand may be remembered for making a false claim.","zh":"品牌可能因作出虛假聲稱而被人記住。"},{"en":"To be remembered for something means people continue to associate you with that action or event later.","zh":"因某事被記住是指人們日後仍把你與某項行為或事件聯繫起來。"},{"en":"A company may be remembered for excellent customer service long after a purchase.","zh":"公司可能在購買多年後仍因優秀顧客服務而被記住。"},{"en":"A politician who breaks an important promise may be remembered for it for years.","zh":"政治人物如果違反重要承諾，可能多年後仍因此被記住。"},{"en":"Serious advertising mistakes can damage reputation because a brand may be remembered for them.","zh":"嚴重廣告錯誤會損害聲譽，因為品牌可能長期因此被人記住。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"move on tomorrow","meaning":"明天就轉到下一件事","examples":[{"en":"An influencer may promote a product today and move on tomorrow.","zh":"KOL今天可能推廣一件產品，明天就轉到下一件事。"},{"en":"To move on tomorrow means to leave the current subject behind quickly and focus on something different the next day.","zh":"「move on tomorrow」表示很快把目前話題放下，第二天專注於另一件事。"},{"en":"A creator may discuss one brand today and move on tomorrow to another sponsor.","zh":"創作者今天可能談一個品牌，明天就轉到另一個贊助商。"},{"en":"Consumers cannot always get help if a promoter simply moves on tomorrow.","zh":"如果推廣者明天就轉到下一件事，消費者未必能得到協助。"},{"en":"The phrase suggests that the promotion may be temporary even though customers deal with the consequences later.","zh":"這個片語表示推廣可能很短暫，但顧客之後仍要承受結果。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"disappointed consumers","meaning":"感到失望的消費者","examples":[{"en":"An influencer may leave disappointed consumers with little support.","zh":"KOL可能令感到失望的消費者得不到太多支援。"},{"en":"Disappointed consumers are customers whose expectations were not met by a product, service, or seller.","zh":"感到失望的消費者是指產品、服務或賣方未能符合其期望的顧客。"},{"en":"Disappointed consumers may complain when an expensive product performs poorly.","zh":"昂貴產品表現欠佳時，感到失望的消費者可能會投訴。"},{"en":"Hidden sponsorship can create disappointed consumers who feel they were misled.","zh":"隱藏贊助可能令消費者覺得受騙，因而感到失望。"},{"en":"Companies should respond to disappointed consumers instead of deleting criticism.","zh":"公司應回應感到失望的消費者，而不是刪除批評。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"little more than","meaning":"只剩下；不過是","examples":[{"en":"Consumers may be left with little more than a deleted post or a vague apology.","zh":"消費者可能只剩下一篇已刪除的帖文或一個含糊的道歉。"},{"en":"“Little more than” means almost nothing beyond the thing mentioned.","zh":"「little more than」表示除了所提到的東西外，幾乎甚麼都沒有。"},{"en":"After the event failed, customers received little more than a short email.","zh":"活動失敗後，顧客只收到一封很短的電郵。"},{"en":"A promise without action may be little more than empty words.","zh":"沒有行動的承諾可能不過是空話。"},{"en":"If harmed consumers receive little more than an apology, they may feel there is no real accountability.","zh":"如果受損消費者只得到道歉，他們可能覺得完全沒有真正問責。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"a deleted post","meaning":"一篇已刪除的帖文","examples":[{"en":"Consumers may be left with a deleted post.","zh":"消費者可能只剩下一篇已刪除的帖文。"},{"en":"A deleted post is online content that has been removed by the person or account that published it.","zh":"已刪除的帖文是由原本發布它的人或帳戶從網上移除的內容。"},{"en":"A creator may remove a misleading advertisement, leaving only a deleted post where evidence once existed.","zh":"創作者可能刪除誤導性廣告，只留下原本有證據的位置變成一篇已刪除的帖文。"},{"en":"Screenshots can remain online even after a deleted post disappears from the original account.","zh":"即使已刪除的帖文從原帳戶消失，截圖仍可能留在網上。"},{"en":"Deleting a post does not automatically solve problems caused by the information it contained.","zh":"刪除帖文並不會自動解決該內容曾經造成的問題。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"a vague apology","meaning":"含糊的道歉","examples":[{"en":"Consumers may receive only a vague apology.","zh":"消費者可能只收到一個含糊的道歉。"},{"en":"A vague apology is an apology that avoids clearly explaining what went wrong or accepting responsibility.","zh":"含糊的道歉是指沒有清楚解釋出錯原因或承擔責任的道歉。"},{"en":"Saying “sorry if anyone was upset” can sound like a vague apology.","zh":"說「如果有人不高興，我們很抱歉」可能聽起來像含糊的道歉。"},{"en":"Customers may become angrier when a company gives a vague apology instead of a clear solution.","zh":"公司如果只給含糊的道歉而沒有清楚解決方法，顧客可能更加生氣。"},{"en":"A meaningful apology should explain the mistake, accept responsibility, and describe what will change.","zh":"有意義的道歉應解釋錯誤、承擔責任，並說明之後會如何改變。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"popularity is not the same as competence","meaning":"受歡迎並不等於有能力","examples":[{"en":"Popularity is not the same as competence.","zh":"受歡迎並不等於有能力。"},{"en":"This sentence means being liked or followed by many people does not prove that someone has the ability to do something well.","zh":"這句話表示受到很多人喜歡或追蹤，並不能證明某人有能力把事情做好。"},{"en":"A popular student may not be the most competent person to organise a difficult project.","zh":"一個受歡迎的學生未必是最有能力組織困難項目的人。"},{"en":"An influencer can have millions of followers without professional knowledge in the subject discussed.","zh":"KOL可以有數百萬追蹤者，卻沒有自己所談領域的專業知識。"},{"en":"When choosing advice, people should separate popularity from actual competence.","zh":"選擇建議時，人們應把受歡迎程度與真正能力分開。"}],"source":"2021 Q5.pdf","sourcePage":9},{"front":"competence","meaning":"能力；勝任能力","examples":[{"en":"Popularity is not the same as competence.","zh":"受歡迎並不等於有能力。"},{"en":"Competence means having enough skill, knowledge, and ability to do a task properly.","zh":"能力是指具有足夠技能、知識和本領，能把工作妥善完成。"},{"en":"A competent electrician knows how to complete repairs safely.","zh":"有勝任能力的電工知道如何安全完成維修。"},{"en":"Professional training can improve competence in difficult or technical work.","zh":"專業訓練可以提高人在困難或技術工作上的能力。"},{"en":"Confidence may create a good impression, but competence is shown through reliable performance.","zh":"自信可以令人留下好印象，但真正能力要靠可靠表現證明。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"a fitness influencer","meaning":"健身KOL","examples":[{"en":"A fitness influencer may look healthy without understanding nutrition.","zh":"健身KOL可能看起來健康，卻不了解營養學。"},{"en":"A fitness influencer is an online creator who shares exercise, training, body, or health-related content.","zh":"健身KOL是分享運動、訓練、身體或健康相關內容的網上創作者。"},{"en":"A fitness influencer may demonstrate workouts or review sports equipment.","zh":"健身KOL可能示範訓練動作或評測運動用品。"},{"en":"Followers may copy a fitness influencer because the person appears strong and disciplined.","zh":"追蹤者可能因為健身KOL看起來強壯和自律而模仿對方。"},{"en":"Looking fit does not prove that a fitness influencer is qualified to give medical or nutritional advice.","zh":"看起來健美並不能證明健身KOL有資格提供醫療或營養建議。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"look healthy","meaning":"看起來健康","examples":[{"en":"A fitness influencer may look healthy without having professional knowledge.","zh":"健身KOL可能看起來健康，卻沒有專業知識。"},{"en":"To look healthy means to appear physically well, energetic, or fit.","zh":"看起來健康是指外表顯得身體良好、有精神或健美。"},{"en":"Someone can look healthy in photographs while still having health problems that cannot be seen.","zh":"一個人在照片中可以看起來健康，同時仍有看不見的健康問題。"},{"en":"Good lighting and editing can make people look healthy online.","zh":"良好燈光和修圖可以令人在網上看起來健康。"},{"en":"Looking healthy is not evidence that someone understands medicine, exercise science, or nutrition.","zh":"看起來健康並不是懂醫學、運動科學或營養學的證據。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"understand nutrition","meaning":"了解營養學","examples":[{"en":"A fitness influencer may not fully understand nutrition.","zh":"健身KOL可能未必完全了解營養學。"},{"en":"To understand nutrition means to know how food, nutrients, and eating patterns affect the body and health.","zh":"了解營養學是指知道食物、營養素和飲食模式如何影響身體與健康。"},{"en":"Dietitians study for years to understand nutrition in a professional way.","zh":"營養師需要多年學習，才能專業地了解營養學。"},{"en":"Someone who understands nutrition knows that different people may have different dietary needs.","zh":"了解營養學的人知道不同人士可能有不同飲食需要。"},{"en":"Personal eating habits alone do not prove that a person fully understands nutrition.","zh":"單靠個人飲食習慣，不能證明一個人完全了解營養學。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"a lifestyle vlogger","meaning":"生活影片網誌創作者","examples":[{"en":"A lifestyle vlogger may recommend an expensive gadget after using it briefly.","zh":"生活影片網誌創作者可能只使用昂貴電子產品很短時間便作出推薦。"},{"en":"A lifestyle vlogger is a video creator who shares parts of everyday life such as shopping, travel, home, food, or routines.","zh":"生活影片網誌創作者是分享購物、旅遊、家居、食物或日常生活等內容的影片創作者。"},{"en":"A lifestyle vlogger may film a weekly diary about work, meals, and new purchases.","zh":"生活影片網誌創作者可能拍攝一星期的工作、飲食和購物日記。"},{"en":"Brands often work with lifestyle vloggers because products can appear naturally in daily-life content.","zh":"品牌常與生活影片網誌創作者合作，因為產品可以自然地出現在日常內容中。"},{"en":"Viewers should remember that a lifestyle vlogger’s experience may be short and highly personal.","zh":"觀眾應記住，生活影片網誌創作者的使用經驗可能很短，而且高度個人化。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"recommend an expensive gadget","meaning":"推薦昂貴電子產品","examples":[{"en":"A lifestyle vlogger may recommend an expensive gadget after using it for only two days.","zh":"生活影片網誌創作者可能只使用兩天便推薦昂貴電子產品。"},{"en":"To recommend an expensive gadget means to advise others to buy a costly electronic device or piece of technology.","zh":"推薦昂貴電子產品是指建議別人購買價格高昂的電子裝置或科技產品。"},{"en":"A reviewer should test a product carefully before recommending an expensive gadget.","zh":"評測者在推薦昂貴電子產品前應仔細測試。"},{"en":"Someone may regret following an influencer who recommends an expensive gadget without discussing its problems.","zh":"如果KOL推薦昂貴電子產品時沒有談到問題，追隨建議的人可能會後悔。"},{"en":"The higher the price, the more evidence consumers may want before accepting a recommendation.","zh":"產品價格越高，消費者在接受推薦前通常越希望看到更多證據。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"a finance influencer","meaning":"財經KOL","examples":[{"en":"A finance influencer may speak confidently about investment while lacking professional training.","zh":"財經KOL可能自信地談論投資，同時缺乏專業訓練。"},{"en":"A finance influencer is an online creator who discusses topics such as saving, investing, debt, markets, or personal money management.","zh":"財經KOL是在網上討論儲蓄、投資、債務、市場或個人理財等主題的創作者。"},{"en":"A finance influencer may explain basic budgeting in short videos.","zh":"財經KOL可能用短片解釋基本預算管理。"},{"en":"Followers can lose money if they treat every finance influencer as a qualified adviser.","zh":"如果追蹤者把每位財經KOL都當作合資格顧問，可能會蒙受金錢損失。"},{"en":"Financial confidence online should be separated from professional knowledge and responsibility.","zh":"網上的財經自信應與專業知識和責任分開判斷。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"speak confidently about","meaning":"自信地談論","examples":[{"en":"A finance influencer may speak confidently about investment.","zh":"財經KOL可能自信地談論投資。"},{"en":"To speak confidently about something means to discuss it in a certain and self-assured way.","zh":"自信地談論某事是指以肯定和有把握的方式談論它。"},{"en":"A student may speak confidently about a topic after preparing carefully.","zh":"學生仔細準備後，可能會自信地談論某個題目。"},{"en":"Someone can speak confidently about medicine while still being wrong.","zh":"一個人可以自信地談論醫學，同時仍然說錯。"},{"en":"Speaking confidently about a subject can sound impressive, but it does not prove expertise.","zh":"自信地談論某個主題可以令人留下深刻印象，但不能證明專業知識。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"lack professional training","meaning":"缺乏專業訓練","examples":[{"en":"A finance influencer may lack professional training.","zh":"財經KOL可能缺乏專業訓練。"},{"en":"To lack professional training means not having received formal education or preparation required for a specialist role.","zh":"缺乏專業訓練是指沒有接受某項專門工作所需要的正式教育或準備。"},{"en":"Someone may enjoy repairing electronics but still lack professional training as an engineer.","zh":"有人可能喜歡維修電子產品，但仍缺乏工程師的專業訓練。"},{"en":"People who lack professional training should be careful when giving high-risk advice.","zh":"缺乏專業訓練的人在提供高風險建議時應格外小心。"},{"en":"Lacking professional training does not make every opinion useless, but it limits what expertise can reasonably be claimed.","zh":"缺乏專業訓練不代表所有意見都沒有價值，但會限制一個人能合理聲稱的專業程度。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"charisma replaces expertise","meaning":"個人魅力取代專業知識","examples":[{"en":"Followers face risks when charisma replaces expertise.","zh":"當個人魅力取代專業知識，追蹤者便會面對風險。"},{"en":"“Charisma replaces expertise” means personal charm begins to matter more than real knowledge or skill.","zh":"「charisma replaces expertise」表示個人魅力開始比真正知識或技能更受重視。"},{"en":"A confident presenter may win attention when charisma replaces expertise in a discussion.","zh":"在討論中，如果個人魅力取代專業知識，自信的講者可能更容易吸引注意。"},{"en":"In health or finance, serious mistakes can happen if charisma replaces expertise.","zh":"在健康或財經領域，如果個人魅力取代專業知識，可能出現嚴重錯誤。"},{"en":"Charisma can help someone communicate, but it should support expertise rather than replace it.","zh":"個人魅力可以幫助溝通，但應配合專業知識，而不是取代它。"}],"source":"2021 Q5.pdf","sourcePage":10},{"front":"mistake confidence for credibility","meaning":"把自信誤當成可信度","examples":[{"en":"Followers risk mistaking confidence for credibility.","zh":"追蹤者有把自信誤當成可信度的風險。"},{"en":"To mistake confidence for credibility means to wrongly assume that someone is reliable simply because they speak with certainty.","zh":"把自信誤當成可信度是指只因某人說話肯定，就錯誤認為對方可靠。"},{"en":"Students may mistake confidence for credibility when a classmate gives an answer loudly but without evidence.","zh":"同學大聲回答卻沒有證據時，學生可能把自信誤當成可信度。"},{"en":"Online audiences can mistake confidence for credibility when creators never show uncertainty.","zh":"當創作者從不表現不確定，網上觀眾可能把自信誤當成可信度。"},{"en":"Checking qualifications and evidence helps people avoid mistaking confidence for credibility.","zh":"查看資格和證據可以幫助人避免把自信誤當成可信度。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"credibility","meaning":"可信度","examples":[{"en":"Confidence is not the same as credibility.","zh":"自信與可信度並不相同。"},{"en":"Credibility is the quality of being believable, reliable, and worthy of trust.","zh":"可信度是指令人相信、可靠並值得信任的程度。"},{"en":"A journalist builds credibility by checking facts and correcting mistakes.","zh":"記者透過核實事實和改正錯誤建立可信度。"},{"en":"A doctor’s credibility comes partly from training, evidence, and professional responsibility.","zh":"醫生的可信度部分來自訓練、證據和專業責任。"},{"en":"Credibility takes time to build and can be damaged quickly by dishonest claims.","zh":"可信度需要時間建立，卻可以因不誠實聲稱迅速受損。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"built on personality alone","meaning":"單靠個人魅力建立","examples":[{"en":"Trust built on personality alone is a fragile foundation.","zh":"單靠個人魅力建立的信任是一個脆弱的基礎。"},{"en":"“Built on personality alone” means based only on someone’s character, charm, or public image rather than evidence or ability.","zh":"「built on personality alone」表示只建基於某人的性格、魅力或公眾形象，而不是證據或能力。"},{"en":"A friendship built on personality alone may struggle if the people do not share values.","zh":"如果兩個人沒有共同價值，單靠個性建立的友誼可能難以維持。"},{"en":"Financial trust built on personality alone is risky when large sums of money are involved.","zh":"涉及大量金錢時，單靠個人魅力建立的財務信任風險很高。"},{"en":"Good judgement should include evidence and accountability rather than being built on personality alone.","zh":"良好判斷應包括證據和問責，而不是單靠個人魅力建立。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"a fragile foundation","meaning":"脆弱的基礎","examples":[{"en":"Trust built on personality alone is a fragile foundation.","zh":"單靠個人魅力建立的信任是一個脆弱的基礎。"},{"en":"A fragile foundation is a weak basis that may fail when pressure or problems appear.","zh":"脆弱的基礎是指在壓力或問題出現時可能失敗的薄弱基礎。"},{"en":"A friendship based only on convenience can be a fragile foundation for long-term trust.","zh":"只建基於方便的友誼，可能是長期信任的脆弱基礎。"},{"en":"A business depending on one customer has a fragile foundation for future income.","zh":"只依賴一位顧客的企業，其未來收入有一個脆弱的基礎。"},{"en":"Trust without evidence or accountability is a fragile foundation because one serious mistake can destroy it.","zh":"沒有證據或問責的信任是一個脆弱的基礎，因為一次嚴重錯誤就可能摧毀它。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, supporters of influencers have a reasonable point.","zh":"誠然，KOL支持者的看法有合理之處。"},{"en":"“Granted” introduces a point the speaker accepts before presenting a different or opposing argument.","zh":"「granted」用來先承認一個觀點，再提出不同或相反的論點。"},{"en":"Granted, online learning is convenient, but some students still need face-to-face support.","zh":"誠然，網上學習很方便，但有些學生仍需要面對面支援。"},{"en":"Granted, influencers can demonstrate products clearly, but demonstrations do not guarantee honesty.","zh":"誠然，KOL可以清楚示範產品，但示範並不保證誠實。"},{"en":"Using “granted” makes an argument more balanced by acknowledging the other side.","zh":"使用「granted」可以承認另一方的觀點，令論證更平衡。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"supporters of influencers","meaning":"KOL支持者","examples":[{"en":"Supporters of influencers argue that they can demonstrate products clearly.","zh":"KOL支持者認為他們可以清楚示範產品。"},{"en":"Supporters of influencers are people who believe online creators have important advantages as sources of recommendations.","zh":"KOL支持者是認為網上創作者作為推薦來源具有重要優勢的人。"},{"en":"Supporters of influencers may say videos show products more realistically than posters do.","zh":"KOL支持者可能會說影片比海報更真實地展示產品。"},{"en":"Some supporters of influencers value the direct interaction between creators and followers.","zh":"有些KOL支持者重視創作者與追蹤者之間的直接互動。"},{"en":"Their arguments should be considered, but they do not prove that every influencer is trustworthy.","zh":"他們的論點值得考慮，但不能證明每一位KOL都值得信任。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"have a reasonable point","meaning":"有合理之處","examples":[{"en":"Supporters of influencers have a reasonable point.","zh":"KOL支持者的看法有合理之處。"},{"en":"To have a reasonable point means to make an argument that is sensible and deserves consideration.","zh":"「have a reasonable point」表示提出一個合理而值得考慮的論點。"},{"en":"Students who ask for more practice time have a reasonable point if the task is difficult.","zh":"如果任務很困難，要求更多練習時間的學生是有合理之處的。"},{"en":"Critics of hidden advertising have a reasonable point because consumers should know when money is involved.","zh":"批評隱藏式廣告的人有合理之處，因為消費者應知道何時涉及金錢。"},{"en":"Someone can have a reasonable point without being completely correct about the whole issue.","zh":"一個人的觀點可以有合理之處，但不代表他對整個問題完全正確。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"demonstrate products","meaning":"示範產品","examples":[{"en":"Influencers can demonstrate products in real-life situations.","zh":"KOL可以在真實生活情境中示範產品。"},{"en":"To demonstrate products means to show how products look, work, or are used.","zh":"示範產品是指展示產品的外觀、功能或使用方法。"},{"en":"A salesperson may demonstrate products by turning them on and explaining each feature.","zh":"售貨員可以開啟產品並解釋每項功能來示範產品。"},{"en":"Video creators can demonstrate products more clearly than a still photograph can.","zh":"影片創作者通常比靜態照片更能清楚示範產品。"},{"en":"Demonstrating a product helps consumers understand usage, but it does not prove every claim about quality.","zh":"示範產品有助消費者了解使用方法，但不能證明所有品質聲稱。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"real-life situations","meaning":"真實生活情境","examples":[{"en":"Influencers can demonstrate products in real-life situations.","zh":"KOL可以在真實生活情境中示範產品。"},{"en":"Real-life situations are ordinary events and conditions that people actually experience outside artificial tests or advertisements.","zh":"真實生活情境是人們在人工測試或廣告以外真正會經歷的日常事件和條件。"},{"en":"A raincoat is better tested in real-life situations such as walking through heavy rain.","zh":"雨衣最好在大雨中步行等真實生活情境下測試。"},{"en":"Students understand communication skills better when they practise them in real-life situations.","zh":"學生在真實生活情境中練習時，會更理解溝通技巧。"},{"en":"Showing a product in real-life situations can reveal practical details that studio photographs hide.","zh":"在真實生活情境中展示產品，可以揭示攝影棚照片看不到的實際細節。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"a makeup tutorial","meaning":"化妝教學","examples":[{"en":"A makeup tutorial may show texture better than a magazine advert.","zh":"化妝教學可能比雜誌廣告更能展示質感。"},{"en":"A makeup tutorial is a lesson, usually in video form, showing how to apply cosmetic products.","zh":"化妝教學通常是以影片形式示範如何使用化妝品的教學內容。"},{"en":"A makeup tutorial may explain how to use foundation, eye shadow, and lipstick step by step.","zh":"化妝教學可能逐步解釋如何使用粉底、眼影和唇膏。"},{"en":"Viewers can see how a product behaves on skin during a makeup tutorial.","zh":"觀眾可以在化妝教學中看到產品在皮膚上的實際表現。"},{"en":"A sponsored makeup tutorial can still be useful, but the sponsorship should be clearly disclosed.","zh":"受贊助的化妝教學仍可能有用，但應清楚披露贊助關係。"}],"source":"2021 Q5.pdf","sourcePage":11},{"front":"show texture","meaning":"展示質感","examples":[{"en":"A makeup tutorial may show texture better than a magazine advert.","zh":"化妝教學可能比雜誌廣告更能展示質感。"},{"en":"To show texture means to reveal how a surface or material looks or feels, such as smooth, thick, rough, or creamy.","zh":"展示質感是指顯示表面或材料看起來或感覺如何，例如光滑、濃稠、粗糙或幼滑。"},{"en":"A close-up video can show texture better than a distant photograph.","zh":"近距離影片比遠距離照片更能展示質感。"},{"en":"Online shoppers appreciate videos that show texture when choosing fabric or cosmetics.","zh":"網上購物者選擇布料或化妝品時，會欣賞能展示質感的影片。"},{"en":"Showing texture gives useful information, but lighting can still affect how the product appears.","zh":"展示質感可以提供有用資訊，但燈光仍可能影響產品外觀。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"a magazine advert","meaning":"雜誌廣告","examples":[{"en":"A makeup tutorial may show texture better than a magazine advert.","zh":"化妝教學可能比雜誌廣告更能展示質感。"},{"en":"A magazine advert is a paid advertisement printed on one or more pages of a magazine.","zh":"雜誌廣告是刊登在雜誌一頁或多頁上的付費廣告。"},{"en":"A perfume company may use a full-page magazine advert with a famous model.","zh":"香水公司可能用名模製作一頁全版雜誌廣告。"},{"en":"A magazine advert can present a beautiful image but cannot show how a product moves or works.","zh":"雜誌廣告可以呈現漂亮畫面，但不能展示產品如何移動或運作。"},{"en":"Unlike video, a magazine advert usually gives consumers only a still visual impression.","zh":"與影片不同，雜誌廣告通常只能給消費者靜態的視覺印象。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"a gaming reviewer","meaning":"遊戲評測者","examples":[{"en":"A gaming reviewer may explain performance more clearly than a poster.","zh":"遊戲評測者可能比海報更清楚解釋性能表現。"},{"en":"A gaming reviewer is someone who tests and comments on video games, gaming hardware, or related products.","zh":"遊戲評測者是測試並評論電子遊戲、遊戲硬件或相關產品的人。"},{"en":"A gaming reviewer may discuss frame rate, controls, graphics, and loading times.","zh":"遊戲評測者可能討論畫面流暢度、控制、圖像和載入時間。"},{"en":"Players may watch a gaming reviewer before buying an expensive new game.","zh":"玩家購買昂貴新遊戲前可能先觀看遊戲評測者的影片。"},{"en":"A useful gaming reviewer should explain both advantages and problems rather than only praising the product.","zh":"有用的遊戲評測者應同時解釋優點和問題，而不是只讚好產品。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"explain performance","meaning":"解釋性能表現","examples":[{"en":"A gaming reviewer may explain performance more clearly than a poster.","zh":"遊戲評測者可能比海報更清楚解釋性能表現。"},{"en":"To explain performance means to describe how well a product, machine, person, or system works under actual conditions.","zh":"解釋性能表現是指描述產品、機器、人物或系統在實際條件下運作得有多好。"},{"en":"A car review may explain performance by discussing speed, braking, and fuel use.","zh":"汽車評測可以透過速度、煞車和耗油量來解釋性能表現。"},{"en":"A laptop reviewer can explain performance by showing how quickly programs open.","zh":"手提電腦評測者可以透過展示程式開啟速度來解釋性能表現。"},{"en":"Explaining performance with real tests is more useful than simply saying a product is “amazing”.","zh":"用真實測試解釋性能表現，比只說產品「非常好」更有用。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"a travel influencer","meaning":"旅遊KOL","examples":[{"en":"A travel influencer may reveal details that a hotel brochure ignores.","zh":"旅遊KOL可能揭示酒店小冊子忽略的細節。"},{"en":"A travel influencer is an online creator who shares information, experiences, photographs, or videos about destinations and journeys.","zh":"旅遊KOL是在網上分享目的地和旅程資訊、經驗、照片或影片的創作者。"},{"en":"A travel influencer may review hotels, flights, restaurants, or tourist attractions.","zh":"旅遊KOL可能評測酒店、航班、餐廳或旅遊景點。"},{"en":"Followers may use a travel influencer’s content when planning a holiday.","zh":"追蹤者計劃假期時可能參考旅遊KOL的內容。"},{"en":"A travel influencer can offer useful personal experience, but sponsored trips may affect what is shown.","zh":"旅遊KOL可以提供有用的個人經驗，但受贊助旅程可能影響他們展示的內容。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"reveal details","meaning":"揭示細節","examples":[{"en":"A travel influencer may reveal details that a hotel brochure ignores.","zh":"旅遊KOL可能揭示酒店小冊子忽略的細節。"},{"en":"To reveal details means to show or explain specific information that was previously hidden, unnoticed, or unknown.","zh":"揭示細節是指展示或解釋之前被隱藏、被忽略或未知的具體資訊。"},{"en":"A close inspection can reveal details that are invisible in a small photograph.","zh":"仔細檢查可以揭示小照片中看不到的細節。"},{"en":"Customer reviews may reveal details about noise or service that advertising leaves out.","zh":"顧客評價可能揭示廣告沒有提到的噪音或服務細節。"},{"en":"Revealing details helps people make better decisions when those details affect real experience.","zh":"當這些細節會影響真實體驗時，揭示細節可以幫助人作出更好的決定。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"a hotel brochure","meaning":"酒店小冊子","examples":[{"en":"A hotel brochure may conveniently ignore certain details.","zh":"酒店小冊子可能為求方便而略過某些細節。"},{"en":"A hotel brochure is a printed or digital booklet that presents a hotel’s rooms, facilities, services, and attractions.","zh":"酒店小冊子是介紹酒店房間、設施、服務和賣點的印刷或電子小冊子。"},{"en":"A hotel brochure may show the swimming pool, restaurant, and sea view.","zh":"酒店小冊子可能展示泳池、餐廳和海景。"},{"en":"Because its purpose is promotional, a hotel brochure usually emphasises positive features.","zh":"因為目的在於推廣，酒店小冊子通常會強調正面特色。"},{"en":"Travellers should compare a hotel brochure with independent reviews before booking.","zh":"旅客預訂前應把酒店小冊子與獨立評價作比較。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"conveniently ignore","meaning":"為求方便而略過","examples":[{"en":"A hotel brochure may conveniently ignore negative details.","zh":"酒店小冊子可能為求方便而略過負面細節。"},{"en":"To conveniently ignore something means to leave out information because mentioning it would be uncomfortable or disadvantageous.","zh":"「conveniently ignore」表示因為某項資訊會令人尷尬或不利，所以選擇不提。"},{"en":"A seller may conveniently ignore scratches when describing a used phone.","zh":"賣二手手機的人可能為求方便而略過機身刮痕。"},{"en":"A politician may conveniently ignore evidence that weakens an argument.","zh":"政治人物可能為求方便而略過削弱自己論點的證據。"},{"en":"When advertisements conveniently ignore disadvantages, consumers receive an incomplete picture.","zh":"當廣告為求方便而略過缺點，消費者得到的資訊便不完整。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"depend on reputation","meaning":"依賴聲譽","examples":[{"en":"Influencers depend on their reputation.","zh":"KOL依賴自己的聲譽。"},{"en":"To depend on reputation means to rely on other people continuing to see you as trustworthy, skilled, or respectable.","zh":"依賴聲譽是指要靠別人持續認為自己值得信任、有能力或受尊重。"},{"en":"A small restaurant may depend on reputation because most new customers come through recommendations.","zh":"小餐廳可能依賴聲譽，因為很多新顧客來自別人推薦。"},{"en":"Freelancers depend on reputation to win future work from clients.","zh":"自由工作者依賴聲譽來爭取未來工作。"},{"en":"Influencers who depend on reputation may lose followers if they repeatedly promote poor products.","zh":"依賴聲譽的KOL如果反覆推廣差劣產品，可能失去追蹤者。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"careless promotion","meaning":"草率的推廣","examples":[{"en":"Careless promotion may damage an influencer’s reputation.","zh":"草率的推廣可能損害KOL的聲譽。"},{"en":"Careless promotion is advertising done without enough checking, responsibility, or concern for possible harm.","zh":"草率的推廣是指沒有充分查證、責任感或考慮可能傷害便進行的廣告活動。"},{"en":"Recommending a health product without reading its warnings is careless promotion.","zh":"沒有閱讀警告便推薦健康產品，就是草率的推廣。"},{"en":"Careless promotion can hurt consumers if important risks are not mentioned.","zh":"如果重要風險沒有被提及，草率的推廣可能傷害消費者。"},{"en":"Influencers can avoid careless promotion by testing products, checking claims, and stating sponsorship clearly.","zh":"KOL可以透過測試產品、核實聲稱和清楚表明贊助來避免草率的推廣。"}],"source":"2021 Q5.pdf","sourcePage":12},{"front":"damage a long-term relationship with","meaning":"損害與……的長期關係","examples":[{"en":"Careless promotion may damage a long-term relationship with followers.","zh":"草率的推廣可能損害與追蹤者的長期關係。"},{"en":"To damage a long-term relationship with someone means to weaken trust that has been built over a long period.","zh":"損害與某人的長期關係是指削弱經過長時間建立的信任。"},{"en":"Repeatedly breaking promises can damage a long-term relationship with a friend.","zh":"反覆違反承諾可以損害與朋友的長期關係。"},{"en":"A company can damage a long-term relationship with customers by hiding serious problems.","zh":"公司隱瞞嚴重問題，可以損害與顧客的長期關係。"},{"en":"One profitable promotion may not be worth it if it damages a long-term relationship with loyal followers.","zh":"如果一次賺錢的推廣會損害與忠實追蹤者的長期關係，可能並不值得。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"long-term relationship","meaning":"長期關係","examples":[{"en":"Influencers often build a long-term relationship with followers.","zh":"KOL經常與追蹤者建立長期關係。"},{"en":"A long-term relationship is a connection between people or organisations that continues over a considerable period.","zh":"長期關係是人或機構之間持續相當長時間的連繫。"},{"en":"Good communication helps couples maintain a long-term relationship.","zh":"良好溝通有助伴侶維持長期關係。"},{"en":"A business builds a long-term relationship with customers by providing reliable service repeatedly.","zh":"企業透過反覆提供可靠服務與顧客建立長期關係。"},{"en":"Long-term relationships are difficult to build quickly but can be damaged by dishonesty.","zh":"長期關係難以在短時間建立，卻可能因不誠實而受損。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"be dismissed","meaning":"被否定；被忽視","examples":[{"en":"These advantages should not be dismissed.","zh":"這些優點不應被否定。"},{"en":"To be dismissed means to be rejected or treated as unimportant without enough consideration.","zh":"「be dismissed」表示在沒有充分考慮下被拒絕或被當作不重要。"},{"en":"A student’s concern should not be dismissed simply because the student is young.","zh":"學生的憂慮不應只因年紀小就被忽視。"},{"en":"Useful evidence should not be dismissed because it challenges a popular opinion.","zh":"有用證據不應因為挑戰受歡迎的觀點就被否定。"},{"en":"The benefits of influencer reviews should not be dismissed, even if there are also serious risks.","zh":"即使KOL評測也有嚴重風險，其優點仍不應被否定。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"even so","meaning":"即使如此","examples":[{"en":"Even so, these advantages do not prove that influencers are generally more trustworthy.","zh":"即使如此，這些優點並不能證明KOL一般而言更值得信任。"},{"en":"“Even so” means despite the point just mentioned, the following statement is still true.","zh":"「even so」表示儘管剛才的觀點成立，接下來的說法仍然是真的。"},{"en":"The weather forecast looks good; even so, we should bring an umbrella.","zh":"天氣預報看起來不錯；即使如此，我們仍應帶雨傘。"},{"en":"Influencers can show products clearly; even so, viewers should check sponsorship.","zh":"KOL可以清楚展示產品；即使如此，觀眾仍應查看贊助資料。"},{"en":"This phrase is useful when accepting one point but showing that it does not change the main conclusion.","zh":"當承認一個觀點但仍要指出它不會改變主要結論時，這個片語很有用。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"generally more trustworthy","meaning":"一般而言更值得信任","examples":[{"en":"These advantages do not prove that influencers are generally more trustworthy.","zh":"這些優點並不能證明KOL一般而言更值得信任。"},{"en":"“Generally more trustworthy” means usually or overall more deserving of trust than another person or source.","zh":"「generally more trustworthy」表示整體或通常比另一個人或來源更值得信任。"},{"en":"Official safety instructions are generally more trustworthy than anonymous online comments.","zh":"官方安全指引一般而言比匿名網上留言更值得信任。"},{"en":"Experts with relevant qualifications may be generally more trustworthy on technical questions.","zh":"在技術問題上，具相關資格的專家一般而言可能更值得信任。"},{"en":"One good experience cannot prove that an entire group is generally more trustworthy.","zh":"一次良好經驗不能證明整個群體一般而言更值得信任。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"comments can be filtered","meaning":"留言可以被篩選","examples":[{"en":"Comments can be filtered by the creator.","zh":"留言可以被創作者篩選。"},{"en":"“Comments can be filtered” means some responses can be hidden, removed, blocked, or selected before other viewers see them.","zh":"「comments can be filtered」表示部分回應可以在其他觀眾看見前被隱藏、刪除、封鎖或挑選。"},{"en":"Social media comments can be filtered to remove abusive language.","zh":"社交媒體留言可以被篩選，以移除侮辱性語言。"},{"en":"A creator may filter comments that criticise a sponsored product.","zh":"創作者可能篩走批評受贊助產品的留言。"},{"en":"If comments can be filtered, the visible reactions may not represent what all users really think.","zh":"如果留言可以被篩選，畫面上看到的反應未必代表所有使用者的真實想法。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"negative experiences","meaning":"負面經歷","examples":[{"en":"Negative experiences can be edited out.","zh":"負面經歷可以被剪走。"},{"en":"Negative experiences are unpleasant events, problems, disappointments, or failures that someone goes through.","zh":"負面經歷是某人遇到的不愉快事件、問題、失望或失敗。"},{"en":"A traveller may have negative experiences such as delays, poor service, or lost luggage.","zh":"旅客可能遇到延誤、差劣服務或行李遺失等負面經歷。"},{"en":"Product reviews are more useful when they include negative experiences as well as positive ones.","zh":"產品評測同時包含負面經歷和正面經歷時會更有用。"},{"en":"If negative experiences disappear from online content, viewers may receive an unrealistically positive picture.","zh":"如果負面經歷從網上內容中消失，觀眾可能得到過度正面的印象。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"be edited out","meaning":"被剪走；被刪去","examples":[{"en":"Negative experiences can be edited out.","zh":"負面經歷可以被剪走。"},{"en":"To be edited out means to be removed from a video, recording, text, or final version during editing.","zh":"「be edited out」表示在剪輯過程中從影片、錄音、文字或最終版本中被移除。"},{"en":"Long pauses are often edited out of recorded interviews.","zh":"錄製訪問中的長時間停頓通常會被剪走。"},{"en":"A creator may edit out moments when a promoted product fails.","zh":"創作者可能把受推廣產品失靈的片段剪走。"},{"en":"When problems are edited out, the final content can look much more perfect than real life.","zh":"當問題被剪走，最後的內容會比真實生活看起來完美得多。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"authentic content","meaning":"真實感內容","examples":[{"en":"“Authentic” content can still be carefully scripted.","zh":"「真實感」內容仍然可以經過仔細編排。"},{"en":"Authentic content is content that appears genuine, natural, and true to the creator’s real personality or experience.","zh":"真實感內容是看起來真誠、自然，而且符合創作者真實個性或經歷的內容。"},{"en":"Audiences often enjoy authentic content because it feels less formal and more personal.","zh":"觀眾常喜歡真實感內容，因為它感覺較不正式和較私人。"},{"en":"A video can look like authentic content while still being planned around a sponsor’s message.","zh":"一段影片可以看起來像真實感內容，同時仍圍繞贊助商訊息策劃。"},{"en":"Authentic appearance should not be confused with complete independence or honesty.","zh":"真實感的外表不應與完全獨立或完全誠實混為一談。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"carefully scripted","meaning":"經仔細編排","examples":[{"en":"Authentic-looking content can still be carefully scripted.","zh":"看似真實的內容仍然可以經仔細編排。"},{"en":"Carefully scripted means planned and written in detail before being presented.","zh":"「carefully scripted」表示在呈現之前已詳細計劃和寫好內容。"},{"en":"A television interview may look casual even though the questions are carefully scripted.","zh":"電視訪問可以看起來很隨意，即使問題其實經仔細編排。"},{"en":"Sponsored videos can be carefully scripted so that product praise sounds natural.","zh":"贊助影片可以經仔細編排，令對產品的讚賞聽起來很自然。"},{"en":"Content being carefully scripted is not automatically dishonest, but viewers should know when commercial control exists.","zh":"內容經仔細編排不一定是不誠實，但觀眾應知道何時存在商業控制。"}],"source":"2021 Q5.pdf","sourcePage":13},{"front":"just because…does not mean…","meaning":"只是因為……並不代表……","examples":[{"en":"Just because a message looks spontaneous does not mean it is honest.","zh":"只是因為訊息看似即興，並不代表它是誠實的。"},{"en":"“Just because A does not mean B” shows that A is not enough evidence to prove B.","zh":"「just because A does not mean B」表示A本身不足以證明B。"},{"en":"Just because a product is expensive does not mean it is high quality.","zh":"只是因為產品昂貴，並不代表它品質高。"},{"en":"Just because someone has many followers does not mean they are an expert.","zh":"只是因為某人有很多追蹤者，並不代表他是專家。"},{"en":"This structure helps challenge conclusions that are based on weak or incomplete evidence.","zh":"這個句式有助反駁建基於薄弱或不完整證據的結論。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"look spontaneous","meaning":"看似即興","examples":[{"en":"A message may look spontaneous without being honest.","zh":"訊息可能看似即興，卻不一定誠實。"},{"en":"To look spontaneous means to appear unplanned, natural, and produced in the moment.","zh":"看似即興是指表面上像沒有預先計劃、自然地即場產生。"},{"en":"A casual-looking video may look spontaneous even after several rehearsals.","zh":"一段看似隨意的影片即使排練過幾次，也可能看似即興。"},{"en":"Livestream promotions often look spontaneous because creators respond immediately to viewers.","zh":"直播推廣常看似即興，因為創作者會即時回應觀眾。"},{"en":"Looking spontaneous can make content feel genuine, but preparation and sponsorship may still exist behind it.","zh":"看似即興可以令內容感覺真實，但背後仍可能存在準備和贊助。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"the real danger lies in","meaning":"真正的危險在於","examples":[{"en":"The real danger lies in the fact that sponsored advice can appear independent.","zh":"真正的危險在於受贊助建議可以看似獨立。"},{"en":"“The real danger lies in” identifies the most serious or important source of risk.","zh":"「the real danger lies in」用來指出最嚴重或最重要的風險來源。"},{"en":"The real danger lies in drivers believing they can safely use phones while moving.","zh":"真正的危險在於駕駛者以為行車時使用手機仍然安全。"},{"en":"With hidden advertising, the real danger lies in consumers not realising they are being persuaded.","zh":"對隱藏式廣告來說，真正的危險在於消費者沒有察覺自己正在被說服。"},{"en":"This phrase helps move attention away from a surface issue and towards a deeper problem.","zh":"這個片語有助把注意力由表面問題轉向更深層的危險。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"sponsored advice","meaning":"贊助建議","examples":[{"en":"Sponsored advice can appear independent when it is not.","zh":"贊助建議可以在其實並非獨立時看似獨立。"},{"en":"Sponsored advice is a recommendation or opinion connected to payment, free products, or another commercial benefit.","zh":"贊助建議是與付款、免費產品或其他商業利益有關的推薦或意見。"},{"en":"A creator giving travel tips after receiving a free hotel stay may be providing sponsored advice.","zh":"創作者接受免費酒店住宿後提供旅遊貼士，可能就是在提供贊助建議。"},{"en":"Sponsored advice can still contain useful information if the commercial relationship is clear.","zh":"如果商業關係清楚，贊助建議仍然可以包含有用資訊。"},{"en":"Consumers should know when advice is sponsored so they can judge possible bias.","zh":"消費者應知道建議何時受贊助，才能判斷可能存在的偏見。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"appear independent","meaning":"看似獨立","examples":[{"en":"Sponsored advice can appear independent when it is not.","zh":"贊助建議可以在其實並非獨立時看似獨立。"},{"en":"To appear independent means to look as though a message or person is free from outside control, payment, or influence.","zh":"看似獨立是指訊息或人物表面上好像不受外部控制、付款或影響。"},{"en":"A review may appear independent even if the company supplied the product for free.","zh":"即使公司免費提供產品，某個評測仍可能看似獨立。"},{"en":"Research should not merely appear independent; conflicts of interest should be disclosed.","zh":"研究不應只看似獨立；利益衝突也應披露。"},{"en":"When paid content appears independent, audiences may give it more trust than they otherwise would.","zh":"當付費內容看似獨立，觀眾可能會給予它原本不會有的額外信任。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"at least","meaning":"至少","examples":[{"en":"At least with traditional advertisements, the commercial motive is usually visible from the start.","zh":"至少在傳統廣告中，商業動機通常從一開始已清楚可見。"},{"en":"“At least” highlights one positive, certain, or minimum point even when the overall situation is imperfect.","zh":"「at least」用來指出即使整體情況不完美，仍有一個正面、確定或最低限度的重點。"},{"en":"The journey was delayed, but at least everyone arrived safely.","zh":"旅程雖然延誤，但至少所有人都安全到達。"},{"en":"The advert may exaggerate, but at least viewers know it is an advert.","zh":"廣告可能誇大，但至少觀眾知道它是廣告。"},{"en":"This phrase is useful when recognising one limited advantage in an otherwise negative situation.","zh":"當情況整體負面，但仍有一個有限優點時，這個片語很有用。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"commercial motive","meaning":"商業動機","examples":[{"en":"The commercial motive is usually visible from the start.","zh":"商業動機通常從一開始已清楚可見。"},{"en":"A commercial motive is the intention to earn money, increase sales, or gain another business benefit.","zh":"商業動機是指賺取金錢、增加銷售或取得其他商業利益的目的。"},{"en":"A shop offering a discount has a clear commercial motive: it wants customers to buy.","zh":"商店提供折扣有清楚的商業動機：希望顧客購買。"},{"en":"Personal stories can hide a commercial motive when they are used to promote sponsored products.","zh":"當個人故事被用來推廣受贊助產品時，可能隱藏商業動機。"},{"en":"Knowing the commercial motive helps consumers judge why a message is being presented.","zh":"知道商業動機有助消費者判斷訊息為何會被呈現。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"visible from the start","meaning":"一開始已清楚可見","examples":[{"en":"The commercial motive is usually visible from the start.","zh":"商業動機通常一開始已清楚可見。"},{"en":"“Visible from the start” means clear or noticeable from the very beginning.","zh":"「visible from the start」表示從最開始就清楚或容易察覺。"},{"en":"In a television commercial, the brand logo is often visible from the start.","zh":"電視廣告中的品牌標誌通常一開始已清楚可見。"},{"en":"A conflict of interest should be visible from the start rather than revealed after people have trusted the advice.","zh":"利益衝突應一開始已清楚可見，而不是在人們信任建議後才披露。"},{"en":"When sponsorship is visible from the start, viewers can interpret the message with proper caution.","zh":"當贊助一開始已清楚可見，觀眾可以帶着適當警覺理解訊息。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, social media influencers may be more engaging than traditional advertisements.","zh":"總括而言，社交媒體KOL可能比傳統廣告更吸引人。"},{"en":"“All things considered” introduces a conclusion reached after thinking about the main advantages and disadvantages.","zh":"「all things considered」用來帶出考慮主要優點和缺點後得出的結論。"},{"en":"All things considered, taking the train is cheaper and less stressful than driving.","zh":"總括而言，乘火車比駕車便宜，而且壓力較少。"},{"en":"All things considered, influencer content can be useful but should not automatically be trusted.","zh":"總括而言，KOL內容可以有用，但不應自動被信任。"},{"en":"This phrase is especially useful in conclusions because it signals a balanced final judgement.","zh":"這個片語特別適合用在結論中，因為它表示一個平衡的最終判斷。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"more engaging than","meaning":"比……更吸引人","examples":[{"en":"Social media influencers may be more engaging than traditional advertisements.","zh":"社交媒體KOL可能比傳統廣告更吸引人。"},{"en":"“More engaging than” means better at holding attention or making people interested than something else.","zh":"「more engaging than」表示比另一樣東西更能保持注意力或令人感興趣。"},{"en":"A practical science experiment may be more engaging than a long lecture.","zh":"實際科學實驗可能比長篇講課更吸引人。"},{"en":"A video demonstration can be more engaging than a printed product description.","zh":"影片示範可以比印刷產品說明更吸引人。"},{"en":"Being more engaging than another message can increase attention without making the information more trustworthy.","zh":"比另一種訊息更吸引人，可以增加注意力，但不會令資訊自動變得更可信。"}],"source":"2021 Q5.pdf","sourcePage":14},{"front":"what matters is not whether…, but whether…","meaning":"重要的不是……而是……","examples":[{"en":"What matters is not whether a message comes from an individual or a company, but whether it is transparent and responsible.","zh":"重要的不是訊息來自個人還是公司，而是它是否透明和負責任。"},{"en":"This structure says the first distinction is less important than the second question.","zh":"這個句式表示第一個分別較不重要，真正重要的是第二個問題。"},{"en":"What matters is not whether a student answers quickly, but whether the answer is correct.","zh":"重要的不是學生回答得有多快，而是答案是否正確。"},{"en":"What matters is not whether an advert feels friendly, but whether viewers know who paid for it.","zh":"重要的不是廣告感覺多友善，而是觀眾是否知道誰支付了費用。"},{"en":"This pattern helps redirect attention from a superficial difference to the real standard that should be used.","zh":"這個句式有助把注意力由表面差異轉向真正應使用的判斷標準。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"a smiling individual","meaning":"面帶笑容的個人","examples":[{"en":"A message may come from a smiling individual.","zh":"訊息可能來自一個面帶笑容的個人。"},{"en":"A smiling individual is a person whose friendly appearance may make a message feel warm or personal.","zh":"面帶笑容的個人是以友善外表令訊息感覺溫暖或私人化的人。"},{"en":"An advert may show a smiling individual holding a product to create a positive feeling.","zh":"廣告可能展示一位面帶笑容的個人拿着產品，以營造正面感覺。"},{"en":"Viewers may respond emotionally to a smiling individual before thinking about the evidence.","zh":"觀眾可能在思考證據前，已先對面帶笑容的個人產生情感反應。"},{"en":"A smiling individual can make a message pleasant, but appearance does not prove honesty.","zh":"面帶笑容的個人可以令訊息更討好，但外表不能證明誠實。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"a polished company","meaning":"包裝精美的公司","examples":[{"en":"A message may come from a polished company.","zh":"訊息可能來自一家包裝精美的公司。"},{"en":"A polished company is a business that presents itself in a highly professional, attractive, and carefully organised way.","zh":"包裝精美的公司是以非常專業、吸引和經仔細安排的方式呈現自己的企業。"},{"en":"A polished company may use expensive design and carefully prepared advertising.","zh":"包裝精美的公司可能使用昂貴設計和精心準備的廣告。"},{"en":"Consumers may trust a polished company because its website and packaging look professional.","zh":"消費者可能因為網站和包裝看起來專業而信任一家包裝精美的公司。"},{"en":"A polished company can still make misleading claims, so presentation should not replace evidence.","zh":"包裝精美的公司仍可能作出誤導性聲稱，所以外在形象不能取代證據。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"transparent, verifiable and responsible","meaning":"透明、可核實和負責任","examples":[{"en":"A trustworthy message should be transparent, verifiable, and responsible.","zh":"值得信任的訊息應該透明、可核實和負責任。"},{"en":"“Transparent, verifiable and responsible” means open about its interests, able to be checked, and willing to accept consequences.","zh":"「transparent, verifiable and responsible」表示公開利益關係、能被查證，而且願意承擔後果。"},{"en":"A medical claim is stronger when it is transparent, verifiable, and responsible.","zh":"醫療聲稱如果透明、可核實和負責任，會更可靠。"},{"en":"Companies should make advertising transparent, verifiable, and responsible by showing sponsorship and supporting evidence.","zh":"公司應透過展示贊助和支持證據，令廣告透明、可核實和負責任。"},{"en":"These qualities provide a stronger basis for trust than popularity or familiarity.","zh":"這些特質比受歡迎程度或熟悉感更能建立信任。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"verifiable","meaning":"可核實的","examples":[{"en":"A trustworthy claim should be verifiable.","zh":"值得信任的聲稱應該是可核實的。"},{"en":"Verifiable means able to be checked and confirmed using reliable information or evidence.","zh":"「verifiable」表示能用可靠資訊或證據加以查證和確認。"},{"en":"A date in a history essay is verifiable if reliable records can confirm it.","zh":"歷史文章中的日期如果能由可靠紀錄確認，就是可核實的。"},{"en":"Product claims should be verifiable through tests rather than depending only on testimonials.","zh":"產品聲稱應能透過測試核實，而不是只依靠用家見證。"},{"en":"If a statement cannot be checked at all, consumers should be cautious about treating it as fact.","zh":"如果一項說法完全無法查證，消費者應小心，不要把它當成事實。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"check sponsorship labels","meaning":"查看贊助標籤","examples":[{"en":"Consumers should check sponsorship labels.","zh":"消費者應查看贊助標籤。"},{"en":"To check sponsorship labels means to look for words or markers showing that content has been paid for or commercially supported.","zh":"查看贊助標籤是指留意顯示內容曾獲付款或商業支持的字眼或標記。"},{"en":"Before trusting a product review, viewers can check sponsorship labels such as “ad” or “sponsored”.","zh":"相信產品評測前，觀眾可以查看「廣告」或「受贊助」等贊助標籤。"},{"en":"Checking sponsorship labels helps people understand the creator’s possible financial interest.","zh":"查看贊助標籤有助人們了解創作者可能存在的金錢利益。"},{"en":"A clear label does not tell consumers whether a product is good, but it makes the relationship more transparent.","zh":"清楚標籤不能告訴消費者產品是否好，但可以令關係更透明。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"compare different sources","meaning":"比較不同資料來源","examples":[{"en":"Consumers should compare different sources before trusting a claim.","zh":"消費者在相信聲稱前應比較不同資料來源。"},{"en":"To compare different sources means to check information from more than one person, organisation, website, or publication.","zh":"比較不同資料來源是指查看多於一位人物、機構、網站或出版物提供的資訊。"},{"en":"Students compare different sources when researching a controversial historical event.","zh":"學生研究具爭議的歷史事件時會比較不同資料來源。"},{"en":"Shoppers can compare different sources by reading expert reviews and customer experiences.","zh":"購物者可以閱讀專家評測和顧客經驗來比較不同資料來源。"},{"en":"Comparing different sources makes it easier to notice disagreement, missing information, or possible bias.","zh":"比較不同資料來源較容易發現分歧、遺漏資訊或可能存在的偏見。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"have the knowledge to","meaning":"有知識去……","examples":[{"en":"Consumers should ask whether the influencer has the knowledge to make the claim.","zh":"消費者應問KOL是否有知識去作出該項聲稱。"},{"en":"To have the knowledge to do something means to possess enough relevant understanding to do it properly.","zh":"「have the knowledge to」表示具備足夠相關知識，可以妥善完成某件事。"},{"en":"A trained mechanic has the knowledge to diagnose many common car problems.","zh":"受過訓練的技工有知識去診斷很多常見汽車問題。"},{"en":"Someone may enjoy exercise without having the knowledge to give medical advice.","zh":"一個人可以喜歡運動，卻沒有知識去提供醫療建議。"},{"en":"Before accepting expert-sounding advice, ask whether the speaker has the knowledge to make that judgement.","zh":"接受聽起來很專業的建議前，應問講者是否有知識作出該判斷。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"make the claim","meaning":"作出聲稱","examples":[{"en":"An influencer should have the knowledge to make the claim.","zh":"KOL應具備足夠知識去作出該項聲稱。"},{"en":"To make the claim means to state that something is true, often in a way that may need evidence.","zh":"作出聲稱是指表示某件事是真的，而這種說法通常可能需要證據支持。"},{"en":"A company should test its product before making the claim that it is safer than competitors.","zh":"公司聲稱產品比競爭者更安全前，應先進行測試。"},{"en":"A student needs evidence before making the claim that one policy caused an economic change.","zh":"學生聲稱某項政策造成經濟變化前，需要有證據支持。"},{"en":"The stronger the claim, the stronger the evidence a person should have before making it.","zh":"聲稱越強烈，提出者在作出聲稱前就應有越有力的證據。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"companies and platforms","meaning":"公司和平台","examples":[{"en":"Companies and platforms should make paid promotions clear.","zh":"公司和平台應令付費推廣清楚可辨。"},{"en":"Companies and platforms are businesses that sell or advertise products and the online services that distribute content to users.","zh":"公司和平台分別指銷售或宣傳產品的企業，以及向使用者分發內容的網上服務。"},{"en":"Companies create advertisements while platforms decide how those advertisements appear to audiences.","zh":"公司製作廣告，而平台決定這些廣告如何呈現在觀眾面前。"},{"en":"Companies and platforms share responsibility when sponsored content is difficult to recognise.","zh":"當受贊助內容難以辨認時，公司和平台都要共同承擔責任。"},{"en":"Clear rules from companies and platforms can help consumers understand when commercial influence is present.","zh":"公司和平台制定清楚規則，可以幫助消費者了解何時存在商業影響。"}],"source":"2021 Q5.pdf","sourcePage":15},{"front":"meanwhile","meaning":"與此同時","examples":[{"en":"Companies and platforms, meanwhile, should make paid promotions as clear as possible.","zh":"與此同時，公司和平台應令付費推廣盡量清晰。"},{"en":"“Meanwhile” introduces something happening at the same time or another related point that should also be considered.","zh":"「meanwhile」用來帶出同一時間發生的事情，或另一個也需要考慮的相關重點。"},{"en":"Parents can prepare dinner; meanwhile, the children can finish their homework.","zh":"父母可以準備晚餐；與此同時，孩子可以完成家課。"},{"en":"Consumers should check claims; companies, meanwhile, should provide clear sponsorship information.","zh":"消費者應核實聲稱；與此同時，公司應提供清楚的贊助資料。"},{"en":"In an argument, “meanwhile” can shift attention to another group’s responsibility.","zh":"在論證中，「meanwhile」可以把注意力轉向另一個群體的責任。"}],"source":"2021 Q5.pdf","sourcePage":16},{"front":"paid promotions","meaning":"付費推廣","examples":[{"en":"Paid promotions should be made as clear as possible.","zh":"付費推廣應盡量清楚。"},{"en":"Paid promotions are advertisements or recommendations for which someone receives money, products, services, or other benefits.","zh":"付費推廣是指有人因廣告或推薦而收到金錢、產品、服務或其他利益。"},{"en":"A sponsored restaurant review is a paid promotion if the creator receives payment.","zh":"如果創作者收到付款，受贊助餐廳評測就是付費推廣。"},{"en":"Paid promotions are not automatically misleading when their commercial nature is openly stated.","zh":"如果商業性質公開說明，付費推廣不一定具誤導性。"},{"en":"Hidden paid promotions are risky because viewers may mistake advertising for independent opinion.","zh":"隱藏式付費推廣有風險，因為觀眾可能把廣告誤當成獨立意見。"}],"source":"2021 Q5.pdf","sourcePage":16},{"front":"as clear as possible","meaning":"盡量清晰","examples":[{"en":"Platforms should make paid promotions as clear as possible.","zh":"平台應令付費推廣盡量清晰。"},{"en":"“As clear as possible” means making something as easy to understand or recognise as circumstances allow.","zh":"「as clear as possible」表示在情況許可下，把某件事做到最容易理解或辨認。"},{"en":"Teachers should make examination instructions as clear as possible.","zh":"老師應令考試指示盡量清晰。"},{"en":"Health warnings should be as clear as possible so users understand the risks.","zh":"健康警告應盡量清晰，讓使用者明白風險。"},{"en":"Sponsorship labels should be as clear as possible rather than hidden in small or confusing text.","zh":"贊助標籤應盡量清晰，而不是藏在細小或令人混亂的文字中。"}],"source":"2021 Q5.pdf","sourcePage":16},{"front":"in the end","meaning":"最終","examples":[{"en":"In the end, trust should be earned by honesty.","zh":"最終，信任應靠誠實贏得。"},{"en":"“In the end” introduces a final result, conclusion, or most important point after everything has been considered.","zh":"「in the end」用來帶出經過所有考慮後的最終結果、結論或最重要重點。"},{"en":"We discussed several routes, but in the end we chose the fastest one.","zh":"我們討論了幾條路線，但最終選擇了最快的一條。"},{"en":"Advertising styles may change, but in the end consumers still need truthful information.","zh":"廣告形式可能改變，但最終消費者仍需要真實資訊。"},{"en":"This phrase is useful for signalling the final conclusion of an argument.","zh":"這個片語適合用來標示論證的最後結論。"}],"source":"2021 Q5.pdf","sourcePage":16},{"front":"be earned by honesty","meaning":"靠誠實贏得","examples":[{"en":"Trust should be earned by honesty.","zh":"信任應靠誠實贏得。"},{"en":"To be earned by honesty means to be gained gradually because someone repeatedly tells the truth and behaves openly.","zh":"靠誠實贏得是指因某人反覆說真話和坦誠行事而逐漸取得信任。"},{"en":"A teacher’s respect is earned by honesty, fairness, and consistent behaviour.","zh":"老師的尊重是靠誠實、公平和一致行為贏得的。"},{"en":"Customer loyalty is earned by honesty when a company admits problems instead of hiding them.","zh":"公司承認問題而不是隱瞞時，可以靠誠實贏得顧客忠誠。"},{"en":"Trust earned by honesty is stronger than trust created only by attractive presentation.","zh":"靠誠實贏得的信任，比只靠漂亮包裝製造的信任更穩固。"}],"source":"2021 Q5.pdf","sourcePage":16},{"front":"manufactured by intimacy","meaning":"靠親密感製造出來","examples":[{"en":"Trust should not be manufactured by intimacy.","zh":"信任不應靠親密感製造出來。"},{"en":"“Manufactured by intimacy” means deliberately created by making people feel personally close, even when a real close relationship does not exist.","zh":"「manufactured by intimacy」表示即使沒有真正親密關係，也刻意令人感到私人親近，從而製造信任。"},{"en":"Advertising can be manufactured by intimacy when creators repeatedly call viewers their “best friends” while selling products.","zh":"創作者一邊賣產品，一邊反覆稱觀眾為「最好的朋友」，就是利用親密感製造廣告效果。"},{"en":"A sense of closeness may be manufactured by intimacy through personal stories, direct eye contact, and familiar language.","zh":"個人故事、直視鏡頭和熟悉語言，都可能令人產生被刻意製造的親密感。"},{"en":"Genuine trust should grow from honesty and responsibility rather than be manufactured by intimacy.","zh":"真正信任應來自誠實和責任，而不是靠親密感製造出來。"}],"source":"2021 Q5.pdf","sourcePage":16}],"dse/writing/part-b/2021/Q6":[{"front":"one quiet revolution","meaning":"一場靜靜的改變","examples":[{"en":"The 21-day challenge became one quiet revolution in the writer’s life.","zh":"這個二十一日挑戰成為作者生命中一場靜靜的改變。"},{"en":"One quiet revolution is a gradual but important change that happens without drama or attention.","zh":"「一場靜靜的改變」指沒有戲劇性或引人注意，卻逐漸帶來重要影響的改變。"},{"en":"Reading for twenty minutes every day became one quiet revolution in my study habits.","zh":"每天閱讀二十分鐘，成為我學習習慣中一場靜靜的改變。"},{"en":"A small daily habit can become one quiet revolution because repeated actions slowly change the way we live.","zh":"一個小小的日常習慣可以成為一場靜靜的改變，因為重複的行動會慢慢改變我們的生活方式。"},{"en":"Sometimes one quiet revolution matters more than a sudden change that does not last.","zh":"有時，一場靜靜的改變比不能持久的突然轉變更重要。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"before this challenge","meaning":"在這次挑戰之前","examples":[{"en":"Before this challenge, gratitude did not seem life-changing to the writer.","zh":"在這次挑戰之前，作者並不覺得感恩能改變人生。"},{"en":"Before this challenge refers to the period before the writer began the 21-day activity.","zh":"「在這次挑戰之前」指作者開始二十一日活動以前的一段時間。"},{"en":"Before this challenge, I rarely stopped to notice the good parts of an ordinary day.","zh":"在這次挑戰之前，我很少停下來留意平凡一天中的好事。"},{"en":"My habits were different before this challenge because I had not yet started reflecting every night.","zh":"在這次挑戰之前，我的習慣有所不同，因為我還未開始每晚反思。"},{"en":"Looking at life before this challenge makes the later changes easier to see.","zh":"回看在這次挑戰之前的生活，更容易看出後來的改變。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"gratitude","meaning":"感恩；感激之情","examples":[{"en":"Gratitude sounded like one of those pretty words people put under sunset photos.","zh":"「感恩」聽起來就像人們放在日落照片下面那些漂亮的字眼之一。"},{"en":"Gratitude is the feeling of recognising and appreciating something good that you have received or experienced.","zh":"感恩是察覺並珍惜自己得到或經歷的美好事物的一種感受。"},{"en":"I felt gratitude when a classmate shared her notes with me after I missed school.","zh":"我缺課後，同學把筆記分享給我，我感到很感恩。"},{"en":"Practising gratitude can help people notice support and kindness that they might otherwise overlook.","zh":"練習感恩可以幫助人留意原本可能忽略的支持和善意。"},{"en":"Gratitude does not mean ignoring problems; it means also recognising what is still good.","zh":"感恩並不代表忽視問題，而是同時看見仍然存在的美好。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"sounded to me like","meaning":"在我聽來像是","examples":[{"en":"Gratitude sounded to me like a pretty but ordinary word.","zh":"感恩在我聽來像是一個漂亮但普通的字。"},{"en":"“Sounded to me like” is used to describe the impression an idea or statement gave someone.","zh":"「在我聽來像是」用來描述某個想法或說法給人的印象。"},{"en":"His explanation sounded to me like an excuse because he avoided answering the main question.","zh":"他的解釋在我聽來像是藉口，因為他避開了主要問題。"},{"en":"The plan sounded to me like a good idea at first, but the cost later worried me.","zh":"那個計劃起初在我聽來像是好主意，但後來它的成本令我擔心。"},{"en":"Something can sound to me like one thing even if I later understand it differently.","zh":"某件事在我聽來可能像是一回事，即使之後我有不同理解。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"one of those","meaning":"那些……之一","examples":[{"en":"Gratitude sounded like one of those pretty words used in social media captions.","zh":"感恩聽起來像是社交媒體帖文中那些漂亮字眼之一。"},{"en":"“One of those” points to one member of a familiar group or type of things.","zh":"「那些……之一」指出屬於某個熟悉類別中的其中一個。"},{"en":"It was one of those mornings when everything seemed to go wrong.","zh":"那是那些甚麼都好像出錯的早晨之一。"},{"en":"This is one of those rules that seems unnecessary until an accident happens.","zh":"這是那些在意外發生前看似沒有必要的規則之一。"},{"en":"Calling something one of those things often shows that the speaker expects the listener to recognise the type.","zh":"說某件事是「那些……之一」，通常表示說話者認為聽者知道是哪一類事物。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"pretty words","meaning":"漂亮但空泛的字眼","examples":[{"en":"Gratitude first seemed like one of those pretty words under sunset photos.","zh":"感恩起初就像日落照片下面那些漂亮但空泛的字眼之一。"},{"en":"Pretty words are attractive-sounding expressions that may sometimes seem deeper than their actual meaning.","zh":"「漂亮但空泛的字眼」是聽起來吸引，卻有時比實際意思顯得更深刻的說法。"},{"en":"The advertisement used pretty words about happiness but gave few details about the product.","zh":"那則廣告用了許多關於幸福的漂亮字眼，卻很少提供產品細節。"},{"en":"Pretty words are not enough if a promise is never followed by action.","zh":"如果承諾從不化為行動，再漂亮的字眼也不夠。"},{"en":"A phrase may sound like pretty words at first but become meaningful through real experience.","zh":"一個說法起初可能只是漂亮字眼，卻可以透過真實經驗變得有意義。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"sunset photos","meaning":"日落照片","examples":[{"en":"People often put words like gratitude under sunset photos.","zh":"人們常把「感恩」之類的字放在日落照片下面。"},{"en":"Sunset photos are pictures taken when the sun is going down and the sky is often colourful.","zh":"日落照片是在太陽下山、天空通常色彩豐富時拍攝的照片。"},{"en":"My friend took several sunset photos at the beach after dinner.","zh":"晚飯後，我的朋友在海灘拍了幾張日落照片。"},{"en":"Sunset photos are popular online because the changing light can make ordinary places look beautiful.","zh":"日落照片在網上很受歡迎，因為變化中的光線可以令普通地方顯得很美。"},{"en":"A thoughtful caption can add meaning to sunset photos, but the picture itself does not prove the words are sincere.","zh":"有心思的文字可以為日落照片增添意義，但照片本身不能證明文字是否真誠。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"not exactly life-changing","meaning":"不算真的改變人生","examples":[{"en":"Gratitude seemed nice, but not exactly life-changing.","zh":"感恩似乎不錯，但不算真的改變人生。"},{"en":"“Not exactly life-changing” means something may be pleasant or useful but does not appear powerful enough to transform your life.","zh":"「不算真的改變人生」表示某事可能令人愉快或有用，但似乎沒有強大到能徹底改變人生。"},{"en":"Buying a new notebook was helpful, but not exactly life-changing.","zh":"買一本新筆記簿很有幫助，但不算真的改變人生。"},{"en":"A small idea may seem not exactly life-changing until you practise it consistently.","zh":"一個小想法起初可能不算真的改變人生，直到你持續實踐它。"},{"en":"Saying something is not exactly life-changing usually plays down how important it seems.","zh":"說某件事「不算真的改變人生」，通常是在淡化它看起來的重要性。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"for better or worse","meaning":"不論好壞；無論如何","examples":[{"en":"For better or worse, social media had changed how the writer measured life.","zh":"不論好壞，社交媒體已經改變了作者衡量人生的方式。"},{"en":"“For better or worse” means whether the result is good or bad, the situation is now a reality.","zh":"「不論好壞」表示無論結果是好是壞，這種情況已成為現實。"},{"en":"For better or worse, smartphones have changed how families communicate.","zh":"不論好壞，智能電話已改變家庭溝通的方式。"},{"en":"Moving away from home changed me, for better or worse, because I had to become more independent.","zh":"離家生活不論好壞都改變了我，因為我必須變得更獨立。"},{"en":"We use “for better or worse” when a change has both possible benefits and disadvantages.","zh":"當一項改變可能同時帶來好處和壞處時，我們會使用「不論好壞」。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"social media","meaning":"社交媒體","examples":[{"en":"Social media had taught the writer to measure life through comparison.","zh":"社交媒體令作者學會透過比較來衡量人生。"},{"en":"Social media refers to online platforms where people create, share, and respond to posts, photos, videos, and messages.","zh":"社交媒體指人們可以建立、分享及回應帖文、照片、影片和訊息的網上平台。"},{"en":"Students often use social media to keep in touch with friends after school.","zh":"學生放學後常使用社交媒體與朋友保持聯絡。"},{"en":"Social media can encourage comparison when users mostly show the happiest parts of their lives.","zh":"當使用者主要展示人生中最快樂的部分時，社交媒體可能令人更容易作比較。"},{"en":"Social media can connect people, but using it constantly may also affect mood and attention.","zh":"社交媒體能把人連繫起來，但經常使用也可能影響心情和專注力。"}],"source":"2021 Q6.pdf","sourcePage":1},{"front":"had taught me to","meaning":"教會了我去……","examples":[{"en":"Social media had taught me to measure my life in likes and marks.","zh":"社交媒體教會了我用讚好數和分數衡量人生。"},{"en":"“Had taught me to” means an earlier experience had gradually trained or influenced someone to behave in a certain way.","zh":"「教會了我去……」表示較早的經歷逐漸訓練或影響某人以某種方式行事。"},{"en":"Working in a busy café had taught me to stay calm when several customers needed help at once.","zh":"在繁忙咖啡店工作教會了我在幾位顧客同時需要幫助時保持冷靜。"},{"en":"Repeated criticism had taught me to check my work carefully before submitting it.","zh":"一再受到批評教會了我在交功課前仔細檢查。"},{"en":"Something that had taught me to act in a certain way may influence me even after the original situation has ended.","zh":"一件曾教會我某種做法的事，即使已經結束，也可能繼續影響我。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"measure my life in","meaning":"用……衡量我的人生","examples":[{"en":"I had learned to measure my life in likes, marks and other people’s highlights.","zh":"我已學會用讚好數、分數和別人生活中的精彩時刻衡量我的人生。"},{"en":"To measure my life in something means to judge my success or worth mainly by that standard.","zh":"「用……衡量我的人生」是指主要以某個標準判斷自己的成功或價值。"},{"en":"If I measure my life in exam marks alone, one bad result can make everything seem like failure.","zh":"如果我只用考試分數衡量人生，一次差成績也可能令一切看似失敗。"},{"en":"People who measure their lives in money may overlook friendship, health, and free time.","zh":"用金錢衡量人生的人可能忽略友誼、健康和自由時間。"},{"en":"It is healthier to use several values rather than measure my life in one number.","zh":"與其只用一個數字衡量我的人生，不如使用多種價值作判斷會更健康。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"likes and marks","meaning":"讚好數和分數","examples":[{"en":"The writer measured life in likes and marks.","zh":"作者用讚好數和分數衡量人生。"},{"en":"Likes and marks are two kinds of numbers that can represent online approval and academic performance.","zh":"讚好數和分數是兩種數字，分別可以代表網上認同和學業表現。"},{"en":"A student may feel successful when likes and marks are high, even though they show only part of life.","zh":"當讚好數和分數很高時，學生可能覺得自己很成功，但它們只反映人生的一部分。"},{"en":"Depending too much on likes and marks can make confidence rise and fall with every result.","zh":"過度依賴讚好數和分數，可能令自信隨每次結果上落。"},{"en":"Likes and marks are useful information, but they cannot measure kindness, effort, or happiness completely.","zh":"讚好數和分數是有用資料，但不能完整衡量善良、努力或快樂。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"other people’s highlights","meaning":"別人生活中的精彩時刻","examples":[{"en":"Social media made the writer compare daily life with other people’s highlights.","zh":"社交媒體令作者把自己的日常生活與別人生活中的精彩時刻比較。"},{"en":"Other people’s highlights are the best, happiest, or most impressive moments they choose to show.","zh":"「別人生活中的精彩時刻」指他們選擇展示的最好、最快樂或最令人羨慕的時刻。"},{"en":"Holiday photos may be other people’s highlights, while the stressful journey behind them stays unseen.","zh":"假期照片可能是別人生活中的精彩時刻，而背後辛苦的旅程並沒有被看見。"},{"en":"Comparing ordinary days with other people’s highlights can make normal life seem worse than it really is.","zh":"把普通日子與別人的精彩時刻比較，可能令人覺得自己的生活比實際更差。"},{"en":"Remember that other people’s highlights are not a complete picture of their lives.","zh":"要記住，別人生活中的精彩時刻並不是他們人生的完整畫面。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"accept the challenge","meaning":"接受挑戰","examples":[{"en":"I accepted the 21-day Gratitude Challenge because I wanted to change.","zh":"我接受了二十一日感恩挑戰，因為我想作出改變。"},{"en":"To accept the challenge means to agree to try a difficult task or activity.","zh":"「接受挑戰」指同意嘗試一項有難度的任務或活動。"},{"en":"I accepted the challenge of speaking English for five minutes every day.","zh":"我接受了每天說五分鐘英語的挑戰。"},{"en":"People often accept a challenge because they want to test themselves or build a new habit.","zh":"人們常因想考驗自己或建立新習慣而接受挑戰。"},{"en":"Accepting the challenge is only the first step; continuing when it becomes difficult matters more.","zh":"接受挑戰只是第一步；遇到困難時仍然堅持更加重要。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"the 21-day Gratitude Challenge","meaning":"二十一日感恩挑戰","examples":[{"en":"The 21-day Gratitude Challenge asked the writer to write about gratitude every night.","zh":"二十一日感恩挑戰要求作者每晚寫下值得感恩的事情。"},{"en":"The 21-day Gratitude Challenge was a three-week activity in which the writer recorded things to be thankful for.","zh":"二十一日感恩挑戰是一項為期三星期的活動，作者要記錄值得感謝的事。"},{"en":"During the 21-day Gratitude Challenge, I wrote a few lines before going to bed.","zh":"在二十一日感恩挑戰期間，我每晚睡前寫幾行字。"},{"en":"The daily routine made the 21-day Gratitude Challenge useful because it encouraged regular reflection.","zh":"每日例行的做法令二十一日感恩挑戰更有用，因為它鼓勵持續反思。"},{"en":"The 21-day Gratitude Challenge focused on noticing small positive moments rather than pretending every day was perfect.","zh":"二十一日感恩挑戰重點是留意細小的正面時刻，而不是假裝每天都完美。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"be tired of feeling as if","meaning":"厭倦了覺得好像","examples":[{"en":"I was tired of feeling as if everyone else was moving ahead.","zh":"我厭倦了覺得好像所有人都在向前走。"},{"en":"To be tired of feeling as if something is true means to be emotionally exhausted by a repeated impression or worry.","zh":"「厭倦了覺得好像……」指因反覆出現的感覺或憂慮而感到心累。"},{"en":"She was tired of feeling as if she had to please everyone.","zh":"她厭倦了覺得好像自己必須討好所有人。"},{"en":"I became tired of feeling as if one mistake meant I was a failure, so I changed how I judged myself.","zh":"我厭倦了覺得好像一次錯誤就代表失敗，所以改變了評價自己的方式。"},{"en":"When people are tired of feeling as if they are falling behind, they may decide to change their habits.","zh":"當人厭倦了覺得好像自己落後時，可能會決定改變習慣。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"move ahead","meaning":"向前走；取得進展","examples":[{"en":"Everyone else seemed to be moving ahead.","zh":"所有人似乎都在向前走。"},{"en":"To move ahead means to make progress towards a goal or a better position.","zh":"「向前走」指朝目標或更好的位置取得進展。"},{"en":"After practising regularly, she began to move ahead in mathematics.","zh":"持續練習後，她的數學開始取得進展。"},{"en":"A project can move ahead faster when everyone understands their responsibilities.","zh":"當每個人都明白自己的責任，項目可以更快向前推進。"},{"en":"Someone else moving ahead does not necessarily mean that you are falling behind.","zh":"別人向前走，不一定代表你正在落後。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"merely keeping up","meaning":"只是勉強跟上","examples":[{"en":"I felt as if I was merely keeping up.","zh":"我覺得自己只是在勉強跟上。"},{"en":"Merely keeping up means doing just enough to remain at the same level as others without feeling real progress.","zh":"「只是勉強跟上」指只做到足以維持與別人同一水平，卻感覺不到真正進步。"},{"en":"With homework arriving every day, I was merely keeping up instead of learning deeply.","zh":"每天都有功課來到時，我只是在勉強跟上，而沒有深入學習。"},{"en":"If a business spends all its time solving urgent problems, it may be merely keeping up rather than improving.","zh":"如果企業把所有時間都花在處理緊急問題上，它可能只是在勉強維持，而不是改善。"},{"en":"There is a difference between moving towards your own goal and merely keeping up with everyone else.","zh":"朝自己的目標前進與只是勉強跟上別人，是兩回事。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"write a journal entry","meaning":"寫日記","examples":[{"en":"I wrote a journal entry every night for three weeks.","zh":"我連續三星期每晚寫一篇日記。"},{"en":"To write a journal entry means to record your thoughts, experiences, or feelings for a particular day.","zh":"「寫日記」指記錄某一天的想法、經歷或感受。"},{"en":"After an argument with my friend, I wrote a journal entry about what had happened.","zh":"與朋友爭吵後，我寫了一篇日記記下發生的事。"},{"en":"Writing a journal entry can help people organise confusing thoughts because they have to put them into words.","zh":"寫日記可以幫助人整理混亂的想法，因為他們必須把想法化成文字。"},{"en":"A journal entry does not need to be long; a few honest sentences can be enough.","zh":"日記不需要很長；幾句真誠的說話也可以足夠。"}],"source":"2021 Q6.pdf","sourcePage":2},{"front":"every night for three weeks","meaning":"連續三星期每晚","examples":[{"en":"The writer wrote a journal entry every night for three weeks.","zh":"作者連續三星期每晚寫一篇日記。"},{"en":"“Every night for three weeks” means the action was repeated nightly throughout a continuous three-week period.","zh":"「連續三星期每晚」表示一個動作在完整的三星期內每晚重複。"},{"en":"I reviewed ten new words every night for three weeks before the test.","zh":"測驗前，我連續三星期每晚溫習十個新詞。"},{"en":"Doing something every night for three weeks can turn a new action into a more familiar routine.","zh":"連續三星期每晚做同一件事，可以令新行動逐漸變成熟悉習慣。"},{"en":"The phrase emphasises regular practice, not just doing something once or twice.","zh":"這個說法強調持續規律地做，而不是只做一兩次。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"hoped to slow down","meaning":"希望放慢腳步","examples":[{"en":"I hoped to slow down and notice what I still had.","zh":"我希望放慢腳步，留意自己仍然擁有的東西。"},{"en":"To hope to slow down means to want to reduce your pace so you have more time to think or notice things.","zh":"「希望放慢腳步」指希望降低生活節奏，讓自己有更多時間思考和留意事物。"},{"en":"During the holiday, I hoped to slow down instead of checking school messages all day.","zh":"假期期間，我希望放慢腳步，而不是整天查看學校訊息。"},{"en":"I hoped to slow down because rushing from task to task was making me tired.","zh":"我希望放慢腳步，因為不斷從一項任務趕到另一項令我很疲累。"},{"en":"Slowing down does not always mean doing less; it can mean paying more attention to what you are doing.","zh":"放慢腳步不一定代表少做事情，也可以表示更留心正在做的事。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"notice what I still had","meaning":"留意自己仍然擁有的東西","examples":[{"en":"The challenge helped me notice what I still had.","zh":"這個挑戰幫助我留意自己仍然擁有的東西。"},{"en":"To notice what I still had means to pay attention to the good things that remained instead of focusing only on what was missing.","zh":"「留意自己仍然擁有的東西」指不只專注失去或缺少的事，而是注意仍然存在的美好。"},{"en":"After losing the competition, I tried to notice what I still had: supportive friends and another chance to improve.","zh":"比賽落敗後，我嘗試留意自己仍然擁有的東西：支持我的朋友，以及再次進步的機會。"},{"en":"Noticing what I still had reduced my disappointment because the difficult event no longer filled the whole picture.","zh":"留意自己仍然擁有的東西減輕了我的失望，因為困難的事情不再佔據整個畫面。"},{"en":"A bad day becomes easier to understand when I notice what I still had as well as what went wrong.","zh":"當我同時留意自己仍然擁有的東西和出了甚麼問題，艱難的一天會較容易理解。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"become less trapped by comparison","meaning":"不再那麼困於比較之中","examples":[{"en":"I wanted to become less trapped by comparison.","zh":"我希望不再那麼困於比較之中。"},{"en":"To become less trapped by comparison means to stop letting constant comparisons with others control your confidence or choices.","zh":"「不再那麼困於比較之中」指不再讓不斷與別人比較控制自己的自信或選擇。"},{"en":"I became less trapped by comparison when I started judging my progress against my own past work.","zh":"當我開始把現在的進度與自己過去的表現比較時，我便不再那麼困於比較之中。"},{"en":"Limiting social media helped me become less trapped by comparison because I saw fewer carefully selected highlights.","zh":"減少使用社交媒體幫助我不再那麼困於比較之中，因為我少看了別人刻意挑選的精彩片段。"},{"en":"Becoming less trapped by comparison does not mean never noticing others; it means their success no longer decides your worth.","zh":"不再那麼困於比較並不代表完全不看別人，而是別人的成功不再決定你的價值。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"trapped by comparison","meaning":"被比較困住","examples":[{"en":"The writer felt trapped by comparison before the challenge.","zh":"挑戰開始前，作者覺得自己被比較困住。"},{"en":"Being trapped by comparison means repeatedly judging yourself against others until it becomes difficult to feel satisfied.","zh":"「被比較困住」指不斷拿自己與別人相比，以致很難對自己感到滿足。"},{"en":"A student may feel trapped by comparison if every classmate’s high mark makes her question her own ability.","zh":"如果每次同學取得高分都令一名學生懷疑自己的能力，她可能會覺得被比較困住。"},{"en":"Social media can leave people trapped by comparison when they constantly see other people’s best moments.","zh":"當人們不斷看到別人最精彩的時刻，社交媒體可能令他們被比較困住。"},{"en":"Setting personal goals can help someone feel less trapped by comparison.","zh":"設定個人目標可以幫助人減少被比較困住的感覺。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"looking back","meaning":"回望起來","examples":[{"en":"Looking back, I would say the challenge made me more attentive.","zh":"回望起來，我會說這個挑戰令我變得更懂得留意。"},{"en":"“Looking back” means thinking about a past experience from your present point of view.","zh":"「回望起來」指從現在的角度重新思考過去的經歷。"},{"en":"Looking back, I understand why my parents worried when I came home late.","zh":"回望起來，我明白父母為何在我很晚回家時擔心。"},{"en":"Looking back can change our judgement because we now know what happened afterwards.","zh":"回望過去可能改變我們的判斷，因為現在已知道後來發生了甚麼。"},{"en":"We often use “looking back” before explaining what we learned from the past.","zh":"我們常在說明從過去學到甚麼之前使用「回望起來」。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"turn me into","meaning":"把我變成","examples":[{"en":"The challenge did not turn me into a completely different person.","zh":"這個挑戰沒有把我變成一個完全不同的人。"},{"en":"To turn me into something means to change me so that I become a different kind of person or thing.","zh":"「把我變成……」指令我改變，成為另一種人或狀態。"},{"en":"Regular practice did not turn me into an expert, but it made me more confident.","zh":"持續練習沒有把我變成專家，但令我更有信心。"},{"en":"A difficult experience can turn me into a more patient person if I learn from it.","zh":"如果我從困難經歷中學習，它可以把我變成一個更有耐性的人。"},{"en":"Real change does not have to turn me into somebody completely new.","zh":"真正的改變不一定要把我變成一個完全不同的人。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"a completely different person","meaning":"一個完全不同的人","examples":[{"en":"The challenge did not make the writer a completely different person.","zh":"這個挑戰沒有令作者變成一個完全不同的人。"},{"en":"A completely different person would have very different habits, attitudes, or behaviour from before.","zh":"「一個完全不同的人」是指習慣、態度或行為都與以前有很大差異的人。"},{"en":"Moving abroad did not make him a completely different person; he still valued the same friendships.","zh":"搬到外國沒有令他變成一個完全不同的人；他仍然珍惜同樣的友誼。"},{"en":"People usually change gradually, so one experience rarely creates a completely different person overnight.","zh":"人通常逐漸改變，所以一次經歷很少會在一夜之間造就一個完全不同的人。"},{"en":"Improvement can matter even when you do not become a completely different person.","zh":"即使你沒有變成一個完全不同的人，進步仍然可以很有意義。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"did something better","meaning":"做到更好的事","examples":[{"en":"The challenge did something better than changing the writer completely.","zh":"這個挑戰做到了一件比徹底改變作者更好的事。"},{"en":"“Did something better” means produced a result that was more useful or valuable than another possible result.","zh":"「做到更好的事」表示產生了一個比另一種可能結果更有用或更有價值的結果。"},{"en":"The teacher did something better than simply giving me the answer: she showed me how to find it myself.","zh":"老師做了一件比直接給我答案更好的事：她教我自己找答案。"},{"en":"Instead of making the problem disappear, the conversation did something better by helping us understand each other.","zh":"那次對話沒有令問題消失，卻做到更好的事，幫助我們互相理解。"},{"en":"Sometimes a small lasting improvement has done something better than a dramatic short-term change.","zh":"有時，細小但持久的進步比戲劇性卻短暫的改變做到更好的事。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"a more attentive one","meaning":"一個更懂得留意的人","examples":[{"en":"The challenge made the writer a more attentive person.","zh":"這個挑戰令作者成為一個更懂得留意的人。"},{"en":"A more attentive person notices details, people’s needs, and small changes more carefully than before.","zh":"一個更懂得留意的人，會比以前更仔細察覺細節、別人的需要和小變化。"},{"en":"Keeping a journal made me a more attentive one because I started noticing ordinary acts of kindness.","zh":"寫日記令我成為一個更懂得留意的人，因為我開始注意平凡的善意。"},{"en":"Listening without checking my phone helped me become a more attentive friend.","zh":"聆聽別人時不查看電話，幫助我成為一個更留心的朋友。"},{"en":"Becoming a more attentive one can improve relationships because people feel noticed and valued.","zh":"成為一個更懂得留意的人可以改善關係，因為別人會感到被看見和重視。"}],"source":"2021 Q6.pdf","sourcePage":3},{"front":"at first","meaning":"起初","examples":[{"en":"At first, I treated the journal like homework.","zh":"起初，我把這本日記當成功課。"},{"en":"“At first” refers to the beginning of a situation before feelings, knowledge, or conditions later change.","zh":"「起初」指一件事情的開始階段，之後感受、理解或情況可能會改變。"},{"en":"At first, the new school felt confusing, but I soon learned my way around.","zh":"起初，新學校令人感到混亂，但我很快便熟悉環境。"},{"en":"A task may seem difficult at first because the method is still unfamiliar.","zh":"一項任務起初可能很困難，因為方法仍然陌生。"},{"en":"“At first” often prepares the reader for a contrast with what happened later.","zh":"「起初」常用來引出後來發生的轉變。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"treat something like homework","meaning":"把某事當成功課","examples":[{"en":"I treated the gratitude journal like homework.","zh":"我把感恩日記當成功課。"},{"en":"To treat something like homework means to do it mainly because you feel you must, rather than because you are personally interested.","zh":"「把某事當成功課」指主要因為覺得必須做而去做，而不是出於真正興趣。"},{"en":"He treated piano practice like homework and only watched the clock until it ended.","zh":"他把練琴當成功課，只是不斷看時間等它結束。"},{"en":"If you treat every hobby like homework, it may stop feeling enjoyable.","zh":"如果你把每個興趣都當成功課，它可能不再令人享受。"},{"en":"An activity can become more meaningful once you stop treating it like homework and understand its purpose.","zh":"當你不再把活動當成功課，而是明白它的目的時，它可能變得更有意義。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"write down","meaning":"寫下","examples":[{"en":"On Day 1, I wrote down the obvious things.","zh":"第一天，我寫下那些顯而易見的事情。"},{"en":"To write something down means to record it in writing so you can remember or examine it later.","zh":"「寫下」指把某件事記錄成文字，以便之後記住或查看。"},{"en":"Please write down the homework before you leave the classroom.","zh":"離開課室前，請寫下功課。"},{"en":"Writing an idea down can make it easier to organise because it is no longer only in your head.","zh":"把想法寫下來可以令它更容易整理，因為它不再只存在腦中。"},{"en":"If something is important, write it down instead of trusting your memory alone.","zh":"如果事情重要，最好寫下來，不要只依賴記憶。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"the obvious things","meaning":"顯而易見的事情","examples":[{"en":"I wrote down the obvious things, such as family, health and friends.","zh":"我寫下那些顯而易見的事情，例如家人、健康和朋友。"},{"en":"The obvious things are the answers or facts that come to mind immediately because they seem clear and expected.","zh":"「顯而易見的事情」是因為清楚而且符合預期，所以立即想到的答案或事實。"},{"en":"When packing for school, the obvious things are books, pens, and your student card.","zh":"為上學收拾物品時，顯而易見的事情包括書本、筆和學生證。"},{"en":"Focusing only on the obvious things can make us miss smaller details that also matter.","zh":"如果只注意顯而易見的事情，我們可能忽略同樣重要的小細節。"},{"en":"The obvious things are often a useful starting point, but deeper thinking may reveal more.","zh":"顯而易見的事情常是很好的起點，但深入思考可能讓我們發現更多。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"felt distant","meaning":"感覺遙遠；不貼近自己","examples":[{"en":"The words felt distant, almost copied from a poster.","zh":"那些字感覺很遙遠，幾乎像從海報抄來的一樣。"},{"en":"If words felt distant, they did not seem personally connected to the speaker’s real feelings or experience.","zh":"如果說話「感覺遙遠」，就是它與說話者真正的感受或經歷沒有很強的個人連繫。"},{"en":"The formal apology felt distant because it sounded like something written by a company rather than a friend.","zh":"那封正式道歉感覺很疏離，因為它像公司寫的文字，而不像朋友說的話。"},{"en":"A lesson may feel distant when students cannot connect it with anything in their own lives.","zh":"當學生不能把課堂內容與自己的生活連結時，那一課可能感覺很遙遠。"},{"en":"Personal details can make an idea feel less distant and more real.","zh":"個人細節可以令一個想法不再那麼遙遠，變得更真實。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"almost copied from","meaning":"像是從……抄來","examples":[{"en":"The words felt almost copied from a moral education poster.","zh":"那些字感覺幾乎像是從德育海報抄來。"},{"en":"“Almost copied from” means something sounds so similar to another source that it hardly feels original or personal.","zh":"「像是從……抄來」表示某些內容與另一來源非常相似，因此幾乎沒有原創或個人感覺。"},{"en":"His speech sounded almost copied from the school website because he used exactly the same phrases.","zh":"他的演講聽起來幾乎像從學校網站抄來，因為用了完全相同的字句。"},{"en":"If an answer is almost copied from a textbook, it may not show the student’s own understanding.","zh":"如果答案幾乎像從課本抄來，可能不能展示學生自己的理解。"},{"en":"Adding real experience can stop writing from sounding almost copied from a model answer.","zh":"加入真實經歷，可以避免文章聽起來像從範文抄來。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"a moral education poster","meaning":"德育海報","examples":[{"en":"The first journal entry sounded like a moral education poster.","zh":"第一篇日記聽起來像一張德育海報。"},{"en":"A moral education poster is a school or public poster that gives simple messages about good behaviour or values.","zh":"德育海報是學校或公共地方用來宣傳良好行為或價值觀的簡單海報。"},{"en":"A moral education poster might remind students to respect others or care for the community.","zh":"德育海報可能提醒學生尊重別人或關心社區。"},{"en":"Because moral education posters often use short general messages, personal writing can sound artificial if it copies their style.","zh":"由於德育海報常使用簡短而普遍的訊息，如果個人文章模仿這種風格，可能會顯得不自然。"},{"en":"A journal should express genuine experience rather than simply sound like a moral education poster.","zh":"日記應表達真實經歷，而不應只是聽起來像德育海報。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"began to understand the point","meaning":"開始明白重點","examples":[{"en":"By Day 4, I began to understand the point of the challenge.","zh":"到第四天，我開始明白這個挑戰的重點。"},{"en":"To begin to understand the point means to start seeing the real purpose or reason behind something.","zh":"「開始明白重點」指開始看見某件事背後真正的目的或理由。"},{"en":"After practising the exercise several times, I began to understand the point of doing it slowly.","zh":"練習那個動作幾次後，我開始明白為何要慢慢做。"},{"en":"I began to understand the point when I saw how the new habit affected my daily choices.","zh":"當我看見新習慣如何影響日常選擇時，我開始明白重點。"},{"en":"People often resist an activity until they begin to understand the point of it.","zh":"人們常在開始明白一項活動的重點之前對它有所抗拒。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"not just about","meaning":"不只是關於……","examples":[{"en":"Gratitude is not just about naming the big blessings.","zh":"感恩不只是關於說出重大的福氣。"},{"en":"“Not just about” shows that a subject includes more than the first idea mentioned.","zh":"「不只是關於……」表示一個主題所包含的內容比首先提到的概念更多。"},{"en":"School is not just about getting high marks; it is also about learning how to think and work with others.","zh":"上學不只是關於取得高分，也包括學習思考和與人合作。"},{"en":"Exercise is not just about appearance because it can also improve strength, sleep, and mood.","zh":"運動不只是關於外表，因為它也可以改善體力、睡眠和心情。"},{"en":"Using “not just about” helps expand an idea beyond an overly narrow view.","zh":"使用「不只是關於……」可以把想法從過分狹窄的理解中擴闊。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"big blessings","meaning":"重大的福氣","examples":[{"en":"Gratitude is not only about naming the big blessings.","zh":"感恩不只是說出重大的福氣。"},{"en":"Big blessings are major good things in life, such as health, loving relationships, safety, or an important opportunity.","zh":"「重大的福氣」指人生中重要的好事，例如健康、充滿愛的關係、安全或重要機會。"},{"en":"Having a supportive family may be one of the big blessings a person appreciates.","zh":"擁有支持自己的家庭，可能是一個人珍惜的重大福氣之一。"},{"en":"If we notice only big blessings, we may overlook small acts of kindness that happen every day.","zh":"如果只留意重大的福氣，我們可能忽略每天出現的小小善意。"},{"en":"Gratitude can include both big blessings and ordinary moments.","zh":"感恩可以包括重大的福氣，也可以包括平凡時刻。"}],"source":"2021 Q6.pdf","sourcePage":4},{"front":"train your eyes to","meaning":"訓練自己去留意","examples":[{"en":"Gratitude trains your eyes to catch small blessings.","zh":"感恩訓練自己去留意小小的福氣。"},{"en":"To train your eyes to notice something means to practise paying attention until you begin to see details more easily.","zh":"「訓練自己去留意……」指反覆練習專注，直到更容易察覺某些細節。"},{"en":"Photography can train your eyes to notice light, shape, and colour in ordinary streets.","zh":"攝影可以訓練自己去留意普通街道中的光線、形狀和顏色。"},{"en":"Keeping a spending record can train your eyes to notice where small amounts of money disappear.","zh":"記錄開支可以訓練自己去留意小額金錢去了哪裏。"},{"en":"You can train your eyes to notice kindness by deliberately looking for it each day.","zh":"你可以每天刻意尋找善意，訓練自己去留意它。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"catch the small ones","meaning":"捕捉那些小小的事物","examples":[{"en":"Gratitude helps you catch the small blessings before they disappear.","zh":"感恩幫助你在小小的福氣消失前捕捉它們。"},{"en":"To catch the small ones means to notice small positive moments before they pass unnoticed.","zh":"「捕捉那些小小的事物」指在細小的正面時刻悄悄過去前留意它們。"},{"en":"A warm message or someone saving you a seat is easy to miss, so try to catch the small ones.","zh":"一句溫暖的訊息或有人替你留座都很容易被忽略，所以要嘗試捕捉那些小小的事物。"},{"en":"Writing at the end of the day helped me catch the small ones because I had to search my memory carefully.","zh":"每天結束時寫下事情幫助我捕捉小事，因為我必須仔細回想。"},{"en":"Big events are easy to remember; gratitude teaches us to catch the small ones too.","zh":"大事很容易記住；感恩也教我們捕捉那些小小的事物。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"before they disappear","meaning":"在它們消失之前","examples":[{"en":"I learned to notice small blessings before they disappeared.","zh":"我學會在小小的福氣消失之前留意它們。"},{"en":"“Before they disappear” means while the moments or opportunities are still present and can still be noticed.","zh":"「在它們消失之前」表示在那些時刻或機會仍然存在、仍能被察覺的時候。"},{"en":"Take a photo of the chalk drawing before it disappears in the rain.","zh":"在粉筆畫被雨水沖走之前，先拍張照片吧。"},{"en":"Small moments are easy to forget, so writing them down before they disappear from memory can preserve them.","zh":"小小的時刻很容易被忘記，所以在它們從記憶中消失前寫下來，可以把它們保存。"},{"en":"Appreciating people before opportunities disappear can prevent later regret.","zh":"在機會消失前珍惜身邊的人，可以減少日後的後悔。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"hold the lift for someone","meaning":"替某人按住升降機","examples":[{"en":"The security guard held the lift for me when I was late.","zh":"當我遲到時，保安員替我按住升降機。"},{"en":"To hold the lift for someone means to keep the lift door open so that the person has time to enter.","zh":"「替某人按住升降機」指讓升降機門保持開啟，使對方有時間進去。"},{"en":"A neighbour held the lift for an elderly man carrying several shopping bags.","zh":"一名鄰居替一位拿着幾袋購物袋的老人按住升降機。"},{"en":"Holding the lift for someone takes only a few seconds but can save them a long wait.","zh":"替某人按住升降機只花幾秒，卻可能令對方不用等很久。"},{"en":"Small actions such as holding the lift for someone can make a busy day feel kinder.","zh":"替某人按住升降機這類小行動，可以令繁忙的一天多一點善意。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"when I was late","meaning":"當我遲到時","examples":[{"en":"The security guard helped me when I was late.","zh":"當我遲到時，保安員幫了我。"},{"en":"“When I was late” refers to a time when I had not arrived by the expected or required time.","zh":"「當我遲到時」指我沒有在預期或規定時間到達的時候。"},{"en":"My teacher let me enter quietly when I was late because the bus had broken down.","zh":"當我因巴士故障而遲到時，老師讓我安靜地進入課室。"},{"en":"When I was late, I rushed and became more stressed, so I started leaving home earlier.","zh":"當我遲到時，我會趕得更急和更緊張，所以後來開始提早出門。"},{"en":"How people treat us when we are late can make an already difficult moment better or worse.","zh":"當我們遲到時，別人如何對待我們可以令本來已困難的時刻變得好一點或更糟。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"a bowl of hot noodles","meaning":"一碗熱湯麵","examples":[{"en":"My mother left a bowl of hot noodles on the table.","zh":"媽媽在桌上留了一碗熱湯麵給我。"},{"en":"A bowl of hot noodles is a simple warm meal served in a bowl, often comforting when someone is hungry or tired.","zh":"一碗熱湯麵是一份用碗盛着的簡單熱食，在人肚餓或疲累時常令人感到安慰。"},{"en":"After evening practice, I came home to a bowl of hot noodles prepared by my father.","zh":"晚上練習後，我回家看見爸爸準備的一碗熱湯麵。"},{"en":"A bowl of hot noodles may seem ordinary, but preparing it for someone can show quiet care.","zh":"一碗熱湯麵可能很普通，但為某人準備它可以表達默默的關心。"},{"en":"Sometimes a bowl of hot noodles means more than an expensive gift because it arrives exactly when you need it.","zh":"有時，一碗熱湯麵比昂貴禮物更有意義，因為它剛好在你需要時出現。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"leave something on the table","meaning":"把某物放在桌上","examples":[{"en":"My mother left a bowl of hot noodles on the table.","zh":"媽媽把一碗熱湯麵放在桌上留給我。"},{"en":"To leave something on the table means to put it there and let it remain for someone to find or use later.","zh":"「把某物放在桌上」指把東西放在那裏，讓它留待別人之後找到或使用。"},{"en":"Please leave the library books on the table so I remember to return them.","zh":"請把圖書館的書放在桌上，好讓我記得歸還。"},{"en":"My father left my medicine on the table because he knew I might forget it.","zh":"爸爸把我的藥放在桌上，因為他知道我可能會忘記。"},{"en":"What someone leaves on the table can sometimes be a practical way of showing care.","zh":"有時，別人留在桌上的東西也是一種實際表達關心的方法。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"send me notes","meaning":"傳筆記給我","examples":[{"en":"A classmate sent me notes when I was absent.","zh":"我缺席時，一位同學傳筆記給我。"},{"en":"To send me notes means to give me written information, often from a lesson or meeting that I missed.","zh":"「傳筆記給我」指把書面資料給我，通常是我錯過的課堂或會議內容。"},{"en":"My friend sent me notes from the history lesson while I was at the dentist.","zh":"我去看牙醫時，朋友把歷史課筆記傳給我。"},{"en":"When classmates send me notes, I can catch up more easily after missing school.","zh":"同學傳筆記給我後，我缺課後可以較容易追回進度。"},{"en":"Sending someone notes is a simple way to help without doing their work for them.","zh":"把筆記傳給別人是一種簡單的幫助方式，又不等於替對方完成工作。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"without making me feel guilty","meaning":"沒有令我感到內疚","examples":[{"en":"My classmate sent me notes without making me feel guilty.","zh":"同學把筆記傳給我，沒有令我感到內疚。"},{"en":"“Without making me feel guilty” means helping or speaking to me without causing me to feel ashamed or responsible for doing something wrong.","zh":"「沒有令我感到內疚」指幫助我或與我說話時，沒有令我因某件事感到羞愧或自責。"},{"en":"My sister reminded me about the broken cup without making me feel guilty about the accident.","zh":"姊姊提醒我打破杯子的事，但沒有令我因意外而感到內疚。"},{"en":"Advice is easier to accept when someone gives it without making me feel guilty.","zh":"當別人給意見而沒有令我感到內疚時，意見通常更容易接受。"},{"en":"Good support can correct a problem without making me feel guilty or small.","zh":"好的支持可以指出問題，而不令我感到內疚或渺小。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"feel guilty for","meaning":"因……而感到內疚","examples":[{"en":"I did not feel guilty for being absent.","zh":"我沒有因缺席而感到內疚。"},{"en":"To feel guilty for something means to feel bad because you believe you did something wrong or caused a problem.","zh":"「因……而感到內疚」指因相信自己做錯了事或造成問題而感到難受。"},{"en":"She felt guilty for forgetting her friend’s birthday.","zh":"她因忘記朋友的生日而感到內疚。"},{"en":"People may feel guilty for resting if they wrongly believe they should always be productive.","zh":"如果人錯誤地認為自己應該一直有生產力，休息時也可能感到內疚。"},{"en":"You do not need to feel guilty for something that was outside your control.","zh":"對於超出自己控制的事情，你不需要感到內疚。"}],"source":"2021 Q6.pdf","sourcePage":5},{"front":"being absent","meaning":"缺席","examples":[{"en":"My classmate helped me when I was absent.","zh":"我缺席時，同學幫了我。"},{"en":"Being absent means not being present at a place where you were expected to be, such as school or work.","zh":"「缺席」指沒有出現在原本應該出席的地方，例如學校或工作場所。"},{"en":"Being absent from one lesson meant I had to ask what homework had been set.","zh":"缺席一堂課令我需要問別人老師布置了甚麼功課。"},{"en":"Being absent repeatedly can make it harder to follow a course because important explanations are missed.","zh":"經常缺席會令跟上課程變得更困難，因為會錯過重要解釋。"},{"en":"Being absent for a good reason is different from simply choosing not to attend.","zh":"因合理原因缺席，與單純選擇不出席並不一樣。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"none of these moments","meaning":"這些時刻都不是","examples":[{"en":"None of these moments was dramatic.","zh":"這些時刻都不是戲劇性的。"},{"en":"“None of these moments” means not one of the experiences being discussed had a particular quality.","zh":"「這些時刻都不是……」表示所談到的經歷中沒有任何一個具有某種特質。"},{"en":"None of these moments cost much money, but I remembered all of them.","zh":"這些時刻都沒有花很多錢，但我全部都記得。"},{"en":"None of these moments seemed important at the time, yet recording them changed how I saw the day.","zh":"這些時刻當時都不像很重要，但記錄它們改變了我看待那一天的方式。"},{"en":"None of these moments was extraordinary; their value came from ordinary kindness.","zh":"這些時刻都不是非凡的大事；它們的價值來自平凡的善意。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"recording them","meaning":"把它們記錄下來","examples":[{"en":"Recording these moments gave them weight.","zh":"把這些時刻記錄下來，令它們變得有分量。"},{"en":"Recording them means writing down, photographing, or otherwise keeping a record of those experiences.","zh":"「把它們記錄下來」指用文字、照片或其他方式保存那些經歷。"},{"en":"I started recording them in a small notebook so I would not forget the good moments.","zh":"我開始把它們記錄在一本小筆記簿中，以免忘記那些美好時刻。"},{"en":"Recording them made ordinary events easier to remember because I had deliberately paid attention.","zh":"把它們記錄下來令普通事情更容易記住，因為我曾刻意留心。"},{"en":"Experiences can pass quickly, but recording them allows us to return to them later.","zh":"經歷可以很快過去，但把它們記錄下來，讓我們日後仍可以回看。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"give something weight","meaning":"令某事變得有分量","examples":[{"en":"Recording small moments gave them weight.","zh":"記錄小小的時刻令它們變得有分量。"},{"en":"To give something weight means to make it seem more important, serious, or worthy of attention.","zh":"「令某事變得有分量」指令某事顯得更重要、更嚴肅或更值得留意。"},{"en":"Hearing the patient’s own story gave the statistics more weight.","zh":"聽到病人的親身故事，令那些統計數字更有分量。"},{"en":"Writing my promise down gave it weight because I could no longer pretend I had forgotten it.","zh":"把承諾寫下來令它變得有分量，因為我不能再假裝忘記了。"},{"en":"Small experiences can gain meaning when we give them weight through careful attention.","zh":"當我們仔細留意，小小的經歷也可以變得更有意義和分量。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"little by little","meaning":"漸漸地","examples":[{"en":"Little by little, my day no longer looked like a list of problems.","zh":"漸漸地，我的一天不再看起來像一連串問題。"},{"en":"“Little by little” means gradually, through many small changes rather than one sudden change.","zh":"「漸漸地」指透過許多細小改變逐步發生，而不是突然一下子改變。"},{"en":"Little by little, the shy student became comfortable speaking in class.","zh":"漸漸地，那位害羞的學生開始敢於在課堂上發言。"},{"en":"Saving a small amount each week can build a useful fund little by little.","zh":"每星期儲一小筆錢，可以漸漸地建立一筆有用的儲蓄。"},{"en":"Habits usually change little by little, so slow progress still counts.","zh":"習慣通常是漸漸改變的，所以緩慢的進步仍然是進步。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"no longer looked like","meaning":"不再看起來像","examples":[{"en":"My day no longer looked like a list of problems.","zh":"我的一天不再看起來像一連串問題。"},{"en":"“No longer looked like” means something stopped appearing or seeming the way it had before.","zh":"「不再看起來像……」表示某事停止呈現或給人以前那種感覺。"},{"en":"After we added plants and better lighting, the room no longer looked like an empty office.","zh":"加入植物和更好的燈光後，房間不再看起來像一間空辦公室。"},{"en":"Once I understood the instructions, the project no longer looked like an impossible task.","zh":"當我明白指示後，那個項目不再看起來像不可能完成的任務。"},{"en":"A situation may be the same, yet it no longer looks like the same thing when our perspective changes.","zh":"情況本身可能沒有改變，但當觀點改變時，它可能不再看起來一樣。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"a list of problems","meaning":"一連串問題","examples":[{"en":"My day no longer looked like a list of problems.","zh":"我的一天不再看起來像一連串問題。"},{"en":"A list of problems means a series of difficulties seen one after another, with little attention to anything positive.","zh":"「一連串問題」指一個接一個的困難，而幾乎沒有留意任何正面的事情。"},{"en":"When I was stressed, Monday felt like a list of problems: a late bus, unfinished work, and a headache.","zh":"當我壓力很大時，星期一就像一連串問題：巴士遲到、工作未完成，還有頭痛。"},{"en":"If we view every day only as a list of problems, small successes can become invisible.","zh":"如果我們只把每天看成一連串問題，小小的成功也可能變得看不見。"},{"en":"Problems are real, but a day can contain more than a list of problems.","zh":"問題是真實存在的，但一天所包含的並不只是一連串問題。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"a collection of","meaning":"一組；一系列","examples":[{"en":"My day looked like a collection of quiet gifts.","zh":"我的一天看起來像一系列靜靜出現的禮物。"},{"en":"“A collection of” means a group of several things considered together.","zh":"「一系列……」指把幾件不同事物放在一起看待的一組東西。"},{"en":"Her desk held a collection of postcards from different countries.","zh":"她的書桌上有一系列來自不同國家的明信片。"},{"en":"A neighbourhood is a collection of homes, shops, streets, and shared memories.","zh":"一個社區是一系列住宅、商店、街道和共同記憶的組合。"},{"en":"Seeing a day as a collection of moments can help us notice more than one dominant feeling.","zh":"把一天看成一系列時刻，可以幫助我們留意超越單一情緒的事情。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"quiet gifts","meaning":"靜靜出現的禮物","examples":[{"en":"My day began to look like a collection of quiet gifts.","zh":"我的一天開始像是一系列靜靜出現的禮物。"},{"en":"Quiet gifts are small good things that arrive without drama, such as help, comfort, or kindness.","zh":"「靜靜出現的禮物」指沒有戲劇性地出現的小小好事，例如幫助、安慰或善意。"},{"en":"A seat offered on a crowded bus can feel like one of the day’s quiet gifts.","zh":"在擠迫巴士上有人讓座，也可以像一天中的一份靜靜出現的禮物。"},{"en":"Quiet gifts are easy to miss because they rarely demand attention.","zh":"靜靜出現的禮物很容易被忽略，因為它們很少吸引注意。"},{"en":"Noticing quiet gifts can make an ordinary day feel richer without pretending it was perfect.","zh":"留意這些靜靜出現的禮物，可以令普通的一天更豐富，而不需要假裝它很完美。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"the second week","meaning":"第二星期","examples":[{"en":"The second week was harder and more honest.","zh":"第二星期更困難，也更真實。"},{"en":"The second week means the seven-day period after the first week and before the third.","zh":"「第二星期」指第一星期之後、第三星期之前的七天。"},{"en":"During the second week of the course, we started doing more difficult exercises.","zh":"課程的第二星期，我們開始做更困難的練習。"},{"en":"The second week often felt harder because the excitement of beginning had disappeared.","zh":"第二星期常感覺更難，因為開始時的新鮮感已經消失。"},{"en":"Progress in the second week may reveal whether a new habit can survive after the first enthusiasm fades.","zh":"第二星期的表現可能顯示一個新習慣能否在最初熱情減退後繼續。"}],"source":"2021 Q6.pdf","sourcePage":6},{"front":"for that reason","meaning":"正因如此","examples":[{"en":"The second week was harder and, for that reason, more honest.","zh":"第二星期更困難，正因如此，也更真實。"},{"en":"“For that reason” means because of the fact or situation just mentioned.","zh":"「正因如此」表示因為剛剛提到的事實或情況。"},{"en":"The road was flooded; for that reason, the school bus arrived late.","zh":"道路水浸；正因如此，校巴遲到了。"},{"en":"I had little time to prepare and, for that reason, kept my presentation simple.","zh":"我準備時間很少，正因如此，我把簡報保持簡單。"},{"en":"“For that reason” clearly links a cause with the result that follows.","zh":"「正因如此」清楚連接前面的原因和後面的結果。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"more honest","meaning":"更真實；更坦誠","examples":[{"en":"The harder second week felt more honest.","zh":"較困難的第二星期感覺更真實。"},{"en":"“More honest” means more truthful and closer to what someone actually thinks or feels.","zh":"「更真實／更坦誠」表示更加符合某人真正的想法或感受。"},{"en":"Her second answer was more honest because she admitted that she was afraid.","zh":"她第二次的回答更坦誠，因為她承認自己害怕。"},{"en":"Writing became more honest when I stopped trying to make every day sound positive.","zh":"當我不再嘗試令每天聽起來都很正面時，文章變得更真實。"},{"en":"A more honest reflection can include disappointment as well as gratitude.","zh":"更真實的反思可以同時包括失望和感恩。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"lose my temper at","meaning":"對……發脾氣","examples":[{"en":"I lost my temper at my younger brother over a small matter.","zh":"我因一件小事對弟弟發了脾氣。"},{"en":"To lose my temper at someone means to suddenly become angry with that person and show it strongly.","zh":"「對某人發脾氣」指突然對那個人生氣，並強烈表現出來。"},{"en":"I lost my temper at a classmate after he repeatedly interrupted me.","zh":"一位同學不斷打斷我後，我對他發了脾氣。"},{"en":"Lack of sleep can make me more likely to lose my temper at people over small mistakes.","zh":"睡眠不足可能令我更容易因小錯誤而對人發脾氣。"},{"en":"If I lose my temper at someone, I may need to apologise after I calm down.","zh":"如果我對某人發了脾氣，冷靜後可能需要道歉。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"over something small","meaning":"因一件小事","examples":[{"en":"I lost my temper over something embarrassingly small.","zh":"我因一件小得令人尷尬的事發了脾氣。"},{"en":"“Over something small” means because of a minor issue that does not seem serious enough to justify a strong reaction.","zh":"「因一件小事」表示因為一個並不嚴重、不太值得強烈反應的小問題。"},{"en":"The two friends argued over something small: who should sit by the window.","zh":"兩個朋友因一件小事爭吵：誰坐窗邊。"},{"en":"Stress can make people become angry over something small because they are already emotionally tired.","zh":"壓力可能令人因一件小事生氣，因為他們本來已經很疲累。"},{"en":"Before reacting over something small, it can help to ask whether the issue will matter tomorrow.","zh":"因小事作出反應前，可以先問自己這件事明天是否仍然重要。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"embarrassingly small","meaning":"小得令人尷尬","examples":[{"en":"The argument was about something embarrassingly small.","zh":"那場爭吵只是因為一件小得令人尷尬的事情。"},{"en":"“Embarrassingly small” describes an issue so minor that you may later feel ashamed that it caused such a strong reaction.","zh":"「小得令人尷尬」形容問題非常微小，以致之後可能會因自己反應太大而感到不好意思。"},{"en":"We had an embarrassingly small disagreement about whose turn it was to wash a cup.","zh":"我們因為輪到誰洗一隻杯而發生了一場小得令人尷尬的爭執。"},{"en":"When stress is high, an embarrassingly small problem can trigger a surprisingly large argument.","zh":"壓力很大時，一個小得令人尷尬的問題也可能引發很大的爭吵。"},{"en":"Calling something embarrassingly small shows that the speaker now sees the reaction as excessive.","zh":"說某事「小得令人尷尬」，表示說話者現在認為當時的反應過度了。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"essentially","meaning":"基本上；實際上","examples":[{"en":"Essentially, he had borrowed my charger without asking.","zh":"基本上，他只是未經同意借了我的充電器。"},{"en":"“Essentially” means when unnecessary details are removed, this is the main or basic truth of the situation.","zh":"「基本上」表示除去不必要的細節後，這就是事情最主要或最基本的事實。"},{"en":"The two plans look different, but essentially they solve the same problem.","zh":"兩個計劃看起來不同，但基本上都在解決同一個問題。"},{"en":"The meeting lasted an hour, but essentially the manager wanted everyone to communicate earlier.","zh":"會議開了一小時，但基本上經理只是希望大家更早溝通。"},{"en":"“Essentially” helps simplify a complicated situation to its central point.","zh":"「基本上」可以把複雜情況簡化成最核心的重點。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"borrow something without asking","meaning":"未經同意借走某物","examples":[{"en":"He had borrowed my charger without asking.","zh":"他未經同意借走了我的充電器。"},{"en":"To borrow something without asking means to take and use another person’s property temporarily without first getting permission.","zh":"「未經同意借走某物」指沒有先取得許可，便暫時拿取和使用別人的東西。"},{"en":"My brother borrowed my headphones without asking and returned them later.","zh":"弟弟未經同意借走我的耳機，之後才還給我。"},{"en":"Borrowing something without asking can cause arguments because the owner may need it or feel disrespected.","zh":"未經同意借東西可能引起爭吵，因為物主可能需要它，或覺得不受尊重。"},{"en":"Even if you plan to return an item, you should ask before borrowing it.","zh":"即使你打算歸還，也應該先問過才借別人的東西。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"my first instinct","meaning":"我的第一反應","examples":[{"en":"My first instinct was to write that there was nothing to be grateful for.","zh":"我的第一反應是寫下那天沒有甚麼值得感恩。"},{"en":"My first instinct is my immediate natural reaction before I have time to think carefully.","zh":"「我的第一反應」指在有時間仔細思考之前，自然而立即出現的反應。"},{"en":"My first instinct was to refuse the invitation, but I decided to consider it overnight.","zh":"我的第一反應是拒絕邀請，但我決定想一晚再說。"},{"en":"When someone criticises me, my first instinct may be to defend myself even before I understand the comment.","zh":"當別人批評我時，我的第一反應可能是自我辯護，甚至還未理解對方的意思。"},{"en":"My first instinct can be useful, but it is not always my best final decision.","zh":"我的第一反應可能有用，但不一定是最好的最終決定。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"nothing to be grateful for","meaning":"沒有甚麼值得感恩","examples":[{"en":"I first thought there was nothing to be grateful for that day.","zh":"我起初以為那天沒有甚麼值得感恩。"},{"en":"“Nothing to be grateful for” means believing that no part of a situation deserves appreciation or thanks.","zh":"「沒有甚麼值得感恩」表示相信一個情況中沒有任何部分值得珍惜或感謝。"},{"en":"After a terrible morning, I felt there was nothing to be grateful for until a friend quietly helped me.","zh":"經歷糟糕的早上後，我覺得沒有甚麼值得感恩，直到朋友默默幫了我。"},{"en":"Stress can make it seem as if there is nothing to be grateful for because problems receive all our attention.","zh":"壓力可以令人覺得沒有甚麼值得感恩，因為問題佔據了所有注意力。"},{"en":"A difficult day may still contain something valuable even when we first see nothing to be grateful for.","zh":"即使最初覺得沒有甚麼值得感恩，艱難的一天仍可能包含有價值的事。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"force myself to","meaning":"迫自己去……","examples":[{"en":"I forced myself to sit with the page.","zh":"我迫自己坐下來面對那一頁。"},{"en":"To force myself to do something means to make myself do it even though I do not feel willing or comfortable.","zh":"「迫自己去……」指即使不願意或不舒服，仍要求自己去做某件事。"},{"en":"I forced myself to start the assignment instead of waiting until I felt motivated.","zh":"我迫自己開始做功課，而不是等到有動力才開始。"},{"en":"Sometimes I force myself to take a short walk because I know I will feel better afterwards.","zh":"有時我會迫自己出去走一小段路，因為知道之後會感覺好一點。"},{"en":"Forcing myself to begin can help when the hardest part is simply getting started.","zh":"當最困難的是開始時，迫自己先踏出第一步可能有幫助。"}],"source":"2021 Q6.pdf","sourcePage":7},{"front":"sit with the page","meaning":"坐下來面對那一頁","examples":[{"en":"I forced myself to sit with the page and think.","zh":"我迫自己坐下來面對那一頁，繼續思考。"},{"en":"To sit with the page means to stay with a writing task instead of escaping it, giving yourself time to think.","zh":"「坐下來面對那一頁」指不逃避寫作任務，而是留下來給自己時間思考。"},{"en":"I wanted to close the notebook, but I sat with the page until I found something honest to write.","zh":"我很想合上筆記簿，但仍坐下來面對那一頁，直到找到真誠的內容可寫。"},{"en":"Sitting with the page can reveal deeper thoughts because you do not accept the first easy answer.","zh":"坐下來面對那一頁可以帶出更深的想法，因為你沒有接受第一個容易的答案。"},{"en":"Sometimes good reflection begins when you are willing to sit with the page in silence.","zh":"有時，好的反思就是從願意安靜地坐下來面對那一頁開始。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"after a few minutes","meaning":"幾分鐘後","examples":[{"en":"After a few minutes, I wrote something more honest.","zh":"幾分鐘後，我寫下了一些更真實的內容。"},{"en":"“After a few minutes” means a short period of several minutes later.","zh":"「幾分鐘後」表示短短數分鐘過去之後。"},{"en":"The bus arrived after a few minutes, so we did not have to wait long.","zh":"幾分鐘後巴士便到了，所以我們不用等很久。"},{"en":"I was angry at first, but after a few minutes I was calm enough to explain the problem.","zh":"我起初很生氣，但幾分鐘後已冷靜得可以解釋問題。"},{"en":"A few minutes of quiet thinking can change what we say next.","zh":"幾分鐘的安靜思考，可以改變我們接下來說的話。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"come into my room","meaning":"走進我的房間","examples":[{"en":"My brother still wanted to come into my room and talk to me.","zh":"弟弟仍然想走進我的房間和我說話。"},{"en":"To come into my room means to enter the room that I use as my personal space.","zh":"「走進我的房間」指進入我作為私人空間使用的房間。"},{"en":"My mother knocked before she came into my room.","zh":"媽媽走進我的房間前先敲門。"},{"en":"I asked my brother not to come into my room while I was studying because I needed quiet.","zh":"我請弟弟在我溫習時不要走進我的房間，因為我需要安靜。"},{"en":"Wanting to come into my room after an argument can show that someone still wants contact or conversation.","zh":"爭吵後仍想走進我的房間，可能表示對方仍希望保持聯絡或談一談。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"push someone away","meaning":"推開某人；疏遠某人","examples":[{"en":"I often pushed my brother away.","zh":"我經常把弟弟推開、疏遠他。"},{"en":"To push someone away can mean to reject emotional closeness or discourage that person from approaching you.","zh":"「推開某人」可以表示拒絕情感上的親近，或令對方不敢再接近自己。"},{"en":"She pushed her friends away whenever they asked whether she needed help.","zh":"每當朋友問她是否需要幫助時，她都把他們推開。"},{"en":"Fear of being hurt can cause people to push others away even when they feel lonely.","zh":"害怕受傷可能令人即使感到孤單，也把別人推開。"},{"en":"Pushing someone away repeatedly can weaken a relationship because the other person may stop trying to connect.","zh":"不斷推開某人可能削弱關係，因為對方最終可能停止嘗試接近你。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"leave me uncomfortable","meaning":"令我感到不自在","examples":[{"en":"That sentence left me uncomfortable.","zh":"那句話令我感到不自在。"},{"en":"If something leaves me uncomfortable, it causes an uneasy feeling that remains after the moment has passed.","zh":"如果某件事令我感到不自在，就是它在事情過後仍留下不安的感覺。"},{"en":"His joke left me uncomfortable because it made fun of someone who was not there.","zh":"他的笑話令我感到不自在，因為他取笑了一個不在場的人。"},{"en":"Honest feedback may leave me uncomfortable when it reveals something I need to change.","zh":"當真誠的意見指出我需要改變的地方時，可能令我感到不自在。"},{"en":"Something that leaves me uncomfortable is not always harmful; discomfort can sometimes lead to reflection.","zh":"令我感到不自在的事情不一定有害；不舒服有時也可以引發反思。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"in a useful way","meaning":"以一種有幫助的方式","examples":[{"en":"The sentence made me uncomfortable in a useful way.","zh":"那句話以一種有幫助的方式令我感到不自在。"},{"en":"“In a useful way” means the effect may not feel pleasant, but it helps produce understanding, improvement, or another benefit.","zh":"「以一種有幫助的方式」表示感受未必舒服，但能帶來理解、改善或其他益處。"},{"en":"The teacher challenged my answer in a useful way by asking me to explain my evidence.","zh":"老師要求我解釋證據，以一種有幫助的方式挑戰我的答案。"},{"en":"Failure can hurt in a useful way when it shows exactly what needs more practice.","zh":"當失敗清楚指出需要多練習的地方時，它可以以一種有幫助的方式令人難受。"},{"en":"Criticism is most helpful when it makes us uncomfortable in a useful way rather than simply making us feel bad.","zh":"最有用的批評會以一種有幫助的方式令我們不舒服，而不只是令我們難受。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"make me realise that","meaning":"令我意識到","examples":[{"en":"The sentence made me realise that gratitude does not cancel frustration.","zh":"那句話令我意識到，感恩並不會抵消挫敗感。"},{"en":"To make me realise that something is true means to cause me to understand it clearly, often after I had not noticed it before.","zh":"「令我意識到……」指使我清楚明白一件事，通常是以前沒有察覺的事情。"},{"en":"Missing the final bus made me realise that I needed to leave work earlier.","zh":"錯過尾班車令我意識到自己需要更早下班離開。"},{"en":"Talking to my friend made me realise that she had been worried, not angry.","zh":"與朋友交談令我意識到她其實是擔心，而不是生氣。"},{"en":"A small experience can make me realise that an assumption I have held for years is wrong.","zh":"一個小經歷也可以令我意識到自己多年來的某個假設是錯的。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"cancel frustration","meaning":"抵消挫敗感","examples":[{"en":"Gratitude does not cancel frustration.","zh":"感恩不會抵消挫敗感。"},{"en":"To cancel frustration would mean to remove or erase the feeling of annoyance or disappointment completely.","zh":"「抵消挫敗感」表示完全消除或抹去煩躁、失望的感覺。"},{"en":"A kind message did not cancel my frustration about the delayed train, but it made the wait easier.","zh":"一句友善訊息沒有抵消我對火車延誤的挫敗感，但令等待較容易。"},{"en":"Gratitude cannot cancel frustration because positive and negative feelings can exist at the same time.","zh":"感恩不能完全抵消挫敗感，因為正面和負面情緒可以同時存在。"},{"en":"You do not need to cancel frustration in order to notice something good.","zh":"你不需要先抵消挫敗感，才可以留意美好的事。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"rather","meaning":"反而；更準確地說","examples":[{"en":"Gratitude does not cancel frustration; rather, it changes the whole story.","zh":"感恩不會抵消挫敗感；反而，它改變了整個故事。"},{"en":"“Rather” can introduce a correction or a more accurate alternative to what has just been said.","zh":"「反而」可以用來提出修正，或補充一個比前面說法更準確的選擇。"},{"en":"The new rule did not punish students; rather, it gave them clearer expectations.","zh":"新規則不是要懲罰學生；反而，它給學生更清楚的要求。"},{"en":"The problem was not a lack of effort; rather, we had misunderstood the instructions.","zh":"問題不是缺乏努力；更準確地說，是我們誤解了指示。"},{"en":"Using “rather” helps show that the second explanation is more accurate than the first.","zh":"使用「反而」可以表示第二個解釋比第一個更準確。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"prevent something from becoming","meaning":"防止某事變成","examples":[{"en":"Gratitude prevents frustration from becoming the whole story.","zh":"感恩防止挫敗感變成整個故事。"},{"en":"To prevent something from becoming something else means to stop it developing into a different or more serious state.","zh":"「防止某事變成……」指阻止某件事發展成另一種或更嚴重的狀態。"},{"en":"Early treatment can prevent a small infection from becoming a serious problem.","zh":"及早治療可以防止小感染變成嚴重問題。"},{"en":"A calm conversation may prevent a misunderstanding from becoming a major argument.","zh":"冷靜交談可能防止誤會變成大型爭吵。"},{"en":"Good habits can prevent temporary stress from becoming a permanent way of living.","zh":"良好習慣可以防止暫時壓力變成長期的生活方式。"}],"source":"2021 Q6.pdf","sourcePage":8},{"front":"the whole story","meaning":"整個故事；全部真相","examples":[{"en":"Frustration should not become the whole story.","zh":"挫敗感不應變成整個故事。"},{"en":"“The whole story” means the complete picture or the only explanation we use to understand a situation.","zh":"「整個故事」指我們理解一個情況時的完整畫面，或唯一採用的解釋。"},{"en":"One bad mark is disappointing, but it is not the whole story of a student’s ability.","zh":"一次差成績令人失望，但不是學生能力的全部真相。"},{"en":"If anger becomes the whole story, we may forget the support that was also present.","zh":"如果憤怒變成整個故事，我們可能忘記當時同樣存在的支持。"},{"en":"A fair judgement looks beyond one event and asks what else belongs in the whole story.","zh":"公平的判斷會看得更全面，思考整個故事中還包括甚麼。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"the same happened after","meaning":"同樣的情況發生在……之後","examples":[{"en":"The same happened after I received a disappointing test result.","zh":"我收到令人失望的測驗成績後，同樣的情況也發生了。"},{"en":"“The same happened after” means a similar reaction or situation occurred following another event.","zh":"「同樣的情況發生在……之後」表示另一件事之後出現了相似的反應或情況。"},{"en":"I felt calmer after writing about the argument, and the same happened after a stressful meeting.","zh":"寫下爭吵的經過後，我平靜了些；一次緊張會議後，同樣的情況也發生了。"},{"en":"My confidence improved after the first practice session; the same happened after the second one.","zh":"第一次練習後我的信心提升；第二次練習後也出現了同樣情況。"},{"en":"This phrase connects two experiences by showing that they produced a similar result.","zh":"這個說法透過顯示兩次經歷產生相似結果，把它們連繫起來。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"a disappointing test result","meaning":"令人失望的測驗成績","examples":[{"en":"I received a disappointing test result.","zh":"我收到了一個令人失望的測驗成績。"},{"en":"A disappointing test result is a mark or score that is lower than the student hoped or expected.","zh":"「令人失望的測驗成績」指低於學生希望或預期的分數。"},{"en":"After receiving a disappointing test result in maths, I asked the teacher which questions I had misunderstood.","zh":"收到令人失望的數學測驗成績後，我問老師自己誤解了哪些題目。"},{"en":"A disappointing test result can feel discouraging, but it can also show which areas need more practice.","zh":"令人失望的測驗成績可能令人灰心，但也可以指出哪些地方需要更多練習。"},{"en":"One disappointing test result does not decide a student’s future performance.","zh":"一次令人失望的測驗成績並不能決定學生未來的表現。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"not for…but for…","meaning":"不是因為……而是因為……","examples":[{"en":"I was grateful not for the mark, but for the teacher’s support.","zh":"我感恩的不是那個分數，而是老師的支持。"},{"en":"“Not for…but for…” shows that the real reason is the second thing, not the first.","zh":"「不是因為……而是因為……」表示真正原因是第二項，而不是第一項。"},{"en":"I thanked him not for solving the problem, but for listening patiently.","zh":"我感謝他，不是因為他解決了問題，而是因為他耐心聆聽。"},{"en":"She chose the course not for its reputation, but for the subjects she genuinely wanted to study.","zh":"她選擇那個課程不是因為名氣，而是因為有她真正想讀的科目。"},{"en":"This structure makes a contrast clear by rejecting one reason and replacing it with another.","zh":"這個句式先否定一個理由，再以另一個理由取代，令對比更清楚。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"come and see me","meaning":"來找我","examples":[{"en":"The teacher wrote, “Come and see me if you need help.”","zh":"老師寫道：「如果你需要幫助，就來找我。」"},{"en":"“Come and see me” is an invitation to meet the speaker in person, usually to talk or receive help.","zh":"「來找我」是邀請對方面對面見自己，通常是為了交談或得到幫助。"},{"en":"The doctor said, “Come and see me again if the pain continues.”","zh":"醫生說：「如果疼痛持續，就再來找我。」"},{"en":"A teacher who says “come and see me” makes it easier for students to ask questions privately.","zh":"老師說「來找我」，可以令學生更容易私下提出問題。"},{"en":"“Come and see me” can signal that support is available rather than leaving someone to manage alone.","zh":"「來找我」可以表示有人願意提供支持，而不是要對方獨自處理。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"if you need help","meaning":"如果你需要幫助","examples":[{"en":"The teacher offered support if I needed help.","zh":"老師表示，如果我需要幫助，他願意提供支持。"},{"en":"“If you need help” means support is available on the condition that you require assistance.","zh":"「如果你需要幫助」表示只要你需要協助，就有支援可用。"},{"en":"Call me if you need help carrying the boxes upstairs.","zh":"如果你需要幫助把箱子搬上樓，就打電話給我。"},{"en":"Telling a new employee “ask if you need help” can reduce mistakes because questions are welcomed.","zh":"告訴新員工「如果需要幫助就問」，可以減少錯誤，因為大家知道提問是受歡迎的。"},{"en":"Offering help is most useful when people know clearly what to do if they need help.","zh":"當人清楚知道需要幫助時可以怎樣做，提供支援才最有用。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"for once","meaning":"這一次；難得一次","examples":[{"en":"For once, I saw support where I would usually have seen failure.","zh":"這一次，我看見了支持，而不是像平時那樣看見失敗。"},{"en":"“For once” means on this particular occasion, in contrast with what usually happens.","zh":"「這一次／難得一次」表示這次情況與平時通常發生的不同。"},{"en":"For once, the bus arrived early instead of ten minutes late.","zh":"難得一次，巴士提早到了，而不是遲十分鐘。"},{"en":"I usually worry before presentations, but for once I felt calm.","zh":"我通常在簡報前很擔心，但這一次我感到平靜。"},{"en":"“For once” highlights that the present experience is unusual compared with a familiar pattern.","zh":"「這一次」強調目前的經歷與一貫模式不同。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"see support","meaning":"看見支持","examples":[{"en":"For once, I saw support instead of failure.","zh":"這一次，我看見了支持，而不是失敗。"},{"en":"To see support means to recognise that someone is offering help, encouragement, or care.","zh":"「看見支持」指察覺有人正在提供幫助、鼓勵或關心。"},{"en":"I began to see support in my teacher’s detailed comments rather than only seeing criticism.","zh":"我開始在老師詳細的評語中看見支持，而不只看見批評。"},{"en":"When we expect rejection, it can be difficult to see support even when people are trying to help.","zh":"當我們預期會被拒絕時，即使別人正在幫忙，也可能很難看見支持。"},{"en":"Learning to see support does not remove the problem, but it changes how alone we feel.","zh":"學會看見支持不會令問題消失，但可以改變我們感到孤單的程度。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"would usually have seen","meaning":"以往通常會看到","examples":[{"en":"I saw support where I would usually have seen failure.","zh":"我看見了支持，而那裏是我以往通常會看到失敗的地方。"},{"en":"“Would usually have seen” describes the interpretation someone normally would have made in a similar past situation.","zh":"「以往通常會看到」描述一個人在類似情況下慣常會作出的理解。"},{"en":"I noticed useful advice where I would usually have seen only criticism.","zh":"我在以前通常只會看到批評的地方，看見了有用的意見。"},{"en":"After changing my perspective, I found an opportunity where I would usually have seen a problem.","zh":"改變觀點後，我在以前通常會看到問題的地方發現了機會。"},{"en":"The phrase shows that a person’s habitual way of understanding something has changed.","zh":"這個說法表示一個人慣常理解事情的方式已經改變。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"by the final week","meaning":"到最後一星期","examples":[{"en":"By the final week, the challenge had begun to affect my behaviour.","zh":"到最後一星期，這個挑戰已開始影響我的行為。"},{"en":"“By the final week” means that before or during the last week, a particular change had already happened.","zh":"「到最後一星期」表示在最後一星期之前或期間，某種改變已經出現。"},{"en":"By the final week of the course, everyone could complete the basic exercise independently.","zh":"到課程最後一星期，每個人都可以獨立完成基本練習。"},{"en":"Practising every day meant that by the final week the new routine felt much more natural.","zh":"每天練習令新習慣到最後一星期時自然了許多。"},{"en":"“By the final week” often shows the result of gradual development over an earlier period.","zh":"「到最後一星期」常用來表示之前一段時間逐漸發展所帶來的結果。"}],"source":"2021 Q6.pdf","sourcePage":9},{"front":"affect my behaviour","meaning":"影響我的行為","examples":[{"en":"The challenge began to affect my behaviour, not just my mood.","zh":"這個挑戰開始影響我的行為，而不只是我的心情。"},{"en":"To affect my behaviour means to change what I actually do, not only what I think or feel.","zh":"「影響我的行為」指改變我實際做的事情，而不只是改變想法或感受。"},{"en":"Learning about sleep began to affect my behaviour because I stopped using my phone so late.","zh":"了解睡眠的重要性開始影響我的行為，因為我不再那麼晚使用電話。"},{"en":"Advice becomes meaningful when it affects my behaviour and leads to different choices.","zh":"當意見影響我的行為並帶來不同選擇時，它才真正變得有意義。"},{"en":"A change in attitude is easier to see when it starts to affect behaviour in everyday situations.","zh":"當態度的改變開始影響日常行為時，這種改變會更容易被看見。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"not just my mood","meaning":"不只是我的心情","examples":[{"en":"The challenge affected my behaviour, not just my mood.","zh":"這個挑戰影響了我的行為，而不只是我的心情。"},{"en":"“Not just my mood” means the change went beyond temporary feelings and influenced other parts of life too.","zh":"「不只是我的心情」表示改變超越了暫時的感受，也影響生活其他部分。"},{"en":"Exercise improved my sleep and concentration, not just my mood.","zh":"運動改善了我的睡眠和專注力，而不只是我的心情。"},{"en":"The new routine changed how I used my time, not just my mood for a few hours.","zh":"新習慣改變了我使用時間的方式，而不只是幾小時內的心情。"},{"en":"A lasting habit should influence actions, not just your mood in the moment.","zh":"持久的習慣應影響行動，而不只是當下的心情。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"thank people more directly","meaning":"更直接地感謝別人","examples":[{"en":"I thanked people more directly during the final week.","zh":"到最後一星期，我更直接地感謝別人。"},{"en":"To thank people more directly means to tell them clearly and personally that you appreciate what they did.","zh":"「更直接地感謝別人」指清楚而親自告訴對方，你珍惜他們所做的事情。"},{"en":"Instead of silently feeling grateful, I thanked my classmate more directly for helping with my notes.","zh":"我不再只是心裏感恩，而是更直接地感謝同學幫我整理筆記。"},{"en":"Thanking people more directly can strengthen relationships because they no longer have to guess whether their effort was noticed.","zh":"更直接地感謝別人可以加強關係，因為對方不用再猜自己的付出是否被看見。"},{"en":"A simple “thank you for helping me yesterday” is one way to thank people more directly.","zh":"簡單說一句「謝謝你昨天幫我」，就是更直接地感謝別人的方法。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"late-night fruit plates","meaning":"深夜準備的水果盤","examples":[{"en":"My mother’s late-night fruit plates meant a lot to me.","zh":"媽媽深夜準備的水果盤對我意義很大。"},{"en":"Late-night fruit plates are plates of prepared fruit brought or left for someone late in the evening.","zh":"「深夜準備的水果盤」指晚上較晚時間為某人準備或送來的一碟水果。"},{"en":"During exam week, my father sometimes brought late-night fruit plates while I studied.","zh":"考試星期期間，爸爸有時在我溫習時送來深夜準備的水果盤。"},{"en":"Late-night fruit plates may look ordinary, but preparing them can be a quiet act of care.","zh":"深夜準備的水果盤看起來很普通，但準備它可以是一種默默的關心。"},{"en":"Small family routines such as late-night fruit plates can become meaningful memories.","zh":"深夜水果盤這類家庭小習慣，可以成為很有意義的回憶。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"mean a lot to me","meaning":"對我意義重大","examples":[{"en":"Her late-night fruit plates meant a lot to me.","zh":"她深夜準備的水果盤對我意義重大。"},{"en":"If something means a lot to me, it is emotionally important or valuable to me.","zh":"如果某件事「對我意義重大」，表示它在情感上對我很重要或很有價值。"},{"en":"The message from my old teacher meant a lot to me because she remembered my graduation day.","zh":"舊老師傳來的訊息對我意義重大，因為她記得我的畢業日。"},{"en":"A small action may mean a lot to me when it shows that someone was thinking about me.","zh":"一個小行動如果顯示有人想着我，也可能對我意義重大。"},{"en":"Things do not have to be expensive to mean a lot to me.","zh":"東西不需要昂貴，也可以對我意義重大。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"message a friend","meaning":"傳訊息給朋友","examples":[{"en":"I messaged a friend simply to say thank you.","zh":"我傳訊息給朋友，只是為了說謝謝。"},{"en":"To message a friend means to send a friend a written or recorded message by phone or online.","zh":"「傳訊息給朋友」指透過電話或網上向朋友發送文字或錄音訊息。"},{"en":"I messaged a friend after school to check whether she had arrived home safely.","zh":"放學後，我傳訊息給朋友，問她是否安全到家。"},{"en":"Messaging a friend can maintain a relationship when you do not have time to meet in person.","zh":"當沒有時間見面時，傳訊息給朋友可以幫助維持關係。"},{"en":"Sometimes it is worth messaging a friend for no reason other than to show appreciation.","zh":"有時，值得傳訊息給朋友，理由只是想表達感激。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"not to ask for","meaning":"不是為了索取","examples":[{"en":"I messaged a friend not to ask for notes or gossip.","zh":"我傳訊息給朋友，不是為了索取筆記或八卦消息。"},{"en":"“Not to ask for” shows that getting something from the other person was not the purpose of the action.","zh":"「不是為了索取」表示行動目的並不是從對方那裏得到某些東西。"},{"en":"I called my grandmother not to ask for a favour, but simply to hear how she was.","zh":"我打電話給祖母，不是為了請她幫忙，只是想知道她近況如何。"},{"en":"Meeting someone not to ask for anything can make the conversation feel more genuine.","zh":"見一個人而不是為了向對方索取甚麼，可以令對話感覺更真誠。"},{"en":"“Not to ask for” often contrasts receiving something with another, less self-centred purpose.","zh":"「不是為了索取」常把取得東西與另一個較不自我中心的目的作對比。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"notes or gossip","meaning":"筆記或八卦消息","examples":[{"en":"I did not message my friend to ask for notes or gossip.","zh":"我傳訊息給朋友不是為了問筆記或八卦消息。"},{"en":"Notes or gossip refers here to useful school information or informal talk about other people’s private lives.","zh":"「筆記或八卦消息」在這裏指有用的學校資料，或關於別人私生活的非正式談話。"},{"en":"Our messages were usually about homework notes or gossip from school.","zh":"我們的訊息平時多數關於功課筆記或學校的八卦消息。"},{"en":"If every conversation is only about notes or gossip, a friendship may never become very deep.","zh":"如果每次對話都只是筆記或八卦消息，友誼可能很難變得深入。"},{"en":"This time I wanted to talk about appreciation rather than notes or gossip.","zh":"這一次，我想談的是感謝，而不是筆記或八卦消息。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"simply to say","meaning":"只是為了說","examples":[{"en":"I messaged my friend simply to say I appreciated her kindness.","zh":"我傳訊息給朋友，只是為了說我很感激她的善意。"},{"en":"“Simply to say” means the only or main purpose was to express the words that follow.","zh":"「只是為了說」表示唯一或主要目的就是表達後面所說的內容。"},{"en":"I called simply to say that I had arrived safely.","zh":"我打電話只是為了說我已經安全到達。"},{"en":"Sometimes people send a short message simply to say they are thinking of someone.","zh":"有時，人們傳一個短訊，只是為了說自己正在想着某人。"},{"en":"A message sent simply to say thank you can feel more sincere because nothing is being requested in return.","zh":"一個只是為了說謝謝的訊息可能更真誠，因為沒有要求任何回報。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"appreciate how","meaning":"感激……的方式","examples":[{"en":"I appreciated how she always checked whether I had eaten lunch.","zh":"我很感激她總會問我是否吃了午餐。"},{"en":"To appreciate how someone does something means to recognise and value the way they regularly act.","zh":"「感激……的方式」指察覺並珍惜某人一貫做事的方式。"},{"en":"I appreciate how my teacher explains mistakes without embarrassing anyone.","zh":"我很感激老師指出錯誤時不會令任何人難堪的方式。"},{"en":"Living away from home made me appreciate how my parents quietly handled many daily tasks.","zh":"離家生活令我更感激父母默默處理許多日常事情的方式。"},{"en":"Saying that you appreciate how someone behaves can make your thanks more specific and meaningful.","zh":"說清楚你感激某人怎樣做事，可以令謝意更具體和有意義。"}],"source":"2021 Q6.pdf","sourcePage":10},{"front":"check whether","meaning":"查看是否；問清楚是否","examples":[{"en":"She always checked whether I had eaten lunch.","zh":"她總會問我是否吃了午餐。"},{"en":"To check whether something is true means to find out or make sure if it has happened or is correct.","zh":"「查看是否」指弄清楚或確認某件事有沒有發生、是否正確。"},{"en":"Before leaving home, I checked whether I had locked the window.","zh":"出門前，我查看自己是否已鎖好窗戶。"},{"en":"A teacher may check whether students understand before moving to a harder topic.","zh":"老師進入較難內容前，可能會查看學生是否明白。"},{"en":"Checking whether something is correct can prevent small mistakes from becoming larger problems.","zh":"查看事情是否正確，可以防止小錯誤變成更大的問題。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"the funny thing is","meaning":"有趣的是","examples":[{"en":"The funny thing is that these small messages made me feel less awkward.","zh":"有趣的是，這些小訊息令我感覺沒那麼尷尬。"},{"en":"“The funny thing is” introduces something surprising, unexpected, or slightly amusing about a situation.","zh":"「有趣的是」用來引出一個令人意外、出乎意料或略帶趣味的情況。"},{"en":"The funny thing is that I was worried about the interview, but I actually enjoyed it.","zh":"有趣的是，我原本很擔心面試，結果卻很享受。"},{"en":"The funny thing is that the cheapest café turned out to have the best food.","zh":"有趣的是，最便宜的咖啡店反而有最好吃的食物。"},{"en":"We often say “the funny thing is” when the result is different from what we expected.","zh":"當結果與預期不同時，我們常會說「有趣的是」。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"less awkward","meaning":"沒那麼尷尬","examples":[{"en":"These small messages made me feel less awkward.","zh":"這些小訊息令我感覺沒那麼尷尬。"},{"en":"“Less awkward” means more comfortable and natural, with less embarrassment or social tension.","zh":"「沒那麼尷尬」表示感覺更自然、更舒服，少了難為情或社交上的緊張。"},{"en":"I felt less awkward at the party after someone introduced me to a few people.","zh":"有人介紹我認識幾個人後，我在派對上沒那麼尷尬。"},{"en":"Practising the presentation several times made speaking in front of the class less awkward.","zh":"把簡報練習幾次後，在全班面前說話沒那麼尷尬。"},{"en":"Honest communication often makes relationships less awkward because people no longer have to guess what the other person feels.","zh":"真誠溝通常令關係沒那麼尷尬，因為大家不用再猜對方的感受。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"open doors to","meaning":"打開通往……的大門","examples":[{"en":"Small messages opened doors to warmer conversations.","zh":"小小的訊息打開了通往更溫暖對話的大門。"},{"en":"To open doors to something means to create opportunities for it to happen or develop.","zh":"「打開通往……的大門」指創造機會，令某件事得以發生或發展。"},{"en":"Learning another language can open doors to new friendships and jobs.","zh":"學習另一種語言可以打開通往新友誼和工作機會的大門。"},{"en":"One honest question opened doors to a deeper conversation between the two brothers.","zh":"一個真誠的問題打開了兩兄弟之間更深入對話的大門。"},{"en":"Small changes can open doors to larger improvements that were not possible before.","zh":"小改變可以打開通往更大改善的大門，而這些改善以前可能不會出現。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"warmer conversations","meaning":"更溫暖的對話","examples":[{"en":"The messages opened doors to warmer conversations.","zh":"那些訊息打開了通往更溫暖對話的大門。"},{"en":"Warmer conversations are friendlier, more caring, and more emotionally open discussions.","zh":"「更溫暖的對話」指更友善、更關心，而且在情感上更開放的交流。"},{"en":"Asking my grandfather about his childhood led to warmer conversations between us.","zh":"問祖父童年的事情後，我們之間開始有了更溫暖的對話。"},{"en":"Expressing thanks can create warmer conversations because people feel appreciated rather than judged.","zh":"表達感謝可以帶來更溫暖的對話，因為人會感到被欣賞，而不是被批判。"},{"en":"Warmer conversations are not necessarily longer; even a short exchange can feel kind and genuine.","zh":"更溫暖的對話不一定更長；即使短短幾句，也可以感覺友善和真誠。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"complain less online","meaning":"較少在網上抱怨","examples":[{"en":"I also noticed that I complained less online.","zh":"我也注意到自己較少在網上抱怨。"},{"en":"To complain less online means to post fewer negative comments or messages about problems on the internet.","zh":"「較少在網上抱怨」指減少在互聯網發表關於問題的負面帖文或訊息。"},{"en":"I began to complain less online and talk directly to people when a problem could actually be solved.","zh":"我開始較少在網上抱怨，而是遇到可以解決的問題時直接與相關的人談。"},{"en":"Pausing before posting helped me complain less online because some frustrations disappeared after I calmed down.","zh":"發布前先停一停令我較少在網上抱怨，因為有些不滿在冷靜後已經減退。"},{"en":"Complaining less online does not mean pretending everything is fine; it means choosing more carefully what to share publicly.","zh":"較少在網上抱怨不等於假裝一切都好，而是更仔細選擇甚麼值得公開分享。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"before posting","meaning":"在發布之前","examples":[{"en":"Before posting a sarcastic story, I would ask myself a question.","zh":"在發布一則帶諷刺意味的限時動態之前，我會問自己一個問題。"},{"en":"“Before posting” means before publishing a message, photo, video, or story online for other people to see.","zh":"「在發布之前」指在把訊息、照片、影片或限時動態放上網給別人看之前。"},{"en":"I reread my comment before posting it to make sure it did not sound rude.","zh":"發布留言之前，我重新讀了一次，確保語氣不會太無禮。"},{"en":"Taking a moment before posting can prevent regret because online messages may spread quickly.","zh":"在發布之前停一停可以減少後悔，因為網上訊息可能很快傳開。"},{"en":"Before posting, ask whether the message is true, useful, and something you are comfortable leaving online.","zh":"在發布之前，可以先問自己內容是否真實、有用，以及是否願意讓它長期留在網上。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"a sarcastic story","meaning":"帶諷刺意味的限時動態","examples":[{"en":"I thought twice before posting a sarcastic story about a bad day.","zh":"我在發布一則關於糟糕一天的諷刺限時動態前再三思考。"},{"en":"A sarcastic story is a social-media story that uses mocking or ironic language, often to express annoyance indirectly.","zh":"「帶諷刺意味的限時動態」指在社交媒體上用嘲諷或反話間接表達不滿的限時內容。"},{"en":"After the delayed train, I almost posted a sarcastic story making fun of the transport company.","zh":"火車延誤後，我差點發布一則取笑運輸公司的諷刺限時動態。"},{"en":"A sarcastic story may feel satisfying for a moment but can embarrass other people or create unnecessary conflict.","zh":"帶諷刺意味的限時動態可能一時令人痛快，但也可能令別人難堪或造成不必要衝突。"},{"en":"If the real goal is to solve a problem, a direct message may work better than a sarcastic story.","zh":"如果真正目的是解決問題，直接傳訊息可能比發布諷刺限時動態更有效。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"ask myself","meaning":"問自己","examples":[{"en":"I would ask myself whether I was being honest.","zh":"我會問自己，我是否真的坦誠。"},{"en":"To ask myself something means to reflect privately on a question instead of immediately reacting.","zh":"「問自己」指先在心裏反思一個問題，而不是立即作出反應。"},{"en":"Before buying the expensive shoes, I asked myself whether I really needed them.","zh":"買那雙昂貴鞋之前，我問自己是否真的需要它。"},{"en":"Asking myself why I am upset can stop me from blaming the wrong person.","zh":"問自己為甚麼不開心，可以防止我把責任錯怪在別人身上。"},{"en":"A useful habit is to ask myself one careful question before making an emotional decision.","zh":"在情緒化地作決定前，先問自己一個仔細的問題，是很有用的習慣。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"being honest","meaning":"坦誠；誠實","examples":[{"en":"I asked myself whether I was being honest.","zh":"我問自己是否真的坦誠。"},{"en":"Being honest means expressing what is genuinely true rather than pretending, exaggerating, or hiding important facts.","zh":"「坦誠」指表達真正的事實，而不是假裝、誇大或隱瞞重要內容。"},{"en":"Being honest with my teacher meant admitting that I had forgotten the deadline.","zh":"對老師坦誠，就是承認自己忘記了截止日期。"},{"en":"Being honest can be uncomfortable at first, but it often prevents larger misunderstandings later.","zh":"坦誠起初可能令人不舒服，但往往能防止之後出現更大的誤會。"},{"en":"Being honest with yourself is especially important when examining your own motives.","zh":"當檢視自己的動機時，對自己坦誠尤其重要。"}],"source":"2021 Q6.pdf","sourcePage":11},{"front":"perform disappointment for attention","meaning":"為博取注意而表演失望","examples":[{"en":"I wondered whether I was only performing disappointment for attention.","zh":"我想知道自己是否只是在為博取注意而表演失望。"},{"en":"To perform disappointment for attention means to display sadness or frustration partly to make other people notice or respond to you.","zh":"「為博取注意而表演失望」指展示悲傷或挫敗，部分目的在於讓別人留意或回應自己。"},{"en":"Posting ten dramatic messages about a small problem can sometimes become a way to perform disappointment for attention.","zh":"因一個小問題發十則戲劇化訊息，有時可能變成為博取注意而表演失望。"},{"en":"If I perform disappointment for attention, my public reaction may become larger than what I truly feel.","zh":"如果我為博取注意而表演失望，公開表現出來的反應可能比真正感受更大。"},{"en":"Asking whether I am expressing a real feeling or performing disappointment for attention can make online behaviour more honest.","zh":"問自己是真正在表達感受，還是在為博取注意而表演失望，可以令網上行為更坦誠。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"that question alone","meaning":"單是那個問題","examples":[{"en":"That question alone was worth the whole challenge.","zh":"單是那個問題，已經值得整個挑戰。"},{"en":"“That question alone” means that even if nothing else had happened, that single question was valuable enough by itself.","zh":"「單是那個問題」表示即使沒有其他事情發生，那一個問題本身已經足夠有價值。"},{"en":"That conversation was useful, but that question alone changed how I understood the problem.","zh":"那次對話很有用，但單是那個問題已經改變我理解問題的方式。"},{"en":"That question alone made me stop before posting, so it affected my behaviour immediately.","zh":"單是那個問題便令我發布前停下來，所以立即影響了我的行為。"},{"en":"Sometimes one strong insight is enough; that question alone can justify a much longer learning process.","zh":"有時一個重要領悟已經足夠；單是那個問題也可以令整個學習過程值得。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"worth the whole challenge","meaning":"值得整個挑戰","examples":[{"en":"That question was already worth the whole challenge.","zh":"單是那個問題，已經值得整個挑戰。"},{"en":"“Worth the whole challenge” means valuable enough to justify all the time and effort spent completing the challenge.","zh":"「值得整個挑戰」表示所得價值足以抵得上完成整個挑戰所花的時間和努力。"},{"en":"Learning how to control my breathing before speaking was worth the whole challenge for me.","zh":"對我來說，學會在發言前控制呼吸已經值得整個挑戰。"},{"en":"Even one lasting habit can be worth the whole challenge if it continues helping you afterwards.","zh":"如果一個新習慣之後仍持續幫助你，單是它也可能值得整個挑戰。"},{"en":"Something does not need many benefits to be worth the whole challenge; one important change can be enough.","zh":"一個挑戰不需要帶來很多好處才值得；一項重要改變已經可以足夠。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"a resounding yes","meaning":"響亮而肯定的「是」","examples":[{"en":"My answer is a resounding yes.","zh":"我的答案是一個響亮而肯定的「是」。"},{"en":"A resounding yes is a very strong, clear, and enthusiastic agreement.","zh":"「響亮而肯定的『是』」表示非常強烈、清楚而充滿肯定的同意。"},{"en":"When the teacher asked whether the trip had been useful, the students gave a resounding yes.","zh":"當老師問旅行是否有用時，學生給出了一個響亮而肯定的「是」。"},{"en":"After seeing the improvement in my sleep, my answer to whether the routine was worthwhile was a resounding yes.","zh":"看見睡眠改善後，如果問我這個習慣是否值得，我的答案會是響亮而肯定的「是」。"},{"en":"“A resounding yes” is much stronger than a hesitant or uncertain yes.","zh":"「響亮而肯定的『是』」比猶豫或不確定的「是」強烈得多。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"not in a magical way","meaning":"不是以神奇的方式","examples":[{"en":"The change was real, though not in a magical way.","zh":"改變是真實的，雖然不是以神奇的方式發生。"},{"en":"“Not in a magical way” means the improvement happened realistically and gradually rather than through an instant miracle.","zh":"「不是以神奇的方式」表示改善是現實而逐漸出現的，而不是像奇蹟般即時發生。"},{"en":"Exercise improved my energy, but not in a magical way; I still had tired days.","zh":"運動改善了我的精神，但不是以神奇的方式；我仍然會有疲累的日子。"},{"en":"Good study habits help, though not in a magical way, because progress still requires time and practice.","zh":"良好學習習慣有幫助，但不是以神奇的方式，因為進步仍需要時間和練習。"},{"en":"Saying a change happened not in a magical way makes the description more realistic.","zh":"說改變不是以神奇的方式出現，可以令描述更現實可信。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"movie-ending kind of way","meaning":"像電影結局那樣","examples":[{"en":"The challenge did not change me in a movie-ending kind of way.","zh":"這個挑戰沒有像電影結局那樣徹底改變我。"},{"en":"A movie-ending kind of way suggests a dramatic, neat transformation in which all problems seem solved at once.","zh":"「像電影結局那樣」暗示一種戲劇性而完整的轉變，好像所有問題一下子都得到解決。"},{"en":"Finishing school did not change my life in a movie-ending kind of way; I still had many decisions to make.","zh":"畢業沒有像電影結局那樣改變我的人生；我仍然有很多決定要作。"},{"en":"Real relationships rarely improve in a movie-ending kind of way because rebuilding trust takes time.","zh":"真實關係很少會像電影結局那樣突然改善，因為重建信任需要時間。"},{"en":"Life can improve without giving us a perfect movie-ending kind of ending.","zh":"人生可以變得更好，而不需要出現完美的電影式結局。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"get annoyed","meaning":"感到煩躁；生氣","examples":[{"en":"I still get annoyed sometimes.","zh":"我有時仍然會感到煩躁。"},{"en":"To get annoyed means to become slightly angry, irritated, or bothered by something.","zh":"「感到煩躁」指因某件事而變得有點生氣、惱火或受困擾。"},{"en":"I get annoyed when someone plays loud music while I am trying to study.","zh":"當我溫習時有人播放很大聲的音樂，我會感到煩躁。"},{"en":"People may get annoyed more easily when they are tired or under pressure.","zh":"人疲累或有壓力時，可能更容易感到煩躁。"},{"en":"Learning gratitude does not mean you never get annoyed; it changes how you deal with the feeling.","zh":"學會感恩不代表永遠不會煩躁，而是改變你處理這種感受的方法。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"worry about exams","meaning":"擔心考試","examples":[{"en":"I still worry about exams.","zh":"我仍然會擔心考試。"},{"en":"To worry about exams means to feel anxious about upcoming tests, results, or your ability to perform well.","zh":"「擔心考試」指對即將來臨的測驗、成績或自己的表現感到焦慮。"},{"en":"I worry about exams most when I feel I have not revised enough.","zh":"當我覺得溫習不足時，我最容易擔心考試。"},{"en":"Starting revision earlier can reduce how much students worry about exams.","zh":"早一點開始溫習可以減少學生擔心考試的程度。"},{"en":"It is normal to worry about exams sometimes, but constant anxiety can make studying harder.","zh":"偶爾擔心考試很正常，但持續焦慮會令學習更困難。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"compare myself with others","meaning":"拿自己和別人比較","examples":[{"en":"I still compare myself with others more often than I should.","zh":"我仍然比應該的更頻密地拿自己和別人比較。"},{"en":"To compare myself with others means to judge my qualities, progress, or success against other people’s.","zh":"「拿自己和別人比較」指把自己的能力、進度或成功與別人的作比較。"},{"en":"I compare myself with others when I see classmates sharing their highest marks online.","zh":"當我看到同學在網上分享最高分時，我會拿自己和別人比較。"},{"en":"If I constantly compare myself with others, I may overlook the progress I have made personally.","zh":"如果我不斷拿自己和別人比較，可能會忽略自己已取得的進步。"},{"en":"Comparing myself with others can provide information, but it should not become the main way I judge my worth.","zh":"拿自己和別人比較可以提供一些資料，但不應成為判斷自我價值的主要方法。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"more often than I should","meaning":"比我應該做的更頻密","examples":[{"en":"I compare myself with others more often than I should.","zh":"我拿自己和別人比較的次數，比我應該做的更頻密。"},{"en":"“More often than I should” means I do something more frequently than I believe is healthy, necessary, or sensible.","zh":"「比我應該做的更頻密」表示我做某件事的次數超過自己認為健康、必要或合理的程度。"},{"en":"I check my phone more often than I should when I am supposed to be studying.","zh":"溫習時，我查看電話的次數比應該的更頻密。"},{"en":"If I apologise more often than I should, I may take responsibility for things that are not my fault.","zh":"如果我道歉得比應該的更頻密，可能會為不屬於自己的責任負責。"},{"en":"The phrase shows that the speaker recognises a habit is happening too frequently.","zh":"這個說法表示說話者已意識到某個習慣出現得太頻密。"}],"source":"2021 Q6.pdf","sourcePage":12},{"front":"no longer as quick to assume","meaning":"不再那麼快就假定","examples":[{"en":"I am no longer as quick to assume that a difficult day is an empty day.","zh":"我不再那麼快就假定艱難的一天是空無收穫的一天。"},{"en":"To be no longer as quick to assume something means to stop reaching that conclusion so rapidly without enough thought.","zh":"「不再那麼快就假定……」指不再沒有充分思考便迅速得出某個結論。"},{"en":"I am no longer as quick to assume that a quiet classmate is unfriendly.","zh":"我不再那麼快就假定安靜的同學不友善。"},{"en":"More experience made me no longer as quick to assume that one mistake meant a plan had failed.","zh":"更多經驗令我不再那麼快就假定一次錯誤代表整個計劃失敗。"},{"en":"Being less quick to assume gives us time to consider other explanations.","zh":"不急着作出假定，可以給我們時間考慮其他解釋。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"a difficult day","meaning":"艱難的一天","examples":[{"en":"A difficult day is not necessarily an empty day.","zh":"艱難的一天不一定是空無收穫的一天。"},{"en":"A difficult day is a day containing stress, disappointment, conflict, tiredness, or other challenges.","zh":"「艱難的一天」指包含壓力、失望、衝突、疲累或其他困難的一天。"},{"en":"Missing the bus and doing badly on a quiz made Tuesday a difficult day.","zh":"錯過巴士和小測表現差，令星期二成為艱難的一天。"},{"en":"A difficult day can still contain supportive people, small successes, and useful lessons.","zh":"艱難的一天仍然可以包含支持你的人、小成功和有用的教訓。"},{"en":"Calling a day difficult describes its challenges; it does not mean nothing good happened.","zh":"說一天艱難是在描述它的困難，並不表示完全沒有好事發生。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"an empty day","meaning":"空無收穫的一天","examples":[{"en":"I no longer assume that a difficult day is an empty day.","zh":"我不再假定艱難的一天就是空無收穫的一天。"},{"en":"An empty day, in this context, means a day that seems to contain nothing valuable, meaningful, or worth appreciating.","zh":"在這個語境中，「空無收穫的一天」指看起來沒有任何有價值、有意義或值得珍惜事情的一天。"},{"en":"I thought Sunday had been an empty day until I remembered the long conversation with my father.","zh":"我原以為星期日是空無收穫的一天，直到想起與爸爸的一次長談。"},{"en":"A day can feel empty when disappointment makes us overlook small positive moments.","zh":"當失望令我們忽略細小的正面時刻，一天可能感覺空空的。"},{"en":"A quiet or difficult day is not automatically an empty day.","zh":"安靜或艱難的一天，不會自動等於空無收穫的一天。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"a small pause between…and…","meaning":"……與……之間的小停頓","examples":[{"en":"Gratitude has become a small pause between what happens and how I understand it.","zh":"感恩已變成發生的事情與我如何理解它之間的一個小停頓。"},{"en":"A small pause between two things is a brief moment of reflection before moving from the first to the second.","zh":"「……與……之間的小停頓」指從第一件事轉到第二件事之前，一個短暫的反思時刻。"},{"en":"Taking a breath creates a small pause between hearing criticism and answering it.","zh":"深呼吸可以在聽到批評與作出回答之間創造一個小停頓。"},{"en":"A small pause between feeling angry and sending a message can prevent an impulsive reply.","zh":"在感到生氣與傳出訊息之間有一個小停頓，可以防止衝動回覆。"},{"en":"Even a small pause between an event and our reaction can create room for a different interpretation.","zh":"即使事件與反應之間只有一個小停頓，也可以為不同的理解留出空間。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"what happens to me","meaning":"發生在我身上的事","examples":[{"en":"Gratitude changes how I understand what happens to me.","zh":"感恩改變了我理解發生在我身上的事情的方式。"},{"en":"“What happens to me” refers to the events and experiences that I personally go through.","zh":"「發生在我身上的事」指我親身經歷的事件和經驗。"},{"en":"I cannot control everything that happens to me, but I can decide how to respond.","zh":"我不能控制所有發生在我身上的事，但可以決定如何回應。"},{"en":"Writing a journal helps me see patterns in what happens to me during stressful weeks.","zh":"寫日記幫助我看見壓力大的星期裏發生在我身上的事情有甚麼模式。"},{"en":"Understanding what happens to me includes both the event itself and the meaning I give it.","zh":"理解發生在我身上的事，包括事件本身，也包括我賦予它的意義。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"how I choose to understand it","meaning":"我選擇如何理解它","examples":[{"en":"Gratitude affects how I choose to understand difficult experiences.","zh":"感恩影響我選擇如何理解艱難的經歷。"},{"en":"“How I choose to understand it” means the interpretation or meaning I deliberately give to an experience.","zh":"「我選擇如何理解它」指我有意識地賦予一段經歷的解釋或意義。"},{"en":"Missing the opportunity hurt, but I could choose to understand it as a reason to prepare better next time.","zh":"錯過那個機會令人難受，但我可以選擇把它理解為下次準備得更好的理由。"},{"en":"How I choose to understand a mistake affects whether I learn from it or simply feel ashamed.","zh":"我選擇如何理解一個錯誤，會影響我是從中學習，還是只感到羞愧。"},{"en":"We cannot choose every event, but we often have some choice in how we understand it.","zh":"我們不能選擇每件發生的事，但通常可以在如何理解它方面作出一些選擇。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"going forward","meaning":"展望將來；往後","examples":[{"en":"Going forward, I plan to keep writing three lines every night.","zh":"往後，我計劃繼續每晚寫三行。"},{"en":"“Going forward” means from now on and into the future.","zh":"「往後」表示從現在開始並延續到未來。"},{"en":"Going forward, our group will meet every Monday instead of arranging meetings at the last minute.","zh":"往後，我們小組會每逢星期一開會，而不是最後一刻才安排。"},{"en":"We learned from the mistake, so going forward we will check the figures twice.","zh":"我們已從錯誤中學習，所以往後會把數字檢查兩次。"},{"en":"“Going forward” is useful when explaining what you intend to do differently in the future.","zh":"當解釋未來打算如何做得不同時，「往後」是一個很有用的說法。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"keep writing","meaning":"繼續寫","examples":[{"en":"I plan to keep writing three lines every night.","zh":"我計劃繼續每晚寫三行。"},{"en":"To keep writing means to continue writing instead of stopping.","zh":"「繼續寫」指不停止，而是把寫作持續下去。"},{"en":"Even when I ran out of ideas, I kept writing until I had explained the experience clearly.","zh":"即使我一時沒有想法，也繼續寫，直到把經歷解釋清楚。"},{"en":"If students keep writing regularly, expressing ideas usually becomes easier with practice.","zh":"如果學生持續規律地寫，表達想法通常會隨練習變得更容易。"},{"en":"You do not need to write a lot; the important thing may simply be to keep writing consistently.","zh":"你不需要寫很多；重要的可能只是持續地繼續寫。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"three lines every night","meaning":"每晚三行","examples":[{"en":"I plan to write three lines every night.","zh":"我計劃每晚寫三行。"},{"en":"“Three lines every night” describes a small, specific writing habit repeated each evening.","zh":"「每晚三行」描述每天晚上重複的一個細小而具體的寫作習慣。"},{"en":"Writing three lines every night felt manageable even on busy school days.","zh":"即使在繁忙的上學日，每晚寫三行仍然是可以做到的。"},{"en":"Because the goal was only three lines every night, I was less likely to give up when tired.","zh":"因為目標只是每晚三行，即使疲累，我也較不容易放棄。"},{"en":"A small target such as three lines every night can be easier to maintain than an ambitious daily essay.","zh":"每晚三行這類小目標，通常比每天寫長文更容易維持。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"especially on days when","meaning":"尤其是在……的日子","examples":[{"en":"I will keep writing, especially on days when I feel I have nothing to say.","zh":"我會繼續寫，尤其是在我覺得沒有話可說的日子。"},{"en":"“Especially on days when” highlights particular days on which an action is even more important or relevant.","zh":"「尤其是在……的日子」突出某些日子，在那些日子某個行動更加重要或相關。"},{"en":"I try to walk outside, especially on days when I have been sitting at my desk for hours.","zh":"我會盡量到外面走走，尤其是在我已經坐在書桌前數小時的日子。"},{"en":"Checking on friends matters especially on days when they seem unusually quiet.","zh":"關心朋友很重要，尤其是在他們顯得異常安靜的日子。"},{"en":"A good habit is valuable on ordinary days, but especially on days when following it feels difficult.","zh":"好習慣在普通日子很有價值，但尤其是在很難堅持的日子更重要。"}],"source":"2021 Q6.pdf","sourcePage":13},{"front":"have nothing to say","meaning":"沒有話可說","examples":[{"en":"Some days, I feel I have nothing to say.","zh":"有些日子，我覺得自己沒有話可說。"},{"en":"To have nothing to say means to feel that no ideas, comments, or experiences come to mind to express.","zh":"「沒有話可說」指感覺想不到任何想法、評論或經歷可以表達。"},{"en":"I opened the blank page and felt I had nothing to say about the ordinary school day.","zh":"我打開空白的一頁，覺得對那個普通的上學日沒有話可說。"},{"en":"Feeling that you have nothing to say can disappear once you begin with one small detail.","zh":"當你從一個小細節開始時，「沒有話可說」的感覺可能會消失。"},{"en":"“I have nothing to say” often means nothing feels important enough to mention, not that absolutely nothing happened.","zh":"「我沒有話可說」通常表示沒有事情感覺重要得值得提起，而不是真的甚麼都沒有發生。"}],"source":"2021 Q6.pdf","sourcePage":14},{"front":"wondering whether","meaning":"想知道是否","examples":[{"en":"You may be wondering whether twenty-one days can really matter.","zh":"你可能正在想，二十一天是否真的有意義。"},{"en":"“Wondering whether” means thinking about a question because you are uncertain which answer is true.","zh":"「想知道是否」指因不確定哪個答案是真的，而在思考一個問題。"},{"en":"I was wondering whether I should take the earlier bus because rain was expected.","zh":"因為預計會下雨，我在想是否應該乘較早的巴士。"},{"en":"Parents may be wondering whether a new study method will actually help their child.","zh":"家長可能想知道新的學習方法是否真的能幫到孩子。"},{"en":"“Wondering whether” is useful for introducing a question or uncertainty without stating a definite answer yet.","zh":"「想知道是否」適合用來引出一個問題或不確定情況，而不立即給出確定答案。"}],"source":"2021 Q6.pdf","sourcePage":14},{"front":"can really matter","meaning":"真的有意義；真的重要","examples":[{"en":"Twenty-one days can really matter if you notice small changes.","zh":"如果你留意細小改變，二十一天真的可以有意義。"},{"en":"If something can really matter, it can have a genuine and meaningful effect rather than being unimportant.","zh":"如果某件事「真的有意義」，表示它能帶來真實而有價值的影響，而不是無關重要。"},{"en":"Ten minutes of daily reading can really matter when the habit continues for months.","zh":"如果每天十分鐘閱讀的習慣持續數月，它真的可以帶來重要影響。"},{"en":"One supportive comment can really matter to a student who is close to giving up.","zh":"對一個接近放棄的學生來說，一句支持的話真的可以很重要。"},{"en":"Small actions can really matter when they are repeated or arrive at exactly the right time.","zh":"當小行動重複出現，或剛好在最需要時出現，它們真的可以很重要。"}],"source":"2021 Q6.pdf","sourcePage":14},{"front":"the best things in life","meaning":"生命中最美好的事物","examples":[{"en":"The best things in life may be free.","zh":"生命中最美好的事物可能是免費的。"},{"en":"“The best things in life” refers to experiences or relationships that give people deep happiness, meaning, or value.","zh":"「生命中最美好的事物」指帶給人深刻快樂、意義或價值的經歷和關係。"},{"en":"Friendship, laughter, family time, and a peaceful walk can be among the best things in life.","zh":"友誼、笑聲、家庭時間和平靜散步，都可以是生命中最美好的事物。"},{"en":"The best things in life are not always expensive because emotional value cannot be measured by price alone.","zh":"生命中最美好的事物不一定昂貴，因為情感價值不能只用價錢衡量。"},{"en":"People often recognise the best things in life only after they stop taking ordinary moments for granted.","zh":"人們常在不再把普通時刻視為理所當然後，才看見生命中最美好的事物。"}],"source":"2021 Q6.pdf","sourcePage":14},{"front":"may be free","meaning":"可能是免費的","examples":[{"en":"The best things in life may be free.","zh":"生命中最美好的事物可能是免費的。"},{"en":"“May be free” means something can sometimes be enjoyed without paying money for it.","zh":"「可能是免費的」表示某件事有時不需要付錢也可以享受。"},{"en":"Watching the sunset with a friend may be free, but the memory can still be valuable.","zh":"和朋友一起看日落可能是免費的，但那段回憶仍可以很珍貴。"},{"en":"A kind conversation may be free because it costs no money, yet it can greatly improve someone’s day.","zh":"一次友善的交談可能是免費的，因為不用花錢，卻可以大大改善某人的一天。"},{"en":"Things that may be free are not necessarily worthless; price and value are different.","zh":"可能是免費的東西不代表沒有價值；價格與價值並不相同。"}],"source":"2021 Q6.pdf","sourcePage":14},{"front":"still have to notice them","meaning":"仍然要留意它們","examples":[{"en":"The best things may be free, but we still have to notice them.","zh":"最美好的事物可能是免費的，但我們仍然要留意它們。"},{"en":"“Still have to notice them” means that even when good things are already present, we must pay attention before we can appreciate them.","zh":"「仍然要留意它們」表示即使美好的事已經存在，我們仍必須先注意到，才能真正珍惜。"},{"en":"A friend may quietly support us every day, but we still have to notice those actions to understand their value.","zh":"朋友可能每天默默支持我們，但我們仍然要留意這些行動，才明白它們的價值。"},{"en":"Busy routines can hide ordinary joys, so we still have to notice them deliberately.","zh":"忙碌的日常生活可能遮蓋平凡的快樂，所以我們仍然要刻意留意它們。"},{"en":"Good things do not automatically improve our lives simply by existing; we still have to notice them.","zh":"美好的事不會只因存在就自動改善人生；我們仍然要留意它們。"}],"source":"2021 Q6.pdf","sourcePage":14}],"dse/writing/part-b/2021/Q7":[{"front":"after midnight","meaning":"午夜過後","examples":[{"en":"The story takes place after midnight at Page & Co.","zh":"故事發生在午夜過後的 Page & Co.。"},{"en":"After midnight means after 12 o’clock at night.","zh":"after midnight 指晚上十二點之後。"},{"en":"The streets are usually quiet after midnight because most shops are closed.","zh":"午夜過後街道通常很安靜，因為大部分商店都關門了。"},{"en":"People may feel nervous after midnight when they are alone in a dark building.","zh":"午夜過後，如果一個人獨自在黑暗的建築物裏，可能會感到緊張。"},{"en":"A phone call after midnight often feels urgent or frightening.","zh":"午夜過後接到電話，通常會令人覺得事情很緊急或可怕。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"clocked in","meaning":"打卡上班","examples":[{"en":"Mr Wong clocked in at 11:45 p.m.","zh":"黃先生在晚上十一時四十五分打卡上班。"},{"en":"To clock in means to record the time when you start work.","zh":"clock in 指記錄開始工作的時間。"},{"en":"Nurses clock in before their shift so the hospital knows they are on duty.","zh":"護士在輪班前打卡上班，讓醫院知道她們正在當值。"},{"en":"If workers forget to clock in, their working hours may not be recorded correctly.","zh":"如果員工忘記打卡上班，他們的工作時數可能不會被正確記錄。"},{"en":"Mr Wong clocked in, but by morning he would never clock out.","zh":"黃先生打卡上班了，但到了早上，他再也沒有打卡下班。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"smelled of","meaning":"有……的氣味","examples":[{"en":"Page & Co. already smelled of dust, glue and rain.","zh":"Page & Co. 已經有灰塵、膠水和雨水的氣味。"},{"en":"If a place smells of something, that smell fills the air there.","zh":"如果一個地方 smells of 某種東西，就是空氣中充滿那種氣味。"},{"en":"The kitchen smelled of fresh bread after Grandma opened the oven.","zh":"奶奶打開焗爐後，廚房有新鮮麵包的氣味。"},{"en":"A classroom may smell of paint after workers repair the walls.","zh":"工人修補牆壁後，課室可能會有油漆的氣味。"},{"en":"The old coat smelled of smoke, so Dad washed it before wearing it.","zh":"那件舊外套有煙味，所以爸爸穿之前先把它洗乾淨。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"dust, glue and rain","meaning":"灰塵、膠水和雨水的氣味","examples":[{"en":"The bookshop smelled of dust, glue and rain.","zh":"書店有灰塵、膠水和雨水的氣味。"},{"en":"Dust, glue and rain suggest an old, damp place full of books and paper.","zh":"dust, glue and rain 暗示一個又舊又潮濕、充滿書和紙的地方。"},{"en":"After the storm, the school library smelled of dust, glue and rain.","zh":"暴風雨過後，學校圖書館有灰塵、膠水和雨水的氣味。"},{"en":"The smell of dust, glue and rain made the closed shop feel older and lonelier.","zh":"灰塵、膠水和雨水的氣味令關了門的商店感覺更古老、更孤單。"},{"en":"Some readers like the smell of dust, glue and rain because it reminds them of old books.","zh":"有些讀者喜歡灰塵、膠水和雨水的氣味，因為它令他們想起舊書。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"the last cashier left","meaning":"最後一位收銀員離開","examples":[{"en":"The bookshop changed after the last cashier left.","zh":"最後一位收銀員離開後，書店變了。"},{"en":"The last cashier left means the final shop worker at the till went away.","zh":"the last cashier left 指最後一位在收銀處工作的店員離開了。"},{"en":"After the last cashier left, the supermarket became quiet and empty.","zh":"最後一位收銀員離開後，超級市場變得安靜又空蕩。"},{"en":"When the last cashier left, Mr Wong became the only person watching the shop.","zh":"最後一位收銀員離開後，黃先生成了唯一看守書店的人。"},{"en":"A place can feel very different after the last cashier left and the lights are dimmed.","zh":"最後一位收銀員離開、燈光變暗後，一個地方會感覺很不同。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"became his kingdom","meaning":"成了他的地盤；成了他的王國","examples":[{"en":"After the last cashier left, the bookshop became his kingdom.","zh":"最後一位收銀員離開後，書店成了他的地盤。"},{"en":"Became his kingdom means the place felt completely under his control.","zh":"became his kingdom 指那個地方感覺完全由他掌控。"},{"en":"When the children went to bed, the quiet living room became Mum’s kingdom.","zh":"孩子上床睡覺後，安靜的客廳成了媽媽的地盤。"},{"en":"The empty classroom became the cleaner’s kingdom after all the students left.","zh":"所有學生離開後，空課室成了清潔工人的地盤。"},{"en":"Mr Wong felt brave because the silent bookshop had become his kingdom.","zh":"黃先生覺得勇敢，因為寂靜的書店已成了他的王國。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"security room","meaning":"保安室","examples":[{"en":"He spent the night in the security room.","zh":"他在保安室裏度過整晚。"},{"en":"A security room is a place where guards watch cameras and alarms.","zh":"security room 是保安員觀看鏡頭和警報的地方。"},{"en":"The mall’s security room has screens showing every entrance.","zh":"商場的保安室有螢幕顯示每個入口。"},{"en":"If an alarm rings, guards in the security room can check where the problem is.","zh":"如果警報響起，保安室裏的保安員可以查看問題在哪裏。"},{"en":"Mr Wong thought the security room would keep him safe from the dark shop.","zh":"黃先生以為保安室能令他避開黑暗書店，保持安全。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"grey monitors","meaning":"灰色監視器","examples":[{"en":"The security room had sixteen grey monitors.","zh":"保安室裏有十六部灰色監視器。"},{"en":"Grey monitors are plain grey screens used for watching camera footage.","zh":"grey monitors 是用來觀看閉路電視畫面的灰色螢幕。"},{"en":"The guard stared at the grey monitors to check the empty corridors.","zh":"保安員盯着灰色監視器，檢查空蕩的走廊。"},{"en":"If one of the grey monitors goes black, the guard may not see danger clearly.","zh":"如果其中一部灰色監視器變黑，保安員可能無法清楚看見危險。"},{"en":"The grey monitors made the room feel cold, dull, and watchful.","zh":"灰色監視器令房間感覺冰冷、沉悶，而且像在監視一切。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"a dented flask","meaning":"凹了的保溫壺","examples":[{"en":"There was a dented flask on the desk.","zh":"桌上有一個凹了的保溫壺。"},{"en":"A dented flask is a drink bottle with a hollow mark from being hit or dropped.","zh":"a dented flask 是一個因被撞或掉下而有凹痕的飲品壺。"},{"en":"Dad still uses a dented flask because it keeps tea hot.","zh":"爸爸仍然使用那個凹了的保溫壺，因為它能保溫茶水。"},{"en":"The flask became dented when it rolled off the table and hit the floor.","zh":"保溫壺從桌上滾下撞到地面，所以凹了。"},{"en":"The dented flask showed that Mr Wong had worked many long night shifts.","zh":"那個凹了的保溫壺顯示黃先生已經做過很多漫長夜班。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"survive until the next morning","meaning":"撐到翌日早上","examples":[{"en":"He had six hours to survive until the next morning.","zh":"他還有六小時要撐到翌日早上。"},{"en":"To survive until the next morning means to stay safe through the night.","zh":"survive until the next morning 指平安熬過整晚直到第二天早上。"},{"en":"Campers had to survive until the next morning when heavy rain trapped them on the hill.","zh":"大雨把露營者困在山上，他們必須撐到翌日早上。"},{"en":"A sick child may need medicine to survive until the next morning before seeing a doctor.","zh":"生病的孩子可能需要藥物撐到翌日早上，然後才去看醫生。"},{"en":"Mr Wong only wanted to survive until the next morning and leave the shop.","zh":"黃先生只想撐到翌日早上，然後離開書店。"}],"source":"2021 Q7.pdf","sourcePage":1},{"front":"door sensor","meaning":"門感應器","examples":[{"en":"The door sensor at the rear kept acting up.","zh":"後方的門感應器不斷出問題。"},{"en":"A door sensor is a device that notices when a door opens or closes.","zh":"door sensor 是感應門何時開關的裝置。"},{"en":"The shop’s door sensor rings whenever a customer enters.","zh":"每當顧客進入，商店的門感應器就會響。"},{"en":"If a door sensor fails, an open door may not trigger an alarm.","zh":"如果門感應器失靈，門打開時可能不會觸發警報。"},{"en":"The broken door sensor made Mr Wong worry about the rear entrance.","zh":"壞掉的門感應器令黃先生擔心後方入口。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"at the rear","meaning":"在後方","examples":[{"en":"The door sensor at the rear kept acting up.","zh":"在後方的門感應器不斷出問題。"},{"en":"At the rear means at the back part of a place or vehicle.","zh":"at the rear 指在某地方或車輛的後面部分。"},{"en":"The emergency exit is at the rear of the cinema.","zh":"緊急出口在戲院後方。"},{"en":"A delivery van stopped at the rear of the shop to unload boxes.","zh":"一輛送貨車停在店舖後方卸下箱子。"},{"en":"Strange sounds at the rear of the building made the guard nervous.","zh":"建築物後方傳來怪聲，令保安員感到緊張。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"keep acting up","meaning":"不斷出問題","examples":[{"en":"The rear door sensor keeps acting up.","zh":"後門感應器不斷出問題。"},{"en":"If a machine keeps acting up, it keeps working badly or strangely.","zh":"如果機器 keeps acting up，就是它不斷運作不正常或很古怪。"},{"en":"My phone keeps acting up and turns off by itself.","zh":"我的電話不斷出問題，會自己關機。"},{"en":"When the printer keeps acting up, students cannot print their homework on time.","zh":"打印機不斷出問題時，學生就不能準時列印功課。"},{"en":"Mr Wong hoped the sensor was only acting up, not warning him of danger.","zh":"黃先生希望感應器只是出問題，而不是在警告他有危險。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"I can handle","meaning":"我應付得來","examples":[{"en":"Mr Wong said he could handle a bookshop.","zh":"黃先生說他應付得來一間書店。"},{"en":"I can handle means I can deal with the situation successfully.","zh":"I can handle 指我能成功處理這個情況。"},{"en":"A student may say, “I can handle this test,” after studying hard.","zh":"學生努力溫習後，可能會說：「這次測驗我應付得來。」"},{"en":"If a worker has enough training, they can handle difficult customers calmly.","zh":"如果員工有足夠訓練，他們可以冷靜應付難纏的顧客。"},{"en":"Mr Wong thought he could handle the bookshop, but the night proved otherwise.","zh":"黃先生以為自己應付得來書店，但那一晚證明並非如此。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"Books remember things","meaning":"書會記住事情","examples":[{"en":"Nico warned him that books remember things.","zh":"尼科警告他，書會記住事情。"},{"en":"Books remember things suggests that stories can keep secrets, memories, or past events alive.","zh":"Books remember things 暗示故事能保存秘密、記憶或過去發生的事。"},{"en":"A diary seems to remember things because it records what people forget.","zh":"日記像會記住事情，因為它記錄了人們會忘記的事。"},{"en":"Old library books may feel as if they remember every hand that touched them.","zh":"舊圖書館的書可能令人覺得它們記得每一隻碰過它們的手。"},{"en":"Nico’s warning made the bookshop sound less like a shop and more like something alive.","zh":"尼科的警告令書店聽起來不像商店，而像某種活物。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"the words stayed with him","meaning":"那些話一直縈繞在心頭","examples":[{"en":"After Nico left, the words stayed with him.","zh":"尼科離開後，那些話一直縈繞在他心頭。"},{"en":"If words stay with someone, they keep thinking about them.","zh":"如果 words stay with someone，就是那些話令人一直想着。"},{"en":"The teacher’s advice stayed with me before the exam.","zh":"考試前，老師的建議一直縈繞在我心頭。"},{"en":"A warning may stay with a person when the situation becomes dangerous.","zh":"當情況變得危險時，警告可能會一直留在一個人心裏。"},{"en":"Nico’s words stayed with Mr Wong because they sounded strange and serious.","zh":"尼科的話一直縈繞在黃先生心頭，因為那些話聽起來奇怪又嚴肅。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"for the first hour","meaning":"起初的一小時","examples":[{"en":"For the first hour, nothing moved except the second hand of the clock.","zh":"起初的一小時，除了時鐘的秒針外，沒有東西動。"},{"en":"For the first hour means during the first sixty minutes.","zh":"for the first hour 指在最初六十分鐘裏。"},{"en":"For the first hour of the lesson, students revised old vocabulary.","zh":"課堂起初的一小時，學生複習舊詞彙。"},{"en":"A new worker may feel nervous for the first hour of a night shift.","zh":"新員工在夜班起初的一小時可能會感到緊張。"},{"en":"For the first hour, the silence made Mr Wong believe nothing would happen.","zh":"起初的一小時，那份寂靜令黃先生相信不會有事發生。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"nothing moved except","meaning":"除了……之外沒有東西動","examples":[{"en":"Nothing moved except the second hand of the clock.","zh":"除了時鐘的秒針外，沒有東西動。"},{"en":"Nothing moved except means everything was still apart from one small thing.","zh":"nothing moved except 指一切都靜止，只有一樣小東西在動。"},{"en":"In the empty classroom, nothing moved except the curtains in the wind.","zh":"空課室裏，除了被風吹動的窗簾外，沒有東西動。"},{"en":"A scene can feel frightening when nothing moves except a shadow.","zh":"當除了影子外沒有東西動時，場景會令人覺得可怕。"},{"en":"Nothing moved except the clock, so the silence felt even deeper.","zh":"除了時鐘外沒有東西動，所以寂靜感更深。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"the second hand of the clock","meaning":"時鐘的秒針","examples":[{"en":"The second hand of the clock clicked its way towards two.","zh":"時鐘的秒針滴答滴答地走向兩點。"},{"en":"The second hand of the clock is the thin hand that counts seconds.","zh":"the second hand of the clock 是時鐘上計算秒數的幼針。"},{"en":"During the exam, I watched the second hand of the clock move too quickly.","zh":"考試時，我看着時鐘的秒針走得太快。"},{"en":"In a silent room, the second hand of the clock can sound unusually loud.","zh":"在安靜的房間裏，時鐘的秒針聽起來可以異常響亮。"},{"en":"Mr Wong stared at the second hand of the clock as the night passed slowly.","zh":"黃先生盯着時鐘的秒針，看着夜晚慢慢過去。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"clicked its way towards","meaning":"滴答滴答地走向","examples":[{"en":"The second hand clicked its way towards one, then two.","zh":"秒針滴答滴答地走向一點，然後走向兩點。"},{"en":"Clicked its way towards means moved slowly with repeated clicking sounds.","zh":"clicked its way towards 指伴隨重複的滴答聲慢慢移向某處。"},{"en":"The old train clicked its way towards the next station.","zh":"舊火車咔嗒咔嗒地駛向下一個車站。"},{"en":"The lift clicked its way towards the top floor, making everyone listen.","zh":"升降機咔嗒咔嗒地升向頂樓，令所有人都留心聽。"},{"en":"The clock clicked its way towards morning, but Mr Wong felt no safer.","zh":"時鐘滴答滴答地走向早晨，但黃先生沒有感到更安全。"}],"source":"2021 Q7.pdf","sourcePage":2},{"front":"beneath a thin blue light","meaning":"在微弱的藍光下","examples":[{"en":"The counter slept beneath a thin blue light.","zh":"櫃枱在微弱的藍光下沉睡。"},{"en":"Beneath a thin blue light means under a weak, pale blue light.","zh":"beneath a thin blue light 指在微弱、淡藍色的光線下。"},{"en":"The hospital corridor looked cold beneath a thin blue light.","zh":"醫院走廊在微弱的藍光下顯得冰冷。"},{"en":"A room can feel lonely beneath a thin blue light because colours look faded.","zh":"房間在微弱的藍光下會令人覺得孤單，因為顏色看起來很淡。"},{"en":"The counter seemed almost alive as it rested beneath a thin blue light.","zh":"櫃枱在微弱的藍光下靜靜躺着，彷彿有生命。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"stood shut","meaning":"緊閉着","examples":[{"en":"On Camera 6, the rear door stood shut.","zh":"在六號鏡頭裏，後門緊閉着。"},{"en":"Stood shut means remained closed and did not move.","zh":"stood shut 指保持關閉，沒有移動。"},{"en":"The school gate stood shut after the final bell.","zh":"最後鐘聲響起後，校門緊閉着。"},{"en":"If a door stands shut all night, people believe no one has entered.","zh":"如果一道門整晚緊閉着，人們會相信沒有人進入。"},{"en":"The rear door stood shut at first, but later it began to swing.","zh":"後門起初緊閉着，但後來開始慢慢擺動。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"shoulders bent","meaning":"肩膊彎着；駝着背","examples":[{"en":"Mr Wong saw himself sitting with his shoulders bent.","zh":"黃先生看見自己坐着，肩膊彎着。"},{"en":"Shoulders bent means the shoulders are curved forward, often from tiredness.","zh":"shoulders bent 指肩膊向前彎曲，通常因疲倦而出現。"},{"en":"The old man walked home with his shoulders bent under the heavy bag.","zh":"老人揹着沉重袋子回家，肩膊彎着。"},{"en":"Students may sit with shoulders bent when they are tired or worried.","zh":"學生疲倦或擔心時，可能會駝着背坐着。"},{"en":"Mr Wong’s bent shoulders made him look weaker on the screen.","zh":"黃先生彎着的肩膊令他在螢幕上看起來更虛弱。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"eyes heavy","meaning":"眼皮沉重","examples":[{"en":"His eyes were heavy even though he was awake.","zh":"即使他醒着，他的眼皮仍然沉重。"},{"en":"Eyes heavy means someone feels very sleepy and struggles to keep their eyes open.","zh":"eyes heavy 指一個人很睏，很難保持眼睛張開。"},{"en":"My eyes were heavy after I studied until midnight.","zh":"我溫習到午夜後，眼皮很沉重。"},{"en":"When a driver’s eyes become heavy, they should stop and rest.","zh":"當司機眼皮變得沉重時，應該停下來休息。"},{"en":"Mr Wong’s eyes grew heavy as if sleep were being pushed onto him.","zh":"黃先生的眼皮越來越沉重，好像睡意被強行壓到他身上。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"the strange thing was that","meaning":"奇怪的是","examples":[{"en":"The strange thing was that he was still wide awake.","zh":"奇怪的是，他仍然十分清醒。"},{"en":"The strange thing was that introduces something surprising or hard to explain.","zh":"the strange thing was that 用來引出令人意外或難以解釋的事情。"},{"en":"The strange thing was that the lost keys were on the table all along.","zh":"奇怪的是，遺失的鑰匙一直就在桌上。"},{"en":"The strange thing was that nobody heard the alarm, although it was loud.","zh":"奇怪的是，警報很響，卻沒有人聽見。"},{"en":"The strange thing was that Mr Wong felt sleepy and wide awake at the same time.","zh":"奇怪的是，黃先生同時覺得睏倦又十分清醒。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"wide awake","meaning":"十分清醒","examples":[{"en":"Mr Wong was still wide awake.","zh":"黃先生仍然十分清醒。"},{"en":"Wide awake means completely awake and not sleepy.","zh":"wide awake 指完全醒着，一點也不想睡。"},{"en":"The baby was wide awake at 2 a.m., so nobody could sleep.","zh":"嬰兒凌晨兩點仍然十分清醒，所以沒有人睡得着。"},{"en":"After drinking strong coffee, I stayed wide awake during the long bus ride.","zh":"喝了濃咖啡後，我在漫長巴士車程中一直十分清醒。"},{"en":"Mr Wong was wide awake, but something still pulled him towards sleep.","zh":"黃先生十分清醒，但仍有某種東西把他拉向睡眠。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"leaned closer","meaning":"靠近一點","examples":[{"en":"He leaned closer to look at the screen.","zh":"他靠近一點去看螢幕。"},{"en":"Leaned closer means moved the upper body nearer to see or hear better.","zh":"leaned closer 指上半身靠近，為了看得或聽得更清楚。"},{"en":"The student leaned closer to read the tiny writing on the board.","zh":"學生靠近一點去讀黑板上細小的字。"},{"en":"People lean closer when they do not want to miss an important whisper.","zh":"人們不想錯過重要耳語時，會靠近一點。"},{"en":"Mr Wong leaned closer because the image on the monitor looked wrong.","zh":"黃先生靠近一點，因為監視器上的畫面看起來不對勁。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"lowered his head onto","meaning":"把頭垂到……上","examples":[{"en":"The man lowered his head onto his arms.","zh":"那個男人把頭垂到手臂上。"},{"en":"Lowered his head onto means gently moved his head down until it rested on something.","zh":"lowered his head onto 指慢慢把頭低下，直到靠在某物上。"},{"en":"The tired child lowered his head onto the desk after lunch.","zh":"疲倦的孩子午飯後把頭垂到桌上。"},{"en":"A worker may lower his head onto his hands when he feels exhausted.","zh":"工人筋疲力盡時，可能會把頭垂到雙手上。"},{"en":"The man lowered his head onto his arms, as if sleep had suddenly taken him.","zh":"那個男人把頭垂到手臂上，彷彿睡意突然抓住了他。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"at the same moment","meaning":"與此同時","examples":[{"en":"At the same moment, Mr Wong felt his eyelids grow heavy.","zh":"與此同時，黃先生感到眼皮變得沉重。"},{"en":"At the same moment means at exactly the same time.","zh":"at the same moment 指在完全相同的時間。"},{"en":"At the same moment the lights went out, the phone rang.","zh":"與此同時，燈熄了，電話也響了。"},{"en":"Two students raised their hands at the same moment to answer the question.","zh":"兩名學生與此同時舉手回答問題。"},{"en":"At the same moment the man slept on screen, Mr Wong began to feel sleepy too.","zh":"螢幕上的男人睡着的同時，黃先生也開始感到睏倦。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"press down on","meaning":"壓在……上","examples":[{"en":"A weight seemed to press down on his eyelids.","zh":"一股重量好像壓在他的眼皮上。"},{"en":"Press down on means push something downward with force or pressure.","zh":"press down on 指用力或壓力把某物向下壓。"},{"en":"Press down on the lid until the box clicks shut.","zh":"把盒蓋向下壓，直到盒子咔一聲關上。"},{"en":"Stress can feel as if it is pressing down on a person’s chest.","zh":"壓力可以令人感覺好像有東西壓在胸口上。"},{"en":"Sleep seemed to press down on Mr Wong’s eyes until he could not fight it.","zh":"睡意好像壓在黃先生的眼睛上，直到他無法抵抗。"}],"source":"2021 Q7.pdf","sourcePage":3},{"front":"eyelids","meaning":"眼皮","examples":[{"en":"Mr Wong felt a weight press down on his eyelids.","zh":"黃先生感到有一股重量壓在他的眼皮上。"},{"en":"Eyelids are the pieces of skin that open and close over your eyes.","zh":"eyelids 是覆蓋眼睛、會開合的皮膚。"},{"en":"Her eyelids became red because she had not slept enough.","zh":"她睡眠不足，所以眼皮變紅了。"},{"en":"When people are tired, their eyelids may close without warning.","zh":"人疲倦時，眼皮可能會毫無預警地合上。"},{"en":"Mr Wong’s eyelids grew heavy, although he knew he should stay awake.","zh":"黃先生的眼皮變得沉重，雖然他知道自己應該保持清醒。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"stretched and blurred","meaning":"拉長並變得模糊","examples":[{"en":"The room stretched and blurred around him.","zh":"房間在他周圍拉長並變得模糊。"},{"en":"Stretched and blurred means shapes seemed longer and less clear.","zh":"stretched and blurred 指形狀好像被拉長，而且變得不清楚。"},{"en":"When I felt dizzy, the corridor stretched and blurred in front of me.","zh":"我感到暈眩時，眼前的走廊拉長並變得模糊。"},{"en":"A dream can make a familiar room stretch and blur into something strange.","zh":"夢境可以令熟悉的房間拉長並變得模糊，變成奇怪的地方。"},{"en":"The security room stretched and blurred as Mr Wong fell into an unnatural sleep.","zh":"當黃先生墮入不自然的睡眠時，保安室拉長並變得模糊。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"told himself to","meaning":"告訴自己要","examples":[{"en":"He told himself to stand up.","zh":"他告訴自己要站起來。"},{"en":"Told himself to means silently ordered or encouraged himself to do something.","zh":"told himself to 指在心裏命令或鼓勵自己做某事。"},{"en":"She told herself to stay calm before the interview.","zh":"面試前，她告訴自己要保持冷靜。"},{"en":"A swimmer may tell himself to keep going when he feels tired.","zh":"游泳者感到疲倦時，可能會告訴自己要繼續。"},{"en":"Mr Wong told himself to stand up, but his body would not obey.","zh":"黃先生告訴自己要站起來，但身體不聽使喚。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"jerked awake","meaning":"猛然驚醒","examples":[{"en":"Mr Wong jerked awake when the alarm screamed.","zh":"警報尖叫時，黃先生猛然驚醒。"},{"en":"Jerked awake means suddenly woke up with a quick, sharp movement.","zh":"jerked awake 指突然醒來，身體快速猛地一動。"},{"en":"I jerked awake when thunder shook the windows.","zh":"雷聲震動窗戶時，我猛然驚醒。"},{"en":"A loud crash can make someone jerk awake from deep sleep.","zh":"一聲巨響可以令人從熟睡中猛然驚醒。"},{"en":"Mr Wong jerked awake so suddenly that his flask fell from the desk.","zh":"黃先生驚醒得太突然，以致他的保溫壺從桌上掉下。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"so violently that","meaning":"猛烈得以致","examples":[{"en":"He jerked awake so violently that his flask rolled off the desk.","zh":"他猛然驚醒，猛烈得以致保溫壺從桌上滾落。"},{"en":"So violently that shows an action was so forceful that it caused a result.","zh":"so violently that 表示動作非常猛烈，因而造成某個結果。"},{"en":"The door slammed so violently that the window shook.","zh":"門關得猛烈，以致窗戶也震動。"},{"en":"The bus stopped so violently that passengers grabbed the seats.","zh":"巴士停得猛烈，以致乘客抓住座位。"},{"en":"Mr Wong woke so violently that the quiet room suddenly felt dangerous.","zh":"黃先生醒得太猛烈，以致安靜的房間突然變得危險。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"rolled off","meaning":"從……滾落","examples":[{"en":"His flask rolled off the desk.","zh":"他的保溫壺從桌上滾落。"},{"en":"Rolled off means moved over the edge and fell after turning round and round.","zh":"rolled off 指一邊滾動一邊越過邊緣掉下。"},{"en":"The pencil rolled off the table and landed under the chair.","zh":"鉛筆從桌上滾落，跌到椅子下面。"},{"en":"If a ball rolls off the pavement, it may go into the road.","zh":"如果球從行人路滾落，可能會滾到馬路上。"},{"en":"The flask rolled off the desk when Mr Wong suddenly woke up.","zh":"黃先生突然醒來時，保溫壺從桌上滾落。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"warning light","meaning":"警示燈","examples":[{"en":"A red warning light flashed beside Camera 6.","zh":"一盞紅色警示燈在六號鏡頭旁邊閃爍。"},{"en":"A warning light is a light that shows something may be wrong or dangerous.","zh":"warning light 是顯示可能有問題或危險的燈。"},{"en":"The car’s warning light came on when the engine overheated.","zh":"汽車引擎過熱時，警示燈亮起。"},{"en":"In a hospital, a warning light can tell nurses that a patient needs help.","zh":"在醫院裏，警示燈可以告訴護士有病人需要幫助。"},{"en":"The red warning light told Mr Wong that Camera 6 needed attention.","zh":"紅色警示燈告訴黃先生，六號鏡頭需要注意。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"flashed beside","meaning":"在……旁邊閃爍","examples":[{"en":"A red warning light flashed beside Camera 6.","zh":"一盞紅色警示燈在六號鏡頭旁邊閃爍。"},{"en":"Flashed beside means shone on and off quickly next to something.","zh":"flashed beside 指在某物旁邊快速亮起又熄滅。"},{"en":"A small light flashed beside the lift button.","zh":"一盞小燈在升降機按鈕旁邊閃爍。"},{"en":"When a warning flashes beside a screen, people know they should check it.","zh":"當警示在螢幕旁邊閃爍時，人們知道應該查看。"},{"en":"The red light flashed beside Camera 6 like a silent alarm.","zh":"紅燈在六號鏡頭旁邊閃爍，像一個無聲警報。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"not merely","meaning":"不只是","examples":[{"en":"The door was not merely open; it was swinging slowly.","zh":"那道門不只是打開了；它正在慢慢擺動。"},{"en":"Not merely means not only; it shows something is more serious than expected.","zh":"not merely 指不只是，用來表示事情比預期更嚴重。"},{"en":"The problem was not merely late homework; the student had missed three lessons.","zh":"問題不只是功課遲交；那名學生已經缺席了三堂課。"},{"en":"The shop was not merely quiet; it looked completely abandoned.","zh":"那間店不只是安靜；它看起來完全被遺棄了。"},{"en":"The rear door was not merely open, so Mr Wong knew something had passed through it.","zh":"後門不只是打開了，所以黃先生知道有東西穿過了它。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"swinging slowly","meaning":"慢慢擺動","examples":[{"en":"The rear door was swinging slowly.","zh":"後門正在慢慢擺動。"},{"en":"Swinging slowly means moving gently back and forth.","zh":"swinging slowly 指輕輕地前後移動。"},{"en":"The garden gate was swinging slowly in the wind.","zh":"花園門在風中慢慢擺動。"},{"en":"A door swinging slowly in an empty building can look frightening.","zh":"一道門在空建築物裏慢慢擺動，可能會令人害怕。"},{"en":"The rear door swung slowly, as if someone had just touched it.","zh":"後門慢慢擺動，彷彿剛有人碰過它。"}],"source":"2021 Q7.pdf","sourcePage":4},{"front":"as though","meaning":"好像；彷彿","examples":[{"en":"The door swung as though someone had just passed through it.","zh":"那道門擺動着，好像剛有人穿過它。"},{"en":"As though means as if; it describes how something seems.","zh":"as though 指好像或彷彿，用來描述某事看起來如何。"},{"en":"She looked at the letter as though it contained bad news.","zh":"她看着那封信，好像裏面有壞消息。"},{"en":"The classroom was silent as though everyone were holding their breath.","zh":"課室安靜得彷彿每個人都屏住呼吸。"},{"en":"The door moved as though an invisible person had entered.","zh":"那道門移動着，好像有一個看不見的人進來了。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"pass through","meaning":"穿過","examples":[{"en":"It looked as though someone had just passed through the door.","zh":"看起來好像剛有人穿過那道門。"},{"en":"Pass through means go through a place, doorway, or object.","zh":"pass through 指穿過某個地方、門口或物件。"},{"en":"Visitors must pass through security before entering the museum.","zh":"參觀者必須通過保安檢查才能進入博物館。"},{"en":"Cold air can pass through a broken window and chill the room.","zh":"冷空氣可以穿過破窗，令房間變冷。"},{"en":"Mr Wong wondered who, or what, had passed through the rear door.","zh":"黃先生想知道是誰，或者是甚麼，穿過了後門。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"grabbed his torch and radio","meaning":"拿起手電筒和對講機","examples":[{"en":"Mr Wong grabbed his torch and radio.","zh":"黃先生拿起手電筒和對講機。"},{"en":"Grabbed his torch and radio means quickly took the tools he needed for patrol.","zh":"grabbed his torch and radio 指迅速拿起巡邏所需的工具。"},{"en":"The guard grabbed his torch and radio when the alarm rang.","zh":"警報響起時，保安員拿起手電筒和對講機。"},{"en":"In an emergency, workers grab their safety equipment before checking the problem.","zh":"在緊急情況中，員工會先拿起安全設備再檢查問題。"},{"en":"Mr Wong grabbed his torch and radio because he had to leave the security room.","zh":"黃先生拿起手電筒和對講機，因為他必須離開保安室。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"security patrol","meaning":"保安巡邏","examples":[{"en":"He said, “Security patrol to rear corridor.”","zh":"他說：「保安巡邏前往後方走廊。」"},{"en":"A security patrol is a guard’s round of checking whether a place is safe.","zh":"security patrol 是保安員巡視地方是否安全的行動。"},{"en":"The school has a security patrol at night to check locked doors.","zh":"學校晚上有保安巡邏，檢查門是否鎖好。"},{"en":"Regular security patrols can prevent theft and notice broken equipment.","zh":"定期保安巡邏可以防止盜竊，並發現損壞設備。"},{"en":"Mr Wong announced his security patrol, although nobody answered.","zh":"黃先生通報保安巡邏，雖然沒有人回答。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"rear corridor","meaning":"後方走廊","examples":[{"en":"He walked towards the rear corridor.","zh":"他走向後方走廊。"},{"en":"A rear corridor is a hallway at the back of a building.","zh":"rear corridor 是建築物後面的走廊。"},{"en":"Staff used the rear corridor to move boxes without disturbing customers.","zh":"員工使用後方走廊搬運箱子，以免打擾顧客。"},{"en":"A rear corridor may feel darker because fewer people pass through it.","zh":"後方走廊可能感覺更黑暗，因為較少人經過。"},{"en":"Mr Wong walked towards the rear corridor because the alarm came from there.","zh":"黃先生走向後方走廊，因為警報來自那裏。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"there was no one to hear him","meaning":"沒有人會聽見他","examples":[{"en":"He spoke into the radio, though there was no one to hear him.","zh":"他對着對講機說話，雖然沒有人會聽見他。"},{"en":"There was no one to hear him means nobody was nearby or available to listen.","zh":"there was no one to hear him 指附近沒有任何人可以聽到他。"},{"en":"The boy shouted in the empty playground, but there was no one to hear him.","zh":"男孩在空蕩的遊樂場大叫，但沒有人會聽見他。"},{"en":"A warning is useless if there is no one to hear it.","zh":"如果沒有人聽見，警告就沒有用。"},{"en":"Mr Wong spoke anyway because the silence made him feel less alone.","zh":"黃先生仍然說了出來，因為寂靜令他覺得沒那麼孤單。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"the arcade outside","meaning":"外面的商場通道","examples":[{"en":"The arcade outside was colder than it should have been.","zh":"外面的商場通道冷得不尋常。"},{"en":"The arcade outside means the covered shopping walkway beyond the shop.","zh":"the arcade outside 指店舖外有上蓋的商場通道。"},{"en":"The arcade outside was empty after all the shops closed.","zh":"所有店舖關門後，外面的商場通道空蕩蕩。"},{"en":"People use the arcade outside to stay dry when it rains.","zh":"下雨時，人們會使用外面的商場通道避雨。"},{"en":"The arcade outside felt wrong because the cold did not match the weather.","zh":"外面的商場通道令人覺得不對勁，因為那份寒冷與天氣不符。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"colder than it should have been","meaning":"冷得不尋常","examples":[{"en":"The arcade outside was colder than it should have been.","zh":"外面的商場通道冷得不尋常。"},{"en":"Colder than it should have been means unexpectedly or unnaturally cold.","zh":"colder than it should have been 指比正常情況更冷，甚至冷得不自然。"},{"en":"The classroom was colder than it should have been, although the heater was on.","zh":"課室冷得不尋常，雖然暖爐已經開着。"},{"en":"Food that is colder than it should have been may have been left outside too long.","zh":"食物如果冷得不尋常，可能是放在外面太久。"},{"en":"The strange cold told Mr Wong that something was not normal.","zh":"那股奇怪寒意告訴黃先生，有些事情並不正常。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"footsteps came back to him","meaning":"腳步聲傳回來","examples":[{"en":"His footsteps came back to him a second late.","zh":"他的腳步聲慢了一秒才傳回來。"},{"en":"Footsteps came back to him means he heard the echo of his own steps.","zh":"footsteps came back to him 指他聽到自己腳步聲的回聲。"},{"en":"In the tunnel, my footsteps came back to me from the walls.","zh":"在隧道裏，我的腳步聲從牆壁傳回來。"},{"en":"Footsteps that come back late can sound like another person walking behind you.","zh":"慢了才傳回來的腳步聲，可能聽起來像另一個人在身後行走。"},{"en":"Mr Wong’s footsteps came back to him and made the corridor feel haunted.","zh":"黃先生的腳步聲傳回來，令走廊感覺像鬧鬼。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"a second late","meaning":"慢了一秒","examples":[{"en":"His footsteps came back to him a second late.","zh":"他的腳步聲慢了一秒才傳回來。"},{"en":"A second late means one second after the expected time.","zh":"a second late 指比預期時間遲了一秒。"},{"en":"The video sound came a second late, so the speaker’s lips did not match.","zh":"影片聲音慢了一秒，所以說話者的嘴形對不上。"},{"en":"If an echo arrives a second late, it can make people feel someone else is there.","zh":"如果回聲慢了一秒才出現，會令人覺得有別人在場。"},{"en":"Mr Wong heard his own steps a second late and stopped walking.","zh":"黃先生聽見自己的腳步聲慢了一秒傳回來，於是停下腳步。"}],"source":"2021 Q7.pdf","sourcePage":5},{"front":"as if another guard were following","meaning":"好像另一名保安員正跟着","examples":[{"en":"His footsteps echoed as if another guard were following him.","zh":"他的腳步聲回響着，好像另一名保安員正跟着他。"},{"en":"As if another guard were following means it sounded like someone else was walking behind him.","zh":"as if another guard were following 指聽起來像有另一個人在身後走。"},{"en":"The empty stairwell echoed as if another guard were following the cleaner.","zh":"空樓梯間傳出回聲，好像另一名保安員正跟着清潔工。"},{"en":"Repeated echoes can make a lonely person feel as if another guard were following.","zh":"重複的回聲會令人感覺好像另一名保安員正跟着。"},{"en":"Mr Wong knew he was alone, but the sound suggested otherwise.","zh":"黃先生知道自己獨自一人，但聲音卻暗示不是這樣。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"just out of sight","meaning":"剛好在視線之外","examples":[{"en":"It felt as if someone were following just out of sight.","zh":"感覺好像有人剛好在視線之外跟着他。"},{"en":"Just out of sight means very near but not visible.","zh":"just out of sight 指很近，但看不見。"},{"en":"The cat hid just out of sight behind the sofa.","zh":"那隻貓躲在梳化後面，剛好在視線之外。"},{"en":"A person walking just out of sight can make an empty street feel unsafe.","zh":"有人在視線之外行走，可以令空街感覺不安全。"},{"en":"Mr Wong felt something was just out of sight, waiting in the dark.","zh":"黃先生感到有東西剛好在視線之外，在黑暗中等待。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"rear entrance","meaning":"後方入口","examples":[{"en":"He reached the bookshop’s rear entrance.","zh":"他到達書店的後方入口。"},{"en":"A rear entrance is the door at the back of a building.","zh":"rear entrance 是建築物後面的入口。"},{"en":"Delivery workers used the restaurant’s rear entrance to bring in food.","zh":"送貨工人使用餐廳的後方入口送入食材。"},{"en":"A rear entrance may need extra security because customers do not watch it.","zh":"後方入口可能需要額外保安，因為顧客不會留意它。"},{"en":"Mr Wong reached the rear entrance and found the sensor blinking.","zh":"黃先生到達後方入口，發現感應器正在閃爍。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"blinked above the door","meaning":"在門上方閃爍","examples":[{"en":"The sensor blinked above the door.","zh":"感應器在門上方閃爍。"},{"en":"Blinked above the door means a small light flashed on and off over the doorway.","zh":"blinked above the door 指一盞小燈在門口上方一明一暗。"},{"en":"The alarm light blinked above the door after closing time.","zh":"關門後，警報燈在門上方閃爍。"},{"en":"If a light blinks above the door, it may be showing a warning.","zh":"如果燈在門上方閃爍，它可能是在發出警告。"},{"en":"The sensor blinked above the door like an eye that would not close.","zh":"感應器在門上方閃爍，像一隻不肯合上的眼睛。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"forcing the key into the lock","meaning":"硬把鑰匙插進鎖裏","examples":[{"en":"Mr Wong forced the key into the lock.","zh":"黃先生硬把鑰匙插進鎖裏。"},{"en":"Forcing the key into the lock means pushing the key in with effort because it does not fit smoothly.","zh":"forcing the key into the lock 指因鑰匙不順利而用力把它推進鎖孔。"},{"en":"She damaged the door by forcing the key into the lock.","zh":"她硬把鑰匙插進鎖裏，結果弄壞了門。"},{"en":"If you keep forcing the key into the lock, the key may break.","zh":"如果你一直硬把鑰匙插進鎖裏，鑰匙可能會折斷。"},{"en":"Mr Wong forced the key into the lock because his hands were shaking.","zh":"黃先生硬把鑰匙插進鎖裏，因為他的手正在發抖。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"pages rustled","meaning":"書頁沙沙作響","examples":[{"en":"Behind the locked door, pages rustled.","zh":"鎖上的門後面，書頁沙沙作響。"},{"en":"Pages rustled means paper made a soft, dry sound as it moved.","zh":"pages rustled 指紙張移動時發出輕微乾燥的沙沙聲。"},{"en":"The pages rustled when the student turned them quickly.","zh":"學生快速翻頁時，書頁沙沙作響。"},{"en":"In a quiet library, pages rustling can sound louder than usual.","zh":"在安靜的圖書館裏，書頁沙沙作響會聽起來比平常更大聲。"},{"en":"The pages rustled behind the door, although nobody should have been inside.","zh":"門後面書頁沙沙作響，雖然裏面不應該有人。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"seemed taller than before","meaning":"看起來比之前更高","examples":[{"en":"Inside, the shelves seemed taller than before.","zh":"進去後，書架看起來比之前更高。"},{"en":"Seemed taller than before means looked higher than someone remembered.","zh":"seemed taller than before 指看起來比記憶中更高。"},{"en":"At night, the school buildings seemed taller than before.","zh":"晚上，學校大樓看起來比之前更高。"},{"en":"Fear can make ordinary things seem taller than before and more threatening.","zh":"恐懼可以令普通事物看起來比之前更高、更有威脅。"},{"en":"The shelves seemed taller than before, as if the bookshop had grown.","zh":"書架看起來比之前更高，彷彿書店自己長大了。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"torchlight moved over","meaning":"手電筒的光掃過","examples":[{"en":"His torchlight moved over travel guides, cookbooks and romance novels.","zh":"他的手電筒的光掃過旅遊指南、烹飪書和愛情小說。"},{"en":"Torchlight moved over means the beam of light passed across different things.","zh":"torchlight moved over 指手電筒的光束掃過不同東西。"},{"en":"The guard’s torchlight moved over the empty seats in the hall.","zh":"保安員的手電筒光掃過大堂裏的空座位。"},{"en":"Torchlight moving over a dark room helps people check what is there.","zh":"手電筒光掃過黑暗房間，可以幫助人檢查裏面有甚麼。"},{"en":"Mr Wong’s torchlight moved over the shelves, looking for something wrong.","zh":"黃先生的手電筒光掃過書架，尋找不對勁的地方。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"travel guides","meaning":"旅遊指南","examples":[{"en":"His torchlight moved over travel guides.","zh":"他的手電筒光掃過旅遊指南。"},{"en":"Travel guides are books that give information about places to visit.","zh":"travel guides 是提供旅遊地點資料的書。"},{"en":"Tourists read travel guides to find hotels, maps, and famous sights.","zh":"遊客閱讀旅遊指南，尋找酒店、地圖和名勝。"},{"en":"A good travel guide can help people avoid getting lost in a new city.","zh":"一本好的旅遊指南可以幫助人在陌生城市避免迷路。"},{"en":"In the dark shop, even the travel guides looked as if they led somewhere unsafe.","zh":"在黑暗書店裏，連旅遊指南也像會把人帶到危險地方。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"cookbooks","meaning":"烹飪書","examples":[{"en":"His torchlight moved over cookbooks.","zh":"他的手電筒光掃過烹飪書。"},{"en":"Cookbooks are books that teach people how to cook dishes.","zh":"cookbooks 是教人如何烹調菜式的書。"},{"en":"My aunt uses cookbooks when she wants to try a new soup.","zh":"姑姐想試新湯時，會使用烹飪書。"},{"en":"Cookbooks help beginners understand ingredients, steps, and cooking time.","zh":"烹飪書幫助初學者理解食材、步驟和烹調時間。"},{"en":"The cookbooks sat quietly on the shelf while the pages elsewhere rustled.","zh":"烹飪書靜靜放在書架上，而別處的書頁卻沙沙作響。"}],"source":"2021 Q7.pdf","sourcePage":6},{"front":"romance novels","meaning":"愛情小說","examples":[{"en":"His torchlight moved over romance novels.","zh":"他的手電筒光掃過愛情小說。"},{"en":"Romance novels are stories mainly about love and relationships.","zh":"romance novels 是主要關於愛情和關係的故事。"},{"en":"Many readers choose romance novels when they want a warm, emotional story.","zh":"許多讀者想讀溫暖、有感情的故事時，會選擇愛情小說。"},{"en":"Romance novels often show how misunderstandings can separate people.","zh":"愛情小說常展示誤會如何令人分離。"},{"en":"In Mr Wong’s torchlight, the romance novels looked strangely out of place.","zh":"在黃先生的手電筒光下，愛情小說顯得奇怪地不合時宜。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"landed on","meaning":"照到；落在","examples":[{"en":"His torchlight landed on a poster near the children’s corner.","zh":"他的手電筒光照到兒童圖書角附近的一張海報。"},{"en":"Landed on means stopped on or came to rest on something.","zh":"landed on 指停在或落在某物上。"},{"en":"Her eyes landed on a strange note on the table.","zh":"她的目光落在桌上一張奇怪的紙條上。"},{"en":"The spotlight landed on the singer when the music began.","zh":"音樂開始時，聚光燈照到歌手身上。"},{"en":"Mr Wong’s torchlight landed on the poster, and the night became stranger.","zh":"黃先生的手電筒光落在海報上，那一晚變得更加奇怪。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"children’s corner","meaning":"兒童圖書角","examples":[{"en":"The poster was near the children’s corner.","zh":"那張海報在兒童圖書角附近。"},{"en":"A children’s corner is an area in a shop or library for children’s books and activities.","zh":"children’s corner 是商店或圖書館裏放兒童書和舉辦兒童活動的區域。"},{"en":"The library’s children’s corner has picture books and small chairs.","zh":"圖書館的兒童圖書角有圖畫書和小椅子。"},{"en":"A children’s corner should feel bright and safe for young readers.","zh":"兒童圖書角應該讓小讀者感到明亮和安全。"},{"en":"The children’s corner felt frightening because the contest drawings lay beneath the poster.","zh":"兒童圖書角令人害怕，因為比賽圖畫放在海報下面。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"short story contest","meaning":"短篇小說比賽","examples":[{"en":"The poster advertised a short story contest.","zh":"那張海報宣傳一個短篇小說比賽。"},{"en":"A short story contest is a competition where people submit short fictional writing.","zh":"short story contest 是讓人提交短篇小說作品的比賽。"},{"en":"The school held a short story contest for students who enjoy writing.","zh":"學校為喜歡寫作的學生舉辦短篇小說比賽。"},{"en":"A short story contest may have rules about topic, length, and deadline.","zh":"短篇小說比賽可能有關於題目、字數和截止日期的規則。"},{"en":"This short story contest asked for a scary story about a guard on duty.","zh":"這個短篇小說比賽要求寫一個關於當值保安員的恐怖故事。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"scary story","meaning":"恐怖故事","examples":[{"en":"The contest asked writers to write a scary story.","zh":"比賽要求作者寫一個恐怖故事。"},{"en":"A scary story is a story meant to make readers feel afraid or nervous.","zh":"scary story 是用來令讀者感到害怕或緊張的故事。"},{"en":"Children told a scary story around the campfire.","zh":"孩子們圍着營火講恐怖故事。"},{"en":"A scary story often uses darkness, strange sounds, and unanswered questions.","zh":"恐怖故事常使用黑暗、怪聲和未解答的問題。"},{"en":"Mr Wong realised the scary story might be writing itself around him.","zh":"黃先生意識到，那個恐怖故事可能正在圍繞着他自己寫成。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"security guard on duty","meaning":"當值的保安員","examples":[{"en":"The story had to be about a security guard on duty one night.","zh":"故事必須關於某晚一名當值的保安員。"},{"en":"A security guard on duty is a guard who is working and responsible for safety at that time.","zh":"security guard on duty 指正在工作並負責當時安全的保安員。"},{"en":"The security guard on duty checked every classroom after school.","zh":"當值的保安員放學後檢查每間課室。"},{"en":"If a security guard on duty ignores an alarm, people may be in danger.","zh":"如果當值的保安員忽視警報，人們可能會有危險。"},{"en":"Mr Wong was the security guard on duty, just like the contest topic.","zh":"黃先生正是當值的保安員，和比賽題目一樣。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"beneath it lay","meaning":"……下面放着","examples":[{"en":"Beneath the poster lay four black-and-white drawings.","zh":"海報下面放着四張黑白圖畫。"},{"en":"Beneath it lay means under it there was something placed or resting.","zh":"beneath it lay 指在它下面放着或躺着某些東西。"},{"en":"Beneath the old photo lay a yellow letter.","zh":"舊照片下面放着一封泛黃的信。"},{"en":"When papers lie beneath a notice, they may be part of the same display.","zh":"如果紙張放在告示下面，它們可能是同一展示的一部分。"},{"en":"Beneath the contest poster lay drawings that seemed to know Mr Wong’s future.","zh":"比賽海報下面放着幾張圖畫，彷彿知道黃先生的未來。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"black-and-white drawings","meaning":"黑白圖畫","examples":[{"en":"Beneath it lay four black-and-white drawings.","zh":"海報下面放着四張黑白圖畫。"},{"en":"Black-and-white drawings are pictures made without colour, using only dark and light tones.","zh":"black-and-white drawings 是不用顏色、只用深淺色調畫成的圖畫。"},{"en":"The art teacher asked students to practise black-and-white drawings before using paint.","zh":"美術老師要求學生先練習黑白圖畫，再使用顏料。"},{"en":"Black-and-white drawings can look serious because colour does not distract the eye.","zh":"黑白圖畫可以顯得嚴肅，因為顏色不會分散視線。"},{"en":"The black-and-white drawings made the children’s corner feel colder.","zh":"那些黑白圖畫令兒童圖書角感覺更冷。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"a lone guard","meaning":"孤身一人的保安員","examples":[{"en":"The last drawing showed a lone guard walking into darkness.","zh":"最後一張圖畫畫着一名孤身一人的保安員走進黑暗中。"},{"en":"A lone guard is a guard who is alone, without help or company.","zh":"a lone guard 指獨自一人、沒有幫手或同伴的保安員。"},{"en":"A lone guard stood outside the closed museum at night.","zh":"一名孤身一人的保安員晚上站在關閉的博物館外。"},{"en":"A lone guard may feel unsafe if the building is large and empty.","zh":"如果建築物又大又空，孤身一人的保安員可能會感到不安全。"},{"en":"The drawing of a lone guard made Mr Wong think of himself.","zh":"那幅孤身保安員的圖畫令黃先生想起自己。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"walking into darkness","meaning":"走進黑暗中","examples":[{"en":"The drawing showed a guard walking into darkness.","zh":"圖畫畫着一名保安員走進黑暗中。"},{"en":"Walking into darkness means moving into a place where little or no light can be seen.","zh":"walking into darkness 指走入幾乎沒有光或完全沒有光的地方。"},{"en":"The child felt afraid walking into darkness after the power cut.","zh":"停電後，孩子走進黑暗中時感到害怕。"},{"en":"In stories, walking into darkness often suggests danger or uncertainty.","zh":"在故事中，走進黑暗中常暗示危險或不確定。"},{"en":"Mr Wong felt he was walking into darkness, not just a corridor.","zh":"黃先生覺得自己走進的不是走廊，而是黑暗本身。"}],"source":"2021 Q7.pdf","sourcePage":7},{"front":"mouth went dry","meaning":"口乾舌燥","examples":[{"en":"Mr Wong’s mouth went dry when he saw the drawings.","zh":"黃先生看見那些圖畫時，口乾舌燥。"},{"en":"Mouth went dry means someone suddenly felt fear, shock, or nervousness.","zh":"mouth went dry 指一個人突然感到害怕、震驚或緊張。"},{"en":"My mouth went dry before I gave a speech to the whole school.","zh":"在全校面前演講前，我口乾舌燥。"},{"en":"A person’s mouth may go dry when they hear bad news.","zh":"一個人聽到壞消息時，可能會口乾舌燥。"},{"en":"Mr Wong’s mouth went dry because the drawing looked too much like him.","zh":"黃先生口乾舌燥，因為那幅圖畫太像他了。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"unfinished","meaning":"未完成的","examples":[{"en":"The last picture was unfinished.","zh":"最後一幅圖畫是未完成的。"},{"en":"Unfinished means not completed yet.","zh":"unfinished 指還沒有完成。"},{"en":"The student handed in an unfinished essay because time ran out.","zh":"時間用完了，學生交了一篇未完成的作文。"},{"en":"An unfinished building can be dangerous if people enter it.","zh":"未完成的建築物如果有人進入，可能很危險。"},{"en":"The unfinished drawing frightened Mr Wong because part of the guard was missing.","zh":"那幅未完成的圖畫嚇壞黃先生，因為保安員的一部分不見了。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"the rest of the body","meaning":"身體其餘部分","examples":[{"en":"Only the guard’s legs had been drawn; the rest of the body was missing.","zh":"只有保安員的雙腿被畫了出來；身體其餘部分不見了。"},{"en":"The rest of the body means all body parts apart from the part already mentioned.","zh":"the rest of the body 指除了已提到部分外的所有身體部位。"},{"en":"The doctor checked the injured hand, then examined the rest of the body.","zh":"醫生檢查受傷的手後，再檢查身體其餘部分。"},{"en":"If only the head is shown in a photo, the rest of the body cannot be seen.","zh":"如果照片只顯示頭部，身體其餘部分就看不見。"},{"en":"In the drawing, the missing rest of the body made the guard look half-erased.","zh":"在圖畫中，不見了的身體其餘部分令保安員像被擦掉了一半。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"was missing","meaning":"不見了","examples":[{"en":"The rest of the guard’s body was missing.","zh":"保安員身體其餘部分不見了。"},{"en":"Was missing means was not there although it should have been there.","zh":"was missing 指本來應該在那裏的東西不見了。"},{"en":"One page was missing from the library book.","zh":"圖書館的書有一頁不見了。"},{"en":"If a child is missing, adults must search immediately.","zh":"如果孩子不見了，大人必須立即尋找。"},{"en":"The guard’s body was missing from the drawing, and Mr Wong felt sick.","zh":"保安員的身體從圖畫中不見了，黃先生感到一陣噁心。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"No sooner had he touched… than…","meaning":"剛一……就……","examples":[{"en":"No sooner had he touched the paper than the public-address system crackled.","zh":"他剛一碰到那張紙，廣播系統就發出沙沙聲。"},{"en":"No sooner had he touched something than something else happened means the second action happened immediately after the first.","zh":"No sooner had he touched… than… 指第一個動作剛發生，第二件事就立即發生。"},{"en":"No sooner had I opened the door than the dog ran outside.","zh":"我剛一打開門，狗就跑了出去。"},{"en":"No sooner had the teacher left than the students began talking.","zh":"老師剛一離開，學生就開始說話。"},{"en":"No sooner had Mr Wong touched the paper than the shop seemed to answer him.","zh":"黃先生剛一碰到那張紙，書店就像回應了他。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"public-address system","meaning":"廣播系統","examples":[{"en":"The public-address system crackled.","zh":"廣播系統發出沙沙聲。"},{"en":"A public-address system is equipment used to make announcements through speakers.","zh":"public-address system 是透過喇叭作出廣播的設備。"},{"en":"The school uses the public-address system to call students to the hall.","zh":"學校使用廣播系統叫學生到禮堂。"},{"en":"If the public-address system fails during an emergency, people may miss instructions.","zh":"如果緊急時廣播系統失靈，人們可能會錯過指示。"},{"en":"The public-address system in the bookshop whispered instead of making a normal announcement.","zh":"書店的廣播系統沒有正常廣播，而是低聲說話。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"crackled","meaning":"發出沙沙聲；發出雜音","examples":[{"en":"The public-address system crackled before a voice spoke.","zh":"一把聲音說話前，廣播系統發出沙沙聲。"},{"en":"Crackled means made a series of short, rough noises.","zh":"crackled 指發出一連串短促粗糙的雜音。"},{"en":"The old radio crackled during the storm.","zh":"暴風雨中，舊收音機發出沙沙聲。"},{"en":"A speaker may crackle when the wire is loose or damaged.","zh":"喇叭電線鬆脫或受損時，可能會發出雜音。"},{"en":"The system crackled, and Mr Wong waited for the voice with fear.","zh":"系統發出沙沙聲，黃先生害怕地等待那把聲音。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"whispered through every speaker","meaning":"從每個喇叭低聲傳出","examples":[{"en":"A voice whispered through every speaker in the shop.","zh":"一把聲音從店裏每個喇叭低聲傳出。"},{"en":"Whispered through every speaker means a soft voice came from all the loudspeakers.","zh":"whispered through every speaker 指柔弱的聲音從所有喇叭傳出。"},{"en":"During the test, instructions whispered through every speaker in the quiet hall.","zh":"測驗期間，指示從安靜禮堂的每個喇叭低聲傳出。"},{"en":"A whisper through every speaker can feel more frightening than a shout.","zh":"從每個喇叭傳出的低語，可能比大叫更可怕。"},{"en":"The voice whispered through every speaker, so Mr Wong could not tell where it came from.","zh":"那把聲音從每個喇叭低聲傳出，所以黃先生分不清它來自哪裏。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"finish your patrol","meaning":"完成你的巡邏","examples":[{"en":"The voice told him to finish his patrol.","zh":"那把聲音叫他完成巡邏。"},{"en":"Finish your patrol means complete the checking route you started.","zh":"finish your patrol 指完成你開始的巡查路線。"},{"en":"The supervisor told the guard to finish his patrol before taking a break.","zh":"主管叫保安員休息前先完成巡邏。"},{"en":"A patrol is unfinished if some rooms or corridors are not checked.","zh":"如果有些房間或走廊沒有檢查，巡邏就未完成。"},{"en":"The voice ordered Mr Wong to finish his patrol, as if the shop controlled his duty.","zh":"那把聲音命令黃先生完成巡邏，好像書店控制着他的職責。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"slid from the shelf","meaning":"從書架滑落","examples":[{"en":"A book slid from the shelf.","zh":"一本書從書架滑落。"},{"en":"Slid from the shelf means moved smoothly off the shelf and fell or dropped down.","zh":"slid from the shelf 指從書架上平滑地滑出並掉下。"},{"en":"The heavy folder slid from the shelf and landed on the floor.","zh":"厚文件夾從書架滑落，落在地上。"},{"en":"If books are not placed properly, they may slide from the shelf.","zh":"如果書沒有放好，它們可能會從書架滑落。"},{"en":"The book slid from the shelf without any visible hand touching it.","zh":"那本書從書架滑落，卻沒有任何看得見的手碰過它。"}],"source":"2021 Q7.pdf","sourcePage":8},{"front":"landed open at his feet","meaning":"攤開落在他腳邊","examples":[{"en":"The book landed open at his feet.","zh":"那本書攤開落在他腳邊。"},{"en":"Landed open at his feet means the book fell and opened on the floor beside his feet.","zh":"landed open at his feet 指書本掉在他腳邊的地上並攤開。"},{"en":"The notebook landed open at her feet, showing the secret page.","zh":"筆記本攤開落在她腳邊，露出秘密的一頁。"},{"en":"When a book lands open, it may reveal a particular sentence by chance.","zh":"一本書攤開落下時，可能會碰巧顯示某一句話。"},{"en":"The book landed open at Mr Wong’s feet as if choosing a page for him.","zh":"那本書攤開落在黃先生腳邊，像是為他選了一頁。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"a neat line of handwriting","meaning":"一行整齊的手寫字","examples":[{"en":"On the page was a neat line of handwriting.","zh":"頁上有一行整齊的手寫字。"},{"en":"A neat line of handwriting is a tidy handwritten sentence or row of words.","zh":"a neat line of handwriting 是一行整齊手寫的句子或文字。"},{"en":"The teacher wrote a neat line of handwriting at the top of the worksheet.","zh":"老師在工作紙頂部寫了一行整齊的手寫字。"},{"en":"A neat line of handwriting can look calm even when the message is frightening.","zh":"一行整齊的手寫字即使內容可怕，也可以看起來很冷靜。"},{"en":"The neat line of handwriting scared Mr Wong because it described him.","zh":"那行整齊的手寫字嚇壞黃先生，因為它描述了他。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"returned to","meaning":"回到……","examples":[{"en":"The handwriting said Mr Wong returned to the security room.","zh":"手寫字寫着黃先生回到保安室。"},{"en":"Returned to means went back to a place where someone had been before.","zh":"returned to 指回到之前去過的地方。"},{"en":"After lunch, students returned to the classroom.","zh":"午飯後，學生回到課室。"},{"en":"A nurse returned to the ward after checking the medicine room.","zh":"護士檢查藥房後回到病房。"},{"en":"The writing said Mr Wong returned to the security room before he had actually done it.","zh":"文字寫着黃先生回到保安室，但他其實還未這樣做。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"found himself still asleep","meaning":"發現自己仍然睡着","examples":[{"en":"Mr Wong returned to the security room and found himself still asleep.","zh":"黃先生回到保安室，發現自己仍然睡着。"},{"en":"Found himself still asleep means he discovered another version of himself sleeping there.","zh":"found himself still asleep 指他發現另一個自己仍在那裏睡着。"},{"en":"In a dream, a boy found himself still asleep in his own bed.","zh":"在夢裏，一個男孩發現自己仍然睡在自己的床上。"},{"en":"This phrase creates fear because a person cannot normally see himself sleeping.","zh":"這個說法製造恐懼，因為人通常不能看見自己睡着。"},{"en":"Mr Wong found himself still asleep, so he no longer knew which self was real.","zh":"黃先生發現自己仍然睡着，所以他再也不知道哪個自己才是真的。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"the corridor bent","meaning":"走廊彎曲","examples":[{"en":"The corridor bent in the wrong direction.","zh":"走廊朝錯誤方向彎曲。"},{"en":"The corridor bent means the hallway turned or curved.","zh":"the corridor bent 指走廊轉彎或彎曲。"},{"en":"The hospital corridor bent left near the waiting room.","zh":"醫院走廊在候診室附近向左彎。"},{"en":"If a familiar corridor bends in a new direction, the place feels impossible.","zh":"如果熟悉的走廊彎向新的方向，那個地方會感覺不可能存在。"},{"en":"The corridor bent where it should not, trapping Mr Wong in the shop.","zh":"走廊在不應該轉彎的地方彎曲，把黃先生困在書店裏。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"in the wrong direction","meaning":"朝錯誤方向","examples":[{"en":"The corridor bent in the wrong direction.","zh":"走廊朝錯誤方向彎曲。"},{"en":"In the wrong direction means towards a way that is incorrect or unexpected.","zh":"in the wrong direction 指朝不正確或意想不到的方向。"},{"en":"We walked in the wrong direction and missed the bus stop.","zh":"我們朝錯誤方向走，結果錯過了巴士站。"},{"en":"If a lift moves in the wrong direction, passengers may panic.","zh":"如果升降機朝錯誤方向移動，乘客可能會驚慌。"},{"en":"The corridor turned in the wrong direction, so Mr Wong knew the shop had changed.","zh":"走廊朝錯誤方向轉彎，所以黃先生知道書店已經改變了。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"opened into","meaning":"通往；開向","examples":[{"en":"The bookshop door opened into the staff toilet.","zh":"書店門竟然通往職員洗手間。"},{"en":"Opened into means led directly into another room or place.","zh":"opened into 指直接通往或開向另一個房間或地方。"},{"en":"The kitchen door opened into a small garden.","zh":"廚房門通往一個小花園。"},{"en":"If a classroom door opens into a storeroom instead, students will know something is wrong.","zh":"如果課室門竟然開向儲物室，學生就會知道有些事情不對。"},{"en":"The bookshop door opened into the staff toilet, breaking the normal map of the shop.","zh":"書店門竟然通往職員洗手間，打亂了書店原本的空間。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"staff toilet","meaning":"職員洗手間","examples":[{"en":"The bookshop door opened into the staff toilet.","zh":"書店門竟然通往職員洗手間。"},{"en":"A staff toilet is a toilet for workers, not customers.","zh":"staff toilet 是給員工使用、不是給顧客使用的洗手間。"},{"en":"Customers should not use the staff toilet unless there is an emergency.","zh":"除非有緊急情況，顧客不應使用職員洗手間。"},{"en":"A staff toilet is usually hidden behind a door or corridor.","zh":"職員洗手間通常藏在一道門或走廊後面。"},{"en":"Mr Wong was disturbed because the bookshop door should not open into the staff toilet.","zh":"黃先生感到不安，因為書店門不應該通往職員洗手間。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"back into Fiction","meaning":"回到小說區","examples":[{"en":"The staircase led back into Fiction.","zh":"樓梯通回小說區。"},{"en":"Back into Fiction means returning to the fiction section of the bookshop.","zh":"back into Fiction 指回到書店的小說區。"},{"en":"After passing the café, the path led back into Fiction.","zh":"走過咖啡區後，那條路通回小說區。"},{"en":"In a bookshop, Fiction is the section for novels and made-up stories.","zh":"在書店裏，Fiction 是放小說和虛構故事的區域。"},{"en":"The staircase led back into Fiction, as if every route returned to stories.","zh":"樓梯通回小說區，彷彿每條路都回到故事之中。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"all the while","meaning":"期間一直；同時","examples":[{"en":"All the while, the alarm kept ringing.","zh":"期間，警報一直響着。"},{"en":"All the while means during the whole time another action was happening.","zh":"all the while 指在另一件事發生的整段時間裏。"},{"en":"She cooked dinner; all the while, the baby kept crying.","zh":"她煮晚飯；期間嬰兒一直哭。"},{"en":"The workers repaired the road; all the while, traffic moved slowly.","zh":"工人修路；同時交通一直緩慢。"},{"en":"Mr Wong ran through changing corridors; all the while, the alarm rang louder.","zh":"黃先生穿過不斷改變的走廊；期間警報越響越大。"}],"source":"2021 Q7.pdf","sourcePage":9},{"front":"kept ringing","meaning":"不停響","examples":[{"en":"The alarm kept ringing louder and louder.","zh":"警報不停響，而且越來越大聲。"},{"en":"Kept ringing means continued to make a ringing sound.","zh":"kept ringing 指持續發出鈴聲。"},{"en":"The phone kept ringing, but nobody answered.","zh":"電話不停響，但沒有人接。"},{"en":"If a fire alarm keeps ringing, people should leave the building.","zh":"如果火警鐘不停響，人們應該離開大樓。"},{"en":"The alarm kept ringing until it sounded less like a machine.","zh":"警報不停響，直到它聽起來不太像機器。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"less like… than…","meaning":"與其說像……不如說像……","examples":[{"en":"The alarm sounded less like a machine than a child laughing.","zh":"警報與其說像機器，不如說像孩子在笑。"},{"en":"Less like one thing than another means it seemed more similar to the second thing.","zh":"less like… than… 指某事不像前者，而更像後者。"},{"en":"His apology sounded less like regret than an excuse.","zh":"他的道歉與其說像後悔，不如說像藉口。"},{"en":"The meeting felt less like a discussion than a lecture.","zh":"那次會議與其說像討論，不如說像講課。"},{"en":"The alarm sounded less like a warning than something alive and cruel.","zh":"警報與其說像警告，不如說像某種活着而殘忍的東西。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"a child laughing behind metal teeth","meaning":"像孩子在金屬牙齒後面笑","examples":[{"en":"The alarm sounded like a child laughing behind metal teeth.","zh":"警報聽起來像孩子在金屬牙齒後面笑。"},{"en":"A child laughing behind metal teeth creates a disturbing image of innocent laughter mixed with machinery.","zh":"a child laughing behind metal teeth 製造出童真笑聲與機械混合的怪異畫面。"},{"en":"The broken toy sounded like a child laughing behind metal teeth.","zh":"那個壞掉的玩具聽起來像孩子在金屬牙齒後面笑。"},{"en":"This image feels scary because laughter should be warm, but metal teeth feel cold and dangerous.","zh":"這個畫面可怕，因為笑聲本應溫暖，但金屬牙齒感覺冰冷又危險。"},{"en":"The alarm’s sound made Mr Wong imagine a child laughing behind metal teeth.","zh":"警報聲令黃先生想像有孩子在金屬牙齒後面笑。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"at last","meaning":"終於","examples":[{"en":"At last, he burst into the security room.","zh":"終於，他衝進保安室。"},{"en":"At last means finally, after waiting, struggling, or trying for some time.","zh":"at last 指經過等待、掙扎或努力後終於發生。"},{"en":"At last, the lost child found his mother.","zh":"終於，走失的孩子找到了媽媽。"},{"en":"We arrived at last after walking through heavy rain.","zh":"我們在大雨中走了很久後，終於到達。"},{"en":"At last, Mr Wong reached the security room, but safety was not there.","zh":"終於，黃先生到達保安室，但安全並不在那裏。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"burst into","meaning":"衝進","examples":[{"en":"He burst into the security room.","zh":"他衝進保安室。"},{"en":"Burst into means entered a place suddenly and with force.","zh":"burst into 指突然用力進入某個地方。"},{"en":"The teacher burst into the classroom when she heard shouting.","zh":"老師聽到叫喊聲後衝進課室。"},{"en":"People may burst into a room during an emergency because there is no time to knock.","zh":"緊急時，人們可能會衝進房間，因為沒有時間敲門。"},{"en":"Mr Wong burst into the security room, desperate to escape the corridors.","zh":"黃先生衝進保安室，急切想逃離那些走廊。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"sleeping at the desk","meaning":"伏在桌前睡着","examples":[{"en":"Someone was sleeping at the desk.","zh":"有人伏在桌前睡着。"},{"en":"Sleeping at the desk means resting with the body or head on a desk.","zh":"sleeping at the desk 指身體或頭靠在桌上睡着。"},{"en":"The tired student was sleeping at the desk after finishing homework late.","zh":"疲倦的學生很晚才完成功課後，伏在桌前睡着。"},{"en":"A worker sleeping at the desk may have stayed awake for too many hours.","zh":"伏在桌前睡着的員工可能已經清醒太多小時。"},{"en":"Mr Wong froze when he saw someone sleeping at the desk in his own place.","zh":"黃先生看見有人在自己的位置伏在桌前睡着，整個人僵住了。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"stepped closer","meaning":"走近一點","examples":[{"en":"Mr Wong stepped closer to the sleeping man.","zh":"黃先生走近那個睡着的男人一點。"},{"en":"Stepped closer means moved nearer by taking one or more steps.","zh":"stepped closer 指走一步或幾步，移近某物或某人。"},{"en":"The doctor stepped closer to hear the patient better.","zh":"醫生走近一點，以便更清楚聽見病人說話。"},{"en":"People step closer when they need to check something carefully.","zh":"人們需要仔細檢查某事時，會走近一點。"},{"en":"Mr Wong stepped closer even though every part of him wanted to run away.","zh":"黃先生走近一點，雖然他全身都想逃跑。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"wore his uniform","meaning":"穿着他的制服","examples":[{"en":"The man wore Mr Wong’s uniform.","zh":"那個男人穿着黃先生的制服。"},{"en":"Wore his uniform means had the same work clothes on his body.","zh":"wore his uniform 指身上穿着他的工作制服。"},{"en":"The new guard wore his uniform on the first day of work.","zh":"新保安員第一天上班時穿着制服。"},{"en":"A person wearing another worker’s uniform may be pretending to be that worker.","zh":"穿着另一名員工制服的人，可能是在假扮那名員工。"},{"en":"The sleeping man wore Mr Wong’s uniform, so Mr Wong felt his identity slipping away.","zh":"睡着的男人穿着黃先生的制服，所以黃先生感到自己的身份正在消失。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"name badge","meaning":"名牌","examples":[{"en":"The man wore Mr Wong’s name badge.","zh":"那個男人戴着黃先生的名牌。"},{"en":"A name badge is a small sign on clothing that shows a person’s name.","zh":"name badge 是戴在衣服上、顯示姓名的小牌。"},{"en":"Shop workers wear name badges so customers know who is helping them.","zh":"店員佩戴名牌，讓顧客知道誰在幫助他們。"},{"en":"A lost name badge can cause confusion if someone else uses it.","zh":"遺失的名牌如果被別人使用，可能會造成混亂。"},{"en":"The name badge on the sleeping man made him look exactly like Mr Wong.","zh":"睡着男人身上的名牌令他看起來完全像黃先生。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"scar above his left eyebrow","meaning":"左眉上方的疤痕","examples":[{"en":"The man even had the scar above Mr Wong’s left eyebrow.","zh":"那個男人甚至有黃先生左眉上方的疤痕。"},{"en":"A scar above his left eyebrow is a mark from an old injury over the left eye.","zh":"scar above his left eyebrow 是左眼上方舊傷留下的痕跡。"},{"en":"The footballer had a small scar above his left eyebrow after an accident.","zh":"那名足球員意外後，左眉上方有一道小疤痕。"},{"en":"A scar can help identify someone because it is personal and hard to copy.","zh":"疤痕可以幫助辨認一個人，因為它很個人化，也很難複製。"},{"en":"The scar above his left eyebrow proved the sleeping man was not just wearing his clothes.","zh":"左眉上方的疤痕證明那個睡着的男人不只是穿着他的衣服。"}],"source":"2021 Q7.pdf","sourcePage":10},{"front":"all sixteen cameras showed","meaning":"十六部鏡頭全部顯示","examples":[{"en":"All sixteen cameras showed the same picture.","zh":"十六部鏡頭全部顯示同一幅畫面。"},{"en":"All sixteen cameras showed means every camera displayed that image.","zh":"all sixteen cameras showed 指每一部鏡頭都顯示那個畫面。"},{"en":"All sixteen cameras showed empty corridors after the mall closed.","zh":"商場關門後，十六部鏡頭全部顯示空走廊。"},{"en":"If all sixteen cameras show the same picture, the security system may be controlled or broken.","zh":"如果十六部鏡頭全部顯示同一畫面，保安系統可能被控制或壞了。"},{"en":"All sixteen cameras showed Mr Wong the same impossible scene.","zh":"十六部鏡頭全部向黃先生顯示同一個不可能的場景。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"the same picture","meaning":"同一幅畫面","examples":[{"en":"All sixteen cameras showed the same picture.","zh":"十六部鏡頭全部顯示同一幅畫面。"},{"en":"The same picture means exactly the same image appeared in every place.","zh":"the same picture 指每個地方都出現完全相同的影像。"},{"en":"Every classroom screen showed the same picture during the announcement.","zh":"廣播期間，每間課室的螢幕都顯示同一幅畫面。"},{"en":"If different cameras show the same picture, the viewer cannot know what is really happening elsewhere.","zh":"如果不同鏡頭都顯示同一幅畫面，觀看者就無法知道其他地方真正發生甚麼。"},{"en":"The same picture on every monitor trapped Mr Wong inside one terrible moment.","zh":"每部監視器上的同一幅畫面，把黃先生困在一個可怕時刻裏。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"one trembling hand","meaning":"一隻顫抖的手","examples":[{"en":"The cameras showed one trembling hand reaching out.","zh":"鏡頭顯示一隻顫抖的手伸出去。"},{"en":"One trembling hand is a single hand shaking because of fear, cold, or weakness.","zh":"one trembling hand 指一隻因恐懼、寒冷或虛弱而發抖的手。"},{"en":"The old woman raised one trembling hand to ask for help.","zh":"老婦人舉起一隻顫抖的手求助。"},{"en":"A trembling hand can show that someone is frightened even without words.","zh":"一隻顫抖的手即使沒有說話，也能顯示一個人很害怕。"},{"en":"On every screen, one trembling hand reached towards the sleeping man.","zh":"每個螢幕上，一隻顫抖的手伸向那個睡着的男人。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"reaching out","meaning":"伸出去","examples":[{"en":"His hand was reaching out towards the chair.","zh":"他的手正朝椅子伸出去。"},{"en":"Reaching out means stretching an arm or hand towards something or someone.","zh":"reaching out 指把手臂或手伸向某物或某人。"},{"en":"The child was reaching out for his mother’s hand.","zh":"孩子伸手去握媽媽的手。"},{"en":"People reach out when they want to touch, help, or take something.","zh":"人們想觸碰、幫助或拿取某物時，會把手伸出去。"},{"en":"Mr Wong’s hand was reaching out, although he wished he could stop it.","zh":"黃先生的手正伸出去，雖然他希望自己能停下來。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"on the screen first","meaning":"先在螢幕上","examples":[{"en":"The sleeping man opened his eyes on the screen first.","zh":"那個睡着的男人先在螢幕上睜開眼睛。"},{"en":"On the screen first means the action appeared on the monitor before it happened in the room.","zh":"on the screen first 指動作先在螢幕上出現，然後才在現實房間裏發生。"},{"en":"The singer appeared on the screen first, then walked onto the stage.","zh":"歌手先在螢幕上出現，然後才走上舞台。"},{"en":"Seeing something on the screen first can make real life feel delayed or unreal.","zh":"先在螢幕上看見某事，會令現實感覺延遲或不真實。"},{"en":"The man opened his eyes on the screen first, so Mr Wong knew time was wrong.","zh":"那個男人先在螢幕上睜開眼睛，所以黃先生知道時間出錯了。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"without turning around","meaning":"沒有轉身","examples":[{"en":"Without turning around, the sleeping man smiled.","zh":"那個睡着的男人沒有轉身就笑了。"},{"en":"Without turning around means without moving the body to face behind.","zh":"without turning around 指沒有把身體轉向後方。"},{"en":"Without turning around, the teacher knew the students were whispering.","zh":"老師沒有轉身，也知道學生正在低聲說話。"},{"en":"A person who answers without turning around may seem calm or frightening.","zh":"一個人沒有轉身就回答，可能顯得冷靜，也可能令人害怕。"},{"en":"The man smiled without turning around, as if he already knew Mr Wong was there.","zh":"那個男人沒有轉身就笑了，彷彿早已知道黃先生在那裏。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"by morning","meaning":"到了早上","examples":[{"en":"By morning, Nico found the security room empty.","zh":"到了早上，尼科發現保安室空無一人。"},{"en":"By morning means when morning arrived or before morning was over.","zh":"by morning 指到了早上時，或在早上結束前。"},{"en":"By morning, the rain had stopped and the streets were dry.","zh":"到了早上，雨已經停了，街道也乾了。"},{"en":"If a problem is not solved by morning, the manager will call for help.","zh":"如果問題到了早上仍未解決，經理會求助。"},{"en":"By morning, Mr Wong had disappeared from the security room.","zh":"到了早上，黃先生已經從保安室消失了。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"found the security room empty","meaning":"發現保安室空無一人","examples":[{"en":"Nico found the security room empty.","zh":"尼科發現保安室空無一人。"},{"en":"Found the security room empty means discovered that nobody was inside the guard’s room.","zh":"found the security room empty 指發現保安室裏沒有任何人。"},{"en":"The manager found the office empty after the night shift.","zh":"經理在夜班後發現辦公室空無一人。"},{"en":"Finding a room empty can be worrying if someone was supposed to be there.","zh":"如果某人本應在房間裏，發現房間空無一人會令人擔心。"},{"en":"Nico found the security room empty, although Mr Wong should have finished his shift there.","zh":"尼科發現保安室空無一人，雖然黃先生本應在那裏完成班次。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"the sensor was silent","meaning":"感應器沒有再響","examples":[{"en":"The rear door sensor was silent.","zh":"後門感應器沒有再響。"},{"en":"The sensor was silent means the device made no sound or warning.","zh":"the sensor was silent 指裝置沒有發出聲音或警告。"},{"en":"The smoke sensor was silent because there was no danger.","zh":"煙霧感應器沒有響，因為沒有危險。"},{"en":"A silent sensor can be reassuring, but it can also mean the system has stopped working.","zh":"沉默的感應器可以令人安心，但也可能代表系統停止運作。"},{"en":"The rear door sensor was silent, as if nothing had happened during the night.","zh":"後門感應器沒有再響，彷彿那晚甚麼也沒有發生。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"contest entry","meaning":"比賽參賽作品","examples":[{"en":"On the desk was a contest entry.","zh":"桌上有一份比賽參賽作品。"},{"en":"A contest entry is a piece of work submitted for a competition.","zh":"contest entry 是提交到比賽中的作品。"},{"en":"The student’s poem became her contest entry for the school writing prize.","zh":"那名學生的詩成為她參加學校寫作獎的比賽作品。"},{"en":"A contest entry usually needs a title, content, and the writer’s name.","zh":"比賽參賽作品通常需要題目、內容和作者姓名。"},{"en":"The contest entry on the desk was frightening because nobody knew who wrote it.","zh":"桌上的比賽參賽作品令人害怕，因為沒有人知道是誰寫的。"}],"source":"2021 Q7.pdf","sourcePage":11},{"front":"freshly printed","meaning":"剛列印出來的","examples":[{"en":"The contest entry was freshly printed.","zh":"那份比賽參賽作品是剛列印出來的。"},{"en":"Freshly printed means printed very recently.","zh":"freshly printed 指剛剛列印出來不久。"},{"en":"The teacher handed out freshly printed worksheets in the morning.","zh":"老師早上派發剛列印出來的工作紙。"},{"en":"Freshly printed paper may still feel warm from the printer.","zh":"剛列印出來的紙可能仍有打印機的暖意。"},{"en":"The freshly printed entry suggested that someone, or something, had used the printer overnight.","zh":"那份剛列印出來的作品暗示有人，或有東西，在夜裏使用過打印機。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"with no author’s name","meaning":"沒有作者署名","examples":[{"en":"The entry was freshly printed, with no author’s name.","zh":"那份作品剛列印出來，沒有作者署名。"},{"en":"With no author’s name means the writer was not identified on the work.","zh":"with no author’s name 指作品上沒有標明作者身份。"},{"en":"The story was rejected because it was submitted with no author’s name.","zh":"那篇故事因為沒有作者署名而被拒收。"},{"en":"A note with no author’s name can feel mysterious or suspicious.","zh":"沒有作者署名的字條可以令人覺得神秘或可疑。"},{"en":"The entry had no author’s name, as if the bookshop itself had written it.","zh":"那份作品沒有作者署名，彷彿是書店自己寫的。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"dropped the pages","meaning":"嚇得把紙張掉下","examples":[{"en":"Nico read the first line and dropped the pages.","zh":"尼科讀了第一行後，嚇得把紙張掉下。"},{"en":"Dropped the pages means let the papers fall, often because of shock or fear.","zh":"dropped the pages 指讓紙張掉落，通常因為震驚或恐懼。"},{"en":"She dropped the pages when she saw the exam result.","zh":"她看見考試結果時，把紙張掉下了。"},{"en":"A person may drop the pages if the message is too frightening to hold.","zh":"如果訊息太可怕，一個人可能會嚇得把紙張掉下。"},{"en":"Nico dropped the pages because the first line repeated the nightmare.","zh":"尼科嚇得把紙張掉下，因為第一行重複了那場噩夢。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"the first line","meaning":"第一行","examples":[{"en":"Nico read the first line of the story.","zh":"尼科讀了故事的第一行。"},{"en":"The first line is the opening sentence or first row of words in a text.","zh":"the first line 是文章的開首句子或第一行文字。"},{"en":"The first line of the poem made the whole class quiet.","zh":"那首詩的第一行令全班安靜下來。"},{"en":"A strong first line can make readers want to continue.","zh":"有力的第一行可以令讀者想繼續讀下去。"},{"en":"Nico feared the story as soon as he read the first line.","zh":"尼科一讀到第一行，就開始害怕那個故事。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"never clocked out","meaning":"從未打卡下班","examples":[{"en":"The guard in the title never clocked out.","zh":"題目中的保安員從未打卡下班。"},{"en":"Never clocked out means never recorded the end of work, suggesting he did not leave normally.","zh":"never clocked out 指從沒有記錄下班時間，暗示他沒有正常離開。"},{"en":"The worker never clocked out because he rushed to help during an emergency.","zh":"那名員工因為趕去協助緊急事件，所以從未打卡下班。"},{"en":"If someone never clocked out after a night shift, the manager would worry.","zh":"如果有人夜班後從未打卡下班，經理會擔心。"},{"en":"Mr Wong never clocked out because the bookshop kept him inside the story.","zh":"黃先生從未打卡下班，因為書店把他留在故事裏。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"clocked out","meaning":"打卡下班","examples":[{"en":"Mr Wong never clocked out after his night shift.","zh":"黃先生夜班後從未打卡下班。"},{"en":"Clocked out means recorded the time when work ended.","zh":"clocked out 指記錄工作結束的時間。"},{"en":"Factory workers clocked out at six before going home.","zh":"工廠員工六點打卡下班，然後回家。"},{"en":"If employees clock out late every day, they may be working overtime.","zh":"如果員工每天很晚才打卡下班，他們可能在加班。"},{"en":"Mr Wong clocked in at night, but he never clocked out in the morning.","zh":"黃先生晚上打卡上班，但早上從未打卡下班。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"the opening line","meaning":"開首第一句","examples":[{"en":"The story ended by repeating the opening line.","zh":"故事以重複開首第一句作結。"},{"en":"The opening line is the first sentence of a story, article, or poem.","zh":"the opening line 是故事、文章或詩的第一句。"},{"en":"A good opening line can quickly show the mood of a story.","zh":"好的開首第一句可以快速顯示故事氣氛。"},{"en":"When a story repeats the opening line at the end, it may create a circular structure.","zh":"當故事在結尾重複開首第一句時，可能會形成循環結構。"},{"en":"Repeating the opening line made Mr Wong’s story feel trapped in a loop.","zh":"重複開首第一句令黃先生的故事感覺困在循環裏。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"freshly printed entry","meaning":"剛列印出來的參賽作品","examples":[{"en":"Nico found a freshly printed entry on the desk.","zh":"尼科在桌上發現一份剛列印出來的參賽作品。"},{"en":"A freshly printed entry is a competition piece that has just come out of the printer.","zh":"freshly printed entry 是剛從打印機列印出來的比賽作品。"},{"en":"The judge picked up a freshly printed entry before the contest deadline.","zh":"評判在比賽截止前拿起一份剛列印出來的參賽作品。"},{"en":"A freshly printed entry with no writer’s name can make people wonder who submitted it.","zh":"一份沒有作者姓名的剛列印出來的參賽作品，會令人猜想是誰提交的。"},{"en":"Nico found the freshly printed entry where Mr Wong’s flask had been.","zh":"尼科在黃先生保溫壺原本的位置，發現那份剛列印出來的參賽作品。"}],"source":"2021 Q7.pdf","sourcePage":12},{"front":"no author’s name","meaning":"沒有作者署名","examples":[{"en":"The story had no author’s name.","zh":"那個故事沒有作者署名。"},{"en":"No author’s name means the writer’s name was not written on the work.","zh":"no author’s name 指作品上沒有寫作者的名字。"},{"en":"The teacher could not return the essay because it had no author’s name.","zh":"那篇文章沒有作者署名，所以老師無法歸還。"},{"en":"A story with no author’s name can feel anonymous, secretive, or suspicious.","zh":"沒有作者署名的故事會令人覺得匿名、神秘或可疑。"},{"en":"The story had no author’s name because perhaps no human had written it.","zh":"那個故事沒有作者署名，因為也許它不是由人類寫成的。"}],"source":"2021 Q7.pdf","sourcePage":12}],"dse/writing/part-b/2021/Q8":[{"front":"compared to","meaning":"被比作……","examples":[{"en":"In Joseph Parry’s poem, friendship is compared to precious metals.","zh":"在 Joseph Parry 的詩中，友誼被比作貴金屬。"},{"en":"When one thing is compared to another, people explain it by showing their similarities.","zh":"當一件事被比作另一件事時，人們會透過相似之處來解釋它。"},{"en":"A teacher may say hard work is compared to planting seeds because both need time before results appear.","zh":"老師可能會說努力被比作種子，因為兩者都需要時間才有成果。"},{"en":"Friendship is compared to precious metals because both can become more valuable over time.","zh":"友誼被比作貴金屬，因為兩者都可以隨時間變得更有價值。"},{"en":"If courage is compared to a candle, the image helps readers understand how it gives light in darkness.","zh":"如果勇氣被比作蠟燭，這個意象能幫助讀者明白它如何在黑暗中帶來光。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"precious metals","meaning":"貴金屬","examples":[{"en":"Friendship is compared to precious metals: new friends are silver, while old friends are gold.","zh":"友誼被比作貴金屬：新朋友如銀，舊朋友如金。"},{"en":"Precious metals are valuable materials, such as gold and silver, that people often keep or treasure.","zh":"貴金屬是有價值的材料，例如金和銀，人們常會保存或珍惜它們。"},{"en":"A family may keep rings made of precious metals because they carry memory and value.","zh":"一個家庭可能會保存由貴金屬製成的戒指，因為它們承載回憶和價值。"},{"en":"Precious metals are used in the poem to show that friendships can be valuable in different ways.","zh":"詩中使用貴金屬來顯示友誼可以以不同方式有價值。"},{"en":"Calling friendship a precious metal suggests that it should not be treated carelessly.","zh":"把友誼稱為貴金屬，暗示它不應被隨便對待。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"new friends are silver","meaning":"新朋友如銀","examples":[{"en":"In the poem, new friends are silver, while old friends are gold.","zh":"在詩中，新朋友如銀，舊朋友如金。"},{"en":"“New friends are silver” means new friendships are valuable, even if they have not lasted for many years.","zh":"「新朋友如銀」意思是新友誼也有價值，即使它們還未經歷多年時間。"},{"en":"A new classmate who listens kindly on the first day may show why new friends are silver.","zh":"開學第一天，一位新同學願意友善聆聽，便能顯示新朋友為何如銀。"},{"en":"New friends are silver because they can bring fresh support, new ideas, and unexpected kindness.","zh":"新朋友如銀，因為他們可以帶來新鮮支持、新想法和意想不到的善意。"},{"en":"The phrase reminds us not to ignore new friendships simply because they are recent.","zh":"這個短語提醒我們，不應只因友誼新近開始就忽視它。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"old friends are gold","meaning":"舊朋友如金","examples":[{"en":"The poem suggests that old friends are gold because they have lasting value.","zh":"這首詩暗示舊朋友如金，因為他們有持久價值。"},{"en":"“Old friends are gold” means long friendships are precious because they have survived time and change.","zh":"「舊朋友如金」意思是長久友誼很珍貴，因為它經歷過時間和轉變。"},{"en":"An old friend who remembers your fears before exams may understand you without long explanations.","zh":"一位記得你考試前恐懼的舊朋友，可能不需要你長篇解釋也能明白你。"},{"en":"Old friends are gold because shared memories can make their care more accurate and steady.","zh":"舊朋友如金，因為共同回憶能令他們的關心更準確和穩定。"},{"en":"The phrase does not mean new friends are useless; it means old friends have already proved their value.","zh":"這個短語不是說新朋友沒有用，而是說舊朋友已經證明了自己的價值。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"school life","meaning":"校園生活","examples":[{"en":"In school life, friendships are constantly reshaped.","zh":"在校園生活中，友誼不斷被重塑。"},{"en":"School life means the daily experience of studying, joining activities, meeting classmates, and growing up in school.","zh":"校園生活是指在學校讀書、參加活動、認識同學和成長的日常經驗。"},{"en":"In school life, students may make friends during lessons, lunch breaks, clubs, and examinations.","zh":"在校園生活中，學生可能在課堂、午餐、小組活動和考試期間交朋友。"},{"en":"School life can change friendships because students move classes, choose subjects, and join different groups.","zh":"校園生活可以改變友誼，因為學生會轉班、選科和加入不同群體。"},{"en":"Good friendships often make school life less lonely and more meaningful.","zh":"良好友誼常令校園生活不那麼孤單，並變得更有意義。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"constantly reshaped","meaning":"不斷被重塑","examples":[{"en":"In school life, friendships are constantly reshaped.","zh":"在校園生活中，友誼不斷被重塑。"},{"en":"If something is constantly reshaped, it changes again and again because new situations affect it.","zh":"如果某事不斷被重塑，意思是它因新情況影響而一次又一次改變。"},{"en":"A student’s friendship circle may be constantly reshaped when classes, clubs, and seats change.","zh":"當班別、學會和座位改變，學生的朋友圈可能不斷被重塑。"},{"en":"Friendships are constantly reshaped because people grow, misunderstand each other, and meet new classmates.","zh":"友誼不斷被重塑，因為人會成長、誤解彼此，也會認識新同學。"},{"en":"Being constantly reshaped does not mean friendship is fake; it means friendship is influenced by life.","zh":"不斷被重塑不代表友誼虛假，而是代表友誼會受生活影響。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"a new seatmate","meaning":"新同桌","examples":[{"en":"A new seatmate may become a lunch companion.","zh":"新同桌可能會成為午餐同伴。"},{"en":"A new seatmate is a person who has just started sitting next to you in class.","zh":"新同桌是剛開始在課堂上坐在你旁邊的人。"},{"en":"A shy student may first talk to a new seatmate by asking about homework.","zh":"害羞的學生可能先透過詢問功課來跟新同桌交談。"},{"en":"A new seatmate can become important because small daily conversations may grow into friendship.","zh":"新同桌可能變得重要，因為日常小對話可以發展成友誼。"},{"en":"Sometimes a new seatmate remains only a classmate, but sometimes they become a trusted friend.","zh":"有時新同桌只是一位同學，但有時他們會成為可信任的朋友。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"a lunch companion","meaning":"午餐同伴","examples":[{"en":"A new seatmate may become a lunch companion.","zh":"新同桌可能會成為午餐同伴。"},{"en":"A lunch companion is someone who eats with you and keeps you company during lunchtime.","zh":"午餐同伴是午飯時和你一起吃飯、陪伴你的人。"},{"en":"A student who feels lonely may feel safer when a lunch companion saves a seat for them.","zh":"感到孤單的學生，如果有午餐同伴替他留位，可能會感到安心一點。"},{"en":"A lunch companion can make a school day easier because lunchtime no longer feels awkward.","zh":"午餐同伴可以令上學日較易過，因為午飯時間不再尷尬。"},{"en":"A lunch companion may later become a close friend if both people enjoy talking together.","zh":"如果兩人喜歡一起聊天，午餐同伴日後可能成為親密朋友。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"a childhood friend","meaning":"童年朋友","examples":[{"en":"A childhood friend may move into another class, district, or dream.","zh":"童年朋友可能會轉到另一班、另一區，或走向另一個夢想。"},{"en":"A childhood friend is someone you have known since you were young.","zh":"童年朋友是你從小就認識的人。"},{"en":"A childhood friend may remember the games, mistakes, and small fears you had in primary school.","zh":"童年朋友可能記得你小學時玩的遊戲、犯過的錯和小小的恐懼。"},{"en":"A childhood friend can feel distant if both people grow in different directions.","zh":"如果兩個人成長方向不同，童年朋友也可能變得疏遠。"},{"en":"Even after years apart, a childhood friend may still understand parts of your past.","zh":"即使分開多年，童年朋友仍可能明白你過去的某些部分。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"move into another class","meaning":"轉到另一班","examples":[{"en":"A childhood friend may move into another class, district, or dream.","zh":"童年朋友可能會轉到另一班、另一區，或走向另一個夢想。"},{"en":"To move into another class means to leave one class group and join a different one.","zh":"轉到另一班意思是離開原本的班別，加入另一個班別。"},{"en":"A student may move into another class after choosing different subjects.","zh":"學生選擇不同科目後，可能會轉到另一班。"},{"en":"When a friend moves into another class, daily conversations may become less frequent.","zh":"當朋友轉到另一班，日常交談可能會減少。"},{"en":"Moving into another class does not have to end friendship if both people keep in touch.","zh":"如果兩人保持聯絡，轉到另一班不一定會結束友誼。"}],"source":"2021 Q8.pdf","sourcePage":1},{"front":"balance old and new friendships","meaning":"平衡新舊友誼","examples":[{"en":"Young people consider how to balance old and new friendships.","zh":"年輕人會思考如何平衡新舊友誼。"},{"en":"To balance old and new friendships means to make time for both long-time friends and recently made friends.","zh":"平衡新舊友誼意思是同時為長久朋友和新認識的朋友留時間。"},{"en":"A student balances old and new friendships by having lunch with a new group but still texting an old friend.","zh":"學生和新圈子吃午飯，同時仍傳訊息給舊朋友，就是在平衡新舊友誼。"},{"en":"If young people fail to balance old and new friendships, one side may feel forgotten.","zh":"如果年輕人未能平衡新舊友誼，其中一方可能會覺得被遺忘。"},{"en":"Balance does not mean equal time every day; it means showing care to both sides.","zh":"平衡不代表每天時間完全相等，而是代表對雙方都表達關心。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"emotionally rich lives","meaning":"情感豐富的生活","examples":[{"en":"Young people try to build emotionally rich lives.","zh":"年輕人嘗試建立情感豐富的生活。"},{"en":"Emotionally rich lives are lives filled with meaningful feelings, close relationships, care, and understanding.","zh":"情感豐富的生活是充滿有意義情感、親密關係、關心和理解的生活。"},{"en":"Students build emotionally rich lives when they have friends who celebrate success and comfort failure.","zh":"當學生有朋友一起慶祝成功、安慰失敗時，他們就在建立情感豐富的生活。"},{"en":"Emotionally rich lives can reduce loneliness because people feel seen and supported.","zh":"情感豐富的生活可以減少孤獨，因為人會感到被看見和被支持。"},{"en":"A busy life is not always an emotionally rich life if it lacks honest connection.","zh":"如果缺乏真誠連繫，忙碌的生活不一定是情感豐富的生活。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"my stance is that","meaning":"我的立場是","examples":[{"en":"My stance is that older friendships are better.","zh":"我的立場是，舊友誼比較好。"},{"en":"“My stance is that” introduces the opinion or position a person will defend.","zh":"「我的立場是」用來引出一個人將會支持的看法或位置。"},{"en":"In an essay, a student may write, “My stance is that homework should teach understanding, not just repetition.”","zh":"在文章中，學生可能寫：「我的立場是，功課應教理解，而不只是重複。」"},{"en":"This phrase helps readers know clearly what argument will follow.","zh":"這個短語幫助讀者清楚知道接下來的論點。"},{"en":"A strong essay usually explains why the writer’s stance is reasonable.","zh":"一篇有力的文章通常會解釋為何作者的立場合理。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"time, change and hardship","meaning":"時間、轉變與困難","examples":[{"en":"Time, change, and hardship reveal the depth of trust.","zh":"時間、轉變與困難會顯示信任的深度。"},{"en":"Time, change and hardship refer to years passing, life becoming different, and difficulties testing a relationship.","zh":"時間、轉變與困難是指歲月流逝、生活變得不同，以及困難考驗一段關係。"},{"en":"Friends may face time, change and hardship when they enter different schools and become busier.","zh":"當朋友升讀不同學校並變得更忙碌時，他們可能面對時間、轉變與困難。"},{"en":"Time, change and hardship can reveal whether friendship is based on convenience or real care.","zh":"時間、轉變與困難可以顯示友誼是建基於方便，還是真正關心。"},{"en":"A friendship that survives time, change and hardship often feels especially steady.","zh":"經歷時間、轉變與困難仍能維持的友誼，往往特別穩定。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"reveal the depth of trust","meaning":"顯示信任的深度","examples":[{"en":"Time, change, and hardship reveal the depth of trust.","zh":"時間、轉變與困難會顯示信任的深度。"},{"en":"To reveal the depth of trust means to show how strong and real trust is.","zh":"顯示信任的深度意思是表明信任有多堅固和真實。"},{"en":"A friend reveals the depth of trust when they keep your secret even after an argument.","zh":"朋友即使在爭吵後仍保守你的秘密，便顯示信任的深度。"},{"en":"Difficult moments reveal the depth of trust because people’s actions become more important than words.","zh":"困難時刻會顯示信任的深度，因為行動比說話更重要。"},{"en":"Easy times may create friendship, but hard times often reveal the depth of trust.","zh":"順利時光可能建立友誼，但困難時光常會顯示信任的深度。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"not by freshness, but by faithfulness","meaning":"不是憑新鮮感，而是憑忠誠","examples":[{"en":"Friendship should be judged not by freshness, but by faithfulness.","zh":"友誼應該不是憑新鮮感，而是憑忠誠來判斷。"},{"en":"“Not by freshness, but by faithfulness” means friendship should be valued by loyalty, not by how new it feels.","zh":"「不是憑新鮮感，而是憑忠誠」意思是友誼應按忠誠來珍視，而不是按它有多新鮮。"},{"en":"A new friend may seem exciting, but a faithful friend stays when life becomes difficult.","zh":"新朋友可能令人興奮，但忠誠的朋友會在生活困難時留下。"},{"en":"Judging friendship by freshness can make people chase novelty and neglect those who truly care.","zh":"用新鮮感判斷友誼，可能令人追逐新奇而忽略真正關心自己的人。"},{"en":"This phrase contrasts temporary excitement with steady commitment.","zh":"這個短語把短暫興奮和穩定承諾作出對比。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"shared history","meaning":"共同經歷","examples":[{"en":"The first difference between old and new friendships lies in shared history.","zh":"舊友誼和新友誼的第一個分別在於共同經歷。"},{"en":"Shared history means past experiences, memories, and events that two people have gone through together.","zh":"共同經歷是指兩個人一起經歷過的過去經驗、回憶和事件。"},{"en":"Two classmates have shared history if they studied for exams, joined clubs, and made mistakes together.","zh":"如果兩位同學一起溫習考試、參加學會和犯過錯，他們便有共同經歷。"},{"en":"Shared history makes friendship deeper because each person understands the other’s background.","zh":"共同經歷令友誼更深，因為每個人都明白對方的背景。"},{"en":"Without shared history, a friendship may still be kind, but it may need more time to deepen.","zh":"沒有共同經歷的友誼仍可以友善，但可能需要更多時間變深。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"lies in","meaning":"在於……","examples":[{"en":"The first difference lies in shared history.","zh":"第一個分別在於共同經歷。"},{"en":"“Lies in” means the main reason, answer, or difference is found in something.","zh":"“Lies in” 意思是主要原因、答案或分別存在於某事之中。"},{"en":"The value of a good teacher lies in patience, clear explanation, and care for students.","zh":"好老師的價值在於耐性、清楚解釋和對學生的關心。"},{"en":"The problem may lie in poor communication, not in bad intentions.","zh":"問題可能在於溝通不良，而不是惡意。"},{"en":"This phrase helps writers point clearly to the real source of an idea.","zh":"這個短語幫助作者清楚指出一個想法的真正來源。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"begin with similarity","meaning":"始於相似之處","examples":[{"en":"New friendships often begin with similarity.","zh":"新友誼往往始於相似之處。"},{"en":"To begin with similarity means to start because two people share something in common.","zh":"始於相似之處意思是兩個人因有共同點而開始建立關係。"},{"en":"Two students may become friends because they like the same singer, game, or subject.","zh":"兩位學生可能因喜歡同一位歌手、遊戲或科目而成為朋友。"},{"en":"Similarity helps new friendships begin because people feel safer talking about common interests.","zh":"相似之處幫助新友誼開始，因為人們談共同興趣時會較安心。"},{"en":"However, a friendship that begins with similarity still needs trust to last.","zh":"然而，始於相似之處的友誼仍需要信任才能持久。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"the same class","meaning":"同一班","examples":[{"en":"New friends may share the same class, hobby, online game, or taste in music.","zh":"新朋友可能同一班、有同一興趣、玩同一網上遊戲，或有相同音樂品味。"},{"en":"The same class means the same group of students learning together in school.","zh":"同一班是指在學校中一起學習的同一組學生。"},{"en":"Students in the same class may naturally talk because they attend lessons and receive homework together.","zh":"同一班的學生可能自然會交談，因為他們一起上課和收到功課。"},{"en":"Being in the same class can create friendship because people meet every day.","zh":"同一班可以創造友誼，因為人們每天見面。"},{"en":"After students leave the same class, they may need effort to keep the friendship alive.","zh":"當學生不再同一班後，他們可能需要付出努力來維持友誼。"}],"source":"2021 Q8.pdf","sourcePage":2},{"front":"taste in music","meaning":"音樂品味","examples":[{"en":"New friends may share the same taste in music.","zh":"新朋友可能有相同音樂品味。"},{"en":"Taste in music means the kinds of songs, singers, or styles a person likes.","zh":"音樂品味是指一個人喜歡的歌曲、歌手或音樂風格。"},{"en":"Two classmates may become friends after discovering that they have the same taste in music.","zh":"兩位同學發現自己有相同音樂品味後，可能會成為朋友。"},{"en":"Similar taste in music can start conversations because people enjoy recommending songs to each other.","zh":"相似的音樂品味可以展開對話，因為人們喜歡互相推薦歌曲。"},{"en":"Different taste in music does not prevent friendship if people respect each other’s choices.","zh":"如果人們尊重彼此選擇，不同音樂品味也不會阻止友誼。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"present polished versions of themselves","meaning":"展示經修飾的自己","examples":[{"en":"Both sides can present polished versions of themselves.","zh":"雙方都可以展示經修飾的自己。"},{"en":"To present polished versions of themselves means to show only the neat, confident, or attractive side of one’s personality.","zh":"展示經修飾的自己意思是只呈現自己整齊、自信或吸引人的一面。"},{"en":"On the first day of school, students may present polished versions of themselves by hiding nervousness.","zh":"開學第一天，學生可能透過隱藏緊張來展示經修飾的自己。"},{"en":"People present polished versions of themselves because they want to make a good impression.","zh":"人們展示經修飾的自己，因為他們想留下好印象。"},{"en":"Old friends often know the less polished parts that new friends have not yet seen.","zh":"舊朋友通常知道新朋友尚未看見的、不那麼修飾的一面。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"by contrast","meaning":"相比之下","examples":[{"en":"By contrast, an old friend knows the unfinished version of us.","zh":"相比之下，舊朋友認識尚未成熟的我們。"},{"en":"“By contrast” introduces a clear difference from the idea just mentioned.","zh":"“By contrast” 用來引出與前面想法清楚不同的一點。"},{"en":"New friends may know your recent hobbies; by contrast, old friends may remember your childhood fears.","zh":"新朋友可能知道你最近的興趣；相比之下，舊朋友可能記得你童年的恐懼。"},{"en":"Writers use “by contrast” to make the difference between two points easier to see.","zh":"作者使用 “by contrast” 來令兩點之間的分別更容易看見。"},{"en":"This phrase is useful when comparing new friendship with old friendship.","zh":"這個短語在比較新友誼和舊友誼時很有用。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"the public version of us","meaning":"我們展現於人前的一面","examples":[{"en":"An old friend knows not only the public version of us but also the unfinished one.","zh":"舊朋友認識的不只是我們展現於人前的一面，也認識尚未成熟的一面。"},{"en":"The public version of us is the side we show to classmates, teachers, or strangers.","zh":"我們展現於人前的一面，是我們給同學、老師或陌生人看到的一面。"},{"en":"A student’s public version may look cheerful, even when they feel worried inside.","zh":"學生展現於人前的一面可能很開朗，即使內心感到擔心。"},{"en":"Old friends understand more than the public version of us because they have seen private struggles too.","zh":"舊朋友理解的不只是我們展現於人前的一面，因為他們也見過私下的掙扎。"},{"en":"The public version of us is not fake, but it is often incomplete.","zh":"我們展現於人前的一面並非虛假，但通常並不完整。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"the unfinished one","meaning":"尚未成熟的一面","examples":[{"en":"An old friend also knows the unfinished one.","zh":"舊朋友也認識尚未成熟的一面。"},{"en":"The unfinished one means the imperfect, still-growing side of a person.","zh":"尚未成熟的一面是指一個人不完美、仍在成長的一面。"},{"en":"A friend who saw you make mistakes in junior forms knows the unfinished one.","zh":"見過你在初中犯錯的朋友，認識你尚未成熟的一面。"},{"en":"Knowing the unfinished one can make friendship warmer because there is less need to pretend.","zh":"認識尚未成熟的一面可以令友誼更溫暖，因為較少需要假裝。"},{"en":"Everyone has an unfinished side because people continue learning and changing.","zh":"每個人都有尚未成熟的一面，因為人會繼續學習和改變。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"a timid child","meaning":"膽怯的孩子","examples":[{"en":"An old friend may remember us as a timid child.","zh":"舊朋友可能記得我們曾是膽怯的孩子。"},{"en":"A timid child is a child who feels shy, nervous, or afraid in new situations.","zh":"膽怯的孩子是在新情況中感到害羞、緊張或害怕的孩子。"},{"en":"A timid child may hide behind a parent when meeting new classmates.","zh":"膽怯的孩子見到新同學時，可能會躲在父母身後。"},{"en":"Remembering someone as a timid child shows how much the friend has seen them grow.","zh":"記得某人曾是膽怯的孩子，顯示朋友見證了他很多成長。"},{"en":"A timid child can become confident when they receive patience and support.","zh":"膽怯的孩子得到耐性和支持後，也可以變得自信。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"an awkward teenager","meaning":"尷尬青澀的少年","examples":[{"en":"An old friend may remember the awkward teenager we once were.","zh":"舊朋友可能記得我們曾經是尷尬青澀的少年。"},{"en":"An awkward teenager is a young person who feels uncomfortable, clumsy, or unsure of themselves.","zh":"尷尬青澀的少年是感到不自在、笨拙或對自己沒有把握的年輕人。"},{"en":"An awkward teenager may worry too much about clothes, speech, or being laughed at.","zh":"尷尬青澀的少年可能太擔心衣著、說話方式或被人取笑。"},{"en":"Old friends who remember an awkward teenager understand the difficult stage behind today’s confidence.","zh":"記得你曾是尷尬青澀少年的舊朋友，明白今天自信背後的困難階段。"},{"en":"Being an awkward teenager is common because growing up often feels confusing.","zh":"成為尷尬青澀的少年很常見，因為成長常令人困惑。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"pretend to be fine","meaning":"假裝沒事","examples":[{"en":"An old friend remembers the person who cried after a failed test and pretended to be fine.","zh":"舊朋友記得那個考試失敗後哭過、卻假裝沒事的人。"},{"en":"To pretend to be fine means to act as if nothing is wrong when you are actually upset.","zh":"假裝沒事意思是明明難過，卻表現得好像沒有問題。"},{"en":"A student may smile and pretend to be fine after losing a competition.","zh":"學生比賽失敗後可能微笑並假裝沒事。"},{"en":"People pretend to be fine because they do not want others to worry or ask questions.","zh":"人們假裝沒事，因為他們不想別人擔心或追問。"},{"en":"A close friend may notice when you pretend to be fine and quietly offer help.","zh":"親密朋友可能察覺你在假裝沒事，並安靜地提供幫助。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"shorten emotional distance","meaning":"縮短情感距離","examples":[{"en":"This history shortens emotional distance.","zh":"這段歷史縮短了情感距離。"},{"en":"To shorten emotional distance means to make people feel closer and more easily understood.","zh":"縮短情感距離意思是令人感覺更親近、更容易被理解。"},{"en":"Sharing childhood memories can shorten emotional distance between two old classmates.","zh":"分享童年回憶可以縮短兩位舊同學之間的情感距離。"},{"en":"Emotional distance becomes shorter when people no longer need to explain every feeling from the beginning.","zh":"當人不再需要從頭解釋每種感受時，情感距離就會縮短。"},{"en":"A single familiar joke can shorten emotional distance after months apart.","zh":"分開數月後，一個熟悉的笑話也可以縮短情感距離。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"a single phrase","meaning":"一句說話","examples":[{"en":"A single phrase can reopen a whole room of memory.","zh":"一句說話可以重新喚起大量回憶。"},{"en":"A single phrase means just one short group of words.","zh":"一句說話是指一組簡短的字詞。"},{"en":"A single phrase from an old song may remind friends of their primary school days.","zh":"一首舊歌中的一句說話，可能令朋友想起小學時光。"},{"en":"A single phrase can be powerful because it carries shared experience behind it.","zh":"一句說話可以很有力量，因為它背後承載共同經驗。"},{"en":"In close friendships, a single phrase may say more than a long explanation.","zh":"在親密友誼中，一句說話可能比長篇解釋更有意思。"}],"source":"2021 Q8.pdf","sourcePage":3},{"front":"reopen a whole room of memory","meaning":"重新喚起大量回憶","examples":[{"en":"A single phrase can reopen a whole room of memory.","zh":"一句說話可以重新喚起大量回憶。"},{"en":"To reopen a whole room of memory means to bring back many old memories suddenly and vividly.","zh":"重新喚起大量回憶意思是突然而鮮明地帶回許多舊回憶。"},{"en":"Seeing an old classroom may reopen a whole room of memory for former students.","zh":"看見舊課室可能會為舊生重新喚起大量回憶。"},{"en":"Shared jokes reopen a whole room of memory because they connect the present with the past.","zh":"共同笑話會重新喚起大量回憶，因為它們把現在和過去連在一起。"},{"en":"This phrase suggests that memory can feel like a place we enter again.","zh":"這個短語暗示回憶可以像一個我們再次走進的地方。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"give context","meaning":"提供背景脈絡","examples":[{"en":"More importantly, history gives context.","zh":"更重要的是，歷史提供背景脈絡。"},{"en":"To give context means to provide background information that helps people understand something correctly.","zh":"提供背景脈絡意思是給出背景資料，幫助人正確理解某事。"},{"en":"A teacher gives context before a poem by explaining when and why it was written.","zh":"老師在教詩前解釋它何時及為何寫成，就是提供背景脈絡。"},{"en":"Old memories give context to a friend’s behaviour because they show what shaped that person.","zh":"舊回憶為朋友的行為提供背景脈絡，因為它們顯示那個人如何被塑造。"},{"en":"Without context, silence may look rude when it actually means sadness or fear.","zh":"沒有背景脈絡，沉默可能看似無禮，但其實可能代表傷心或恐懼。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"unusually silent","meaning":"異常沉默","examples":[{"en":"An old friend may notice that I am unusually silent.","zh":"舊朋友可能會注意到我異常沉默。"},{"en":"Unusually silent means much quieter than normal in a way that may show something is wrong.","zh":"異常沉默意思是比平常安靜得多，可能顯示有問題。"},{"en":"A talkative student who becomes unusually silent after lunch may be upset.","zh":"一位健談的學生午飯後變得異常沉默，可能是感到難過。"},{"en":"Being unusually silent can signal worry, disappointment, tiredness, or hidden pressure.","zh":"異常沉默可能表示擔心、失望、疲倦或隱藏壓力。"},{"en":"A caring friend notices unusually silent behaviour instead of ignoring it.","zh":"關心人的朋友會注意異常沉默的行為，而不是忽視它。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"not merely","meaning":"不只是","examples":[{"en":"He does not merely ask whether I am tired.","zh":"他不只是問我是否疲倦。"},{"en":"“Not merely” means not only this simple thing, but something more important as well.","zh":"“Not merely” 意思是不只是這件簡單的事，還有更重要的東西。"},{"en":"A good teacher does not merely mark mistakes; she explains how to improve them.","zh":"好老師不只是批改錯誤，還會解釋如何改善。"},{"en":"Old friends do not merely hear your words because they also read your mood and history.","zh":"舊朋友不只是聽你的說話，因為他們也會讀懂你的情緒和過去。"},{"en":"This phrase helps show that an action has deeper meaning than it first seems.","zh":"這個短語幫助顯示一個行動比表面看來有更深意思。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"recognise my habit of withdrawing","meaning":"察覺我退縮的習慣","examples":[{"en":"He may recognise my habit of withdrawing when I feel disappointed.","zh":"他可能察覺我在感到失望時會退縮的習慣。"},{"en":"To recognise my habit of withdrawing means to notice that I usually become quiet or distant when I am upset.","zh":"察覺我退縮的習慣意思是注意到我難過時通常會變得安靜或疏遠。"},{"en":"An old friend may recognise my habit of withdrawing after I stop replying to messages.","zh":"當我停止回覆訊息後，舊朋友可能會察覺我退縮的習慣。"},{"en":"Recognising this habit helps a friend offer support before the sadness becomes worse.","zh":"察覺這個習慣能幫助朋友在悲傷惡化前提供支持。"},{"en":"New friends may miss this sign because they do not yet know my patterns.","zh":"新朋友可能錯過這個訊號，因為他們還未知道我的模式。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"feel disappointed","meaning":"感到失望","examples":[{"en":"I often withdraw when I feel disappointed.","zh":"我感到失望時常會退縮。"},{"en":"To feel disappointed means to feel unhappy because something did not happen as hoped.","zh":"感到失望意思是因事情沒有如希望般發生而不開心。"},{"en":"A student may feel disappointed after studying hard but receiving a low mark.","zh":"學生努力溫習後仍得到低分，可能會感到失望。"},{"en":"People may become quiet when they feel disappointed because they need time to accept the result.","zh":"人們感到失望時可能變得安靜，因為他們需要時間接受結果。"},{"en":"A good friend does not laugh when you feel disappointed; they help you recover.","zh":"好朋友不會在你感到失望時取笑你，而會幫助你恢復。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"study together since junior secondary","meaning":"自初中起一起讀書","examples":[{"en":"Two classmates have studied together since junior secondary.","zh":"兩位同學自初中起一起讀書。"},{"en":"To study together since junior secondary means to have been classmates or study partners from the early years of secondary school.","zh":"自初中起一起讀書意思是從中學早期開始成為同學或學習夥伴。"},{"en":"Students who study together since junior secondary may know each other’s strengths and fears.","zh":"自初中起一起讀書的學生，可能知道彼此的強項和恐懼。"},{"en":"Studying together for years creates shared habits, memories, and trust.","zh":"多年一起讀書會建立共同習慣、回憶和信任。"},{"en":"By Form Six, friends who studied together since junior secondary may understand each other quickly.","zh":"到中六時，自初中起一起讀書的朋友可能很快明白彼此。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"by Form Six","meaning":"到中六時","examples":[{"en":"By Form Six, one look may be enough to show that a friend is nervous.","zh":"到中六時，一個眼神可能已足以顯示朋友很緊張。"},{"en":"By Form Six means by the final senior secondary year in the Hong Kong school system.","zh":"到中六時是指到香港學制中的高中最後一年時。"},{"en":"By Form Six, students may have spent many years learning, failing, and growing together.","zh":"到中六時，學生可能已一起學習、失敗和成長多年。"},{"en":"By Form Six, friendship can become deeper because classmates have faced many school pressures together.","zh":"到中六時，友誼可能更深，因為同學一起面對過很多學業壓力。"},{"en":"The phrase shows that time has passed and experience has built understanding.","zh":"這個短語顯示時間已過去，而經驗建立了理解。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"one look at","meaning":"看一眼……","examples":[{"en":"One look at a trembling hand may be enough for a friend to understand.","zh":"看一眼顫抖的手，朋友可能已經明白。"},{"en":"One look at something means a quick glance that gives information immediately.","zh":"看一眼某物意思是快速一瞥，並立即得到一些資訊。"},{"en":"One look at a student’s tired face may tell a teacher that the class needs a break.","zh":"老師看一眼學生疲倦的臉，可能就知道全班需要休息。"},{"en":"Close friends need only one look at small details because they know each other’s usual behaviour.","zh":"親密朋友只需看一眼小細節，因為他們知道彼此平常的行為。"},{"en":"One look at an empty lunch box may show that someone was too busy to eat.","zh":"看一眼空的飯盒，可能顯示某人太忙而沒有吃飯。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"a trembling hand","meaning":"顫抖的手","examples":[{"en":"One look at a trembling hand before an examination may be enough.","zh":"考試前看一眼顫抖的手，可能已經足夠。"},{"en":"A trembling hand is a hand that shakes because of fear, coldness, illness, or nervousness.","zh":"顫抖的手是因恐懼、寒冷、疾病或緊張而發抖的手。"},{"en":"A student may hide a trembling hand before giving a speech.","zh":"學生演講前可能會隱藏顫抖的手。"},{"en":"A trembling hand can show anxiety even when a person says they are fine.","zh":"即使一個人說自己沒事，顫抖的手也可以顯示焦慮。"},{"en":"A caring friend may notice a trembling hand and offer calm support.","zh":"關心人的朋友可能注意到顫抖的手，並提供平靜支持。"}],"source":"2021 Q8.pdf","sourcePage":4},{"front":"before an examination","meaning":"考試前","examples":[{"en":"A trembling hand before an examination may show anxiety.","zh":"考試前顫抖的手可能顯示焦慮。"},{"en":"Before an examination means in the time just before a test begins.","zh":"考試前意思是測驗開始之前的一段時間。"},{"en":"Before an examination, students may review notes, sharpen pencils, or breathe deeply to calm down.","zh":"考試前，學生可能會重溫筆記、削鉛筆或深呼吸來冷靜。"},{"en":"Pressure often rises before an examination because students worry about results.","zh":"考試前壓力常會上升，因為學生擔心成績。"},{"en":"A kind word before an examination can help a nervous friend feel less alone.","zh":"考試前一句善意說話，可以幫助緊張的朋友不那麼孤單。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"offer a spare pen","meaning":"提供一支後備筆","examples":[{"en":"A friend may offer a spare pen, a joke, or quiet company.","zh":"朋友可能會提供一支後備筆、一個笑話，或安靜的陪伴。"},{"en":"To offer a spare pen means to give an extra pen to someone who needs one.","zh":"提供一支後備筆意思是把額外的筆給需要的人。"},{"en":"Before an exam, a classmate may offer a spare pen to a student who forgot their pencil case.","zh":"考試前，同學可能會向忘記筆袋的學生提供一支後備筆。"},{"en":"Offering a spare pen is a small action, but it can reduce another person’s panic.","zh":"提供一支後備筆是小小行動，但可以減少別人的慌張。"},{"en":"In friendship, simple help like offering a spare pen can show real care.","zh":"在友誼中，提供一支後備筆這類簡單幫助也能顯示真正關心。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"quiet company","meaning":"安靜的陪伴","examples":[{"en":"A friend may offer quiet company before an examination.","zh":"朋友可能會在考試前提供安靜的陪伴。"},{"en":"Quiet company means staying with someone calmly without forcing them to talk.","zh":"安靜的陪伴意思是平靜地留在某人身邊，而不強迫對方說話。"},{"en":"When a student is upset, quiet company may help more than many questions.","zh":"當學生難過時，安靜的陪伴可能比很多問題更有幫助。"},{"en":"Quiet company is useful because some people need presence, not advice, when they are nervous.","zh":"安靜的陪伴很有用，因為有些人在緊張時需要的是陪伴，而不是建議。"},{"en":"A true friend knows when to speak and when to give quiet company.","zh":"真正的朋友知道何時說話，何時給予安靜的陪伴。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"with greater precision","meaning":"更準確地","examples":[{"en":"Older friends often understand with greater precision.","zh":"舊朋友往往更準確地理解。"},{"en":"With greater precision means more accurately and with better understanding of details.","zh":"更準確地意思是更精確，並更能理解細節。"},{"en":"A doctor diagnoses with greater precision after asking clear questions and checking symptoms.","zh":"醫生清楚提問並檢查症狀後，能更準確地診斷。"},{"en":"Old friends understand with greater precision because they know your habits, fears, and past experiences.","zh":"舊朋友能更準確地理解，因為他們知道你的習慣、恐懼和過去經歷。"},{"en":"Care becomes more helpful when it is given with greater precision.","zh":"當關心能更準確地給予，它會更有幫助。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"carries memory","meaning":"承載回憶","examples":[{"en":"Old friendship is gold because it carries memory.","zh":"舊友誼如金，因為它承載回憶。"},{"en":"If friendship carries memory, it holds shared experiences from the past.","zh":"如果友誼承載回憶，意思是它保存了過去的共同經驗。"},{"en":"A friendship carries memory when two people remember old classrooms, jokes, and struggles together.","zh":"當兩個人一起記得舊課室、笑話和掙扎，這段友誼便承載回憶。"},{"en":"Memory makes friendship valuable because it gives present care a deeper background.","zh":"回憶令友誼有價值，因為它為當下的關心提供更深背景。"},{"en":"A new friendship may become stronger as it slowly carries memory too.","zh":"新友誼也可以隨時間慢慢承載回憶而變強。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"make care more intelligent","meaning":"令關心更懂得分寸","examples":[{"en":"Memory makes care more intelligent.","zh":"回憶令關心更懂得分寸。"},{"en":"To make care more intelligent means to make support wiser, more suitable, and more sensitive to a person’s needs.","zh":"令關心更懂得分寸意思是令支持更明智、更合適，也更能照顧一個人的需要。"},{"en":"A friend who knows you dislike public attention may help quietly, making care more intelligent.","zh":"知道你不喜歡公開受關注的朋友，可能會安靜地幫助你，令關心更懂得分寸。"},{"en":"Care becomes more intelligent when it is based on memory, not guessing.","zh":"當關心建基於回憶而不是猜測，它便更懂得分寸。"},{"en":"Intelligent care does not always mean doing more; sometimes it means doing the right small thing.","zh":"懂得分寸的關心不一定是做更多；有時是做對那件小事。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"more dependable","meaning":"更可靠","examples":[{"en":"Older friendships are more dependable because they have survived disruption.","zh":"舊友誼更可靠，因為它們經受過變動。"},{"en":"More dependable means more reliable and more likely to stay strong when problems appear.","zh":"更可靠意思是更值得信賴，並更可能在問題出現時保持穩定。"},{"en":"A dependable friend arrives on time when you need help after school.","zh":"可靠的朋友會在你放學後需要幫助時準時到達。"},{"en":"Old friendships may be more dependable because they have already faced arguments and distance.","zh":"舊友誼可能更可靠，因為它們已經面對過爭吵和距離。"},{"en":"A friendship is not more dependable because it is old only; it must also remain caring.","zh":"友誼並非只因為舊就更可靠；它也必須保持關心。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"survive disruption","meaning":"經受變動","examples":[{"en":"Older friendships are more dependable because they have survived disruption.","zh":"舊友誼更可靠，因為它們經受過變動。"},{"en":"To survive disruption means to continue even after change, trouble, or interruption.","zh":"經受變動意思是在改變、困難或中斷之後仍然持續。"},{"en":"A friendship may survive disruption when one student moves school but both still call each other.","zh":"當一位學生轉校後，兩人仍互相通電話，友誼便可能經受變動。"},{"en":"Surviving disruption proves that the relationship is not based only on convenience.","zh":"經受變動證明關係不只是建基於方便。"},{"en":"Friendships that survive disruption often become stronger because people choose to stay connected.","zh":"經受變動的友誼往往變得更強，因為人們選擇保持連繫。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"when life is convenient","meaning":"當生活方便時","examples":[{"en":"It is easy to be friendly when life is convenient.","zh":"當生活方便時，表現友善是容易的。"},{"en":"When life is convenient means when schedules, distance, and situations make friendship easy.","zh":"當生活方便時，是指時間表、距離和情況都令友誼容易維持。"},{"en":"Classmates may be friendly when life is convenient because they see each other every day.","zh":"同學在生活方便時可能很友善，因為他們每天見面。"},{"en":"The real strength of friendship appears when life is no longer convenient.","zh":"當生活不再方便時，友誼的真正力量才會顯現。"},{"en":"Being kind only when life is convenient may not prove deep loyalty.","zh":"只在生活方便時友善，未必能證明深厚忠誠。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"timetables match","meaning":"時間表配合","examples":[{"en":"Friendship feels easy when timetables match.","zh":"當時間表配合時，友誼感覺容易。"},{"en":"Timetables match when two people are free at the same time or follow similar schedules.","zh":"時間表配合是指兩個人在同一時間有空，或有相似的日程。"},{"en":"Students whose timetables match can study, eat lunch, and go home together more easily.","zh":"時間表配合的學生較容易一起溫習、吃午飯和放學回家。"},{"en":"When timetables no longer match, friends need more effort to arrange time together.","zh":"當時間表不再配合，朋友需要更多努力安排相聚時間。"},{"en":"Matching timetables help friendship begin, but they do not guarantee lasting trust.","zh":"時間表配合有助友誼開始，但不能保證持久信任。"}],"source":"2021 Q8.pdf","sourcePage":5},{"front":"jokes land easily","meaning":"玩笑容易被接住","examples":[{"en":"Friendship feels easy when jokes land easily.","zh":"當玩笑容易被接住時，友誼感覺容易。"},{"en":"Jokes land easily when people understand them quickly and find them funny.","zh":"玩笑容易被接住，是指人們很快明白笑點並覺得有趣。"},{"en":"In a close group, jokes land easily because everyone knows the shared stories behind them.","zh":"在親密小組中，玩笑容易被接住，因為大家知道背後的共同故事。"},{"en":"If jokes do not land easily, people may feel awkward or misunderstood.","zh":"如果玩笑不容易被接住，人們可能會感到尷尬或被誤解。"},{"en":"Jokes landing easily can create warmth, but friendship also needs respect during serious moments.","zh":"玩笑容易被接住可以製造溫暖，但友誼在嚴肅時刻也需要尊重。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"the real test comes when","meaning":"真正的考驗在於","examples":[{"en":"The real test comes when circumstances become inconvenient.","zh":"真正的考驗在於情況變得不方便的時候。"},{"en":"“The real test comes when” introduces the moment that shows whether something is truly strong.","zh":"“The real test comes when” 用來引出能顯示某事是否真正堅固的時刻。"},{"en":"The real test comes when a friend needs help during your busiest week.","zh":"真正的考驗在於朋友在你最忙的一星期需要幫助時。"},{"en":"This phrase shows that easy situations do not fully prove loyalty.","zh":"這個短語顯示容易的情況不能完全證明忠誠。"},{"en":"In friendship, the real test comes when care requires effort, patience, or sacrifice.","zh":"在友誼中，真正的考驗在於關心需要努力、耐性或犧牲時。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"circumstances become inconvenient","meaning":"情況變得不方便","examples":[{"en":"The real test comes when circumstances become inconvenient.","zh":"真正的考驗在於情況變得不方便的時候。"},{"en":"Circumstances become inconvenient when the situation makes it harder to act kindly or stay connected.","zh":"情況變得不方便，是指環境令友善行動或保持聯絡變得更困難。"},{"en":"Circumstances become inconvenient when friends live far apart or have different examination schedules.","zh":"當朋友住得很遠或有不同考試時間表時，情況便變得不方便。"},{"en":"Friendship may weaken when circumstances become inconvenient if both sides stop making effort.","zh":"如果雙方停止付出努力，情況變得不方便時友誼可能變弱。"},{"en":"A strong friendship continues even when circumstances become inconvenient.","zh":"堅固的友誼即使在情況變得不方便時仍會延續。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"prepare for different futures","meaning":"為不同的未來作準備","examples":[{"en":"Friends may prepare for different futures.","zh":"朋友可能會為不同的未來作準備。"},{"en":"To prepare for different futures means to make plans that lead people in separate directions.","zh":"為不同的未來作準備意思是制定會把人帶向不同方向的計劃。"},{"en":"One friend may prepare for university while another prepares for work or overseas study.","zh":"一位朋友可能準備升讀大學，另一位則準備工作或海外升學。"},{"en":"Preparing for different futures can reduce daily contact because each person has new duties.","zh":"為不同的未來作準備可能會減少日常聯絡，因為每個人都有新責任。"},{"en":"Friends can prepare for different futures and still respect each other’s paths.","zh":"朋友可以為不同的未來作準備，同時仍尊重彼此的道路。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"disappoint one another","meaning":"令彼此失望","examples":[{"en":"Friends may disappoint one another at times.","zh":"朋友有時可能會令彼此失望。"},{"en":"To disappoint one another means to make each other feel let down or hurt by words, actions, or choices.","zh":"令彼此失望意思是因說話、行動或選擇而令對方感到失落或受傷。"},{"en":"Friends may disappoint one another when one forgets an important promise.","zh":"當其中一人忘記重要承諾時，朋友可能會令彼此失望。"},{"en":"Disappointment can damage friendship if people refuse to apologise or listen.","zh":"如果人們拒絕道歉或聆聽，失望可能傷害友誼。"},{"en":"Friends who disappoint one another can still repair the relationship through honesty and effort.","zh":"令彼此失望的朋友，仍可以透過誠實和努力修補關係。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"remain respectful through these changes","meaning":"在轉變中仍保持尊重","examples":[{"en":"A friendship that remains respectful through these changes has passed real tests.","zh":"一段在轉變中仍保持尊重的友誼，已經通過真正考驗。"},{"en":"To remain respectful through these changes means to keep treating each other politely and fairly while life changes.","zh":"在轉變中仍保持尊重意思是在生活改變時，仍以禮貌和公平對待彼此。"},{"en":"Friends remain respectful through these changes when they support different subject choices without mocking them.","zh":"朋友支持彼此不同的選科而不取笑，就是在轉變中仍保持尊重。"},{"en":"Respect helps friendship survive because change can easily create jealousy or misunderstanding.","zh":"尊重幫助友誼存續，因為轉變容易造成嫉妒或誤解。"},{"en":"A friendship may change shape, but it can stay healthy if people remain respectful.","zh":"友誼的形態可能改變，但如果人們仍保持尊重，它可以保持健康。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"pass examinations that no written promise can replace","meaning":"經過文字承諾無法取代的考驗","examples":[{"en":"A friendship that survives change has passed examinations that no written promise can replace.","zh":"能經歷轉變的友誼，已經通過文字承諾無法取代的考驗。"},{"en":"This phrase means real-life tests prove friendship better than words or formal promises.","zh":"這個短語意思是現實生活中的考驗，比說話或正式承諾更能證明友誼。"},{"en":"A friend who stays after conflict passes an examination that a simple message cannot replace.","zh":"衝突後仍留下的朋友，通過了一個簡單訊息無法取代的考驗。"},{"en":"Such examinations matter because loyalty is shown through action, not only through claims.","zh":"這些考驗重要，因為忠誠是透過行動顯示，而不只是聲稱。"},{"en":"In friendship, difficult moments can test people more deeply than any written promise.","zh":"在友誼中，困難時刻比任何文字承諾都更能深入考驗人。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"be excluded from a group chat","meaning":"被群組排除在外","examples":[{"en":"A student may be excluded from a group chat after a misunderstanding.","zh":"學生可能在誤會後被群組排除在外。"},{"en":"To be excluded from a group chat means to be left out of an online conversation group.","zh":"被群組排除在外意思是被排除在網上聊天群組之外。"},{"en":"A student may feel hurt if classmates create plans in a group chat but leave them out.","zh":"如果同學在群組中計劃活動卻把某人排除在外，那位學生可能會受傷。"},{"en":"Being excluded from a group chat can make someone feel rejected and socially isolated.","zh":"被群組排除在外可能令人感到被拒絕和被社交孤立。"},{"en":"Before excluding someone from a group chat, friends should first ask what really happened.","zh":"在把某人排除在群組之外前，朋友應先問清楚真正發生了甚麼。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"after a misunderstanding","meaning":"在誤會之後","examples":[{"en":"A student may be excluded from a group chat after a misunderstanding.","zh":"學生可能在誤會之後被群組排除在外。"},{"en":"After a misunderstanding means after people wrongly understand a situation or each other’s words.","zh":"在誤會之後，是指人們錯誤理解某個情況或彼此說話之後。"},{"en":"After a misunderstanding, classmates may avoid someone before hearing the full story.","zh":"在誤會之後，同學可能還未聽完整件事就避開某人。"},{"en":"Problems can grow after a misunderstanding if nobody explains or apologises.","zh":"如果沒有人解釋或道歉，誤會之後問題可能擴大。"},{"en":"A good friend asks questions after a misunderstanding instead of spreading rumours.","zh":"好朋友在誤會之後會提出問題，而不是散播謠言。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"hesitate","meaning":"猶豫","examples":[{"en":"A new friend may hesitate to take a side.","zh":"新朋友可能會猶豫是否表態支持某一方。"},{"en":"To hesitate means to pause before acting because you feel unsure or afraid.","zh":"猶豫意思是因不確定或害怕而在行動前停頓。"},{"en":"A student may hesitate before answering a difficult question in front of the class.","zh":"學生在全班面前回答困難問題前，可能會猶豫。"},{"en":"Friends may hesitate to help when they worry about becoming unpopular.","zh":"當朋友擔心變得不受歡迎時，可能會猶豫是否幫忙。"},{"en":"Hesitating is understandable, but silence can hurt someone who needs support.","zh":"猶豫可以理解，但沉默可能傷害需要支持的人。"}],"source":"2021 Q8.pdf","sourcePage":6},{"front":"take a side","meaning":"表態支持某一方","examples":[{"en":"A new friend may fear that taking a side will make them unpopular.","zh":"新朋友可能害怕表態支持某一方會令自己不受歡迎。"},{"en":"To take a side means to support one person or opinion in a disagreement.","zh":"表態支持某一方意思是在分歧中支持某個人或某個意見。"},{"en":"In a class argument, a student may take a side after hearing both explanations.","zh":"在班中爭執裏，學生可能在聽完雙方解釋後表態支持某一方。"},{"en":"Taking a side can be risky because others may accuse you of being unfair.","zh":"表態支持某一方可能有風險，因為其他人可能指責你不公平。"},{"en":"A mature person takes a side carefully, based on truth rather than popularity.","zh":"成熟的人會根據真相而不是人氣，謹慎地表態支持某一方。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"make someone unpopular","meaning":"令某人不受歡迎","examples":[{"en":"Taking a side may make someone unpopular.","zh":"表態支持某一方可能會令某人不受歡迎。"},{"en":"To make someone unpopular means to cause others to dislike, avoid, or criticise that person.","zh":"令某人不受歡迎意思是導致其他人不喜歡、避開或批評那個人。"},{"en":"Defending a wrongly blamed classmate may make someone unpopular in a careless group.","zh":"在一個不夠謹慎的群體中，維護被錯怪的同學可能會令某人不受歡迎。"},{"en":"Fear of becoming unpopular can stop people from doing what is fair.","zh":"害怕變得不受歡迎，可能阻止人做公平的事。"},{"en":"Being unpopular for telling the truth may be painful, but it can show moral courage.","zh":"因說真話而不受歡迎可能痛苦，但能顯示道德勇氣。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"ask what truly happened","meaning":"問清楚真相","examples":[{"en":"An old friend may ask what truly happened.","zh":"舊朋友可能會問清楚真相。"},{"en":"To ask what truly happened means to seek the real story before judging someone.","zh":"問清楚真相意思是在判斷某人之前尋找真正的事情經過。"},{"en":"A good classmate asks what truly happened before believing a rumour about a friend.","zh":"好同學在相信關於朋友的謠言前，會先問清楚真相。"},{"en":"Asking what truly happened can prevent unfair blame and unnecessary conflict.","zh":"問清楚真相可以避免不公平責怪和不必要衝突。"},{"en":"This action shows loyalty because the friend wants truth, not gossip.","zh":"這個行動顯示忠誠，因為朋友想知道真相，而不是八卦。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"defend someone when rumours spread","meaning":"在謠言傳開時維護某人","examples":[{"en":"An old friend may defend someone when rumours spread.","zh":"舊朋友可能會在謠言傳開時維護某人。"},{"en":"To defend someone when rumours spread means to speak up for a person while others repeat unproven stories.","zh":"在謠言傳開時維護某人，意思是在其他人重複未證實的故事時為那個人發聲。"},{"en":"A student may defend someone when rumours spread by saying, “We should ask them first.”","zh":"學生可以在謠言傳開時說「我們應該先問他本人」，以維護某人。"},{"en":"Defending someone can stop a false story from damaging their reputation.","zh":"維護某人可以阻止虛假故事損害他的名聲。"},{"en":"True friendship includes courage to defend someone fairly, not blindly.","zh":"真正友誼包括公平地維護某人的勇氣，而不是盲目維護。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"correct someone privately","meaning":"私下糾正某人","examples":[{"en":"An old friend may still correct someone privately if they were wrong.","zh":"如果某人錯了，舊朋友仍可能會私下糾正他。"},{"en":"To correct someone privately means to tell a person their mistake away from public embarrassment.","zh":"私下糾正某人意思是在不公開令對方尷尬的情況下指出錯誤。"},{"en":"A friend may correct someone privately after class instead of criticising them in the group chat.","zh":"朋友可能會在課後私下糾正某人，而不是在群組中批評他。"},{"en":"Private correction protects dignity while still helping the person learn.","zh":"私下糾正能保護尊嚴，同時仍幫助對方學習。"},{"en":"A loyal friend does not hide every mistake; they correct someone privately with care.","zh":"忠誠的朋友不會掩蓋所有錯誤；他們會帶著關心私下糾正某人。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"blind agreement","meaning":"盲目認同","examples":[{"en":"Such loyalty is not blind agreement.","zh":"這種忠誠不是盲目認同。"},{"en":"Blind agreement means supporting someone without thinking about whether they are right or wrong.","zh":"盲目認同意思是不思考對錯就支持某人。"},{"en":"A friend shows blind agreement if they defend a classmate’s lie only because they are close.","zh":"如果朋友只因關係親近就維護同學的謊言，那就是盲目認同。"},{"en":"Blind agreement can make friendship harmful because it ignores truth and responsibility.","zh":"盲目認同可能令友誼變得有害，因為它忽視真相和責任。"},{"en":"Real loyalty allows honest correction, not blind agreement.","zh":"真正忠誠容許誠實糾正，而不是盲目認同。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"stand beside someone","meaning":"站在某人身旁","examples":[{"en":"Loyalty is the courage to stand beside someone without abandoning moral judgement.","zh":"忠誠是有勇氣站在某人身旁，同時不放棄道德判斷。"},{"en":"To stand beside someone means to support them during difficulty or criticism.","zh":"站在某人身旁意思是在困難或批評中支持對方。"},{"en":"A friend may stand beside someone who is being unfairly blamed by classmates.","zh":"朋友可能會站在被同學不公平責怪的人身旁。"},{"en":"Standing beside someone matters because lonely people often need visible support.","zh":"站在某人身旁很重要，因為孤單的人常需要看得見的支持。"},{"en":"To stand beside someone does not mean agreeing with every choice they make.","zh":"站在某人身旁不代表同意他所作的每個選擇。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"moral judgement","meaning":"道德判斷","examples":[{"en":"Loyalty should not require abandoning moral judgement.","zh":"忠誠不應要求人放棄道德判斷。"},{"en":"Moral judgement is the ability to decide whether an action is right, wrong, fair, or unfair.","zh":"道德判斷是判斷一個行動是對、錯、公平或不公平的能力。"},{"en":"A student uses moral judgement when deciding whether to report cheating.","zh":"學生決定是否舉報作弊時，就是在使用道德判斷。"},{"en":"Friendship without moral judgement may protect bad behaviour instead of correcting it.","zh":"沒有道德判斷的友誼，可能會保護壞行為而不是糾正它。"},{"en":"A good friend keeps moral judgement while still showing care.","zh":"好朋友會保留道德判斷，同時仍表達關心。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"endure conflict, distance and personal growth","meaning":"經歷衝突、距離與個人成長","examples":[{"en":"Friendships that have endured conflict, distance, and personal growth deserve special trust.","zh":"經歷衝突、距離與個人成長的友誼，值得特別信任。"},{"en":"To endure conflict, distance and personal growth means to survive arguments, separation, and changes in personality.","zh":"經歷衝突、距離與個人成長意思是承受爭執、分隔和性格改變。"},{"en":"Friends may endure conflict, distance and personal growth when they study in different places but keep communicating honestly.","zh":"當朋友在不同地方讀書但仍誠實溝通，他們可能經歷衝突、距離與個人成長。"},{"en":"These experiences test friendship because they make easy closeness harder.","zh":"這些經驗會考驗友誼，因為它們令輕鬆的親近變得更難。"},{"en":"A friendship that endures these pressures often becomes steadier and more mature.","zh":"能經歷這些壓力的友誼，往往變得更穩定和成熟。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"deserve special trust","meaning":"值得特別信任","examples":[{"en":"Friendships that have endured conflict deserve special trust.","zh":"經歷過衝突的友誼值得特別信任。"},{"en":"To deserve special trust means to be worthy of deeper confidence because something has been proved.","zh":"值得特別信任意思是因某事已被證明而值得更深信心。"},{"en":"A friend who keeps helping after disagreement may deserve special trust.","zh":"爭執後仍繼續幫助你的朋友，可能值得特別信任。"},{"en":"Special trust is earned through actions during difficult times, not only through kind words.","zh":"特別信任是透過困難時的行動贏得，而不只是靠好聽說話。"},{"en":"A friendship deserves special trust when it remains honest, respectful, and steady.","zh":"當一段友誼保持誠實、尊重和穩定，它便值得特別信任。"}],"source":"2021 Q8.pdf","sourcePage":7},{"front":"granted","meaning":"誠然","examples":[{"en":"Granted, it would be unfair to dismiss new friendships as shallow.","zh":"誠然，把新友誼視為膚淺而否定是不公平的。"},{"en":"“Granted” means the writer accepts one point before giving a different or stronger argument.","zh":"“Granted” 意思是作者先承認一點，再提出不同或更強的論點。"},{"en":"Granted, online learning is convenient, but students still need real discussion.","zh":"誠然，網上學習很方便，但學生仍需要真正討論。"},{"en":"Writers use “granted” to sound fair and reasonable before disagreeing partly.","zh":"作者使用 “granted” 來在部分不同意前顯得公平和合理。"},{"en":"In an essay, “granted” helps show that the writer understands both sides.","zh":"在文章中，“granted” 有助顯示作者理解雙方。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"dismiss something as shallow","meaning":"把……視為膚淺而否定","examples":[{"en":"It would be unfair to dismiss new friendships as shallow.","zh":"把新友誼視為膚淺而否定是不公平的。"},{"en":"To dismiss something as shallow means to reject it as lacking depth without considering it carefully.","zh":"把……視為膚淺而否定，意思是沒有仔細考慮就認為它缺乏深度並加以拒絕。"},{"en":"A teacher should not dismiss a student’s simple question as shallow because it may show real confusion.","zh":"老師不應把學生簡單的問題視為膚淺而否定，因為那可能顯示真正困惑。"},{"en":"People may dismiss new friendships as shallow when they judge only by time.","zh":"人們只按時間判斷時，可能會把新友誼視為膚淺而否定。"},{"en":"Before dismissing something as shallow, we should ask whether it has real value in another way.","zh":"在把某事視為膚淺而否定前，我們應問它是否以另一種方式有真正價值。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"bring energy, curiosity and fresh perspectives","meaning":"帶來活力、好奇心和新觀點","examples":[{"en":"New friends can bring energy, curiosity, and fresh perspectives.","zh":"新朋友可以帶來活力、好奇心和新觀點。"},{"en":"To bring energy, curiosity and fresh perspectives means to add liveliness, questions, and new ways of seeing things.","zh":"帶來活力、好奇心和新觀點意思是加入生命力、問題意識和看事物的新方式。"},{"en":"A new club member may bring energy, curiosity and fresh perspectives to a school project.","zh":"一位新學會成員可能為學校項目帶來活力、好奇心和新觀點。"},{"en":"New perspectives help because old groups can become too used to one way of thinking.","zh":"新觀點很有幫助，因為舊群體可能太習慣一種思考方式。"},{"en":"Friendship becomes richer when old trust meets new energy and curiosity.","zh":"當舊信任遇上新活力和好奇心，友誼會變得更豐富。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"fresh perspectives","meaning":"新角度","examples":[{"en":"New friends can bring fresh perspectives.","zh":"新朋友可以帶來新角度。"},{"en":"Fresh perspectives are new ways of thinking about a situation or problem.","zh":"新角度是看待情況或問題的新思考方式。"},{"en":"A new classmate may offer fresh perspectives on how to organise a group project.","zh":"新同學可能對如何組織小組項目提出新角度。"},{"en":"Fresh perspectives can help people notice solutions they had ignored.","zh":"新角度可以幫助人注意到自己曾忽略的解決方法。"},{"en":"Old friends give stability, while fresh perspectives can encourage growth.","zh":"舊朋友帶來穩定，而新角度可以鼓勵成長。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"who we are becoming","meaning":"我們正在成為怎樣的人","examples":[{"en":"Sometimes new friends understand who we are becoming.","zh":"有時新朋友明白我們正在成為怎樣的人。"},{"en":"Who we are becoming means the person we are slowly changing into.","zh":"我們正在成為怎樣的人，是指我們正慢慢變成的那種人。"},{"en":"A new friend in secondary school may understand your new dream better than people from childhood.","zh":"中學的新朋友可能比童年朋友更明白你的新夢想。"},{"en":"New friends can understand who we are becoming because they meet us during a new stage of growth.","zh":"新朋友可以明白我們正在成為怎樣的人，因為他們在新的成長階段認識我們。"},{"en":"Old friends know our past, but new friends may see our future direction more clearly.","zh":"舊朋友知道我們的過去，但新朋友可能更清楚看見我們未來的方向。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"who we used to be","meaning":"我們過去的樣子","examples":[{"en":"Old friends may know who we used to be.","zh":"舊朋友可能知道我們過去的樣子。"},{"en":"Who we used to be means the person we were in the past.","zh":"我們過去的樣子，是指我們從前是怎樣的人。"},{"en":"A childhood friend may remember who we used to be before we became confident.","zh":"童年朋友可能記得我們在變得自信前過去的樣子。"},{"en":"Knowing who we used to be helps old friends understand why certain memories still matter.","zh":"知道我們過去的樣子，幫助舊朋友明白為何某些回憶仍然重要。"},{"en":"We should not be trapped by who we used to be, but it is part of our story.","zh":"我們不應被過去的樣子困住，但那是我們故事的一部分。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"encourage someone to speak publicly","meaning":"鼓勵某人公開發言","examples":[{"en":"A new friend in a debate club may encourage a quiet student to speak publicly.","zh":"辯論學會的新朋友可能鼓勵安靜的學生公開發言。"},{"en":"To encourage someone to speak publicly means to support them in talking in front of others.","zh":"鼓勵某人公開發言意思是支持某人在其他人面前說話。"},{"en":"A teacher may encourage someone to speak publicly by letting them practise in a small group first.","zh":"老師可能先讓學生在小組練習，以鼓勵某人公開發言。"},{"en":"Encouragement can build confidence because public speaking often feels frightening at first.","zh":"鼓勵可以建立信心，因為公開發言一開始常令人害怕。"},{"en":"A friend who encourages you to speak publicly may help you discover a stronger voice.","zh":"鼓勵你公開發言的朋友，可能幫助你發現更有力量的聲音。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"assume that","meaning":"假設；以為","examples":[{"en":"An old friend may assume that silence means comfort.","zh":"舊朋友可能以為沉默代表自在。"},{"en":"To assume that means to believe something is true without checking carefully.","zh":"假設或以為某事，意思是沒有仔細確認就相信它是真的。"},{"en":"A parent may assume that a child is lazy when the real problem is tiredness.","zh":"父母可能以為孩子懶惰，但真正問題其實是疲倦。"},{"en":"Assuming too quickly can cause misunderstanding because people’s feelings are not always visible.","zh":"太快假設可能造成誤會，因為人的感受並不總是看得見。"},{"en":"Good friends ask questions instead of simply assuming that they already know the answer.","zh":"好朋友會提出問題，而不是直接以為自己已知道答案。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"silence means comfort","meaning":"沉默代表自在","examples":[{"en":"An old friend may wrongly assume that silence means comfort.","zh":"舊朋友可能錯誤地以為沉默代表自在。"},{"en":"“Silence means comfort” suggests that a quiet person feels relaxed and safe.","zh":"「沉默代表自在」暗示安靜的人感到放鬆和安全。"},{"en":"In a library, silence may mean comfort because students can read peacefully.","zh":"在圖書館，沉默可能代表自在，因為學生可以平靜閱讀。"},{"en":"In friendship, silence does not always mean comfort; it may also mean sadness or fear.","zh":"在友誼中，沉默不一定代表自在；它也可能代表傷心或恐懼。"},{"en":"Friends should check gently before deciding that silence means comfort.","zh":"朋友在判斷沉默代表自在前，應溫和地確認。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"not only…, but also…","meaning":"不但……而且……","examples":[{"en":"Parry says not only to make new friends, but also to keep the old.","zh":"Parry 說，不但要結交新朋友，而且要保持舊友誼。"},{"en":"“Not only…, but also…” connects two ideas and shows that both are important.","zh":"“Not only…, but also…” 連接兩個想法，並顯示兩者都重要。"},{"en":"Students should not only study hard, but also rest enough before exams.","zh":"學生考試前不但應努力溫習，而且應有足夠休息。"},{"en":"This structure helps writers add a second point that strengthens the first.","zh":"這個結構幫助作者加入第二點，以加強第一點。"},{"en":"In friendship, we should not only welcome new people, but also protect old bonds.","zh":"在友誼中，我們不但應歡迎新人，而且應保護舊連繫。"}],"source":"2021 Q8.pdf","sourcePage":8},{"front":"keep the old","meaning":"保持舊友誼","examples":[{"en":"The poem reminds us to make new friends and keep the old.","zh":"這首詩提醒我們要結交新朋友，也要保持舊友誼。"},{"en":"To keep the old means to continue valuing old friendships instead of replacing them completely.","zh":"保持舊友誼意思是繼續重視舊朋友，而不是完全取代他們。"},{"en":"A student can keep the old by sending messages to primary school friends after changing schools.","zh":"學生轉校後傳訊息給小學朋友，就是在保持舊友誼。"},{"en":"Keeping old friendships matters because shared history cannot be quickly rebuilt.","zh":"保持舊友誼很重要，因為共同歷史不能很快重建。"},{"en":"We can make new friends without forgetting to keep the old.","zh":"我們可以結交新朋友，同時不忘保持舊友誼。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"have value","meaning":"有價值","examples":[{"en":"Silver has value.","zh":"銀也有價值。"},{"en":"To have value means to be useful, meaningful, important, or worth keeping.","zh":"有價值意思是有用、有意義、重要或值得保留。"},{"en":"A simple thank-you note can have value because it makes someone feel appreciated.","zh":"一張簡單的感謝卡也可以有價值，因為它令人感到被欣賞。"},{"en":"New friendships have value when they bring kindness, learning, and support.","zh":"當新友誼帶來善意、學習和支持，它們便有價值。"},{"en":"Something does not need to be perfect or old to have value.","zh":"某事不需要完美或古老才有價值。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"given enough time","meaning":"假以時日","examples":[{"en":"Given enough time, a new friendship may become part of our treasure.","zh":"假以時日，一段新友誼可能成為我們寶藏的一部分。"},{"en":"Given enough time means if enough time passes for something to develop.","zh":"假以時日意思是如果有足夠時間讓某事發展。"},{"en":"Given enough time, a nervous student may become comfortable in a new class.","zh":"假以時日，一位緊張的學生可能會在新班別感到自在。"},{"en":"New friendships need time because trust usually grows through repeated experience.","zh":"新友誼需要時間，因為信任通常透過反覆經驗成長。"},{"en":"Given enough time, today’s silver friendship may become tomorrow’s gold.","zh":"假以時日，今天如銀的友誼可能成為明天如金的友誼。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"become part of the treasure of our lives","meaning":"成為人生寶藏的一部分","examples":[{"en":"A new friendship may become part of the treasure of our lives.","zh":"一段新友誼可能成為人生寶藏的一部分。"},{"en":"To become part of the treasure of our lives means to become one of the precious memories or relationships we deeply value.","zh":"成為人生寶藏的一部分意思是成為我們深深珍惜的寶貴回憶或關係之一。"},{"en":"A classmate who helps you through a hard year may become part of the treasure of your life.","zh":"一位陪你度過艱難一年級的同學，可能成為你人生寶藏的一部分。"},{"en":"Friendship becomes treasure when it gives support, memory, and meaning over time.","zh":"當友誼隨時間帶來支持、回憶和意義，它便成為寶藏。"},{"en":"Not every new friendship becomes treasure, but some slowly earn that place.","zh":"不是每段新友誼都會成為寶藏，但有些會慢慢贏得這個位置。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"more of a promise than proof","meaning":"更像承諾，而非證明","examples":[{"en":"New friendship is more of a promise than proof.","zh":"新友誼更像承諾，而非證明。"},{"en":"More of a promise than proof means something shows possibility, but it has not yet been fully tested.","zh":"更像承諾，而非證明意思是某事顯示可能性，但尚未被充分考驗。"},{"en":"A new study plan is more of a promise than proof until the student follows it for months.","zh":"新溫習計劃在學生持續執行數月前，更像承諾，而非證明。"},{"en":"New friendship may feel hopeful, but time has not yet shown whether it will last.","zh":"新友誼可能令人充滿希望，但時間尚未顯示它是否持久。"},{"en":"This phrase explains why new friendships are valuable but still uncertain.","zh":"這個短語解釋為何新友誼有價值，但仍有不確定性。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"be tested by disagreement","meaning":"受到分歧考驗","examples":[{"en":"Friendship must be tested by disagreement, boredom, or distance.","zh":"友誼必須受到分歧、沉悶或距離考驗。"},{"en":"To be tested by disagreement means to face conflict that shows whether a relationship can remain respectful.","zh":"受到分歧考驗意思是面對衝突，從而顯示一段關係能否保持尊重。"},{"en":"A friendship is tested by disagreement when two students support different ideas in a group project.","zh":"當兩位學生在小組項目中支持不同想法時，友誼便受到分歧考驗。"},{"en":"Disagreement tests friendship because people may become defensive or hurt.","zh":"分歧會考驗友誼，因為人們可能變得自我保護或受傷。"},{"en":"A strong friendship can be tested by disagreement and still continue honestly.","zh":"堅固的友誼可以受到分歧考驗，仍然誠實地延續。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"there is no telling whether","meaning":"無法判斷是否……","examples":[{"en":"There is no telling whether a new friendship is genuine commitment.","zh":"我們無法判斷一段新友誼是否是真正的承諾。"},{"en":"“There is no telling whether” means it is impossible to know clearly yet.","zh":"“There is no telling whether” 意思是暫時無法清楚知道。"},{"en":"There is no telling whether a new club will succeed until members work together for a term.","zh":"在成員一起合作一個學期前，無法判斷新學會是否會成功。"},{"en":"In new friendship, there is no telling whether kindness will continue during difficulty.","zh":"在新友誼中，我們無法判斷善意是否會在困難時持續。"},{"en":"This phrase shows uncertainty and the need for time.","zh":"這個短語顯示不確定性和時間的需要。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"genuine commitment","meaning":"真正的承諾","examples":[{"en":"There is no telling whether it is admiration, convenience, or genuine commitment.","zh":"我們無法判斷它是欣賞、方便，還是真正的承諾。"},{"en":"Genuine commitment means real willingness to stay, care, and make effort over time.","zh":"真正的承諾意思是真實願意隨時間留下、關心和付出努力。"},{"en":"A friend shows genuine commitment by checking on you even when you no longer sit together.","zh":"即使不再同坐，朋友仍關心你，就是顯示真正的承諾。"},{"en":"Genuine commitment matters because feelings alone may fade when life becomes difficult.","zh":"真正的承諾很重要，因為單靠感覺在生活困難時可能會消退。"},{"en":"Friendship needs genuine commitment, not only excitement at the beginning.","zh":"友誼需要真正的承諾，而不只是開始時的興奮。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"not automatically superior","meaning":"並非必然較優勝","examples":[{"en":"Old friendships are not automatically superior.","zh":"舊友誼並非必然較優勝。"},{"en":"Not automatically superior means not better in every case simply because of one feature.","zh":"並非必然較優勝意思是不會只因某個特點就在每種情況下更好。"},{"en":"An old method is not automatically superior if it no longer helps students learn.","zh":"如果舊方法不再幫助學生學習，它並非必然較優勝。"},{"en":"Old friendships may fail if they become careless, controlling, or disrespectful.","zh":"如果舊友誼變得粗心、控制或不尊重，它也可能失敗。"},{"en":"This phrase reminds us to judge friendship by quality, not age alone.","zh":"這個短語提醒我們按質素判斷友誼，而不是只按年期。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"remain warm after years of change","meaning":"經多年轉變後仍然溫暖","examples":[{"en":"Old friendships may remain warm after years of change.","zh":"舊友誼可能經多年轉變後仍然溫暖。"},{"en":"To remain warm after years of change means to stay kind, close, and caring even after life becomes different.","zh":"經多年轉變後仍然溫暖意思是即使生活變得不同，仍保持善意、親近和關心。"},{"en":"Primary school friends may remain warm after years of change if they still share honest messages.","zh":"如果小學朋友仍真誠傳訊息，他們可能經多年轉變後仍然溫暖。"},{"en":"This warmth is meaningful because time and distance often cool relationships.","zh":"這份溫暖很有意義，因為時間和距離常令關係冷卻。"},{"en":"A friendship that remains warm after years of change has shown unusual steadiness.","zh":"經多年轉變後仍然溫暖的友誼，顯示出不尋常的穩定。"}],"source":"2021 Q8.pdf","sourcePage":9},{"front":"earn confidence","meaning":"贏得信心","examples":[{"en":"Old friendships have earned a confidence that new friendships have yet to build.","zh":"舊友誼已經贏得一份新友誼尚未建立的信心。"},{"en":"To earn confidence means to win trust through repeated actions and proven reliability.","zh":"贏得信心意思是透過反覆行動和被證明的可靠來取得信任。"},{"en":"A student earns confidence from classmates by keeping promises and doing group work carefully.","zh":"學生透過守承諾和認真做小組工作，贏得同學的信心。"},{"en":"Old friends earn confidence because they have shown care through different stages of life.","zh":"舊朋友贏得信心，因為他們在不同人生階段都顯示關心。"},{"en":"Confidence in friendship is earned slowly, not demanded quickly.","zh":"友誼中的信心是慢慢贏得的，不是快速要求得來的。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"have yet to build","meaning":"尚未建立","examples":[{"en":"New friendships have yet to build the same level of confidence.","zh":"新友誼尚未建立同等程度的信心。"},{"en":"Have yet to build means have not built something, but may build it later.","zh":"尚未建立意思是還未建立某事，但日後可能建立。"},{"en":"A new team has yet to build trust because members have not worked together under pressure.","zh":"新團隊尚未建立信任，因為成員還未在壓力下一起工作。"},{"en":"New friendships have yet to build deep confidence because they need more shared experience.","zh":"新友誼尚未建立深厚信心，因為它們需要更多共同經驗。"},{"en":"“Have yet to build” leaves room for hope, not rejection.","zh":"「尚未建立」留下希望空間，而不是否定。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"all things considered","meaning":"總括而言","examples":[{"en":"All things considered, older friendships are generally better.","zh":"總括而言，舊友誼一般而言比較好。"},{"en":"All things considered means after thinking about all important points together.","zh":"總括而言意思是在一起考慮所有重要觀點之後。"},{"en":"All things considered, a shorter study plan may be better if students can follow it consistently.","zh":"總括而言，如果學生能持續執行，較短的溫習計劃可能更好。"},{"en":"Writers use this phrase to introduce a balanced final judgement.","zh":"作者使用這個短語來引出平衡的最終判斷。"},{"en":"All things considered, friendship should be judged by depth, steadiness, and care.","zh":"總括而言，友誼應按深度、穩定和關心來判斷。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"generally better","meaning":"一般而言更好","examples":[{"en":"Older friendships are generally better when they are deeper and steadier.","zh":"當舊友誼更深厚和更穩定時，它們一般而言更好。"},{"en":"Generally better means better in most cases, though not always in every case.","zh":"一般而言更好意思是在大多數情況下較好，但不是每一種情況都一定如此。"},{"en":"A quiet classroom is generally better for reading, but group discussion may need noise.","zh":"安靜課室一般而言更適合閱讀，但小組討論可能需要聲音。"},{"en":"Older friendships may be generally better because they have been tested by time.","zh":"舊友誼可能一般而言更好，因為它們受過時間考驗。"},{"en":"Saying “generally better” leaves space for exceptions.","zh":"說「一般而言更好」為例外留下空間。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"provided that","meaning":"前提是","examples":[{"en":"Older friendships are better, provided that “better” means deeper and steadier.","zh":"舊友誼比較好，前提是「好」指更深厚和更穩定。"},{"en":"Provided that means only if a certain condition is true.","zh":"前提是意思是只有在某個條件成立時才可以。"},{"en":"Students can join the trip, provided that their parents sign the form.","zh":"學生可以參加旅行，前提是父母簽署表格。"},{"en":"This phrase is useful because it makes an argument more careful and specific.","zh":"這個短語很有用，因為它令論點更謹慎和具體。"},{"en":"Old friendships are valuable provided that they remain respectful and caring.","zh":"舊友誼有價值，前提是它們仍保持尊重和關心。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"deeper, steadier and more fully tested","meaning":"更深厚、更穩定、更經考驗","examples":[{"en":"Older friendships are deeper, steadier, and more fully tested.","zh":"舊友誼更深厚、更穩定、更經考驗。"},{"en":"Deeper, steadier and more fully tested means more meaningful, more stable, and proven through different situations.","zh":"更深厚、更穩定、更經考驗意思是更有意義、更穩固，並在不同情況中被證明。"},{"en":"A friendship becomes deeper, steadier and more fully tested after friends face exams, arguments, and distance together.","zh":"朋友一起面對考試、爭吵和距離後，友誼會變得更深厚、更穩定、更經考驗。"},{"en":"Such friendship is trusted because it has survived more than easy moments.","zh":"這種友誼值得信任，因為它經歷的不只是輕鬆時刻。"},{"en":"New friendships may become deeper, steadier and more fully tested with enough time.","zh":"假以時日，新友誼也可能變得更深厚、更穩定、更經考驗。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"worship the past","meaning":"盲目崇拜過去","examples":[{"en":"Students should not worship the past.","zh":"學生不應盲目崇拜過去。"},{"en":"To worship the past means to admire old things so much that we refuse to judge them fairly.","zh":"盲目崇拜過去意思是過度欣賞舊事物，以致拒絕公平判斷。"},{"en":"A school should not worship the past by keeping outdated rules that hurt students.","zh":"學校不應透過保留傷害學生的過時規則來盲目崇拜過去。"},{"en":"Worshipping the past can stop people from accepting useful change.","zh":"盲目崇拜過去可能阻止人接受有用改變。"},{"en":"Respecting old friendships is wise, but worshipping the past can become unhealthy.","zh":"尊重舊友誼是明智的，但盲目崇拜過去可能變得不健康。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"chase every new connection","meaning":"追逐每一段新關係","examples":[{"en":"Students should not chase every new connection.","zh":"學生不應追逐每一段新關係。"},{"en":"To chase every new connection means to keep seeking new relationships without caring for existing ones.","zh":"追逐每一段新關係意思是不斷尋找新關係，卻不照顧已有關係。"},{"en":"A student may chase every new connection online but forget to support close classmates.","zh":"學生可能在網上追逐每一段新關係，卻忘記支持親近同學。"},{"en":"Chasing every new connection can make friendships shallow because attention becomes scattered.","zh":"追逐每一段新關係可能令友誼變得膚淺，因為注意力變得分散。"},{"en":"It is good to meet new people, but not to chase every new connection carelessly.","zh":"認識新人是好的，但不應粗心地追逐每一段新關係。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"make room for","meaning":"為……留位置","examples":[{"en":"Students should make room for new classmates.","zh":"學生應為新同學留位置。"},{"en":"To make room for someone means to create space, time, or welcome for them.","zh":"為某人留位置意思是為對方創造空間、時間或歡迎。"},{"en":"A lunch group can make room for a new classmate by inviting them to sit together.","zh":"午餐小組邀請新同學一起坐，就是為他留位置。"},{"en":"Making room for others reduces loneliness and helps a community become kinder.","zh":"為別人留位置可以減少孤獨，並幫助社群變得更友善。"},{"en":"We can make room for new friends without pushing old friends away.","zh":"我們可以為新朋友留位置，而不把舊朋友推開。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"send the message","meaning":"傳訊息","examples":[{"en":"Students should send the message before distance grows.","zh":"學生應在距離擴大前傳訊息。"},{"en":"To send the message means to contact someone through a written phone or online message.","zh":"傳訊息意思是透過電話或網上文字訊息聯絡某人。"},{"en":"A student may send the message, “How are you?” to a friend who has become quiet.","zh":"學生可能向變得安靜的朋友傳訊息：「你最近怎樣？」"},{"en":"Sending the message early can prevent small distance from becoming long silence.","zh":"早點傳訊息可以防止小距離變成長時間沉默。"},{"en":"Sometimes a friendship is repaired because one person chooses to send the message first.","zh":"有時友誼能被修補，是因為其中一人選擇先傳訊息。"}],"source":"2021 Q8.pdf","sourcePage":10},{"front":"make the call","meaning":"打電話","examples":[{"en":"Students should make the call and repair small misunderstandings.","zh":"學生應打電話，並修補小誤會。"},{"en":"To make the call means to phone someone, often to speak more directly than texting.","zh":"打電話意思是致電某人，通常比傳訊息更直接地交談。"},{"en":"A student may make the call after an argument because messages can sound cold.","zh":"爭吵後，學生可能會打電話，因為文字訊息聽起來可能冷淡。"},{"en":"Making the call can repair misunderstanding because voice shows tone and sincerity.","zh":"打電話可以修補誤會，因為聲音能顯示語氣和真誠。"},{"en":"It may feel awkward to make the call, but it can save an important friendship.","zh":"打電話可能令人尷尬，但它可以挽救重要友誼。"}],"source":"2021 Q8.pdf","sourcePage":11},{"front":"repair small misunderstandings","meaning":"修補小誤會","examples":[{"en":"Students should repair small misunderstandings before they harden into distance.","zh":"學生應在小誤會變成疏離前修補它們。"},{"en":"To repair small misunderstandings means to explain, apologise, or listen before minor problems grow.","zh":"修補小誤會意思是在小問題擴大前解釋、道歉或聆聽。"},{"en":"A friend can repair small misunderstandings by saying, “I did not mean to ignore you.”","zh":"朋友可以說「我不是故意忽視你」來修補小誤會。"},{"en":"Repairing small misunderstandings early prevents resentment from becoming stronger.","zh":"早點修補小誤會可以防止怨氣變得更強。"},{"en":"Many friendships end not from one big fight, but from small misunderstandings left unrepaired.","zh":"許多友誼結束不是因一次大爭吵，而是因小誤會一直沒有被修補。"}],"source":"2021 Q8.pdf","sourcePage":11},{"front":"harden into distance","meaning":"變成疏離","examples":[{"en":"Small misunderstandings may harden into distance.","zh":"小誤會可能會變成疏離。"},{"en":"To harden into distance means to slowly become coldness, separation, or emotional gap.","zh":"變成疏離意思是慢慢成為冷淡、分隔或情感距離。"},{"en":"A missed birthday message may harden into distance if neither friend explains their feelings.","zh":"如果雙方都不解釋感受，一次忘記生日訊息可能會變成疏離。"},{"en":"Problems harden into distance when silence lasts too long.","zh":"當沉默持續太久，問題就會變成疏離。"},{"en":"Quick honesty can stop small hurt from hardening into distance.","zh":"及時誠實可以阻止小傷害變成疏離。"}],"source":"2021 Q8.pdf","sourcePage":11},{"front":"add brightness to our lives","meaning":"為生活增添亮光","examples":[{"en":"New friends may add brightness to our lives.","zh":"新朋友可能為生活增添亮光。"},{"en":"To add brightness to our lives means to bring joy, energy, hope, or colour into daily experience.","zh":"為生活增添亮光意思是為日常經驗帶來快樂、活力、希望或色彩。"},{"en":"A cheerful new classmate may add brightness to our lives by making school feel less heavy.","zh":"一位開朗的新同學可能令上學不那麼沉重，為生活增添亮光。"},{"en":"New friendships add brightness because they bring new stories, habits, and encouragement.","zh":"新友誼會增添亮光，因為它們帶來新故事、新習慣和鼓勵。"},{"en":"Brightness is valuable, but it becomes warmer when friendship also has trust.","zh":"亮光很有價值，但當友誼也有信任時，它會變得更溫暖。"}],"source":"2021 Q8.pdf","sourcePage":11},{"front":"give that brightness a home","meaning":"讓那份亮光有歸屬","examples":[{"en":"Old friends give that brightness a home.","zh":"舊朋友讓那份亮光有歸屬。"},{"en":"To give that brightness a home means to turn happiness into something stable, familiar, and lasting.","zh":"讓那份亮光有歸屬意思是把快樂變成穩定、熟悉和持久的東西。"},{"en":"A new joke gives brightness, but an old friend gives that brightness a home by remembering it for years.","zh":"新笑話帶來亮光，而舊朋友多年後仍記得它，就是讓那份亮光有歸屬。"},{"en":"Old friendships give brightness a home because they hold joy inside shared history.","zh":"舊友誼讓亮光有歸屬，因為它們把快樂保存在共同歷史中。"},{"en":"This phrase suggests that excitement becomes deeper when it belongs somewhere safe.","zh":"這個短語暗示，當興奮感屬於安全的地方時，它會變得更深。"}],"source":"2021 Q8.pdf","sourcePage":11},{"front":"has been through fire","meaning":"經歷過烈火考驗","examples":[{"en":"Gold has been through fire.","zh":"金經歷過烈火考驗。"},{"en":"If something has been through fire, it has survived serious difficulty and become stronger or more valuable.","zh":"如果某事經歷過烈火考驗，意思是它經受嚴重困難後仍存在，並變得更強或更有價值。"},{"en":"A friendship has been through fire when it survives conflict, distance, and painful honesty.","zh":"一段友誼經歷衝突、距離和痛苦的誠實後仍能存續，就是經歷過烈火考驗。"},{"en":"Fire suggests testing because heat can destroy weak things but purify strong metal.","zh":"烈火象徵考驗，因為高溫可以毀掉脆弱之物，也可以煉淨堅固金屬。"},{"en":"The phrase explains why old friendship can feel precious after years of hardship.","zh":"這個短語解釋為何舊友誼在多年困難後會顯得珍貴。"}],"source":"2021 Q8.pdf","sourcePage":11}],"dse/writing/part-b/2021/Q9":[{"front":"a family drama for every generation","meaning":"適合各代人觀看的家庭劇","examples":[{"en":"Beneath the Same Roof is a family drama for every generation.","zh":"《同一屋簷下》是一部適合各代人觀看的家庭劇。"},{"en":"A family drama for every generation is a story that grandparents, parents, and young people can all understand.","zh":"適合各代人觀看的家庭劇，是指祖父母、父母和年輕人都能理解的故事。"},{"en":"A television series about daily arguments, love, and forgiveness can become a family drama for every generation.","zh":"一部關於日常爭執、愛與原諒的電視劇，可以成為適合各代人觀看的家庭劇。"},{"en":"A family drama for every generation works well when it shows problems that different age groups face at home.","zh":"當一部適合各代人觀看的家庭劇呈現不同年齡層在家中面對的問題時，效果會很好。"},{"en":"This kind of drama does not belong to only one age group because family life connects everyone.","zh":"這類劇集不只屬於某一個年齡層，因為家庭生活把所有人連繫起來。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"Production Manager","meaning":"製作經理","examples":[{"en":"The proposal is addressed to the Production Manager at TV Station X.","zh":"這份建議書是寫給 X 電視台的製作經理。"},{"en":"A Production Manager is the person who helps organise the practical work needed to make a show.","zh":"製作經理是協助安排製作節目所需實際工作的人。"},{"en":"The Production Manager may check the budget, filming schedule, locations, and staff before a drama begins.","zh":"製作經理可能會在劇集開拍前檢查預算、拍攝時間表、地點和人手。"},{"en":"If the Production Manager plans poorly, the crew may waste time and money during filming.","zh":"如果製作經理計劃不周，拍攝期間工作團隊可能會浪費時間和金錢。"},{"en":"Writers often send proposals to a Production Manager because that person understands how an idea can become a real programme.","zh":"編劇常把建議書交給製作經理，因為此人明白一個構思如何變成真正的節目。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"TV station","meaning":"電視台","examples":[{"en":"The proposal is addressed to TV Station X.","zh":"這份建議書是寫給 X 電視台。"},{"en":"A TV station is a company or organisation that broadcasts television programmes to viewers.","zh":"電視台是向觀眾播放電視節目的公司或機構。"},{"en":"A TV station may produce news, dramas, documentaries, and entertainment shows.","zh":"電視台可以製作新聞、劇集、紀錄片和娛樂節目。"},{"en":"If a TV station wants younger viewers, it may develop programmes about school, work, and family life.","zh":"如果電視台想吸引年輕觀眾，它可能會開發關於學校、工作和家庭生活的節目。"},{"en":"A strong proposal helps a TV station decide whether a new programme is worth producing.","zh":"一份有力的建議書可以幫助電視台決定新節目是否值得製作。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"a proposal for","meaning":"關於……的建議書","examples":[{"en":"This is a proposal for a new TV drama series.","zh":"這是一份關於新電視劇集的建議書。"},{"en":"A proposal for something is a written plan that explains an idea and asks others to consider it.","zh":"關於某事的建議書，是一份解釋構思並請別人考慮的書面計劃。"},{"en":"A student may write a proposal for a school recycling campaign.","zh":"學生可以寫一份關於學校回收活動的建議書。"},{"en":"A clear proposal for a project can help teachers understand its purpose, cost, and benefits.","zh":"一份清晰的項目建議書，可以幫助老師了解其目的、成本和好處。"},{"en":"Without a proposal for the activity, the organisers may not know what they are being asked to approve.","zh":"如果沒有關於該活動的建議書，籌辦者可能不知道自己被要求批准甚麼。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"a new TV drama series","meaning":"新電視劇集","examples":[{"en":"The writer proposes a new TV drama series called Beneath the Same Roof.","zh":"作者提議一部名為《同一屋簷下》的新電視劇集。"},{"en":"A new TV drama series is a fresh television story told over several episodes.","zh":"新電視劇集是以多集形式講述的全新電視故事。"},{"en":"A new TV drama series about nurses could show their daily pressure, friendships, and difficult choices.","zh":"一部關於護士的新電視劇集，可以呈現他們的日常壓力、友誼和艱難選擇。"},{"en":"A station may order a new TV drama series when it wants to attract viewers over many weeks.","zh":"當電視台想在多星期內吸引觀眾時，可能會訂製一部新電視劇集。"},{"en":"A successful new TV drama series needs interesting characters, clear conflicts, and reasons for viewers to return.","zh":"一部成功的新電視劇集需要有趣角色、清晰衝突，以及讓觀眾回來收看的理由。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"I am writing to propose","meaning":"我寫信是為了提議","examples":[{"en":"I am writing to propose an original television drama series.","zh":"我寫信是為了提議一部原創電視劇集。"},{"en":"I am writing to propose is a formal way to introduce an idea that you want someone to consider.","zh":"「我寫信是為了提議」是一種正式說法，用來介紹希望別人考慮的構思。"},{"en":"I am writing to propose a school charity day that raises money for elderly neighbours.","zh":"我寫信是為了提議舉辦一個學校慈善日，為長者鄰居籌款。"},{"en":"This phrase is useful in letters because it states the purpose clearly at the beginning.","zh":"這個短語在書信中很有用，因為它一開始就清楚說明目的。"},{"en":"When you use I am writing to propose, the reader expects a plan, reasons, and possible benefits.","zh":"當你使用「我寫信是為了提議」時，讀者會預期看到計劃、理由和可能好處。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"an original television drama series","meaning":"原創電視劇集","examples":[{"en":"Beneath the Same Roof is an original television drama series.","zh":"《同一屋簷下》是一部原創電視劇集。"},{"en":"An original television drama series is a TV story created with new characters and plot, not simply copied from another work.","zh":"原創電視劇集是用新角色和新情節創作的電視故事，而不是簡單抄襲另一部作品。"},{"en":"A writer may develop an original television drama series based on ordinary life in a busy neighbourhood.","zh":"編劇可以根據繁忙社區中的普通生活，創作一部原創電視劇集。"},{"en":"An original television drama series can stand out if its setting and characters feel fresh.","zh":"如果背景和角色令人感到新鮮，一部原創電視劇集就能突出。"},{"en":"Viewers often remember an original television drama series when it shows familiar emotions in a new way.","zh":"當原創電視劇集以新方式呈現熟悉情感時，觀眾往往會記得它。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"entitled","meaning":"名為","examples":[{"en":"The drama series is entitled Beneath the Same Roof.","zh":"這部劇集名為《同一屋簷下》。"},{"en":"Entitled means given a title or name.","zh":"entitled 的意思是被給予某個標題或名稱。"},{"en":"The school magazine published a story entitled The Last Bus Home.","zh":"校刊刊登了一篇名為《最後一班回家的巴士》的故事。"},{"en":"A report entitled Clean Streets, Better Lives clearly tells readers what it is about.","zh":"一份名為《清潔街道，更好生活》的報告，清楚告訴讀者其內容。"},{"en":"In formal writing, entitled is often used before the name of a book, film, article, or programme.","zh":"在正式寫作中，entitled 常用於書籍、電影、文章或節目的名稱前。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"a twelve-episode family story","meaning":"十二集家庭故事","examples":[{"en":"The series is a twelve-episode family story set in Hong Kong.","zh":"這部劇集是一個以香港為背景的十二集家庭故事。"},{"en":"A twelve-episode family story is a family drama told in twelve separate parts.","zh":"十二集家庭故事是分成十二個部分講述的家庭劇。"},{"en":"A twelve-episode family story gives enough time to show how relationships change slowly.","zh":"十二集家庭故事有足夠時間展示關係如何慢慢改變。"},{"en":"If each episode reveals one secret, a twelve-episode family story can keep viewers interested.","zh":"如果每一集揭示一個秘密，十二集家庭故事可以令觀眾保持興趣。"},{"en":"This format is useful because it allows family problems to develop instead of being solved too quickly.","zh":"這種形式很有用，因為它讓家庭問題逐步發展，而不是太快被解決。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"set in present-day Hong Kong","meaning":"以當代香港為背景","examples":[{"en":"The story is set in present-day Hong Kong.","zh":"這個故事以當代香港為背景。"},{"en":"Set in present-day Hong Kong means the story happens in modern Hong Kong, not in the past or future.","zh":"以當代香港為背景，意思是故事發生在現代香港，而不是過去或未來。"},{"en":"A drama set in present-day Hong Kong may show crowded flats, busy streets, and changing neighbourhoods.","zh":"一部以當代香港為背景的劇集，可能展示擠迫單位、繁忙街道和轉變中的社區。"},{"en":"This setting helps viewers connect the story with problems they see around them now.","zh":"這個背景幫助觀眾把故事與眼前的問題連繫起來。"},{"en":"A story set in present-day Hong Kong can feel immediate because the places and pressures are familiar.","zh":"以當代香港為背景的故事會令人感到貼近，因為地方和壓力都很熟悉。"}],"source":"2021Q9.pdf","sourcePage":1},{"front":"in recent years","meaning":"近年來","examples":[{"en":"In recent years, many viewers have been drawn to meaningful family dramas.","zh":"近年來，許多觀眾被有意義的家庭劇吸引。"},{"en":"In recent years means during the last few years, not a long time ago.","zh":"in recent years 的意思是在過去幾年，而不是很久以前。"},{"en":"In recent years, more students have used online videos to revise after school.","zh":"近年來，更多學生使用網上影片在放學後溫習。"},{"en":"In recent years, rent increases have made life harder for many young workers.","zh":"近年來，租金上升令許多年輕打工仔生活更困難。"},{"en":"This phrase is useful when describing a change or trend that has happened quite recently.","zh":"這個短語在描述最近發生的改變或趨勢時很有用。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"be drawn to","meaning":"被……吸引","examples":[{"en":"Many viewers have been drawn to programmes that reflect real family life.","zh":"許多觀眾被反映真實家庭生活的節目吸引。"},{"en":"To be drawn to something means to feel attracted to it or interested in it.","zh":"be drawn to something 的意思是被某事物吸引或對其感興趣。"},{"en":"Students may be drawn to a teacher who explains difficult ideas with simple examples.","zh":"學生可能會被一位用簡單例子解釋難題的老師吸引。"},{"en":"People are often drawn to stories that reflect their own fears and hopes.","zh":"人們常被反映自己恐懼與希望的故事吸引。"},{"en":"A person may be drawn to a quiet park because it offers peace after a busy day.","zh":"一個人可能被安靜的公園吸引，因為它在忙碌一天後帶來平靜。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"do not simply entertain","meaning":"不只是娛樂","examples":[{"en":"These programmes do not simply entertain viewers.","zh":"這些節目不只是娛樂觀眾。"},{"en":"Programmes that do not simply entertain also teach, comfort, challenge, or make people think.","zh":"不只是娛樂的節目，也會教導、安慰、挑戰或令人思考。"},{"en":"A school play may not simply entertain if it also helps students understand bullying.","zh":"如果一齣校園劇也幫助學生理解欺凌，它就不只是娛樂。"},{"en":"Documentaries do not simply entertain because they often explain real problems.","zh":"紀錄片不只是娛樂，因為它們常常解釋真實問題。"},{"en":"A good family drama does not simply entertain when it helps viewers understand their own relationships.","zh":"當一部好的家庭劇幫助觀眾理解自己的關係時，它就不只是娛樂。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"recognise their own homes","meaning":"認出自己的家庭生活","examples":[{"en":"Viewers can recognise their own homes, worries and hopes on screen.","zh":"觀眾可以在螢幕上認出自己的家庭生活、憂慮和希望。"},{"en":"To recognise their own homes means viewers see family situations that feel similar to their real lives.","zh":"認出自己的家庭生活，意思是觀眾看到與自己現實生活相似的家庭情況。"},{"en":"Parents may recognise their own homes in a drama about money worries and children’s exams.","zh":"父母可能在一部關於金錢壓力和子女考試的劇集中，認出自己的家庭生活。"},{"en":"When viewers recognise their own homes on screen, they may feel understood rather than judged.","zh":"當觀眾在螢幕上認出自己的家庭生活時，他們可能覺得被理解，而不是被批判。"},{"en":"A realistic setting helps audiences recognise their own homes in the small details of daily life.","zh":"寫實背景透過日常生活細節，幫助觀眾認出自己的家庭生活。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"worries and hopes","meaning":"憂慮與希望","examples":[{"en":"The drama reflects viewers’ worries and hopes.","zh":"這部劇集反映觀眾的憂慮與希望。"},{"en":"Worries and hopes are the fears people carry and the better future they wish for.","zh":"憂慮與希望，是指人們心中的恐懼，以及他們期望的更好未來。"},{"en":"Students’ worries and hopes may include exams, friendships, and dreams about future jobs.","zh":"學生的憂慮與希望可能包括考試、友誼和未來工作的夢想。"},{"en":"A good story shows worries and hopes together because people are rarely only sad or only happy.","zh":"好故事會同時展示憂慮與希望，因為人很少只有悲傷或只有快樂。"},{"en":"When a drama reflects real worries and hopes, viewers may feel that the story speaks to them.","zh":"當劇集反映真實的憂慮與希望時，觀眾可能覺得故事在打動自己。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"on screen","meaning":"在螢幕上","examples":[{"en":"Many viewers want to see their own lives on screen.","zh":"許多觀眾想在螢幕上看到自己的生活。"},{"en":"On screen means shown in a film, television programme, or video.","zh":"on screen 的意思是在電影、電視節目或影片中呈現。"},{"en":"A child may feel excited when their school appears on screen in a news report.","zh":"當孩子的學校出現在新聞報道的螢幕上時，孩子可能會很興奮。"},{"en":"Problems can feel more real when people see ordinary families facing them on screen.","zh":"當人們在螢幕上看到普通家庭面對問題時，問題會顯得更真實。"},{"en":"Not every part of life on screen is realistic, so viewers should think carefully about what they watch.","zh":"螢幕上的生活不一定全都寫實，所以觀眾應該仔細思考自己看的內容。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"with this in mind","meaning":"考慮到這一點","examples":[{"en":"With this in mind, the writer developed a drama about three generations.","zh":"考慮到這一點，作者創作了一部關於三代人的劇集。"},{"en":"With this in mind means because of the idea just mentioned, someone makes a decision or plan.","zh":"with this in mind 的意思是因為剛才提到的想法，所以某人作出決定或計劃。"},{"en":"The classroom is noisy at lunchtime; with this in mind, the teacher moves the reading activity to the library.","zh":"課室在午膳時間很嘈吵；考慮到這一點，老師把閱讀活動移到圖書館。"},{"en":"With this in mind is useful when you connect a problem to the solution that follows.","zh":"當你把問題與接下來的解決方法連繫起來時，with this in mind 很有用。"},{"en":"The phrase helps readers see that the next action is not random but based on earlier thinking.","zh":"這個短語幫助讀者看出下一個行動不是隨意的，而是基於之前的思考。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"three generations of","meaning":"三代……","examples":[{"en":"The drama is about three generations of the Lau family.","zh":"這部劇集講述劉家三代人的故事。"},{"en":"Three generations of a family usually means grandparents, parents, and children.","zh":"一個家庭的三代人通常指祖父母、父母和子女。"},{"en":"Three generations of one family may live together and disagree about money, study, and traditions.","zh":"一個家庭的三代人可能同住，並因金錢、學業和傳統而意見不同。"},{"en":"Showing three generations of characters helps a story compare old values with new ideas.","zh":"展示三代角色有助故事比較舊價值與新想法。"},{"en":"In many homes, three generations of relatives share love but also face daily misunderstandings.","zh":"在許多家庭中，三代親人共享愛，但也面對日常誤會。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"live above","meaning":"住在……樓上","examples":[{"en":"The Lau family live above a fading cha chaan teng.","zh":"劉家住在一間日漸式微的茶餐廳樓上。"},{"en":"To live above a place means to have a home on a higher floor of the same building.","zh":"live above a place 的意思是住在同一座建築物較高樓層的家中。"},{"en":"Some shop owners live above their shops so they can open early in the morning.","zh":"有些店主住在自己的店舖樓上，所以早上可以很早開門。"},{"en":"A family that lives above a restaurant may hear kitchen noise late at night.","zh":"住在餐廳樓上的家庭，晚上可能會聽到廚房聲音。"},{"en":"This phrase helps describe buildings where work and home are closely connected.","zh":"這個短語有助描述工作與家庭緊密相連的建築物。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"a fading cha chaan teng","meaning":"日漸式微的茶餐廳","examples":[{"en":"The family live above a fading cha chaan teng in Sham Shui Po.","zh":"這家人住在深水埗一間日漸式微的茶餐廳樓上。"},{"en":"A fading cha chaan teng is a Hong Kong-style café that is losing customers, energy, or importance.","zh":"日漸式微的茶餐廳，是指正在失去顧客、活力或重要性的港式茶餐廳。"},{"en":"A fading cha chaan teng may still have loyal elderly customers but fewer young people visit it.","zh":"日漸式微的茶餐廳可能仍有忠實的年長顧客，但較少年輕人光顧。"},{"en":"Rising rent and changing tastes can turn a once-busy café into a fading cha chaan teng.","zh":"租金上升和口味改變，可以令一間曾經熱鬧的茶餐廳變得日漸式微。"},{"en":"This setting can feel emotional because it shows both memory and decline.","zh":"這個背景會令人感到有情感，因為它同時展示回憶和衰落。"}],"source":"2021Q9.pdf","sourcePage":2},{"front":"family quarrels","meaning":"家庭爭執","examples":[{"en":"The series is not just about family quarrels.","zh":"這部劇集不只是關於家庭爭執。"},{"en":"Family quarrels are arguments between relatives, often about money, duties, choices, or old pain.","zh":"家庭爭執是親人之間的爭吵，通常與金錢、責任、選擇或舊傷痛有關。"},{"en":"Family quarrels may begin when siblings disagree about caring for an elderly parent.","zh":"當兄弟姊妹不同意如何照顧年老父母時，家庭爭執可能開始。"},{"en":"If family quarrels are never discussed honestly, small anger can grow into long silence.","zh":"如果家庭爭執從不被坦誠討論，小小怒氣可能變成長久沉默。"},{"en":"A drama can use family quarrels to show love, pride, fear, and the need for forgiveness.","zh":"劇集可以利用家庭爭執來展示愛、驕傲、恐懼和原諒的需要。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"not just about","meaning":"不只是關於……","examples":[{"en":"The series is not just about family quarrels.","zh":"這部劇集不只是關於家庭爭執。"},{"en":"Not just about means something includes more meaning than the first obvious topic.","zh":"not just about 的意思是某事包含比表面主題更多的意義。"},{"en":"A school sports day is not just about winning; it is also about teamwork and courage.","zh":"學校運動會不只是關於勝利，也關於團隊合作和勇氣。"},{"en":"A film about food may be not just about cooking but also about memory and family.","zh":"一部關於食物的電影，可能不只是關於烹飪，也關於記憶和家庭。"},{"en":"This phrase helps writers show that a subject has deeper layers.","zh":"這個短語幫助作者展示一個主題有更深層次。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"memory and sacrifice","meaning":"回憶與犧牲","examples":[{"en":"The drama explores memory and sacrifice within one family.","zh":"這部劇集探討一個家庭中的回憶與犧牲。"},{"en":"Memory and sacrifice mean remembered experiences and the things people give up for others.","zh":"回憶與犧牲，意思是被記住的經歷，以及人們為別人放棄的東西。"},{"en":"A grandmother’s old photo album may show memory and sacrifice in a family’s past.","zh":"祖母的舊相簿可能展示一個家庭過去的回憶與犧牲。"},{"en":"Parents’ sacrifice can shape children’s lives, even when the children do not understand it at first.","zh":"父母的犧牲可以塑造子女的人生，即使子女起初並不明白。"},{"en":"Stories about memory and sacrifice often feel moving because they show love through actions, not only words.","zh":"關於回憶與犧牲的故事常令人感動，因為它們透過行動而不只是言語展示愛。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"quiet courage","meaning":"默默的勇氣","examples":[{"en":"The series shows the quiet courage needed to love people across generations.","zh":"這部劇集展示跨世代去愛人所需要的默默的勇氣。"},{"en":"Quiet courage is the strength to face difficult feelings without showing off.","zh":"默默的勇氣，是指面對困難感受時不炫耀的力量。"},{"en":"A child shows quiet courage when they apologise after hurting a friend.","zh":"孩子傷害朋友後願意道歉，就是展現默默的勇氣。"},{"en":"Caring for a sick parent every day can require quiet courage because the work is tiring and unseen.","zh":"每天照顧生病父母可能需要默默的勇氣，因為這份工作很累又不容易被看見。"},{"en":"Quiet courage is often found in small acts, such as listening, staying, and trying again.","zh":"默默的勇氣常出現在小行動中，例如聆聽、留下和再次嘗試。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"across generations","meaning":"跨世代","examples":[{"en":"The drama explores love across generations.","zh":"這部劇集探討跨世代的愛。"},{"en":"Across generations means involving people from different age groups in the same family or society.","zh":"across generations 的意思是涉及同一家庭或社會中不同年齡層的人。"},{"en":"A song can be loved across generations if both grandparents and teenagers enjoy it.","zh":"如果祖父母和青少年都喜歡一首歌，它就可以跨世代受到喜愛。"},{"en":"Misunderstandings across generations may happen when young people and elders value different things.","zh":"當年輕人和長者重視不同事情時，跨世代誤會可能發生。"},{"en":"Stories across generations help audiences see how the past still affects the present.","zh":"跨世代故事幫助觀眾看見過去如何仍然影響現在。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"deliberately ordinary","meaning":"刻意塑造成平凡","examples":[{"en":"The main characters are deliberately ordinary.","zh":"主要角色被刻意塑造成平凡。"},{"en":"Deliberately ordinary means intentionally made simple, everyday, and not glamorous.","zh":"deliberately ordinary 的意思是有意地塑造成簡單、日常而不華麗。"},{"en":"A writer may create deliberately ordinary characters so viewers can see themselves in them.","zh":"作者可能創作刻意平凡的角色，讓觀眾在他們身上看到自己。"},{"en":"Deliberately ordinary settings, such as kitchens and bus stops, can make a drama feel real.","zh":"廚房和巴士站等刻意平凡的背景，可以令劇集感覺真實。"},{"en":"This choice reminds viewers that powerful stories can come from normal lives.","zh":"這個選擇提醒觀眾，有力量的故事可以來自普通生活。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"ordinary people","meaning":"平凡人","examples":[{"en":"Ordinary people often carry the most moving stories.","zh":"平凡人往往承載最動人的故事。"},{"en":"Ordinary people are normal people who are not famous, rich, or unusually powerful.","zh":"平凡人是指不出名、不富有或沒有特別權力的普通人。"},{"en":"A bus driver, cleaner, nurse, or student can be an ordinary person with a meaningful story.","zh":"巴士司機、清潔工、護士或學生，都可以是有意義故事的平凡人。"},{"en":"Stories about ordinary people can feel close because their problems resemble our own.","zh":"關於平凡人的故事會令人感到貼近，因為他們的問題像我們自己的問題。"},{"en":"When writers respect ordinary people, small daily choices can become dramatic and important.","zh":"當作者尊重平凡人時，小小的日常選擇也可以變得戲劇化和重要。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"moving stories","meaning":"動人的故事","examples":[{"en":"Ordinary people often carry the most moving stories.","zh":"平凡人往往承載最動人的故事。"},{"en":"Moving stories are stories that touch people’s feelings deeply.","zh":"動人的故事是深深觸動人們情感的故事。"},{"en":"A moving story may show a father working quietly for years to support his child.","zh":"一個動人的故事可能展示父親多年默默工作來支持孩子。"},{"en":"Moving stories often work because they show pain, kindness, or change in a believable way.","zh":"動人的故事常有效，因為它們以可信方式展示痛苦、善意或改變。"},{"en":"A story does not need a shocking event to be moving if the emotions are honest.","zh":"如果情感真誠，一個故事不需要震撼事件也可以動人。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"a retired neon-sign craftsman","meaning":"退休霓虹招牌工匠","examples":[{"en":"Lau Man-chung is a retired neon-sign craftsman.","zh":"劉文忠是一名退休霓虹招牌工匠。"},{"en":"A retired neon-sign craftsman is someone who used to make or repair neon signs but no longer works full-time.","zh":"退休霓虹招牌工匠是曾經製作或維修霓虹招牌、但已不再全職工作的人。"},{"en":"A retired neon-sign craftsman may remember when glowing shop signs filled old streets.","zh":"退休霓虹招牌工匠可能記得發光招牌遍佈舊街道的年代。"},{"en":"As neon signs disappear, a retired neon-sign craftsman may feel that part of the city’s memory is fading.","zh":"隨着霓虹招牌消失，退休霓虹招牌工匠可能感到城市記憶的一部分正在褪色。"},{"en":"This character can connect personal regret with the changing look of Hong Kong.","zh":"這個角色可以把個人遺憾與香港外貌的轉變連繫起來。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"stubborn silence","meaning":"固執的沉默","examples":[{"en":"His stubborn silence hides years of regret.","zh":"他固執的沉默隱藏多年的遺憾。"},{"en":"Stubborn silence means refusing to speak even when talking could solve a problem.","zh":"固執的沉默，是指即使說出來可以解決問題，仍拒絕開口。"},{"en":"A father’s stubborn silence may make his children think he does not care.","zh":"父親固執的沉默可能令子女以為他不在乎。"},{"en":"Stubborn silence can damage relationships because feelings remain locked inside.","zh":"固執的沉默會傷害關係，因為感受一直被鎖在心裏。"},{"en":"Sometimes a person uses stubborn silence to protect themselves from shame or pain.","zh":"有時一個人用固執的沉默來保護自己免受羞愧或痛苦。"}],"source":"2021Q9.pdf","sourcePage":3},{"front":"hide years of regret","meaning":"隱藏多年的遺憾","examples":[{"en":"His stubborn silence hides years of regret.","zh":"他固執的沉默隱藏多年的遺憾。"},{"en":"To hide years of regret means to keep long-lasting guilt or sadness unspoken.","zh":"hide years of regret 的意思是把長久的內疚或悲傷藏起來，不說出口。"},{"en":"A person may hide years of regret after failing to apologise to a close friend.","zh":"一個人未能向好友道歉後，可能會隱藏多年的遺憾。"},{"en":"When people hide years of regret, a small conversation can suddenly become emotional.","zh":"當人們隱藏多年的遺憾時，一段小小對話可能突然變得情緒化。"},{"en":"Stories often reveal hidden regret slowly so viewers understand why a character acts coldly.","zh":"故事常慢慢揭示隱藏的遺憾，讓觀眾明白角色為何表現冷淡。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"a hardworking single mother","meaning":"勤奮的單親媽媽","examples":[{"en":"Lau Mei-yan is a hardworking single mother.","zh":"劉美欣是一位勤奮的單親媽媽。"},{"en":"A hardworking single mother raises her child or children without a partner and works hard to support them.","zh":"勤奮的單親媽媽，是指沒有伴侶一起撫養子女，並努力工作支持他們的母親。"},{"en":"A hardworking single mother may rush from work to school to pick up her child.","zh":"勤奮的單親媽媽可能下班後立刻趕去學校接孩子。"},{"en":"Financial pressure can make life especially tiring for a hardworking single mother.","zh":"經濟壓力會令勤奮的單親媽媽生活特別疲累。"},{"en":"This kind of character often shows strength, exhaustion, love, and responsibility at the same time.","zh":"這類角色常同時展示力量、疲憊、愛和責任。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"manage the family café","meaning":"經營家庭茶餐廳","examples":[{"en":"Mei-yan manages the family café.","zh":"美欣經營家庭茶餐廳。"},{"en":"To manage the family café means to run and organise the daily work of a café owned by the family.","zh":"manage the family café 的意思是經營和安排家族擁有的茶餐廳日常工作。"},{"en":"A person who manages the family café may order food, pay staff, serve customers, and handle bills.","zh":"經營家庭茶餐廳的人可能要訂食材、支薪、服務顧客和處理帳單。"},{"en":"If no one manages the family café carefully, service may become slow and money may be lost.","zh":"如果沒有人細心經營家庭茶餐廳，服務可能變慢，金錢也可能流失。"},{"en":"Managing the family café can be stressful because business problems and family problems mix together.","zh":"經營家庭茶餐廳可能很有壓力，因為生意問題和家庭問題混在一起。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"keep everyone together","meaning":"維繫一家人","examples":[{"en":"She tries to keep everyone together.","zh":"她努力維繫一家人。"},{"en":"To keep everyone together means to stop a family or group from falling apart.","zh":"keep everyone together 的意思是阻止一個家庭或群體分裂。"},{"en":"An older sister may keep everyone together by calling relatives after an argument.","zh":"姐姐可能在爭吵後打電話給親戚，以維繫一家人。"},{"en":"When money problems grow, it becomes harder to keep everyone together.","zh":"當金錢問題加深時，維繫一家人會變得更困難。"},{"en":"This phrase often shows emotional responsibility rather than physical action only.","zh":"這個短語常表示情感上的責任，而不只是身體上的行動。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"return from Canada","meaning":"從加拿大回來","examples":[{"en":"Wai-hong has returned from Canada after a failed business venture.","zh":"偉康在一次創業失敗後從加拿大回來。"},{"en":"To return from Canada means to come back after living, working, or staying in Canada.","zh":"return from Canada 的意思是在加拿大生活、工作或逗留後回來。"},{"en":"A student may return from Canada after finishing university there.","zh":"學生可能在加拿大完成大學後從加拿大回來。"},{"en":"When someone returns from Canada after many years, relatives may treat them differently.","zh":"當某人多年後從加拿大回來，親人可能會以不同方式對待他。"},{"en":"Returning from Canada can bring both excitement and awkwardness if old relationships have changed.","zh":"如果舊關係已經改變，從加拿大回來可能同時帶來興奮和尷尬。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"a failed business venture","meaning":"失敗的創業項目","examples":[{"en":"He returned from Canada after a failed business venture.","zh":"他在一次失敗的創業項目後從加拿大回來。"},{"en":"A failed business venture is a business attempt that did not succeed.","zh":"失敗的創業項目，是指沒有成功的生意嘗試。"},{"en":"A café opened without enough customers can become a failed business venture.","zh":"一間開業後沒有足夠顧客的咖啡店，可能成為失敗的創業項目。"},{"en":"A failed business venture may leave a person with debt, shame, and fear of starting again.","zh":"失敗的創業項目可能令一個人留下債務、羞愧和再次開始的恐懼。"},{"en":"Talking honestly about a failed business venture can help a family understand what really happened.","zh":"誠實談論失敗的創業項目，可以幫助家人理解真正發生了甚麼。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"be treated as both…and…","meaning":"被視為既是……又是……","examples":[{"en":"Wai-hong is treated as both a stranger and a son.","zh":"偉康被視為既是陌生人，又是兒子。"},{"en":"To be treated as both one thing and another means people see you in two different ways at the same time.","zh":"be treated as both one thing and another 的意思是別人同時用兩種不同方式看待你。"},{"en":"A student who returns after studying abroad may be treated as both local and foreign.","zh":"一個留學後回來的學生，可能被視為既是本地人，又是外來者。"},{"en":"Being treated as both trusted and blamed can make a person feel confused.","zh":"被視為既可信又應受責怪，可能令一個人感到困惑。"},{"en":"This structure shows mixed feelings, especially in complicated relationships.","zh":"這個結構展示混合感受，尤其適用於複雜關係。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"the youngest generation","meaning":"最年輕一代","examples":[{"en":"The youngest generation consists of Chloe and Marcus.","zh":"最年輕一代由 Chloe 和 Marcus 組成。"},{"en":"The youngest generation means the children or teenagers in a family or group.","zh":"最年輕一代是指家庭或群體中的孩子或青少年。"},{"en":"The youngest generation may understand technology better than their parents and grandparents.","zh":"最年輕一代可能比父母和祖父母更懂科技。"},{"en":"In a family drama, the youngest generation often asks questions that older people avoid.","zh":"在家庭劇中，最年輕一代常提出長輩迴避的問題。"},{"en":"The youngest generation can bring new ideas but may also feel pressure from old expectations.","zh":"最年輕一代可以帶來新想法，但也可能感到舊期望帶來壓力。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"consist of","meaning":"由……組成","examples":[{"en":"The youngest generation consists of Chloe and Marcus.","zh":"最年輕一代由 Chloe 和 Marcus 組成。"},{"en":"Consist of means to be made up of certain people, parts, or things.","zh":"consist of 的意思是由某些人、部分或事物組成。"},{"en":"A school team may consist of players, a coach, and student helpers.","zh":"一支校隊可以由球員、教練和學生助手組成。"},{"en":"A balanced meal can consist of rice, vegetables, protein, and fruit.","zh":"一頓均衡膳食可以由米飯、蔬菜、蛋白質和水果組成。"},{"en":"Use consist of when you want to explain what something includes.","zh":"當你想解釋某事物包括甚麼時，可以使用 consist of。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"a Form Six student","meaning":"中六學生","examples":[{"en":"Chloe is a Form Six student who wants to become a documentary filmmaker.","zh":"Chloe 是一名中六學生，想成為紀錄片導演。"},{"en":"A Form Six student is a senior secondary student preparing for important public examinations in Hong Kong.","zh":"中六學生是在香港準備重要公開考試的高中學生。"},{"en":"A Form Six student may feel pressure from exams, university choices, and family expectations.","zh":"中六學生可能因考試、大學選擇和家庭期望而感到壓力。"},{"en":"If a Form Six student has a dream outside traditional careers, adults may not understand at first.","zh":"如果中六學生有傳統職業以外的夢想，成年人起初可能不明白。"},{"en":"This detail helps show that Chloe is at an age of pressure and decision.","zh":"這個細節有助展示 Chloe 正處於有壓力和要作決定的年紀。"}],"source":"2021Q9.pdf","sourcePage":4},{"front":"documentary filmmaker","meaning":"紀錄片導演","examples":[{"en":"Chloe wants to become a documentary filmmaker.","zh":"Chloe 想成為紀錄片導演。"},{"en":"A documentary filmmaker makes films about real people, events, places, or social issues.","zh":"紀錄片導演拍攝關於真實人物、事件、地方或社會議題的影片。"},{"en":"A documentary filmmaker may interview elderly neighbours to record their memories.","zh":"紀錄片導演可能訪問長者鄰居，以記錄他們的回憶。"},{"en":"Good documentary filmmakers need patience because real stories take time to understand.","zh":"好的紀錄片導演需要耐性，因為真實故事需要時間去理解。"},{"en":"A documentary filmmaker can help viewers see ordinary lives with more respect.","zh":"紀錄片導演可以幫助觀眾更尊重地看見普通人的生活。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"better than the adults realise","meaning":"比成年人意識到的更清楚","examples":[{"en":"Marcus understands the family better than the adults realise.","zh":"Marcus 比成年人意識到的更清楚地理解這個家庭。"},{"en":"Better than the adults realise means a young person knows more than older people think.","zh":"better than the adults realise 的意思是年輕人知道的比成年人以為的更多。"},{"en":"A child may understand parents’ money worries better than the adults realise.","zh":"孩子可能比成年人意識到的更清楚地理解父母的金錢憂慮。"},{"en":"Adults may hide arguments, but children often notice tension better than the adults realise.","zh":"成年人可能隱藏爭吵，但孩子常比成年人意識到的更清楚地察覺張力。"},{"en":"This phrase shows that young characters can be observant, not just innocent.","zh":"這個短語顯示年輕角色可以很有觀察力，而不只是天真。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"stand between…and…","meaning":"站在……與……之間","examples":[{"en":"The young characters stand between old habits and new ambitions.","zh":"年輕角色站在舊習慣與新抱負之間。"},{"en":"To stand between two things means to be caught between different choices, values, or worlds.","zh":"stand between two things 的意思是夾在不同選擇、價值或世界之間。"},{"en":"Teenagers often stand between family expectations and their own dreams.","zh":"青少年常站在家庭期望與自己夢想之間。"},{"en":"A small shop may stand between tradition and the need to modernise.","zh":"小店可能站在傳統與現代化需要之間。"},{"en":"This phrase is useful when a person or group belongs partly to both sides.","zh":"當一個人或群體部分屬於兩邊時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"old habits","meaning":"舊習慣","examples":[{"en":"The younger generation stands between old habits and new ambitions.","zh":"年輕一代站在舊習慣與新抱負之間。"},{"en":"Old habits are ways of acting or thinking that people have followed for a long time.","zh":"舊習慣是人們長久以來遵循的行為或思考方式。"},{"en":"A family may keep old habits, such as eating together every Sunday.","zh":"一個家庭可能保留舊習慣，例如每個星期日一起吃飯。"},{"en":"Old habits can comfort people, but they can also stop necessary change.","zh":"舊習慣可以安慰人，但也可能阻止必要的改變。"},{"en":"When young people question old habits, elders may feel criticised or afraid.","zh":"當年輕人質疑舊習慣時，長輩可能感到被批評或害怕。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"new ambitions","meaning":"新抱負","examples":[{"en":"The younger generation brings new ambitions into the family.","zh":"年輕一代把新抱負帶進家庭。"},{"en":"New ambitions are fresh goals or dreams that people want to achieve.","zh":"新抱負是人們想實現的新目標或夢想。"},{"en":"A teenager’s new ambitions may include studying film instead of joining the family business.","zh":"青少年的新抱負可能包括修讀電影，而不是加入家族生意。"},{"en":"New ambitions can create conflict when they challenge old expectations.","zh":"當新抱負挑戰舊期望時，可能會造成衝突。"},{"en":"Families grow when they learn to listen to new ambitions instead of rejecting them immediately.","zh":"當家庭學會聆聽新抱負，而不是立刻拒絕它們時，家庭就會成長。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"warmth and tension","meaning":"溫情與張力","examples":[{"en":"The young characters give the drama both warmth and tension.","zh":"年輕角色為這部劇集帶來溫情與張力。"},{"en":"Warmth and tension means a story has kindness and love, but also conflict or pressure.","zh":"溫情與張力，意思是故事中既有善意和愛，也有衝突或壓力。"},{"en":"A family dinner can have warmth and tension when relatives care about one another but disagree strongly.","zh":"當親人彼此關心卻強烈意見不合時，一頓家庭晚餐可以同時有溫情與張力。"},{"en":"Warmth and tension make a drama feel real because family life is rarely simple.","zh":"溫情與張力令劇集感覺真實，因為家庭生活很少是簡單的。"},{"en":"Without warmth, conflict feels harsh; without tension, a story may feel too flat.","zh":"沒有溫情，衝突會顯得冷酷；沒有張力，故事可能顯得平淡。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"central to the story","meaning":"對故事十分重要","examples":[{"en":"The setting is central to the story.","zh":"背景對故事十分重要。"},{"en":"Central to the story means extremely important to how the story develops.","zh":"central to the story 的意思是對故事如何發展極其重要。"},{"en":"In a school drama, the classroom may be central to the story because most conflicts begin there.","zh":"在校園劇中，課室可能對故事十分重要，因為大多數衝突都從那裏開始。"},{"en":"A café can be central to the story if every family member has memories connected to it.","zh":"如果每個家庭成員都有與茶餐廳相連的回憶，茶餐廳就可以對故事十分重要。"},{"en":"When something is central to the story, removing it would change the whole meaning.","zh":"當某事物對故事十分重要時，把它移走會改變整個意義。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"old signboards","meaning":"舊招牌","examples":[{"en":"Golden Years sits under old signboards.","zh":"「金年華」位於舊招牌之下。"},{"en":"Old signboards are shop signs that have been used for many years and often carry local history.","zh":"舊招牌是使用多年、常承載本地歷史的店舖招牌。"},{"en":"Old signboards can remind residents of shops that once shaped the neighbourhood.","zh":"舊招牌可以提醒居民那些曾塑造社區的店舖。"},{"en":"When old signboards are removed, a street may lose part of its familiar character.","zh":"當舊招牌被移走，一條街可能失去部分熟悉特色。"},{"en":"In a drama, old signboards can quietly show memory, age, and change.","zh":"在劇集中，舊招牌可以悄悄展示記憶、年歲和轉變。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"newly built flats","meaning":"新建住宅單位","examples":[{"en":"The café stands beside newly built flats.","zh":"這間茶餐廳位於新建住宅單位旁邊。"},{"en":"Newly built flats are apartments that have recently been constructed.","zh":"新建住宅單位是最近建成的公寓。"},{"en":"Newly built flats may attract young families but also raise rent in an old neighbourhood.","zh":"新建住宅單位可能吸引年輕家庭，但也可能推高舊社區的租金。"},{"en":"When newly built flats appear beside old shops, residents may feel the area is changing too quickly.","zh":"當新建住宅單位出現在舊店旁邊時，居民可能覺得該區變化太快。"},{"en":"This contrast can show the pressure between development and memory.","zh":"這種對比可以展示發展與記憶之間的壓力。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"a soon-to-close cinema","meaning":"即將結業的戲院","examples":[{"en":"The café is opposite a soon-to-close cinema.","zh":"這間茶餐廳對面是一間即將結業的戲院。"},{"en":"A soon-to-close cinema is a cinema that will stop operating in the near future.","zh":"即將結業的戲院，是指不久後將停止營業的戲院。"},{"en":"A soon-to-close cinema may still hold memories for people who watched films there as children.","zh":"即將結業的戲院可能仍承載人們童年看電影的回憶。"},{"en":"When a soon-to-close cinema announces its final week, neighbours may feel that an era is ending.","zh":"當即將結業的戲院宣布最後一星期營業時，鄰里可能覺得一個年代正在結束。"},{"en":"This detail can make a setting feel sad because it shows local culture disappearing.","zh":"這個細節可以令背景帶有哀傷，因為它展示本地文化正在消失。"}],"source":"2021Q9.pdf","sourcePage":5},{"front":"the noisy kitchen","meaning":"嘈雜的廚房","examples":[{"en":"Scenes take place in the noisy kitchen of the family café.","zh":"場景發生在家庭茶餐廳嘈雜的廚房中。"},{"en":"The noisy kitchen is a busy cooking space full of sounds such as chopping, frying, talking, and orders.","zh":"嘈雜的廚房是充滿切菜、煎炒、說話和落單聲音的繁忙煮食空間。"},{"en":"In a noisy kitchen, workers must listen carefully so they do not miss instructions.","zh":"在嘈雜的廚房中，員工必須仔細聆聽，才不會錯過指示。"},{"en":"A noisy kitchen can create tension because people are tired, rushed, and surrounded by heat.","zh":"嘈雜的廚房會造成張力，因為人們疲累、趕急，又被熱力包圍。"},{"en":"In family dramas, a noisy kitchen often becomes a place where hidden feelings suddenly come out.","zh":"在家庭劇中，嘈雜的廚房常成為隱藏感受突然爆發的地方。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"narrow rooftop","meaning":"狹窄的天台","examples":[{"en":"Chloe secretly films interviews on the narrow rooftop.","zh":"Chloe 在狹窄的天台上偷拍訪問。"},{"en":"A narrow rooftop is a small, limited roof space where people cannot move around freely.","zh":"狹窄的天台是空間有限、不能自由走動的小天台。"},{"en":"Teenagers may sit on a narrow rooftop when they need a quiet place away from adults.","zh":"青少年需要遠離成年人、找個安靜地方時，可能會坐在狹窄的天台上。"},{"en":"A narrow rooftop can feel private but also slightly dangerous because there is little space.","zh":"狹窄的天台可以感覺私密，但也因空間不足而有點危險。"},{"en":"In a drama, a narrow rooftop can create intimate conversations above the noise of the city.","zh":"在劇集中，狹窄的天台可以在城市噪音之上創造親密對話。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"secretly films interviews","meaning":"偷偷拍攝訪問","examples":[{"en":"Chloe secretly films interviews on the rooftop.","zh":"Chloe 在天台上偷拍訪問。"},{"en":"To secretly film interviews means to record people speaking without openly telling everyone involved.","zh":"secretly film interviews 的意思是在沒有公開告訴所有相關人士的情況下，錄下別人說話。"},{"en":"A student may secretly film interviews because she is afraid her family will stop the project.","zh":"學生可能因害怕家人阻止項目，而偷偷拍攝訪問。"},{"en":"Secretly filming interviews can create conflict if people feel their privacy has been broken.","zh":"如果別人覺得私隱被侵犯，偷偷拍攝訪問可能造成衝突。"},{"en":"This action shows curiosity, courage, and possible danger at the same time.","zh":"這個行動同時展示好奇、勇氣和可能的危險。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"every corner reveals","meaning":"每個角落都展現","examples":[{"en":"Every corner reveals a different layer of Hong Kong life.","zh":"每個角落都展現香港生活的不同層面。"},{"en":"Every corner reveals means many small places show something meaningful when people look closely.","zh":"every corner reveals 的意思是許多小地方在細看時都展示有意義的東西。"},{"en":"In an old market, every corner reveals a story about work, food, and neighbours.","zh":"在舊街市中，每個角落都展現關於工作、食物和鄰里的故事。"},{"en":"When every corner reveals memory, the setting becomes more than a background.","zh":"當每個角落都展現記憶時，背景就不只是背景。"},{"en":"This phrase helps describe a place that feels rich, detailed, and full of life.","zh":"這個短語有助描述一個豐富、細緻和充滿生命力的地方。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"a different layer of","meaning":"……的不同層面","examples":[{"en":"The café reveals a different layer of Hong Kong life.","zh":"這間茶餐廳展現香港生活的不同層面。"},{"en":"A different layer of something means another side or level that is not immediately obvious.","zh":"a different layer of something 的意思是另一個不一定即時看見的面向或層次。"},{"en":"Talking to cleaners may reveal a different layer of school life that students often ignore.","zh":"與清潔工交談，可能揭示學生常忽略的校園生活不同層面。"},{"en":"A night bus route can show a different layer of the city after most people have gone home.","zh":"夜班巴士路線可以展示大多數人回家後城市的不同層面。"},{"en":"This phrase is useful when a place or story has hidden depth.","zh":"當一個地方或故事有隱藏深度時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"Hong Kong life","meaning":"香港生活","examples":[{"en":"The setting shows many layers of Hong Kong life.","zh":"這個背景展示香港生活的許多層面。"},{"en":"Hong Kong life includes the city’s homes, food, transport, work, family pressure, and neighbourhood culture.","zh":"香港生活包括這座城市的住屋、食物、交通、工作、家庭壓力和社區文化。"},{"en":"A drama about crowded flats and busy cafés can show everyday Hong Kong life.","zh":"一部關於擠迫單位和繁忙茶餐廳的劇集，可以展示日常香港生活。"},{"en":"Hong Kong life often mixes speed, pressure, humour, and strong community memory.","zh":"香港生活常混合速度、壓力、幽默和強烈的社區記憶。"},{"en":"A story feels local when it shows Hong Kong life through ordinary details, not only famous landmarks.","zh":"當故事透過普通細節而不只是著名地標展示香港生活時，它會感覺本地。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"under threat","meaning":"受到威脅","examples":[{"en":"The family café is also under threat.","zh":"這間家庭茶餐廳也受到威脅。"},{"en":"Under threat means facing danger, pressure, or the possibility of being lost.","zh":"under threat 的意思是面對危險、壓力或可能失去的情況。"},{"en":"A small library may be under threat if the government plans to cut its funding.","zh":"如果政府計劃削減資金，一間小圖書館可能受到威脅。"},{"en":"Old neighbourhood shops are under threat when rents rise faster than profits.","zh":"當租金上升得比利潤快，舊社區小店就會受到威脅。"},{"en":"When something is under threat, people must decide whether and how to protect it.","zh":"當某事物受到威脅時，人們必須決定是否以及如何保護它。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"a developer","meaning":"地產發展商","examples":[{"en":"A developer offers to buy the building.","zh":"一名地產發展商提出收購這座大廈。"},{"en":"A developer is a person or company that buys land or buildings to create new property projects.","zh":"地產發展商是購買土地或樓宇以發展新物業項目的人或公司。"},{"en":"A developer may replace old shops with new flats or shopping centres.","zh":"地產發展商可能用新住宅或商場取代舊店舖。"},{"en":"When a developer enters an old neighbourhood, residents may worry about rent and memories being lost.","zh":"當地產發展商進入舊社區時，居民可能擔心租金和回憶會消失。"},{"en":"In dramas, a developer often creates pressure by offering money for a place people love.","zh":"在劇集中，地產發展商常透過為人們所愛的地方出價來製造壓力。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"offer to buy","meaning":"提出收購","examples":[{"en":"A developer offers to buy the building.","zh":"一名地產發展商提出收購這座大廈。"},{"en":"To offer to buy something means to say that you are willing to pay money for it.","zh":"offer to buy something 的意思是表示願意付錢購買某物。"},{"en":"A neighbour may offer to buy an old bicycle that has been left unused.","zh":"鄰居可能提出收購一部已閒置的舊單車。"},{"en":"When someone offers to buy a family home, relatives may argue about whether to accept.","zh":"當有人提出收購家庭住所時，親人可能會爭論是否接受。"},{"en":"An offer to buy can seem helpful, but it may also create difficult choices.","zh":"收購提議看似有幫助，但也可能造成艱難選擇。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"promise someone a share of","meaning":"承諾給某人一份……","examples":[{"en":"The developer promises each family member a share of the money.","zh":"地產發展商承諾給每位家庭成員一份款項。"},{"en":"To promise someone a share of something means to say they will receive part of it.","zh":"promise someone a share of something 的意思是承諾某人會得到其中一部分。"},{"en":"Parents may promise each child a share of the family savings when they sell an old flat.","zh":"父母賣掉舊單位時，可能承諾給每個孩子一份家庭積蓄。"},{"en":"Promising someone a share of the money can reduce arguments, but it can also make people greedy.","zh":"承諾給某人一份金錢可以減少爭執，但也可能令人變得貪心。"},{"en":"This phrase is often used when money, property, or responsibility is divided.","zh":"這個短語常用於分配金錢、物業或責任時。"}],"source":"2021Q9.pdf","sourcePage":6},{"front":"a share of the money","meaning":"一份金錢；一份款項","examples":[{"en":"Each family member is promised a share of the money.","zh":"每位家庭成員都被承諾會得到一份款項。"},{"en":"A share of the money means one part of a larger amount that is divided among people.","zh":"a share of the money 是指在一筆較大金額中分給某人的一部分。"},{"en":"After selling a shop, siblings may each receive a share of the money.","zh":"賣掉店舖後，兄弟姊妹可能各自得到一份款項。"},{"en":"Arguments may begin if people think their share of the money is unfair.","zh":"如果人們認為自己分得的一份款項不公平，爭執可能開始。"},{"en":"Money can look simple on paper, but a share of the money may carry emotion and history.","zh":"金錢在紙面上看似簡單，但一份款項可能承載情感和歷史。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"at first glance","meaning":"乍看之下","examples":[{"en":"At first glance, selling the building seems sensible.","zh":"乍看之下，賣掉大廈看似合理。"},{"en":"At first glance means when you first look at something, before thinking more carefully.","zh":"at first glance 的意思是在最初看某事時，還未仔細思考。"},{"en":"At first glance, the cheaper phone seems like the better choice.","zh":"乍看之下，較便宜的手機似乎是更好的選擇。"},{"en":"At first glance, moving schools may seem frightening, but it may bring better support.","zh":"乍看之下，轉校可能令人害怕，但它可能帶來更好的支援。"},{"en":"This phrase often prepares readers for a deeper view that may be different from the first impression.","zh":"這個短語常為讀者準備一個可能不同於第一印象的更深看法。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"seem sensible","meaning":"看似合理","examples":[{"en":"Selling the building seems sensible at first.","zh":"賣掉大廈起初看似合理。"},{"en":"Seem sensible means appear reasonable or practical.","zh":"seem sensible 的意思是看起來合理或實際。"},{"en":"Taking the bus may seem sensible when parking is expensive.","zh":"當泊車費昂貴時，乘巴士可能看似合理。"},{"en":"A decision can seem sensible at first but cause regret if people ignore emotions.","zh":"一個決定起初可能看似合理，但如果人們忽略情感，可能會造成遺憾。"},{"en":"This phrase is useful when an idea looks practical but still needs careful thought.","zh":"當一個想法看似實際但仍需要仔細考慮時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"on closer inspection","meaning":"仔細一看","examples":[{"en":"On closer inspection, the offer creates painful questions.","zh":"仔細一看，這個收購提議帶來痛苦的問題。"},{"en":"On closer inspection means after looking more carefully at the details.","zh":"on closer inspection 的意思是在更仔細查看細節之後。"},{"en":"On closer inspection, the cheap apartment has hidden repair costs.","zh":"仔細一看，那個便宜單位有隱藏的維修費用。"},{"en":"On closer inspection, a simple family argument may reveal years of hurt.","zh":"仔細一看，一場簡單家庭爭吵可能揭示多年的傷痛。"},{"en":"This phrase shows that the first impression was incomplete.","zh":"這個短語顯示第一印象並不完整。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"force someone to ask","meaning":"迫使某人思考","examples":[{"en":"The offer forces each character to ask what home is worth.","zh":"這個收購提議迫使每個角色思考家的價值。"},{"en":"To force someone to ask means to make a person face a question they cannot avoid.","zh":"force someone to ask 的意思是令某人面對一個無法迴避的問題。"},{"en":"Losing a job may force someone to ask what kind of work they truly want.","zh":"失去工作可能迫使某人思考自己真正想要甚麼工作。"},{"en":"A serious illness can force a family to ask how they should spend their time together.","zh":"一場重病可以迫使家庭思考他們應如何一起度過時間。"},{"en":"This phrase often introduces a difficult question caused by pressure or change.","zh":"這個短語常引出由壓力或改變造成的艱難問題。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"what a home is worth","meaning":"一個家的價值","examples":[{"en":"Each character must ask what a home is worth.","zh":"每個角色都必須思考一個家的價值。"},{"en":"What a home is worth means the value of a home in money, memory, love, and belonging.","zh":"what a home is worth 的意思是一個家在金錢、回憶、愛與歸屬感上的價值。"},{"en":"A flat may be worth millions, but what a home is worth cannot be measured only by price.","zh":"一個單位可能值數百萬，但一個家的價值不能只用價格衡量。"},{"en":"When a family considers selling, they must ask what a home is worth to each person.","zh":"當家庭考慮出售時，他們必須思考一個家對每個人有甚麼價值。"},{"en":"This question is painful because home can mean safety to one person and burden to another.","zh":"這個問題令人痛苦，因為家對一個人可能是安全，對另一個人可能是負擔。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"not only…but also…","meaning":"不但……而且……","examples":[{"en":"The home contains not only property, but also grief and promises.","zh":"這個家不但包含物業，而且包含悲傷與承諾。"},{"en":"Not only…but also connects two ideas and shows that both are important.","zh":"not only…but also 連接兩個想法，並顯示兩者都重要。"},{"en":"A good school teaches not only knowledge, but also kindness and responsibility.","zh":"好學校不但教知識，而且教善良和責任。"},{"en":"A family meal is not only about food, but also about time spent together.","zh":"一頓家庭飯不但關於食物，而且關於一起相處的時間。"},{"en":"This structure helps writers add a deeper or surprising second point.","zh":"這個結構幫助作者加入更深或令人意外的第二點。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"unfinished apologies","meaning":"未說出口的道歉","examples":[{"en":"The home contains grief, promises and unfinished apologies.","zh":"這個家包含悲傷、承諾和未說出口的道歉。"},{"en":"Unfinished apologies are apologies that people wanted or needed to say but never completed.","zh":"未說出口的道歉，是指人們想說或需要說，但從未完成的道歉。"},{"en":"A son may carry unfinished apologies after leaving home during an argument.","zh":"兒子在爭吵中離家後，可能一直背負未說出口的道歉。"},{"en":"Unfinished apologies can keep families apart because no one knows how to begin again.","zh":"未說出口的道歉可以令家人分離，因為沒有人知道如何重新開始。"},{"en":"A drama may use unfinished apologies to show that silence can hurt for many years.","zh":"劇集可以用未說出口的道歉來展示沉默可以傷害多年。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"the plot begins when","meaning":"劇情開始於……","examples":[{"en":"The plot begins when Chloe discovers a box of old videotapes.","zh":"劇情開始於 Chloe 發現一箱舊錄影帶。"},{"en":"The plot begins when means the main story starts at the moment a key event happens.","zh":"the plot begins when 的意思是主要故事在某個關鍵事件發生時開始。"},{"en":"The plot begins when a student finds a lost letter inside an old library book.","zh":"劇情開始於一名學生在舊圖書館書本裏發現一封遺失的信。"},{"en":"If the plot begins when a secret is discovered, viewers immediately want to know more.","zh":"如果劇情開始於一個秘密被發現，觀眾會立刻想知道更多。"},{"en":"This phrase helps introduce the event that starts the story’s main conflict.","zh":"這個短語幫助介紹引發故事主要衝突的事件。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"discover a box of","meaning":"發現一箱……","examples":[{"en":"Chloe discovers a box of old videotapes.","zh":"Chloe 發現一箱舊錄影帶。"},{"en":"To discover a box of something means to find a container filled with things, often unexpectedly.","zh":"discover a box of something 的意思是找到一個裝滿某些東西的箱子，通常是意外發現。"},{"en":"A child may discover a box of family photos while cleaning a cupboard.","zh":"孩子在清理櫃子時，可能發現一箱家庭相片。"},{"en":"Discovering a box of letters can reveal forgotten promises or hidden problems.","zh":"發現一箱信件可能揭示被遺忘的承諾或隱藏問題。"},{"en":"This phrase often begins a mystery because the objects inside may explain the past.","zh":"這個短語常開啟一個謎團，因為箱內物件可能解釋過去。"}],"source":"2021Q9.pdf","sourcePage":7},{"front":"old videotapes","meaning":"舊錄影帶","examples":[{"en":"Chloe discovers a box of old videotapes recorded by her grandmother.","zh":"Chloe 發現一箱由祖母錄製的舊錄影帶。"},{"en":"Old videotapes are video recordings from the past, usually stored on physical tapes.","zh":"舊錄影帶是過去的影片紀錄，通常儲存在實體錄影帶上。"},{"en":"Old videotapes may show family members when they were young.","zh":"舊錄影帶可能展示家人年輕時的樣子。"},{"en":"If old videotapes are damaged, important memories may be lost forever.","zh":"如果舊錄影帶損壞，重要回憶可能永遠失去。"},{"en":"In a drama, old videotapes can let the past speak directly to the present.","zh":"在劇集中，舊錄影帶可以讓過去直接向現在說話。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"recorded by","meaning":"由……錄製","examples":[{"en":"The videotapes were recorded by Chloe’s late grandmother.","zh":"這些錄影帶由 Chloe 的已故祖母錄製。"},{"en":"Recorded by means created or captured on audio or video by a particular person.","zh":"recorded by 的意思是由某個人以聲音或影像形式錄下。"},{"en":"The interview was recorded by a student for her history project.","zh":"這段訪問由一名學生為她的歷史項目錄製。"},{"en":"A message recorded by a parent can become precious after many years.","zh":"由父母錄製的訊息，多年後可能變得珍貴。"},{"en":"This phrase tells us who made the recording and may explain why it matters.","zh":"這個短語告訴我們誰製作了錄音或影片，也可能解釋它為何重要。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"late grandmother","meaning":"已故祖母","examples":[{"en":"The tapes were recorded by Chloe’s late grandmother.","zh":"這些錄影帶由 Chloe 的已故祖母錄製。"},{"en":"Late grandmother means a grandmother who has passed away.","zh":"late grandmother 的意思是已經去世的祖母。"},{"en":"A child may keep a recipe book written by her late grandmother.","zh":"孩子可能保存一本由已故祖母寫下的食譜。"},{"en":"Memories of a late grandmother can bring comfort but also sadness during family gatherings.","zh":"在家庭聚會中，已故祖母的回憶可以帶來安慰，也帶來悲傷。"},{"en":"This phrase is respectful and often used when speaking about someone who has died.","zh":"這個短語很尊重，常用於談及已離世的人。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"be linked to","meaning":"與……有關","examples":[{"en":"Each tape is linked to one episode and one family secret.","zh":"每卷錄影帶都與一集和一個家庭秘密有關。"},{"en":"To be linked to something means to be connected with it in meaning, cause, or story.","zh":"be linked to something 的意思是在意義、原因或故事上與某事相連。"},{"en":"A student’s tiredness may be linked to poor sleep rather than laziness.","zh":"學生的疲累可能與睡眠不足有關，而不是懶惰。"},{"en":"A family argument can be linked to an old event that no one wants to discuss.","zh":"一場家庭爭吵可以與一件沒有人想討論的舊事有關。"},{"en":"This phrase helps explain that two things are not separate.","zh":"這個短語幫助解釋兩件事並不是分開的。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"one family secret","meaning":"一個家庭秘密","examples":[{"en":"Each tape reveals one family secret.","zh":"每卷錄影帶揭示一個家庭秘密。"},{"en":"One family secret is a hidden truth known by some relatives but not openly discussed.","zh":"一個家庭秘密，是指一些親人知道但沒有公開討論的隱藏真相。"},{"en":"One family secret may explain why two brothers stopped talking years ago.","zh":"一個家庭秘密可能解釋為何兩兄弟多年前停止說話。"},{"en":"When one family secret is revealed, trust can break or begin to heal.","zh":"當一個家庭秘密被揭示時，信任可能破裂，也可能開始修復。"},{"en":"A drama often uses one family secret to make viewers question what they already believe.","zh":"劇集常用一個家庭秘密令觀眾質疑自己原本相信的事。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"a vanished savings book","meaning":"消失了的存摺","examples":[{"en":"One tape is connected to a vanished savings book.","zh":"其中一卷錄影帶與一本消失了的存摺有關。"},{"en":"A vanished savings book is a bank record book that has disappeared.","zh":"消失了的存摺，是指一本不見了的銀行紀錄簿。"},{"en":"A vanished savings book may cause suspicion if relatives think someone took it.","zh":"如果親人以為有人拿走它，消失了的存摺可能引起猜疑。"},{"en":"If a vanished savings book contained important money records, its loss could create serious conflict.","zh":"如果消失了的存摺載有重要金錢紀錄，它的遺失可能造成嚴重衝突。"},{"en":"This object can symbolise both missing money and missing trust.","zh":"這件物件可以象徵失去的金錢，也象徵失去的信任。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"an unsent letter","meaning":"未寄出的信","examples":[{"en":"Another tape reveals an unsent letter.","zh":"另一卷錄影帶揭示一封未寄出的信。"},{"en":"An unsent letter is a letter that was written but never delivered.","zh":"未寄出的信，是指已經寫好但從未送出的信。"},{"en":"An unsent letter may contain an apology that someone was too afraid to send.","zh":"未寄出的信可能包含某人太害怕寄出的道歉。"},{"en":"Finding an unsent letter can change how a family understands the past.","zh":"發現一封未寄出的信，可以改變一個家庭對過去的理解。"},{"en":"This object is powerful because it shows words that existed but never reached the right person.","zh":"這件物件很有力量，因為它展示了存在過但從未送到對的人手中的說話。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"a broken wedding bracelet","meaning":"破碎的結婚手鏈","examples":[{"en":"The family secret involves a broken wedding bracelet.","zh":"這個家庭秘密涉及一條破碎的結婚手鏈。"},{"en":"A broken wedding bracelet is a damaged piece of jewellery connected to marriage.","zh":"破碎的結婚手鏈，是指一件與婚姻有關但已損壞的首飾。"},{"en":"A broken wedding bracelet may remind a family of love, betrayal, or a painful argument.","zh":"破碎的結婚手鏈可能令一家人想起愛、背叛或痛苦爭吵。"},{"en":"If a wedding bracelet breaks during a quarrel, it may become a symbol of a damaged relationship.","zh":"如果結婚手鏈在爭執中斷裂，它可能成為受損關係的象徵。"},{"en":"In a story, small objects like this can carry large emotional meaning.","zh":"在故事中，這類小物件可以承載巨大的情感意義。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"split the siblings apart","meaning":"令兄弟姊妹反目","examples":[{"en":"A quarrel split the siblings apart.","zh":"一場爭吵令兄弟姊妹反目。"},{"en":"To split the siblings apart means to make brothers and sisters stop being close.","zh":"split the siblings apart 的意思是令兄弟姊妹不再親近。"},{"en":"A fight over inheritance can split the siblings apart for many years.","zh":"一場關於遺產的爭執，可以令兄弟姊妹多年反目。"},{"en":"Misunderstanding a parent’s decision may split the siblings apart if no one explains the truth.","zh":"如果沒有人解釋真相，誤解父母的決定可能令兄弟姊妹反目。"},{"en":"This phrase shows that one conflict can damage a whole family structure.","zh":"這個短語顯示一場衝突可以破壞整個家庭結構。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"take episode four, for example","meaning":"以第四集為例","examples":[{"en":"Take episode four, for example: a blackout traps the family in the café.","zh":"以第四集為例：一場停電把一家人困在茶餐廳裏。"},{"en":"Take episode four, for example is used to introduce one clear example from a larger series.","zh":"take episode four, for example 用來從較大的系列中介紹一個清楚例子。"},{"en":"Take lesson three, for example: it shows how one mistake can change the whole experiment.","zh":"以第三課為例：它展示一個錯誤如何改變整個實驗。"},{"en":"This phrase helps writers support a general point with a specific case.","zh":"這個短語幫助作者用具體例子支持一般看法。"},{"en":"When you say take this for example, readers expect details that prove your idea.","zh":"當你說「以此為例」時，讀者會預期看到證明你想法的細節。"}],"source":"2021Q9.pdf","sourcePage":8},{"front":"a city-wide blackout","meaning":"全城停電","examples":[{"en":"A city-wide blackout traps the family in the café.","zh":"一場全城停電把一家人困在茶餐廳裏。"},{"en":"A city-wide blackout is a power failure that affects the whole city or a very large area.","zh":"全城停電是影響整個城市或很大範圍的電力故障。"},{"en":"During a city-wide blackout, lifts may stop, traffic lights may fail, and shops may close.","zh":"全城停電期間，升降機可能停頓，交通燈可能失靈，商店可能關門。"},{"en":"A city-wide blackout can force people to talk because phones and screens stop working.","zh":"全城停電可以迫使人們交談，因為電話和螢幕停止運作。"},{"en":"In a drama, this event creates pressure by cutting characters off from normal routines.","zh":"在劇集中，這件事透過切斷角色的正常日常生活來製造壓力。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"trap the family in","meaning":"把一家人困在……","examples":[{"en":"The blackout traps the family in the café.","zh":"停電把一家人困在茶餐廳裏。"},{"en":"To trap the family in a place means to make them unable to leave easily.","zh":"trap the family in a place 的意思是令一家人不容易離開某個地方。"},{"en":"Heavy rain may trap a family in a small village for the night.","zh":"大雨可能把一家人困在小村莊一晚。"},{"en":"When characters are trapped in one place, hidden conflicts often come out.","zh":"當角色被困在同一地方時，隱藏衝突常會浮現。"},{"en":"This phrase can describe both a physical situation and an emotional pressure.","zh":"這個短語可以描述身體上的情況，也可以描述情感壓力。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"without phones or customers","meaning":"沒有電話，也沒有顧客","examples":[{"en":"Without phones or customers, the family finally starts talking.","zh":"沒有電話，也沒有顧客，一家人終於開始交談。"},{"en":"Without phones or customers means the usual distractions and business duties are absent.","zh":"without phones or customers 的意思是平常的分心事物和生意責任都不在。"},{"en":"Without phones or customers, café workers may suddenly notice how tired they are.","zh":"沒有電話，也沒有顧客，茶餐廳員工可能突然注意到自己有多疲累。"},{"en":"When a family is without phones or customers, silence can become uncomfortable enough to start a conversation.","zh":"當一家人沒有電話，也沒有顧客時，沉默可能變得尷尬，足以引發對話。"},{"en":"This phrase shows how removing ordinary noise can reveal hidden feelings.","zh":"這個短語展示移除日常噪音後，隱藏感受會浮現。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"finally talk about","meaning":"終於談及","examples":[{"en":"They finally talk about why Wai-hong left Hong Kong.","zh":"他們終於談及偉康當年為何離開香港。"},{"en":"To finally talk about something means to discuss a difficult subject after avoiding it for a long time.","zh":"finally talk about something 的意思是在長時間迴避後，終於討論一個困難話題。"},{"en":"A family may finally talk about debt after another bill arrives.","zh":"另一張帳單到來後，一家人可能終於談及債務。"},{"en":"When people finally talk about old pain, the conversation may be painful but necessary.","zh":"當人們終於談及舊傷痛時，對話可能痛苦但必要。"},{"en":"This phrase suggests relief because silence has lasted too long.","zh":"這個短語暗示一種釋放，因為沉默已經持續太久。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"years ago","meaning":"多年前","examples":[{"en":"Wai-hong left Hong Kong years ago.","zh":"偉康多年前離開香港。"},{"en":"Years ago means many years before the present time.","zh":"years ago 的意思是在現在之前許多年。"},{"en":"She moved to another district years ago, but she still remembers her old neighbours.","zh":"她多年前搬到另一區，但仍記得舊鄰居。"},{"en":"Something that happened years ago can still affect a family today.","zh":"多年前發生的事，今天仍可以影響一個家庭。"},{"en":"This phrase is often used when the past feels distant but not forgotten.","zh":"當過去感覺遙遠但未被遺忘時，常會使用這個短語。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"by the final episode","meaning":"到最後一集","examples":[{"en":"By the final episode, the family must make a difficult decision.","zh":"到最後一集，一家人必須作出艱難決定。"},{"en":"By the final episode means before or at the last part of the series.","zh":"by the final episode 的意思是在劇集最後一部分之前或之時。"},{"en":"By the final episode, viewers expect the main conflicts to reach a turning point.","zh":"到最後一集，觀眾會期望主要衝突到達轉折點。"},{"en":"In a mystery drama, by the final episode, the truth should become clear.","zh":"在懸疑劇中，到最後一集，真相應該變得清楚。"},{"en":"This phrase helps show how the story builds towards its ending.","zh":"這個短語幫助展示故事如何逐步走向結局。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"decide whether to","meaning":"決定是否","examples":[{"en":"The family must decide whether to sell Golden Years.","zh":"這家人必須決定是否賣掉「金年華」。"},{"en":"To decide whether to do something means to choose between doing it and not doing it.","zh":"decide whether to do something 的意思是在做與不做之間作出選擇。"},{"en":"A student must decide whether to join the debate team or focus on exams.","zh":"學生必須決定是否加入辯論隊，還是專注考試。"},{"en":"Families may decide whether to move house after rent becomes too high.","zh":"當租金變得太高時，家庭可能決定是否搬屋。"},{"en":"This phrase is useful when a choice has two serious sides.","zh":"當一個選擇有兩個嚴肅面向時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"turn it into","meaning":"把它變成","examples":[{"en":"They may turn the café into a community kitchen.","zh":"他們可能把茶餐廳變成社區廚房。"},{"en":"To turn it into something means to change its purpose, use, or form.","zh":"turn it into something 的意思是改變它的用途、功能或形式。"},{"en":"A school can turn an empty classroom into a reading room.","zh":"學校可以把空課室變成閱讀室。"},{"en":"If a family turns a shop into a home, the space must be redesigned.","zh":"如果一家人把店舖變成住所，空間就必須重新設計。"},{"en":"This phrase shows transformation from one thing into another.","zh":"這個短語展示某物由一種東西轉變成另一種東西。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"a community kitchen","meaning":"社區廚房","examples":[{"en":"The family considers turning the café into a community kitchen.","zh":"這家人考慮把茶餐廳變成社區廚房。"},{"en":"A community kitchen is a place where food is prepared for people in the neighbourhood, especially those who need help.","zh":"社區廚房是為社區人士，尤其是有需要的人準備食物的地方。"},{"en":"A community kitchen may serve elderly residents, low-income families, or people living alone.","zh":"社區廚房可以服務長者居民、低收入家庭或獨居人士。"},{"en":"If a community kitchen is well organised, it can reduce loneliness as well as hunger.","zh":"如果社區廚房安排得好，它不但可以減少飢餓，也可以減少孤獨。"},{"en":"This idea changes a private business into a service for the wider community.","zh":"這個想法把私人生意變成服務更大社區的地方。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"serve elderly neighbours","meaning":"服務長者鄰居","examples":[{"en":"The kitchen would serve elderly neighbours after closing hours.","zh":"這個廚房會在營業時間結束後服務長者鄰居。"},{"en":"To serve elderly neighbours means to provide help, food, or care to older people living nearby.","zh":"serve elderly neighbours 的意思是為附近長者提供幫助、食物或照顧。"},{"en":"Volunteers may serve elderly neighbours by delivering hot meals during bad weather.","zh":"義工可以在惡劣天氣中派送熱飯，服務長者鄰居。"},{"en":"A café that serves elderly neighbours can become a place of support, not just a business.","zh":"一間服務長者鄰居的茶餐廳，可以成為支援之地，而不只是生意。"},{"en":"This phrase shows kindness in practical action.","zh":"這個短語展示實際行動中的善意。"}],"source":"2021Q9.pdf","sourcePage":9},{"front":"after closing hours","meaning":"營業時間結束後","examples":[{"en":"The café may serve elderly neighbours after closing hours.","zh":"茶餐廳可能在營業時間結束後服務長者鄰居。"},{"en":"After closing hours means after a shop or business has stopped serving normal customers for the day.","zh":"after closing hours 的意思是在店舖或生意一天停止服務普通顧客之後。"},{"en":"Staff may clean tables after closing hours when the last customers have left.","zh":"最後一批顧客離開後，員工可能在營業時間結束後清潔桌子。"},{"en":"A library may hold a private meeting after closing hours for volunteers.","zh":"圖書館可能在營業時間結束後為義工舉行私人會議。"},{"en":"This phrase shows that something happens outside normal business time.","zh":"這個短語表示某事發生在正常營業時間之外。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"hopeful but not unrealistically perfect","meaning":"有希望但不過分理想化","examples":[{"en":"The ending is hopeful but not unrealistically perfect.","zh":"結局有希望但不過分理想化。"},{"en":"Hopeful but not unrealistically perfect means the ending gives comfort while still feeling believable.","zh":"hopeful but not unrealistically perfect 的意思是結局帶來安慰，但仍然可信。"},{"en":"A story may be hopeful but not unrealistically perfect if the family begins to heal but still has work to do.","zh":"如果家庭開始修復關係但仍有事情要努力，故事就可以有希望但不過分理想化。"},{"en":"Such an ending respects real life because problems do not disappear overnight.","zh":"這種結局尊重現實生活，因為問題不會一夜之間消失。"},{"en":"Viewers often trust this kind of ending because it offers hope without pretending everything is fixed.","zh":"觀眾常信任這類結局，因為它給人希望，卻不假裝一切已經解決。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"save part of","meaning":"保住……的一部分","examples":[{"en":"They save part of the café.","zh":"他們保住茶餐廳的一部分。"},{"en":"To save part of something means to protect some of it, even if the whole thing cannot be kept.","zh":"save part of something 的意思是即使不能保留全部，也保護其中一部分。"},{"en":"A school may save part of an old building by turning one room into a history corner.","zh":"學校可以把一個房間變成歷史角，保住舊建築的一部分。"},{"en":"When money is limited, families may save part of a tradition instead of losing it completely.","zh":"當金錢有限時，家庭可能保住傳統的一部分，而不是完全失去它。"},{"en":"This phrase can show compromise between loss and protection.","zh":"這個短語可以展示失去與保護之間的妥協。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"lose part of","meaning":"失去……的一部分","examples":[{"en":"They lose part of the building.","zh":"他們失去大廈的一部分。"},{"en":"To lose part of something means some of it is taken away, sold, damaged, or no longer kept.","zh":"lose part of something 的意思是其中一部分被拿走、出售、損壞或無法保留。"},{"en":"A community may lose part of its park when a new road is built.","zh":"當新道路興建時，社區可能失去公園的一部分。"},{"en":"Losing part of a family home can still hurt, even if some rooms are saved.","zh":"即使有些房間被保留下來，失去家庭住所的一部分仍然會令人心痛。"},{"en":"This phrase often shows that a solution brings both gain and sadness.","zh":"這個短語常顯示解決方法同時帶來收穫和悲傷。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"reconciliation","meaning":"和解","examples":[{"en":"The family learns that reconciliation takes time.","zh":"這家人明白和解需要時間。"},{"en":"Reconciliation is the process of repairing a relationship after conflict, hurt, or separation.","zh":"和解是在衝突、傷害或分離後修復關係的過程。"},{"en":"Reconciliation may begin when two siblings finally admit they both felt hurt.","zh":"當兩兄弟姊妹終於承認彼此都受過傷，和解可能開始。"},{"en":"Forced apologies do not create real reconciliation if no one listens honestly.","zh":"如果沒有人真誠聆聽，被迫道歉並不能帶來真正和解。"},{"en":"Reconciliation often needs patience because trust returns slowly.","zh":"和解常需要耐性，因為信任是慢慢回來的。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"must be rebuilt","meaning":"必須重新建立","examples":[{"en":"Reconciliation, like love, must be rebuilt one conversation at a time.","zh":"和解像愛一樣，必須透過一次又一次對話重新建立。"},{"en":"Must be rebuilt means something damaged needs to be repaired step by step.","zh":"must be rebuilt 的意思是受損的東西需要一步步修復。"},{"en":"Trust must be rebuilt after a friend breaks an important promise.","zh":"朋友打破重要承諾後，信任必須重新建立。"},{"en":"A community damaged by conflict must be rebuilt through fair rules and patient dialogue.","zh":"受衝突傷害的社區，必須透過公平規則和耐心對話重新建立。"},{"en":"This phrase suggests that repair is possible, but it requires effort.","zh":"這個短語暗示修復是可能的，但需要努力。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"one conversation at a time","meaning":"一次談話一步步地","examples":[{"en":"They rebuild trust one conversation at a time.","zh":"他們透過一次又一次談話，一步步重新建立信任。"},{"en":"One conversation at a time means progress happens slowly through repeated honest talks.","zh":"one conversation at a time 的意思是透過重複而真誠的談話慢慢取得進展。"},{"en":"A parent and child may repair their relationship one conversation at a time after years of distance.","zh":"父母和子女在多年疏離後，可能透過一次又一次談話一步步修復關係。"},{"en":"When trust is broken, one conversation at a time is safer than forcing everything to be solved at once.","zh":"當信任破裂時，一次談話一步步地修復，比強迫一次過解決所有事情更安全。"},{"en":"This phrase shows patience and small steps.","zh":"這個短語展示耐性和小步前進。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"would be popular with viewers","meaning":"會受觀眾歡迎","examples":[{"en":"The writer believes the series would be popular with viewers.","zh":"作者相信這部劇集會受觀眾歡迎。"},{"en":"Would be popular with viewers means audiences would probably like and watch it.","zh":"would be popular with viewers 的意思是觀眾很可能會喜歡並收看它。"},{"en":"A comedy about school life would be popular with viewers if the characters feel real.","zh":"如果角色真實，一部關於校園生活的喜劇會受觀眾歡迎。"},{"en":"A programme may be popular with viewers because it speaks to their daily problems.","zh":"一個節目可能因打動觀眾的日常問題而受觀眾歡迎。"},{"en":"This phrase is useful when explaining why a proposal has a good chance of success.","zh":"當解釋一份建議為何有成功機會時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"for two main reasons","meaning":"基於兩個主要原因","examples":[{"en":"The series would be popular for two main reasons.","zh":"這部劇集會受歡迎，基於兩個主要原因。"},{"en":"For two main reasons means there are two important explanations for the point being made.","zh":"for two main reasons 的意思是有兩個重要解釋支持正在提出的觀點。"},{"en":"I support the plan for two main reasons: it saves money and helps students.","zh":"我支持這個計劃，基於兩個主要原因：它節省金錢，也幫助學生。"},{"en":"Using this phrase helps organise an argument clearly.","zh":"使用這個短語可以清楚組織論點。"},{"en":"Readers expect the writer to explain both reasons after this phrase.","zh":"讀者看到這個短語後，會預期作者解釋兩個原因。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"speak to all age groups","meaning":"打動各年齡層","examples":[{"en":"The drama speaks to all age groups.","zh":"這部劇集打動各年齡層。"},{"en":"To speak to all age groups means to be meaningful or attractive to children, adults, and older people.","zh":"speak to all age groups 的意思是對孩子、成年人和長者都有意義或吸引力。"},{"en":"A story about family meals may speak to all age groups because everyone understands home.","zh":"關於家庭飯局的故事可能打動各年齡層，因為人人都理解家。"},{"en":"Programmes that speak to all age groups often mix humour, memory, and current problems.","zh":"打動各年齡層的節目常混合幽默、回憶和當前問題。"},{"en":"This phrase does not mean literal speaking; it means emotional connection.","zh":"這個短語不是指字面上的說話，而是指情感連繫。"}],"source":"2021Q9.pdf","sourcePage":10},{"front":"respond to","meaning":"對……有共鳴","examples":[{"en":"Older viewers will respond to Man-chung’s fear of being forgotten.","zh":"年長觀眾會對文忠害怕被遺忘有共鳴。"},{"en":"To respond to something means to feel a reaction, interest, sympathy, or connection.","zh":"respond to something 的意思是對某事產生反應、興趣、同情或連繫。"},{"en":"Students may respond to a story about exam pressure because it feels close to their lives.","zh":"學生可能對關於考試壓力的故事有共鳴，因為它貼近他們的生活。"},{"en":"Viewers respond to honest characters more strongly than perfect ones.","zh":"觀眾對真誠角色的反應，通常比對完美角色更強烈。"},{"en":"This phrase often explains why a certain audience will care about a story.","zh":"這個短語常解釋為何某類觀眾會在意一個故事。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"fear of being forgotten","meaning":"害怕被遺忘","examples":[{"en":"Man-chung has a deep fear of being forgotten.","zh":"文忠有很深的害怕被遺忘之感。"},{"en":"Fear of being forgotten is the worry that people will no longer remember or value you.","zh":"害怕被遺忘，是指擔心人們不再記得或重視自己。"},{"en":"An elderly craftsman may have a fear of being forgotten when his skills are no longer needed.","zh":"當年長工匠的技術不再被需要時，他可能會害怕被遺忘。"},{"en":"This fear can make people hold tightly to old objects, stories, or places.","zh":"這種恐懼可以令人緊緊抓住舊物件、故事或地方。"},{"en":"A drama about this fear can help younger viewers understand loneliness in old age.","zh":"關於這種恐懼的劇集，可以幫助年輕觀眾理解老年的孤獨。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"understand someone’s exhaustion","meaning":"理解某人的疲累","examples":[{"en":"Parents will understand Mei-yan’s exhaustion.","zh":"父母會理解美欣的疲累。"},{"en":"To understand someone’s exhaustion means to recognise how tired they are and why.","zh":"understand someone’s exhaustion 的意思是明白某人有多疲累以及原因。"},{"en":"Working parents may understand a nurse’s exhaustion after a long night shift.","zh":"在漫長夜班後，工作的父母可能理解護士的疲累。"},{"en":"People understand someone’s exhaustion better when they see the hidden work behind daily responsibilities.","zh":"當人們看見日常責任背後隱藏的工作時，就會更理解某人的疲累。"},{"en":"This phrase shows sympathy for tiredness that may not be obvious at first.","zh":"這個短語表示對起初不明顯的疲累有同理心。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"see themselves in","meaning":"在……身上看到自己","examples":[{"en":"Teenagers will see themselves in Chloe’s hunger to be heard.","zh":"青少年會在 Chloe 渴望被聽見之中看到自己。"},{"en":"To see themselves in a character means to recognise their own feelings or experiences in that person.","zh":"see themselves in a character 的意思是在某個角色身上認出自己的感受或經歷。"},{"en":"Students may see themselves in a character who is afraid to disappoint their parents.","zh":"學生可能在一個害怕令父母失望的角色身上看到自己。"},{"en":"Viewers connect strongly with stories when they see themselves in the struggles on screen.","zh":"當觀眾在螢幕上的掙扎中看到自己時，他們會強烈連繫故事。"},{"en":"This phrase explains why a character feels relatable.","zh":"這個短語解釋為何角色令人有代入感。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"hunger to be heard","meaning":"渴望被聽見","examples":[{"en":"Chloe’s hunger to be heard will speak to teenagers.","zh":"Chloe 渴望被聽見會打動青少年。"},{"en":"Hunger to be heard means a strong desire for others to listen and take your voice seriously.","zh":"hunger to be heard 的意思是強烈希望別人聆聽並認真看待自己的聲音。"},{"en":"A teenager may feel hunger to be heard when adults dismiss every opinion as childish.","zh":"當成年人把每個意見都當成幼稚時，青少年可能會渴望被聽見。"},{"en":"This hunger can lead young people to write, film, protest, or speak more loudly.","zh":"這種渴望可以令年輕人寫作、拍攝、抗議或更大聲說話。"},{"en":"The phrase is emotional because it shows a need for respect, not just attention.","zh":"這個短語帶有情感，因為它展示對尊重的需要，而不只是對注意的需要。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"few, if any","meaning":"即使有，也很少","examples":[{"en":"Few, if any, families are free from misunderstandings.","zh":"即使有，也很少家庭沒有誤會。"},{"en":"Few, if any means almost none, or possibly none at all.","zh":"few, if any 的意思是幾乎沒有，甚至可能完全沒有。"},{"en":"Few, if any, students finish a difficult project without making mistakes.","zh":"即使有，也很少學生能完成困難項目而不犯錯。"},{"en":"Few, if any, friendships survive without honesty and patience.","zh":"即使有，也很少友誼能在沒有誠實和耐性的情況下維持。"},{"en":"This phrase is useful when making a strong but careful general statement.","zh":"當你想作出有力但謹慎的一般說法時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"be free from","meaning":"沒有……；不受……影響","examples":[{"en":"Few families are free from misunderstandings.","zh":"很少家庭沒有誤會。"},{"en":"To be free from something means not to have it or not to be affected by it.","zh":"be free from something 的意思是沒有某事物，或不受其影響。"},{"en":"A school should be free from bullying so students feel safe.","zh":"學校應該沒有欺凌，讓學生感到安全。"},{"en":"No workplace is completely free from pressure, but good management can reduce it.","zh":"沒有工作場所能完全沒有壓力，但良好管理可以減少壓力。"},{"en":"This phrase often describes freedom from problems, danger, or unfair treatment.","zh":"這個短語常描述沒有問題、危險或不公平待遇的狀態。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"misunderstandings","meaning":"誤會","examples":[{"en":"The drama turns family misunderstandings into emotional scenes.","zh":"這部劇集把家庭誤會變成充滿情感的場面。"},{"en":"Misunderstandings happen when people wrongly understand someone’s words, actions, or intentions.","zh":"誤會發生在人們錯誤理解別人的說話、行動或意圖時。"},{"en":"A misunderstanding may begin when a text message sounds colder than the writer intended.","zh":"當短訊聽起來比作者原意更冷淡時，誤會可能開始。"},{"en":"Family misunderstandings can grow serious when no one asks for clarification.","zh":"如果沒有人詢問清楚，家庭誤會可以變得嚴重。"},{"en":"Many conflicts become easier to solve once the misunderstanding is explained.","zh":"一旦誤會被解釋清楚，許多衝突就會更容易解決。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"scenes of humour, conflict and tenderness","meaning":"帶有幽默、衝突和溫情的場面","examples":[{"en":"The drama turns misunderstandings into scenes of humour, conflict and tenderness.","zh":"這部劇集把誤會變成帶有幽默、衝突和溫情的場面。"},{"en":"Scenes of humour, conflict and tenderness contain funny moments, arguments, and gentle care.","zh":"帶有幽默、衝突和溫情的場面，包含有趣時刻、爭吵和溫柔關懷。"},{"en":"A family dinner can create scenes of humour, conflict and tenderness when people tease, quarrel, and help one another.","zh":"當家人互相取笑、爭執又幫助彼此時，一頓家庭飯可以創造帶有幽默、衝突和溫情的場面。"},{"en":"These scenes feel realistic because families often mix laughter with pain.","zh":"這些場面感覺真實，因為家庭常把笑聲與痛苦混在一起。"},{"en":"This phrase describes emotional variety within one story.","zh":"這個短語描述一個故事中的情感多樣性。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"strong visual and emotional appeal","meaning":"強烈的視覺及情感吸引力","examples":[{"en":"The idea has strong visual and emotional appeal.","zh":"這個構思有強烈的視覺及情感吸引力。"},{"en":"Strong visual and emotional appeal means something looks memorable and also touches feelings.","zh":"強烈的視覺及情感吸引力，是指某事物看起來難忘，同時觸動感情。"},{"en":"A film set in an old market may have strong visual and emotional appeal because of its colours and memories.","zh":"一部以舊街市為背景的電影，可能因色彩和回憶而有強烈的視覺及情感吸引力。"},{"en":"Strong visual appeal attracts the eyes, while emotional appeal keeps the heart interested.","zh":"強烈的視覺吸引力吸引眼睛，而情感吸引力令內心保持興趣。"},{"en":"This phrase is useful when explaining why an idea could work well on screen.","zh":"當解釋一個構思為何適合螢幕呈現時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":11},{"front":"neon signs","meaning":"霓虹招牌","examples":[{"en":"The neon signs give the drama a distinctive look.","zh":"霓虹招牌令這部劇集有鮮明外觀。"},{"en":"Neon signs are bright signs made with glowing lights, often used outside shops.","zh":"霓虹招牌是用發光燈管製成的明亮招牌，常見於店舖外。"},{"en":"Neon signs can make a street feel lively, old-fashioned, and full of local memory.","zh":"霓虹招牌可以令街道感覺熱鬧、懷舊和充滿本地記憶。"},{"en":"When neon signs disappear, some people feel the city has lost part of its character.","zh":"當霓虹招牌消失時，有些人覺得城市失去了部分特色。"},{"en":"In visual storytelling, neon signs can create mood before any character speaks.","zh":"在視覺敘事中，霓虹招牌可以在任何角色開口前先營造氣氛。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"handwritten menus","meaning":"手寫餐牌","examples":[{"en":"The handwritten menus help create the café’s identity.","zh":"手寫餐牌幫助創造這間茶餐廳的身份。"},{"en":"Handwritten menus are menus written by hand rather than printed professionally.","zh":"手寫餐牌是用手寫成，而不是專業印刷的餐牌。"},{"en":"Handwritten menus can make a small restaurant feel personal and local.","zh":"手寫餐牌可以令小餐廳感覺有人情味和本地特色。"},{"en":"A handwritten menu may change every day because the owner writes down fresh dishes.","zh":"手寫餐牌可能每天更改，因為店主會寫下新鮮菜式。"},{"en":"In a drama, handwritten menus can show care, habit, and the personality of a place.","zh":"在劇集中，手寫餐牌可以展示用心、習慣和一個地方的個性。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"cramped flat","meaning":"狹小的單位","examples":[{"en":"The cramped flat reflects everyday Hong Kong family life.","zh":"狹小的單位反映日常香港家庭生活。"},{"en":"A cramped flat is a small home where people have little space to move or be private.","zh":"狹小的單位是空間很少、難以自由活動或保持私人空間的住所。"},{"en":"In a cramped flat, siblings may need to study, sleep, and argue in the same room.","zh":"在狹小的單位中，兄弟姊妹可能要在同一房間溫習、睡覺和爭吵。"},{"en":"Cramped flats can increase family tension because everyone hears and sees too much.","zh":"狹小的單位會增加家庭張力，因為每個人都聽到和看到太多。"},{"en":"This setting helps show how physical space affects emotional life.","zh":"這個背景幫助展示實際空間如何影響情感生活。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"rooftop skyline","meaning":"天台天際線","examples":[{"en":"The rooftop skyline gives the drama a memorable visual style.","zh":"天台天際線令這部劇集有難忘的視覺風格。"},{"en":"Rooftop skyline means the view of buildings and sky seen from a rooftop.","zh":"rooftop skyline 的意思是從天台看到的建築物和天空景色。"},{"en":"A rooftop skyline can show old buildings beside new towers.","zh":"天台天際線可以展示舊樓與新高樓並列。"},{"en":"Teenagers may look at the rooftop skyline when they dream about leaving or changing their lives.","zh":"青少年夢想離開或改變生活時，可能會望着天台天際線。"},{"en":"In film, a rooftop skyline can make private feelings feel connected to the whole city.","zh":"在電影中，天台天際線可以令私人感受與整個城市連繫起來。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"distinctive identity","meaning":"鮮明特色","examples":[{"en":"The setting gives the drama a distinctive identity.","zh":"這個背景令這部劇集有鮮明特色。"},{"en":"Distinctive identity means a clear character or style that makes something easy to recognise.","zh":"distinctive identity 的意思是清楚的個性或風格，令某事物容易被認出。"},{"en":"A restaurant has a distinctive identity if people remember its food, design, and service.","zh":"如果人們記得一間餐廳的食物、設計和服務，它就有鮮明特色。"},{"en":"A drama needs a distinctive identity so it does not feel like every other series.","zh":"劇集需要鮮明特色，才不會感覺像其他所有劇集。"},{"en":"Local details often give a story its distinctive identity.","zh":"本地細節常給予故事鮮明特色。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"the mystery of the tapes","meaning":"錄影帶之謎","examples":[{"en":"The mystery of the tapes would encourage viewers to return every week.","zh":"錄影帶之謎會鼓勵觀眾每星期回來收看。"},{"en":"The mystery of the tapes means the unanswered questions hidden in the videotapes.","zh":"錄影帶之謎，是指隱藏在錄影帶中的未解問題。"},{"en":"If each tape reveals only part of the truth, the mystery of the tapes becomes stronger.","zh":"如果每卷錄影帶只揭示部分真相，錄影帶之謎就會更強。"},{"en":"The mystery of the tapes can make viewers wonder who knew the secret and why it was hidden.","zh":"錄影帶之謎可以令觀眾好奇誰知道秘密，以及為何秘密被隱藏。"},{"en":"This phrase shows how an object can drive the story forward.","zh":"這個短語展示一件物件如何推動故事向前。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"encourage viewers to return","meaning":"鼓勵觀眾繼續收看","examples":[{"en":"The mystery would encourage viewers to return every week.","zh":"這個謎團會鼓勵觀眾每星期繼續收看。"},{"en":"To encourage viewers to return means to give audiences a reason to watch the next episode.","zh":"encourage viewers to return 的意思是給觀眾一個收看下一集的理由。"},{"en":"A cliffhanger can encourage viewers to return because they want to know what happens next.","zh":"懸念可以鼓勵觀眾繼續收看，因為他們想知道接下來發生甚麼。"},{"en":"Strong characters encourage viewers to return when people care about their choices.","zh":"當人們在意角色的選擇時，有力角色會鼓勵觀眾繼續收看。"},{"en":"This phrase is useful when explaining how a series keeps its audience.","zh":"當解釋一部劇集如何留住觀眾時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"every week","meaning":"每星期","examples":[{"en":"Viewers would return every week to discover more about the family.","zh":"觀眾會每星期回來收看，以發現更多關於這個家庭的事情。"},{"en":"Every week means once each week or repeatedly from week to week.","zh":"every week 的意思是每週一次，或一星期接一星期地重複。"},{"en":"Students meet every week to practise speaking English.","zh":"學生每星期見面練習英語口語。"},{"en":"A drama needs enough suspense for viewers to come back every week.","zh":"劇集需要有足夠懸念，令觀眾每星期回來收看。"},{"en":"This phrase is often used for regular habits, meetings, or broadcast schedules.","zh":"這個短語常用於規律習慣、會議或播放時間表。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"the more…the more…","meaning":"越……越……","examples":[{"en":"The more the audience discovers, the more they want to know.","zh":"觀眾發現得越多，就越想知道更多。"},{"en":"The more…the more… shows that one thing increases as another thing increases.","zh":"the more…the more… 表示一件事增加時，另一件事也增加。"},{"en":"The more students practise, the more confident they become.","zh":"學生練習得越多，就越有信心。"},{"en":"The more a family avoids a problem, the more painful it may become.","zh":"一個家庭越迴避問題，問題就可能越痛苦。"},{"en":"This structure is useful for showing a growing connection between two changes.","zh":"這個結構很適合展示兩個變化之間逐漸加強的關係。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"stay together","meaning":"維繫在一起","examples":[{"en":"The audience will want to know whether the family can stay together.","zh":"觀眾會想知道這家人能否維繫在一起。"},{"en":"To stay together means to remain united instead of separating or falling apart.","zh":"stay together 的意思是保持團結，而不是分開或瓦解。"},{"en":"A family may struggle to stay together when money problems create blame.","zh":"當金錢問題造成互相責怪時，家庭可能難以維繫在一起。"},{"en":"Teams stay together better when members talk honestly after mistakes.","zh":"當成員在犯錯後坦誠交談，團隊會更容易維繫在一起。"},{"en":"This phrase often carries emotional weight because it suggests love is being tested.","zh":"這個短語常帶有情感重量，因為它暗示愛正在受考驗。"}],"source":"2021Q9.pdf","sourcePage":12},{"front":"I would be grateful if","meaning":"如蒙……我將十分感激","examples":[{"en":"I would be grateful if you would consider this proposal for development.","zh":"如蒙閣下考慮這份建議書作進一步開發，我將十分感激。"},{"en":"I would be grateful if is a polite formal phrase used to make a request.","zh":"I would be grateful if 是一個禮貌正式的短語，用來提出請求。"},{"en":"I would be grateful if you could reply before Friday.","zh":"如蒙閣下能在星期五前回覆，我將十分感激。"},{"en":"In letters, this phrase sounds respectful because it does not sound like a command.","zh":"在書信中，這個短語顯得尊重，因為它不像命令。"},{"en":"Use it when asking someone to read, approve, consider, or help with something.","zh":"當你請別人閱讀、批准、考慮或協助某事時，可以使用它。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"consider this proposal","meaning":"考慮這份建議書","examples":[{"en":"The writer asks the Production Manager to consider this proposal.","zh":"作者請製作經理考慮這份建議書。"},{"en":"To consider this proposal means to read the plan carefully and think about whether to accept it.","zh":"consider this proposal 的意思是仔細閱讀這份計劃，並思考是否接受。"},{"en":"A teacher may ask the principal to consider this proposal for a new reading club.","zh":"老師可能請校長考慮這份關於新閱讀會的建議書。"},{"en":"If decision-makers consider this proposal seriously, they will examine its aims, costs, and benefits.","zh":"如果決策者認真考慮這份建議書，他們會檢視其目的、成本和好處。"},{"en":"This phrase is polite because it asks for careful thought rather than immediate agreement.","zh":"這個短語很有禮貌，因為它要求仔細思考，而不是立即同意。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"for development","meaning":"作進一步開發","examples":[{"en":"The proposal is submitted for development.","zh":"這份建議書被提交作進一步開發。"},{"en":"For development means for further planning, improvement, or production work.","zh":"for development 的意思是作進一步計劃、改良或製作工作。"},{"en":"A promising story idea may be chosen for development before filming begins.","zh":"一個有潛力的故事構思，可能在拍攝前被選中作進一步開發。"},{"en":"When a project is accepted for development, the team may write scripts, plan budgets, and test ideas.","zh":"當項目被接受作進一步開發，團隊可能會寫劇本、計劃預算和測試想法。"},{"en":"This phrase shows that the idea is not finished yet but has potential to grow.","zh":"這個短語顯示構思尚未完成，但有成長潛力。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"have the potential to","meaning":"有潛力……","examples":[{"en":"The series has the potential to become a memorable prime-time drama.","zh":"這部劇集有潛力成為一部令人難忘的黃金時段劇集。"},{"en":"To have the potential to do something means to have the ability or possibility to succeed in that way.","zh":"have the potential to do something 的意思是有能力或可能以某方式成功。"},{"en":"A quiet student may have the potential to become a strong speaker with practice.","zh":"一名安靜的學生如果加以練習，可能有潛力成為出色演講者。"},{"en":"A small community project can have the potential to improve many lives if supported well.","zh":"一個小型社區項目如果得到良好支援，可以有潛力改善許多人的生活。"},{"en":"This phrase is useful when an idea is not yet successful but could become successful.","zh":"當一個想法尚未成功但可能成功時，這個短語很有用。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"a memorable prime-time drama","meaning":"令人難忘的黃金時段劇集","examples":[{"en":"The series could become a memorable prime-time drama.","zh":"這部劇集可以成為一部令人難忘的黃金時段劇集。"},{"en":"A memorable prime-time drama is a television drama shown during a popular evening time and remembered by viewers.","zh":"令人難忘的黃金時段劇集，是在受歡迎的晚間時段播放，並被觀眾記住的電視劇。"},{"en":"A memorable prime-time drama needs strong characters and scenes people discuss the next day.","zh":"令人難忘的黃金時段劇集需要有力角色，以及令人第二天仍會討論的場面。"},{"en":"If a drama speaks to family life, it may succeed as a memorable prime-time drama.","zh":"如果一部劇集打動家庭生活，它可能成為令人難忘的黃金時段劇集。"},{"en":"This phrase suggests both commercial success and emotional impact.","zh":"這個短語暗示商業成功和情感影響。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"combine…with…","meaning":"把……與……結合","examples":[{"en":"The drama combines a recognisable Hong Kong setting with universal emotions.","zh":"這部劇集把令人熟悉的香港背景與普世情感結合起來。"},{"en":"To combine one thing with another means to bring two elements together.","zh":"combine one thing with another 的意思是把兩種元素放在一起。"},{"en":"A good lesson can combine clear explanation with practical exercises.","zh":"好課堂可以把清晰解釋與實際練習結合起來。"},{"en":"A restaurant may combine traditional recipes with modern presentation.","zh":"餐廳可以把傳統食譜與現代擺盤結合起來。"},{"en":"This structure helps show how two different strengths work together.","zh":"這個結構幫助展示兩種不同優點如何一起發揮作用。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"a recognisable Hong Kong setting","meaning":"令人熟悉的香港背景","examples":[{"en":"The series has a recognisable Hong Kong setting.","zh":"這部劇集有令人熟悉的香港背景。"},{"en":"A recognisable Hong Kong setting is a background that viewers can easily identify as Hong Kong.","zh":"令人熟悉的香港背景，是觀眾能容易辨認為香港的背景。"},{"en":"Cha chaan tengs, rooftops, narrow flats, and busy streets can create a recognisable Hong Kong setting.","zh":"茶餐廳、天台、狹小單位和繁忙街道，可以創造令人熟悉的香港背景。"},{"en":"A recognisable Hong Kong setting helps local viewers feel that the story belongs to them.","zh":"令人熟悉的香港背景幫助本地觀眾覺得故事屬於他們。"},{"en":"This setting works best when it uses real daily details, not only postcard views.","zh":"這個背景最好使用真實日常細節，而不只是明信片式景色。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"universal emotions","meaning":"普世情感","examples":[{"en":"The drama combines a local setting with universal emotions.","zh":"這部劇集把本地背景與普世情感結合起來。"},{"en":"Universal emotions are feelings that many people can understand, no matter where they live.","zh":"普世情感是許多人無論住在哪裏都能理解的感受。"},{"en":"Love, regret, fear, hope, and loneliness are universal emotions.","zh":"愛、遺憾、恐懼、希望和孤獨都是普世情感。"},{"en":"A story with universal emotions can reach viewers outside its local setting.","zh":"帶有普世情感的故事，可以打動本地背景以外的觀眾。"},{"en":"Universal emotions make a drama feel human even when the culture is very specific.","zh":"即使文化十分具體，普世情感也令劇集感覺有人性。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"home, after all","meaning":"畢竟，家是……","examples":[{"en":"Home, after all, is where people hurt and forgive one another.","zh":"畢竟，家是人們互相傷害又互相原諒的地方。"},{"en":"Home, after all is used to remind readers of an important truth about home.","zh":"home, after all 用來提醒讀者一個關於家的重要真相。"},{"en":"Home, after all, is not only a place to sleep but also a place to belong.","zh":"畢竟，家不只是睡覺的地方，也是歸屬之地。"},{"en":"A family may argue often, but home, after all, is where they learn to return.","zh":"一家人可能常常爭吵，但畢竟，家是他們學會回來的地方。"},{"en":"This phrase sounds reflective because it sums up a deeper meaning.","zh":"這個短語帶有反思意味，因為它總結更深意義。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"hurt one another","meaning":"互相傷害","examples":[{"en":"Home is where people sometimes hurt one another.","zh":"家是人們有時互相傷害的地方。"},{"en":"To hurt one another means to cause each other emotional or physical pain.","zh":"hurt one another 的意思是令彼此在情感或身體上受傷。"},{"en":"Family members may hurt one another with careless words during an argument.","zh":"家人在爭吵中可能用粗心的說話互相傷害。"},{"en":"People who love each other can still hurt one another when they feel afraid or ignored.","zh":"相愛的人在感到害怕或被忽視時，仍可能互相傷害。"},{"en":"This phrase is honest because close relationships can bring both comfort and pain.","zh":"這個短語很真實，因為親密關係可以同時帶來安慰和痛苦。"}],"source":"2021Q9.pdf","sourcePage":13},{"front":"forgive one another","meaning":"互相原諒","examples":[{"en":"Home is also where people forgive one another.","zh":"家也是人們互相原諒的地方。"},{"en":"To forgive one another means to stop holding anger against each other after hurt has happened.","zh":"forgive one another 的意思是在傷害發生後，不再一直怨恨彼此。"},{"en":"Siblings may forgive one another after finally understanding the reason behind an old argument.","zh":"兄弟姊妹終於明白舊爭吵背後的原因後，可能會互相原諒。"},{"en":"People forgive one another more easily when apologies are honest and actions change.","zh":"當道歉真誠且行動有所改變，人們會更容易互相原諒。"},{"en":"This phrase shows that family repair must come from both sides.","zh":"這個短語顯示家庭修復必須來自雙方。"}],"source":"2021Q9.pdf","sourcePage":14},{"front":"one way or another","meaning":"無論如何；總會有辦法","examples":[{"en":"People find their way back one way or another.","zh":"人們總會有辦法找到回去的路。"},{"en":"One way or another means somehow, even if the exact method is not clear.","zh":"one way or another 的意思是以某種方式，即使具體方法還不清楚。"},{"en":"We will solve the transport problem one way or another before the trip.","zh":"我們無論如何都會在旅行前解決交通問題。"},{"en":"Families may stay connected one way or another, even after years of silence.","zh":"即使沉默多年，家人仍可能總會有辦法保持連繫。"},{"en":"This phrase suggests determination or inevitability despite uncertainty.","zh":"這個短語暗示在不確定中仍有決心或必然性。"}],"source":"2021Q9.pdf","sourcePage":14},{"front":"find their way back","meaning":"找到回去的路；重修舊好","examples":[{"en":"Family members find their way back to one another.","zh":"家庭成員找到回到彼此身邊的路。"},{"en":"To find their way back means to return emotionally or physically after being separated or distant.","zh":"find their way back 的意思是在分離或疏遠後，在情感上或身體上回來。"},{"en":"Old friends may find their way back after a small apology opens the door.","zh":"舊朋友可能在一次小小道歉打開大門後重修舊好。"},{"en":"A son who left home in anger may slowly find his way back through honest conversations.","zh":"憤怒離家的兒子，可能透過真誠對話慢慢找到回去的路。"},{"en":"This phrase is hopeful because it suggests broken relationships can still move toward repair.","zh":"這個短語充滿希望，因為它暗示破裂關係仍可以走向修復。"}],"source":"2021Q9.pdf","sourcePage":14},{"front":"Yours faithfully","meaning":"謹啟","examples":[{"en":"The proposal ends with Yours faithfully.","zh":"這份建議書以「謹啟」結尾。"},{"en":"Yours faithfully is a formal closing used at the end of a letter when the writer does not know the recipient personally.","zh":"Yours faithfully 是正式書信結尾用語，常用於作者不熟悉收信人的情況。"},{"en":"A student may write Yours faithfully at the end of a formal letter to a company manager.","zh":"學生給公司經理寫正式信件時，可以在結尾寫 Yours faithfully。"},{"en":"Using Yours faithfully makes the ending polite and professional.","zh":"使用 Yours faithfully 令結尾顯得禮貌和專業。"},{"en":"This phrase belongs in formal letters, not casual messages to friends.","zh":"這個短語屬於正式書信，不適合給朋友的隨意訊息。"}],"source":"2021Q9.pdf","sourcePage":14}]};
window.EDMUND_FLASHCARD_SEED = window.EDMUND_FLASHCARD_SEED || {};
Object.assign(window.EDMUND_FLASHCARD_SEED,window.EDMUND_DSE_WRITING_PART_B_2021_SEED);
